"""Knowledge Graph REST API Router.







Provides CRUD endpoints for entities, relations, stats, and visualization



export. Uses JSON-file persistence for browser-mode support (outside Electron).







Endpoints



---------



GET    /api/electron/kg/entities/search  – search entities



POST   /api/electron/kg/entities         – create entity



GET    /api/electron/kg/entities/{id}    – get entity



PATCH  /api/electron/kg/entities/{id}    – update entity



DELETE /api/electron/kg/entities/{id}    – delete entity



GET    /api/electron/kg/entities/{id}/neighbors – get neighbors



POST   /api/electron/kg/relations        – create relation



GET    /api/electron/kg/relations        – query relations



GET    /api/electron/kg/stats            – graph statistics



GET    /api/electron/kg/export/viz       – visualization export



GET    /api/electron/kg/export           – full graph export



"""







from __future__ import annotations







import asyncio



import json



import logging



import time



import uuid



from pathlib import Path



import re



from datetime import datetime, timezone



from typing import Any, Dict, List, Optional







from fastapi import APIRouter, Header, HTTPException, Query, Request, StreamingResponse, WebSocket, WebSocketDisconnect



from fastapi.responses import JSONResponse



from pydantic import BaseModel, Field







from deerflow.config.paths import get_paths



from deerflow.models.factory import create_chat_model







logger = logging.getLogger(__name__)







router = APIRouter(prefix="/api/electron/kg", tags=["knowledge-graph"])







_lock = asyncio.Lock()







# In-memory storage



_entities: dict[str, dict] = {}



_relations: dict[str, dict] = {}



_persistence_path: Optional[Path] = None



_creation_timestamps: dict[str, float] = {}  # entity_id -> timestamp



_entity_tags: dict[str, set[str]] = {}  # entity_id -> set of tags







# ── WebSocket Subscription System ───────────────────────────────







class ConnectionManager:



    """Manages WebSocket connections for real-time updates."""







    def __init__(self):



        self.active_connections: dict[str, list[WebSocket]] = {



            "entities": [],



            "relations": [],



            "all": [],



        }







    async def connect(self, websocket: WebSocket, channel: str = "all"):



        await websocket.accept()



        if channel not in self.active_connections:



            self.active_connections[channel] = []



        self.active_connections[channel].append(websocket)



        logger.info(f"WebSocket connected to {channel}. Total: {len(self.active_connections[channel])}")







    def disconnect(self, websocket: WebSocket, channel: str = "all"):



        if websocket in self.active_connections.get(channel, []):



            self.active_connections[channel].remove(websocket)



            logger.info(f"WebSocket disconnected from {channel}. Total: {len(self.active_connections.get(channel, []))}")







    async def broadcast(self, channel: str, message: dict):



        """Broadcast message to all connections in a channel."""



        disconnected = []



        for connection in self.active_connections.get(channel, []):



            try:



                await connection.send_json(message)



            except Exception as e:



                logger.warning(f"Failed to send to WebSocket: {e}")



                disconnected.append(connection)







        # Clean up disconnected



        for conn in disconnected:



            self.disconnect(conn, channel)







        # Also broadcast to "all" channel



        if channel != "all":



            await self.broadcast("all", message)











_manager = ConnectionManager()











class GraphEvent(BaseModel):



    """Event payload for graph updates."""



    eventType: str  # entity_created, entity_updated, entity_deleted, relation_created, relation_deleted



    entityId: str | None = None



    relationId: str | None = None



    data: dict | None = None



    timestamp: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())











# ── Pydantic models ───────────────────────────────────────────────────











class CreateEntityRequest(BaseModel):



    name: str = Field(..., min_length=1, description="Entity name")



    type: str = Field(..., description="Entity type (e.g. person, organization)")



    aliases: list[str] = Field(default_factory=list)



    description: str | None = None



    properties: dict = Field(default_factory=dict)



    source: str | None = None



    confidence: float = Field(default=0.5, ge=0.0, le=1.0)











class UpdateEntityRequest(BaseModel):



    name: str | None = None



    type: str | None = None



    aliases: list[str] | None = None



    description: str | None = None



    properties: dict | None = None



    confidence: float | None = Field(default=None, ge=0.0, le=1.0)











class CreateRelationRequest(BaseModel):



    sourceId: str = Field(..., alias="sourceId")



    targetId: str = Field(..., alias="targetId")



    type: str = Field(..., description="Relation type")



    properties: dict = Field(default_factory=dict)



    confidence: float = Field(default=0.5, ge=0.0, le=1.0)



    source: str | None = None







    model_config = {"populate_by_name": True}











class GraphStatsResponse(BaseModel):



    totalEntities: int = 0



    totalRelations: int = 0



    entityTypes: dict = Field(default_factory=dict)



    relationTypes: dict = Field(default_factory=dict)



    averageConfidence: float = 0.0



    orphanedEntities: int = 0



    mostConnected: list[dict] = Field(default_factory=list)











# ── persistence helpers ───────────────────────────────────────────────











def _get_persistence_path() -> Path:



    global _persistence_path



    if _persistence_path is None:



        try:



            base = get_paths().base_dir



        except Exception:



            base = Path(".")



        _persistence_path = base / "knowledge_graph.json"



    return _persistence_path











async def _load_state() -> None:



    path = _get_persistence_path()



    if not path.exists():



        return



    try:



        data = json.loads(path.read_text(encoding="utf-8"))



    except Exception:



        logger.exception("Failed to read knowledge_graph.json")



        return



    entities_raw = data.get("entities", [])



    for e in entities_raw:



        if isinstance(e, dict) and e.get("id"):



            _entities[e["id"]] = e



    relations_raw = data.get("relations", [])



    for r in relations_raw:



        if isinstance(r, dict) and r.get("id"):



            _relations[r["id"]] = r



    logger.info("Loaded %d entities and %d relations from knowledge_graph.json",



                len(_entities), len(_relations))











async def _save_state() -> None:



    path = _get_persistence_path()



    try:



        path.parent.mkdir(parents=True, exist_ok=True)



        data = {



            "entities": list(_entities.values()),



            "relations": list(_relations.values()),



            "updatedAt": time.time(),



        }



        path.write_text(json.dumps(data, indent=2), encoding="utf-8")



    except Exception:



        logger.exception("Failed to persist knowledge graph state")











def _now_iso() -> str:



    from datetime import datetime, timezone



    return datetime.now(timezone.utc).isoformat()











# ── Entity endpoints ──────────────────────────────────────────────────











@router.post("/entities")



async def create_entity(req: CreateEntityRequest):



    async with _lock:



        eid = str(uuid.uuid4())



        now = _now_iso()



        timestamp = time.time()



        entity = {



            "id": eid,



            "name": req.name,



            "type": req.type,



            "aliases": req.aliases,



            "description": req.description,



            "properties": req.properties,



            "source": req.source,



            "confidence": req.confidence,



            "createdAt": now,



            "updatedAt": now,



            "accessCount": 0,



            "lastAccessed": now,



        }



        _entities[eid] = entity



        _creation_timestamps[eid] = timestamp



        await _save_state()



        # Trigger webhooks



        _trigger_webhooks("entity.created", {"entityId": eid, "name": req.name, "type": req.type})



        # WebSocket notification



        await _notify_entity_change("entity_created", eid, entity)



        return entity











@router.get("/entities/{entity_id}")



async def get_entity(entity_id: str):



    entity = _entities.get(entity_id)



    if entity is None:



        raise HTTPException(status_code=404, detail="Entity not found")



    entity["accessCount"] = entity.get("accessCount", 0) + 1



    return entity











@router.get("/entities/search")



async def search_entities(



    name: str | None = Query(default=None),



    type: str | None = Query(default=None),



    search: str | None = Query(default=None),



    limit: int = Query(default=100, ge=1),



    minConfidence: float = Query(default=0.0, ge=0.0, le=1.0, alias="minConfidence"),



):



    results: list[dict] = []



    for e in _entities.values():



        conf = e.get("confidence", 0)



        if conf < minConfidence:



            continue



        if type and e.get("type") != type:



            continue



        if name and name.lower() not in e.get("name", "").lower():



            continue



        if search:



            hay = json.dumps(e).lower()



            if search.lower() not in hay:



                continue



        results.append(dict(e))



    return results[:limit]











@router.patch("/entities/{entity_id}")



async def update_entity(entity_id: str, req: UpdateEntityRequest):



    async with _lock:



        if entity_id not in _entities:



            raise HTTPException(status_code=404, detail="Entity not found")



        e = _entities[entity_id]



        for field in ("name", "type", "aliases", "description", "properties", "confidence"):



            val = getattr(req, field, None)



            if val is not None:



                e[field] = val



        e["updatedAt"] = _now_iso()



        await _save_state()



        # WebSocket notification



        await _notify_entity_change("entity_updated", entity_id, e)



        return e











@router.delete("/entities/{entity_id}")



async def delete_entity(entity_id: str):



    async with _lock:



        if entity_id not in _entities:



            raise HTTPException(status_code=404, detail="Entity not found")



        del _entities[entity_id]



        # Remove related relations



        to_del = [rid for rid, r in _relations.items()



                  if r.get("sourceId") == entity_id or r.get("targetId") == entity_id]



        for rid in to_del:



            del _relations[rid]



        await _save_state()



        # WebSocket notification



        await _notify_entity_change("entity_deleted", entity_id)



        return {"success": True}











@router.get("/entities/{entity_id}/neighbors")



async def get_neighbors(entity_id: str):



    if entity_id not in _entities:



        return []



    neighbors: list[dict] = []



    for r in _relations.values():



        if r.get("sourceId") == entity_id:



            tid = r.get("targetId")



            if tid and tid in _entities:



                neighbors.append({



                    "entity": dict(_entities[tid]),



                    "relation": dict(r),



                    "direction": "out",



                })



        elif r.get("targetId") == entity_id:



            sid = r.get("sourceId")



            if sid and sid in _entities:



                neighbors.append({



                    "entity": dict(_entities[sid]),



                    "relation": dict(r),



                    "direction": "in",



                })



    return neighbors











# ── Entity Tags Endpoints ───────────────────────────────────────────────











class AddTagsRequest(BaseModel):



    tags: list[str] = Field(..., description="Tags to add")











class EntityTagsResponse(BaseModel):



    entityId: str



    tags: list[str]



    count: int











class TagStatsResponse(BaseModel):



    tags: list[dict]  # [{tag, count, entityIds}]



    totalTags: int











@router.post("/entities/{entity_id}/tags")



async def add_tags(entity_id: str, req: AddTagsRequest) -> EntityTagsResponse:



    """Add tags to an entity."""



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    if entity_id not in _entity_tags:



        _entity_tags[entity_id] = set()







    for tag in req.tags:



        if tag.strip():



            _entity_tags[entity_id].add(tag.strip().lower())







    return EntityTagsResponse(



        entityId=entity_id,



        tags=sorted(_entity_tags[entity_id]),



        count=len(_entity_tags[entity_id]),



    )











@router.get("/entities/{entity_id}/tags")



async def get_tags(entity_id: str) -> EntityTagsResponse:



    """Get all tags for an entity."""



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    tags = sorted(_entity_tags.get(entity_id, set()))







    return EntityTagsResponse(



        entityId=entity_id,



        tags=tags,



        count=len(tags),



    )











@router.delete("/entities/{entity_id}/tags/{tag}")



async def delete_tag(entity_id: str, tag: str) -> EntityTagsResponse:



    """Delete a tag from an entity."""



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    tag_lower = tag.strip().lower()



    if entity_id in _entity_tags and tag_lower in _entity_tags[entity_id]:



        _entity_tags[entity_id].remove(tag_lower)







    tags = sorted(_entity_tags.get(entity_id, set()))







    return EntityTagsResponse(



        entityId=entity_id,



        tags=tags,



        count=len(tags),



    )











@router.get("/tags/all")



async def get_all_tags() -> TagStatsResponse:



    """Get all tags with usage statistics."""



    tag_stats: dict[str, dict] = {}







    for entity_id, tags in _entity_tags.items():



        for tag in tags:



            if tag not in tag_stats:



                tag_stats[tag] = {"count": 0, "entityIds": []}



            tag_stats[tag]["count"] += 1



            tag_stats[tag]["entityIds"].append(entity_id)







    sorted_tags = sorted(



        [{"tag": t, "count": s["count"], "entityIds": s["entityIds"]}



         for t, s in tag_stats.items()],



        key=lambda x: -x["count"]



    )







    return TagStatsResponse(



        tags=sorted_tags[:100],



        totalTags=len(tag_stats),



    )











# ── Entity enrichment endpoints ───────────────────────────────────────











class EnrichRequest(BaseModel):



    """Request for entity enrichment."""



    model_name: str | None = Field(default=None, description="LLM model to use")



    fields: list[str] = Field(



        default_factory=lambda: ["description", "aliases", "type", "properties"],



        description="Fields to enrich",



    )



    overwrite: bool = Field(



        default=False,



        description="Overwrite existing values",



    )











class EnrichResponse(BaseModel):



    """Response for entity enrichment."""



    entity_id: str = Field(alias="entityId")



    enriched: dict = Field(default_factory=dict)



    suggestions: dict = Field(default_factory=dict)



    model_used: str | None = Field(default=None, alias="modelUsed")



    success: bool = True



    error: str | None = None







    model_config = {"populate_by_name": True}











class RelationSuggestion(BaseModel):



    """Suggested relation for an entity."""



    target_id: str = Field(alias="targetId")



    target_name: str = Field(alias="targetName")



    relation_type: str = Field(alias="relationType", description="Relation type")



    confidence: float = Field(ge=0.0, le=1.0)



    reasoning: str | None = None











class EnrichRelationsResponse(BaseModel):



    """Response for relation suggestion."""



    entity_id: str = Field(alias="entityId")



    suggestions: list[RelationSuggestion] = Field(default_factory=list)



    model_used: str | None = Field(default=None, alias="modelUsed")



    success: bool = True



    error: str | None = None







    model_config = {"populate_by_name": True}











async def _enrich_entity_with_llm(



    entity: dict,



    fields: list[str],



    model_name: str | None,



    overwrite: bool,



) -> tuple[dict, dict, str | None]:



    """Enrich an entity using LLM.







    Returns (enriched, suggestions, model_used).



    """



    enriched = {}



    suggestions = {}



    model_used = None







    llm = None



    if model_name:



        try:



            llm = create_chat_model(model_name)



        except Exception:



            logger.debug(f"Model {model_name} not available")







    if llm is None:



        from deerflow.config import get_app_config







        config = get_app_config()



        if config.models:



            try:



                llm = create_chat_model(config.models[0].name)



                model_used = config.models[0].name



            except Exception as e:



                logger.debug(f"No LLM available: {e}")



                return enriched, suggestions, None



        else:



            return enriched, suggestions, None







    if llm is None:



        return enriched, suggestions, None







    name = entity.get("name", "")



    entity_type = entity.get("type", "")



    existing_desc = entity.get("description")



    existing_aliases = entity.get("aliases", [])



    existing_props = entity.get("properties", {})







    # Build prompt for enrichment



    fields_to_enrich = []



    if "description" in fields and not existing_desc:



        fields_to_enrich.append("description")



    if "aliases" in fields and not existing_aliases:



        fields_to_enrich.append("aliases")



    if "type" in fields and not entity_type:



        fields_to_enrich.append("type")



    if "properties" in fields:



        fields_to_enrich.append("properties")







    if not fields_to_enrich:



        return enriched, suggestions, model_used







    prompt = f"""Analyze the following entity and provide enrichment suggestions.







Entity name: {name}



Entity type: {entity_type}



Existing aliases: {existing_aliases}



Existing description: {existing_desc or 'None'}



Existing properties: {existing_props}







Respond with a JSON object containing the fields you can enrich.



Include only these fields: {', '.join(fields_to_enrich)}







For each field provide:



- description: A 1-2 sentence description of what this entity is



- aliases: Alternative names or variations of the entity name



- type: The most appropriate entity type (e.g., person, organization, concept, document, process, tool, location)



- properties: Any additional properties that characterize this entity







Respond with only the JSON object."""







    try:



        response = llm.invoke(prompt)



        result = response.content if hasattr(response, "content") else str(response)







        # Try to parse JSON from response



        json_match = re.search(r"\{[\s\S]*\}", result)



        if json_match:



            parsed = json.loads(json_match.group())



            for key in fields_to_enrich:



                if key in parsed and parsed[key]:



                    suggestions[key] = parsed[key]



                    if overwrite or not entity.get(key):



                        enriched[key] = parsed[key]



    except Exception as e:



        logger.debug(f"Enrichment failed: {e}")







    return enriched, suggestions, model_used











@router.post("/entities/{entity_id}/enrich")



async def enrich_entity(



    entity_id: str,



    request: EnrichRequest = EnrichRequest(),



) -> EnrichResponse:



    """Enrich an entity using AI.







    Uses LLM to generate missing descriptions, suggest aliases,



    infer types, and add properties.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    entity = _entities[entity_id]







    enriched, suggestions, model_used = await _enrich_entity_with_llm(



        entity,



        request.fields,



        request.model_name,



        request.overwrite,



    )







    # Apply enriched fields if overwrite is enabled



    if request.overwrite and enriched:



        entity.update(enriched)



        _entities[entity_id] = entity







    return EnrichResponse(



        entityId=entity_id,



        enriched=enriched,



        suggestions=suggestions,



        modelUsed=model_used,



    )











@router.post("/entities/{entity_id}/enrich/relations")



async def enrich_entity_relations(



    entity_id: str,



    max_suggestions: int = Query(default=5, ge=1, le=20),



    model_name: str | None = Query(default=None),



) -> EnrichRelationsResponse:



    """Suggest potential relations for an entity using AI.







    Analyzes the entity and existing graph to suggest meaningful



    connections to other entities.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    entity = _entities[entity_id]



    suggestions = []







    # Get existing relations



    existing_targets = set()



    for rel in _relations.values():



        if rel.get("sourceId") == entity_id:



            existing_targets.add(rel.get("targetId"))



        if rel.get("targetId") == entity_id:



            existing_targets.add(rel.get("sourceId"))







    # Get all other entities for context



    other_entities = [



        {"id": eid, "name": e.get("name"), "type": e.get("type")}



        for eid, e in _entities.items()



        if eid != entity_id



    ]







    llm = None



    model_used = None



    if model_name:



        try:



            llm = create_chat_model(model_name)



        except Exception:



            logger.debug(f"Model {model_name} not available")







    if llm is None:



        from deerflow.config import get_app_config







        config = get_app_config()



        if config.models:



            try:



                llm = create_chat_model(config.models[0].name)



                model_used = config.models[0].name



            except Exception:



                pass







    if llm is None:



        return EnrichRelationsResponse(



            entityId=entity_id,



            suggestions=[],



            modelUsed=None,



            error="No LLM available",



        )







    name = entity.get("name", "")



    entity_type = entity.get("type", "")







    prompt = f"""Given the entity "{name}" (type: {entity_type}), suggest up to {max_suggestions} meaningful connections to other entities in the knowledge graph.







Existing connected entities: {list(existing_targets) if existing_targets else 'None'}







Other entities in the graph:



{json.dumps(other_entities[:50], indent=2)}







Respond with a JSON array of suggested relations, each with:



- targetId: The ID of the target entity



- targetName: The name of the target entity



- relationType: The type of relationship (e.g., related_to, part_of, uses, created_by, operates_in)



- confidence: Confidence score 0.0-1.0



- reasoning: Brief explanation of why this connection makes sense







Respond with only the JSON array."""







    try:



        response = llm.invoke(prompt)



        result = response.content if hasattr(response, "content") else str(response)







        json_match = re.search(r"\[[\s\S]*\]", result)



        if json_match:



            parsed = json.loads(json_match.group())



            for item in parsed[:max_suggestions]:



                if isinstance(item, dict):



                    suggestions.append(RelationSuggestion(



                        targetId=item.get("targetId", ""),



                        targetName=item.get("targetName", ""),



                        relationType=item.get("relationType", "related_to"),



                        confidence=item.get("confidence", 0.5),



                        reasoning=item.get("reasoning"),



                    ))



    except Exception as e:



        logger.debug(f"Relation enrichment failed: {e}")



        return EnrichRelationsResponse(



            entityId=entity_id,



            suggestions=[],



            modelUsed=model_used,



            error=str(e),



        )







    return EnrichRelationsResponse(



        entityId=entity_id,



        suggestions=suggestions,



        modelUsed=model_used,



    )











# ── Path finding & subgraph endpoints ──────────────────────────────











def _find_all_paths_bfs(



    source_id: str,



    target_id: str,



    max_hops: int,



) -> list[list[tuple[str, dict]]]:



    """Find all paths between source and target using BFS."""



    if source_id == target_id:



        return [[(source_id, {})]]







    paths: list[list[tuple[str, dict]]] = []



    queue: list[tuple[str, list[tuple[str, dict]], set[str]]] = [



        (source_id, [(source_id, {})], {source_id})



    ]







    while queue:



        current, path, visited = queue.pop(0)







        if len(path) > max_hops + 1:



            continue







        # Find all edges from current



        for r in _relations.values():



            next_entity_id = None



            direction = ""







            if r.get("sourceId") == current and r.get("targetId") not in visited:



                next_entity_id = r.get("targetId")



                direction = "out"



            elif r.get("targetId") == current and r.get("sourceId") not in visited:



                next_entity_id = r.get("sourceId")



                direction = "in"







            if next_entity_id:



                new_visited = visited.copy()



                new_visited.add(next_entity_id)



                new_path = path + [(next_entity_id, dict(r), direction)]







                if next_entity_id == target_id:



                    paths.append(new_path)



                else:



                    queue.append((next_entity_id, new_path, new_visited))







    return paths











def _build_subgraph(center_id: str, max_hops: int) -> tuple[set[str], list[dict]]:



    """Build subgraph within N hops of center entity."""



    visited: set[str] = {center_id}



    queue: list[tuple[str, int]] = [(center_id, 0)]



    edges: list[dict] = []







    while queue:



        current, depth = queue.pop(0)







        if depth >= max_hops:



            continue







        for r in _relations.values():



            next_id = None







            if r.get("sourceId") == current and r.get("targetId") not in visited:



                next_id = r.get("targetId")



            elif r.get("targetId") == current and r.get("sourceId") not in visited:



                next_id = r.get("sourceId")







            if next_id and next_id not in visited:



                visited.add(next_id)



                queue.append((next_id, depth + 1))



                edges.append(dict(r))







    return visited, edges











@router.post("/paths/find")



async def find_paths(req: PathFindRequest) -> PathFindResponse:



    """Find all paths between two entities.







    Uses BFS to find all simple paths up to maxHops.



    """



    if req.sourceId not in _entities or req.targetId not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    raw_paths = _find_all_paths_bfs(req.sourceId, req.targetId, req.maxHops)







    results = []



    for raw_path in raw_paths:



        formatted_path = []



        for entity_id, rel, direction in raw_path:



            if rel:



                formatted_path.append({



                    "entityId": entity_id,



                    "name": _entities.get(entity_id, {}).get("name", entity_id),



                    "relation": rel,



                    "direction": direction,



                })



            else:



                formatted_path.append({



                    "entityId": entity_id,



                    "name": _entities.get(entity_id, {}).get("name", entity_id),



                })







        results.append(PathResult(path=formatted_path, hops=len(formatted_path) - 1))







    return PathFindResponse(



        sourceId=req.sourceId,



        targetId=req.targetId,



        paths=results,



        totalFound=len(results),



    )











@router.post("/subgraph/extract")



async def extract_subgraph(req: SubgraphRequest) -> SubgraphResponse:



    """Extract subgraph around a center entity.







    Returns all entities within maxHops and their relations.



    """



    if req.centerEntityId not in _entities:



        raise HTTPException(status_code=404, detail="Center entity not found")







    visited, edges = _build_subgraph(req.centerEntityId, req.maxHops)







    nodes = []



    for eid in visited:



        if eid in _entities:



            nodes.append(dict(_entities[eid]))







    return SubgraphResponse(



        centerEntityId=req.centerEntityId,



        nodes=nodes,



        edges=edges,



        totalNodes=len(nodes),



        totalEdges=len(edges),



    )











# ── Centrality metrics & community detection ───────────────────────











def _compute_pagerank(



    damping: float = 0.85,



    iterations: int = 20,



) -> dict[str, float]:



    """Compute PageRank scores for all entities."""



    if not _entities:



        return {}







    # Initialize scores uniformly



    scores: dict[str, float] = {eid: 1.0 / len(_entities) for eid in _entities}







    # Build adjacency (outgoing edges per entity)



    outgoing: dict[str, set[str]] = {eid: set() for eid in _entities}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        if sid in _entities and tid in _entities:



            outgoing[sid].add(tid)







    # Iterative computation



    for _ in range(iterations):



        new_scores: dict[str, float] = {}



        for eid in _entities:



            # Sum contributions from linking entities



            contrib = 0.0



            for src, targets in outgoing.items():



                if eid in targets and targets:



                    contrib += scores[src] / len(targets)



            new_scores[eid] = (1 - damping) / len(_entities) + damping * contrib



        scores = new_scores







    return scores











def _detect_communities_label_propagation() -> tuple[list[list[str]], float]:



    """Detect communities using label propagation."""



    if not _entities:



        return [], 0.0







    # Initialize labels with entity IDs



    labels: dict[str, str] = {eid: eid for eid in _entities}







    # Build adjacency



    adj: dict[str, set[str]] = {eid: set() for eid in _entities}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        if sid in _entities and tid in _entities:



            adj[sid].add(tid)



            adj[tid].add(sid)







    # Label propagation (5 iterations)



    for _ in range(5):



        for eid in list(_entities.keys()):



            neighbors = adj.get(eid, set())



            if not neighbors:



                continue







            # Get neighbor label frequencies



            freq: dict[str, int] = {}



            for n in neighbors:



                lab = labels.get(n, eid)



                freq[lab] = freq.get(lab, 0) + 1







            # Find most frequent



            if freq:



                max_count = max(freq.values())



                candidates = [l for l, c in freq.items() if c == max_count]



                labels[eid] = sorted(candidates)[0]







    # Group by community



    communities_dict: dict[str, list[str]] = {}



    for eid, lab in labels.items():



        if lab not in communities_dict:



            communities_dict[lab] = []



        communities_dict[lab].append(eid)







    communities = list(communities_dict.values())







    # Simple modularity approximation



    modularity = 0.0



    if communities:



        inside_edges = 0



        total_edges = len(_relations)



        if total_edges > 0:



            for comm in communities:



                for e1 in comm:



                    for e2 in comm:



                        if e1 != e2 and e2 in adj.get(e1, set()):



                            inside_edges += 1



            inside_edges //= 2



            modularity = inside_edges / total_edges if total_edges > 0 else 0.0







    return communities, round(modularity, 3)











@router.get("/centrality")



async def get_centrality() -> CentralityResponse:



    """Get centrality metrics for all entities.







    Computes degree centrality and PageRank for the entire graph.



    """



    if not _entities:



        return CentralityResponse()







    # Degree centrality



    degree_scores: dict[str, int] = {}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        degree_scores[sid] = degree_scores.get(sid, 0) + 1



        degree_scores[tid] = degree_scores.get(tid, 0) + 1







    # Normalize degree centrality



    max_degree = max(degree_scores.values()) if degree_scores else 1



    degree_centrality = {



        eid: round(count / max_degree, 3)



        for eid, count in degree_scores.items()



    }







    # PageRank



    pagerank = _compute_pagerank()







    # Top by degree



    top_degree = sorted(



        [{"entityId": eid, "name": _entities[eid].get("name", eid), "score": degree_centrality.get(eid, 0)}



         for eid in degree_scores],



        key=lambda x: -x["score"]



    )[:10]







    # Top by pagerank



    top_pr = sorted(



        [{"entityId": eid, "name": _entities[eid].get("name", eid), "score": pagerank.get(eid, 0)}



         for eid in pagerank],



        key=lambda x: -x["score"]



    )[:10]







    return CentralityResponse(



        degreeCentrality=degree_centrality,



        pagerank=pagerank,



        topByDegree=top_degree,



        topByPagerank=top_pr,



    )











@router.get("/communities")



async def get_communities() -> CommunityResponse:



    """Detect communities in the graph.







    Uses label propagation algorithm to find densely connected groups.



    """



    communities, modularity = _detect_communities_label_propagation()







    return CommunityResponse(



        communities=communities,



        totalCommunities=len(communities),



        modularity=modularity,



    )











