class TemporalStatsResponse(BaseModel):



    """Response for temporal statistics."""



    totalEntities: int



    oldestEntity: dict | None = None



    newestEntity: dict | None = None



    averageAgeDays: float



    entitiesByType: dict[str, int]



    totalRelations: int











class ActivityStatsResponse(BaseModel):



    """Response for activity statistics."""



    mostAccessed: list[dict] = Field(default_factory=list)



    leastAccessed: list[dict] = Field(default_factory=list)



    accessStats: dict











class RecentActivityResponse(BaseModel):



    """Response for recent activity."""



    recentlyCreated: list[dict] = Field(default_factory=list)



    recentlyUpdated: list[dict] = Field(default_factory=list)



    totalRecentCreates: int



    totalRecentUpdates: int











def _compute_similarity(e1: dict, e2: dict, match_types: bool) -> float:



    """Compute similarity score between two entities."""



    score = 0.0







    if match_types and e1.get("type") == e2.get("type"):



        score += 0.4







    d1 = set(e1.get("description", "").lower().split())



    d2 = set(e2.get("description", "").lower().split())



    if d1 and d2:



        overlap = len(d1 & d2)



        total = len(d1 | d2)



        score += 0.3 * (overlap / total if total > 0 else 0)







    a1 = set(e1.get("aliases", []))



    a2 = set(e2.get("aliases", []))



    if a1 and a2:



        score += 0.3 * len(a1 & a2) / max(len(a1 | a2), 1)







    return round(score, 3)











def _detect_anomalies() -> tuple[list[dict], list[dict], list[dict]]:



    """Detect anomalies in the graph."""



    if not _entities:



        return [], [], []







    entity_anomalies: list[dict] = []



    connection_anomalies: list[dict] = []



    relation_anomalies: list[dict] = []







    connection_counts: dict[str, int] = {}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        connection_counts[sid] = connection_counts.get(sid, 0) + 1



        connection_counts[tid] = connection_counts.get(tid, 0) + 1







    avg_degree = sum(connection_counts.values()) / len(connection_counts) if connection_counts else 0







    for eid, ent in _entities.items():



        if not ent.get("description") or ent.get("confidence", 1) < 0.3:



            entity_anomalies.append({



                "entityId": eid,



                "name": ent.get("name", eid),



                "reason": "missing_description" if not ent.get("description") else "low_confidence",



            })







        cnt = connection_counts.get(eid, 0)



        if cnt == 0:



            connection_anomalies.append({



                "entityId": eid,



                "name": ent.get("name", eid),



                "connectionCount": 0,



                "reason": "isolated",



            })



        elif cnt > avg_degree * 3:



            connection_anomalies.append({



                "entityId": eid,



                "name": ent.get("name", eid),



                "connectionCount": cnt,



                "reason": "hub_outlier",



            })







    for rid, rel in _relations.items():



        if rel.get("confidence", 1) < 0.5:



            relation_anomalies.append({



                "relationId": rid,



                "sourceId": rel.get("sourceId"),



                "targetId": rel.get("targetId"),



                "confidence": rel.get("confidence"),



                "reason": "low_confidence",



            })







    return entity_anomalies, connection_anomalies, relation_anomalies











@router.post("/similarity/find")



async def find_similar(req: SimilarEntityRequest) -> SimilarityResponse:



    """Find similar entities based on type, description, and aliases."""



    if req.entityId not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    ref = _entities[req.entityId]



    scores: list[tuple[str, float]] = []







    for eid, ent in _entities.items():



        if eid == req.entityId:



            continue







        score = _compute_similarity(ref, ent, req.matchTypes)



        if score > 0.1:



            scores.append((eid, score))







    scores.sort(key=lambda x: -x[1])



    top = scores[: req.maxResults]







    similar = [



        SimilarEntity(



            entityId=eid,



            name=_entities[eid].get("name", eid),



            type=_entities[eid].get("type", ""),



            score=score,



        )



        for eid, score in top



    ]







    return SimilarityResponse(



        referenceId=req.entityId,



        referenceName=ref.get("name", req.entityId),



        similar=similar,



    )











@router.get("/anomalies")



async def detect_anomalies() -> AnomalyResponse:



    """Detect anomalous entities and relations in the graph."""



    entity_anomalies, connection_anomalies, relation_anomalies = _detect_anomalies()







    total = len(entity_anomalies) + len(connection_anomalies) + len(relation_anomalies)







    return AnomalyResponse(



        entityAnomalies=entity_anomalies,



        connectionAnomalies=connection_anomalies,



        relationAnomalies=relation_anomalies,



        totalAnomalies=total,



    )











# ── Temporal analysis endpoints ───────────────────────────────











def _calculate_entity_age(entity: dict) -> float:



    """Calculate entity age in days from creation timestamp."""



    ts = entity.get("_createdAt")



    if ts is None:



        return 0.0



    return (time.time() - ts) / 86400  # Convert seconds to days











@router.get("/temporal/stats")



async def get_temporal_stats() -> TemporalStatsResponse:



    """Get temporal statistics about the knowledge graph.







    Returns information about entity ages, oldest/newest entities,



    and distribution by type.



    """



    now = time.time()



    total_entities = len(_entities)







    if total_entities == 0:



        return TemporalStatsResponse(



            totalEntities=0,



            oldestEntity=None,



            newestEntity=None,



            averageAgeDays=0.0,



            entitiesByType={},



            totalRelations=len(_relations),



        )







    oldest: dict | None = None



    newest: dict | None = None



    oldest_age = -1.0



    newest_age = float("inf")



    total_age = 0.0



    type_counts: dict[str, int] = {}







    for e in _entities.values():



        age = _calculate_entity_age(e)



        total_age += age







        etype = e.get("type", "unknown")



        type_counts[etype] = type_counts.get(etype, 0) + 1







        if oldest is None or age > oldest_age:



            oldest = e



            oldest_age = age







        if newest is None or age < newest_age:



            newest = e



            newest_age = age







    avg_age = total_age / total_entities if total_entities > 0 else 0.0







    return TemporalStatsResponse(



        totalEntities=total_entities,



        oldestEntity={



            "id": oldest.get("id"),



            "name": oldest.get("name"),



            "type": oldest.get("type"),



            "ageDays": round(oldest_age, 1),



        } if oldest else None,



        newestEntity={



            "id": newest.get("id"),



            "name": newest.get("name"),



            "type": newest.get("type"),



            "ageDays": round(newest_age, 1),



        } if newest else None,



        averageAgeDays=round(avg_age, 1),



        entitiesByType=type_counts,



        totalRelations=len(_relations),



    )











@router.get("/temporal/activity")



async def get_activity_stats(



    limit: int = Query(default=10, ge=1, le=100, description="Number of entities to return")



) -> ActivityStatsResponse:



    """Get activity statistics based on access counts.







    Returns most and least accessed entities, useful for



    identifying popular or neglected entities.



    """



    entities_with_access = [



        {"id": e.get("id"), "name": e.get("name"), "type": e.get("type"),



         "accessCount": e.get("accessCount", 0), "lastAccessed": e.get("lastAccessed")}



        for e in _entities.values()



    ]







    # Sort by access count



    sorted_by_access = sorted(entities_with_access, key(lambda x: x.get("accessCount", 0)), reverse=True)







    most_accessed = sorted_by_access[:limit]



    least_accessed = sorted(sorted_by_access, key=lambda x: x.get("accessCount", 0))[:limit]







    # Calculate stats



    access_counts = [e.get("accessCount", 0) for e in _entities.values()]



    access_stats = {



        "totalAccesses": sum(access_counts),



        "averageAccesses": round(sum(access_counts) / len(access_counts), 1) if access_counts else 0,



        "maxAccesses": max(access_counts) if access_counts else 0,



    }







    return ActivityStatsResponse(



        mostAccessed=most_accessed,



        leastAccessed=least_accessed,



        accessStats=access_stats,



    )











@router.get("/temporal/recent")



async def get_recent_activity(



    days: int = Query(default=7, ge=1, le=90, description="Number of days to look back"),



    limit: int = Query(default=20, ge=1, le=100, description="Max entities per category"),



) -> RecentActivityResponse:



    """Get recently created and updated entities.







    Useful for tracking recent knowledge additions and changes.



    """



    now = time.time()



    cutoff = now - (days * 86400)







    recently_created: list[dict] = []



    recently_updated: list[dict] = []







    for e in _entities.values():



        created_ts = e.get("_createdAt", 0)



        updated_ts = e.get("_updatedAt", "")







        if created_ts and created_ts >= cutoff:



            recently_created.append({



                "id": e.get("id"),



                "name": e.get("name"),



                "type": e.get("type"),



                "createdAt": e.get("createdAt"),



            })







        if updated_ts:



            # Try to parse ISO date



            try:



                updated_time = datetime.fromisoformat(updated_ts.replace("Z", "+00:00"))



                updated_ts_val = updated_time.timestamp()



                if updated_ts_val >= cutoff:



                    recently_updated.append({



                        "id": e.get("id"),



                        "name": e.get("name"),



                        "type": e.get("type"),



                        "updatedAt": updated_ts,



                    })



            except (ValueError, TypeError):



                pass







    # Sort by creation time (newest first)



    recently_created.sort(key=lambda x: x.get("createdAt", ""), reverse=True)



    recently_updated.sort(key=lambda x: x.get("updatedAt", ""), reverse=True)







    return RecentActivityResponse(



        recentlyCreated=recently_created[:limit],



        recentlyUpdated=recently_updated[:limit],



        totalRecentCreates=len(recently_created),



        totalRecentUpdates=len(recently_updated),



    )











@router.get("/entities/by-doc/{doc_id}")



async def get_entities_by_document(doc_id: str) -> list[dict]:



    """Return all KG entities linked to a specific Knowledge Base document.







    Entities created during document upload store sourceDocId in their



    properties. This endpoint queries by that property.



    """



    results: list[dict] = []



    for e in _entities.values():



        props = e.get("properties", {})



        if isinstance(props, dict) and props.get("sourceDocId") == doc_id:



            results.append(dict(e))



    return results











