@router.get("/stats")



async def get_stats() -> GraphStatsResponse:



    entity_count = len(_entities)



    relation_count = len(_relations)



    entity_types: dict[str, int] = {}



    confidences: list[float] = []



    for e in _entities.values():



        t = e.get("type", "unknown")



        entity_types[t] = entity_types.get(t, 0) + 1



        confidences.append(e.get("confidence", 0))



    relation_types: dict[str, int] = {}



    for r in _relations.values():



        t = r.get("type", "unknown")



        relation_types[t] = relation_types.get(t, 0) + 1







    avg_conf = sum(confidences) / len(confidences) if confidences else 0.0







    # Compute orphaned and most-connected



    connected = set()



    connection_counts: dict[str, int] = {}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        if sid:



            connected.add(sid)



            connection_counts[sid] = connection_counts.get(sid, 0) + 1



        if tid:



            connected.add(tid)



            connection_counts[tid] = connection_counts.get(tid, 0) + 1



    orphaned = sum(1 for eid in _entities if eid not in connected)



    most = sorted(connection_counts.items(), key=lambda x: -x[1])[:10]



    most_connected = [



        {"entityId": eid, "name": _entities[eid].get("name", eid), "connectionCount": cnt}



        for eid, cnt in most



    ]







    return GraphStatsResponse(



        totalEntities=entity_count,



        totalRelations=relation_count,



        entityTypes=entity_types,



        relationTypes=relation_types,



        averageConfidence=round(avg_conf, 3),



        orphanedEntities=orphaned,



        mostConnected=most_connected,



    )











# ── Webhook storage for real-time push ────────────────────────────







_webhooks: dict[str, dict] = {}  # webhook_id -> {url, events, secret}



_creation_timestamps: dict[str, float] = {}  # entity_id -> timestamp











def _trigger_webhooks(event_type: str, data: dict) -> None:



    """Trigger all webhooks matching the event type."""



    for wid, hook in _webhooks.items():



        if event_type in hook.get("events", []):



            try:



                import aiohttp



                import asyncio







                async def _send():



                    async with aiohttp.ClientSession() as session:



                        payload = {



                            "event": event_type,



                            "timestamp": time.time(),



                            "data": data,



                        }



                        await session.post(hook["url"], json=payload, timeout=aiohttp.ClientTimeout(total=5))







                asyncio.create_task(_send())



            except Exception:



                pass  # Non-blocking, ignore failures











