    wid = str(uuid.uuid4())[:8]



    _webhooks[wid] = {



        "url": req.url,



        "events": req.events,



        "secret": req.secret,



    }



    return WebhookResponse(



        webhookId=wid,



        url=req.url,



        events=req.events,



        createdAt=time.time(),



    )











