@router.delete("/webhooks/{webhook_id}")



async def delete_webhook(webhook_id: str) -> dict:



    """Delete a webhook."""



    if webhook_id in _webhooks:



        del _webhooks[webhook_id]



        return {"deleted": webhook_id}



    raise HTTPException(status_code=404, detail="Webhook not found")











@router.get("/stats/enhanced")



async def get_enhanced_stats() -> EnhancedStatsResponse:



    """Get enhanced graph statistics with analytics."""



    entity_count = len(_entities)



    relation_count = len(_relations)







    # Entity types



    entity_types: dict[str, int] = {}



    confidences: list[float] = []



    for e in _entities.values():



        t = e.get("type", "unknown")



        entity_types[t] = entity_types.get(t, 0) + 1



        confidences.append(e.get("confidence", 0))







    # Relation types



    relation_types: dict[str, int] = {}



    for r in _relations.values():



        t = r.get("type", "unknown")



        relation_types[t] = relation_types.get(t, 0) + 1







    avg_conf = sum(confidences) / len(confidences) if confidences else 0.0







    # Connected entities and degree distribution



    connected = set()



    degree_counts: dict[str, int] = {}



    for r in _relations.values():



        sid = r.get("sourceId", "")



        tid = r.get("targetId", "")



        if sid:



            connected.add(sid)



            degree_counts[sid] = degree_counts.get(sid, 0) + 1



        if tid:



            connected.add(tid)



            degree_counts[tid] = degree_counts.get(tid, 0) + 1







    orphaned = sum(1 for eid in _entities if eid not in connected)







    # Most connected



    most = sorted(degree_counts.items(), key=lambda x: -x[1])[:10]



    most_connected = [



        {"entityId": eid, "name": _entities[eid].get("name", eid), "connectionCount": cnt}



        for eid, cnt in most



    ]







    # Degree distribution (histogram)



    degree_distribution: dict[int, int] = {}



    for cnt in degree_counts.values():



        degree_distribution[cnt] = degree_distribution.get(cnt, 0) + 1







    # Average degree



    avg_degree = sum(degree_counts.values()) / entity_count if entity_count > 0 else 0.0







    # Graph density: actual_edges / possible_edges = 2*E / (V*(V-1))



    possible_edges = entity_count * (entity_count - 1)



    density = (2 * relation_count) / possible_edges if possible_edges > 0 else 0.0







    # Time series (last 7 days)



    now = time.time()



    day_ms = 86400



    time_series: dict[str, list[dict]] = {"entities": [], "relations": []}



    for days_ago in range(7, 0, -1):



        cutoff = now - (days_ago * day_ms)



        prev_cutoff = cutoff - day_ms







        ents_in_period = sum(



            1 for ts in _creation_timestamps.values()



            if prev_cutoff <= ts < cutoff



        )



        rels_in_period = sum(



            1 for r in _relations.values()



            if r.get("_createdAt", 0) and prev_cutoff <= r.get("_createdAt", 0) < cutoff



        )







        time_series["entities"].append({"day": days_ago, "count": ents_in_period})



        time_series["relations"].append({"day": days_ago, "count": rels_in_period})







    return EnhancedStatsResponse(



        totalEntities=entity_count,



        totalRelations=relation_count,



        entityTypes=entity_types,



        relationTypes=relation_types,



        averageConfidence=round(avg_conf, 3),



        orphanedEntities=orphaned,



        mostConnected=most_connected,



        density=round(density, 4),



        degreeDistribution=degree_distribution,



        avgDegree=round(avg_degree, 2),



        timeSeries=time_series,



    )











@router.post("/relations/extract")



async def extract_relations(req: ExtractRelationsRequest) -> ExtractRelationsResponse:



    """Extract relations from text using LLM.







    Analyzes text to determine if a relation exists between the specified



    source and target entities. Uses LLM by default for accurate extraction.



    """



    if req.use_llm:



        llm_relations = await _extract_relations_with_llm(



            req.text,



            req.sourceEntity,



            req.sourceType,



            req.targetEntity,



            req.targetType,



            req.relationTypes,



            req.model_name,



        )



        if llm_relations:



            return ExtractRelationsResponse(



                relations=llm_relations[:20],



                createdCount=len(llm_relations),



            )







    # Fallback: return empty response if no relations found



    return ExtractRelationsResponse(relations=[], createdCount=0)











@router.post("/relations/extract-and-create")



async def extract_and_create_relations(



    req: ExtractRelationsRequest,



) -> ExtractAndCreateRelationsResponse:



    """Extract relations from text and auto-create entities if they don't exist.







    This endpoint extends /relations/extract by automatically creating



    the source and target entities if they are not found in the knowledge graph.



    The extracted relations are also saved to the knowledge graph.



    """



    if req.use_llm:



        llm_relations = await _extract_relations_with_llm(



            req.text,



            req.sourceEntity,



            req.sourceType,



            req.targetEntity,



            req.targetType,



            req.relationTypes,



            req.model_name,



        )



    else:



        llm_relations = []







    # Extract and create entities + relations



    async with _lock:



        created_entities_count = 0



        created_relations_count = 0







        for rel in llm_relations:



            # Find or create source entity



            sid, source_created = await _find_or_create_entity(



                rel.sourceEntity, req.sourceType, req.source or "llm-extraction"



            )



            if source_created:



                created_entities_count += 1







            # Find or create target entity



            tid, target_created = await _find_or_create_entity(



                rel.targetEntity, req.targetType, req.source or "llm-extraction"



            )



            if target_created:



                created_entities_count += 1







            # Create the relation in the knowledge graph



            rid = str(uuid.uuid4())



            now = _now_iso()



            relation = {



                "id": rid,



                "sourceId": sid,



                "targetId": tid,



                "type": rel.relationType,



                "properties": rel.properties,



                "confidence": rel.confidence,



                "source": req.source or "llm-extraction",



                "createdAt": now,



                "updatedAt": now,



            }



            _relations[rid] = relation



            created_relations_count += 1







        if created_relations_count > 0 or created_entities_count > 0:



            await _save_state()







    return ExtractAndCreateRelationsResponse(



        relations=llm_relations[:20],



        createdRelations=created_relations_count,



        createdEntities=created_entities_count,



    )











@router.get("/export/viz")



async def export_viz(



    format: str = Query(



        default="d3",



        description="Output format: d3, cytoscape, graphml, gexf, or full"



    ),



    include_metadata: bool = Query(



        default=False,



        description="Include full metadata in output"



    ),



):



    """Export knowledge graph for visualization.







    Formats:



    - d3: D3.js compatible node-edge format



    - cytoscape: Cytoscape.js format



    - graphml: GraphML XML format



    - gexf: Gephi GEXF XML format



    - full: Full data with metadata







    Query Parameters:



    - format: Output format (default: d3)



    - include_metadata: Include createdAt, updatedAt, properties (default: false)



    """



    if format == "d3":



        nodes = [



            {



                "data": {



                    "id": e["id"],



                    "label": e.get("name", e["id"]),



                    "type": e.get("type", "unknown"),



                    "confidence": e.get("confidence", 0),



                }



            }



            for e in _entities.values()



        ]



        edges = [



            {



                "data": {



                    "id": r["id"],



                    "source": r.get("sourceId", ""),



                    "target": r.get("targetId", ""),



                    "label": r.get("type", "related_to"),



                    "confidence": r.get("confidence", 0),



                }



            }



            for r in _relations.values()



        ]



        return {"nodes": nodes, "edges": edges}







    elif format == "cytoscape":



        elements = []



        # Add nodes



        for e in _entities.values():



            elements.append({



                "data": {



                    "id": e["id"],



                    "label": e.get("name", e["id"]),



                    "type": e.get("type", "unknown"),



                }



            })



        # Add edges



        for r in _relations.values():



            elements.append({



                "data": {



                    "id": r["id"],



                    "source": r.get("sourceId", ""),



                    "target": r.get("targetId", ""),



                    "label": r.get("type", "related_to"),



                }



            })



        return {"elements": elements}







    elif format == "graphml":



        # Generate GraphML XML



        nodes_xml = ""



        for e in _entities.values():



            nodes_xml += f"""    <node id="{e['id']}">



      <data key="label">{e.get('name', e['id'])}</data>



      <data key="type">{e.get('type', 'unknown')}</data>



    </node>"""







        edges_xml = ""



        for r in _relations.values():



            edges_xml += f"""    <edge id="{r['id']}" source="{r.get('sourceId', '')}" target="{r.get('targetId', '')}">



      <data key="label">{r.get('type', 'related_to')}</data>



    </edge>"""







        graphml = f"""<?xml version="1.0" encoding="UTF-8"?>



<graphml xmlns="http://graphml.org/graphml/1.1">



  <key id="label" for="node" attr.name="label" attr.type="string"/>



  <key id="type" for="node" attr.name="type" attr.type="string"/>



  <key id="label" for="edge" attr.name="label" attr.type="string"/>



  <graph id="G" edgedefault="directed">



{nodes_xml}



{edges_xml}



  </graph>



</graphml>"""



        return {"graphml": graphml}







    elif format == "gexf":



        # Generate GEXF XML (Gephi format)



        # Get unique attributes for dynamic edge definition



        node_attrs = []



        edge_attrs = []







        # Collect all property keys



        all_node_keys = set()



        all_edge_keys = set()



        for e in _entities.values():



            if e.get("properties"):



                all_node_keys.update(e["properties"].keys())



        for r in _relations.values():



            if r.get("properties"):



                all_edge_keys.update(r["properties"].keys())







        # Build attribute declarations



        attrs_xml = ""



        for key in all_node_keys:



            attrs_xml += f"""    <attribute type="string" id="{key}" title="{key}"/>



"""



        for key in all_edge_keys:



            attrs_xml += f"""    <attribute type="string" id="e_{key}" title="{key}"/>



"""







        # Build nodes XML



        nodes_xml = ""



        for e in _entities.values():



            node_id = e["id"]



            node_label = e.get("name", node_id)



            node_type = e.get("type", "unknown")







            # Add attributes if include_metadata



            attr_values = ""



            if include_metadata and e.get("properties"):



                for key, val in e["properties"].items():



                    attr_values += f"""        <attvalue for="{key}" value="{str(val).replace('"', '&quot;')}"/>



"""







            nodes_xml += f"""    <node id="{node_id}" label="{node_label}">



      <attvalues>



{attr_values}      </attvalues>



      <attributes class="node">



        <attribute value="{node_type}" for="type"/>



      </attributes>



    </node>



"""







        # Build edges XML



        edges_xml = ""



        for r in _relations.values():



            edge_id = r["id"]



            source = r.get("sourceId", "")



            target = r.get("targetId", "")



            edge_type = r.get("type", "related_to")







            # Add attributes if include_metadata



            attr_values = ""



            if include_metadata and r.get("properties"):



                for key, val in r["properties"].items():



                    attr_values += f"""        <attvalue for="e_{key}" value="{str(val).replace('"', '&quot;')}"/>



"""







            edges_xml += f"""    <edge id="{edge_id}" source="{source}" target="{target}" type="{edge_type}">



      <attvalues>



{attr_values}      </attvalues>



    </edge>



"""







        # Get current time for static graph



        from datetime import datetime



        now = datetime.now().strftime("%Y-%m-%d")







        gexf = f"""<?xml version="1.0" encoding="UTF-8"?>



<gexf xmlns="http://www.gexf.net/1.2draft" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://www.gexf.net/1.2draft http://www.gexf.net/1.2draft/gexf.xsd" version="1.2">



  <meta lastModifiedDate="{now}">



    <creator>DeerFlow Knowledge Graph</creator>



    <description>Knowledge Graph Export</description>



  </meta>



  <attributes class="node" mode="static">



{attrs_xml}  </attributes>



  <graph mode="static" defaultedgetype="directed">



    <attributes class="edge" mode="static">



    </attributes>



    <nodes>



{nodes_xml}    </nodes>



    <edges>



{edges_xml}    </edges>



  </graph>



</gexf>"""



        return {"gexf": gexf}







    elif format == "full":



        # Full export with all metadata



        nodes = []



        for e in _entities.values():



            node_data = {



                "id": e["id"],



                "name": e.get("name", e["id"]),



                "type": e.get("type", "unknown"),



                "confidence": e.get("confidence", 0),



            }



            if include_metadata:



                node_data.update({



                    "description": e.get("description", ""),



                    "aliases": e.get("aliases", []),



                    "properties": e.get("properties", {}),



                    "source": e.get("source", ""),



                    "createdAt": e.get("createdAt", ""),



                    "updatedAt": e.get("updatedAt", ""),



                    "accessCount": e.get("accessCount", 0),



                })



            nodes.append({"data": node_data})







        edges = []



        for r in _relations.values():



            edge_data = {



                "id": r["id"],



                "source": r.get("sourceId", ""),



                "target": r.get("targetId", ""),



                "type": r.get("type", "related_to"),



                "confidence": r.get("confidence", 0),



            }



            if include_metadata:



                edge_data.update({



                    "properties": r.get("properties", {}),



                    "source": r.get("source", ""),



                    "createdAt": r.get("createdAt", ""),



                })



            edges.append({"data": edge_data})







        # Add statistics



        stats = {



            "nodeCount": len(nodes),



            "edgeCount": len(edges),



            "entityTypes": list(set(e.get("type", "unknown") for e in _entities.values())),



            "relationTypes": list(set(r.get("type", "related_to") for r in _relations.values())),



        }







        return {



            "nodes": nodes,



            "edges": edges,



            "stats": stats,



            "version": "1.0",



        }







    else:



        raise HTTPException(status_code=400, detail=f"Unknown format: {format}")











@router.get("/export")



async def export_graph():



    return {



        "entities": list(_entities.values()),



        "relations": list(_relations.values()),



        "version": 1,



        "updatedAt": _now_iso(),



    }











# ── AI Entity Extraction ───────────────────────────────────────────











import re











class ExtractEntitiesRequest(BaseModel):



    """Request to extract entities from text."""



    text: str = Field(..., min_length=1, description="Text to extract entities from")



    types: list[str] = Field(



        default_factory=lambda: ["person", "organization", "project", "concept"],



        description="Entity types to extract"



    )



    source: str | None = Field(default=None, description="Source identifier for extracted entities")



    use_llm: bool = Field(default=False, description="Use LLM for extraction (more accurate)")



    model_name: str | None = Field(default=None, description="Model to use for LLM extraction")











class ExtractedEntity(BaseModel):



    """A single extracted entity."""



    name: str



    type: str



    confidence: float



    mentions: int = 1











class ExtractEntitiesResponse(BaseModel):



    """Response with extracted entities."""



    entities: list[ExtractedEntity]



    relations: list[dict] = Field(default_factory=list)



    extractedCount: int = 0











class ExtractRelationsRequest(BaseModel):



    """Request to extract relations from text."""



    text: str = Field(..., min_length=1, description="Text to extract relations from")



    sourceEntity: str = Field(..., description="Source entity name for the relation")



    sourceType: str = Field(..., description="Source entity type")



    targetEntity: str = Field(..., description="Target entity name for the relation")



    targetType: str = Field(..., description="Target entity type")



    relationTypes: list[str] = Field(



        default_factory=lambda: ["owns", "works_for", "related_to", "part_of", "uses", "depends_on"],



        description="Relation types to consider"



    )



    source: str | None = Field(default=None, description="Source identifier")



    use_llm: bool = Field(default=True, description="Use LLM for extraction (more accurate)")



    model_name: str | None = Field(default=None, description="Model to use for LLM extraction")











class ExtractedRelation(BaseModel):



    """A single extracted relation."""



    sourceEntity: str



    targetEntity: str



    relationType: str



    confidence: float



    properties: dict = Field(default_factory=dict)











class ExtractAndCreateRelationsResponse(BaseModel):



    """Response with extracted relations and created entities."""



    relations: list[ExtractedRelation]



    createdRelations: int = 0



    createdEntities: int = 0











# Helper functions



async def _find_or_create_entity(name: str, entity_type: str, source: str = "auto-creation") -> tuple[str, bool]:



    """Find an entity by name or create it if not found.







    Returns (entity_id, was_created).



    """



    # Search for existing entity with similar name



    for eid, entity in _entities.items():



        if name.lower() == entity.get("name", "").lower():



            return eid, False







    # Create new entity



    eid = str(uuid.uuid4())



    now = _now_iso()



    new_entity = {



        "id": eid,



        "name": name,



        "type": entity_type,



        "aliases": [],



        "description": f"Auto-created from relation extraction",



        "properties": {"autoCreated": True},



        "source": source,



        "confidence": 0.7,



        "createdAt": now,



        "updatedAt": now,



        "accessCount": 0,



        "lastAccessed": now,



    }



    _entities[eid] = new_entity



    return eid, True











_EXTRACTION_PATTERNS: dict[str, list[re.Pattern]] = {}











def _get_patterns(entity_type: str) -> list[re.Pattern]:



    """Get or compile extraction patterns for an entity type."""



    if entity_type not in _EXTRACTION_PATTERNS:



        patterns = []



        if entity_type == "person":



            # Look for capitalized names (simplified heuristic)



            patterns = [



                re.compile(r"\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)\b"),



                re.compile(r"\b([A-Z]\.?\s*[A-Z][a-z]+)\b"),



            ]



        elif entity_type == "organization":



            patterns = [



                re.compile(r"\b([A-Z][A-Za-z]+(?:\s+(?:Inc|Corp|Ltd|LLC|Co|Group|Company)))\b"),



                re.compile(r"\b(Google|Microsoft|Apple|Amazon|Meta|Tesla|OpenAI|Anthropic|NetEase|ByteDance)\b", re.IGNORECASE),



            ]



        elif entity_type == "project":



            patterns = [



                re.compile(r"\b(?:Project|Prj)[:\s]+([A-Z][A-Za-z0-9_-]+)", re.IGNORECASE),



                re.compile(r"\b([A-Z][a-z]+(?:\s+[A-Z][a-z0-9]+)+)\b"),



            ]



        elif entity_type == "concept":



            patterns = [



                re.compile(r"\b([A-Z][a-z]+(?:tion|ing|ness|ity))\b"),



            ]



        _EXTRACTION_PATTERNS[entity_type] = patterns



    return _EXTRACTION_PATTERNS[entity_type]











async def _extract_entities_with_llm(



    text: str,



    entity_types: list[str],



    model_name: str | None = None,



) -> list[ExtractedEntity]:



    """Extract entities using LLM for better accuracy.







    Uses the configured LLM to extract entities from text with higher



    confidence than pattern-based extraction.



    """



    if not text or not entity_types:



        return []







    extracted: dict[str, ExtractedEntity] = {}







    try:



        # Get configured model (fallback to first available)



        llm = None



        if model_name:



            try:



                llm = create_chat_model(model_name)



            except Exception:



                logger.debug(f"Model {model_name} not available, trying default")







        if llm is None:



            # Try to get any available model



            from deerflow.config import get_app_config







            config = get_app_config()



            if config.models:



                try:



                    llm = create_chat_model(config.models[0].name)



                except Exception as e:



                    logger.debug(f"No LLM available: {e}")



                    return []







        if llm is None:



            return []







        # Build extraction prompt



        types_str = ", ".join(entity_types)



        prompt = f"""Extract all {types_str} entities from the following text.







Return a JSON array with each entity having:



- name: the entity name



- type: the entity type (one of: {types_str})



- confidence: confidence score (0.0-1.0)







Text:



{text}







Respond with only the JSON array."""







        # Call LLM



        from langchain_core.messages import HumanMessage







        response = await llm.ainvoke([HumanMessage(content=prompt)])



        content = response.content if hasattr(response, "content") else str(response)







        # Parse JSON from response



        import json







        try:



            # Try to extract JSON array from response



            import re







            json_match = re.search(r"\[.*\]", content, re.DOTALL)



            if json_match:



                entities_data = json.loads(json_match.group())



                for ent in entities_data:



                    if isinstance(ent, dict) and "name" in ent and "type" in ent:



                        key = f"{ent['type']}:{ent['name'].lower()}"



                        if key not in extracted:



                            extracted[key] = ExtractedEntity(



                                name=ent["name"],



                                type=ent["type"],



                                confidence=ent.get("confidence", 0.7),



                                mentions=1,



                            )



                        else:



                            extracted[key].mentions += 1



        except Exception as e:



            logger.debug(f"Failed to parse LLM response: {e}")







    except Exception as e:



        logger.warning(f"LLM extraction failed: {e}")







    return list(extracted.values())











async def _extract_relations_with_llm(



    text: str,



    source_entity: str,



    source_type: str,



    target_entity: str,



    target_type: str,



    relation_types: list[str],



    model_name: str | None = None,



) -> list[ExtractedRelation]:



    """Extract relations using LLM for better accuracy.







    Uses the configured LLM to extract relations between entities from text



    with higher confidence than pattern-based extraction.



    """



    if not text or not source_entity or not target_entity:



        return []







    extracted: list[ExtractedRelation] = []







    try:



        # Get configured model (fallback to first available)



        llm = None



        if model_name:



            try:



                llm = create_chat_model(model_name)



            except Exception:



                logger.debug(f"Model {model_name} not available, trying default")







        if llm is None:



            from deerflow.config import get_app_config







            config = get_app_config()



            if config.models:



                try:



                    llm = create_chat_model(config.models[0].name)



                except Exception as e:



                    logger.debug(f"No LLM available: {e}")



                    return []







        if llm is None:



            return []







        # Build extraction prompt



        types_str = ", ".join(relation_types)



        prompt = f"""Analyze the following text and determine if there is a relation between the source entity



"{source_entity}" (type: {source_type}) and target entity "{target_entity}" (type: {target_type}).







Return a JSON array of relations found. Each relation should have:



- sourceEntity: the source entity name



- targetEntity: the target entity name



- relationType: the relation type (one of: {types_str})



- confidence: confidence score (0.0-1.0)



- properties: any additional properties discovered







Text:



{text}







Respond with only the JSON array. If no relation exists, return an empty array []. """







        # Call LLM



        from langchain_core.messages import HumanMessage







        response = await llm.ainvoke([HumanMessage(content=prompt)])



        content = response.content if hasattr(response, "content") else str(response)







        # Parse JSON from response



        import json



        import re







        try:



            json_match = re.search(r"\[.*\]", content, re.DOTALL)



            if json_match:



                relations_data = json.loads(json_match.group())



                for rel in relations_data:



                    if isinstance(rel, dict) and "relationType" in rel:



                        extracted.append(ExtractedRelation(



                            sourceEntity=rel.get("sourceEntity", source_entity),



                            targetEntity=rel.get("targetEntity", target_entity),



                            relationType=rel["relationType"],



                            confidence=rel.get("confidence", 0.7),



                            properties=rel.get("properties", {}),



                        ))



        except Exception as e:



            logger.debug(f"Failed to parse LLM response: {e}")







    except Exception as e:



        logger.warning(f"LLM relation extraction failed: {e}")







    return extracted











def _extract_entities_from_text(text: str, entity_type: str) -> list[tuple[str, float]]:



    """Extract entities of a given type from text using simple patterns."""



    results: list[tuple[str, float]] = []



    seen: set[str] = set()







    for pattern in _get_patterns(entity_type):



        for match in pattern.finditer(text):



            name = match.group(1).strip() if match.lastindex else match.group(0).strip()



            if name and name.lower() not in seen:



                seen.add(name.lower())



                # Simple confidence based on context



                confidence = 0.5



                if len(name) > 3:



                    confidence += 0.1



                # Check for repeated mentions



                count = len(re.findall(re.escape(name), text, re.IGNORECASE))



                confidence = min(0.95, confidence + count * 0.05)



                results.append((name, confidence))







    return results











@router.post("/extract")



async def extract_entities(req: ExtractEntitiesRequest) -> ExtractEntitiesResponse:



    """Extract entities from text.







    Uses pattern-based extraction by default. Set use_llm=true to enable



    LLM-based extraction for better accuracy.



    """



    # Use LLM extraction if requested



    if req.use_llm:



        llm_extracted = await _extract_entities_with_llm(



            req.text,



            req.types,



            req.model_name,



        )



        if llm_extracted:



            return ExtractEntitiesResponse(



                entities=llm_extracted[:50],



                extractedCount=len(llm_extracted),



            )







    # Fallback to pattern-based extraction



    extracted: list[ExtractedEntity] = []



    all_entities: dict[str, ExtractedEntity] = {}







    for entity_type in req.types:



        matches = _extract_entities_from_text(req.text, entity_type)



        for name, confidence in matches:



            key = f"{entity_type}:{name.lower()}"



            if key in all_entities:



                all_entities[key].mentions += 1



                all_entities[key].confidence = min(0.95, all_entities[key].confidence + 0.05)



            else:



                all_entities[key] = ExtractedEntity(



                    name=name,



                    type=entity_type,



                    confidence=confidence,



                    mentions=1



                )







    # Sort by mentions and confidence



    sorted_entities = sorted(all_entities.values(), key=lambda e: (-e.mentions, -e.confidence))







    return ExtractEntitiesResponse(



        entities=sorted_entities[:50],  # Limit to top 50



        extractedCount=len(sorted_entities)



    )











@router.post("/extract-and-create")



async def extract_and_create(req: ExtractEntitiesRequest) -> ExtractEntitiesResponse:



    """Extract and create entities in the knowledge graph."""



    extracted = await extract_entities(req)







    async with _lock:



        created_entities: list[ExtractedEntity] = []



        for entity in extracted.entities:



            # Check for existing entity with similar name



            existing = False



            for existing_entity in _entities.values():



                if entity.name.lower() in existing_entity.get("name", "").lower():



                    existing = True



                    break







            if not existing:



                eid = str(uuid.uuid4())



                now = _now_iso()



                new_entity = {



                    "id": eid,



                    "name": entity.name,



                    "type": entity.type,



                    "aliases": [],



                    "description": f"Extracted from text (confidence: {entity.confidence:.2f})",



                    "properties": {"extractedFrom": req.text[:200], "mentions": entity.mentions},



                    "source": req.source or "pattern-extraction",



                    "confidence": entity.confidence,



                    "createdAt": now,



                    "updatedAt": now,



                    "accessCount": 0,



                    "lastAccessed": now,



                }



                _entities[eid] = new_entity



                created_entities.append(entity)







        await _save_state()







    return ExtractEntitiesResponse(



        entities=created_entities,



        extractedCount=len(created_entities)



    )











@router.post("/extract-session")



async def extract_from_session(



    session_id: str = Query(..., description="Session ID to extract from"),



    types: list[str] | None = Query(default=None),



    create: bool = Query(default=False, description="Whether to create extracted entities"),



) -> ExtractEntitiesResponse:



    """Extract entities from a session's conversation history."""



    from deerflow.client import DeerFlowClient







    if types is None:



        types = ["person", "organization", "project", "concept"]







    client = DeerFlowClient()



    messages: list[dict] = []







    try:



        # Try to get session messages



        result = client.get_memory()



        if result and "messages" in result:



            messages = result["messages"]



    except Exception as e:



        logger.warning(f"Could not get session messages: {e}")







    if not messages:



        return ExtractEntitiesResponse(entities=[], extractedCount=0)







    # Build text from messages



    text_parts = []



    for msg in messages[-20:]:  # Last 20 messages



        if isinstance(msg, dict):



            content = msg.get("content", "")



            role = msg.get("role", "")



            if content:



                text_parts.append(f"{role}: {content}")







    full_text = "\n".join(text_parts)







    req = ExtractEntitiesRequest(text=full_text, types=types, source=f"session:{session_id}")







    if create:



        return await extract_and_create(req)



    else:



        return await extract_entities(req)











