# ── Graph Snapshots & Versioning ──────────────────────────────────────







# In-memory snapshot storage: snapshot_id -> (entities, relations, created_at)



_graph_snapshots: dict[str, tuple[dict, dict, str]] = {}











class SnapshotRequest(BaseModel):



    """Request to create a snapshot."""



    name: str = Field(..., description="Snapshot name")



    description: str | None = Field(default=None, description="Optional description")











class SnapshotResponse(BaseModel):



    """Response for snapshot operations."""



    snapshot_id: str



    name: str



    description: str | None



    entity_count: int



    relation_count: int



    created_at: str



    size_bytes: int











class SnapshotListResponse(BaseModel):



    """List of snapshots."""



    snapshots: list[dict]



    total: int











class RestoreResponse(BaseModel):



    """Response for restore operation."""



    restored_entities: int



    restored_relations: int



    snapshot_id: str



    previous_state: dict











@router.post("/snapshots", response_model=SnapshotResponse)



async def create_snapshot(req: SnapshotRequest) -> SnapshotResponse:



    """Create a snapshot of the current knowledge graph state.







    Saves all entities and relations to an in-memory snapshot that can be restored later.



    """



    import copy



    snapshot_id = f"snap_{uuid.uuid4().hex[:12]}"



    now = _now_iso()







    # Deep copy entities and relations



    entities_snapshot = copy.deepcopy(_entities)



    relations_snapshot = copy.deepcopy(_relations)







    # Store snapshot



    _graph_snapshots[snapshot_id] = (entities_snapshot, relations_snapshot, now)







    # Calculate approximate size



    import json



    size = len(json.dumps(entities_snapshot)) + len(json.dumps(relations_snapshot))







    return SnapshotResponse(



        snapshot_id=snapshot_id,



        name=req.name,



        description=req.description,



        entity_count=len(entities_snapshot),



        relation_count=len(relations_snapshot),



        created_at=now,



        size_bytes=size,



    )











@router.get("/snapshots", response_model=SnapshotListResponse)



async def list_snapshots() -> SnapshotListResponse:



    """List all snapshots."""



    snapshots = []



    for sid, (entities, relations, created) in _graph_snapshots.items():



        import json



        snapshots.append({



            "snapshot_id": sid,



            "entity_count": len(entities),



            "relation_count": len(relations),



            "created_at": created,



            "size_bytes": len(json.dumps(entities)) + len(json.dumps(relations)),



        })







    return SnapshotListResponse(



        snapshots=snapshots,



        total=len(snapshots),



    )











@router.get("/snapshots/{snapshot_id}", response_model=SnapshotResponse)



async def get_snapshot(snapshot_id: str) -> SnapshotResponse:



    """Get details of a specific snapshot."""



    if snapshot_id not in _graph_snapshots:



        from fastapi import HTTPException



        raise HTTPException(status_code=404, detail="Snapshot not found")







    entities, relations, created = _graph_snapshots[snapshot_id]



    import json



    return SnapshotResponse(



        snapshot_id=snapshot_id,



        name=snapshot_id,



        description=None,



        entity_count=len(entities),



        relation_count=len(relations),



        created_at=created,



        size_bytes=len(json.dumps(entities)) + len(json.dumps(relations)),



    )











@router.post("/snapshots/{snapshot_id}/restore", response_model=RestoreResponse)



async def restore_snapshot(snapshot_id: str) -> RestoreResponse:



    """Restore knowledge graph from a snapshot.







    Returns the previous state so it can be restored again if needed.



    """



    import copy



    if snapshot_id not in _graph_snapshots:



        from fastapi import HTTPException



        raise HTTPException(status_code=404, detail="Snapshot not found")







    # Save current state as backup



    previous_state = {



        "entities": copy.deepcopy(_entities),



        "relations": copy.deepcopy(_relations),



    }







    # Restore from snapshot



    entities, relations, _ = _graph_snapshots[snapshot_id]



    _entities = copy.deepcopy(entities)



    _relations = copy.deepcopy(relations)







    return RestoreResponse(



        restored_entities=len(_entities),



        restored_relations=len(_relations),



        snapshot_id=snapshot_id,



        previous_state={"entities": len(previous_state["entities"]), "relations": len(previous_state["relations"])},



    )











@router.delete("/snapshots/{snapshot_id}")



async def delete_snapshot(snapshot_id: str) -> dict:



    """Delete a snapshot."""



    if snapshot_id not in _graph_snapshots:



        from fastapi import HTTPException



        raise HTTPException(status_code=404, detail="Snapshot not found")







    del _graph_snapshots[snapshot_id]



    return {"deleted": snapshot_id}











