# ── Analytics Dashboard Endpoints ────────────────────────











# Historical data storage for trend analysis (in-memory)



_analytics_history: list[dict] = []



_analytics_history_max_size = 1000











def _record_analytics_snapshot() -> None:



    """Record current analytics for trend analysis."""



    from datetime import datetime, timezone



    now = datetime.now(timezone.utc)



    snapshot = {



        "timestamp": now.isoformat(),



        "entity_count": len(_entities),



        "relation_count": len(_relations),



        "avg_confidence": 0.0,



        "graph_density": 0.0,



    }







    # Calculate average confidence



    if _entities:



        total_conf = sum(e.get("confidence", 0.0) for e in _entities.values())



        snapshot["avg_confidence"] = total_conf / len(_entities)







    # Calculate graph density



    n = len(_entities)



    snapshot["graph_density"] = len(_relations) / (n * (n - 1)) if n > 1 else 0.0







    _analytics_history.append(snapshot)



    if len(_analytics_history) > _analytics_history_max_size:



        _analytics_history.pop(0)











def _parse_time_range(range_str: str) -> float:



    """Parse time range string to seconds."""



    mapping = {"1h": 3600, "6h": 6*3600, "24h": 24*3600, "7d": 7*24*3600, "30d": 30*24*3600, "90d": 90*24*3600}



    return mapping.get(range_str, 7*24*3600)











@router.post("/analytics/dashboard", response_model=KPIDashboardResponse)



async def get_kpi_dashboard(req: KPIDashboardRequest) -> KPIDashboardResponse:



    """Get enhanced KPI dashboard with trends and anomaly detection.







    Provides:



    - Summary KPIs (counts, density, isolation)



    - Growth metrics (24h changes)



    - Quality metrics (confidence)



    - Connectivity metrics



    - Trending entities



    - Anomaly alerts



    - Time series data



    """



    from datetime import datetime, timezone







    # Record current snapshot for trend analysis



    _record_analytics_snapshot()







    # Time range calculation



    time_range_seconds = _parse_time_range(req.time_range)



    time_range_start = time.time() - time_range_seconds







    # Basic counts



    total_entities = len(_entities)



    total_relations = len(_relations)







    # Active in last 24h



    cutoff_24h = time.time() - (24 * 3600)



    active_entities_24h = sum(1 for ts in _creation_timestamps.values() if ts >= cutoff_24h)



    active_relations_24h = sum(1 for r in _relations.values() if r.get("createdAt", 0) >= cutoff_24h)







    # Growth calculations (compare to 24h ago)



    cutoff_48h = time.time() - (48 * 3600)



    prev_entities_24h = sum(1 for ts in _creation_timestamps.values() if cutoff_48h <= ts < cutoff_24h)



    entity_growth_24h = active_entities_24h - prev_entities_24h



    entity_growth_rate = (entity_growth_24h / prev_entities_24h * 100) if prev_entities_24h > 0 else 0.0







    prev_relations_24h = sum(1 for r in _relations.values() if (cutoff_48h <= r.get("createdAt", 0) < cutoff_24h))



    relation_growth_24h = active_relations_24h - prev_relations_24h



    relation_growth_rate = (relation_growth_24h / prev_relations_24h * 100) if prev_relations_24h > 0 else 0.0







    # Quality metrics



    confidences = [e.get("confidence", 0.0) for e in _entities.values()]



    avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0



    high_confidence_count = sum(1 for c in confidences if c >= 0.8)



    high_confidence_ratio = high_confidence_count / len(confidences) if confidences else 0.0



    low_confidence_count = sum(1 for c in confidences if c < 0.3)







    # Connectivity metrics



    connection_counts: dict[str, int] = {}



    for relation in _relations.values():



        source = relation.get("sourceId", "")



        target = relation.get("targetId", "")



        if source:



            connection_counts[source] = connection_counts.get(source, 0) + 1



        if target:



            connection_counts[target] = connection_counts.get(target, 0) + 1







    connection_values = list(connection_counts.values())



    avg_connections = sum(connection_values) / len(connection_values) if connection_values else 0.0



    max_connections = max(connection_values) if connection_values else 0



    hub_entities = sum(1 for c in connection_values if c > 10)







    # Graph density and isolation



    n = len(_entities)



    graph_density = len(_relations) / (n * (n - 1)) if n > 1 else 0.0



    all_connected = set(connection_counts.keys())



    isolated = set(_entities.keys()) - all_connected



    isolation_ratio = len(isolated) / n if n > 0 else 0.0







    # Build KPIs



    kpis = [



        DashboardKPI(label="Total Entities", value=total_entities, trend="stable", change_pct=0.0),



        DashboardKPI(label="Total Relations", value=total_relations, trend="stable", change_pct=0.0),



        DashboardKPI(label="Graph Density", value=round(graph_density * 100, 2), unit="%", trend="stable"),



        DashboardKPI(label="Avg Confidence", value=round(avg_confidence * 100, 1), unit="%", trend="stable"),



        DashboardKPI(label="Active (24h)", value=active_entities_24h,



                    trend="up" if entity_growth_24h > 0 else "down",



                    change_pct=round(entity_growth_rate, 1)),



    ]







    # Trending entities (entities with most connections)



    trending = []



    sorted_by_connections = sorted(connection_counts.items(), key=lambda x: x[1], reverse=True)



    for eid, score in sorted_by_connections[:5]:



        entity = _entities.get(eid, {})



        trending.append(TrendingEntity(



            entity_id=eid,



            name=entity.get("name", eid),



            type=entity.get("type", "unknown"),



            score=score,



            trend="rising" if score > 5 else "stable",



        ))







    # Anomaly detection



    anomaly_alerts = []



    if req.include_anomalies:



        # Check for isolation anomaly



        if isolation_ratio > 0.3:



            anomaly_alerts.append(AnomalyAlert(



                id=str(uuid.uuid4())[:8],



                severity="medium" if isolation_ratio > 0.5 else "low",



                type="isolation",



                message=f"High isolation ratio: {round(isolation_ratio * 100, 1)}% entities have no connections",



                affected_entity=None,



                detected_at=datetime.now(timezone.utc).isoformat(),



            ))







        # Check for low confidence



        if low_confidence_count > total_entities * 0.3:



            anomaly_alerts.append(AnomalyAlert(



                id=str(uuid.uuid4())[:8],



                severity="medium",



                type="quality",



                message=f"Low confidence: {low_confidence_count} entities have confidence < 0.3",



                affected_entity=None,



                detected_at=datetime.now(timezone.utc).isoformat(),



            ))







        # Check for density anomaly



        if graph_density > 0.8:



            anomaly_alerts.append(AnomalyAlert(



                id=str(uuid.uuid4())[:8],



                severity="high",



                type="density",



                message=f"Very high graph density: {round(graph_density * 100, 1)}%",



                affected_entity=None,



                detected_at=datetime.now(timezone.utc).isoformat(),



            ))







    # Time series data



    entity_time_series = []



    relation_time_series = []



    for snapshot in _analytics_history[-30:]:  # Last 30 snapshots



        entity_time_series.append(TimeSeriesPoint(



            timestamp=snapshot["timestamp"][:16],



            value=float(snapshot["entity_count"]),



        ))



        relation_time_series.append(TimeSeriesPoint(



            timestamp=snapshot["timestamp"][:16],



            value=float(snapshot["relation_count"]),



        ))







    return KPIDashboardResponse(



        total_entities=total_entities,



        total_relations=total_relations,



        active_entities_24h=active_entities_24h,



        active_relations_24h=active_relations_24h,



        graph_density=round(graph_density, 4),



        isolation_ratio=round(isolation_ratio, 4),



        entity_growth_24h=entity_growth_24h,



        relation_growth_24h=relation_growth_24h,



        entity_growth_rate=round(entity_growth_rate, 2),



        relation_growth_rate=round(relation_growth_rate, 2),



        avg_confidence=round(avg_confidence, 4),



        high_confidence_ratio=round(high_confidence_ratio, 4),



        low_confidence_count=low_confidence_count,



        avg_connections=round(avg_connections, 2),



        max_connections=max_connections,



        hub_entities=hub_entities,



        kpis=kpis,



        trending_entities=trending,



        anomaly_alerts=anomaly_alerts,



        entity_time_series=entity_time_series,



        relation_time_series=relation_time_series,



        time_range=req.time_range,



        generated_at=datetime.now(timezone.utc).isoformat(),



    )











@router.post("/analytics/trends", response_model=TrendAnalysisResponse)



async def get_trend_analysis(req: TrendAnalysisRequest) -> TrendAnalysisResponse:



    """Get trend analysis for specified metric.







    Args:



        metric: entities, relations, connections, confidence



        time_range: 7d, 30d, 90d, all



        granularity: hourly, daily, weekly



    """



    from datetime import datetime, timezone







    time_range_seconds = _parse_time_range(req.time_range)



    cutoff = time.time() - time_range_seconds







    # Filter history by time range



    filtered = []



    for snapshot in _analytics_history:



        ts_str = snapshot["timestamp"]



        try:



            ts = datetime.fromisoformat(ts_str.replace("Z", "+00:00")).timestamp()



            if ts >= cutoff:



                filtered.append(snapshot)



        except Exception:



            continue







    # Get current and previous values



    if filtered:



        current_value = filtered[-1].get(req.metric, 0) if filtered else 0



        previous_value = filtered[0].get(req.metric, 0) if len(filtered) > 1 else current_value



    else:



        # Fallback to current state



        if req.metric == "entities":



            current_value = len(_entities)



            previous_value = current_value



        elif req.metric == "relations":



            current_value = len(_relations)



            previous_value = current_value



        elif req.metric == "confidence":



            current_value = sum(e.get("confidence", 0.0) for e in _entities.values()) / len(_entities) if _entities else 0



            previous_value = current_value



        else:



            current_value = 0



            previous_value = 0







    change_pct = ((current_value - previous_value) / previous_value * 100) if previous_value > 0 else 0.0



    trend = "increasing" if change_pct > 1 else "decreasing" if change_pct < -1 else "stable"







    # Build data points



    data_points = []



    step = max(1, len(filtered) // 20)



    for i, snapshot in enumerate(filtered[::step]):



        data_points.append(TimeSeriesPoint(



            timestamp=snapshot["timestamp"][:16],



            value=float(snapshot.get(req.metric, 0)),



        ))







    return TrendAnalysisResponse(



        metric=req.metric,



        time_range=req.time_range,



        granularity=req.granularity,



        current_value=current_value,



        previous_value=previous_value,



        change_pct=round(change_pct, 2),



        trend=trend,



        data_points=data_points,



    )











@router.post("/analytics/anomalies", response_model=AnomalyDetectionResponse)



async def detect_anomalies(req: AnomalyDetectionRequest) -> AnomalyDetectionResponse:



    """Detect anomalies in the knowledge graph.







    Checks for:



    - spikes: Unexpected large increase in entities/relations



    - drops: Unexpected decrease



    - isolation: High ratio of isolated entities



    - density: Abnormal graph density







    Args:



        sensitivity: low, medium, high (affects threshold)



        check_types: List of anomaly types to check



    """



    from datetime import datetime, timezone







    sensitivity_multiplier = {"low": 2.0, "medium": 1.5, "high": 1.0}



    multiplier = sensitivity_multiplier.get(req.sensitivity, 1.5)







    anomalies = []



    severity_counts = {"low": 0, "medium": 0, "high": 0, "critical": 0}







    # Get historical averages



    if len(_analytics_history) >= 2:



        recent = _analytics_history[-5:] if len(_analytics_history) >= 5 else _analytics_history



        avg_entities = sum(s["entity_count"] for s in recent) / len(recent)



        avg_relations = sum(s["relation_count"] for s in recent) / len(recent)







        current_entities = len(_entities)



        current_relations = len(_relations)







        # Check for spikes



        if "spikes" in req.check_types:



            if current_entities > avg_entities * (1 + 0.3 * multiplier):



                severity = "critical" if current_entities > avg_entities * 2 else "high" if current_entities > avg_entities * 1.5 else "medium"



                anomalies.append(AnomalyAlert(



                    id=str(uuid.uuid4())[:8],



                    severity=severity,



                    type="spike",



                    message=f"Entity count spike: {current_entities} vs avg {round(avg_entities, 1)}",



                    affected_entity=None,



                    detected_at=datetime.now(timezone.utc).isoformat(),



                ))



                severity_counts[severity] += 1







            if current_relations > avg_relations * (1 + 0.3 * multiplier):



                severity = "critical" if current_relations > avg_relations * 2 else "high" if current_relations > avg_relations * 1.5 else "medium"



                anomalies.append(AnomalyAlert(



                    id=str(uuid.uuid4())[:8],



                    severity=severity,



                    type="spike",



                    message=f"Relation count spike: {current_relations} vs avg {round(avg_relations, 1)}",



                    affected_entity=None,



                    detected_at=datetime.now(timezone.utc).isoformat(),



                ))



                severity_counts[severity] += 1







    # Check for isolation



    if "isolation" in req.check_types:



        n = len(_entities)



        if n > 0:



            connection_counts = {}



            for relation in _relations.values():



                source = relation.get("sourceId", "")



                target = relation.get("targetId", "")



                if source:



                    connection_counts[source] = connection_counts.get(source, 0) + 1



                if target:



                    connection_counts[target] = connection_counts.get(target, 0) + 1







            isolated = len(set(_entities.keys()) - set(connection_counts.keys()))



            isolation_ratio = isolated / n







            if isolation_ratio > 0.3 * multiplier:



                severity = "critical" if isolation_ratio > 0.6 else "high" if isolation_ratio > 0.4 else "medium" if isolation_ratio > 0.3 else "low"



                anomalies.append(AnomalyAlert(



                    id=str(uuid.uuid4())[:8],



                    severity=severity,



                    type="isolation",



                    message=f"High isolation: {isolated} entities ({round(isolation_ratio * 100, 1)}%) have no connections",



                    affected_entity=None,



                    detected_at=datetime.now(timezone.utc).isoformat(),



                ))



                severity_counts[severity] += 1







    # Check for density anomalies



    if "density" in req.check_types:



        n = len(_entities)



        density = len(_relations) / (n * (n - 1)) if n > 1 else 0.0



        if density > 0.8:



            anomalies.append(AnomalyAlert(



                id=str(uuid.uuid4())[:8],



                severity="critical",



                type="density",



                message=f"Very high graph density: {round(density * 100, 1)}%",



                affected_entity=None,



                detected_at=datetime.now(timezone.utc).isoformat(),



            ))



            severity_counts["critical"] += 1







    return AnomalyDetectionResponse(



        detected_at=datetime.now(timezone.utc).isoformat(),



        anomalies=anomalies,



        total_checked=len(req.check_types) * 2,  # entities + relations



        anomaly_count=len(anomalies),



        severity_distribution=severity_counts,



    )











