@router.get("/entities/{entity_id}/stats", response_model=EntityStatsResponse)



async def get_entity_stats(entity_id: str) -> EntityStatsResponse:



    """Get detailed statistics for a specific entity."""



    if entity_id not in _entities:



        from fastapi import HTTPException



        raise HTTPException(status_code=404, detail="Entity not found")







    entity = _entities[entity_id]







    # Find connections



    connections_in = 0



    connections_out = 0



    related = []







    for relation in _relations.values():



        source = relation.get("sourceId", "")



        target = relation.get("targetId", "")







        if source == entity_id:



            connections_out += 1



            related.append({



                "id": target,



                "type": relation.get("type", "unknown"),



                "direction": "outgoing",



            })



        elif target == entity_id:



            connections_in += 1



            related.append({



                "id": source,



                "type": relation.get("type", "unknown"),



                "direction": "incoming",



            })







    return EntityStatsResponse(



        entity_id=entity_id,



        name=entity.get("name", entity_id),



        connections_in=connections_in,



        connections_out=connections_out,



        total_connections=connections_in + connections_out,



        related_entities=related,



    )











