# ── Graph Similarity Search ───────────────────────────────







import math











class SimilaritySearchRequest(BaseModel):



    """Request for similarity search."""



    entity_id: str = Field(description="Entity to find similar entities for")



    limit: int = Field(default=10, ge=1, le=50, description="Max results to return")



    use_neighbors: bool = Field(default=True, description="Include neighbor features")











class SimilarityResult(BaseModel):



    """Similar entity result."""



    entity_id: str



    name: str



    similarity_score: float



    matching_types: int



    matching_domains: int



    shared_relations: int











class GraphSimilarityResponse(BaseModel):



    """Response for similarity search."""



    query_entity: str



    total_results: int



    results: list[dict]











def _get_entity_features(entity_id: str, include_neighbors: bool = True) -> dict:



    """Extract feature vector for an entity."""



    if entity_id not in _entities:



        return {}







    entity = _entities[entity_id]



    features = {



        "type": entity.get("type", ""),



        "domain": entity.get("domain", ""),



        "tags": set(entity.get("tags", [])),



    }







    if include_neighbors:



        # Get neighbor entity IDs



        neighbors = set()



        for relation in _relations.values():



            if relation.get("sourceId") == entity_id:



                neighbors.add(relation.get("targetId", ""))



            elif relation.get("targetId") == entity_id:



                neighbors.add(relation.get("sourceId", ""))



        features["neighbors"] = neighbors







        # Get neighbor types



        neighbor_types = set()



        for nid in neighbors:



            neighbor = _entities.get(nid, {})



            if neighbor.get("type"):



                neighbor_types.add(neighbor.get("type"))



        features["neighbor_types"] = neighbor_types







        # Get relation types connected to this entity



        rel_types = set()



        for relation in _relations.values():



            if relation.get("sourceId") == entity_id or relation.get("targetId") == entity_id:



                rel_types.add(relation.get("type", ""))



        features["relation_types"] = rel_types







    return features











def _calculate_similarity(features1: dict, features2: dict) -> float:



    """Calculate similarity score between two feature vectors."""



    if not features1 or not features2:



        return 0.0







    score = 0.0



    max_score = 0.0







    # Type match (0.3)



    if features1.get("type") == features2.get("type"):



        score += 0.3







    # Domain match (0.2)



    if features1.get("domain") == features2.get("domain"):



        score += 0.2







    # Tags overlap (0.2)



    tags1 = features1.get("tags", set())



    tags2 = features2.get("tags", set())



    if tags1 and tags2:



        overlap = len(tags1 & tags2)



        union = len(tags1 | tags2)



        score += (overlap / union) * 0.2 if union > 0 else 0.0







    # Neighbor type overlap (0.2)



    ntypes1 = features1.get("neighbor_types", set())



    ntypes2 = features2.get("neighbor_types", set())



    if ntypes1 and ntypes2:



        overlap = len(ntypes1 & ntypes2)



        union = len(ntypes1 | ntypes2)



        score += (overlap / union) * 0.2 if union > 0 else 0.0







    return min(score, 1.0)











@router.post("/entities/similar", response_model=GraphSimilarityResponse)



async def find_similar_entities(req: SimilaritySearchRequest) -> GraphSimilarityResponse:



    """Find entities similar to the given entity.







    Similarity based on:



    - Entity type (0.3)



    - Domain (0.2)



    - Tags overlap (0.2)



    - Neighbor types overlap (0.2)



    """



    if req.entity_id not in _entities:



        from fastapi import HTTPException



        raise HTTPException(status_code=404, detail="Entity not found")







    query_features = _get_entity_features(req.entity_id, req.use_neighbors)







    if not query_features:



        return GraphSimilarityResponse(



            query_entity=req.entity_id,



            total_results=0,



            results=[],



        )







    # Calculate similarity with all other entities



    similarities = []



    for eid, entity in _entities.items():



        if eid == req.entity_id:



            continue







        features = _get_entity_features(eid, req.use_neighbors)



        score = _calculate_similarity(query_features, features)







        if score > 0:



            # Count matching types and domains



            matching_types = 1 if entity.get("type") == query_features.get("type") else 0



            matching_domains = 1 if entity.get("domain") == query_features.get("domain") else 0







            # Count shared relations



            query_neighbors = query_features.get("neighbors", set())



            target_neighbors = features.get("neighbors", set())



            shared = len(query_neighbors & target_neighbors)







            similarities.append({



                "entity_id": eid,



                "name": entity.get("name", eid),



                "similarity_score": round(score, 2),



                "matching_types": matching_types,



                "matching_domains": matching_domains,



                "shared_relations": shared,



            })







    # Sort by similarity score descending



    similarities.sort(key=lambda x: x["similarity_score"], reverse=True)







    # Return top results



    results = similarities[:req.limit]



    total = len(similarities)







    return GraphSimilarityResponse(



        query_entity=req.entity_id,



        total_results=total,



        results=results,



    )











class EntityClusterRequest(BaseModel):



    """Request for entity clustering."""



    min_similarity: float = Field(default=0.3, ge=0.0, le=1.0, description="Minimum similarity to cluster")











class EntityCluster(BaseModel):



    """Entity cluster."""



    cluster_id: int



    entities: list[dict]



    shared_type: str | None



    shared_domain: str | None



    size: int











class GraphClusteringResponse(BaseModel):



    """Response for entity clustering."""



    total_clusters: int



    total_entities: int



    clusters: list[dict]











@router.post("/entities/cluster", response_model=GraphClusteringResponse)



async def cluster_entities(req: EntityClusterRequest) -> GraphClusteringResponse:



    """Cluster entities by similarity.







    Groups entities that share type/domain and have similar neighbors.



    """



    # Simple clustering: group by type, then by domain



    type_groups: dict[str, list[str]] = {}



    domain_groups: dict[str, list[str]] = {}







    for eid, entity in _entities.items():



        etype = entity.get("type", "unknown")



        domain = entity.get("domain", "unknown")







        if etype not in type_groups:



            type_groups[etype] = []



        type_groups[etype].append(eid)







        if domain not in domain_groups:



            domain_groups[domain] = []



        domain_groups[domain].append(eid)







    # Build clusters



    clusters = []



    cluster_id = 0







    # First cluster by type



    for etype, eids in type_groups.items():



        if len(eids) < 2:



            continue







        members = []



        for eid in eids:



            entity = _entities[eid]



            members.append({



                "id": eid,



                "name": entity.get("name", eid),



                "domain": entity.get("domain", ""),



            })







        clusters.append({



            "cluster_id": cluster_id,



            "entities": members,



            "shared_type": etype,



            "shared_domain": None,



            "size": len(members),



        })



        cluster_id += 1







    # Then cluster by domain within same types



    for domain, eids in domain_groups.items():



        if len(eids) < 2:



            continue







        # Check if already covered by type cluster



        covered = False



        for cluster in clusters:



            if cluster.get("shared_domain") == domain:



                covered = True



                break







        if not covered:



            members = []



            for eid in eids:



                entity = _entities[eid]



                members.append({



                    "id": eid,



                    "name": entity.get("name", eid),



                    "type": entity.get("type", ""),



                })







            clusters.append({



                "cluster_id": cluster_id,



                "entities": members,



                "shared_type": None,



                "shared_domain": domain,



                "size": len(members),



            })



            cluster_id += 1







    return GraphClusteringResponse(



        total_clusters=len(clusters),



        total_entities=len(_entities),



        clusters=clusters,



    )











# ========== Graph Versioning and History ==========







class VersionMetadata(BaseModel):



    version_id: str



    timestamp: str



    entity_count: int



    relation_count: int



    description: str











class VersionCreateRequest(BaseModel):



    description: str = ""











class VersionListResponse(BaseModel):



    versions: list[VersionMetadata]



    total: int











class VersionDetailResponse(BaseModel):



    version_id: str



    timestamp: str



    description: str



    entity_count: int



    relation_count: int



    entities: list[dict]



    relations: list[dict]











# In-memory version storage



_versions: dict[str, dict] = {}











@router.post("/versions", response_model=VersionMetadata)



async def create_version(request: VersionCreateRequest):



    """Create a named version snapshot of the entire graph."""



    global _versions







    version_id = f"v{int(time.time() * 1000)}"







    version_data = {



        "version_id": version_id,



        "timestamp": datetime.now(timezone.utc).isoformat(),



        "description": request.description,



        "entity_count": len(_entities),



        "relation_count": len(_relations),



        "entities": dict(_entities),



        "relations": dict(_relations),



    }







    async with _lock:



        _versions[version_id] = version_data







    return VersionMetadata(



        version_id=version_id,



        timestamp=version_data["timestamp"],



        entity_count=len(_entities),



        relation_count=len(_relations),



        description=request.description,



    )











@router.get("/versions", response_model=VersionListResponse)



async def list_versions(limit: int = Query(20, ge=1, le=100)):



    """List all graph versions."""



    versions = sorted(



        [



            VersionMetadata(



                version_id=v["version_id"],



                timestamp=v["timestamp"],



                entity_count=v["entity_count"],



                relation_count=v["relation_count"],



                description=v["description"],



            )



            for v in _versions.values()



        ],



        key=lambda x: x.timestamp,



        reverse=True,



    )[:limit]







    return VersionListResponse(versions=versions, total=len(versions))











@router.get("/versions/{version_id}", response_model=VersionDetailResponse)



async def get_version(version_id: str):



    """Get detailed version data."""



    if version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    version = _versions[version_id]







    return VersionDetailResponse(



        version_id=version["version_id"],



        timestamp=version["timestamp"],



        description=version["description"],



        entity_count=version["entity_count"],



        relation_count=version["relation_count"],



        entities=list(version["entities"].values()),



        relations=list(version["relations"].values()),



    )











@router.delete("/versions/{version_id}")



async def delete_version(version_id: str):



    """Delete a version."""



    if version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    async with _lock:



        del _versions[version_id]







    return {"status": "deleted", "version_id": version_id}











@router.post("/versions/{version_id}/restore", response_model=dict)



async def restore_version(version_id: str):



    """Restore graph from a version snapshot."""



    if version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    version = _versions[version_id]







    async with _lock:



        _entities.clear()



        _entities.update(version["entities"])



        _relations.clear()



        _relations.update(version["relations"])







    return {



        "status": "restored",



        "version_id": version_id,



        "entity_count": len(_entities),



        "relation_count": len(_relations),



    }











@router.get("/versions/{version_id}/compare/{other_version_id}", response_model=dict)



async def compare_versions(version_id: str, other_version_id: str):



    """Compare two versions."""



    if version_id not in _versions or other_version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    v1 = _versions[version_id]



    v2 = _versions[other_version_id]







    entity_ids_1 = set(v1["entities"].keys())



    entity_ids_2 = set(v2["entities"].keys())







    added_entities = entity_ids_2 - entity_ids_1



    removed_entities = entity_ids_1 - entity_ids_2



    common_entities = entity_ids_1 & entity_ids_2







    relation_ids_1 = set(v1["relations"].keys())



    relation_ids_2 = set(v2["relations"].keys())







    added_relations = relation_ids_2 - relation_ids_1



    removed_relations = relation_ids_1 - relation_ids_2



    common_relations = relation_ids_1 & relation_ids_2







    return {



        "version1": {"id": version_id, "timestamp": v1["timestamp"]},



        "version2": {"id": other_version_id, "timestamp": v2["timestamp"]},



        "entity_changes": {



            "added": len(added_entities),



            "removed": len(removed_entities),



            "common": len(common_entities),



        },



        "relation_changes": {



            "added": len(added_relations),



            "removed": len(removed_relations),



            "common": len(common_relations),



        },



    }











# ========== Graph Merge ==========







class MergeRequest(BaseModel):



    entities: list[dict] = []



    relations: list[dict] = []



    conflict_strategy: str = Field(default="newer", pattern="^(newer|older|skip|replace)$")











class MergeConflict(BaseModel):



    entity_id: str



    existing: dict



    incoming: dict



    reason: str











class MergeResponse(BaseModel):



    merged_entities: int



    merged_relations: int



    conflicts: list[MergeConflict]



    resolved: int











@router.post("/merge", response_model=MergeResponse)



async def merge_graph(request: MergeRequest):



    """Merge entities and relations from external source."""



    merged_entities = 0



    merged_relations = 0



    conflicts = []







    async with _lock:



        # Merge entities



        for entity in request.entities:



            entity_id = entity.get("id")



            if not entity_id:



                continue







            if entity_id in _entities:



                # Conflict detected



                existing = _entities[entity_id]



                incoming_ts = entity.get("updated_at", entity.get("created_at", ""))



                existing_ts = existing.get("updated_at", existing.get("created_at", ""))







                conflict = MergeConflict(



                    entity_id=entity_id,



                    existing=existing,



                    incoming=entity,



                    reason="entity_already_exists",



                )



                conflicts.append(conflict)







                # Resolve based on strategy



                if request.conflict_strategy == "replace":



                    _entities[entity_id] = entity



                    merged_entities += 1



                elif request.conflict_strategy == "newer" and incoming_ts > existing_ts:



                    _entities[entity_id] = entity



                    merged_entities += 1



                # skip or older: keep existing



            else:



                _entities[entity_id] = entity



                merged_entities += 1







        # Merge relations



        for relation in request.relations:



            relation_id = relation.get("id")



            if not relation_id:



                continue







            if relation_id in _relations:



                # Skip existing relations on conflict



                pass



            else:



                _relations[relation_id] = relation



                merged_relations += 1







    return MergeResponse(



        merged_entities=merged_entities,



        merged_relations=merged_relations,



        conflicts=conflicts,



        resolved=len(conflicts),



    )











@router.post("/merge/auto", response_model=dict)



async def auto_merge_with_conflict_detection(request: MergeRequest):



    """Auto-merge with intelligent conflict resolution."""



    results = await merge_graph(request)







    auto_resolved = []



    for conflict in results.conflicts:



        entity_id = conflict.entity_id







        # Simple resolution: use entity with more fields as newer



        incoming_fields = len(conflict.incoming)



        existing_fields = len(conflict.existing)







        if incoming_fields > existing_fields:



            auto_resolved.append({



                "entity_id": entity_id,



                "resolution": "incoming_larger",



            })







    return {



        "total_merged": results.merged_entities + results.merged_relations,



        "auto_resolved": len(auto_resolved),



        "manual_resolution_needed": len(results.conflicts) - len(auto_resolved),



        "conflicts": [



            {



                "entity_id": c.entity_id,



                "reason": c.reason,



            }



            for c in results.conflicts



        ],



    }











# ========== Advanced Path Finding ==========







class PathFindRequest(BaseModel):



    source_id: str



    target_id: str



    max_length: int = Field(default=5, ge=1, le=10)



    algorithm: str = Field(default="shortest", pattern="^(shortest|all|bfs)$")











class PathResponse(BaseModel):



    paths: list[list[dict]]



    total_paths: int



    source_id: str



    target_id: str











def build_adjacency():



    """Build adjacency list for path finding."""



    adj = {}



    for eid in _entities:



        adj[eid] = []







    for rid, rel in _relations.items():



        source = rel.get("source_id")



        target = rel.get("target_id")



        if source and target and source in adj and target in adj:



            adj[source].append(target)







    return adj











@router.post("/paths/advanced", response_model=PathResponse)



async def find_advanced_paths(request: PathFindRequest):



    """Find paths between two entities with multiple algorithms."""



    source = request.source_id



    target = request.target_id



    max_len = request.max_length







    if source not in _entities or target not in _entities:



        raise HTTPException(status_code=404, detail="Source or target entity not found")







    adj = build_adjacency()







    paths = []







    if request.algorithm == "shortest":



        # BFS for shortest path



        from collections import deque







        queue = deque([(source, [source])])



        visited = {source}







        while queue:



            current, path = queue.popleft()







            if current == target:



                paths.append(path)



                break







            if len(path) >= max_len:



                continue







            for neighbor in adj.get(current, []):



                if neighbor not in visited or len(path) + 1 < max_len:



                    visited.add(neighbor)



                    queue.append((neighbor, path + [neighbor]))







    elif request.algorithm == "all":



        # DFS for all simple paths



        def dfs(node, path):



            if node == target:



                paths.append(path[:])



                return







            if len(path) >= max_len:



                return







            for neighbor in adj.get(node, []):



                if neighbor not in path:



                    path.append(neighbor)



                    dfs(neighbor, path)



                    path.pop()







        dfs(source, [source])







    elif request.algorithm == "bfs":



        # BFS for all paths at minimum length



        from collections import deque







        levels = {source: 0}



        queue = deque([source])



        found_paths = []







        while queue:



            current = queue.popleft()



            current_level = levels[current]







            if current_level >= max_len:



                continue







            for neighbor in adj.get(current, []):



                if neighbor not in levels:



                    levels[neighbor] = current_level + 1



                    queue.append(neighbor)







                if neighbor == target:



                    # Reconstruct path



                    path = [neighbor]



                    rev_queue = deque([neighbor])



                    while rev_queue:



                        n = rev_queue.popleft()



                        for rid, rel in _relations.items():



                            if rel.get("target_id") == n and rel.get("source_id") in levels:



                                if levels[rel.get("source_id")] == levels.get(n, 0) - 1:



                                    path.insert(0, rel.get("source_id"))



                                    rev_queue.append(rel.get("source_id"))



                                    break



                    if path not in found_paths and len(path) <= max_len:



                        found_paths.append(path)







        paths = found_paths







    # Format paths with entity/relation details



    formatted_paths = []



    for path in paths:



        path_details = []



        for i, eid in enumerate(path):



            entity = _entities.get(eid, {})



            step = {



                "entity_id": eid,



                "name": entity.get("name", eid),



                "type": entity.get("type", ""),



            }







            # Add relation if not last



            if i < len(path) - 1:



                next_eid = path[i + 1]



                for rid, rel in _relations.items():



                    if rel.get("source_id") == eid and rel.get("target_id") == next_eid:



                        step["relation_id"] = rid



                        step["relation_type"] = rel.get("type", "")



                        break







            path_details.append(step)







        formatted_paths.append(path_details)







    return PathResponse(



        paths=formatted_paths,



        total_paths=len(formatted_paths),



        source_id=source,



        target_id=target,



    )











class WeightedPathRequest(BaseModel):



    source_id: str



    target_id: str



    max_length: int = Field(default=5, ge=1, le=10)



    weight_by: str = Field(default="confidence", pattern="^(confidence|strength|type)$")











class WeightedPathResponse(BaseModel):



    best_path: list[dict]



    path_weight: float



    alternative_paths: list[dict]



    source_id: str



    target_id: str











@router.post("/paths/weighted", response_model=WeightedPathResponse)



async def find_weighted_paths(request: WeightedPathRequest):



    """Find weighted shortest path between entities."""



    source = request.source_id



    target = request.target_id







    if source not in _entities or target not in _entities:



        raise HTTPException(status_code=404, detail="Source or target entity not found")







    adj = build_adjacency()







    # Calculate edge weights



    def get_weight(from_id, to_id):



        for rid, rel in _relations.items():



            if rel.get("source_id") == from_id and rel.get("target_id") == to_id:



                if request.weight_by == "confidence":



                    return 1.0 - (rel.get("confidence", 0.5))



                elif request.weight_by == "strength":



                    strength = rel.get("strength", 0.5)



                    return 1.0 - strength



                else:



                    return 1.0  # Equal weight by type



        return 1.0







    # Dijkstra's algorithm



    import heapq







    distances = {source: 0.0}



    predecessors = {source: None}



    visited = set()



    heap = [(0.0, source)]







    while heap:



        dist, current = heapq.heappop(heap)







        if current in visited:



            continue



        visited.add(current)







        if current == target:



            break







        for neighbor in adj.get(current, []):



            if neighbor not in visited:



                weight = get_weight(current, neighbor)



                new_dist = dist + weight







                if neighbor not in distances or new_dist < distances[neighbor]:



                    distances[neighbor] = new_dist



                    predecessors[neighbor] = current



                    heapq.heappush(heap, (new_dist, neighbor))







    # Reconstruct path



    if target not in predecessors:



        return WeightedPathResponse(



            best_path=[],



            path_weight=float("inf"),



            alternative_paths=[],



            source_id=source,



            target_id=target,



        )







    path = []



    current = target



    while current is not None:



        entity = _entities.get(current, {})



        path.append({



            "entity_id": current,



            "name": entity.get("name", current),



            "type": entity.get("type", ""),



        })



        current = predecessors.get(current)







    path.reverse()







    return WeightedPathResponse(



        best_path=path,



        path_weight=distances.get(target, float("inf")),



        alternative_paths=[],



        source_id=source,



        target_id=target,



    )











# ========== Graph Pattern Matching ==========







class PatternRequest(BaseModel):



    pattern_entity_type: str = ""



    pattern_relation_type: str = ""



    min_entities: int = Field(default=2, ge=1)



    max_entities: int = Field(default=10, ge=1)











class PatternMatch(BaseModel):



    entity_id: str



    name: str



    matched_by: str











class PatternResponse(BaseModel):



    pattern: str



    matches: list[dict]



    total_matches: int











@router.post("/patterns/match", response_model=PatternResponse)



async def match_patterns(request: PatternRequest):



    """Find entities matching a pattern."""



    matches = []







    for eid, entity in _entities.items():



        # Check entity type



        if request.pattern_entity_type and entity.get("type") != request.pattern_entity_type:



            continue







        # Count matching relations



        matching_relations = 0



        for rid, rel in _relations.items():



            if request.pattern_relation_type:



                if rel.get("type") != request.pattern_relation_type:



                    continue



            if rel.get("source_id") == eid or rel.get("target_id") == eid:



                matching_relations += 1







        if matching_relations >= request.min_entities:



            matches.append({



                "entity_id": eid,



                "name": entity.get("name", eid),



                "type": entity.get("type", ""),



                "matching_relations": matching_relations,



            })







    # Sort by matching relations count



    matches.sort(key=lambda x: x.get("matching_relations", 0), reverse=True)



    matches = matches[: request.max_entities]







    pattern_desc = f"type={request.pattern_entity_type}, rel={request.pattern_relation_type}"







    return PatternResponse(



        pattern=pattern_desc,



        matches=matches,



        total_matches=len(matches),



    )











# ========== Graph Export Formats ==========







class ExportMarkdownResponse(BaseModel):



    content: str



    format: str = "markdown"



    entity_count: int



    relation_count: int











@router.post("/export/markdown", response_model=ExportMarkdownResponse)



async def export_markdown(



    include_relations: bool = True,



    include_descriptions: bool = True,



):



    """Export graph as Markdown document."""



    lines = [



        f"# Knowledge Graph Export",



        f"",



        f"Generated: {datetime.now(timezone.utc).isoformat()}",



        f"",



        f"## Statistics",



        f"",



        f"- Total Entities: {len(_entities)}",



        f"- Total Relations: {len(_relations)}",



        f"",



    ]







    # Group by type



    by_type = {}



    for eid, entity in _entities.items():



        etype = entity.get("type", "unknown")



        if etype not in by_type:



            by_type[etype] = []



        by_type[etype].append(entity)







    for etype, entities in sorted(by_type.items()):



        lines.append(f"## {etype}")



        lines.append("")







        for entity in entities:



            name = entity.get("name", entity.get("id", ""))



            lines.append(f"### {name}")



            lines.append("")







            if include_descriptions and entity.get("description"):



                lines.append(f"{entity['description']}")



                lines.append("")







            if include_relations:



                for rid, rel in _relations.items():



                    if rel.get("source_id") == entity.get("id"):



                        target = _entities.get(rel.get("target_id", ""))



                        if target:



                            lines.append(



                                f"- {rel.get('type', 'related')} → [{target.get('name', '')}]"



                            )



                lines.append("")







    content = "\n".join(lines)







    return ExportMarkdownResponse(



        content=content,



        format="markdown",



        entity_count=len(_entities),



        relation_count=len(_relations),



    )











