def _execute_workflow_action(action: str, params: dict[str, Any], context: dict[str, Any]) -> dict[str, Any]:



    """Execute a single workflow action."""



    try:



        if action == "extract":



            content = params.get("content", "")



            doc_id = params.get("doc_id", f"doc_{datetime.now(timezone.utc).timestamp()}")



            # Use existing extract logic



            entities_found = []



            relations_found = []



            # Simple extraction based on content



            lines = content.split("\n") if content else []



            for i, line in enumerate(lines):



                if line.strip() and len(line.strip()) > 2:



                    entities_found.append({



                        "id": f"extracted_e{len(entities_found)}",



                        "name": line.strip()[:50],



                        "type": "text",



                        "source": "workflow_extraction",



                    })



            return {"success": True, "entities": entities_found, "relations": relations_found, "count": len(entities_found)}







        elif action == "enrich":



            entity_id = params.get("entity_id", "")



            if entity_id and entity_id in _entities:



                entity = _entities[entity_id]



                # Simulate enrichment



                entity["enriched"] = True



                entity["enrichment_timestamp"] = datetime.now(timezone.utc).isoformat()



                _entities[entity_id] = entity



                return {"success": True, "entity_id": entity_id}



            return {"success": False, "error": "Entity not found"}







        elif action == "validate":



            # Run validation



            issues = []



            for eid, entity in _entities.items():



                if not entity.get("name"):



                    issues.append({"entity_id": eid, "issue": "missing_name"})



                if not entity.get("type"):



                    issues.append({"entity_id": eid, "issue": "missing_type"})



            return {"success": True, "issues": issues, "total_checked": len(_entities)}







        elif action == "anomalies":



            # Find anomalies



            anomalies = []



            # Check for isolated nodes



            for eid in _entities:



                has_relations = any(



                    r.get("source_id") == eid or r.get("target_id") == eid



                    for r in _relations.values()



                )



                if not has_relations:



                    anomalies.append({"entity_id": eid, "type": "isolated_node"})



            return {"success": True, "anomalies": anomalies, "count": len(anomalies)}







        elif action == "stats":



            return {



                "success": True,



                "entity_count": len(_entities),



                "relation_count": len(_relations),



                "types": list(set(e.get("type", "unknown") for e in _entities.values())),



            }







        elif action == "export_viz":



            return {"success": True, "format": "viz", "url": "/export/viz"}







        elif action == "export_json":



            return {



                "success": True,



                "format": "json",



                "entities": len(_entities),



                "relations": len(_relations),



            }







        elif action == "similarity":



            entity_id = params.get("entity_id", "")



            if entity_id in _entities:



                # Find similar entities



                target = _entities[entity_id]



                similar = []



                for eid, entity in _entities.items():



                    if eid != entity_id:



                        similarity = 0.5  # Simplified



                        if target.get("type") == entity.get("type"):



                            similarity = 0.8



                        if similarity > 0.5:



                            similar.append({"entity_id": eid, "similarity": similarity})



                return {"success": True, "similar": similar[:5]}



            return {"success": False, "error": "Entity not found"}







        elif action == "cluster":



            # Simple clustering



            by_type = {}



            for eid, entity in _entities.items():



                etype = entity.get("type", "unknown")



                if etype not in by_type:



                    by_type[etype] = []



                by_type[etype].append(eid)



            return {"success": True, "clusters": by_type}







        elif action == "create_entity":



            entity_data = params.get("entity_data", {})



            entity_id = entity_data.get("id", f"wf_entity_{datetime.now(timezone.utc).timestamp()}")



            entity_data["id"] = entity_id



            _entities[entity_id] = entity_data



            return {"success": True, "entity_id": entity_id}







        elif action == "create_relation":



            rel_data = params.get("relation_data", {})



            rel_id = rel_data.get("id", f"wf_relation_{datetime.now(timezone.utc).timestamp()}")



            rel_data["id"] = rel_id



            _relations[rel_id] = rel_data



            return {"success": True, "relation_id": rel_id}







        else:



            return {"success": False, "error": f"Unknown action: {action}"}







    except Exception as e:



        return {"success": False, "error": str(e)}











