    # Use template if specified



    if use_template and use_template in WORKFLOW_TEMPLATES:



        template = WORKFLOW_TEMPLATES[use_template]



        workflow.name = template["name"]



        workflow.description = template["description"]



        workflow.version = template["version"]



        workflow.steps = [WorkflowStep(**s) for s in template["steps"]]







    workflow_id = f"wf_{workflow.name.lower().replace(' ', '_')}_{datetime.now(timezone.utc).timestamp()}"







    workflow_data = {



        "id": workflow_id,



        "name": workflow.name,



        "description": workflow.description,



        "version": workflow.version,



        "steps": [s.model_dump() for s in workflow.steps],



        "on_error": workflow.on_error,



        "tags": workflow.tags,



        "created_at": datetime.now(timezone.utc).isoformat(),



    }







    _workflows[workflow_id] = workflow_data







    return WorkflowResponse(



        workflow_id=workflow_id,



        name=workflow.name,



        version=workflow.version,



        step_count=len(workflow.steps),



        created_at=workflow_data["created_at"],



    )











