@router.post("/workflows/{workflow_id}/execute", response_model=WorkflowExecutionResponse)



async def execute_workflow(



    workflow_id: str,



    request: WorkflowExecutionRequest,



):



    """Execute a workflow."""



    global _workflow_execution_counter, _workflow_executions







    if workflow_id not in _workflows:



        raise HTTPException(status_code=404, detail="Workflow not found")







    workflow = _workflows[workflow_id]



    _workflow_execution_counter += 1



    execution_id = f"exec_{_workflow_execution_counter}_{datetime.now(timezone.utc).timestamp()}"







    execution = {



        "id": execution_id,



        "workflow_id": workflow_id,



        "status": "pending",



        "started_at": datetime.now(timezone.utc).isoformat(),



        "completed_at": None,



        "steps_completed": 0,



        "total_steps": len(workflow.get("steps", [])),



        "results": {},



        "error": None,



        "input_params": request.input_params,



    }







    _workflow_executions[execution_id] = execution







    # Execute synchronously



    context = {"input": request.input_params, "entities": {}, "relations": {}}



    steps = workflow.get("steps", [])







    for step in steps:



        step_result = _execute_workflow_action(



            step["action"],



            step.get("params", {}),



            context,



        )



        execution["results"][step["id"]] = step_result







        if not step_result.get("success", False):



            if step.get("on_failure") == "stop":



                execution["status"] = "failed"



                execution["error"] = step_result.get("error", "Step failed")



                break



            elif step.get("on_failure") == "continue":



                continue



        else:



            execution["steps_completed"] += 1



            # Update context



            context["entities"].update(step_result.get("entities", {}))



            context["relations"].update(step_result.get("relations", {}))







    if execution["status"] == "pending":



        execution["status"] = "completed"







    execution["completed_at"] = datetime.now(timezone.utc).isoformat()



    _workflow_executions[execution_id] = execution







    return WorkflowExecutionResponse(



        execution_id=execution_id,



        workflow_id=workflow_id,



        status=execution["status"],



        started_at=execution["started_at"],



        completed_at=execution["completed_at"],



        steps_completed=execution["steps_completed"],



        total_steps=execution["total_steps"],



        results=execution["results"],



        error=execution["error"],



    )











