@router.post("/workflows/executions/{execution_id}/cancel", response_model=dict)



async def cancel_workflow_execution(execution_id: str):



    """Cancel a running workflow execution."""



    if execution_id not in _workflow_executions:



        raise HTTPException(status_code=404, detail="Execution not found")







    execution = _workflow_executions[execution_id]



    if execution["status"] not in ["pending", "running"]:



        raise HTTPException(status_code=400, detail="Execution cannot be cancelled")







    execution["status"] = "cancelled"



    execution["completed_at"] = datetime.now(timezone.utc).isoformat()



    _workflow_executions[execution_id] = execution







    return {"success": True, "message": "Execution cancelled"}











# ========== Graph Triggers and Events ==========







# In-memory trigger storage



_triggers: dict[str, dict] = {}



_trigger_events: dict[str, list[dict]] = {}











class TriggerDefinition(BaseModel):



    """Trigger definition."""



    name: str



    event_type: str  # entity_created, entity_updated, entity_deleted, relation_created, relation_deleted



    entity_type: str | None = None



    condition: str | None = None  # SQL-like condition



    action: str  # webhook, enrich, tag, notify



    action_params: dict[str, Any] = {}



    enabled: bool = True











class TriggerResponse(BaseModel):



    """Trigger created response."""



    trigger_id: str



    name: str



    event_type: str



    action: str



    enabled: bool



    created_at: str











class TriggerListResponse(BaseModel):



    """List of triggers."""



    triggers: list[dict]



    total: int











class EventLogResponse(BaseModel):



    """Event log response."""



    events: list[dict]



    total: int











def _trigger_matches_condition(entity: dict, condition: str | None) -> bool:



    """Check if entity matches trigger condition."""



    if not condition:



        return True







    try:



        # Simple condition evaluation



        # Format: "field op value" e.g., "type == person"



        parts = condition.split()



        if len(parts) >= 3:



            field = parts[0]



            op = parts[1]



            value = " ".join(parts[2:]).strip("'\"")







            entity_value = str(entity.get(field, ""))



            if op == "==":



                return entity_value == value



            elif op == "!=":



                return entity_value != value



            elif op == "contains":



                return value in entity_value



            elif op == "startswith":



                return entity_value.startswith(value)



            elif op == "endswith":



                return entity_value.endswith(value)



        return True



    except:



        return False











def _execute_trigger_action(trigger: dict, event_data: dict) -> dict[str, Any]:



    """Execute trigger action."""



    action = trigger.get("action", "")



    action_params = trigger.get("action_params", {})







    try:



        if action == "tag":



            entity_id = event_data.get("entity_id")



            if entity_id and entity_id in _entities:



                tag = action_params.get("tag", "triggered")



                if "tags" not in _entities[entity_id]:



                    _entities[entity_id]["tags"] = []



                if tag not in _entities[entity_id]["tags"]:



                    _entities[entity_id]["tags"].append(tag)



                return {"success": True, "action": "tag", "entity_id": entity_id, "tag": tag}







        elif action == "enrich":



            entity_id = event_data.get("entity_id")



            if entity_id and entity_id in _entities:



                _entities[entity_id]["trigger_enriched"] = True



                _entities[entity_id]["trigger_timestamp"] = datetime.now(timezone.utc).isoformat()



                return {"success": True, "action": "enrich", "entity_id": entity_id}







        elif action == "notify":



            # Store notification



            notification = {



                "trigger_id": trigger.get("id"),



                "event_type": event_data.get("event_type"),



                "entity_id": event_data.get("entity_id"),



                "timestamp": datetime.now(timezone.utc).isoformat(),



            }



            if "notifications" not in _trigger_events:



                _trigger_events["notifications"] = []



            _trigger_events["notifications"].append(notification)



            return {"success": True, "action": "notify", "notification": notification}







        elif action == "webhook":



            # Just log the webhook call



            webhook_url = action_params.get("url", "")



            return {"success": True, "action": "webhook", "url": webhook_url, "event": event_data}







        return {"success": False, "error": f"Unknown action: {action}"}



    except Exception as e:



        return {"success": False, "error": str(e)}











def _trigger_event(event_type: str, event_data: dict):



    """Trigger events for matching triggers."""



    for trigger_id, trigger in _triggers.items():



        if not trigger.get("enabled", True):



            continue







        if trigger.get("event_type") != event_type:



            continue







        # Check entity type filter



        entity_type = event_data.get("entity_type")



        if trigger.get("entity_type") and entity_type:



            if trigger["entity_type"] != entity_type:



                continue







        # Check condition



        entity_id = event_data.get("entity_id")



        entity = _entities.get(entity_id, {}) if entity_id else {}



        if not _trigger_matches_condition(entity, trigger.get("condition")):



            continue







        # Execute action



        result = _execute_trigger_action(trigger, event_data)



        event_data["trigger_results"] = event_data.get("trigger_results", [])



        event_data["trigger_results"].append({



            "trigger_id": trigger_id,



            "result": result,



        })











