# Async Background Workflow Execution (v0.92)



# ========================================







# Background job storage



_background_jobs: dict[str, dict] = {}











class BackgroundJobRequest(BaseModel):



    """Request to run workflow in background."""



    workflow_id: str



    input_params: dict | None = None











class BackgroundJobResponse(BaseModel):



    """Response for background job."""



    job_id: str



    status: str  # queued, running, completed, failed, cancelled



    workflow_id: str



    execution_id: str | None



    created_at: str



    started_at: str | None



    completed_at: str | None



    result: dict | None



    error: str | None



    progress: float











class BackgroundJobListResponse(BaseModel):



    """List of background jobs."""



    jobs: list[BackgroundJobResponse]



    total: int











@router.post("/workflows/background/submit", response_model=BackgroundJobResponse)



async def submit_background_workflow(req: BackgroundJobRequest) -> BackgroundJobResponse:



    """Submit a workflow for background execution."""



    from datetime import datetime







    job_id = f"job_{_now_iso()}"



    now = _now_iso()







    # Create execution first



    execution_id = f"exec_{now}"







    job = {



        "job_id": job_id,



        "status": "queued",



        "workflow_id": req.workflow_id,



        "execution_id": execution_id,



        "input_params": req.input_params or {},



        "created_at": now,



        "started_at": None,



        "completed_at": None,



        "result": None,



        "error": None,



        "progress": 0.0,



    }







    _background_jobs[job_id] = job



    _workflow_executions[execution_id] = {



        "execution_id": execution_id,



        "workflow_id": req.workflow_id,



        "status": "queued",



        "input_params": req.input_params or {},



        "created_at": now,



        "started_at": None,



        "completed_at": None,



        "result": None,



        "steps_completed": [],



    }







    return BackgroundJobResponse(



        job_id=job_id,



        status=job["status"],



        workflow_id=req.workflow_id,



        execution_id=execution_id,



        created_at=now,



        started_at=None,



        completed_at=None,



        result=None,



        error=None,



        progress=0.0,



    )











@router.get("/workflows/background/{job_id}", response_model=BackgroundJobResponse)



async def get_background_job(job_id: str) -> BackgroundJobResponse:



    """Get status of a background job."""



    job = _background_jobs.get(job_id)



    if not job:



        raise HTTPException(status_code=404, detail="Job not found")







    return BackgroundJobResponse(**job)











@router.get("/workflows/background", response_model=BackgroundJobListResponse)



async def list_background_jobs(



    status: str | None = None,



    limit: int = 20,



    offset: int = 0,



) -> BackgroundJobListResponse:



    """List background jobs with optional status filter."""



    all_jobs = list(_background_jobs.values())







    if status:



        all_jobs = [j for j in all_jobs if j.get("status") == status]







    all_jobs.sort(key=lambda x: x.get("created_at", ""), reverse=True)







    total = len(all_jobs)



    jobs = all_jobs[offset:offset + limit]







    return BackgroundJobListResponse(



        jobs=[BackgroundJobResponse(**j) for j in jobs],



        total=total,



    )











@router.post("/workflows/background/{job_id}/cancel", response_model=BackgroundJobResponse)



async def cancel_background_job(job_id: str) -> BackgroundJobResponse:



    """Cancel a background job."""



    job = _background_jobs.get(job_id)



    if not job:



        raise HTTPException(status_code=404, detail="Job not found")







    if job["status"] in ["completed", "failed", "cancelled"]:



        raise HTTPException(status_code=400, detail=f"Cannot cancel job in status: {job['status']}")







    job["status"] = "cancelled"



    job["completed_at"] = _now_iso()







    # Also cancel execution if exists



    if job.get("execution_id"):



        exec_id = job["execution_id"]



        if exec_id in _workflow_executions:



            _workflow_executions[exec_id]["status"] = "cancelled"



            _workflow_executions[exec_id]["completed_at"] = _now_iso()







    return BackgroundJobResponse(**job)











@router.get("/workflows/background/{job_id}/result")



async def get_background_job_result(job_id: str) -> dict:



    """Get the result of a completed background job."""



    job = _background_jobs.get(job_id)



    if not job:



        raise HTTPException(status_code=404, detail="Job not found")







    if job["status"] != "completed":



        return {



            "status": job["status"],



            "progress": job.get("progress", 0),



            "result": job.get("result"),



            "error": job.get("error"),



        }







    return {



        "status": "completed",



        "progress": 1.0,



        "result": job.get("result"),



        "completed_at": job.get("completed_at"),



    }











# ===== Workflow Scheduling (Cron-like) =====







# Schedule storage



_schedules: dict[str, dict] = {}



_schedule_exec_history: dict[str, list[dict]] = {}  # schedule_id -> execution history



_schedule_enabled: dict[str, bool] = {}  # schedule_id -> enabled











def _parse_cron_expression(cron_expr: str) -> dict:



    """Parse a cron expression into components."""



    parts = cron_expr.strip().split()



    if len(parts) != 5:



        raise ValueError("Cron expression must have 5 parts: minute hour day-of-month month day-of-week")







    return {



        "minute": parts[0],



        "hour": parts[1],



        "day_of_month": parts[2],



        "month": parts[3],



        "day_of_week": parts[4],



    }











def _cron_matches(cron_parts: dict, dt: datetime) -> bool:



    """Check if a datetime matches a cron expression."""



    import calendar







    def matches_field(field: str, value: int) -> bool:



        if field == "*":



            return True



        if "/" in field:



            # Handle step values (e.g., */5)



            step = int(field.split("/")[1])



            return value % step == 0



        if "," in field:



            # Handle lists (e.g., 1,3,5)



            return str(value) in field.split(",")



        if "-" in field:



            # Handle ranges (e.g., 1-5)



            start, end = map(int, field.split("-"))



            return start <= value <= end



        return str(value) == field







    return (



        matches_field(cron_parts["minute"], dt.minute) and



        matches_field(cron_parts["hour"], dt.hour) and



        matches_field(cron_parts["day_of_month"], dt.day) and



        matches_field(cron_parts["month"], dt.month) and



        matches_field(cron_parts["day_of_week"], dt.weekday())



    )











def _next_scheduled_time(cron_expr: str, from_dt: datetime | None = None) -> datetime | None:



    """Calculate the next scheduled time after a given datetime."""



    if from_dt is None:



        from_dt = datetime.now()







    try:



        cron_parts = _parse_cron_expression(cron_expr)



    except ValueError:



        return None







    # Check up to 1 year ahead



    for _ in range(525600):  # minutes in a year



        if _cron_matches(cron_parts, from_dt):



            return from_dt



        from_dt = from_dt.replace(minute=from_dt.minute + 1)



        # Handle minute overflow



        if from_dt.minute == 0:



            from_dt = from_dt.replace(hour=(from_dt.hour + 1) % 24)



            if from_dt.hour == 0:



                from_dt = from_dt.replace(day=from_dt.day + 1)



                if from_dt.day > calendar.monthrange(from_dt.year, from_dt.month)[1]:



                    from_dt = from_dt.replace(day=1, month=from_dt.month + 1)



                    if from_dt.month > 12:



                        from_dt = from_dt.replace(month=1, year=from_dt.year + 1)







    return None











def _now_iso() -> str:



    return datetime.now(timezone.utc).isoformat()











class CreateScheduleRequest(BaseModel):



    """Request to create a workflow schedule."""



    workflow_id: str



    cron_expression: str



    name: str | None = None



    description: str | None = None



    input_params: dict = {}



    enabled: bool = True



    timezone: str = "UTC"











class ScheduleResponse(BaseModel):



    """Response for a workflow schedule."""



    schedule_id: str



    workflow_id: str



    name: str | None



    description: str | None



    cron_expression: str



    next_run: str | None



    last_run: str | None



    input_params: dict



    enabled: bool



    timezone: str



    created_at: str



    execution_count: int











class UpdateScheduleRequest(BaseModel):



    """Request to update a workflow schedule."""



    name: str | None = None



    description: str | None = None



    cron_expression: str | None = None



    input_params: dict | None = None



    enabled: bool | None = None



    timezone: str | None = None











class ScheduleHistoryEntry(BaseModel):



    """A single schedule execution history entry."""



    execution_id: str



    started_at: str



    completed_at: str | None



    status: str  # triggered, completed, failed, skipped



    job_id: str | None



    result: dict | None



    error: str | None











class ScheduleListResponse(BaseModel):



    """Response for listing schedules."""



    schedules: list[ScheduleResponse]



    total: int











class ScheduleHistoryResponse(BaseModel):



    """Response for schedule execution history."""



    history: list[ScheduleHistoryEntry]



    total: int











@router.post("/workflows/schedules", response_model=ScheduleResponse)



async def create_schedule(req: CreateScheduleRequest) -> ScheduleResponse:



    """Create a new workflow schedule with cron expression."""



    # Validate cron expression



    try:



        cron_parts = _parse_cron_expression(req.cron_expression)



    except ValueError as e:



        raise HTTPException(status_code=400, detail=str(e))







    schedule_id = f"sched_{uuid.uuid4().hex[:12]}"



    now = _now_iso()







    # Calculate next run



    next_run_dt = _next_scheduled_time(req.cron_expression)



    next_run = next_run_dt.isoformat() if next_run_dt else None







    schedule = {



        "schedule_id": schedule_id,



        "workflow_id": req.workflow_id,



        "name": req.name,



        "description": req.description,



        "cron_expression": req.cron_expression,



        "next_run": next_run,



        "last_run": None,



        "input_params": req.input_params,



        "enabled": req.enabled,



        "timezone": req.timezone,



        "created_at": now,



    }







    _schedules[schedule_id] = schedule



    _schedule_enabled[schedule_id] = req.enabled



    _schedule_exec_history[schedule_id] = []







    return ScheduleResponse(



        schedule_id=schedule_id,



        workflow_id=req.workflow_id,



        name=req.name,



        description=req.description,



        cron_expression=req.cron_expression,



        next_run=next_run,



        last_run=None,



        input_params=req.input_params,



        enabled=req.enabled,



        timezone=req.timezone,



        created_at=now,



        execution_count=0,



    )











@router.get("/workflows/schedules", response_model=ScheduleListResponse)



async def list_schedules(



    workflow_id: str | None = None,



    enabled: bool | None = None,



    limit: int = Query(50, le=100),



    offset: int = 0,



) -> ScheduleListResponse:



    """List all workflow schedules."""



    schedules = []







    for sched_id, sched in _schedules.items():



        # Filter by workflow_id



        if workflow_id and sched.get("workflow_id") != workflow_id:



            continue



        # Filter by enabled status



        if enabled is not None and _schedule_enabled.get(sched_id) != enabled:



            continue







        # Calculate next run



        next_run_dt = _next_scheduled_time(sched["cron_expression"])



        next_run = next_run_dt.isoformat() if next_run_dt else None







        schedules.append(ScheduleResponse(



            schedule_id=sched_id,



            workflow_id=sched.get("workflow_id", ""),



            name=sched.get("name"),



            description=sched.get("description"),



            cron_expression=sched.get("cron_expression", ""),



            next_run=next_run,



            last_run=sched.get("last_run"),



            input_params=sched.get("input_params", {}),



            enabled=_schedule_enabled.get(sched_id, True),



            timezone=sched.get("timezone", "UTC"),



            created_at=sched.get("created_at", ""),



            execution_count=len(_schedule_exec_history.get(sched_id, [])),



        ))







    # Sort by next run



    schedules.sort(key=lambda s: s.next_run or "")







    # Apply pagination



    total = len(schedules)



    schedules = schedules[offset:offset + limit]







    return ScheduleListResponse(schedules=schedules, total=total)











@router.get("/workflows/schedules/{schedule_id}", response_model=ScheduleResponse)



async def get_schedule(schedule_id: str) -> ScheduleResponse:



    """Get a workflow schedule by ID."""



    sched = _schedules.get(schedule_id)



    if not sched:



        raise HTTPException(status_code=404, detail="Schedule not found")







    # Calculate next run



    next_run_dt = _next_scheduled_time(sched["cron_expression"])



    next_run = next_run_dt.isoformat() if next_run_dt else None







    return ScheduleResponse(



        schedule_id=schedule_id,



        workflow_id=sched.get("workflow_id", ""),



        name=sched.get("name"),



        description=sched.get("description"),



        cron_expression=sched.get("cron_expression", ""),



        next_run=next_run,



        last_run=sched.get("last_run"),



        input_params=sched.get("input_params", {}),



        enabled=_schedule_enabled.get(schedule_id, True),



        timezone=sched.get("timezone", "UTC"),



        created_at=sched.get("created_at", ""),



        execution_count=len(_schedule_exec_history.get(schedule_id, [])),



    )











@router.patch("/workflows/schedules/{schedule_id}", response_model=ScheduleResponse)



async def update_schedule(schedule_id: str, req: UpdateScheduleRequest) -> ScheduleResponse:



    """Update a workflow schedule."""



    sched = _schedules.get(schedule_id)



    if not sched:



        raise HTTPException(status_code=404, detail="Schedule not found")







    # Update fields



    if req.name is not None:



        sched["name"] = req.name



    if req.description is not None:



        sched["description"] = req.description



    if req.cron_expression is not None:



        try:



            _parse_cron_expression(req.cron_expression)



            sched["cron_expression"] = req.cron_expression



        except ValueError as e:



            raise HTTPException(status_code=400, detail=str(e))



    if req.input_params is not None:



        sched["input_params"] = req.input_params



    if req.enabled is not None:



        _schedule_enabled[schedule_id] = req.enabled



    if req.timezone is not None:



        sched["timezone"] = req.timezone







    # Recalculate next run



    next_run_dt = _next_scheduled_time(sched["cron_expression"])



    next_run = next_run_dt.isoformat() if next_run_dt else None







    return ScheduleResponse(



        schedule_id=schedule_id,



        workflow_id=sched.get("workflow_id", ""),



        name=sched.get("name"),



        description=sched.get("description"),



        cron_expression=sched.get("cron_expression", ""),



        next_run=next_run,



        last_run=sched.get("last_run"),



        input_params=sched.get("input_params", {}),



        enabled=_schedule_enabled.get(schedule_id, True),



        timezone=sched.get("timezone", "UTC"),



        created_at=sched.get("created_at", ""),



        execution_count=len(_schedule_exec_history.get(schedule_id, [])),



    )











@router.delete("/workflows/schedules/{schedule_id}")



async def delete_schedule(schedule_id: str) -> dict:



    """Delete a workflow schedule."""



    if schedule_id not in _schedules:



        raise HTTPException(status_code=404, detail="Schedule not found")







    del _schedules[schedule_id]



    _schedule_enabled.pop(schedule_id, None)



    _schedule_exec_history.pop(schedule_id, None)







    return {"status": "deleted", "schedule_id": schedule_id}











@router.post("/workflows/schedules/{schedule_id}/trigger")



async def trigger_schedule(schedule_id: str) -> dict:



    """Manually trigger a workflow schedule immediately."""



    sched = _schedules.get(schedule_id)



    if not sched:



        raise HTTPException(status_code=404, detail="Schedule not found")







    if not _schedule_enabled.get(schedule_id, True):



        raise HTTPException(status_code=400, detail="Schedule is disabled")







    # Create execution history entry



    execution_id = f"exec_{uuid.uuid4().hex[:12]}"



    now = _now_iso()







    entry = {



        "execution_id": execution_id,



        "started_at": now,



        "completed_at": None,



        "status": "triggered",



        "job_id": None,



        "result": None,



        "error": None,



    }







    history = _schedule_exec_history.setdefault(schedule_id, [])



    history.append(entry)







    # Keep only last 100 entries



    if len(history) > 100:



        history[:] = history[-100:]







    # Update last run



    sched["last_run"] = now







    return {



        "status": "triggered",



        "execution_id": execution_id,



        "schedule_id": schedule_id,



        "workflow_id": sched.get("workflow_id"),



    }











@router.get("/workflows/schedules/{schedule_id}/history", response_model=ScheduleHistoryResponse)



async def get_schedule_history(



    schedule_id: str,



    limit: int = Query(20, le=100),



    offset: int = 0,



) -> ScheduleHistoryResponse:



    """Get execution history for a schedule."""



    if schedule_id not in _schedules:



        raise HTTPException(status_code=404, detail="Schedule not found")







    history = _schedule_exec_history.get(schedule_id, [])







    # Build response entries



    entries = []



    for entry in reversed(history):



        entries.append(ScheduleHistoryEntry(



            execution_id=entry.get("execution_id", ""),



            started_at=entry.get("started_at", ""),



            completed_at=entry.get("completed_at"),



            status=entry.get("status", ""),



            job_id=entry.get("job_id"),



            result=entry.get("result"),



            error=entry.get("error"),



        ))







    total = len(entries)



    entries = entries[offset:offset + limit]







    return ScheduleHistoryResponse(history=entries, total=total)











@router.post("/workflows/schedules/{schedule_id}/enable")



async def enable_schedule(schedule_id: str) -> ScheduleResponse:



    """Enable a workflow schedule."""



    sched = _schedules.get(schedule_id)



    if not sched:



        raise HTTPException(status_code=404, detail="Schedule not found")







    _schedule_enabled[schedule_id] = True







    # Recalculate next run



    next_run_dt = _next_scheduled_time(sched["cron_expression"])



    next_run = next_run_dt.isoformat() if next_run_dt else None







    return ScheduleResponse(



        schedule_id=schedule_id,



        workflow_id=sched.get("workflow_id", ""),



        name=sched.get("name"),



        description=sched.get("description"),



        cron_expression=sched.get("cron_expression", ""),



        next_run=next_run,



        last_run=sched.get("last_run"),



        input_params=sched.get("input_params", {}),



        enabled=True,



        timezone=sched.get("timezone", "UTC"),



        created_at=sched.get("created_at", ""),



        execution_count=len(_schedule_exec_history.get(schedule_id, [])),



    )











@router.post("/workflows/schedules/{schedule_id}/disable")



async def disable_schedule(schedule_id: str) -> ScheduleResponse:



    """Disable a workflow schedule."""



    sched = _schedules.get(schedule_id)



    if not sched:



        raise HTTPException(status_code=404, detail="Schedule not found")







    _schedule_enabled[schedule_id] = False







    return ScheduleResponse(



        schedule_id=schedule_id,



        workflow_id=sched.get("workflow_id", ""),



        name=sched.get("name"),



        description=sched.get("description"),



        cron_expression=sched.get("cron_expression", ""),



        next_run=None,



        last_run=sched.get("last_run"),



        input_params=sched.get("input_params", {}),



        timezone=sched.get("timezone", "UTC"),



        created_at=sched.get("created_at", ""),



        execution_count=len(_schedule_exec_history.get(schedule_id, [])),



    )











