    # Apply filters



    if workflow_id:



        webhooks = [w for w in webhooks if w.get("workflow_id") == workflow_id]



    if enabled is not None:



        webhooks = [w for w in webhooks if w.get("enabled") == enabled]







    webhooks = webhooks[:limit]







    return WebhookListResponse(



        webhooks=[



            WebhookResponse(



                webhook_id=w["webhook_id"],



                workflow_id=w.get("workflow_id", ""),



                name=w.get("name", ""),



                description=w.get("description"),



                trigger_url=f"/api/electron/kg/workflows/webhooks/{w['webhook_id']}/trigger",



                secret="***HIDDEN***",  # Don't expose secret in list



                allowed_methods=w.get("allowed_methods", ["POST"]),



                allowed_ips=w.get("allowed_ips", []),



                custom_headers=w.get("custom_headers", {}),



                enabled=w.get("enabled", True),



                created_at=w.get("created_at", ""),



                invocation_count=len(_webhook_invocations.get(w["webhook_id"], [])),



                last_triggered=w.get("last_triggered"),



            )



            for w in webhooks



        ],



        total=len(webhooks),



    )











