@router.post("/workflows/webhooks/{webhook_id}/trigger")



async def trigger_webhook(



    webhook_id: str,



    request: Request,



    payload: dict | None = None,



) -> dict:



    """Trigger a workflow via webhook (public endpoint)."""



    webhook = _webhooks.get(webhook_id)



    if not webhook:



        raise HTTPException(status_code=404, detail="Webhook not found")







    if not webhook.get("enabled", True):



        raise HTTPException(status_code=403, detail="Webhook is disabled")







    # Get request details



    method = request.method



    client_ip = request.client.host if request.client else None



    headers = dict(request.headers)







    # Check allowed methods



    if method not in webhook.get("allowed_methods", ["POST"]):



        raise HTTPException(status_code=405, detail=f"Method {method} not allowed")







    # Check IP whitelist



    allowed_ips = webhook.get("allowed_ips", [])



    if allowed_ips and client_ip not in allowed_ips:



        raise HTTPException(status_code=403, detail="IP not allowed")







    # Generate invocation record



    invocation_id = f"whi_{uuid.uuid4().hex[:12]}"



    now = _now_iso()







    # Prepare payload



    body = payload



    if body is None:



        try:



            body = await request.json() if method == "POST" else {}



        except Exception:



            body = {}







    # Extract query params



    query_params = dict(request.query_params)







    # Try to trigger the workflow



    triggered = False



    error_msg = None



    result = None







    try:



        workflow_id = webhook.get("workflow_id")



        if workflow_id in _workflows:



            # Execute workflow with webhook payload



            exec_req = WorkflowExecutionRequest(



                input_params={



                    "triggered_by": "webhook",



                    "webhook_id": webhook_id,



                    "invocation_id": invocation_id,



                    "source_ip": client_ip,



                    "payload": body,



                    "query_params": query_params,



                }



            )



            result = await execute_workflow(workflow_id, exec_req)



            triggered = True



            webhook["last_triggered"] = now



    except Exception as e:



        error_msg = str(e)







    # Record invocation



    invocation = {



        "invocation_id": invocation_id,



        "webhook_id": webhook_id,



        "timestamp": now,



        "method": method,



        "source_ip": client_ip,



        "headers": headers,



        "payload": body,



        "query_params": query_params,



        "status_code": 200 if triggered else 500,



        "response_body": str(result) if result else None,



        "triggered_workflow": triggered,



        "error": error_msg,



    }







    if webhook_id not in _webhook_invocations:



        _webhook_invocations[webhook_id] = []







    invocations = _webhook_invocations[webhook_id]



    invocations.append(invocation)







    # Keep last 100 invocations



    if len(invocations) > 100:



        _webhook_invocations[webhook_id] = invocations[-100:]







    if error_msg and not triggered:



        raise HTTPException(status_code=500, detail=f"Workflow trigger failed: {error_msg}")







    # Return custom headers



    custom_headers = webhook.get("custom_headers", {})







    return JSONResponse(



        content={



            "webhook_id": webhook_id,



            "invocation_id": invocation_id,



            "workflow_id": webhook.get("workflow_id"),



            "triggered": triggered,



            "result": result.model_dump() if result else None,



        },



        headers=custom_headers,



    )











