# =============================================================================



# GRAPH PATTERN SEARCH & EXTRACTION



# =============================================================================











class EntityPatternRequest(BaseModel):



    """Request to search entities by pattern."""



    entity_types: list[str] = []  # Match entities of these types



    domains: list[str] = []  # Match entities in these domains



    tags: list[str] = []  # Match entities with ALL these tags



    any_tags: list[str] = []  # Match entities with ANY of these tags



    min_confidence: float | None = None



    max_confidence: float | None = None



    name_contains: str | None = None  # Case-insensitive substring match



    name_regex: str | None = None  # Regex pattern match



    created_after: str | None = None  # ISO datetime



    updated_after: str | None = None  # ISO datetime



    has_relations: bool | None = None  # Filter by relation presence



    limit: int = Query(100, le=1000)











class EntityPatternMatch(BaseModel):



    """A single entity matching the pattern."""



    entity_id: str



    name: str



    type: str



    domain: str



    tags: list[str]



    confidence: float



    relation_count: int



    created_at: str



    updated_at: str











class EntityPatternResponse(BaseModel):



    """Response for entity pattern search."""



    entities: list[EntityPatternMatch]



    total: int



    pattern_applied: dict  # What filters were applied











class RelationPatternRequest(BaseModel):



    """Request to search relations by pattern."""



    relation_types: list[str] = []  # Match relations of these types



    source_types: list[str] = []  # Match source entities of these types



    target_types: list[str] = []  # Match target entities of these types



    source_domains: list[str] = []  # Match source entities in these domains



    target_domains: list[str] = []  # Match target entities in these domains



    min_strength: float | None = None



    max_strength: float | None = None



    bidirectional: bool | None = None  # Filter by bidirectional flag



    created_after: str | None = None



    limit: int = Query(100, le=1000)











class RelationPatternMatch(BaseModel):



    """A single relation matching the pattern."""



    relation_id: str



    source_id: str



    source_name: str



    target_id: str



    target_name: str



    relation_type: str



    strength: float



    bidirectional: bool



    created_at: str











class RelationPatternResponse(BaseModel):



    """Response for relation pattern search."""



    relations: list[RelationPatternMatch]



    total: int











class PatternSubgraphRequest(BaseModel):



    """Request to extract subgraph by pattern."""



    # Entity filters



    entity_types: list[str] = []



    domains: list[str] = []



    tags: list[str] = []



    min_confidence: float | None = None



    name_contains: str | None = None



    # Relation filters



    relation_types: list[str] = []



    min_strength: float | None = None



    # Output options



    include_relations: bool = True



    max_nodes: int = Query(500, le=10000)











class PatternSubgraphResponse(BaseModel):



    """Response for pattern-based subgraph extraction."""



    nodes: list[dict]



    edges: list[dict]



    total_nodes: int



    total_edges: int



    pattern_summary: dict











class PatternStatsRequest(BaseModel):



    """Request for pattern statistics."""



    entity_types: list[str] = []



    domains: list[str] = []



    tags: list[str] = []



    relation_types: list[str] = []











class PatternStatsResponse(BaseModel):



    """Response for pattern statistics."""



    total_entities: int



    total_relations: int



    entity_type_distribution: dict[str, int]



    domain_distribution: dict[str, int]



    relation_type_distribution: dict[str, int]



    confidence_distribution: dict[str, int]



    strength_distribution: dict[str, int]



    top_tags: list[dict]



    most_connected: list[dict]











@router.post("/patterns/entities", response_model=EntityPatternResponse)



async def search_entities_by_pattern(req: EntityPatternRequest) -> EntityPatternResponse:



    """Search entities by complex pattern criteria."""



    import re as regex_module







    matches = []







    for entity in _entities.values():



        # Entity type filter



        if req.entity_types and entity.get("type") not in req.entity_types:



            continue







        # Domain filter



        if req.domains and entity.get("domain") not in req.domains:



            continue







        # Tags filter (ALL must match)



        entity_tags = set(entity.get("tags", []))



        if req.tags:



            if not all(t in entity_tags for t in req.tags):



                continue







        # Any tags filter (ANY can match)



        if req.any_tags:



            if not any(t in entity_tags for t in req.any_tags):



                continue







        # Confidence range



        conf = entity.get("confidence", 0.5)



        if req.min_confidence is not None and conf < req.min_confidence:



            continue



        if req.max_confidence is not None and conf > req.max_confidence:



            continue







        # Name contains



        name = entity.get("name", "")



        if req.name_contains and req.name_contains.lower() not in name.lower():



            continue







        # Name regex



        if req.name_regex:



            try:



                if not regex_module.search(req.name_regex, name):



                    continue



            except regex_module.error:



                pass







        # Time filters



        if req.created_after and entity.get("created_at", "") < req.created_after:



            continue



        if req.updated_after and entity.get("updated_at", "") < req.updated_after:



            continue







        # Has relations



        if req.has_relations is not None:



            # Check if entity has any relations



            has_any = False



            for rel in _relations.values():



                if (rel.get("sourceId") == entity.get("entity_id") or



                    rel.get("targetId") == entity.get("entity_id")):



                    has_any = True



                    break



            if req.has_relations and not has_any:



                continue



            if not req.has_relations and has_any:



                continue







        # Count relations



        rel_count = 0



        for rel in _relations.values():



            if (rel.get("sourceId") == entity.get("entity_id") or



                rel.get("targetId") == entity.get("entity_id")):



                rel_count += 1







        matches.append(EntityPatternMatch(



            entity_id=entity.get("entity_id", ""),



            name=name,



            type=entity.get("type", ""),



            domain=entity.get("domain", ""),



            tags=entity.get("tags", []),



            confidence=conf,



            relation_count=rel_count,



            created_at=entity.get("created_at", ""),



            updated_at=entity.get("updated_at", ""),



        ))







        if len(matches) >= req.limit:



            break







    total = len(matches)







    return EntityPatternResponse(



        entities=matches[:req.limit],



        total=total,



        pattern_applied={



            "entity_types": req.entity_types,



            "domains": req.domains,



            "tags": req.tags,



            "any_tags": req.any_tags,



            "min_confidence": req.min_confidence,



            "name_contains": req.name_contains,



        },



    )











@router.post("/patterns/relations", response_model=RelationPatternResponse)



async def search_relations_by_pattern(req: RelationPatternRequest) -> RelationPatternResponse:



    """Search relations by complex pattern criteria."""



    matches = []







    for relation in _relations.values():



        source_id = relation.get("sourceId", "")



        target_id = relation.get("targetId", "")







        source = _entities.get(source_id, {})



        target = _entities.get(target_id, {})







        # Relation type filter



        rtype = relation.get("type", "")



        if req.relation_types and rtype not in req.relation_types:



            continue







        # Source type filter



        if req.source_types and source.get("type") not in req.source_types:



            continue







        # Target type filter



        if req.target_types and target.get("type") not in req.target_types:



            continue







        # Source domain filter



        if req.source_domains and source.get("domain") not in req.source_domains:



            continue







        # Target domain filter



        if req.target_domains and target.get("domain") not in req.target_domains:



            continue







        # Strength range



        strength = relation.get("strength", 0.5)



        if req.min_strength is not None and strength < req.min_strength:



            continue



        if req.max_strength is not None and strength > req.max_strength:



            continue







        # Bidirectional filter



        if req.bidirectional is not None:



            if relation.get("bidirectional", False) != req.bidirectional:



                continue







        # Time filter



        if req.created_after and relation.get("created_at", "") < req.created_after:



            continue







        matches.append(RelationPatternMatch(



            relation_id=relation.get("relation_id", ""),



            source_id=source_id,



            source_name=source.get("name", ""),



            target_id=target_id,



            target_name=target.get("name", ""),



            relation_type=rtype,



            strength=strength,



            bidirectional=relation.get("bidirectional", False),



            created_at=relation.get("created_at", ""),



        ))







        if len(matches) >= req.limit:



            break







    total = len(matches)







    return RelationPatternResponse(



        relations=matches[:req.limit],



        total=total,



    )











@router.post("/patterns/subgraph", response_model=PatternSubgraphResponse)



async def extract_subgraph_by_pattern(req: PatternSubgraphRequest) -> PatternSubgraphResponse:



    """Extract subgraph based on pattern criteria."""



    # First find matching entities



    matching_entity_ids: set[str] = set()







    for entity in _entities.values():



        # Entity type filter



        if req.entity_types and entity.get("type") not in req.entity_types:



            continue







        # Domain filter



        if req.domains and entity.get("domain") not in req.domains:



            continue







        # Tags filter



        entity_tags = set(entity.get("tags", []))



        if req.tags:



            if not all(t in entity_tags for t in req.tags):



                continue







        # Confidence filter



        conf = entity.get("confidence", 0.5)



        if req.min_confidence is not None and conf < req.min_confidence:



            continue







        # Name contains



        name = entity.get("name", "")



        if req.name_contains and req.name_contains.lower() not in name.lower():



            continue







        matching_entity_ids.add(entity.get("entity_id", ""))







        if len(matching_entity_ids) >= req.max_nodes:



            break







    # Now find matching relations between matched entities



    nodes = []



    edges = []







    for eid in matching_entity_ids:



        if eid in _entities:



            nodes.append(dict(_entities[eid]))







    if req.include_relations:



        for relation in _relations.values():



            source_id = relation.get("sourceId", "")



            target_id = relation.get("targetId", "")







            # Both endpoints must be in matching entities



            if source_id not in matching_entity_ids or target_id not in matching_entity_ids:



                continue







            # Relation type filter



            rtype = relation.get("type", "")



            if req.relation_types and rtype not in req.relation_types:



                continue







            # Strength filter



            strength = relation.get("strength", 0.5)



            if req.min_strength is not None and strength < req.min_strength:



                continue







            edges.append(dict(relation))







    return PatternSubgraphResponse(



        nodes=nodes,



        edges=edges,



        total_nodes=len(nodes),



        total_edges=len(edges),



        pattern_summary={



            "entity_types": req.entity_types,



            "domains": req.domains,



            "tags": req.tags,



            "relation_types": req.relation_types,



            "min_confidence": req.min_confidence,



            "name_contains": req.name_contains,



        },



    )











@router.post("/patterns/stats", response_model=PatternStatsResponse)



async def get_pattern_stats(req: PatternStatsRequest) -> PatternStatsResponse:



    """Get statistics for entities and relations matching pattern."""



    entity_type_dist: dict[str, int] = {}



    domain_dist: dict[str, int] = {}



    relation_type_dist: dict[str, int] = {}



    confidence_dist = {"low": 0, "medium": 0, "high": 0}



    strength_dist = {"weak": 0, "medium": 0, "strong": 0}



    tag_counts: dict[str, int] = {}



    connection_counts: dict[str, int] = {}







    # Filter entities



    for entity in _entities.values():



        if req.entity_types and entity.get("type") not in req.entity_types:



            continue



        if req.domains and entity.get("domain") not in req.domains:



            continue



        if req.tags:



            entity_tags = set(entity.get("tags", []))



            if not all(t in entity_tags for t in req.tags):



                continue







        entity_type_dist[entity.get("type", "unknown")] = entity_type_dist.get(entity.get("type", "unknown"), 0) + 1



        domain_dist[entity.get("domain", "unknown")] = domain_dist.get(entity.get("domain", "unknown"), 0) + 1







        conf = entity.get("confidence", 0.5)



        if conf < 0.4:



            confidence_dist["low"] += 1



        elif conf < 0.7:



            confidence_dist["medium"] += 1



        else:



            confidence_dist["high"] += 1







        for tag in entity.get("tags", []):



            tag_counts[tag] = tag_counts.get(tag, 0) + 1







        eid = entity.get("entity_id")



        if eid:



            connection_counts[eid] = 0







    # Filter relations and count connections



    for relation in _relations.values():



        if req.relation_types and relation.get("type") not in req.relation_types:



            continue







        relation_type_dist[relation.get("type", "unknown")] = relation_type_dist.get(relation.get("type", "unknown"), 0) + 1







        strength = relation.get("strength", 0.5)



        if strength < 0.33:



            strength_dist["weak"] += 1



        elif strength < 0.66:



            strength_dist["medium"] += 1



        else:



            strength_dist["strong"] += 1







        source = relation.get("sourceId")



        target = relation.get("targetId")



        if source in connection_counts:



            connection_counts[source] = connection_counts.get(source, 0) + 1



        if target in connection_counts:



            connection_counts[target] = connection_counts.get(target, 0) + 1







    # Top tags



    top_tags = sorted(



        [{"tag": t, "count": c} for t, c in tag_counts.items()],



        key=lambda x: x["count"],



        reverse=True,



    )[:10]







    # Most connected



    most_connected = sorted(



        [{"entity_id": eid, "connections": count} for eid, count in connection_counts.items()],



        key=lambda x: x["connections"],



        reverse=True,



    )[:10]







    total_entities = sum(entity_type_dist.values())



    total_relations = sum(relation_type_dist.values())







    return PatternStatsResponse(



        total_entities=total_entities,



        total_relations=total_relations,



        entity_type_distribution=entity_type_dist,



        domain_distribution=domain_dist,



        relation_type_distribution=relation_type_dist,



        confidence_distribution=confidence_dist,



        strength_distribution=strength_dist,



        top_tags=top_tags,



        most_connected=most_connected,



    )











@router.post("/patterns/paths")



async def find_paths_between_pattern(



    source_pattern: EntityPatternRequest,



    target_pattern: EntityPatternRequest,



    max_length: int = Query(4, le=10),



) -> dict:



    """Find paths between entities matching source and target patterns."""



    # Find source entities



    source_ids: set[str] = set()







    for entity in _entities.values():



        if source_pattern.entity_types and entity.get("type") not in source_pattern.entity_types:



            continue



        if source_pattern.domains and entity.get("domain") not in source_pattern.domains:



            continue



        if source_pattern.name_contains:



            if source_pattern.name_contains.lower() not in entity.get("name", "").lower():



                continue



        source_ids.add(entity.get("entity_id", ""))







    # Find target entities



    target_ids: set[str] = set()







    for entity in _entities.values():



        if target_pattern.entity_types and entity.get("type") not in target_pattern.entity_types:



            continue



        if target_pattern.domains and entity.get("domain") not in target_pattern.domains:



            continue



        if target_pattern.name_contains:



            if target_pattern.name_contains.lower() not in entity.get("name", "").lower():



                continue



        target_ids.add(entity.get("entity_id", ""))







    if not source_ids or not target_ids:



        raise HTTPException(status_code=404, detail="No entities match source or target pattern")







    # Build adjacency



    adjacency: dict[str, set[str]] = {eid: set() for eid in _entities}



    for rel in _relations.values():



        src = rel.get("sourceId", "")



        tgt = rel.get("targetId", "")



        if src in _entities and tgt in _entities:



            adjacency[src].add(tgt)



            if rel.get("bidirectional", False):



                adjacency[tgt].add(src)







    # BFS to find paths



    paths: list[dict] = []







    for start in source_ids:



        if start in target_ids:



            # Direct match



            paths.append({



                "path": [start],



                "length": 0,



                "edges": [],



            })



            continue







        visited = {start}



        queue = [(start, [start], [])]  # (current, path, edges)







        while queue:



            current, path, path_edges = queue.pop(0)







            if len(path) > max_length:



                continue







            for neighbor in adjacency.get(current, []):



                if neighbor in visited:



                    continue







                visited.add(neighbor)



                new_path = path + [neighbor]



                new_edges = path_edges + [current]







                if neighbor in target_ids:



                    paths.append({



                        "path": new_path,



                        "length": len(new_path) - 1,



                        "edges": new_edges,



                    })







                    if len(paths) >= 50:  # Limit results



                        break



                else:



                    queue.append((neighbor, new_path, new_edges))







            if len(paths) >= 50:



                break







        if len(paths) >= 50:



            break







    return {



        "paths": paths[:20],



        "total_paths": len(paths),



        "source_count": len(source_ids),



        "target_count": len(target_ids),



    }











