class GraphCompareResponse(BaseModel):



    """Response for graph comparison."""



    summary: dict



    entities_added: list[dict]



    entities_removed: list[dict]



    entities_changed: list[dict]



    relations_added: list[dict]



    relations_removed: list[dict]



    relations_changed: list[dict]











async def _compare_entity_sets(



    entities_a: dict[str, dict],



    entities_b: dict[str, dict],



) -> tuple[list[dict], list[dict], list[dict]]:



    """Compare two entity sets and return added, removed, changed."""



    import copy







    added = []



    removed = []



    changed = []







    ids_a = set(entities_a.keys())



    ids_b = set(entities_b.keys())







    # Entities in B but not in A (added)



    for eid in ids_b - ids_a:



        entity = copy.deepcopy(entities_b[eid])



        entity["status"] = "added"



        added.append(entity)







    # Entities in A but not in B (removed)



    for eid in ids_a - ids_b:



        entity = copy.deepcopy(entities_a[eid])



        entity["status"] = "removed"



        removed.append(entity)







    # Entities in both - check for changes



    for eid in ids_a & ids_b:



        ent_a = entities_a[eid]



        ent_b = entities_b[eid]







        # Compare fields (exclude entity_id)



        changes = {}



        all_keys = set(ent_a.keys()) | set(ent_b.keys())



        all_keys.discard("entity_id")







        for key in all_keys:



            val_a = ent_a.get(key)



            val_b = ent_b.get(key)



            if val_a != val_b:



                changes[key] = (val_a, val_b)







        if changes:



            entity = copy.deepcopy(ent_b)



            entity["status"] = "changed"



            entity["field_changes"] = changes



            changed.append(entity)







    return added, removed, changed











async def _compare_relation_sets(



    relations_a: dict[str, dict],



    relations_b: dict[str, dict],



) -> tuple[list[dict], list[dict], list[dict]]:



    """Compare two relation sets and return added, removed, changed."""



    import copy







    added = []



    removed = []



    changed = []







    ids_a = set(relations_a.keys())



    ids_b = set(relations_b.keys())







    # Relations in B but not in A (added)



    for rid in ids_b - ids_a:



        rel = copy.deepcopy(relations_b[rid])



        rel["status"] = "added"



        added.append(rel)







    # Relations in A but not in B (removed)



    for rid in ids_a - ids_b:



        rel = copy.deepcopy(relations_a[rid])



        rel["status"] = "removed"



        removed.append(rel)







    # Relations in both - check for changes



    for rid in ids_a & ids_b:



        rel_a = relations_a[rid]



        rel_b = relations_b[rid]







        # Compare fields



        changes = {}



        all_keys = set(rel_a.keys()) | set(rel_b.keys())



        all_keys.discard("relation_id")







        for key in all_keys:



            val_a = rel_a.get(key)



            val_b = rel_b.get(key)



            if val_a != val_b:



                changes[key] = (val_a, val_b)







        if changes:



            rel = copy.deepcopy(rel_b)



            rel["status"] = "changed"



            rel["field_changes"] = changes



            changed.append(rel)







    return added, removed, changed











@router.post("/compare/snapshots", response_model=GraphCompareResponse)



async def compare_snapshots(req: SnapshotCompareRequest) -> GraphCompareResponse:



    """Compare two snapshots and return differences.







    Returns entities and relations that were added, removed, or changed.



    """



    import copy







    # Get snapshot A



    if req.snapshot_a not in _graph_snapshots:



        raise HTTPException(status_code=404, detail=f"Snapshot A '{req.snapshot_a}' not found")







    entities_a, relations_a, created_a = _graph_snapshots[req.snapshot_a]







    # Get snapshot B



    if req.snapshot_b not in _graph_snapshots:



        raise HTTPException(status_code=404, detail=f"Snapshot B '{req.snapshot_b}' not found")







    entities_b, relations_b, created_b = _graph_snapshots[req.snapshot_b]







    # Compare



    entities_added, entities_removed, entities_changed = await _compare_entity_sets(entities_a, entities_b)



    relations_added, relations_removed, relations_changed = await _compare_relation_sets(relations_a, relations_b)







    # Build summary



    summary = {



        "snapshot_a": req.snapshot_a,



        "snapshot_b": req.snapshot_b,



        "created_a": created_a,



        "created_b": created_b,



        "entity_count_a": len(entities_a),



        "entity_count_b": len(entities_b),



        "relation_count_a": len(relations_a),



        "relation_count_b": len(relations_b),



        "entities_added": len(entities_added),



        "entities_removed": len(entities_removed),



        "entities_changed": len(entities_changed),



        "relations_added": len(relations_added),



        "relations_removed": len(relations_removed),



        "relations_changed": len(relations_changed),



        "total_changes": len(entities_added) + len(entities_removed) + len(entities_changed) + len(relations_added) + len(relations_removed) + len(relations_changed),



    }







    return GraphCompareResponse(



        summary=summary,



        entities_added=entities_added[:100],



        entities_removed=entities_removed[:100],



        entities_changed=entities_changed[:100],



        relations_added=relations_added[:100],



        relations_removed=relations_removed[:100],



        relations_changed=relations_changed[:100],



    )











