class GraphStreamMetric(BaseModel):



    """Metrics about the streaming system."""



    events_per_minute: float



    entity_events: int



    relation_events: int



    peak_buffer_usage: float











@router.get("/stream/metrics", response_model=GraphStreamMetric)



async def get_stream_metrics() -> GraphStreamMetric:



    """Get streaming system metrics."""



    events = list(_graph_change_buffer)







    # Count by type



    entity_events = sum(1 for e in events if e.event_type.startswith("entity_"))



    relation_events = sum(1 for e in events if e.event_type.startswith("relation_"))







    # Calculate events per minute (approximate)



    buffer_age_estimate = 1.0  # Assume buffer filled over ~1 minute



    events_per_minute = len(events) / buffer_age_estimate if buffer_age_estimate > 0 else 0







    # Peak buffer usage



    peak_usage = len(events) / 1000.0  # maxlen is 1000







    return GraphStreamMetric(



        events_per_minute=events_per_minute,



        entity_events=entity_events,



        relation_events=relation_events,



        peak_buffer_usage=peak_usage,



    )











