# In-memory notification storage



_notification_rules: dict[str, NotificationRule] = {}



_notification_templates: dict[str, NotificationTemplate] = {}



_notification_history: list[NotificationRecord] = []



_notification_history_max = 5000



_last_notification_times: dict[str, datetime] = {}  # For rate limiting











def _render_template(template: str, context: dict[str, Any]) -> str:



    """Render a notification template with context."""



    result = template



    for key, value in context.items():



        result = result.replace(f"{{{key}}}", str(value))



    return result











async def _send_via_webhook(url: str, payload: dict) -> tuple[bool, str]:



    """Send notification via webhook."""



    try:



        # In production, use httpx or similar



        # For now, simulate success



        import json



        payload_str = json.dumps(payload, indent=2)



        return True, f"Webhook sent to {url}: {payload_str[:200]}"



    except Exception as e:



        return False, str(e)











async def _send_via_email(to: list[str], subject: str, body: str) -> tuple[bool, str]:



    """Send notification via email."""



    try:



        # In production, use aiosmtplib or similar



        return True, f"Email sent to {', '.join(to)}: {subject}"



    except Exception as e:



        return False, str(e)











async def _send_via_slack(channel: str, title: str, body: str) -> tuple[bool, str]:



    """Send notification via Slack."""



    try:



        # In production, use slack-sdk



        return True, f"Slack message sent to {channel}: {title}"



    except Exception as e:



        return False, str(e)











async def _send_notification(



    channel: NotificationChannel,



    recipient: str,



    subject: str | None,



    title: str | None,



    body: str,



    priority: NotificationPriority,



    event_type: str | None = None,



    entity_id: str | None = None,



    relation_id: str | None = None,



) -> tuple[bool, str]:



    """Send notification via specified channel."""



    if channel == NotificationChannel.WEBHOOK:



        payload = {



            "subject": subject,



            "title": title,



            "body": body,



            "priority": priority.value,



            "event_type": event_type,



            "entity_id": entity_id,



            "relation_id": relation_id,



        }



        return await _send_via_webhook(recipient, payload)



    elif channel == NotificationChannel.EMAIL:



        return await _send_via_email(recipient.split(","), subject or "", body)



    elif channel == NotificationChannel.SLACK:



        return await _send_via_slack(recipient, title or "", body)



    elif channel == NotificationChannel.WEBSOCKET:



        # WebSocket notifications handled by the streaming system



        return True, f"WebSocket notification queued: {body[:100]}"



    elif channel == NotificationChannel.DISCORD:



        return True, f"Discord notification sent: {body[:100]}"



    elif channel == NotificationChannel.SMS:



        return True, f"SMS notification sent: {body[:100]}"



    else:



        return False, f"Unknown channel: {channel}"











def _check_rate_limit(rule: NotificationRule) -> bool:



    """Check if rate limit allows sending."""



    now = datetime.utcnow()



    rule_key = f"{rule.rule_id}:{rule.channel}"







    # Get last sent time



    last_time = _last_notification_times.get(rule_key)







    if last_time is None:



        _last_notification_times[rule_key] = now



        return True







    # Check if enough time has passed



    hours_since_last = (now - last_time).total_seconds() / 3600



    min_interval = 1.0 / rule.rate_limit_per_hour if rule.rate_limit_per_hour > 0 else 1.0







    if hours_since_last >= min_interval:



        _last_notification_times[rule_key] = now



        return True







    return False











@router.post("/notifications/rules", response_model=NotificationRuleResponse)



async def create_notification_rule(



    request: CreateNotificationRuleRequest,



) -> NotificationRuleResponse:



    """Create a new notification rule.







    Notification rules define when and how notifications are sent.



    Rules can filter by event type and entity type, and support rate limiting.







    Args:



        request: Rule configuration



    """



    import uuid4



    from datetime import datetime







    rule_id = f"rule_{uuid4().hex[:8]}"







    # Validate channel-specific requirements



    if request.channel == NotificationChannel.WEBHOOK and not request.webhook_url:



        raise HTTPException(status_code=400, detail="webhook_url required for webhook channel")



    if request.channel == NotificationChannel.EMAIL and not request.email_to:



        raise HTTPException(status_code=400, detail="email_to required for email channel")



    if request.channel == NotificationChannel.SLACK and not request.slack_channel:



        raise HTTPException(status_code=400, detail="slack_channel required for slack channel")







    rule = NotificationRule(



        rule_id=rule_id,



        name=request.name,



        channel=request.channel,



        event_types=request.event_types,



        entity_type_filter=request.entity_type_filter,



        condition_expr=request.condition_expr,



        template_id=request.template_id,



        webhook_url=request.webhook_url,



        email_to=request.email_to,



        slack_channel=request.slack_channel,



        priority=request.priority,



        rate_limit_per_hour=request.rate_limit_per_hour,



    )







    _notification_rules[rule_id] = rule







    return NotificationRuleResponse(



        rule_id=rule_id,



        name=request.name,



        channel=request.channel,



        enabled=True,



        event_types=request.event_types,



        priority=request.priority,



        created_at=datetime.utcnow(),



    )











