@router.post("/notifications/send", response_model=dict)



async def send_notification(



    request: SendNotificationRequest,



) -> dict:



    """Send a notification immediately.







    Useful for testing or manual notifications.







    Args:



        request: Notification content



    """



    import uuid4



    from datetime import datetime







    notification_id = f"notif_{uuid4().hex[:12]}"







    # Send via channel



    success, message = await _send_notification(



        channel=request.channel,



        recipient=request.recipient,



        subject=request.subject,



        title=request.title,



        body=request.body,



        priority=request.priority,



        event_type=request.event_type,



        entity_id=request.entity_id,



        relation_id=request.relation_id,



    )







    # Record in history



    record = NotificationRecord(



        notification_id=notification_id,



        rule_id=None,



        template_id=None,



        channel=request.channel,



        priority=request.priority,



        status=NotificationStatus.SENT if success else NotificationStatus.FAILED,



        recipient=request.recipient,



        subject=request.subject,



        title=request.title,



        body=request.body,



        event_type=request.event_type,



        entity_id=request.entity_id,



        relation_id=request.relation_id,



        sent_at=datetime.utcnow() if success else None,



        error_message=None if success else message,



    )







    _notification_history.append(record)



    if len(_notification_history) > _notification_history_max:



        _notification_history.pop(0)







    return {



        "notification_id": notification_id,



        "status": "sent" if success else "failed",



        "message": message,



    }











@router.get("/notifications/history", response_model=NotificationListResponse)



async def get_notification_history(



    channel: NotificationChannel | None = None,



    status: NotificationStatus | None = None,



    page: int = 1,



    page_size: int = 20,



) -> NotificationListResponse:



    """Get notification send history.







    Args:



        channel: Filter by channel



        status: Filter by status



        page: Page number (1-indexed)



        page_size: Items per page



    """



    notifications = list(_notification_history)







    # Apply filters



    if channel:



        notifications = [n for n in notifications if n.channel == channel]



    if status:



        notifications = [n for n in notifications if n.status == status]







    # Paginate



    total = len(notifications)



    start = (page - 1) * page_size



    end = start + page_size



    page_items = notifications[start:end]







    return NotificationListResponse(



        notifications=[n.model_dump() for n in page_items],



        total=total,



        page=page,



        page_size=page_size,



    )











@router.get("/notifications/stats", response_model=NotificationStats)



async def get_notification_stats() -> NotificationStats:



    """Get notification statistics."""



    notifications = list(_notification_history)







    total_sent = sum(1 for n in notifications if n.status == NotificationStatus.SENT)



    total_failed = sum(1 for n in notifications if n.status == NotificationStatus.FAILED)







    # By channel



    by_channel: dict[str, int] = {}



    for n in notifications:



        channel_key = n.channel.value



        by_channel[channel_key] = by_channel.get(channel_key, 0) + 1







    # By priority



    by_priority: dict[str, int] = {}



    for n in notifications:



        priority_key = n.priority.value



        by_priority[priority_key] = by_priority.get(priority_key, 0) + 1







    # By status



    by_status: dict[str, int] = {}



    for n in notifications:



        status_key = n.status.value



        by_status[status_key] = by_status.get(status_key, 0) + 1







    return NotificationStats(



        total_sent=total_sent,



        total_failed=total_failed,



        by_channel=by_channel,



        by_priority=by_priority,



        by_status=by_status,



    )











