import gzip



import hashlib



import json



import os



import shutil



import tempfile



from datetime import datetime



from enum import Enum



from pathlib import Path



from typing import Optional







# ── Backup Models ────────────────────────────────────────────────────────────











class BackupType(str, Enum):



    """Type of backup."""



    FULL = "full"



    INCREMENTAL = "incremental"











class BackupStatus(str, Enum):



    """Status of a backup."""



    PENDING = "pending"



    IN_PROGRESS = "in_progress"



    COMPLETED = "completed"



    FAILED = "failed"











class RestoreMode(str, Enum):



    """Mode for restoring a backup."""



    FULL = "full"  # Replace current graph



    MERGE = "merge"  # Add to existing











class BackupRotationPolicy(str, Enum):



    """Backup rotation strategy."""



    NONE = "none"  # Keep all backups



    count_based = "count_based"  # Keep N most recent



    DAILY = "daily"  # Keep daily for N days



    WEEKLY = "weekly"  # Keep weekly for N weeks











class BackupCreateRequest(BaseModel):



    """Request to create a backup."""



    name: Optional[str] = None



    backup_type: BackupType = BackupType.FULL



    description: Optional[str] = None



    include_metadata: bool = True



    compress: bool = True











class BackupInfo(BaseModel):



    """Information about a backup."""



    backup_id: str



    name: Optional[str]



    backup_type: BackupType



    status: BackupStatus



    created_at: datetime



    size_bytes: Optional[int] = 0



    entity_count: int = 0



    relation_count: int = 0



    checksum: Optional[str] = None



    description: Optional[str] = None



    file_path: Optional[str] = None











class BackupListResponse(BaseModel):



    """Response for listing backups."""



    backups: list[dict]



    total: int



    total_size_bytes: int











class RestoreRequest(BaseModel):



    """Request to restore from a backup."""



    restore_mode: RestoreMode = RestoreMode.FULL



    verify_checksum: bool = True



    conflict_resolution: Optional[str] = "skip"  # skip, overwrite, rename











class RestoreResponse(BaseModel):



    """Response for restore operation."""



    status: str



    backup_id: str



    entities_restored: int



    relations_restored: int



    message: str











class BackupPolicyRequest(BaseModel):



    """Request to configure backup rotation policy."""



    policy: BackupRotationPolicy



    max_count: Optional[int] = 10



    retention_days: Optional[int] = 30











# ── Backup Storage ────────────────────────────────────────────────────────────────







# In-memory backup storage



_backup_registry: dict[str, BackupInfo] = {}



_backup_data_store: dict[str, dict] = {}







# Storage directory for file-based backups



_BACKUP_DIR = Path(os.path.join(os.path.dirname(__file__), "..", "..", "data", "backups"))



_BACKUP_DIR.mkdir(parents=True, exist_ok=True)







# Backup rotation policy



_backup_policy: dict = {



    "policy": BackupRotationPolicy.NONE,



    "max_count": 10,



    "retention_days": 30,



}











def _compute_checksum(data: dict) -> str:



    """Compute SHA256 checksum for data."""



    json_str = json.dumps(data, sort_keys=True, default=str)



    return hashlib.sha256(json_str.encode()).hexdigest()











def _get_all_entities() -> list[dict]:



    """Get all entities from the graph."""



    return [



        {"entity_id": eid, **entity}



        for eid, entity in _entities.items()



    ]











def _get_all_relations() -> list[dict]:



    """Get all relations from the graph."""



    return [



        {"relation_id": rid, **relation}



        for rid, relation in _relations.items()



    ]











def _apply_backup_rotation():



    """Apply backup rotation policy to clean up old backups."""



    policy = _backup_policy.get("policy", BackupRotationPolicy.NONE)







    if policy == BackupRotationPolicy.NONE:



        return







    if policy == BackupRotationPolicy.COUNT_BASED:



        max_count = _backup_policy.get("max_count", 10)



        backups = sorted(_backup_registry.values(), key=lambda b: b.created_at, reverse=True)



        if len(backups) > max_count:



            for backup in backups[max_count:]:



                _delete_backup_files(backup.backup_id)







    elif policy in (BackupRotationPolicy.DAILY, BackupRotationPolicy.WEEKLY):



        retention_days = _backup_policy.get("retention_days", 30)



        cutoff = datetime.now()



        if policy == BackupRotationPolicy.WEEKLY:



            retention_days *= 7







        for backup in list(_backup_registry.values()):



            age = (cutoff - backup.created_at).days



            if age > retention_days:



                _delete_backup_files(backup.backup_id)











def _delete_backup_files(backup_id: str):



    """Delete backup files and remove from registry."""



    if backup_id in _backup_registry:



        backup = _backup_registry[backup_id]



        if backup.file_path and os.path.exists(backup.file_path):



            try:



                os.remove(backup.file_path)



            except Exception:



                pass







        if backup_id in _backup_data_store:



            del _backup_data_store[backup_id]







        del _backup_registry[backup_id]











# ── Backup Endpoints ─────────────────────────────────────────────────────











@router.post("/graph/backup", response_model=BackupInfo)



async def create_backup(request: BackupCreateRequest) -> BackupInfo:



    """Create a new backup of the knowledge graph.







    Creates a backup of all entities and relations. Supports full backups



    (all data) and incremental backups (changes since last backup).







    Args:



        request: Backup configuration







    Returns:



        Backup information including ID, size, and entity/relation counts



    """



    import uuid



    from datetime import datetime







    backup_id = str(uuid.uuid4())[:8]



    timestamp = datetime.now()







    # Collect data to backup



    backup_data = {



        "backup_id": backup_id,



        "name": request.name,



        "backup_type": request.backup_type.value,



        "created_at": timestamp.isoformat(),



        "description": request.description,



        "entities": _get_all_entities() if request.backup_type == BackupType.FULL else [],



        "relations": _get_all_relations() if request.backup_type == BackupType.FULL else [],



    }







    # Calculate counts and checksum



    entity_count = len(backup_data.get("entities", []))



    relation_count = len(backup_data.get("relations", []))



    checksum = _compute_checksum(backup_data)







    # Store backup data in memory



    _backup_data_store[backup_id] = backup_data







    # Optionally save to file



    file_path = None



    size_bytes = 0



    if request.compress:



        try:



            filename = f"backup_{backup_id}.json.gz"



            file_path = str(_BACKUP_DIR / filename)







            json_data = json.dumps(backup_data, default=str)



            with gzip.open(file_path, "wt", encoding="utf-8") as f:



                f.write(json_data)







            size_bytes = os.path.getsize(file_path)



        except Exception as e:



            # Fallback to uncompressed storage



            file_path = None







    # Create backup info



    backup_info = BackupInfo(



        backup_id=backup_id,



        name=request.name,



        backup_type=request.backup_type,



        status=BackupStatus.COMPLETED,



        created_at=timestamp,



        size_bytes=size_bytes or len(json.dumps(backup_data, default=str)),



        entity_count=entity_count,



        relation_count=relation_count,



        checksum=checksum,



        description=request.description,



        file_path=file_path,



    )







    _backup_registry[backup_id] = backup_info







    # Apply rotation policy



    _apply_backup_rotation()







    return backup_info











@router.get("/graph/backups", response_model=BackupListResponse)



async def list_backups(



    limit: int = 50,



    offset: int = 0,



) -> BackupListResponse:



    """List all backups.







    Returns a paginated list of all backups with their metadata.







    Args:



        limit: Maximum number of backups to return



        offset: Number of backups to skip







    Returns:



        List of backups with total count and size



    """



    backups = sorted(



        _backup_registry.values(),



        key=lambda b: b.created_at,



        reverse=True,



    )







    total = len(backups)



    total_size_bytes = sum(b.size_bytes or 0 for b in backups)







    page_items = backups[offset : offset + limit]







    return BackupListResponse(



        backups=[b.model_dump() for b in page_items],



        total=total,



        total_size_bytes=total_size_bytes,



    )











@router.get("/graph/backups/{backup_id}", response_model=BackupInfo)



async def get_backup(backup_id: str) -> BackupInfo:



    """Get detailed information about a specific backup.







    Returns metadata about the backup including size, counts, and checksum.







    Args:



        backup_id: ID of the backup







    Returns:



        Backup information



    """



    if backup_id not in _backup_registry:



        raise HTTPException(status_code=404, detail=f"Backup {backup_id} not found")







    return _backup_registry[backup_id]











@router.get("/graph/backups/{backup_id}/download")



async def download_backup(backup_id: str) -> FileResponse:



    """Download a backup file.







    Returns the full backup data as a JSON file download.







    Args:



        backup_id: ID of the backup







    Returns:



        File response with backup data



    """



    if backup_id not in _backup_registry:



        raise HTTPException(status_code=404, detail=f"Backup {backup_id} not found")







    backup = _backup_registry[backup_id]







    # Check if there's a file-based backup



    if backup.file_path and os.path.exists(backup.file_path):



        return FileResponse(



            path=backup.file_path,



            media_type="application/gzip",



            filename=f"backup_{backup_id}.json.gz",



        )







    # Generate in-memory backup



    backup_data = _backup_data_store.get(backup_id, {})







    # Create temporary file



    temp_file = tempfile.NamedTemporaryFile(



        mode="w",



        delete=False,



        suffix=".json",



        encoding="utf-8",



    )



    json.dump(backup_data, temp_file, default=str)



    temp_file.close()







    return FileResponse(



        path=temp_file.name,



        media_type="application/json",



        filename=f"backup_{backup_id}.json",



        background=str(temp_file.name),



    )











@router.delete("/graph/backups/{backup_id}", response_model=dict)



async def delete_backup(backup_id: str) -> dict:



    """Delete a backup.







    Removes a backup and its associated data from storage.







    Args:



        backup_id: ID of the backup to delete







    Returns:



        Confirmation message



    """



    if backup_id not in _backup_registry:



        raise HTTPException(status_code=404, detail=f"Backup {backup_id} not found")







    _delete_backup_files(backup_id)







    return {



        "status": "deleted",



        "backup_id": backup_id,



    }











@router.post("/graph/backups/{backup_id}/restore", response_model=RestoreResponse)



async def restore_backup(



    backup_id: str,



    request: RestoreRequest,



) -> RestoreResponse:



    """Restore the knowledge graph from a backup.







    Restores entities and relations from a backup. Supports full restore (replaces



    current graph) and merge mode (adds to existing).







    Args:



        backup_id: ID of the backup to restore



        request: Restore configuration







    Returns:



        Restore result with counts



    """



    if backup_id not in _backup_registry:



        raise HTTPException(status_code=404, detail=f"Backup {backup_id} not found")







    backup = _backup_registry[backup_id]



    backup_data = _backup_data_store.get(backup_id)







    if not backup_data:



        raise HTTPException(status_code=404, detail="Backup data not found")







    # Verify checksum if requested



    if request.verify_checksum and backup.checksum:



        computed = _compute_checksum(backup_data)



        if computed != backup.checksum:



            raise HTTPException(



                status_code=400,



                detail="Backup checksum verification failed",



            )







    entities = backup_data.get("entities", [])



    relations = backup_data.get("relations", [])







    entities_restored = 0



    relations_restored = 0







    if request.restore_mode == RestoreMode.FULL:



        # Clear current graph and restore



        _entities.clear()



        _relations.clear()







        for entity in entities:



            eid = entity.get("entity_id")



            if eid:



                _entities[eid] = entity



                entities_restored += 1







        for relation in relations:



            rid = relation.get("relation_id")



            if rid:



                _relations[rid] = relation



                relations_restored += 1







    else:



        # Merge mode - add to existing



        resolution = request.conflict_resolution or "skip"







        for entity in entities:



            eid = entity.get("entity_id")



            if eid:



                if resolution == "skip" and eid in _entities:



                    continue



                elif resolution == "rename":



                    # Find unique ID



                    original_eid = eid



                    counter = 1



                    while eid in _entities:



                        eid = f"{original_eid}_restored_{counter}"



                        counter += 1



                    entity["entity_id"] = eid







                _entities[eid] = entity



                entities_restored += 1







        for relation in relations:



            rid = relation.get("relation_id")



            if rid:



                if resolution == "skip" and rid in _relations:



                    continue



                elif resolution == "rename":



                    original_rid = rid



                    counter = 1



                    while rid in _relations:



                        rid = f"{original_rid}_restored_{counter}"



                        counter += 1



                    relation["relation_id"] = rid







                _relations[rid] = relation



                relations_restored += 1







    return RestoreResponse(



        status="restored",



        backup_id=backup_id,



        entities_restored=entities_restored,



        relations_restored=relations_restored,



        message=f"Restored {entities_restored} entities and {relations_restored} relations",



    )











@router.post("/graph/backups/policy", response_model=dict)



async def set_backup_policy(request: BackupPolicyRequest) -> dict:



    """Configure backup rotation policy.







    Sets the policy for automatic backup cleanup and rotation.







    Args:



        request: Policy configuration







    Returns:



        Confirmation message



    """



    _backup_policy["policy"] = request.policy



    _backup_policy["max_count"] = request.max_count



    _backup_policy["retention_days"] = request.retention_days







    # Apply policy immediately



    _apply_backup_rotation()







    return {



        "status": "updated",



        "policy": request.policy.value,



        "max_count": request.max_count,



        "retention_days": request.retention_days,



    }











@router.get("/graph/backups/policy", response_model=dict)



async def get_backup_policy() -> dict:



    """Get current backup rotation policy."""



    return _backup_policy.copy()











# ── Scheduled Backup ────────────────────────────────────────────────────







class ScheduledBackupConfig(BaseModel):



    """Configuration for scheduled backups."""



    enabled: bool = False



    interval_hours: int = 24



    max_backups: int = 7



    backup_type: BackupType = BackupType.FULL



    include_metadata: bool = True



    compress: bool = True











_scheduled_backup_config: ScheduledBackupConfig = ScheduledBackupConfig()











@router.post("/graph/backup/schedule", response_model=dict)



async def configure_scheduled_backup(config: ScheduledBackupConfig) -> dict:



    """Configure scheduled automatic backups.







    Sets up periodic automatic backups of the knowledge graph.







    Args:



        config: Schedule configuration







    Returns:



        Confirmation message



    """



    global _scheduled_backup_config



    _scheduled_backup_config = config







    return {



        "status": "configured",



        "enabled": config.enabled,



        "interval_hours": config.interval_hours,



        "max_backups": config.max_backups,



    }











@router.get("/graph/backup/schedule", response_model=dict)



async def get_scheduled_backup_config() -> dict:



    """Get scheduled backup configuration."""



    return _scheduled_backup_config.model_dump()











@router.post("/graph/backup/schedule/trigger", response_model=BackupInfo)



async def trigger_scheduled_backup() -> BackupInfo:



    """Manually trigger a scheduled backup.







    Creates a backup using the scheduled configuration.



    Useful for testing or immediate backup before major changes.



    """



    config = _scheduled_backup_config







    request = BackupCreateRequest(



        name=f"Scheduled backup",



        backup_type=config.backup_type,



        include_metadata=config.include_metadata,



        compress=config.compress,



    )







    backup = await create_backup(request)







    # Update rotation based on max_backups



    _backup_policy["policy"] = BackupRotationPolicy.COUNT_BASED



    _backup_policy["max_count"] = config.max_backups



    _apply_backup_rotation()







    return backup











