# ║           ITERATION 101: Signed Payload Validation System                 ║



# ╚══════════════════════════════════════════════════════════════════════════════╝



# Production-grade security for external API integrations







import hmac



import hashlib



import base64



import json



import time



from datetime import datetime, timedelta



from typing import Optional



from pydantic import BaseModel











# ── Signature Configuration ───────────────────────────────────────────────







class SignatureConfig(BaseModel):



    """Configuration for payload signing."""



    secret_key: str = "default-secret-key"



    algorithm: str = "sha256"



    timestamp_tolerance_seconds: int = 300  # 5 minutes











_signature_config: SignatureConfig = SignatureConfig()











# ── Signed Payload Models ──────────────────────────────────────────────────







class SignedPayloadRequest(BaseModel):



    """Request payload to sign."""



    payload: dict



    include_timestamp: bool = True











class SignedPayloadResponse(BaseModel):



    """Response with signature."""



    payload: dict



    signature: str



    timestamp: str



    algorithm: str











class VerifySignatureRequest(BaseModel):



    """Request to verify a signature."""



    payload: dict



    signature: str



    timestamp: str



    algorithm: str = "sha256"











class VerifySignatureResponse(BaseModel):



    """Result of signature verification."""



    valid: bool



    reason: Optional[str] = None



    timestamp_valid: bool = True











# ── Core Signature Functions ─────────────────────────────────────────







def _generate_signature(payload: dict, timestamp: str, secret: str, algorithm: str = "sha256") -> str:



    """Generate HMAC signature for payload.







    Creates a signature by combining payload with timestamp using HMAC.







    Args:



        payload: Data to sign



        timestamp: ISO format timestamp



        secret: Secret key for signing



        algorithm: Hash algorithm (sha256/sha512)







    Returns:



        Base64 encoded signature



    """



    # Create canonical payload string



    payload_str = json.dumps(payload, sort_keys=True, separators=(',', ':'))







    # Combine payload and timestamp



    message = f"{timestamp}:{payload_str}"







    # Generate HMAC



    if algorithm == "sha512":



        hm = hmac.new(secret.encode(), message.encode(), hashlib.sha512)



    else:



        hm = hmac.new(secret.encode(), message.encode(), hashlib.sha256)







    # Return base64 encoded signature



    return base64.b64encode(hm.digest()).decode()











def _verify_signature(payload: dict, timestamp: str, signature: str, secret: str, algorithm: str = "sha256") -> tuple[bool, Optional[str]]:



    """Verify HMAC signature.







    Args:



        payload: Original payload



        timestamp: ISO timestamp from request



        signature: Base64 signature to verify



        secret: Secret key



        algorithm: Hash algorithm







    Returns:



        (is_valid, reason_if_invalid)



    """



    try:



        expected = _generate_signature(payload, timestamp, secret, algorithm)







        if not hmac.compare_digest(expected, signature):



            return False, "signature_mismatch"







        # Check timestamp validity (replay attack prevention)



        try:



            request_time = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))



            now = datetime.now(request_time.tzinfo)



            diff = abs((now - request_time).total_seconds())







            if diff > _signature_config.timestamp_tolerance_seconds:



                return False, "timestamp_expired"



        except (ValueError, TypeError):



            return False, "invalid_timestamp"







        return True, None







    except Exception as e:



        return False, f"verification_error: {str(e)}"











# ── Payload Signing APIs ───────────────────────────────────────────────







@router.post("/graph/signature/sign", response_model=SignedPayloadResponse)



async def sign_payload(request: SignedPayloadRequest) -> SignedPayloadResponse:



    """Sign a payload for secure transmission.







    Creates a signed payload that can be verified by recipients.



    The signature proves the payload wasn't tampered with.







    Args:



        request: Payload to sign







    Returns:



        Signed payload with signature and timestamp



    """



    timestamp = datetime.now().isoformat()







    signature = _generate_signature(



        request.payload,



        timestamp,



        _signature_config.secret_key,



        _signature_config.algorithm



    )







    return SignedPayloadResponse(



        payload=request.payload,



        signature=signature,



        timestamp=timestamp,



        algorithm=_signature_config.algorithm



    )











@router.post("/graph/signature/verify", response_model=VerifySignatureResponse)



async def verify_signature(request: VerifySignatureRequest) -> VerifySignatureResponse:



    """Verify a signed payload.







    Validates that the payload hasn't been tampered with



    and that the timestamp is still valid (prevents replay attacks).







    Args:



        request: Payload and signature to verify







    Returns:



        Verification result



    """



    is_valid, reason = _verify_signature(



        request.payload,



        request.timestamp,



        request.signature,



        _signature_config.secret_key,



        request.algorithm



    )







    return VerifySignatureResponse(



        valid=is_valid,



        reason=reason,



        timestamp_valid=(reason != "timestamp_expired")



    )











@router.post("/graph/signature/config", response_model=dict)



async def configure_signature(config: SignatureConfig) -> dict:



    """Configure signature settings.







    Args:



        config: Signature configuration







    Returns:



        Confirmation



    """



    global _signature_config



    _signature_config = config







    return {"status": "configured", "algorithm": config.algorithm}











@router.get("/graph/signature/config", response_model=dict)



async def get_signature_config() -> dict:



    """Get signature configuration."""



    # Don't expose the secret key



    return {



        "algorithm": _signature_config.algorithm,



        "timestamp_tolerance_seconds": _signature_config.timestamp_tolerance_seconds,



    }











# ── Webhook with Signature Verification ───────────────────────────────







class WebhookPayload(BaseModel):



    """Incoming webhook payload."""



    event: str



    data: dict



    signature: str



    timestamp: str











class WebhookResponse(BaseModel):



    """Response from webhook processing."""



    accepted: bool



    reason: Optional[str] = None











@router.post("/graph/webhook", response_model=WebhookResponse)



async def receive_webhook(payload: WebhookPayload) -> WebhookResponse:



    """Receive and verify a signed webhook.







    Accepts webhooks from external systems with signature verification.



    Validates both integrity and freshness of the payload.







    Args:



        payload: Webhook payload







    Returns:



        Acceptance result



    """



    # Verify signature



    is_valid, reason = _verify_signature(



        {"event": payload.event, "data": payload.data},



        payload.timestamp,



        payload.signature,



        _signature_config.secret_key,



        _signature_config.algorithm



    )







    if not is_valid:



        return WebhookResponse(accepted=False, reason=reason)







    # Process the webhook event



    # (Here would be event-specific processing)



    return WebhookResponse(accepted=True)











# ── Batch Signature Operations ──────────────────────────────────────







class BatchSignRequest(BaseModel):



    """Request to sign multiple payloads."""



    payloads: list[dict]











class BatchSignResponse(BaseModel):



    """Response with multiple signatures."""



    signed_payloads: list[SignedPayloadResponse]











@router.post("/graph/signature/sign/batch", response_model=BatchSignResponse)



async def batch_sign_payloads(request: BatchSignRequest) -> BatchSignResponse:



    """Sign multiple payloads at once.







    Useful for batch processing or pre-generating



    signed payloads for scheduled transmission.







    Args:



        request: List of payloads to sign







    Returns:



        List of signed payloads



    """



    timestamp = datetime.now().isoformat()







    signed = []



    for payload in request.payloads:



        signature = _generate_signature(



            payload,



            timestamp,



            _signature_config.secret_key,



            _signature_config.algorithm



        )







        signed.append(SignedPayloadResponse(



            payload=payload,



            signature=signature,



            timestamp=timestamp,



            algorithm=_signature_config.algorithm



        ))







    return BatchSignResponse(signed_payloads=signed)











class BatchVerifyRequest(BaseModel):



    """Request to verify multiple signatures."""



    payloads: list[VerifySignatureRequest]











class BatchVerifyResponse(BaseModel):



    """Results of batch verification."""



    results: list[VerifySignatureResponse]



    valid_count: int



    invalid_count: int











@router.post("/graph/signature/verify/batch", response_model=BatchVerifyResponse)



async def batch_verify_signatures(request: BatchVerifyRequest) -> BatchVerifyResponse:



    """Verify multiple signatures at once.







    Args:



        request: List of payloads to verify







    Returns:



        Verification results



    """



    results = []



    valid_count = 0



    invalid_count = 0







    for item in request.payloads:



        is_valid, reason = _verify_signature(



            item.payload,



            item.timestamp,



            item.signature,



            _signature_config.secret_key,



            item.algorithm



        )







        if is_valid:



            valid_count += 1



        else:



            invalid_count += 1







        results.append(VerifySignatureResponse(



            valid=is_valid,



            reason=reason,



            timestamp_valid=(reason != "timestamp_expired")



        ))







    return BatchVerifyResponse(



        results=results,



        valid_count=valid_count,



        invalid_count=invalid_count



    )











