# In-memory template storage



_export_templates: dict[str, ExportTemplate] = {}



_template_counter = 0











def _generate_template_id() -> str:



    """Generate unique template ID."""



    global _template_counter



    _template_counter += 1



    return f"tpl_{_template_counter:06d}"











def _apply_template_filters(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[list[dict], list[dict]]:



    """Apply template filters to entities and relations."""



    filtered_entities = entities



    filtered_relations = relations







    # Apply node filter



    if template.node_filter:



        try:



            filtered_entities = [



                e for e in filtered_entities



                if eval(template.node_filter, {"e": e})



            ]



        except Exception:



            pass







    # Apply edge filter



    if template.edge_filter:



        try:



            filtered_relations = [



                r for r in filtered_relations



                if eval(template.edge_filter, {"r": r})



            ]



        except Exception:



            pass







    # Apply max depth



    if template.max_depth:



        max_depth = template.max_depth



        entity_ids = {e["id"] for e in filtered_entities[:max_depth * 2]} if filtered_entities else set()



        filtered_entities = filtered_entities[:max_depth]



        filtered_relations = [



            r for r in filtered_relations



            if r.get("source") in entity_ids and r.get("target") in entity_ids



        ]







    return filtered_entities, filtered_relations











def _export_to_json(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[str, int]:



    """Export graph to JSON format."""



    data = {



        "graph": {



            "entities": [],



            "relations": []



        }



    }







    for entity in entities:



        node = {"id": entity.get("id"), "type": entity.get("type")}



        if template.include_properties:



            node["properties"] = entity.get("properties", {})



        if template.include_metadata:



            node["metadata"] = entity.get("metadata", {})



        if template.include_timestamps:



            node["created_at"] = entity.get("created_at")



            if template.include_metadata:



                node["updated_at"] = entity.get("updated_at")



        data["graph"]["entities"].append(node)







    for relation in relations:



        edge = {



            "source": relation.get("source"),



            "target": relation.get("target"),



            "relation_type": relation.get("relation_type")



        }



        if template.include_properties:



            edge["properties"] = relation.get("properties", {})



        if template.include_metadata:



            edge["metadata"] = relation.get("metadata", {})



        data["graph"]["relations"].append(edge)







    json_str = json.dumps(data, indent=2, ensure_ascii=False)



    return json_str, len(entities) + len(relations)











def _export_to_csv(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[str, int]:



    """Export graph to CSV format."""



    import io



    import csv







    output = io.StringIO()







    # Entity CSV



    writer = csv.writer(output)



    writer.writerow(["# Entities"])



    headers = ["id", "type"]



    if template.include_properties:



        headers.extend(["properties"])



    if template.include_metadata:



        headers.extend(["metadata"])



    if template.include_timestamps:



        headers.extend(["created_at", "updated_at"])



    writer.writerow(headers)







    for entity in entities:



        row = [entity.get("id", ""), entity.get("type", "")]



        if template.include_properties:



            row.append(json.dumps(entity.get("properties", {})))



        if template.include_metadata:



            row.append(json.dumps(entity.get("metadata", {})))



        if template.include_timestamps:



            row.append(str(entity.get("created_at", "")))



            if template.include_metadata:



                row.append(str(entity.get("updated_at", "")))



        writer.writerow(row)







    writer.writerow([])



    writer.writerow(["# Relations"])



    rel_headers = ["source", "target", "relation_type"]



    if template.include_properties:



        rel_headers.append("properties")



    writer.writerow(rel_headers)







    for relation in relations:



        row = [



            relation.get("source", ""),



            relation.get("target", ""),



            relation.get("relation_type", "")



        ]



        if template.include_properties:



            row.append(json.dumps(relation.get("properties", {})))



        writer.writerow(row)







    return output.getvalue(), len(entities) + len(relations)











def _export_to_mermaid(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[str, int]:



    """Export graph to Mermaid diagram format."""



    lines = ["```mermaid", "flowchart TD"]







    # Node definitions



    for entity in entities:



        entity_id = entity.get("id", "")



        entity_type = entity.get("type", "entity")



        label = entity.get("properties", {}).get("name", entity_id)



        lines.append(f'    {entity_id}["{label} ({entity_type})"]')







    lines.append("")







    # Edge definitions



    for relation in relations:



        source = relation.get("source", "")



        target = relation.get("target", "")



        rel_type = relation.get("relation_type", "related")



        lines.append(f'    {source} -->|{rel_type}| {target}')







    lines.append("```")







    return "\n".join(lines), len(entities) + len(relations)











def _export_to_dot(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[str, int]:



    """Export graph to DOT format."""



    lines = ["digraph KnowledgeGraph {", "  rankdir=LR;"]







    # Node definitions



    for entity in entities:



        entity_id = entity.get("id", "")



        entity_type = entity.get("type", "entity")



        label = entity.get("properties", {}).get("name", entity_id)



        dot_id = entity_id.replace("-", "_")



        lines.append(f'  {dot_id} [label="{label}", type="{entity_type}"];')







    lines.append("")







    # Edge definitions



    for relation in relations:



        source = relation.get("source", "").replace("-", "_")



        target = relation.get("target", "").replace("-", "_")



        rel_type = relation.get("relation_type", "related")



        lines.append(f'  {source} -> {target} [label="{rel_type}"];')







    lines.append("}")







    return "\n".join(lines), len(entities) + len(relations)











def _export_to_markdown(



    entities: list[dict],



    relations: list[dict],



    template: ExportTemplate



) -> tuple[str, int]:



    """Export graph to Markdown documentation."""



    lines = ["# Knowledge Graph Export\n"]







    # Summary statistics



    lines.append("## Summary\n")



    lines.append(f"- Total Entities: {len(entities)}")



    lines.append(f"- Total Relations: {len(relations)}")



    lines.append(f"- Export Date: {datetime.now().isoformat()}\n")







    # Entity tables



    lines.append("## Entities\n")



    lines.append("| ID | Type | Properties |")



    lines.append("|---|---|---|")



    for entity in entities:



        entity_id = entity.get("id", "")



        entity_type = entity.get("type", "")



        props = ", ".join([



            f"{k}={v}" for k, v in (entity.get("properties", {})).items()



        ][:3])



        lines.append(f"| {entity_id} | {entity_type} | {props} |")







    lines.append("\n## Relations\n")



    lines.append("| Source | Target | Type |")



    lines.append("|---|---|---|")



    for relation in relations:



        source = relation.get("source", "")



        target = relation.get("target", "")



        rel_type = relation.get("relation_type", "")



        lines.append(f"| {source} | {target} | {rel_type} |")







    return "\n".join(lines), len(entities) + len(relations)











