# =============================================================================



# GRAPH ANALYTICS - Iteration 103



# =============================================================================







from enum import Enum



from collections import defaultdict, deque



from typing import Optional



import heapq



import math











class AnalyticsMetric(str, Enum):



    STATISTICS = "statistics"



    DEGREE = "degree"



    CENTRALITY = "centrality"



    PATH = "path"



    CONNECTIVITY = "connectivity"



    COMMUNITY = "community"











class CentralityMetric(str, Enum):



    DEGREE = "degree"



    BETWEENNESS = "betweenness"



    CLOSENESS = "closeness"











class CentralityMetric(str, Enum):



    DEGREE = "degree"



    BETWEENNESS = "betweenness"



    CLOSENESS = "closeness"











# =============================================================================



# Graph Analytics Engine



# =============================================================================







class GraphAnalyticsEngine:



    """Core analytics engine for knowledge graph analysis."""







    def __init__(self):



        self.graph: Dict[str, Dict[str, Any]] = {}







    def load_graph(self, nodes: List[Dict], edges: List[Dict]) -> None:



        """Load nodes and edges into internal graph structure."""



        self.graph = defaultdict(lambda: {"in": defaultdict(int), "out": defaultdict(int)})







        # Build adjacency



        for node in nodes:



            node_id = node.get("id") or node.get("node_id")



            if node_id:



                self.graph[node_id] = {"in": defaultdict(int), "out": defaultdict(int), "data": node}







        # Add edges



        for edge in edges:



            source = edge.get("source")



            target = edge.get("target")



            if source and target:



                self.graph[source]["out"][target] += 1



                self.graph[target]["in"][source] += 1







    def compute_statistics(self) -> GraphStatistics:



        """Compute basic graph statistics."""



        total_nodes = len(self.graph)



        total_edges = sum(



            sum(self.graph[n]["out"].values()) for n in self.graph



        ) // 2  # Undirected count







        avg_degree = sum(



            len(self.graph[n]["out"]) + len(self.graph[n]["in"])



            for n in self.graph



        ) / total_nodes if total_nodes > 0 else 0







        # Max possible edges for density



        max_edges = total_nodes * (total_nodes - 1) // 2



        density = total_edges / max_edges if max_edges > 0 else 0







        # Connected components



        components = self._find_connected_components()



        connected_components = len(components)







        diameter = None



        if connected_components == 1 and total_nodes <= 100:



            # Only compute for small connected graphs



            diameter = self._compute_diameter()







        return GraphStatistics(



            total_nodes=total_nodes,



            total_edges=total_edges,



            density=round(density, 4),



            avg_degree=round(avg_degree, 2),



            connected_components=connected_components,



            is_directed=False,



            is_connected=(connected_components == 1),



            diameter=diameter



        )







    def _find_connected_components(self) -> List[Set[str]]:



        """Find all connected components using BFS."""



        visited = set()



        components = []







        for start in self.graph:



            if start not in visited:



                component = set()



                queue = deque([start])



                while queue:



                    node = queue.popleft()



                    if node in visited:



                        continue



                    visited.add(node)



                    component.add(node)



                    # Get all neighbors



                    for neighbor in self.graph[node]["out"]:



                        if neighbor not in visited:



                            queue.append(neighbor)



                    for neighbor in self.graph[node]["in"]:



                        if neighbor not in visited:



                            queue.append(neighbor)



                components.append(component)







        return components







    def _compute_diameter(self) -> int:



        """Compute graph diameter using BFS from all nodes."""



        if not self.graph:



            return 0







        max_distance = 0







        for start in self.graph:



            distances = self._bfs_distances(start)



            if distances:



                max_distance = max(max_distance, max(distances.values()))







        return max_distance







    def _bfs_distances(self, start: str) -> Dict[str, int]:



        """Compute shortest distances from start to all reachable nodes."""



        distances = {start: 0}



        queue = deque([start])







        while queue:



            node = queue.popleft()



            distance = distances[node]







            # All neighbors



            neighbors = set(self.graph[node]["out"].keys()) | set(self.graph[node]["in"].keys())







            for neighbor in neighbors:



                if neighbor not in distances:



                    distances[neighbor] = distance + 1



                    queue.append(neighbor)







        return distances







    def compute_degree_analysis(self, node_ids: Optional[List[str]] = None) -> List[DegreeAnalysis]:



        """Compute degree analysis for specified nodes."""



        target_nodes = node_ids if node_ids else list(self.graph.keys())







        results = []



        for node_id in target_nodes:



            if node_id in self.graph:



                in_deg = len(self.graph[node_id]["in"])



                out_deg = len(self.graph[node_id]["out"])



                results.append(DegreeAnalysis(



                    node_id=node_id,



                    in_degree=in_deg,



                    out_degree=out_deg,



                    total_degree=in_deg + out_deg



                ))







        return sorted(results, key=lambda x: x.total_degree, reverse=True)







    def compute_degree_distribution(self) -> List[DegreeDistribution]:



        """Compute degree distribution histogram."""



        degree_counts = defaultdict(int)







        for node in self.graph:



            total_deg = len(self.graph[node]["in"]) + len(self.graph[node]["out"])



            degree_counts[total_deg] += 1







        total_nodes = len(self.graph)



        distribution = []







        for degree in sorted(degree_counts.keys()):



            count = degree_counts[degree]



            distribution.append(DegreeDistribution(



                degree=degree,



                count=count,



                percentage=round(count / total_nodes * 100, 2) if total_nodes > 0 else 0



            ))







        return distribution







    def compute_centrality(



        self,



        metric: CentralityMetric = CentralityMetric.DEGREE,



        node_ids: Optional[List[str]] = None



    ) -> List[CentralityScore]:



        """Compute centrality metrics."""



        target_nodes = node_ids if node_ids else list(self.graph.keys())



        scores = {}







        if metric == CentralityMetric.DEGREE:



            for node in target_nodes:



                if node in self.graph:



                    deg = len(self.graph[node]["in"]) + len(self.graph[node]["out"])



                    scores[node] = deg / (len(self.graph) - 1) if len(self.graph) > 1 else 0



        elif metric == CentralityMetric.CLOSENESS:



            scores = self._compute_closeness_centrality(target_nodes)



        elif metric == CentralityMetric.BETWEENNESS:



            scores = self._compute_betweenness_centrality(target_nodes)







        # Sort and rank



        sorted_nodes = sorted(scores.items(), key=lambda x: x[1], reverse=True)



        results = []



        for rank, (node_id, centrality) in enumerate(sorted_nodes, 1):



            results.append(CentralityScore(



                node_id=node_id,



                centrality=round(centrality, 4),



                rank=rank



            ))







        return results







    def _compute_closeness_centrality(self, node_ids: List[str]) -> Dict[str, float]:



        """Compute closeness centrality."""



        scores = {}



        n = len(self.graph)







        for node in node_ids:



            if node not in self.graph:



                continue







            distances = self._bfs_distances(node)



            # Remove self



            distances.pop(node, None)







            if distances:



                total_dist = sum(distances.values())



                scores[node] = (len(distances) - 1) / total_dist if total_dist > 0 else 0



            else:



                scores[node] = 0







        return scores







    def _compute_betweenness_centrality(self, node_ids: List[str]) -> Dict[str, float]:



        """Approximate betweenness centrality using sampling."""



        scores = {n: 0.0 for n in node_ids if n in self.graph}







        if not self.graph:



            return scores







        # Sample sources for approximation



        sources = list(self.graph.keys())



        total = len(sources)







        for source in sources:



            if source not in self.graph:



                continue







            distances = self._bfs_distances(source)



            paths = self._find_all_shortest_paths(source, distances)







            for target, path_list in paths.items():



                for path in path_list:



                    # Skip endpoints



                    for node in path[1:-1]:



                        if node in scores:



                            scores[node] += 1 / len(path_list)







        # Normalize



        normalizer = 2 / ((n - 1) * (n - 2)) if n > 2 else 1



        for node in scores:



            scores[node] *= normalizer







        return scores







    def _find_all_shortest_paths(



        self,



        source: str,



        distances: Dict[str, int]



    ) -> Dict[str, List[List[str]]]:



        """Find all shortest paths from source."""



        if not distances:



            return {}







        paths = defaultdict(list)







        for target in distances:



            if target == source or distances[target] == 0:



                continue



            path = self._reconstruct_path(source, target, distances)



            if path:



                paths[target].append(path)







        return paths







    def _reconstruct_path(



        self,



        source: str,



        target: str,



        distances: Dict[str, int]



    ) -> Optional[List[str]]:



        """Reconstruct a shortest path."""



        if target not in distances:



            return None







        path = [target]



        current = target



        target_dist = distances[target]







        while current != source:



            neighbors = set(self.graph[current]["in"].keys()) | set(self.graph[current]["out"].keys())



            for neighbor in neighbors:



                if neighbor in distances and distances[neighbor] == target_dist - 1:



                    path.append(neighbor)



                    current = neighbor



                    target_dist -= 1



                    break



            else:



                return None







        return list(reversed(path))







    def find_shortest_path(self, source: str, target: str, max_depth: int = 20) -> PathResult:



        """Find shortest path between two nodes."""



        if source == target:



            return PathResult(



                source=source,



                target=target,



                distance=0,



                path=[source],



                is_reachable=True



            )







        if source not in self.graph or target not in self.graph:



            return PathResult(



                source=source,



                target=target,



                distance=-1,



                path=[],



                is_reachable=False



            )







        # BFS for shortest path



        queue = deque([(source, [source])])



        visited = {source}







        while queue:



            node, path = queue.popleft()







            if len(path) > max_depth:



                continue







            neighbors = set(self.graph[node]["out"].keys()) | set(self.graph[node]["in"].keys())







            for neighbor in neighbors:



                if neighbor == target:



                    return PathResult(



                        source=source,



                        target=target,



                        distance=len(path),



                        path=path + [neighbor],



                        is_reachable=True



                    )







                if neighbor not in visited:



                    visited.add(neighbor)



                    queue.append((neighbor, path + [neighbor]))







        return PathResult(



            source=source,



            target=target,



            distance=-1,



            path=[],



            is_reachable=False



        )







    def compute_connectivity(self) -> List[ConnectivityResult]:



        """Analyze connectivity components."""



        components = self._find_connected_components()







        results = []



        for idx, component in enumerate(components):



            node_count = len(component)



            edge_count = 0







            for node in component:



                neighbors = set(self.graph[node]["out"].keys()) & component



                edge_count += len(neighbors)







            results.append(ConnectivityResult(



                component_id=idx,



                node_count=node_count,



                edge_count=edge_count // 2,



                nodes=sorted(component)



            ))







        return sorted(results, key=lambda x: x.node_count, reverse=True)







    def detect_communities(self, method: str = "label_propagation") -> List[CommunityResult]:



        """Detect communities in the graph."""



        if not self.graph:



            return []







        # Simple label propagation



        labels = {node: i for i, node in enumerate(self.graph.keys())}



        changed = True



        max_iterations = 50







        iteration = 0



        while changed and iteration < max_iterations:



            changed = False



            iteration += 1







            for node in list(self.graph.keys()):



                neighbor_labels = []



                neighbors = set(self.graph[node]["out"].keys()) | set(self.graph[node]["in"].keys())







                for neighbor in neighbors:



                    if neighbor in labels:



                        neighbor_labels.append(labels[neighbor])







                if neighbor_labels:



                    # Most common label



                    from collections import Counter



                    most_common = Counter(neighbor_labels).most_common(1)[0][0]



                    if labels[node] != most_common:



                        labels[node] = most_common



                        changed = True







        # Group by community



        community_groups = defaultdict(list)



        for node, label in labels.items():



            community_groups[label].append(node)







        results = []



        for idx, (label, nodes) in enumerate(sorted(community_groups.items(), key=lambda x: len(x[1]), reverse=True)):



            internal_edges = 0



            for node in nodes:



                neighbors = set(self.graph[node]["out"].keys()) & set(nodes)



                internal_edges += len(neighbors)







            results.append(CommunityResult(



                community_id=idx,



                size=len(nodes),



                nodes=sorted(nodes)[:50],  # Limit for response



                internal_edges=internal_edges // 2



            ))







        return results[:20]  # Return top 20











# Global analytics engine instance



_analytics_engine = GraphAnalyticsEngine()











def _ensure_analytics_loaded():



    """Ensure analytics engine has latest graph data."""



    global _analytics_engine



    nodes_data = [{"id": n["node_id"], **n} for n in _graph_nodes.values() if n.get("node_id")]



    edges_data = [



        {"source": e["source"], "target": e["target"]}



        for e in _graph_edges.values()



        if e.get("source") and e.get("target")



    ]



    _analytics_engine.load_graph(nodes_data, edges_data)











