    if not request.metrics or AnalyticsMetric.CONNECTIVITY in request.metrics:



        response.connectivity = _analytics_engine.compute_connectivity()







    if not request.metrics or AnalyticsMetric.COMMUNITY in request.metrics:



        response.communities = _analytics_engine.detect_communities()







    return response











