@router.post("/i18n/search", response_model=MultilingualSearchResponse)



async def multilingual_search(request: MultilingualSearchRequest) -> MultilingualSearchResponse:



    """Search entities with multilingual support."""



    query = request.query



    locales = request.locales



    entity_types = request.entity_types







    # Detect query language



    query_lang = _translation_engine.detect_language(query)







    # Search across locales



    results = []







    # Load all entities



    all_entities = _load_all_entities()







    for entity_id, entity_data in all_entities.items():



        if entity_types and entity_data.get("type") not in entity_types:



            continue







        original_name = entity_data.get("name", "")



        score = 0.0







        # Calculate score for each locale



        name_translations = {}







        for locale in locales:



            if locale == query_lang:



                # Same language - exact match



                if query.lower() in original_name.lower():



                    score = 1.0



                name_translations[locale] = original_name



            else:



                # Different language - check translation



                translated = _translation_engine.translate(



                    original_name,



                    locale,



                    "en"



                )



                name_translations[locale] = translated







                if query.lower() in translated.lower():



                    score = max(score, 0.7)







        if score > 0 or query.lower() in original_name.lower():



            # Include if there's any match



            if score == 0:



                score = 0.3 if query.lower() in original_name.lower() else 0







            if score > 0:



                results.append(SearchResult(



                    entity_id=entity_id,



                    name=original_name,



                    name_translations=name_translations,



                    entity_type=entity_data.get("type", "unknown"),



                    score=score



                ))







    # Sort by score



    results.sort(key=lambda x: x.score, reverse=True)







    # Limit results



    results = results[:50]







    return MultilingualSearchResponse(



        query=query,



        results=results,



        total=len(results),



        searched_locales=locales



    )











@router.get("/i18n/locales", response_model=LocaleResponse)



async def get_supported_locales(



    accept_language: Optional[str] = None



) -> LocaleResponse:



    """Get list of supported locales."""



    languages = _translation_engine.get_supported_languages()







    supported_locales = [



        LocaleInfo(



            locale=f"{lang['code']}-{lang['code'].upper()}" if lang['code'] not in ["zh", "en"] else (



                "zh-CN" if lang['code'] == "zh" else "en-US"



            ),



            language_name=lang["name"],



            native_name=lang["native"]



        )



        for lang in languages



    ]







    # Determine best locale from Accept-Language header



    current = "en-US"



    if accept_language:



        # Simple parsing - take first language



        preferred = accept_language.split(",")[0].split(";")[0].strip()



        prefix = preferred.split("-")[0].lower()







        locale_map = {



            "en": "en-US", "zh": "zh-CN", "ja": "ja-JP",



            "ko": "ko-KR", "es": "es-ES", "fr": "fr-FR",



            "de": "de-DE", "pt": "pt-BR", "ru": "ru-RU"



        }



        current = locale_map.get(prefix, "en-US")







    return LocaleResponse(



        current_locale=current,



        supported_locales=supported_locales,



        default_locale="en-US"



    )











@router.post("/i18n/locale", response_model=dict)



async def set_user_locale(locale: str) -> dict:



    """Set user's preferred locale."""



    valid_locales = [



        "en-US", "zh-CN", "zh-TW", "ja-JP", "ko-KR",



        "es-ES", "fr-FR", "de-DE", "pt-BR", "ru-RU"



    ]







    if locale not in valid_locales:



        return {"error": f"Invalid locale. Valid: {valid_locales}"}







    return {



        "locale": locale,



        "message": f"Locale set to {locale}",



        "timestamp": _now_iso()



    }











@router.get("/i18n/translate/batch", response_model=List[TranslationResult])



async def translate_batch(



    texts: str,



    target_locale: str = "zh-CN",



    source_locale: str = "auto"



) -> List[TranslationResult]:



    """Translate multiple texts at once."""



    text_list = texts.split("|")  # Pipe-separated







    results = []



    source = source_locale







    if source == "auto":



        # Detect from first text



        source = _translation_engine.detect_language(text_list[0])







    for text in text_list:



        text = text.strip()



        if not text:



            continue







        translated = _translation_engine.translate(text, target_locale, source)







        results.append(TranslationResult(



            original_text=text,



            translated_text=translated,



            source_locale=source,



            target_locale=target_locale



        ))







    return results











@router.post("/i18n/export", response_model=dict)



async def export_translations(



    entity_type: Optional[str] = None,



    target_locale: str = "zh-CN"



) -> dict:



    """Export entity translations for a locale."""



    all_entities = _load_all_entities()







    translations = {}







    for entity_id, entity_data in all_entities.items():



        if entity_type and entity_data.get("type") != entity_type:



            continue







        original_name = entity_data.get("name", entity_id)



        translated = _translation_engine.translate(original_name, target_locale, "en")







        translations[entity_id] = {



            "original": original_name,



            "translated": translated,



            "type": entity_data.get("type", "unknown")



        }







    return {



        "locale": target_locale,



        "entity_count": len(translations),



        "translations": translations,



        "timestamp": _now_iso()



    }











