# ============================================================



# Annotation & Commenting APIs (v1.06)



# ============================================================











@router.post("/annotations", response_model=Annotation)



async def create_annotation(request: AnnotationCreate) -> Annotation:



    """Create an annotation/comment on a knowledge graph element."""



    annotation_id = _generate_annotation_id()



    now = _now_iso()







    # Parse mentions from content if not provided



    mentions = request.mentions or []



    if not mentions:



        # Extract @mentions from content



        import re



        mentions = re.findall(r'@(\w+)', request.content)







    annotation = Annotation(



        annotation_id=annotation_id,



        target_type=request.target_type,



        target_id=request.target_id,



        content=request.content,



        author_id=request.author_id,



        author_name=request.author_name,



        parent_id=request.parent_id,



        mentions=mentions,



        status=AnnotationStatus.OPEN,



        created_at=now,



        updated_at=now



    )







    _annotations[annotation_id] = annotation







    # Record activity



    _record_activity(



        request.author_id,



        request.author_name,



        "added annotation",



        request.target_type,



        request.target_id,



        request.content[:50]



    )







    # Trigger webhooks for annotation events



    event_type = CollaborationWebhookEvent.ANNOTATION_REPLY if request.parent_id else CollaborationWebhookEvent.ANNOTATION_CREATED



    webhook_data = {



        "annotation_id": annotation_id,



        "target_type": request.target_type,



        "target_id": request.target_id,



        "content": request.content,



        "author_id": request.author_id,



        "author_name": request.author_name,



    }



    if request.parent_id:



        webhook_data["parent_id"] = request.parent_id







    asyncio.create_task(_trigger_collaboration_webhook(



        event_type,



        webhook_data,



        user_id=request.author_id



    ))







    return annotation











@router.get("/annotations", response_model=AnnotationResponse)



async def get_annotations(



    target_type: Optional[str] = None,



    target_id: Optional[str] = None,



    author_id: Optional[str] = None,



    status: Optional[str] = None,



    parent_id: Optional[str] = None,  # None = top-level, "any" = all replies



    limit: int = 50,



    offset: int = 0



) -> AnnotationResponse:



    """Get annotations with filters."""



    annotations = list(_annotations.values())







    # Apply filters



    if target_type:



        annotations = [a for a in annotations if a.target_type == target_type]







    if target_id:



        annotations = [a for a in annotations if a.target_id == target_id]







    if author_id:



        annotations = [a for a in annotations if a.author_id == author_id]







    if status:



        annotations = [a for a in annotations if a.status.value == status]







    if parent_id is not None:



        if parent_id == "any":



            # Get all replies (annotations with parent_id)



            annotations = [a for a in annotations if a.parent_id is not None]



        else:



            # Get children of specific annotation



            annotations = [a for a in annotations if a.parent_id == parent_id]



    else:



        # Default: top-level only (no parent)



        annotations = [a for a in annotations if a.parent_id is None]







    # Sort by created_at descending



    annotations.sort(key=lambda a: a.created_at, reverse=True)







    # Apply pagination



    total = len(annotations)



    annotations = annotations[offset:offset + limit]







    return AnnotationResponse(annotations=annotations, total=total)











@router.get("/annotations/{annotation_id}", response_model=Annotation)



async def get_annotation(annotation_id: str) -> Annotation:



    """Get a specific annotation."""



    if annotation_id not in _annotations:



        raise HTTPException(status_code=404, detail="Annotation not found")







    return _annotations[annotation_id]











@router.put("/annotations/{annotation_id}", response_model=Annotation)



async def update_annotation(



    annotation_id: str,



    request: AnnotationUpdate



) -> Annotation:



    """Update an annotation."""



    if annotation_id not in _annotations:



        raise HTTPException(status_code=404, detail="Annotation not found")







    annotation = _annotations[annotation_id]







    if request.content is not None:



        annotation.content = request.content



        annotation.updated_at = _now_iso()







    if request.status is not None:



        annotation.status = AnnotationStatus(request.status)



        if request.status == "resolved":



            annotation.resolved_by = annotation.author_id



            annotation.resolved_at = _now_iso()



        annotation.updated_at = _now_iso()







    # Trigger webhooks



    webhook_data = {



        "annotation_id": annotation_id,



        "content": annotation.content,



        "status": annotation.status.value,



        "author_id": annotation.author_id,



    }



    asyncio.create_task(_trigger_collaboration_webhook(



        CollaborationWebhookEvent.ANNOTATION_UPDATED,



        webhook_data,



        user_id=annotation.author_id



    ))







    return annotation











@router.delete("/annotations/{annotation_id}")



async def delete_annotation(



    annotation_id: str,



    author_id: str



) -> dict:



    """Delete an annotation."""



    if annotation_id not in _annotations:



        raise HTTPException(status_code=404, detail="Annotation not found")







    annotation = _annotations[annotation_id]







    # Only author can delete



    if annotation.author_id != author_id:



        raise HTTPException(status_code=403, detail="Only author can delete annotation")







    del _annotations[annotation_id]







    # Also delete all replies



    replies_to_delete = [



        a_id for a_id, a in _annotations.items()



        if a.parent_id == annotation_id



    ]



    for reply_id in replies_to_delete:



        del _annotations[reply_id]







    # Trigger webhooks



    webhook_data = {



        "annotation_id": annotation_id,



        "target_type": annotation.target_type,



        "target_id": annotation.target_id,



        "author_id": annotation.author_id,



    }



    asyncio.create_task(_trigger_collaboration_webhook(



        CollaborationWebhookEvent.ANNOTATION_DELETED,



        webhook_data,



        user_id=annotation.author_id



    ))







    return {



        "message": f"Annotation {annotation_id} deleted",



        "timestamp": _now_iso()



    }











