# ============================================================



# Annotation Full-Text Search APIs (v1.10)



# ============================================================











class AnnotationSearchRequest(BaseModel):



    """Request to search annotations."""



    query: str  # Search query text



    target_type: Optional[str] = None  # Filter by target type (node, edge, graph)



    target_id: Optional[str] = None  # Filter by specific target



    author_id: Optional[str] = None  # Filter by author



    status: Optional[str] = None  # Filter by status (open, resolved, archived)



    mentions: Optional[str] = None  # Filter by mentioned user



    sort_by: str = "relevance"  # relevance, created_at, updated_at, upvotes



    sort_order: str = "desc"  # asc, desc



    offset: int = 0



    limit: int = 20











class SearchResult(BaseModel):



    """Single search result with score."""



    annotation: Annotation



    score: float



    matched_fields: List[str]











class AnnotationSearchResponse(BaseModel):



    """Response for search."""



    results: List[SearchResult]



    total: int



    query: str



    took_ms: float











def _calculate_search_score(annotation: Annotation, query: str) -> Tuple[float, List[str]]:



    """



    Calculate relevance score for an annotation given a search query.



    Returns (score, matched_fields).



    """



    score = 0.0



    matched_fields = []



    query_lower = query.lower()



    query_words = set(query_lower.split())







    # Check content (highest weight - up to 50 points)



    content_lower = annotation.content.lower()



    if query_lower in content_lower:



        # Exact match in content -highest weight



        score += 50



        matched_fields.append("content")



    else:



        # Check individual words



        matches = sum(1 for w in query_words if w in content_lower)



        if matches > 0:



            score += matches * 10



            if "content" not in matched_fields:



                matched_fields.append("content")







    # Check author name (up to 20 points)



    author_lower = annotation.author_name.lower()



    if query_lower in author_lower:



        score += 20



        matched_fields.append("author_name")







    # Check mentions (up to 15 points)



    if annotation.mentions:



        for mention in annotation.mentions:



            if query_lower in mention.lower():



                score += 15



                if "mentions" not in matched_fields:



                    matched_fields.append("mentions")



                break







    # Boost for engagement (up to 15 points)



    score += min(annotation.upvotes * 2, 10)  # Up to 10 points for upvotes



    score += min(annotation.downvotes, 5)  # Downvotes reduce slightly but not negative







    return score, matched_fields











def _matches_filters(annotation: Annotation, target_type: Optional[str],



                   target_id: Optional[str], author_id: Optional[str],



                   status: Optional[str], mentions: Optional[str]) -> bool:



    """Check if annotation matches filters."""



    if target_type and annotation.target_type != target_type:



        return False



    if target_id and annotation.target_id != target_id:



        return False



    if author_id and annotation.author_id != author_id:



        return False



    if status and annotation.status.value != status:



        return False



    if mentions:



        mentions_lower = mentions.lower()



        if not any(mentions_lower in m.lower() for m in annotation.mentions):



            return False



    return True











@router.post("/annotations/search", response_model=AnnotationSearchResponse)



async def search_annotations(request: AnnotationSearchRequest) -> AnnotationSearchResponse:



    """



    Full-text search across annotations.







    Searchable fields:



    - content (highest weight)



    - author_name



    - mentions







    Returns results sorted by relevance or specified field.



    """



    import time



    start_time = time.time()







    # Normalize query



    query = request.query.strip()



    if not query:



        raise HTTPException(status_code=400, detail="Search query cannot be empty")







    # Collect all annotations matching filters



    candidate_results = []



    for annotation in _annotations.values():



        if not _matches_filters(



            annotation,



            request.target_type,



            request.target_id,



            request.author_id,



            request.status,



            request.mentions



        ):



            continue







        # Calculate score



        score, matched_fields = _calculate_search_score(annotation, query)







        # Only include if there's some match



        if score > 0:



            candidate_results.append(SearchResult(



                annotation=annotation,



                score=score,



                matched_fields=matched_fields



            ))







    # Sort results



    reverse_sort = request.sort_order == "desc"



    if request.sort_by == "relevance":



        candidate_results.sort(key=lambda x: x.score, reverse=reverse_sort)



    elif request.sort_by == "created_at":



        candidate_results.sort(key=lambda x: x.annotation.created_at, reverse=reverse_sort)



    elif request.sort_by == "updated_at":



        candidate_results.sort(key=lambda x: x.annotation.updated_at, reverse=reverse_sort)



    elif request.sort_by == "upvotes":



        candidate_results.sort(key=lambda x: x.annotation.upvotes, reverse=reverse_sort)







    # Pagination



    total = len(candidate_results)



    offset = min(request.offset, total)



    limit = min(request.limit, 100)



    paged_results = candidate_results[offset:offset + limit]







    took_ms = (time.time() - start_time) * 1000







    return AnnotationSearchResponse(



        results=paged_results,



        total=total,



        query=query,



        took_ms=took_ms



    )











@router.get("/annotations/search/autocomplete")



async def search_annotations_autocomplete(q: str, limit: int = 5) -> List[dict]:



    """



    Quick autocomplete for annotations.



    Returns top matching annotation previews.



    """



    if not q or len(q) < 2:



        return []







    limit = min(limit, 20)







    # Get top results



    search_req = AnnotationSearchRequest(



        query=q,



        limit=limit,



        sort_by="relevance"



    )



    response = await search_annotations(search_req)







    # Format for autocomplete



    suggestions = []



    for result in response.results:



        ann = result.annotation



        # Truncate content for display



        content_preview = ann.content[:80] + "..." if len(ann.content) > 80 else ann.content



        suggestions.append({



            "annotation_id": ann.annotation_id,



            "preview": content_preview,



            "author": ann.author_name,



            "target": f"{ann.target_type}:{ann.target_id}",



            "score": result.score



        })







    return suggestions











