@router.post("/files", response_model=SharedFile)



async def upload_file(request: FileUploadRequest) -> SharedFile:



    """Upload/share a file in a room."""



    # Validate file size



    file_size_mb = request.file_size / (1024 * 1024)



    if file_size_mb > _max_file_size_mb:



        raise HTTPException(



            status_code=400,



            detail=f"File size exceeds {_max_file_size_mb}MB limit"



        )







    # Validate room exists



    if request.room_id not in _collab_rooms:



        raise HTTPException(status_code=404, detail="Room not found")







    # Validate user is room member



    room = _collab_rooms[request.room_id]



    if request.uploader_id not in room.members:



        raise HTTPException(status_code=403, detail="Must be room member to upload")







    file_id = _generate_file_id()



    now = _now_iso()







    # Calculate expiration if provided



    expires_at = None



    if request.expires_hours:



        import datetime



        expires_dt = datetime.datetime.now() + datetime.timedelta(hours=request.expires_hours)



        expires_at = expires_dt.isoformat()







    file = SharedFile(



        file_id=file_id,



        room_id=request.room_id,



        file_name=request.file_name,



        file_type=request.file_type,



        file_size=request.file_size,



        storage_key=request.storage_key,



        uploader_id=request.uploader_id,



        uploader_name=request.uploader_name,



        visibility=FileVisibility(request.visibility),



        created_at=now,



        expires_at=expires_at



    )







    _room_files[file_id] = file







    # Record activity



    _record_activity(



        request.uploader_id,



        request.uploader_name,



        "uploaded file",



        "file",



        file_id,



        request.file_name



    )







    return file











@router.get("/files", response_model=FileResponse)



async def list_files(



    room_id: Optional[str] = None,



    uploader_id: Optional[str] = None,



    file_type: Optional[str] = None,



    limit: int = 50,



    offset: int = 0



) -> FileResponse:



    """List shared files with filters."""



    files = list(_room_files.values())







    # Apply filters



    if room_id:



        files = [f for f in files if f.room_id == room_id]







    if uploader_id:



        files = [f for f in files if f.uploader_id == uploader_id]







    if file_type:



        files = [f for f in files if f.file_type.startswith(file_type)]







    # Filter expired files



    now = _now_iso()



    files = [f for f in files if f.expires_at is None or f.expires_at > now]







    # Sort by created_at descending



    files.sort(key=lambda f: f.created_at, reverse=True)







    # Apply pagination



    total = len(files)



    files = files[offset:offset + limit]







    return FileResponse(files=files, total=total)











