@router.get("/files/stats", response_model=dict)



async def get_file_stats() -> dict:



    """Get file sharing statistics."""



    # Filter expired



    now = _now_iso()



    active_files = [



        f for f in _room_files.values()



        if f.expires_at is None or f.expires_at > now



    ]







    total_size = sum(f.file_size for f in active_files)



    total_size_mb = total_size / (1024 * 1024)







    # By visibility



    by_visibility = {}



    for f in active_files:



        by_visibility[f.visibility.value] = by_visibility.get(f.visibility.value, 0) + 1







    # By room



    by_room = {}



    for f in active_files:



        by_room[f.room_id] = by_room.get(f.room_id, 0) + 1







    # Top files by downloads



    top_files = sorted(



        active_files,



        key=lambda f: f.download_count,



        reverse=True



    )[:5]







    return {



        "total_files": len(active_files),



        "total_size_mb": round(total_size_mb, 2),



        "total_downloads": sum(f.download_count for f in active_files),



        "by_visibility": by_visibility,



        "by_room": by_room,



        "top_files": [



            {



                "file_id": f.file_id,



                "file_name": f.file_name,



                "downloads": f.download_count



            }



            for f in top_files



        ],



        "timestamp": _now_iso()



    }











# =============================================================================



# WebSocket Real-Time Push Infrastructure



# =============================================================================







from fastapi import WebSocket, WebSocketDisconnect



from typing import Dict, Set, Optional



import json



import asyncio











class WebSocketManager:



    """Manages WebSocket connections and real-time event broadcasting."""







    def __init__(self):



        # Connection storage: connection_id -> WebSocket



        self.active_connections: Dict[str, WebSocket] = {}







        # Room subscriptions: room_id -> set of connection_ids



        self.room_subscriptions: Dict[str, Set[str]] = {}







        # User connections: user_id -> set of connection_ids



        self.user_connections: Dict[str, Set[str]] = {}







        # Event handlers



        self.event_handlers: Dict[str, list] = {}







    async def connect(self, websocket: WebSocket, connection_id: str, user_id: Optional[str] = None) -> None:



        """Accept and register a new WebSocket connection."""



        await websocket.accept()



        self.active_connections[connection_id] = websocket







        if user_id:



            if user_id not in self.user_connections:



                self.user_connections[user_id] = set()



            self.user_connections[user_id].add(connection_id)







    def disconnect(self, connection_id: str, user_id: Optional[str] = None) -> None:



        """Remove a WebSocket connection."""



        if connection_id in self.active_connections:



            del self.active_connections[connection_id]







        # Remove from room subscriptions



        for room_id in list(self.room_subscriptions.keys()):



            if connection_id in self.room_subscriptions[room_id]:



                self.room_subscriptions[room_id].remove(connection_id)







        # Remove from user connections



        if user_id and user_id in self.user_connections:



            self.user_connections[user_id].discard(connection_id)







    async def subscribe_to_room(self, connection_id: str, room_id: str) -> None:



        """Subscribe a connection to a room's events."""



        if room_id not in self.room_subscriptions:



            self.room_subscriptions[room_id] = set()



        self.room_subscriptions[room_id].add(connection_id)







    async def unsubscribe_from_room(self, connection_id: str, room_id: str) -> None:



        """Unsubscribe a connection from a room."""



        if room_id in self.room_subscriptions:



            self.room_subscriptions[room_id].discard(connection_id)







    async def send_personal_message(self, message: dict, connection_id: str) -> None:



        """Send a message to a specific connection."""



        if connection_id in self.active_connections:



            websocket = self.active_connections[connection_id]



            try:



                await websocket.send_json(message)



            except Exception:



                # Connection closed, remove it



                self.disconnect(connection_id)







    async def broadcast_to_room(self, message: dict, room_id: str) -> None:



        """Broadcast a message to all connections subscribed to a room."""



        if room_id not in self.room_subscriptions:



            return







        disconnected = []



        for connection_id in self.room_subscriptions[room_id]:



            if connection_id in self.active_connections:



                try:



                    websocket = self.active_connections[connection_id]



                    await websocket.send_json(message)



                except Exception:



                    disconnected.append(connection_id)







        # Clean up disconnected



        for conn_id in disconnected:



            self.disconnect(conn_id)







    async def broadcast_to_all(self, message: dict) -> None:



        """Broadcast a message to all active connections."""



        disconnected = []



        for connection_id, websocket in self.active_connections.items():



            try:



                await websocket.send_json(message)



            except Exception:



                disconnected.append(connection_id)







        for conn_id in disconnected:



            self.disconnect(conn_id)







    async def broadcast_to_user(self, message: dict, user_id: str) -> None:



        """Broadcast a message to all connections for a user."""



        if user_id not in self.user_connections:



            return







        disconnected = []



        for connection_id in self.user_connections[user_id]:



            if connection_id in self.active_connections:



                try:



                    websocket = self.active_connections[connection_id]



                    await websocket.send_json(message)



                except Exception:



                    disconnected.append(connection_id)







        for conn_id in disconnected:



            self.disconnect(conn_id)







    def get_room_subscribers(self, room_id: str) -> int:



        """Get count of subscribers to a room."""



        if room_id not in self.room_subscriptions:



            return 0



        return len(self.room_subscriptions[room_id])







    def get_active_count(self) -> int:



        """Get total active connections."""



        return len(self.active_connections)











# Global WebSocket manager



_ws_manager = WebSocketManager()











class WebSocketEventType(str, Enum):



    """Types of real-time events."""



    PRESENCE_UPDATE = "presence_update"



    ANNOTATION_CREATED = "annotation_created"



    ANNOTATION_UPDATED = "annotation_updated"



    ANNOTATION_DELETED = "annotation_deleted"



    ACTIVITY_POSTED = "activity_posted"



    ROOM_JOINED = "room_joined"



    ROOM_LEFT = "room_left"



    FILE_UPLOADED = "file_uploaded"



    FILE_DOWNLOADED = "file_downloaded"



    USER_TYPING = "user_typing"



    CURSOR_MOVED = "cursor_moved"











class RealTimeEvent(BaseModel):



    """A real-time event message."""



    event_type: WebSocketEventType



    connection_id: Optional[str] = None



    user_id: Optional[str] = None



    user_name: Optional[str] = None



    room_id: Optional[str] = None



    payload: dict



    timestamp: str = Field(default_factory=_now_iso)











class WebSocketConnectionRequest(BaseModel):



    """Request to establish WebSocket connection."""



    user_id: str



    user_name: str



    initial_room: Optional[str] = None











class WebSocketMessage(BaseModel):



    """Message sent over WebSocket."""



    event_type: WebSocketEventType



    room_id: Optional[str] = None



    target_user_id: Optional[str] = None



    payload: dict











class WebSocketStatus(BaseModel):



    """WebSocket connection status."""



    connection_id: str



    status: str  # connected, disconnected



    active_connections: int



    room_subscribers: Optional[dict] = None











# In-memory connection metadata



_ws_connections_meta: Dict[str, dict] = {}



_connection_id_counter = 0











def _generate_connection_id() -> str:



    """Generate unique connection ID."""



    global _connection_id_counter



    _connection_id_counter += 1



    return f"ws_{int(time.time() * 1000)}_{_connection_id_counter}"











@router.websocket("/ws/collaboration")



async def websocket_collaboration(websocket: WebSocket):



    """WebSocket endpoint for real-time collaboration."""



    connection_id = _generate_connection_id()



    user_id = None



    current_room = None







    try:



        # Wait for initial connection message



        initial_data = await websocket.receive_text()



        try:



            request = json.loads(initial_data)



            user_id = request.get("user_id")



            user_name = request.get("user_name", "Anonymous")



            current_room = request.get("initial_room")



        except json.JSONDecodeError:



            await websocket.close(code=4000, reason="Invalid initial message")



            return







        if not user_id:



            await websocket.close(code=4001, reason="User ID required")



            return







        # Register connection



        await _ws_manager.connect(websocket, connection_id, user_id)







        # Store metadata



        _ws_connections_meta[connection_id] = {



            "user_id": user_id,



            "user_name": user_name,



            "current_room": current_room,



            "connected_at": _now_iso()



        }







        # Subscribe to initial room if provided



        if current_room:



            await _ws_manager.subscribe_to_room(connection_id, current_room)



            # Notify room about new user



            await _ws_manager.broadcast_to_room({



                "event_type": WebSocketEventType.ROOM_JOINED.value,



                "user_id": user_id,



                "user_name": user_name,



                "room_id": current_room,



                "payload": {"message": f"{user_name} joined the room"},



                "timestamp": _now_iso()



            }, current_room)







        # Send welcome message



        await websocket.send_json({



            "event_type": "connection_established",



            "connection_id": connection_id,



            "user_id": user_id,



            "timestamp": _now_iso()



        })







        # Main message loop



        while True:



            data = await websocket.receive_text()







            try:



                message = json.loads(data)



                event_type = message.get("event_type")



                room_id = message.get("room_id")



                target_user_id = message.get("target_user_id")



                payload = message.get("payload", {})







                if event_type == "subscribe_room" and room_id:



                    await _ws_manager.subscribe_to_room(connection_id, room_id)



                    _ws_connections_meta[connection_id]["current_room"] = room_id







                elif event_type == "unsubscribe_room" and room_id:



                    await _ws_manager.unsubscribe_from_room(connection_id, room_id)







                elif event_type == "typing" and room_id:



                    # Broadcast typing indicator



                    await _ws_manager.broadcast_to_room({



                        "event_type": WebSocketEventType.USER_TYPING.value,



                        "user_id": user_id,



                        "user_name": user_name,



                        "room_id": room_id,



                        "payload": payload,



                        "timestamp": _now_iso()



                    }, room_id)







                elif event_type == "cursor" and room_id:



                    # Broadcast cursor position



                    await _ws_manager.broadcast_to_room({



                        "event_type": WebSocketEventType.CURSOR_MOVED.value,



                        "user_id": user_id,



                        "user_name": user_name,



                        "room_id": room_id,



                        "payload": payload,



                        "timestamp": _now_iso()



                    }, room_id)







                elif event_type == "room_message" and room_id:



                    # Broadcast message to room



                    await _ws_manager.broadcast_to_room({



                        "event_type": "room_message",



                        "user_id": user_id,



                        "user_name": user_name,



                        "room_id": room_id,



                        "payload": payload,



                        "timestamp": _now_iso()



                    }, room_id)







                elif event_type == "personal_message" and target_user_id:



                    # Send to specific user



                    await _ws_manager.broadcast_to_user({



                        "event_type": "personal_message",



                        "from_user_id": user_id,



                        "from_user_name": user_name,



                        "payload": payload,



                        "timestamp": _now_iso()



                    }, target_user_id)







                elif event_type == "ping":



                    # Respond to ping



                    await websocket.send_json({



                        "event_type": "pong",



                        "timestamp": _now_iso()



                    })







            except json.JSONDecodeError:



                await websocket.send_json({



                    "event_type": "error",



                    "message": "Invalid JSON",



                    "timestamp": _now_iso()



                })







    except WebSocketDisconnect:



        pass



    finally:



        # Clean up



        _ws_manager.disconnect(connection_id, user_id)







        if connection_id in _ws_connections_meta:



            meta = _ws_connections_meta[connection_id]



            # Notify room about user leaving



            if meta.get("current_room"):



                await _ws_manager.broadcast_to_room({



                    "event_type": WebSocketEventType.ROOM_LEFT.value,



                    "user_id": meta.get("user_id"),



                    "user_name": meta.get("user_name"),



                    "room_id": meta["current_room"],



                    "payload": {"message": f"{meta.get('user_name')} left the room"},



                    "timestamp": _now_iso()



                }, meta["current_room"])







            del _ws_connections_meta[connection_id]











@router.get("/ws/status", response_model=WebSocketStatus)



async def get_websocket_status(connection_id: str) -> WebSocketStatus:



    """Get WebSocket connection status."""



    is_connected = connection_id in _active_connections







    room_subscribers = None



    if is_connected:



        # Build room subscriber counts



        room_subscribers = {}



        for room_id in _ws_manager.room_subscriptions:



            count = len(_ws_manager.room_subscriptions[room_id])



            if count > 0:



                room_subscribers[room_id] = count







    return WebSocketStatus(



        connection_id=connection_id,



        status="connected" if is_connected else "disconnected",



        active_connections=_ws_manager.get_active_count(),



        room_subscribers=room_subscribers



    )











@router.get("/ws/rooms/{room_id}/subscribers", response_model=dict)



async def get_room_subscribers(room_id: str) -> dict:



    """Get count of subscribers to a room via WebSocket."""



    return {



        "room_id": room_id,



        "subscriber_count": _ws_manager.get_room_subscribers(room_id),



        "timestamp": _now_iso()



    }











async def _broadcast_annotation_event(



    event_type: WebSocketEventType,



    annotation: Annotation,



    room_id: Optional[str] = None



) -> None:



    """Broadcast annotation event to relevant connections."""



    if room_id:



        await _ws_manager.broadcast_to_room({



            "event_type": event_type.value,



            "annotation_id": annotation.id,



            "target_id": annotation.target_id,



            "user_id": annotation.author_id,



            "user_name": annotation.author_name,



            "room_id": room_id,



            "payload": annotation.model_dump(),



            "timestamp": _now_iso()



        }, room_id)











async def _broadcast_activity_event(



    activity: ActivityEntry,



    room_id: Optional[str] = None



) -> None:



    """Broadcast activity event to relevant connections."""



    if room_id:



        await _ws_manager.broadcast_to_room({



            "event_type": WebSocketEventType.ACTIVITY_POSTED.value,



            "user_id": activity.user_id,



            "user_name": activity.user_name,



            "room_id": room_id,



            "payload": activity.model_dump(),



            "timestamp": _now_iso()



        }, room_id)











# API endpoint to trigger real-time notification (for external integration)



@router.post("/ws/push", response_model=dict)



async def push_realtime_event(



    event_type: str,



    user_id: Optional[str] = None,



    room_id: Optional[str] = None,



    payload: Optional[dict] = None



) -> dict:



    """Push a real-time event to connected clients."""



    message = {



        "event_type": event_type,



        "payload": payload or {},



        "timestamp": _now_iso()



    }







    if room_id:



        await _ws_manager.broadcast_to_room(message, room_id)



    elif user_id:



        await _ws_manager.broadcast_to_user(message, user_id)



    else:



        await _ws_manager.broadcast_to_all(message)







    return {



        "status": "broadcasted",



        "connections": _ws_manager.get_active_count(),



        "timestamp": _now_iso()



    }











# Stats endpoint



@router.get("/ws/stats", response_model=dict)



async def get_websocket_stats() -> dict:



    """Get WebSocket statistics."""



    # Count users with active connections



    users_with_connections = len(_ws_manager.user_connections)







    # Room usage



    room_usage = {}



    for room_id, connections in _ws_manager.room_subscriptions.items():



        if connections:



            room_usage[room_id] = len(connections)







    return {



        "active_connections": _ws_manager.get_active_count(),



        "users_with_connections": users_with_connections,



        "rooms_with_subscribers": len(room_usage),



        "room_usage": room_usage,



        "timestamp": _now_iso()



    }











