# ========== Version Rollback ==========







class VersionRollbackRequest(BaseModel):



    """Request to rollback to a version."""



    target_version: str



    create_backup: bool = True



    changelog: str = ""











class VersionRollbackResponse(BaseModel):



    """Response from rollback operation."""



    success: bool



    new_version: str



    backup_version: str | None



    message: str











def _get_version_limit(entity_id: str) -> int:



    """Get configured version limit for entity (default: 50)."""



    # Could be extended to store per-entity limits



    return 50











def _cleanup_old_versions(entity_id: str) -> int:



    """Remove old versions beyond limit. Returns count of removed versions."""



    versions = _entity_versions.get(entity_id, [])



    limit = _get_version_limit(entity_id)







    if len(versions) <= limit:



        return 0







    removed = 0



    while len(versions) > limit:



        # Remove oldest (last in list)



        versions.pop()



        removed += 1







    _entity_versions[entity_id] = versions



    return removed











@router.post("/entities/{entity_id}/versions/rollback")



async def rollback_version(



    entity_id: str,



    request: VersionRollbackRequest,



) -> VersionRollbackResponse:



    """Rollback entity to a specific version.







    Creates a new version with the data from target version.



    Optionally creates a backup of current version.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    versions = _entity_versions.get(entity_id, [])



    if not versions:



        raise HTTPException(status_code=404, detail="No versions found")







    # Find target version



    target = next((v for v in versions if v.get("version") == request.target_version), None)



    if not target:



        raise HTTPException(status_code=404, detail=f"Version {request.target_version} not found")







    from datetime import datetime



    new_version_num = len(versions) + 1



    new_version_str = f"v{new_version_num}"



    backup_version = None







    # Create backup of current version



    if request.create_backup:



        current = versions[0]



        backup_version = f"v{new_version_num}_backup"



        backup_data = {



            "entity_id": entity_id,



            "version": backup_version,



            "data": current.get("data", {}),



            "status": "backup",



            "changelog": f"Backup before rollback to {request.target_version}",



            "created_at": datetime.now().isoformat(),



            "parent_version": current.get("version"),



        }



        versions.insert(0, backup_data)







    # Create rollback version



    rollback_data = {



        "entity_id": entity_id,



        "version": new_version_str,



        "data": target.get("data", {}),



        "status": "active",



        "changelog": request.changelog or f"Rollback to {request.target_version}",



        "created_at": datetime.now().isoformat(),



        "parent_version": request.target_version,



    }



    versions.insert(0, rollback_data)



    _entity_versions[entity_id] = versions







    # Clean up old versions



    removed = _cleanup_old_versions(entity_id)







    return VersionRollbackResponse(



        success=True,



        new_version=new_version_str,



        backup_version=backup_version,



        message=f"Rolled back to {request.target_version}, created {new_version_str}" + (f", removed {removed} old versions" if removed else ""),



    )











@router.get("/entities/{entity_id}/versions/limit")



async def get_version_limit(entity_id: str) -> dict:



    """Get version limit and current count for entity."""



    versions = _entity_versions.get(entity_id, [])



    limit = _get_version_limit(entity_id)



    current = len(versions)







    return {



        "entity_id": entity_id,



        "limit": limit,



        "current": current,



        "available": max(0, limit - current),



    }











