class VersionTagRequest(BaseModel):



    """Request to add a tag to a version."""



    tag: str



    description: str = ""











class VersionTagResponse(BaseModel):



    """Response for tag operation."""



    success: bool



    entity_id: str



    version: str



    tag: str



    message: str











class VersionTagInfo(BaseModel):



    """Information about a tag."""



    tag: str



    description: str



    created_at: str



    created_by: str = "system"











class VersionTagsListResponse(BaseModel):



    """Response listing tags for a version."""



    entity_id: str



    version: str



    tags: list[VersionTagInfo]



    total: int











class VersionsByTagResponse(BaseModel):



    """Response listing versions with a specific tag."""



    tag: str



    versions: list[dict]  # entity_id, version, description, created_at



    total: int











# Storage for version tags: {entity_id: {version: [tag_info_dict, ...]}}



_entity_version_tags: dict[str, dict[str, list[dict]]] = {}











@router.post("/entities/{entity_id}/versions/{version}/tags")



async def add_version_tag(



    entity_id: str,



    version: str,



    request: VersionTagRequest,



) -> VersionTagResponse:



    """Add a tag to a version.







    Tags help organize and categorize versions (e.g., 'production', 'staging', 'release-v1.0').



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    versions = _entity_versions.get(entity_id, [])



    if not versions:



        raise HTTPException(status_code=404, detail="No versions found")







    # Verify version exists



    version_data = next((v for v in versions if v.get("version") == version), None)



    if not version_data:



        raise HTTPException(status_code=404, detail=f"Version {version} not found")







    from datetime import datetime







    # Initialize entity tag storage if needed



    if entity_id not in _entity_version_tags:



        _entity_version_tags[entity_id] = {}







    if version not in _entity_version_tags[entity_id]:



        _entity_version_tags[entity_id][version] = []







    # Check if tag already exists



    existing_tags = _entity_version_tags[entity_id][version]



    if any(t.get("tag") == request.tag for t in existing_tags):



        raise HTTPException(status_code=409, detail=f"Tag '{request.tag}' already exists for version {version}")







    # Add new tag



    tag_info = {



        "tag": request.tag,



        "description": request.description,



        "created_at": datetime.now().isoformat(),



        "created_by": "system",



    }



    _entity_version_tags[entity_id][version].append(tag_info)







    return VersionTagResponse(



        success=True,



        entity_id=entity_id,



        version=version,



        tag=request.tag,



        message=f"Tag '{request.tag}' added to {version}",



    )











@router.delete("/entities/{entity_id}/versions/{version}/tags/{tag}")



async def remove_version_tag(



    entity_id: str,



    version: str,



    tag: str,



) -> VersionTagResponse:



    """Remove a tag from a version."""



    if entity_id not in _entity_version_tags:



        raise HTTPException(status_code=404, detail="No tags found for entity")







    if version not in _entity_version_tags[entity_id]:



        raise HTTPException(status_code=404, detail=f"No tags found for version {version}")







    tags = _entity_version_tags[entity_id][version]



    original_count = len(tags)







    # Remove tag



    _entity_version_tags[entity_id][version] = [t for t in tags if t.get("tag") != tag]







    if len(_entity_version_tags[entity_id][version]) == original_count:



        raise HTTPException(status_code=404, detail=f"Tag '{tag}' not found")







    return VersionTagResponse(



        success=True,



        entity_id=entity_id,



        version=version,



        tag=tag,



        message=f"Tag '{tag}' removed from {version}",



    )











@router.get("/entities/{entity_id}/versions/{version}/tags")



async def get_version_tags(



    entity_id: str,



    version: str,



) -> VersionTagsListResponse:



    """Get all tags for a specific version."""



    if entity_id not in _entity_version_tags:



        return VersionTagsListResponse(



            entity_id=entity_id,



            version=version,



            tags=[],



            total=0,



        )







    if version not in _entity_version_tags[entity_id]:



        return VersionTagsListResponse(



            entity_id=entity_id,



            version=version,



            tags=[],



            total=0,



        )







    tags = _entity_version_tags[entity_id][version]



    tag_infos = [



        VersionTagInfo(



            tag=t.get("tag"),



            description=t.get("description", ""),



            created_at=t.get("created_at"),



            created_by=t.get("created_by", "system"),



        )



        for t in tags



    ]







    return VersionTagsListResponse(



        entity_id=entity_id,



        version=version,



        tags=tag_infos,



        total=len(tag_infos),



    )











@router.get("/versions/tags")



async def list_all_tags(



    tag: str | None = None,



    entity_id: str | None = None,



) -> VersionsByTagResponse:



    """List all versions with a specific tag, or all tags across entities.







    - If `tag` is provided, find all versions with that tag



    - If `tag` is not provided, list all unique tags



    """



    if tag:



        # Find all versions with this tag



        results = []



        for eid, version_map in _entity_version_tags.items():



            if entity_id and eid != entity_id:



                continue



            for ver, tags in version_map.items():



                if any(t.get("tag") == tag for t in tags):



                    entity = _entities.get(eid, {})



                    tag_info = next(t for t in tags if t.get("tag") == tag)



                    results.append({



                        "entity_id": eid,



                        "entity_name": entity.get("name", eid),



                        "version": ver,



                        "description": tag_info.get("description", ""),



                        "created_at": tag_info.get("created_at"),



                    })







        return VersionsByTagResponse(



            tag=tag,



            versions=results,



            total=len(results),



        )



    else:



        # List all unique tags



        unique_tags: dict[str, list[dict]] = {}



        for eid, version_map in _entity_version_tags.items():



            if entity_id and eid != entity_id:



                continue



            for ver, tags in version_map.items():



                for t in tags:



                    tag_name = t.get("tag")



                    if tag_name not in unique_tags:



                        unique_tags[tag_name] = []



                    unique_tags[tag_name].append({



                        "entity_id": eid,



                        "version": ver,



                        "description": t.get("description", ""),



                    })







        # Convert to response format



        all_versions = []



        for tag_name, version_list in unique_tags.items():



            for v in version_list:



                entity = _entities.get(v.get("entity_id"), {})



                all_versions.append({



                    "entity_id": v.get("entity_id"),



                    "entity_name": entity.get("name", v.get("entity_id")),



                    "version": v.get("version"),



                    "description": v.get("description", ""),



                    "created_at": None,



                })







        return VersionsByTagResponse(



            tag="",



            versions=all_versions,



            total=len(all_versions),



        )











# ========== Batch Version Operations ==========







class BatchVersionOperation(BaseModel):



    """A single version operation in a batch."""



    entity_id: str



    version: str











class BatchVersionTagRequest(BaseModel):



    """Request to add tags to multiple entity versions."""



    operations: list[BatchVersionOperation]



    tag: str = Field(..., description="Tag to add to all versions")



    description: str = Field("", description="Optional description for the tag")











