@router.post("/versions/batch/tags")



async def batch_add_version_tags(



    request: BatchVersionTagRequest,



) -> BatchVersionTagResponse:



    """Add a tag to multiple entity versions at once.







    This is useful for batch categorizing versions (e.g., tagging all production



    versions with 'production').







    Request:



    ```json



    {



      "operations": [



        {"entity_id": "entity_1", "version": "v1"},



        {"entity_id": "entity_2", "version": "v2"}



      ],



      "tag": "production",



      "description": "Production release"



    }



    ```



    """



    from datetime import datetime







    results: list[BatchVersionOperationResult] = []



    successful = 0



    failed = 0



    timestamp = datetime.now().isoformat()







    for op in request.operations:



        try:



            entity_id = op.entity_id



            version = op.version







            # Check entity exists



            if entity_id not in _entities:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Entity '{entity_id}' not found"



                ))



                failed += 1



                continue







            # Check version exists



            versions = _entity_versions.get(entity_id, [])



            version_data = next((v for v in versions if v.get("version") == version), None)



            if not version_data:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Version '{version}' not found"



                ))



                failed += 1



                continue







            # Initialize tag storage if needed



            if entity_id not in _entity_version_tags:



                _entity_version_tags[entity_id] = {}



            if version not in _entity_version_tags[entity_id]:



                _entity_version_tags[entity_id][version] = []







            # Check if tag already exists



            existing_tags = _entity_version_tags[entity_id][version]



            if any(t.get("tag") == request.tag for t in existing_tags):



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Tag '{request.tag}' already exists"



                ))



                failed += 1



                continue







            # Add the tag



            tag_info = {



                "tag": request.tag,



                "description": request.description,



                "created_at": timestamp,



                "created_by": "system",



            }



            _entity_version_tags[entity_id][version].append(tag_info)







            results.append(BatchVersionOperationResult(



                entity_id=entity_id,



                version=version,



                success=True,



                message=f"Tag '{request.tag}' added"



            ))



            successful += 1







        except Exception as e:



            results.append(BatchVersionOperationResult(



                entity_id=op.entity_id,



                version=op.version,



                success=False,



                message=str(e)



            ))



            failed += 1







    return BatchVersionTagResponse(



        results=results,



        total=len(results),



        successful=successful,



        failed=failed,



    )











@router.delete("/versions/batch/tags")



async def batch_remove_version_tags(



    request: BatchVersionTagRequest,



) -> BatchVersionTagResponse:



    """Remove a tag from multiple entity versions at once.







    Request:



    ```json



    {



      "operations": [



        {"entity_id": "entity_1", "version": "v1"},



        {"entity_id": "entity_2", "version": "v2"}



      ],



      "tag": "production"



    }



    ```



    """



    results: list[BatchVersionOperationResult] = []



    successful = 0



    failed = 0







    for op in request.operations:



        try:



            entity_id = op.entity_id



            version = op.version







            # Check entity exists



            if entity_id not in _entities:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Entity '{entity_id}' not found"



                ))



                failed += 1



                continue







            # Check tag exists



            if entity_id not in _entity_version_tags or version not in _entity_version_tags[entity_id]:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"No tags found for version '{version}'"



                ))



                failed += 1



                continue







            # Remove the tag



            tags = _entity_version_tags[entity_id][version]



            original_count = len(tags)



            tags = [t for t in tags if t.get("tag") != request.tag]







            if len(tags) == original_count:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Tag '{request.tag}' not found"



                ))



                failed += 1



                continue







            _entity_version_tags[entity_id][version] = tags



            results.append(BatchVersionOperationResult(



                entity_id=entity_id,



                version=version,



                success=True,



                message=f"Tag '{request.tag}' removed"



            ))



            successful += 1







        except Exception as e:



            results.append(BatchVersionOperationResult(



                entity_id=op.entity_id,



                version=op.version,



                success=False,



                message=str(e)



            ))



            failed += 1







    return BatchVersionTagResponse(



        results=results,



        total=len(results),



        successful=successful,



        failed=failed,



    )











@router.post("/versions/batch/delete")



async def batch_delete_versions(



    request: BatchVersionDeleteRequest,



) -> BatchVersionDeleteResponse:



    """Delete multiple entity versions at once.







    Request:



    ```json



    {



      "operations": [



        {"entity_id": "entity_1", "version": "v1"},



        {"entity_id": "entity_2", "version": "v2"}



      ]



    }



    ```



    """



    results: list[BatchVersionOperationResult] = []



    successful = 0



    failed = 0







    for op in request.operations:



        try:



            entity_id = op.entity_id



            version = op.version







            # Check entity exists



            if entity_id not in _entities:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Entity '{entity_id}' not found"



                ))



                failed += 1



                continue







            # Check version exists



            versions = _entity_versions.get(entity_id, [])



            if not versions:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"No versions found for entity"



                ))



                failed += 1



                continue







            # Check if trying to delete the current version



            entity_versions = _entity_versions.get(entity_id, [])



            current = next((v for v in entity_versions if v.get("is_current")), None)



            if current and current.get("version") == version:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message="Cannot delete current version"



                ))



                failed += 1



                continue







            # Remove version



            original_count = len(versions)



            versions = [v for v in versions if v.get("version") != version]







            if len(versions) == original_count:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Version '{version}' not found"



                ))



                failed += 1



                continue







            _entity_versions[entity_id] = versions



            results.append(BatchVersionOperationResult(



                entity_id=entity_id,



                version=version,



                success=True,



                message=f"Version deleted"



            ))



            successful += 1







        except Exception as e:



            results.append(BatchVersionOperationResult(



                entity_id=op.entity_id,



                version=op.version,



                success=False,



                message=str(e)



            ))



            failed += 1







    return BatchVersionDeleteResponse(



        results=results,



        total=len(results),



        successful=successful,



        failed=failed,



    )











@router.post("/versions/batch/rollback")



async def batch_rollback_versions(



    request: BatchVersionRollbackRequest,



) -> BatchVersionTagResponse:



    """Rollback multiple entities to their previous versions.







    Each operation specifies an entity. The rollback will restore that entity



    to its state at the specified version.







    Request:



    ```json



    {



      "operations": [



        {"entity_id": "entity_1", "version": "v1"},



        {"entity_id": "entity_2", "version": "v2"}



      ]



    }



    ```



    """



    results: list[BatchVersionOperationResult] = []



    successful = 0



    failed = 0







    for op in request.operations:



        try:



            entity_id = op.entity_id



            version = op.version







            # Check entity exists



            if entity_id not in _entities:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Entity '{entity_id}' not found"



                ))



                failed += 1



                continue







            # Check version exists



            versions = _entity_versions.get(entity_id, [])



            version_data = next((v for v in versions if v.get("version") == version), None)



            if not version_data:



                results.append(BatchVersionOperationResult(



                    entity_id=entity_id,



                    version=version,



                    success=False,



                    message=f"Version '{version}' not found"



                ))



                failed += 1



                continue







            # Restore the entity to this version



            entity = _entities.get(entity_id, {})



            current_entity_data = version_data.get("data", {})







            # Update the entity with version data



            for key, value in current_entity_data.items():



                if key != "id":



                    entity[key] = value







            _entities[entity_id] = entity







            # Mark version as current



            for v in versions:



                v["is_current"] = (v.get("version") == version)







            results.append(BatchVersionOperationResult(



                entity_id=entity_id,



                version=version,



                success=True,



                message=f"Rolled back to version '{version}'"



            ))



            successful += 1







        except Exception as e:



            results.append(BatchVersionOperationResult(



                entity_id=op.entity_id,



                version=op.version,



                success=False,



                message=str(e)



            ))



            failed += 1







    return BatchVersionTagResponse(



        results=results,



        total=len(results),



        successful=successful,



        failed=failed,



    )











@router.post("/versions/batch/export")



async def batch_export_versions(



    request: BatchVersionExportRequest,



) -> BatchVersionExportResponse:



    """Export multiple entity versions in a single request.







    Request:



    ```json



    {



      "operations": [



        {"entity_id": "entity_1", "version": "v1"},



        {"entity_id": "entity_2", "version": "v2"}



      ]



    }



    ```







    Response:



    ```json



    {



      "results": [...],



      "total": 2,



      "successful": 2,



      "combined_export": {



        "entities": {...},



        "exported_at": "..."



      }



    }



    ```



    """



    results: list[BatchVersionExportResultItem] = []



    successful = 0



    failed = 0



    combined_entities: dict[str, dict] = {}







    for op in request.operations:



        try:



            entity_id = op.entity_id



            version = op.version







            # Check entity exists



            if entity_id not in _entities:



                results.append(BatchVersionExportResultItem(



                    entity_id=entity_id,



                    version=version,



                    export_data=None,



                    success=False,



                    message=f"Entity '{entity_id}' not found"



                ))



                failed += 1



                continue







            # Get version data



            versions = _entity_versions.get(entity_id, [])



            version_data = next((v for v in versions if v.get("version") == version), None)



            if not version_data:



                results.append(BatchVersionExportResultItem(



                    entity_id=entity_id,



                    version=version,



                    export_data=None,



                    success=False,



                    message=f"Version '{version}' not found"



                ))



                failed += 1



                continue







            # Create export data



            entity = _entities.get(entity_id, {})







            # Build relations



            relations_list = [



                r for r in _relations.values()



                if r.get("source_id") == entity_id or r.get("target_id") == entity_id



            ]



            relations = {r.get("id"): r for r in relations_list}







            export_data = {



                "entity": entity,



                "version": version_data,



                "relations": relations,



                "tags": _entity_version_tags.get(entity_id, {}).get(version, []),



            }







            combined_entities[entity_id] = export_data







            results.append(BatchVersionExportResultItem(



                entity_id=entity_id,



                version=version,



                export_data=export_data,



                success=True,



                message=f"Version exported"



            ))



            successful += 1







        except Exception as e:



            results.append(BatchVersionExportResultItem(



                entity_id=op.entity_id,



                version=op.version,



                export_data=None,



                success=False,



                message=str(e)



            ))



            failed += 1







    # Create combined export



    import pytz



    from datetime import datetime



    china_tz = pytz.timezone('Asia/Shanghai')



    timestamp = datetime.now(china_tz).isoformat()







    combined_export = None



    if combined_entities:



        combined_export = {



            "entities": combined_entities,



            "exported_at": timestamp,



            "total_entities": len(combined_entities),



            "version": "1.17.0",



        }







    return BatchVersionExportResponse(



        results=results,



        total=len(results),



        successful=successful,



        combined_export=combined_export,



    )











