# ========== Lineage Cycle Detection ==========







class CycleInfo(BaseModel):



    """Information about a cycle."""



    entity_ids: list[str]



    total_entities: int



    cycle_length: int



    cycle_type: str  # "direct", "indirect"











class CycleCheckResponse(BaseModel):



    """Response for cycle check."""



    would_create_cycle: bool



    cycle_exists: bool



    cycle_paths: list[list[str]]



    blocked_links: list[dict]











class CycleStatsResponse(BaseModel):



    """Statistics about cycles."""



    total_entities_in_cycles: int



    total_cycles: int



    longest_cycle: int



    entities_in_longest_cycle: list[str]











def _detect_cycle_from_node(



    start_node: str,



    current_node: str,



    visited: set[str],



    path: list[str],



    graph: dict[str, list[str]],



) -> list[list[str]]:



    """Detect all cycles starting from a node using DFS.







    Returns list of cycles, where each cycle is a list of entity IDs forming a cycle.



    """



    cycles = []



    visited.add(current_node)



    path.append(current_node)







    # Get outgoing edges (descendants)



    descendants = graph.get(current_node, [])







    for descendant in descendants:



        if descendant == start_node and len(path) > 1:



            # Found a cycle back to start



            cycle_path = path + [descendant]



            cycles.append(cycle_path)



        elif descendant not in path and descendant in graph:



            # Continue DFS



            new_cycles = _detect_cycle_from_node(



                start_node, descendant, visited.copy(), path.copy(), graph



            )



            cycles.extend(new_cycles)



        elif descendant in path and descendant != start_node:



            # Found a cycle that's not back to start - track it



            cycle_start = path.index(descendant)



            cycle_path = path[cycle_start:] + [descendant]



            # Only add unique cycles



            if cycle_path not in cycles and len(cycle_path) > 2:



                cycles.append(cycle_path)







    return cycles











def _build_lineage_graph(direction: str = "descendants") -> dict[str, list[str]]:



    """Build adjacency list from lineage data.







    Args:



        direction: "descendants" for forward graph (entity -> descendants)



                   "ancestors" for backward graph (entity -> ancestors)



    """



    graph = {}







    for entity_id, lineage_info in _entity_lineage.items():



        if direction == "descendants":



            # Entity points to its sources (what it derives from)



            graph[entity_id] = [



                link.get("source_id") for link in lineage_info.get("lineage", [])



                if link.get("source_id")



            ]



        else:



            # Find entities that point to this entity as a source



            graph[entity_id] = []



            for other_id, other_info in _entity_lineage.items():



                for link in other_info.get("lineage", []):



                    if link.get("source_id") == entity_id:



                        graph[entity_id].append(other_id)







    return graph











def _check_would_create_cycle(



    entity_id: str,



    source_ids: list[str],



) -> tuple[bool, list[list[str]]]:



    """Check if adding lineage links would create a cycle.







    Returns:



        (would_create_cycle, list of cycle paths)



    """



    # Build graph with proposed new edges



    graph = _build_lineage_graph("descendants")







    # Temporarily add proposed edges



    original = graph.get(entity_id, [])



    graph[entity_id] = source_ids







    cycle_paths = []



    all_visiting = set()



    all_path = []







    # Check cycles for each source



    for source_id in source_ids:



        if source_id in graph:



            cycles = _detect_cycle_from_node(



                entity_id,



                source_id,



                set(),



                [],



                graph



            )



            cycle_paths.extend(cycles)







    # Restore original



    if original:



        graph[entity_id] = original



    else:



        graph.pop(entity_id, None)







    would_cycle = len(cycle_paths) > 0



    return would_cycle, cycle_paths











def _find_all_cycles() -> list[CycleInfo]:



    """Find all cycles in the lineage graph using DFS."""



    all_cycles = []



    seen_cycle_hashes = set()







    # Build forward graph (entity -> sources)



    graph = _build_lineage_graph("descendants")







    for start_node in graph.keys():



        if start_node not in graph:



            continue







        visited = set()



        path = []







        # Use DFS to find cycles



        cycles = _detect_cycle_from_node(



            start_node,



            start_node,



            visited,



            path,



            graph



        )







        for cycle in cycles:



            # Normalize cycle (remove duplicate back to start)



            normalized = cycle[:-1] if cycle and cycle[-1] == cycle[0] else cycle







            # Create hash for deduplication



            cycle_hash = tuple(sorted(normalized))



            if cycle_hash in seen_cycle_hashes:



                continue



            seen_cycle_hashes.add(cycle_hash)







            # Determine cycle type



            cycle_type = "direct" if len(normalized) == 2 else "indirect"







            all_cycles.append(CycleInfo(



                entity_ids=normalized,



                total_entities=len(normalized),



                cycle_length=len(normalized),



                cycle_type=cycle_type,



            ))







    return all_cycles











def _get_entities_in_cycles() -> set[str]:



    """Get all entities that are part of any cycle."""



    entities = set()



    for cycle in _find_all_cycles():



        entities.update(cycle.entity_ids)



    return entities











@router.get("/entities/{entity_id}/lineage/cycles")



async def get_entity_cycles(



    entity_id: str,



) -> dict:



    """Get all cycles involving a specific entity.







    Returns all cycles that include this entity, either as a direct participant



    or through intermediate connections.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    # Build lineage graph



    graph = _build_lineage_graph("descendants")







    cycles = []







    # Check direct cycles (entity -> source -> entity)



    direct_sources = graph.get(entity_id, [])



    for source_id in direct_sources:



        source_sources = graph.get(source_id, [])



        if entity_id in source_sources:



            cycles.append({



                "entity_ids": [entity_id, source_id, entity_id],



                "total_entities": 2,



                "cycle_length": 2,



                "cycle_type": "direct",



            })







    # Check indirect cycles using DFS



    if entity_id in graph:



        visiting = set()



        path = []







        def dfs_find_cycles(current: str, target: str, visited: set, path_list: list) -> list:



            found = []



            visited.add(current)



            path_list.append(current)







            for next_node in graph.get(current, []):



                if next_node == target and len(path_list) > 1:



                    # Found cycle back to target



                    found.append(path_list + [next_node])



                elif next_node not in visited and next_node in graph:



                    results = dfs_find_cycles(next_node, target, visited.copy(), path_list.copy())



                    found.extend(results)







            return found







        for source in direct_sources:



            if source in graph:



                cycle_paths = dfs_find_cycles(source, entity_id, set(), [])



                for cycle_path in cycle_paths:



                    if cycle_path:



                        cycles.append({



                            "entity_ids": cycle_path,



                            "total_entities": len(cycle_path) - 1,



                            "cycle_length": len(cycle_path) - 1,



                            "cycle_type": "indirect",



                        })







    return {



        "entity_id": entity_id,



        "total_cycles": len(cycles),



        "cycles": cycles,



    }











@router.get("/lineage/cycles")



async def get_all_cycles(



    max_depth: int = 10,



) -> dict:



    """Get all cycles in the lineage graph.







    This is a potentially expensive operation for large graphs.



    Use max_depth to limit the search depth for cycle detection.



    """



    if len(_entity_lineage) == 0:



        return {



            "total_cycles": 0,



            "total_entities_in_cycles": 0,



            "cycles": [],



            "longest_cycle": 0,



        }







    cycles = _find_all_cycles()







    # Sort by cycle length



    cycles_sorted = sorted(cycles, key=lambda c: c.cycle_length, reverse=True)







    # Limit to max_depth if specified



    if max_depth > 0:



        cycles_sorted = [c for c in cycles_sorted if c.cycle_length <= max_depth]







    entities_in_cycles = _get_entities_in_cycles()







    longest = cycles_sorted[0] if cycles_sorted else None







    return {



        "total_cycles": len(cycles_sorted),



        "total_entities_in_cycles": len(entities_in_cycles),



        "cycles": [



            {



                "entity_ids": c.entity_ids,



                "total_entities": c.total_entities,



                "cycle_length": c.cycle_length,



                "cycle_type": c.cycle_type,



            }



            for c in cycles_sorted



        ],



        "longest_cycle": {



            "entity_ids": longest.entity_ids if longest else [],



            "cycle_length": longest.cycle_length if longest else 0,



        } if longest else None,



    }











@router.post("/entities/{entity_id}/lineage/check-cycle")



async def check_lineage_cycle(



    entity_id: str,



    request: SetLineageRequest,



) -> CycleCheckResponse:



    """Check if adding lineage links would create a cycle.







    Use this before setting lineage to prevent cycle creation.



    This is a dry-run check that doesn't modify any data.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    # Validate source entities exist



    for source_id in request.source_ids:



        if source_id not in _entities:



            raise HTTPException(status_code=404, detail=f"Source entity {source_id} not found")







    # Check if it would create a cycle



    would_cycle, cycle_paths = _check_would_create_cycle(entity_id, request.source_ids)







    # Format the results



    blocked_links = []



    if would_cycle:



        for cycle_path in cycle_paths:



            if len(cycle_path) >= 2:



                blocked_links.append({



                    "from": cycle_path[0],



                    "to": cycle_path[-1] if len(cycle_path) > 1 else cycle_path[0],



                    "path": cycle_path,



                })







    return CycleCheckResponse(



        would_create_cycle=would_cycle,



        cycle_exists=bool(cycle_paths),



        cycle_paths=cycle_paths[:10],  # Limit to first 10



        blocked_links=blocked_links[:10],



    )











@router.get("/lineage/cycles/stats")



async def get_cycle_stats() -> CycleStatsResponse:



    """Get statistics about cycles in the lineage graph."""



    if len(_entity_lineage) == 0:



        return CycleStatsResponse(



            total_entities_in_cycles=0,



            total_cycles=0,



            longest_cycle=0,



            entities_in_longest_cycle=[],



        )







    cycles = _find_all_cycles()



    entities_in_cycles = _get_entities_in_cycles()







    # Find longest cycle



    longest = max(cycles, key=lambda c: c.cycle_length) if cycles else None







    return CycleStatsResponse(



        total_entities_in_cycles=len(entities_in_cycles),



        total_cycles=len(cycles),



        longest_cycle=longest.cycle_length if longest else 0,



        entities_in_longest_cycle=longest.entity_ids if longest else [],



    )











# Update set_entity_lineage to prevent cycles by default



_original_set_lineage = set_entity_lineage











async def set_entity_lineage_with_cycle_check(



    entity_id: str,



    request: SetLineageRequest,



    prevent_cycles: bool = True,



) -> dict:



    """Set lineage relationships with optional cycle prevention.







    Args:



        entity_id: The target entity ID



        request: The lineage request



        prevent_cycles: If True (default), prevents cycle creation



    """



    if prevent_cycles:



        # Check for cycles first



        would_cycle, cycle_paths = _check_would_create_cycle(entity_id, request.source_ids)







        if would_cycle:



            raise HTTPException(



                status_code=400,



                detail=f"Adding these lineage links would create cycle(s). " +



                       f"Blocked links: {[p[-1] for p in cycle_paths[:5]]}"



            )







    return await _original_set_lineage(entity_id, request)











# Override the original endpoint to add cycle prevention



@router.post("/entities/{entity_id}/lineage")



async def set_entity_lineage_safe(



    entity_id: str,



    request: SetLineageRequest,



    prevent_cycles: bool = True,



) -> dict:



    """Set lineage relationships for an entity.







    By default, prevents cycle creation. Set prevent_cycles=false to allow cycles.



    """



    if entity_id not in _entities:



        raise HTTPException(status_code=404, detail="Entity not found")







    # Validate all source entities exist



    for source_id in request.source_ids:



        if source_id not in _entities:



            raise HTTPException(status_code=404, detail=f"Source entity {source_id} not found")







    if prevent_cycles:



        # Check for cycles first



        would_cycle, cycle_paths = _check_would_create_cycle(entity_id, request.source_ids)







        if would_cycle:



            raise HTTPException(



                status_code=400,



                detail=f"Adding these lineage links would create cycle(s). " +



                       f"Use prevent_cycles=false to override."



            )







    # Get or create lineage record



    if entity_id not in _entity_lineage:



        _entity_lineage[entity_id] = {



            "entity_id": entity_id,



            "lineage": [],



            "created_at": _now_iso(),



        }







    entity_name = _entities[entity_id].get("name", entity_id)



    entity_type = _entities[entity_id].get("type", "unknown")







    # Add lineage links



    for source_id in request.source_ids:



        source_entity = _entities[source_id]



        source_name = source_entity.get("name", source_id)



        source_type = source_entity.get("type", "unknown")







        _entity_lineage[entity_id]["lineage"].append({



            "source_id": source_id,



            "source_name": source_name,



            "source_type": source_type,



            "lineage_type": request.lineage_type.value,



            "created_at": _now_iso(),



        })







        # Also add reverse lineage from source to target



        if source_id not in _entity_lineage:



            _entity_lineage[source_id] = {



                "entity_id": source_id,



                "lineage": [],



                "created_at": _now_iso(),



            }







        _entity_lineage[source_id]["lineage"].append({



            "source_id": entity_id,



            "source_name": entity_name,



            "source_type": entity_type,



            "lineage_type": "derived_to",  # Reverse relationship



            "created_at": _now_iso(),



        })







    return {



        "entity_id": entity_id,



        "total_links": len(_entity_lineage[entity_id]["lineage"]),



        "sources_added": len(request.source_ids),



    }











# ========== Version Analytics (v1.18) ==========







class VersionAnalyticsResponse(BaseModel):



    """Response for version analytics."""



    total_versions: int



    total_entities_in_versions: int



    total_relations_in_versions: int



    average_entities_per_version: float



    average_relations_per_version: float



    average_version_size_kb: float



    storage_trend: str  # growing, shrinking, stable



    version_frequency: dict  # daily/weekly/monthly counts



    entity_distribution: dict  # entity type distribution



    largest_version: dict



    smallest_version: dict



    most_active_entity: dict | None



    created_at_range: dict











@router.get("/versions/analytics", response_model=VersionAnalyticsResponse)



async def get_version_analytics() -> VersionAnalyticsResponse:



    """Get comprehensive analytics for all versions."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    total_versions = len(_versions)



    total_entities = sum(len(v.get("entities", {})) for v in _versions.values())



    total_relations = sum(len(v.get("relations", {})) for v in _versions.values())







    avg_entities = total_entities / total_versions if total_versions > 0 else 0



    avg_relations = total_relations / total_versions if total_versions > 0 else 0







    # Calculate sizes



    sizes = []



    for v in _versions.values():



        importjson = json.dumps(v.get("entities", {}))



        importjson_rel = json.dumps(v.get("relations", {}))



        sizes.append((len(importjson) + len(importjson_rel)) / 1024)  # KB







    avg_size = sum(sizes) / len(sizes) if sizes else 0







    # Determine storage trend



    if len(sizes) >= 2:



        first_half = sum(sizes[:len(sizes)//2]) / (len(sizes)//2)



        second_half = sum(sizes[len(sizes)//2:]) / (len(sizes) - len(sizes)//2)



        if second_half > first_half * 1.1:



            storage_trend = "growing"



        elif second_half < first_half * 0.9:



            storage_trend = "shrinking"



        else:



            storage_trend = "stable"



    else:



        storage_trend = "stable"







    # Entity distribution across versions



    entity_types: dict[str, int] = {}



    for v in _versions.values():



        for entity in v.get("entities", {}).values():



            etype = entity.get("type", "unknown")



            entity_types[etype] = entity_types.get(etype, 0) + 1







    # Find largest/smallest versions



    largest = max(_versions.items(), key=lambda x: len(x[1].get("entities", {})))



    smallest = min(_versions.items(), key=lambda x: len(x[1].get("entities", {})))







    # Find most active entity (appears in most versions)



    entity_versions: dict[str, int] = {}



    for v in _versions.values():



        for eid in v.get("entities", {}).keys():



            entity_versions[eid] = entity_versions.get(eid, 0) + 1







    most_active = None



    if entity_versions:



        most_active_id = max(entity_versions.items(), key=lambda x: x[1])[0]



        most_active = {



            "entity_id": most_active_id,



            "appears_in_versions": entity_versions[most_active_id]



        }







    # Version frequency (by day)



    version_frequency = {}



    for vid, v in _versions.items():



        ts = v.get("timestamp", "")



        if ts:



            day = ts[:10]  # YYYY-MM-DD



            version_frequency[day] = version_frequency.get(day, 0) + 1







    # Created at range



    timestamps = [v.get("timestamp", "") for v in _versions.values() if v.get("timestamp")]



    created_range = {}



    if timestamps:



        created_range = {



            "oldest": min(timestamps),



            "newest": max(timestamps)



        }







    return VersionAnalyticsResponse(



        total_versions=total_versions,



        total_entities_in_versions=total_entities,



        total_relations_in_versions=total_relations,



        average_entities_per_version=round(avg_entities, 2),



        average_relations_per_version=round(avg_relations, 2),



        average_version_size_kb=round(avg_size, 2),



        storage_trend=storage_trend,



        version_frequency=version_frequency,



        entity_distribution=entity_types,



        largest_version={



            "version_id": largest[0],



            "entity_count": len(largest[1].get("entities", {})),



            "relation_count": len(largest[1].get("relations", {}))



        },



        smallest_version={



            "version_id": smallest[0],



            "entity_count": len(smallest[1].get("entities", {})),



            "relation_count": len(smallest[1].get("relations", {}))



        },



        most_active_entity=most_active,



        created_at_range=created_range



    )











class VersionEntityDiff(BaseModel):



    """Detailed diff for a single entity."""



    entity_id: str



    status: str  # added, removed, modified, unchanged



    property_changes: dict | None = None



    old_value: dict | None = None



    new_value: dict | None = None











class SemanticCompareRequest(BaseModel):



    """Request for semantic version comparison."""



    version1_id: str



    version2_id: str



    include_property_details: bool = True



    detect_breaking_changes: bool = True











class SemanticCompareResponse(BaseModel):



    """Response for semantic version comparison."""



    version1_id: str



    version2_id: str



    summary: dict



    entity_diffs: list[VersionEntityDiff]



    breaking_changes: list[dict]



    added_entity_types: list[str]



    removed_entity_types: list[str]



    modified_entity_types: list[str]











@router.post("/versions/semantic-compare", response_model=SemanticCompareResponse)



async def semantic_compare_versions(



    request: SemanticCompareRequest,



) -> SemanticCompareResponse:



    """Perform semantic comparison between two versions with detailed breakdown."""



    v1_id = request.version1_id



    v2_id = request.version2_id







    if v1_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Version {v1_id} not found")



    if v2_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Version {v2_id} not found")







    v1 = _versions[v1_id]



    v2 = _versions[v2_id]







    entities1 = v1.get("entities", {})



    entities2 = v2.get("entities", {})







    # Collect all entity IDs



    all_entity_ids = set(entities1.keys()) | set(entities2.keys())







    entity_diffs = []



    added_types: set[str] = set()



    removed_types: set[str] = set()



    modified_types: set[str] = set()



    breaking_changes = []







    for eid in all_entity_ids:



        in_v1 = eid in entities1



        in_v2 = eid in entities2







        if not in_v1 and in_v2:



            # Added



            entity = entities2[eid]



            etype = entity.get("type", "unknown")



            added_types.add(etype)



            entity_diffs.append(VersionEntityDiff(



                entity_id=eid,



                status="added",



                new_value=entity if request.include_property_details else None



            ))







            # Check for breaking changes (new required fields that are missing in v1)



            if request.detect_breaking_changes:



                breaking_changes.append({



                    "entity_id": eid,



                    "type": "new_entity",



                    "severity": "info",



                    "description": f"New entity '{eid}' added in {v2_id}"



                })







        elif in_v1 and not in_v2:



            # Removed



            entity = entities1[eid]



            etype = entity.get("type", "unknown")



            removed_types.add(etype)



            entity_diffs.append(VersionEntityDiff(



                entity_id=eid,



                status="removed",



                old_value=entity if request.include_property_details else None



            ))







            if request.detect_breaking_changes:



                breaking_changes.append({



                    "entity_id": eid,



                    "type": "entity_removed",



                    "severity": "critical",



                    "description": f"Entity '{eid}' was removed in {v2_id}"



                })







        elif in_v1 and in_v2:



            # Both exist - check for modifications



            e1 = entities1[eid]



            e2 = entities2[eid]







            # Calculate property changes



            prop_changes = {}



            old_val = None



            new_val = None







            all_keys = set(e1.keys()) | set(e2.keys())



            for key in all_keys:



                val1 = e1.get(key)



                val2 = e2.get(key)



                if val1 != val2:



                    change_type = "modified"



                    if key not in e1:



                        change_type = "added"



                    elif key not in e2:



                        change_type = "removed"



                    prop_changes[key] = {



                        "type": change_type,



                        "old_value": val1,



                        "new_value": val2



                    }







                    if request.detect_breaking_changes:



                        # Detect breaking changes based on field removal or type change



                        if change_type == "removed":



                            breaking_changes.append({



                                "entity_id": eid,



                                "field": key,



                                "type": "field_removed",



                                "severity": "high",



                                "description": f"Field '{key}' was removed from entity '{eid}'"



                            })



                        elif val1 is None and val2 is not None:



                            breaking_changes.append({



                                "entity_id": eid,



                                "field": key,



                                "type": "field_added",



                                "severity": "low",



                                "description": f"Non-nullable field '{key}' added to entity '{eid}'"



                            })







            if prop_changes:



                etype = e2.get("type", "unknown")



                modified_types.add(etype)



                if request.include_property_details:



                    old_val = e1



                    new_val = e2







                entity_diffs.append(VersionEntityDiff(



                    entity_id=eid,



                    status="modified",



                    property_changes=prop_changes if request.include_property_details else None,



                    old_value=old_val,



                    new_value=new_val



                ))



            else:



                entity_diffs.append(VersionEntityDiff(



                    entity_id=eid,



                    status="unchanged"



                ))







    summary = {



        "total_entities_compared": len(all_entity_ids),



        "added": sum(1 for d in entity_diffs if d.status == "added"),



        "removed": sum(1 for d in entity_diffs if d.status == "removed"),



        "modified": sum(1 for d in entity_diffs if d.status == "modified"),



        "unchanged": sum(1 for d in entity_diffs if d.status == "unchanged"),



        "breaking_change_count": len(breaking_changes),



    }







    return SemanticCompareResponse(



        version1_id=v1_id,



        version2_id=v2_id,



        summary=summary,



        entity_diffs=entity_diffs,



        breaking_changes=breaking_changes,



        added_entity_types=sorted(added_types),



        removed_entity_types=sorted(removed_types),



        modified_entity_types=sorted(modified_types)



    )











class VersionHealthRequest(BaseModel):



    """Request for version health check."""



    version_id: str



    check_completeness: bool = True



    check_consistency: bool = True



    check_freshness: bool = True











class VersionHealthScore(BaseModel):



    """Health score breakdown."""



    overall: float



    completeness: float | None = None



    consistency: float | None = None



    freshness: float | None = None



    issues: list[dict]



    recommendations: list[str]











@router.post("/versions/health", response_model=VersionHealthScore)



async def check_version_health(



    request: VersionHealthRequest,



) -> VersionHealthScore:



    """Check health score for a specific version."""



    if request.version_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Version {request.version_id} not found")







    version = _versions[request.version_id]



    entities = version.get("entities", {})



    relations = version.get("relations", {})







    issues = []



    recommendations = []



    scores = {}







    if request.check_completeness:



        # Check if entities have required fields



        incomplete_entities = 0



        for eid, entity in entities.items():



            # Check for basic required fields



            has_name = "name" in entity



            has_type = "type" in entity



            has_props = "properties" in entity or len(entity) > 2



            if not (has_name and has_type):



                incomplete_entities += 1



                issues.append({



                    "entity_id": eid,



                    "type": "incomplete",



                    "description": f"Entity '{eid}' missing required fields"



                })







        completeness = 100 * (1 - incomplete_entities / max(len(entities), 1))



        scores["completeness"] = round(completeness, 2)







        if completeness < 80:



            recommendations.append("Add required fields (name, type) to all entities")







    if request.check_consistency:



        # Check relation consistency - verify source/target entities exist



        broken_relations = 0



        for rid, relation in relations.items():



            src = relation.get("source")



            tgt = relation.get("target")



            if src not in entities or tgt not in entities:



                broken_relations += 1



                issues.append({



                    "relation_id": rid,



                    "type": "broken",



                    "description": f"Relation '{rid}' references non-existent entity"



                })







        consistency = 100 * (1 - broken_relations / max(len(relations), 1))



        scores["consistency"] = round(consistency, 2)







        if broken_relations > 0:



            recommendations.append("Fix or remove broken relations referencing non-existent entities")







    if request.check_freshness:



        # Check how recent the version is



        ts = version.get("timestamp", "")



        if ts:



            try:



                from datetime import datetime, timedelta



                import pytz



                # Try to parse timestamp



                for fmt in ["%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%d"]:



                    try:



                        version_dt = datetime.strptime(ts[:19], fmt)



                        age_days = (datetime.now() - version_dt).days



                        if age_days <= 1:



                            freshness = 100



                        elif age_days <= 7:



                            freshness = 80



                        elif age_days <= 30:



                            freshness = 60



                        else:



                            freshness = 40



                        scores["freshness"] = freshness



                        break



                    except:



                        continue



            except:



                scores["freshness"] = 50  # Unknown







        if scores.get("freshness", 100) < 60:



            recommendations.append("Version is stale - consider creating a fresh snapshot")







    # Calculate overall score



    valid_scores = [v for v in scores.values() if v is not None]



    overall = sum(valid_scores) / len(valid_scores) if valid_scores else 50







    return VersionHealthScore(



        overall=round(overall, 2),



        completeness=scores.get("completeness"),



        consistency=scores.get("consistency"),



        freshness=scores.get("freshness"),



        issues=issues,



        recommendations=recommendations



    )











class VersionTimelineEntry(BaseModel):



    """Single entry in version timeline."""



    version_id: str



    timestamp: str



    entity_count: int



    relation_count: int



    delta_entities: int



    delta_relations: int











@router.get("/versions/timeline", response_model=list[VersionTimelineEntry])



async def get_version_timeline() -> list[VersionTimelineEntry]:



    """Get timeline of all versions with delta information."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    # Sort versions by timestamp



    sorted_versions = sorted(



        _versions.items(),



        key=lambda x: x[1].get("timestamp", ""),



        reverse=True



    )







    timeline = []



    prev_entity_count = 0



    prev_relation_count = 0







    for version_id, version in sorted_versions:



        entity_count = len(version.get("entities", {}))



        relation_count = len(version.get("relations", {}))







        delta_entities = entity_count - prev_entity_count



        delta_relations = relation_count - prev_relation_count







        timeline.append(VersionTimelineEntry(



            version_id=version_id,



            timestamp=version.get("timestamp", ""),



            entity_count=entity_count,



            relation_count=relation_count,



            delta_entities=delta_entities,



            delta_relations=delta_relations



        ))







        prev_entity_count = entity_count



        prev_relation_count = relation_count







    return timeline











