# ========== Cross-Version Entity Lineage ==========







class EntityLineageRequest(BaseModel):



    """Request to track entity lineage across versions."""



    entity_id: str = Field(description="Entity ID to track")



    include_ancestors: bool = Field(default=True, description="Include ancestor versions")



    include_descendants: bool = Field(default=True, description="Include descendant versions")



    max_depth: int = Field(default=10, ge=1, le=50, description="Maximum lineage depth")











class EntityLineageEntry(BaseModel):



    """Single lineage entry."""



    version_id: str



    timestamp: str



    exists: bool



    data: dict[str, Any] | None = None



    parent_version_id: str | None = None











class EntityLineageResponse(BaseModel):



    """Entity lineage across versions."""



    entity_id: str



    total_versions: int



    first_seen: str | None



    last_seen: str | None



    lineage: list[EntityLineageEntry]



    lineage_chain: list[str]  # Version IDs in order











def _track_entity_lineage(



    entity_id: str,



    include_ancestors: bool,



    include_descendants: bool,



    max_depth: int,



) -> EntityLineageResponse:



    """Track entity across all versions."""



    lineage = []



    lineage_chain = []







    # Sort versions by timestamp



    sorted_versions = sorted(



        _versions.items(),



        key=lambda x: x[1].get("timestamp", ""),



    )







    first_seen = None



    last_seen = None







    for vid, version in sorted_versions:



        entities = version.get("entities", {})



        exists = entity_id in entities







        if exists:



            if first_seen is None:



                first_seen = version.get("timestamp", "")



            last_seen = version.get("timestamp", "")







        entry = EntityLineageEntry(



            version_id=vid,



            timestamp=version.get("timestamp", ""),



            exists=exists,



            data=dict(entities[entity_id]) if exists else None,



            parent_version_id=None,



        )



        lineage.append(entry)



        if exists:



            lineage_chain.append(vid)







    # Limit results



    if len(lineage) > max_depth:



        lineage = lineage[:max_depth]



        lineage_chain = lineage_chain[:max_depth]







    return EntityLineageResponse(



        entity_id=entity_id,



        total_versions=len(_versions),



        first_seen=first_seen,



        last_seen=last_seen,



        lineage=lineage,



        lineage_chain=lineage_chain,



    )











@router.post("/versions/entity-lineage", response_model=EntityLineageResponse)



async def get_entity_lineage(



    request: EntityLineageRequest,



) -> EntityLineageResponse:



    """Track entity evolution across all versions."""



    return _track_entity_lineage(



        request.entity_id,



        request.include_ancestors,



        request.include_descendants,



        request.max_depth,



    )











class EntityMutation(BaseModel):



    """Entity change between versions."""



    entity_id: str



    version_a: str



    version_b: str



    change_type: str  # added, removed, modified, unchanged



    attribute_changes: dict[str, tuple[Any, Any]] | None = None











class EntityMutationResponse(BaseModel):



    """Entity mutations across versions."""



    entity_id: str



    mutations: list[EntityMutation]



    total_mutations: int



    mutation_frequency: float











@router.post("/versions/entity-mutations", response_model=EntityMutationResponse)



async def get_entity_mutations(



    entity_id: str = Body(..., description="Entity ID to track"),



    version_ids: list[str] | None = Body(None, description="Specific versions to compare"),



) -> EntityMutationResponse:



    """Track entity mutations (changes) across versions."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    # Get versions to compare



    if version_ids:



        target_versions = [(vid, _versions[vid]) for vid in version_ids if vid in _versions]



        if not target_versions:



            raise HTTPException(status_code=404, detail="No matching versions found")



    else:



        target_versions = sorted(



            _versions.items(),



            key=lambda x: x[1].get("timestamp", ""),



        )







    mutations = []



    prev_entity_data = None



    prev_version_id = None







    for vid, version in target_versions:



        entities = version.get("entities", {})



        exists = entity_id in entities



        current_entity_data = entities.get(entity_id) if exists else None







        if prev_entity_data is None:



            # First version



            if exists:



                change_type = "added"



                mutations.append(EntityMutation(



                    entity_id=entity_id,



                    version_a="",



                    version_b=vid,



                    change_type=change_type,



                ))



        else:



            if exists and prev_entity_data:



                # Check for modifications



                attr_changes = {}



                for key in set(prev_entity_data.keys()) | set(current_entity_data.keys()):



                    old_val = prev_entity_data.get(key)



                    new_val = current_entity_data.get(key)



                    if old_val != new_val:



                        attr_changes[key] = (old_val, new_val)







                if attr_changes:



                    change_type = "modified"



                    mutations.append(EntityMutation(



                        entity_id=entity_id,



                        version_a=prev_version_id,



                        version_b=vid,



                        change_type=change_type,



                        attribute_changes=attr_changes,



                    ))



                else:



                    change_type = "unchanged"



            elif exists and not prev_entity_data:



                change_type = "added"



                mutations.append(EntityMutation(



                    entity_id=entity_id,



                    version_a=prev_version_id or "",



                    version_b=vid,



                    change_type=change_type,



                ))



            elif not exists and prev_entity_data:



                change_type = "removed"



                mutations.append(EntityMutation(



                    entity_id=entity_id,



                    version_a=prev_version_id,



                    version_b=vid,



                    change_type=change_type,



                ))







        prev_entity_data = current_entity_data



        prev_version_id = vid







    total_mutations = len(mutations)



    mutation_freq = total_mutations / len(target_versions) if target_versions else 0







    return EntityMutationResponse(



        entity_id=entity_id,



        mutations=mutations,



        total_mutations=total_mutations,



        mutation_frequency=round(mutation_freq, 2),



    )











