# In-memory storage for new features



_scheduled_rollbacks: dict[str, ScheduledRollback] = {}



_retention_policies: dict[str, VersionRetentionPolicy] = {}



_version_merges: dict[str, VersionMergeResult] = {}



_merged_versions: dict[str, dict] = {}







# ── Cron Helper Functions ───────────────────────────────











def _parse_cron_next_run(cron_expr: str, from_datetime: datetime | None = None) -> str | None:



    """Calculate next run time from cron expression. Returns ISO string or None if invalid."""



    if from_datetime is None:



        from_datetime = datetime.now(timezone.utc)







    parts = cron_expr.strip().split()



    if len(parts) < 5:



        return None







    try:



        minute, hour, day, month, weekday = parts[:5]







        # Simple calculation - just calculate next occurrence



        # This is a simplified implementation



        next_dt = from_datetime.replace(second=0, microsecond=0)







        # Handle minute



        if minute == "*":



            pass



        elif minute.isdigit():



            next_dt = next_dt.replace(minute=int(minute))



        else:



            return None







        # Handle hour



        if hour == "*":



            pass



        elif hour.isdigit():



            next_dt = next_dt.replace(hour=int(hour))



        else:



            return None







        # If calculated time is in past, add a day



        if next_dt <= from_datetime:



            from datetime import timedelta



            next_dt = next_dt + timedelta(days=1)







        return next_dt.isoformat()



    except Exception:



        return None











def _check_rollback_condition(condition: str | None, threshold: float | None) -> bool:



    """Check if rollback condition is met."""



    if not condition or threshold is None:



        return True







    condition = condition.lower()







    if condition == "entity_count_below":



        current_count = len(_entities)



        return current_count < threshold



    elif condition == "entity_count_above":



        current_count = len(_entities)



        return current_count > threshold



    elif condition == "relation_count_below":



        current_count = len(_relations)



        return current_count < threshold



    elif condition == "relation_count_above":



        current_count = len(_relations)



        return current_count > threshold



    elif condition == "version_count_above":



        current_count = len(_versions)



        return current_count > threshold



    elif condition == "version_count_below":



        current_count = len(_versions)



        return current_count < threshold







    return True











