@router.post("/versions/scheduled-rollbacks", response_model=ScheduledRollbackResponse)



async def create_scheduled_rollback(req: ScheduledRollbackCreate) -> ScheduledRollbackResponse:



    """Create a scheduled rollback."""



    # Validate target version exists



    if req.target_version_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Target version {req.target_version_id} not found")







    # Validate cron expression



    next_run = _parse_cron_next_run(req.cron_expression)



    if next_run is None:



        raise HTTPException(status_code=400, detail="Invalid cron expression. Use: minute hour day month weekday")







    schedule = ScheduledRollback(



        name=req.name,



        cron_expression=req.cron_expression,



        target_version_id=req.target_version_id,



        condition=req.condition,



        condition_threshold=req.condition_threshold,



        next_scheduled=next_run,



    )







    _scheduled_rollbacks[schedule.schedule_id] = schedule







    return ScheduledRollbackResponse(



        schedule_id=schedule.schedule_id,



        name=schedule.name,



        cron_expression=schedule.cron_expression,



        target_version_id=schedule.target_version_id,



        enabled=schedule.enabled,



        created_at=schedule.created_at,



        message="Scheduled rollback created successfully",



    )











