async def delete_scheduled_rollback(schedule_id: str) -> dict:



    """Delete a scheduled rollback."""



    if schedule_id not in _scheduled_rollbacks:



        raise HTTPException(status_code=404, detail="Scheduled rollback not found")







    del _scheduled_rollbacks[schedule_id]



    return {"message": "Scheduled rollback deleted", "schedule_id": schedule_id}











@router.post("/versions/scheduled-rollbacks/{schedule_id}/trigger", response_model=dict)



async def trigger_scheduled_rollback(schedule_id: str) -> dict:



    """Manually trigger a scheduled rollback."""



    if schedule_id not in _scheduled_rollbacks:



        raise HTTPException(status_code=404, detail="Scheduled rollback not found")







    schedule = _scheduled_rollbacks[schedule_id]







    if not schedule.enabled:



        raise HTTPException(status_code=400, detail="Scheduled rollback is disabled")







    # Check condition



    if not _check_rollback_condition(schedule.condition, schedule.condition_threshold):



        return {"message": "Condition not met, skipping rollback", "schedule_id": schedule_id}







    # Check target version exists



    if schedule.target_version_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Target version {schedule.target_version_id} not found")







    # Perform rollback



    target_version = _versions[schedule.target_version_id]







    # Backup current state



    backup_id = f"auto_backup_{uuid.uuid4().hex[:8]}"



    _versions[backup_id] = {



        "entities": dict(_entities),



        "relations": dict(_relations),



        "timestamp": datetime.now(timezone.utc).isoformat(),



        "type": "auto_backup",



    }







    # Restore target version



    _entities.clear()



    _entities.update(target_version.get("entities", {}))



    _relations.clear()



    _relations.update(target_version.get("relations", {}))







    # Update schedule



    schedule.last_triggered = datetime.now(timezone.utc).isoformat()



    schedule.next_scheduled = _parse_cron_next_run(schedule.cron_expression)



    schedule.trigger_count += 1



    _scheduled_rollbacks[schedule_id] = schedule







    return {



        "message": "Scheduled rollback triggered successfully",



        "schedule_id": schedule_id,



        "target_version_id": schedule.target_version_id,



        "backup_id": backup_id,



        "timestamp": schedule.last_triggered,



    }











@router.post("/versions/scheduled-rollbacks/{schedule_id}/toggle", response_model=dict)



async def toggle_scheduled_rollback(schedule_id: str) -> dict:



    """Enable or disable a scheduled rollback."""



    if schedule_id not in _scheduled_rollbacks:



        raise HTTPException(status_code=404, detail="Scheduled rollback not found")







    schedule = _scheduled_rollbacks[schedule_id]



    schedule.enabled = not schedule.enabled



    if schedule.enabled:



        schedule.next_scheduled = _parse_cron_next_run(schedule.cron_expression)



    else:



        schedule.next_scheduled = None







    return {



        "schedule_id": schedule_id,



        "enabled": schedule.enabled,



        "message": f"Scheduled rollback {'enabled' if schedule.enabled else 'disabled'}",



    }











