@router.post("/versions/policies/{policy_id}/trigger", response_model=dict)



async def trigger_version_policy(policy_id: str, entity_id: str = None) -> dict:



    """Manually trigger a policy."""



    if policy_id not in _version_policies:



        raise HTTPException(status_code=404, detail="Policy not found")







    policy = _version_policies[policy_id]



    if not policy.enabled:



        raise HTTPException(status_code=400, detail="Policy is disabled")







    executions = []







    # Evaluate condition



    condition_met = _evaluate_policy_condition(policy.conditions, entity_id)



    if condition_met:



        # Execute actions



        for action in policy.actions:



            result = _execute_policy_action(action, entity_id)



            executions.append(result)







        policy.execution_count += 1



        policy.last_executed = datetime.utcnow().isoformat()







    return {



        "policy_id": policy_id,



        "condition_met": condition_met,



        "executions": executions,



    }











def _evaluate_policy_condition(conditions: dict, entity_id: str = None) -> bool:



    """Evaluate if a policy condition is met."""



    field = conditions.get("field")



    operator = conditions.get("operator")



    value = conditions.get("value")







    if not field or not operator:



        return True







    actual_value = None







    # Get actual value based on field



    if field == "entity_count":



        actual_value = len(_entity_versions) if not entity_id else len(_entity_versions.get(entity_id, []))



    elif field == "version_count":



        actual_value = len(_versions)



    elif field == "version_age_days":



        if _versions:



            first_version = list(_versions.values())[0]



            created = first_version.get("created_at", "")



            if created:



                created_time = datetime.fromisoformat(created.replace("Z", "+00:00"))



                actual_value = (datetime.utcnow() - created_time.replace(tzinfo=None)).days



    elif field == "total_entities":



        actual_value = len(_entity_versions)







    if actual_value is None:



        return False







    # Evaluate operator



    if operator == "gt":



        return actual_value > value



    elif operator == "gte":



        return actual_value >= value



    elif operator == "lt":



        return actual_value < value



    elif operator == "lte":



        return actual_value <= value



    elif operator == "eq":



        return actual_value == value



    elif operator == "neq":



        return actual_value != value







    return False











def _execute_policy_action(action: dict, entity_id: str = None) -> dict:



    """Execute a policy action."""



    action_type = action.get("type")



    params = action.get("params", {})







    if action_type == "tag":



        tag = params.get("tag", "")



        if entity_id and entity_id in _entity_versions:



            for v in _entity_versions[entity_id]:



                if "tags" not in v:



                    v["tags"] = []



                if tag not in v["tags"]:



                    v["tags"].append(tag)



        return {"action": "tag", "tag": tag, "status": "executed"}







    elif action_type == "notify":



        message = params.get("message", "Policy triggered")



        return {"action": "notify", "message": message, "status": "executed"}







    elif action_type == "archive":



        if entity_id and entity_id in _entity_versions:



            for v in _entity_versions[entity_id]:



                v["archived"] = True



        return {"action": "archive", "status": "executed"}







    elif action_type == "delete_version":



        if entity_id and entity_id in _entity_versions:



            versions = _entity_versions[entity_id]



            if versions:



                oldest = versions[-1]



                versions.remove(oldest)



        return {"action": "delete_version", "status": "executed"}







    elif action_type == "merge":



        return {"action": "merge", "status": "scheduled"}







    return {"action": action_type, "status": "unknown"}











@router.post("/versions/policies/evaluate", response_model=list[dict])



async def evaluate_all_policies(entity_id: str = None) -> list[dict]:



    """Evaluate all enabled policies and return which ones would trigger."""



    results = []







    # Sort by priority



    policies = sorted(_version_policies.values(), key=lambda p: p.priority, reverse=True)







    for policy in policies:



        if not policy.enabled:



            continue







        condition_met = _evaluate_policy_condition(policy.conditions, entity_id)



        results.append({



            "policy_id": policy.policy_id,



            "name": policy.name,



            "condition_met": condition_met,



            "actions": policy.actions if condition_met else [],



        })







    return results











