# ── Version Comparison Endpoints ───────────────────────────────────







@router.post("/versions/compare", response_model=dict)



async def compare_versions(req: VersionCompareRequest) -> dict:



    """Compare two versions and return differences."""



    v1 = _versions.get(req.version_id_1)



    v2 = _versions.get(req.version_id_2)







    if not v1 or not v2:



        return {"error": "One or both versions not found"}







    comparison_id = f"cmp_{int(time.time())}"







    # Calculate similarity



    entities1 = set(v1.get("entities", []))



    entities2 = set(v2.get("entities", []))



    common = entities1 & entities2



    union = entities1 | entities2



    similarity = len(common) / len(union) * 100 if union else 0







    # Find differences



    unique_to_v1 = list(entities1 - entities2)



    unique_to_v2 = list(entities2 - entities1)







    # Metadata diff



    metadata_diff = {}



    for key in set(v1.keys()) | set(v2.keys()):



        if v1.get(key) != v2.get(key):



            metadata_diff[key] = {



                "version_1": v1.get(key),



                "version_2": v2.get(key),



            }







    # Tag diff



    tags1 = set(v1.get("tags", []))



    tags2 = set(v2.get("tags", []))



    tag_diff = {



        "common": list(tags1 & tags2),



        "unique_to_v1": list(tags1 - tags2),



        "unique_to_v2": list(tags2 - tags1),



    }







    comparison = {



        "comparison_id": comparison_id,



        "version_id_1": req.version_id_1,



        "version_id_2": req.version_id_2,



        "compare_type": req.compare_type,



        "similarity_score": similarity,



        "common_entities": list(common),



        "unique_to_v1": unique_to_v1,



        "unique_to_v2": unique_to_v2,



        "metadata_diff": metadata_diff,



        "tag_diff": tag_diff,



        "entity_count_v1": len(entities1),



        "entity_count_v2": len(entities2),



        "timestamp": time.time(),



    }







    _version_comparisons[comparison_id] = comparison



    return comparison











