@router.post("/versions/diff", response_model=dict)



async def get_version_diff(req: VersionDiffRequest) -> dict:



    """Get detailed diff between two versions."""



    v1 = _versions.get(req.version_id_1)



    v2 = _versions.get(req.version_id_2)







    if not v1 or not v2:



        return {"error": "One or both versions not found"}







    entities1 = v1.get("entities", [])



    entities2 = v2.get("entities", [])







    # Calculate diff stats



    set1, set2 = set(entities1), set(entities2)



    added = set2 - set1  # In v2 but not v1



    removed = set1 - set2  # In v1 but not v2



    modified = []  # Could be enhanced with actual diff







    diff_result = {



        "version_id_1": req.version_id_1,



        "version_id_2": req.version_id_2,



        "stats": {



            "added_count": len(added),



            "removed_count": len(removed),



            "unchanged_count": len(set1 & set2),



            "total_change": len(added) + len(removed),



        },



        "added_entities": list(added),



        "removed_entities": list(removed),



        "similarity_percentage": len(set1 & set2) / max(len(set1 | set2), 1) * 100,



    }







    return diff_result











@router.post("/versions/analytics", response_model=dict)



async def get_version_analytics(req: VersionAnalyticsRequest) -> dict:



    """Get analytics for multiple versions."""



    versions_data = []



    for vid in req.version_ids:



        v = _versions.get(vid)



        if v:



            versions_data.append({



                "version_id": vid,



                "entity_count": len(v.get("entities", [])),



                "created_at": v.get("created_at"),



                "tags": v.get("tags", []),



            })







    if not versions_data:



        return {"error": "No valid versions found"}







    analytics = {



        "version_count": len(versions_data),



        "total_entities": sum(v["entity_count"] for v in versions_data),



        "avg_entities_per_version": sum(v["entity_count"] for v in versions_data) / len(versions_data),



    }







    if req.metric in ("all", "growth"):



        # Calculate growth metrics



        sorted_versions = sorted(versions_data, key=lambda v: v.get("created_at", 0))



        if len(sorted_versions) > 1:



            first_count = sorted_versions[0]["entity_count"]



            last_count = sorted_versions[-1]["entity_count"]



            analytics["growth"] = {



                "first_version_entities": first_count,



                "last_version_entities": last_count,



                "growth_rate": ((last_count - first_count) / max(first_count, 1)) * 100,



            }







    if req.metric in ("all", "activity"):



        # Activity metrics



        analytics["activity"] = {



            "versions_with_tags": sum(1 for v in versions_data if v.get("tags")),



            "tag_coverage": sum(1 for v in versions_data if v.get("tags")) / len(versions_data) * 100,



        }







    if req.metric in ("all", "quality"):



        # Quality metrics



        analytics["quality"] = {



            "min_entities": min(v["entity_count"] for v in versions_data),



            "max_entities": max(v["entity_count"] for v in versions_data),



            "versions_over_50_entities": sum(1 for v in versions_data if v["entity_count"] > 50),



        }







    return analytics











@router.get("/versions/timeline", response_model=dict)



async def get_version_timeline() -> dict:



    """Get timeline of all versions."""



    versions = []



    for vid, v in _versions.items():



        versions.append({



            "version_id": vid,



            "created_at": v.get("created_at"),



            "entity_count": len(v.get("entities", [])),



            "label": v.get("label"),



            "is_draft": v.get("is_draft"),



        })







    versions.sort(key=lambda v: v.get("created_at", 0))







    timeline = []



    cumulative = 0



    for v in versions:



        cumulative += v["entity_count"]



        timeline.append({



            "version_id": v["version_id"],



            "timestamp": v.get("created_at"),



            "entity_count": v["entity_count"],



            "cumulative_entities": cumulative,



            "label": v.get("label"),



        })







    return {



        "timeline": timeline,



        "total_versions": len(versions),



        "total_entities": cumulative,



    }











