# Version Workflow Automation (v1.25.0)



# =============================================================================







class VersionWorkflow:



    """Version workflow model."""







    def __init__(



        self,



        workflow_id: str,



        name: str,



        description: str,



        trigger: str,  # on_create, on_update, on_delete, on_tag_added, etc.



        conditions: list[dict],



        actions: list[dict],



        enabled: bool = True,



        priority: int = 0,



    ):



        self.workflow_id = workflow_id



        self.name = name



        self.description = description



        self.trigger = trigger



        self.conditions = conditions



        self.actions = actions



        self.enabled = enabled



        self.priority = priority







    def to_dict(self) -> dict:



        return {



            "workflow_id": self.workflow_id,



            "name": self.name,



            "description": self.description,



            "trigger": self.trigger,



            "conditions": self.conditions,



            "actions": self.actions,



            "enabled": self.enabled,



            "priority": self.priority,



        }











class WorkflowExecution:



    """Workflow execution result."""







    def __init__(



        self,



        execution_id: str,



        workflow_id: str,



        version_id: str,



        trigger: str,



        status: str,  # success, failed, skipped



        timestamp: str,



        results: dict | None = None,



        error: str | None = None,



    ):



        self.execution_id = execution_id



        self.workflow_id = workflow_id



        self.version_id = version_id



        self.trigger = trigger



        self.status = status



        self.timestamp = timestamp



        self.results = results or {}



        self.error = error







    def to_dict(self) -> dict:



        return {



            "execution_id": self.execution_id,



            "workflow_id": self.workflow_id,



            "version_id": self.version_id,



            "trigger": self.trigger,



            "status": self.status,



            "timestamp": self.timestamp,



            "results": self.results,



            "error": self.error,



        }











# Available triggers



WORKFLOW_TRIGGERS = [



    "on_version_created",



    "on_version_updated",



    "on_version_deleted",



    "on_version_restored",



    "on_version_tagged",



    "on_version_untagged",



    "on_version_exported",



    "on_version_imported",



    "on_version_compared",



    "on_version_merged",



    "on_version_rolled_back",



    "on_version_analyzed",



    "on_version_categorized",



    "on_version_policy_triggered",



    "manual",



]







# Available actions



WORKFLOW_ACTIONS = [



    "add_tag",



    "remove_tag",



    "set_category",



    "set_label",



    "notify",



    "archive",



    "backup",



    "validate",



    "run_analysis",



    "trigger_policy",



    "create_version",



]







# Condition operators



CONDITION_OPERATORS = [



    "equals",



    "not_equals",



    "contains",



    "not_contains",



    "greater_than",



    "less_than",



    "in",



    "not_in",



]







# In-memory stores



_version_workflows: dict[str, VersionWorkflow] = {}



_workflow_executions: dict[str, WorkflowExecution] = {}



_workflow_execution_history: list[WorkflowExecution] = []











def _generate_workflow_id() -> str:



    """Generate unique workflow ID."""



    return f"wf_{_now_iso()}_{len(_version_workflows) + 1}"











def _generate_execution_id() -> str:



    """Generate unique execution ID."""



    return f"exec_{_now_iso()}_{len(_workflow_executions) + 1}"











def _check_workflow_conditions(



    version_data: dict,



    conditions: list[dict],



) -> tuple[bool, str]:



    """Check if workflow conditions are met."""



    if not conditions:



        return True, "No conditions to check"







    for condition in conditions:



        field = condition.get("field", "")



        operator = condition.get("operator", "equals")



        value = condition.get("value")







        # Get version field value



        version_value = version_data.get(field)







        # Check condition



        if operator == "equals":



            if version_value != value:



                return False, f"Field {field} is not {value}"



        elif operator == "not_equals":



            if version_value == value:



                return False, f"Field {field} is {value}"



        elif operator == "contains":



            if not version_value or value not in str(version_value):



                return False, f"Field {field} does not contain {value}"



        elif operator == "not_contains":



            if value in str(version_value):



                return False, f"Field {field} contains {value}"



        elif operator == "greater_than":



            try:



                if float(version_value or 0) <= float(value):



                    return False, f"Field {field} is not greater than {value}"



            except (ValueError, TypeError):



                return False, f"Field {field} is not numeric"



        elif operator == "less_than":



            try:



                if float(version_value or 0) >= float(value):



                    return False, f"Field {field} is not less than {value}"



            except (ValueError, TypeError):



                return False, f"Field {field} is not numeric"



        elif operator == "in":



            if version_value not in (value if isinstance(value, list) else [value]):



                return False, f"Field {field} is not in allowed values"



        elif operator == "not_in":



            if version_value in (value if isinstance(value, list) else [value]):



                return False, f"Field {field} is in disallowed values"







    return True, "All conditions met"











async def _execute_workflow_action(



    action: dict,



    version_id: str,



    version_data: dict,



) -> tuple[bool, dict, str]:



    """Execute a single workflow action."""



    action_type = action.get("type")



    params = action.get("params", {})







    try:



        if action_type == "add_tag":



            tag = params.get("tag")



            if tag and tag not in version_data.get("tags", []):



                version_data.setdefault("tags", []).append(tag)



            return True, {"tag": tag}, "Tag added"







        elif action_type == "remove_tag":



            tag = params.get("tag")



            if tag and tag in version_data.get("tags", []):



                version_data["tags"].remove(tag)



            return True, {"tag": tag}, "Tag removed"







        elif action_type == "set_category":



            category = params.get("category")



            version_data["category"] = category



            return True, {"category": category}, "Category set"







        elif action_type == "set_label":



            label = params.get("label")



            version_data["label"] = label



            return True, {"label": label}, "Label set"







        elif action_type == "notify":



            # Placeholder for notification



            message = params.get("message", f"Workflow executed for version {version_id}")



            return True, {"message": message}, "Notification sent"







        elif action_type == "archive":



            version_data["archived"] = True



            return True, {}, "Version archived"







        elif action_type == "backup":



            # Create a backup version



            backup_id = f"{version_id}_backup_{_now_iso()}"



            backup_data = version_data.copy()



            backup_data["version_id"] = backup_id



            backup_data["created_at"] = _now_iso()



            _versions[backup_id] = backup_data



            return True, {"backup_id": backup_id}, "Backup created"







        elif action_type == "validate":



            # Run validation



            return True, {"valid": True}, "Validation passed"







        elif action_type == "run_analysis":



            # Run version analysis



            analysis = {



                "version_id": version_id,



                "entity_count": len(version_data.get("entities", [])),



                "tag_count": len(version_data.get("tags", [])),



                "analyzed_at": _now_iso(),



            }



            return True, analysis, "Analysis completed"







        elif action_type == "trigger_policy":



            policy_id = params.get("policy_id")



            if policy_id in _retention_policies:



                # Trigger policy



                return True, {"policy_id": policy_id}, "Policy triggered"



            return False, {}, f"Policy {policy_id} not found"







        elif action_type == "create_version":



            # Create a new version based on current



            new_version_id = params.get("version_id", f"new_{_now_iso()}")



            new_data = {



                "version_id": new_version_id,



                "entities": version_data.get("entities", []).copy(),



                "tags": version_data.get("tags", []).copy(),



                "metadata": version_data.get("metadata", {}).copy(),



                "created_at": _now_iso(),



            }



            _versions[new_version_id] = new_data



            return True, {"version_id": new_version_id}, "Version created"







        else:



            return False, {}, f"Unknown action type: {action_type}"







    except Exception as e:



        return False, {}, str(e)











async def _execute_workflow(



    workflow: VersionWorkflow,



    version_id: str,



    trigger: str,



) -> WorkflowExecution:



    """Execute a workflow for a version."""



    version_data = _versions.get(version_id, {})







    # Check conditions



    conditions_met, condition_msg = _check_workflow_conditions(



        version_data,



        workflow.conditions,



    )







    if not conditions_met:



        exec_result = WorkflowExecution(



            execution_id=_generate_execution_id(),



            workflow_id=workflow.workflow_id,



            version_id=version_id,



            trigger=trigger,



            status="skipped",



            timestamp=_now_iso(),



            error=condition_msg,



        )



        _workflow_executions[exec_result.execution_id] = exec_result



        _workflow_execution_history.append(exec_result)



        return exec_result







    # Execute actions



    results = {}



    all_success = True



    errors = []







    for action in workflow.actions:



        success, result, msg = await _execute_workflow_action(



            action,



            version_id,



            version_data,



        )



        results[action.get("type")] = {"success": success, "message": msg, "result": result}



        if not success:



            all_success = False



            errors.append(msg)







    # Update version if modified



    if version_id in _versions:



        _versions[version_id] = version_data







    # Create execution record



    exec_result = WorkflowExecution(



        execution_id=_generate_execution_id(),



        workflow_id=workflow.workflow_id,



        version_id=version_id,



        trigger=trigger,



        status="success" if all_success else "failed",



        timestamp=_now_iso(),



        results=results,



        error="; ".join(errors) if errors else None,



    )



    _workflow_executions[exec_result.execution_id] = exec_result



    _workflow_execution_history.append(exec_result)







    # Keep only last 1000 executions



    if len(_workflow_execution_history) > 1000:



        _workflow_execution_history = _workflow_execution_history[-1000:]







    return exec_result











async def _trigger_workflows(



    trigger: str,



    version_id: str,



    details: dict | None = None,



) -> list[WorkflowExecution]:



    """Trigger all workflows matching the trigger type."""



    # Record event



    _record_version_event(



        event_type=f"workflow_{trigger}",



        version_id=version_id,



        details=details,



    )







    # Find matching workflows



    matching_workflows = [



        wf for wf in _version_workflows.values()



        if wf.enabled and wf.trigger == trigger



    ]







    # Sort by priority



    matching_workflows.sort(key=lambda w: w.priority, reverse=True)







    # Execute workflows



    executions = []



    for workflow in matching_workflows:



        execution = await _execute_workflow(workflow, version_id, trigger)



        executions.append(execution)







    return executions











