class CreateWorkflowRequest(BaseModel):



    """Create workflow request."""



    name: str



    description: str



    trigger: str



    conditions: list[dict] = []



    actions: list[dict]



    enabled: bool = True



    priority: int = 0











class ExecuteWorkflowRequest(BaseModel):



    """Execute workflow request."""



    version_id: str











class WorkflowTriggerRequest(BaseModel):



    """Trigger workflows request."""



    version_id: str



    trigger: str | None = None











@router.post("/versions/workflows", response_model=dict)



async def create_workflow(req: CreateWorkflowRequest) -> dict:



    """Create a new workflow."""



    if req.trigger not in WORKFLOW_TRIGGERS:



        raise HTTPException(



            status_code=400,



            detail=f"Invalid trigger. Available: {WORKFLOW_TRIGGERS}"



        )







    # Validate actions



    for action in req.actions:



        if action.get("type") not in WORKFLOW_ACTIONS:



            raise HTTPException(



                status_code=400,



                detail=f"Invalid action: {action.get('type')}. Available: {WORKFLOW_ACTIONS}"



            )







    # Validate conditions



    for condition in req.conditions:



        if condition.get("operator") not in CONDITION_OPERATORS:



            raise HTTPException(



                status_code=400,



                detail=f"Invalid operator: {condition.get('operator')}. Available: {CONDITION_OPERATORS}"



            )







    workflow_id = _generate_workflow_id()



    workflow = VersionWorkflow(



        workflow_id=workflow_id,



        name=req.name,



        description=req.description,



        trigger=req.trigger,



        conditions=req.conditions,



        actions=req.actions,



        enabled=req.enabled,



        priority=req.priority,



    )



    _version_workflows[workflow_id] = workflow







    return {



        "workflow_id": workflow_id,



        **workflow.to_dict(),



    }











@router.get("/versions/workflows", response_model=list[dict])



async def list_workflows(enabled: bool | None = None) -> list[dict]:



    """List all workflows."""



    workflows = list(_version_workflows.values())







    if enabled is not None:



        workflows = [w for w in workflows if w.enabled == enabled]







    return [w.to_dict() for w in workflows]











@router.get("/versions/workflows/{workflow_id}", response_model=dict)



async def get_workflow(workflow_id: str) -> dict:



    """Get workflow details."""



    if workflow_id not in _version_workflows:



        raise HTTPException(status_code=404, detail="Workflow not found")







    return _version_workflows[workflow_id].to_dict()











@router.delete("/versions/workflows/{workflow_id}", response_model=dict)



async def delete_workflow(workflow_id: str) -> dict:



    """Delete a workflow."""



    if workflow_id not in _version_workflows:



        raise HTTPException(status_code=404, detail="Workflow not found")







    workflow = _version_workflows.pop(workflow_id)







    return {



        "workflow_id": workflow_id,



        "deleted": True,



        "name": workflow.name,



    }











@router.post("/versions/workflows/{workflow_id}/toggle", response_model=dict)



async def toggle_workflow(workflow_id: str) -> dict:



    """Toggle workflow enabled/disabled."""



    if workflow_id not in _version_workflows:



        raise HTTPException(status_code=404, detail="Workflow not found")







    workflow = _version_workflows[workflow_id]



    workflow.enabled = not workflow.enabled







    return {



        "workflow_id": workflow_id,



        "enabled": workflow.enabled,



    }











@router.post("/versions/workflows/{workflow_id}/execute", response_model=dict)



async def execute_workflow(workflow_id: str, req: ExecuteWorkflowRequest) -> dict:



    """Execute a workflow manually."""



    if workflow_id not in _version_workflows:



        raise HTTPException(status_code=404, detail="Workflow not found")







    if req.version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    workflow = _version_workflows[workflow_id]



    execution = await _execute_workflow(workflow, req.version_id, "manual")







    return execution.to_dict()











@router.post("/versions/workflows/trigger", response_model=list[dict])



async def trigger_workflows(req: WorkflowTriggerRequest) -> list[dict]:



    """Trigger workflows for a version."""



    if req.version_id not in _versions:



        raise HTTPException(status_code=404, detail="Version not found")







    trigger = req.trigger or "manual"



    executions = await _trigger_workflows(trigger, req.version_id)







    return [e.to_dict() for e in executions]











@router.get("/versions/workflows/executions", response_model=list[dict])



async def list_workflow_executions(



    workflow_id: str | None = None,



    version_id: str | None = None,



    status: str | None = None,



    limit: int = 50,



) -> list[dict]:



    """List workflow executions."""



    executions = list(_workflow_execution_history)







    if workflow_id:



        executions = [e for e in executions if e.workflow_id == workflow_id]



    if version_id:



        executions = [e for e in executions if e.version_id == version_id]



    if status:



        executions = [e for e in executions if e.status == status]







    # Sort by timestamp descending



    executions.sort(key=lambda e: e.timestamp, reverse=True)







    return [e.to_dict() for e in executions[:limit]]











@router.get("/versions/workflows/executions/{execution_id}", response_model=dict)



async def get_workflow_execution(execution_id: str) -> dict:



    """Get workflow execution details."""



    if execution_id not in _workflow_executions:



        raise HTTPException(status_code=404, detail="Execution not found")







    return _workflow_executions[execution_id].to_dict()











