@router.get("/versions/workflow-dashboard", response_model=dict)



async def get_workflow_dashboard() -> dict:



    """Get workflow automation dashboard."""



    # Count workflows



    total_workflows = len(_version_workflows)



    enabled_workflows = sum(1 for w in _version_workflows.values() if w.enabled)



    disabled_workflows = total_workflows - enabled_workflows







    # Count executions



    total_executions = len(_workflow_execution_history)



    success_executions = sum(1 for e in _workflow_execution_history if e.status == "success")



    failed_executions = sum(1 for e in _workflow_execution_history if e.status == "failed")



    skipped_executions = sum(1 for e in _workflow_execution_history if e.status == "skipped")







    # Events summary



    events_summary = {}



    for event in _version_events.values():



        event_type = event.event_type



        events_summary[event_type] = events_summary.get(event_type, 0) + 1







    # Triggers summary



    triggers_summary = {}



    for workflow in _version_workflows.values():



        trigger = workflow.trigger



        triggers_summary[trigger] = triggers_summary.get(trigger, 0) + 1







    return {



        "workflows": {



            "total": total_workflows,



            "enabled": enabled_workflows,



            "disabled": disabled_workflows,



        },



        "executions": {



            "total": total_executions,



            "success": success_executions,



            "failed": failed_executions,



            "skipped": skipped_executions,



            "success_rate": (success_executions / total_executions * 100) if total_executions > 0 else 0,



        },



        "events": {



            "total": len(_version_events),



            "by_type": events_summary,



        },



        "available_triggers": WORKFLOW_TRIGGERS,



        "available_actions": WORKFLOW_ACTIONS,



        "triggers_by_type": triggers_summary,



    }











