# Version AI Recommendations (v1.26.0)



# =============================================================================







from enum import Enum



from typing import Optional



from datetime import datetime, timedelta







class RecommendationType(str, Enum):



    CLEANUP = "cleanup"



    MERGE = "merge"



    BRANCH = "branch"



    ARCHIVE = "archive"



    RESTORE = "restore"



    COMPARE = "compare"



    OPTIMIZE = "optimize"



    RETENTION = "retention"



    BACKUP = "backup"







class RecommendationPriority(str, Enum):



    CRITICAL = "critical"



    HIGH = "high"



    MEDIUM = "medium"



    LOW = "low"







class VersionRecommendation(BaseModel):



    recommendation_id: str



    recommendation_type: RecommendationType



    priority: RecommendationPriority



    title: str



    description: str



    target_entity_id: Optional[str] = None



    target_version: Optional[str] = None



    suggested_action: str



    estimated_impact: str



    confidence: float



    created_at: str



    dismissed: bool = False







class RecommendationRequest(BaseModel):



    entity_id: Optional[str] = None



    recommendation_types: Optional[list[RecommendationType]] = None



    min_priority: Optional[RecommendationPriority] = None







class RecommendationResponse(BaseModel):



    recommendations: list[VersionRecommendation]



    total: int



    by_type: dict[str, int]



    by_priority: dict[str, int]







class ApplyRecommendationRequest(BaseModel):



    recommendation_id: str



    apply: bool = True







# In-memory storage for recommendations



_version_recommendations: dict[str, VersionRecommendation] = {}







def _generate_recommendation_id() -> str:



    return f"rec_{_now_iso()}_{len(_version_recommendations) + 1}"







async def _analyze_entity_recommendations(entity_id: str) -> list[VersionRecommendation]:



    """Analyze entity version data to generate recommendations."""



    recommendations = []



    versions = _entity_versions.get(entity_id, [])







    if not versions:



        return recommendations







    # Analyze version patterns



    version_count = len(versions)



    active_versions = [v for v in versions if v.get("status") == "active"]



    archived_versions = [v for v in versions if v.get("status") == "archived"]



    deleted_versions = [v for v in versions if v.get("status") == "deleted"]







    # Cleanup recommendations



    if version_count > 50:



        recommendations.append(VersionRecommendation(



            recommendation_id=_generate_recommendation_id(),



            recommendation_type=RecommendationType.CLEANUP,



            priority=RecommendationPriority.HIGH,



            title=f"Cleanup {version_count} versions for entity",



            description=f"Entity has {version_count} versions. Consider archiving or deleting old versions.",



            target_entity_id=entity_id,



            suggested_action=f"archive_old_versions",



            estimated_impact="Reduces storage by ~{:.0f}%".format(min(80, version_count * 1.5)),



            confidence=0.85,



            created_at=_now_iso(),



        ))







    # Merge recommendations for large version counts



    if version_count > 30:



        recommendations.append(VersionRecommendation(



            recommendation_id=_generate_recommendation_id(),



            recommendation_type=RecommendationType.MERGE,



            priority=RecommendationPriority.MEDIUM,



            title=f"Merge similar versions for entity",



            description=f"Entity has {version_count} versions with potential duplicates.",



            target_entity_id=entity_id,



            suggested_action="merge_similar_versions",



            estimated_impact="Reduce version count by {:.0f}%".format(min(50, version_count * 1.2)),



            confidence=0.70,



            created_at=_now_iso(),



        ))







    # Retention recommendations



    if version_count > 20:



        old_versions = [v for v in versions if v.get("created_at")]



        old_threshold = datetime.now() - timedelta(days=90)



        very_old = sum(1 for v in old_versions if v.get("created_at") and v["created_at"] < old_threshold.isoformat())



        if very_old > 5:



            recommendations.append(VersionRecommendation(



                recommendation_id=_generate_recommendation_id(),



                recommendation_type=RecommendationType.RETENTION,



                priority=RecommendationPriority.MEDIUM,



                title=f"Set retention policy for entity",



                description=f"Entity has {very_old} versions older than 90 days.",



                target_entity_id=entity_id,



                suggested_action="set_retention_policy",



                estimated_impact="Automate cleanup of old versions",



                confidence=0.80,



                created_at=_now_iso(),



            ))







    # Optimization recommendations for large data



    if versions:



        total_size = sum(v.get("size", 0) for v in versions)



        if total_size > 10 * 1024 * 1024:  # 10MB



            recommendations.append(VersionRecommendation(



                recommendation_id=_generate_recommendation_id(),



                recommendation_type=RecommendationType.OPTIMIZE,



                priority=RecommendationPriority.HIGH,



                title=f"Optimize storage for entity",



                description=f"Entity versions total ~{total_size / 1024 / 1024:.1f}MB.",



                target_entity_id=entity_id,



                suggested_action="compress_versions",



                estimated_impact="Reduce storage by ~40%",



                confidence=0.90,



                created_at=_now_iso(),



            ))







    return recommendations







async def _generate_global_recommendations() -> list[VersionRecommendation]:



    """Generate global recommendations across all entities."""



    recommendations = []







    # Total entities with versions



    total_entities = len(_entity_versions)



    total_versions = sum(len(v) for v in _entity_versions.values())







    # Global cleanup recommendation



    if total_versions > 500:



        entities_with_many = [(eid, len(vers)) for eid, vers in _entity_versions.items() if len(vers) > 20]



        if entities_with_many:



            top_entity = max(entities_with_many, key=lambda x: x[1])



            recommendations.append(VersionRecommendation(



                recommendation_id=_generate_recommendation_id(),



                recommendation_type=RecommendationType.CLEANUP,



                priority=RecommendationPriority.CRITICAL,



                title="Global cleanup required",



                description=f"System has {total_versions} versions across {total_entities} entities. {len(entities_with_many)} entities have >20 versions.",



                target_entity_id=top_entity[0],



                suggested_action="batch_cleanup",



                estimated_impact="Free up significant storage",



                confidence=0.85,



                created_at=_now_iso(),



            ))







    # Global archive recommendation



    old_entities = 0



    old_threshold = datetime.now() - timedelta(days=180)



    for entity_id, versions in _entity_versions.items():



        has_old = any(v.get("created_at") and v["created_at"] < old_threshold.isoformat() for v in versions)



        if has_old:



            old_entities += 1







    if old_entities > 10:



        recommendations.append(VersionRecommendation(



            recommendation_id=_generate_recommendation_id(),



            recommendation_type=RecommendationType.ARCHIVE,



            priority=RecommendationPriority.HIGH,



            title="Archive old entity versions",



            description=f"{old_entities} entities have versions older than 180 days.",



            suggested_action="archive_old_entities",



            estimated_impact="Improve system performance",



            confidence=0.75,



            created_at=_now_iso(),



        ))







    # Branch recommendation



    active_entities = sum(1 for vers in _entity_versions.values() if len(vers) > 10)



    if active_entities > 5:



        recommendations.append(VersionRecommendation(



            recommendation_id=_generate_recommendation_id(),



            recommendation_type=RecommendationType.BRANCH,



            priority=RecommendationPriority.MEDIUM,



            title="Use version branches for parallel development",



            description=f"{active_entities} entities have >10 versions. Consider using branches.",



            suggested_action="enable_branching",



            estimated_impact="Better version organization",



            confidence=0.70,



            created_at=_now_iso(),



        ))







    # Backup recommendation



    if total_versions > 100 and not _version_cross_refs:



        recommendations.append(VersionRecommendation(



            recommendation_id=_generate_recommendation_id(),



            recommendation_type=RecommendationType.BACKUP,



            priority=RecommendationPriority.CRITICAL,



            title="Set up version backup",



            description=f"System has {total_versions} versions but no backup references.",



            suggested_action="create_backup_policy",



            estimated_impact="Ensure data safety",



            confidence=0.95,



            created_at=_now_iso(),



        ))







    return recommendations







async def _generate_recommendations(entity_id: Optional[str] = None) -> list[VersionRecommendation]:



    """Generate all recommendations."""



    recommendations = []







    if entity_id:



        # Entity-specific recommendations



        recommendations.extend(await _analyze_entity_recommendations(entity_id))



    else:



        # Global recommendations



        recommendations.extend(await _generate_global_recommendations())







        # Also generate per-entity recommendations



        for eid in list(_entity_versions.keys())[:20]:  # Limit to 20 entities



            recommendations.extend(await _analyze_entity_recommendations(eid))







    # Store recommendations



    for rec in recommendations:



        _version_recommendations[rec.recommendation_id] = rec







    return recommendations











@router.post("/versions/recommendations", response_model=RecommendationResponse)



async def generate_recommendations(req: RecommendationRequest) -> RecommendationResponse:



    """Generate version recommendations using AI analysis."""



    entity_id = req.entity_id



    filter_types = req.recommendation_types



    min_priority = req.min_priority







    # Generate recommendations



    all_recommendations = await _generate_recommendations(entity_id)







    # Apply filters



    filtered = all_recommendations







    if filter_types:



        filtered = [r for r in filtered if r.recommendation_type in filter_types]







    if min_priority:



        priority_order = {



            RecommendationPriority.CRITICAL: 0,



            RecommendationPriority.HIGH: 1,



            RecommendationPriority.MEDIUM: 2,



            RecommendationPriority.LOW: 3,



        }



        min_priority_value = priority_order.get(min_priority, 3)



        filtered = [r for r in filtered if priority_order.get(r.priority, 3) <= min_priority_value]







    # Filter out dismissed



    filtered = [r for r in filtered if not r.dismissed]







    # Count by type and priority



    by_type: dict[str, int] = {}



    by_priority: dict[str, int] = {}



    for r in filtered:



        by_type[r.recommendation_type.value] = by_type.get(r.recommendation_type.value, 0) + 1



        by_priority[r.priority.value] = by_priority.get(r.priority.value, 0) + 1







    return RecommendationResponse(



        recommendations=filtered,



        total=len(filtered),



        by_type=by_type,



        by_priority=by_priority,



    )











@router.get("/versions/recommendations", response_model=RecommendationResponse)



async def get_recommendations(



    entity_id: Optional[str] = None,



    recommendation_type: Optional[RecommendationType] = None,



    priority: Optional[RecommendationPriority] = None,



) -> RecommendationResponse:



    """Get existing recommendations."""



