    if not _version_recommendations:



        await _generate_recommendations(entity_id)







    # Filter recommendations



    filtered = list(_version_recommendations.values())







    if entity_id:



        filtered = [r for r in filtered if r.target_entity_id == entity_id or r.target_entity_id is None]







    if recommendation_type:



        filtered = [r for r in filtered if r.recommendation_type == recommendation_type]







    if priority:



        filtered = [r for r in filtered if r.priority == priority]







    # Exclude dismissed



    filtered = [r for r in filtered if not r.dismissed]







    # Count by type and priority



    by_type: dict[str, int] = {}



    by_priority: dict[str, int] = {}



    for r in filtered:



        by_type[r.recommendation_type.value] = by_type.get(r.recommendation_type.value, 0) + 1



        by_priority[r.priority.value] = by_priority.get(r.priority.value, 0) + 1







    return RecommendationResponse(



        recommendations=filtered,



        total=len(filtered),



        by_type=by_type,



        by_priority=by_priority,



    )











