@router.post("/versions/recommendations/{recommendation_id}/apply", response_model=dict)



async def apply_recommendation(



    recommendation_id: str,



    req: ApplyRecommendationRequest,



) -> dict:



    """Apply a recommendation."""



    if recommendation_id not in _version_recommendations:



        raise HTTPException(status_code=404, detail="Recommendation not found")







    rec = _version_recommendations[recommendation_id]



    applied = req.apply







    if not applied:



        rec.dismissed = True



        return {"status": "dismissed", "recommendation_id": recommendation_id}







    action = rec.suggested_action



    entity_id = rec.target_entity_id







    results = {"status": "applied", "recommendation_id": recommendation_id, "action": action}







    # Execute suggested action



    if action == "archive_old_versions" and entity_id:



        versions = _entity_versions.get(entity_id, [])



        archived = 0



        for v in versions:



            old_threshold = datetime.now() - timedelta(days=90)



            if v.get("created_at") and v["created_at"] < old_threshold.isoformat():



                v["status"] = "archived"



                archived += 1



        results["archived_count"] = archived







    elif action == "merge_similar_versions" and entity_id:



        results["status"] = "pending_implementation"



        results["message"] = "Merge requires interactive user confirmation"







    elif action == "set_retention_policy":



        # Create a retention policy



        new_policy = VersionPolicy(



            policy_id=f"auto_retention_{_now_iso()}",



            name="Auto-generated retention policy",



            description="Automatically archive versions older than 90 days",



            target_entity_id=entity_id,



            max_age_days=90,



            action="archive",



            enabled=True,



            conditions=[],



        )



        _retention_policies[new_policy.policy_id] = {



            "policy_id": new_policy.policy_id,



            "name": new_policy.name,



            "description": new_policy.description,



            "target_entity_id": new_policy.target_entity_id,



            "max_age_days": new_policy.max_age_days,



            "action": new_policy.action,



            "enabled": new_policy.enabled,



            "conditions": new_policy.conditions,



        }



        results["created_policy"] = new_policy.policy_id







    elif action == "compress_versions":



        results["status"] = "pending_implementation"



        results["message"] = "Compression requires configuration"







    elif action == "batch_cleanup":



        cleaned = 0



        for eid, versions in _entity_versions.items():



            old_versions = [



                v for v in versions



                if v.get("created_at") and v["created_at"] < (datetime.now() - timedelta(days=180)).isoformat()



            ]



            for v in old_versions:



                v["status"] = "archived"



                cleaned += 1



        results["cleaned_count"] = cleaned







    elif action == "archive_old_entities":



        archived = 0



        old_threshold = datetime.now() - timedelta(days=180)



        for eid, versions in _entity_versions.items():



            for v in versions:



                if v.get("created_at") and v["created_at"] < old_threshold.isoformat():



                    v["status"] = "archived"



                    archived += 1



        results["archived_count"] = archived







    elif action == "enable_branching":



        results["status"] = "info"



        results["message"] = "Use /entities/{id}/versions/branches to create branches"







    elif action == "create_backup_policy":



        # Create a cross-reference as backup



        new_ref = VersionCrossReference(



            reference_id=f"backup_ref_{_now_iso()}",



            source_version_id="global",



            target_version_id="backup",



            reference_type="backup",



            description="Auto-generated backup reference",



            metadata={"auto_created": True, "backup_type": "full"},



        )



        _version_cross_refs[new_ref.reference_id] = new_ref



        results["created_reference"] = new_ref.reference_id







    else:



        results["status"] = "unknown_action"



        results["message"] = f"Action '{action}' not recognized"







    # Mark as dismissed after applying



    rec.dismissed = True







    return results











