@router.get("/versions/recommendations/dashboard", response_model=dict)



async def get_recommendations_dashboard() -> dict:



    """Get recommendations dashboard."""



    # Generate fresh recommendations



    all_recs = await _generate_recommendations()



    active = [r for r in all_recs if not r.dismissed]







    by_type: dict[str, list[dict]] = {}



    by_priority: dict[str, list[dict]] = {}







    for r in active:



        type_key = r.recommendation_type.value



        priority_key = r.priority.value







        if type_key not in by_type:



            by_type[type_key] = []



        by_type[type_key].append({



            "id": r.recommendation_id,



            "title": r.title,



            "entity": r.target_entity_id,



        })







        if priority_key not in by_priority:



            by_priority[priority_key] = []



        by_priority[priority_key].append({



            "id": r.recommendation_id,



            "title": r.title,



            "type": r.recommendation_type.value,



        })







    # Count actionable



    actionable = sum(1 for r in active if r.suggested_action in [



        "archive_old_versions", "batch_cleanup", "archive_old_entities", "create_backup_policy", "set_retention_policy"



    ])







    return {



        "total_recommendations": len(active),



        "actionable": actionable,



        "by_type": {k: len(v) for k, v in by_type.items()},



        "by_priority": {k: len(v) for k, v in by_priority.items()},



        "priority_breakdown": {



            RecommendationPriority.CRITICAL.value: len([r for r in active if r.priority == RecommendationPriority.CRITICAL]),



            RecommendationPriority.HIGH.value: len([r for r in active if r.priority == RecommendationPriority.HIGH]),



            RecommendationPriority.MEDIUM.value: len([r for r in active if r.priority == RecommendationPriority.MEDIUM]),



            RecommendationPriority.LOW.value: len([r for r in active if r.priority == RecommendationPriority.LOW]),



        },



    }











# =============================================================================



# Version Validation Rules (v1.27.0)



# =============================================================================







class ValidationRuleType(str, Enum):



    MIN_VERSIONS = "min_versions"



    MAX_VERSIONS = "max_versions"



    MAX_AGE = "max_age"



    MIN_SIZE = "min_size"



    MAX_SIZE = "max_size"



    REQUIRED_FIELD = "required_field"



    DUPLICATE_CHECK = "duplicate_check"



    ORPHANED_CHECK = "orphaned_check"



    SIZE_THRESHOLD = "size_threshold"







class ValidationSeverity(str, Enum):



    CRITICAL = "critical"



    HIGH = "high"



    MEDIUM = "medium"



    LOW = "low"



    INFO = "info"







class VersionValidationRule(BaseModel):



    rule_id: str



    name: str



    description: str



    rule_type: ValidationRuleType



    severity: ValidationSeverity



    enabled: bool = True



    params: dict[str, Any] = {}







class VersionValidationIssue(BaseModel):



    issue_id: str



    rule_id: str



    rule_name: str



    severity: ValidationSeverity



    entity_id: Optional[str] = None



    version: Optional[str] = None



    message: str



    details: dict[str, Any] = {}







class VersionValidationReport(BaseModel):



    report_id: str



    timestamp: str



    total_issues: int



    by_severity: dict[str, int]



    by_rule: dict[str, int]



    issues: list[VersionValidationIssue]







class VersionValidationPolicy(BaseModel):



    policy_id: str



    name: str



    description: str



    rule_ids: list[str]



    enabled: bool = True



    schedule: Optional[str] = None







class VersionValidationRequest(BaseModel):



    entity_id: Optional[str] = None



    rule_ids: Optional[list[str]] = None



    severity_filter: Optional[ValidationSeverity] = None







# In-memory storage



_version_validation_rules: dict[str, VersionValidationRule] = {}



_version_validation_issues: dict[str, list[VersionValidationIssue]] = {}



_version_validation_policies: dict[str, VersionValidationPolicy] = {}







def _generate_validation_id() -> str:



    return f"valid_{_now_iso()}_{len(_version_validation_rules) + 1}"







# Initialize default validation rules



def _init_default_validation_rules():



    """Initialize default version validation rules."""



    rules = [



        VersionValidationRule(



            rule_id="vrule_max_versions",



            name="Maximum versions limit",



            description="Check if entity has too many versions",



            rule_type=ValidationRuleType.MAX_VERSIONS,



            severity=ValidationSeverity.HIGH,



            params={"max_count": 100},



        ),



        VersionValidationRule(



            rule_id="vrule_old_versions",



            name="Old version cleanup",



            description="Identify versions older than 180 days",



            rule_type=ValidationRuleType.MAX_AGE,



            severity=ValidationSeverity.MEDIUM,



            params={"max_age_days": 180},



        ),



        VersionValidationRule(



            rule_id="vrule_size_check",



            name="Version size check",



            description="Check for excessively large versions",



            rule_type=ValidationRuleType.MAX_SIZE,



            severity=ValidationSeverity.HIGH,



            params={"max_size_mb": 50},



        ),



        VersionValidationRule(



            rule_id="vrule_min_versions",



            name="Minimum versions check",



            description="Check if entity should have more versions",



            rule_type=ValidationRuleType.MIN_VERSIONS,



            severity=ValidationSeverity.INFO,



            params={"min_count": 1},



        ),



        VersionValidationRule(



            rule_id="vrule_required_fields",



            name="Required fields validation",



            description="Check required fields are present",



            rule_type=ValidationRuleType.REQUIRED_FIELD,



            severity=ValidationSeverity.HIGH,



            params={"required_fields": ["name", "version"]},



        ),



        VersionValidationRule(



            rule_id="vrule_duplicate",



            name="Duplicate version check",



            description="Check for duplicate versions",



            rule_type=ValidationRuleType.DUPLICATE_CHECK,



            severity=ValidationSeverity.MEDIUM,



            params={},



        ),



        VersionValidationRule(



            rule_id="vrule_orphaned",



            name="Orphaned version check",



            description="Check for orphaned versions without entity",



            rule_type=ValidationRuleType.ORPHANED_CHECK,



            severity=ValidationSeverity.HIGH,



            params={},



        ),



    ]



    for rule in rules:



        _version_validation_rules[rule.rule_id] = rule







# Initialize on module load



_init_default_validation_rules()







async def _validate_version(rule: VersionValidationRule, entity_id: str, version_data: dict) -> list[VersionValidationIssue]:



    """Run a single validation rule against a version."""



    issues = []



    rule_type = rule.rule_type







    if rule_type == ValidationRuleType.MAX_VERSIONS:



        max_count = rule.params.get("max_count", 100)



        versions = _entity_versions.get(entity_id, [])



        if len(versions) > max_count:



            issues.append(VersionValidationIssue(



                issue_id=_generate_validation_id(),



                rule_id=rule.rule_id,



                rule_name=rule.name,



                severity=rule.severity,



                entity_id=entity_id,



                version=version_data.get("version"),



                message=f"Entity has {len(versions)} versions, exceeds max of {max_count}",



                details={"version_count": len(versions), "max_allowed": max_count},



            ))







    elif rule_type == ValidationRuleType.MAX_AGE:



        max_age_days = rule.params.get("max_age_days", 180)



        created_at = version_data.get("created_at")



        if created_at:



            try:



                version_time = datetime.fromisoformat(created_at.replace("Z", "+00:00"))



                age_days = (datetime.now() - version_time.replace(tzinfo=None)).days



                if age_days > max_age_days:



                    issues.append(VersionValidationIssue(



                        issue_id=_generate_validation_id(),



                        rule_id=rule.rule_id,



                        rule_name=rule.name,



                        severity=rule.severity,



                        entity_id=entity_id,



                        version=version_data.get("version"),



                        message=f"Version is {age_days} days old, exceeds max of {max_age_days}",



                        details={"age_days": age_days, "max_allowed": max_age_days},



                    ))



            except Exception:



                pass







    elif rule_type == ValidationRuleType.MAX_SIZE:



        max_size_mb = rule.params.get("max_size_mb", 50)



        size = version_data.get("size", 0)



        size_mb = size / (1024 * 1024) if size else 0



        if size_mb > max_size_mb:



            issues.append(VersionValidationIssue(



                issue_id=_generate_validation_id(),



                rule_id=rule.rule_id,



                rule_name=rule.name,



                severity=rule.severity,



                entity_id=entity_id,



                version=version_data.get("version"),



                message=f"Version size {size_mb:.1f}MB exceeds max {max_size_mb}MB",



                details={"size_mb": size_mb, "max_allowed": max_size_mb},



            ))







    elif rule_type == ValidationRuleType.REQUIRED_FIELD:



        required_fields = rule.params.get("required_fields", [])



        for field in required_fields:



            if field not in version_data or version_data.get(field) is None:



                issues.append(VersionValidationIssue(



                    issue_id=_generate_validation_id(),



                    rule_id=rule.rule_id,



                    rule_name=rule.name,



                    severity=rule.severity,



                    entity_id=entity_id,



                    version=version_data.get("version"),



                    message=f"Required field '{field}' is missing",



                    details={"missing_field": field},



                ))







    elif rule_type == ValidationRuleType.DUPLICATE_CHECK:



        versions = _entity_versions.get(entity_id, [])



        version_nums = [v.get("version") for v in versions]



        if len(version_nums) != len(set(version_nums)):



            duplicates = [v for v in set(version_nums) if version_nums.count(v) > 1]



            if duplicates:



                issues.append(VersionValidationIssue(



                    issue_id=_generate_validation_id(),



                    rule_id=rule.rule_id,



                    rule_name=rule.name,



                    severity=rule.severity,



                    entity_id=entity_id,



                    version=version_data.get("version"),



                    message=f"Duplicate version numbers: {duplicates}",



                    details={"duplicates": duplicates},



                ))







    return issues







async def _validate_version_entity(entity_id: str, rule_ids: Optional[list[str]] = None) -> list[VersionValidationIssue]:



    """Validate all versions for an entity."""



    all_issues = []



    versions = _entity_versions.get(entity_id, [])







    # Get rules to apply



    rules = list(_version_validation_rules.values())



    if rule_ids:



        rules = [r for r in rules if r.rule_id in rule_ids]







    # Apply rules to each version



    for version_data in versions:



        for rule in rules:



            if rule.enabled:



                issues = await _validate_version(rule, entity_id, version_data)



                all_issues.extend(issues)







    return all_issues











