@router.post("/versions/validation/rules/{rule_id}/toggle", response_model=VersionValidationRule)



async def toggle_validation_rule(rule_id: str) -> VersionValidationRule:



    """Toggle a validation rule enabled/disabled."""



    if rule_id not in _version_validation_rules:



        raise HTTPException(status_code=404, detail="Rule not found")



    rule = _version_validation_rules[rule_id]



    rule.enabled = not rule.enabled



    return rule











@router.post("/versions/validate", response_model=VersionValidationReport)



async def validate_versions(req: VersionValidationRequest) -> VersionValidationReport:



    """Run version validation."""



    entity_id = req.entity_id



    rule_ids = req.rule_ids



    severity_filter = req.severity_filter







    all_issues = []







    # Validate specific entity or all entities



    if entity_id:



        issues = await _validate_version_entity(entity_id, rule_ids)



        all_issues.extend(issues)



    else:



        for eid in list(_entity_versions.keys()):



            issues = await _validate_version_entity(eid, rule_ids)



            all_issues.extend(issues)







    # Apply severity filter



    if severity_filter:



        severity_order = {



            ValidationSeverity.CRITICAL: 0,



            ValidationSeverity.HIGH: 1,



            ValidationSeverity.MEDIUM: 2,



            ValidationSeverity.LOW: 3,



            ValidationSeverity.INFO: 4,



        }



        min_severity = severity_order.get(severity_filter, 4)



        all_issues = [i for i in all_issues if severity_order.get(i.severity, 4) <= min_severity]







    # Calculate statistics



    by_severity: dict[str, int] = {}



    by_rule: dict[str, int] = {}



    for issue in all_issues:



        by_severity[issue.severity.value] = by_severity.get(issue.severity.value, 0) + 1



        by_rule[issue.rule_id] = by_rule.get(issue.rule_id, 0) + 1







    report = VersionValidationReport(



        report_id=f"vreport_{_now_iso()}",



        timestamp=_now_iso(),



        total_issues=len(all_issues),



        by_severity=by_severity,



        by_rule=by_rule,



        issues=all_issues,



    )







    # Store issues



    _version_validation_issues[report.report_id] = all_issues







    return report











@router.get("/versions/validation/reports", response_model=list[dict])



async def get_validation_reports(limit: int = 10) -> list[dict]:



    """Get validation report history."""



    reports = []



    for report_id, issues in _version_validation_issues.items():



        by_severity: dict[str, int] = {}



        for issue in issues:



            by_severity[issue.severity.value] = by_severity.get(issue.severity.value, 0) + 1







        reports.append({



            "report_id": report_id,



            "total_issues": len(issues),



            "by_severity": by_severity,



        })







    reports.sort(key=lambda x: x["report_id"], reverse=True)



    return reports[:limit]











@router.get("/versions/validation/summary", response_model=dict)



async def get_validation_summary() -> dict:



    """Get validation summary."""



    rules_enabled = sum(1 for r in _version_validation_rules.values() if r.enabled)



    rules_disabled = len(_version_validation_rules) - rules_enabled







    by_type: dict[str, int] = {}



    for rule in _version_validation_rules.values():



        by_type[rule.rule_type.value] = by_type.get(rule.rule_type.value, 0) + 1







    return {



        "total_rules": len(_version_validation_rules),



        "enabled": rules_enabled,



        "disabled": rules_disabled,



        "by_type": by_type,



        "available_rule_types": [t.value for t in ValidationRuleType],



    }











