@router.post("/versions/validation/policies/{policy_id}/validate", response_model=VersionValidationReport)



async def validate_with_policy(policy_id: str, entity_id: Optional[str] = None) -> VersionValidationReport:



    """Validate using a specific policy."""



    if policy_id not in _version_validation_policies:



        raise HTTPException(status_code=404, detail="Policy not found")







