class ComparisonTemplateField(BaseModel):



    """A field to compare in version comparison."""



    field_path: str  # e.g., "data.name", "metadata.tags", "relations count"



    display_name: str



    comparison_type: str = "exact"  # exact, fuzzy, numeric, percentage, ignored



    ignore_patterns: list[str] = []



    weight: float = 1.0











class ComparisonThreshold(BaseModel):



    """Threshold configuration for comparison."""



    field_path: str



    match_threshold: float = 100.0  # percentage



    warn_threshold: float = 80.0











class VersionComparisonTemplate(BaseModel):



    """A reusable version comparison template."""



    template_id: str



    name: str



    description: str = ""



    fields: list[ComparisonTemplateField]



    thresholds: list[ComparisonThreshold] = []



    ignore_field_patterns: list[str] = []



    include_relations: bool = True



    include_metadata: bool = True



    include_tags: bool = True



    created_at: str



    updated_at: str



    enabled: bool = True











class VersionComparisonTemplateCreateRequest(BaseModel):



    """Request to create a comparison template."""



    name: str



    description: str = ""



    fields: list[ComparisonTemplateField]



    thresholds: list[ComparisonThreshold] = []



    ignore_field_patterns: list[str] = []



    include_relations: bool = True



    include_metadata: bool = True



    include_tags: bool = True











class VersionComparisonTemplateUpdateRequest(BaseModel):



    """Request to update a comparison template."""



    name: Optional[str] = None



    description: Optional[str] = None



    fields: Optional[list[ComparisonTemplateField]] = None



    thresholds: Optional[list[ComparisonThreshold]] = None



    ignore_field_patterns: Optional[list[str]] = None



    include_relations: Optional[bool] = None



    include_metadata: Optional[bool] = None



    include_tags: Optional[bool] = None



    enabled: Optional[bool] = None











class VersionComparisonResult(BaseModel):



    """Result of applying a comparison template."""



    template_id: str



    version_a: str



    version_b: str



    overall_score: float  # 0-100 percentage match



    field_results: list[dict]



    matching_fields: list[str]



    differing_fields: list[str]



    ignored_fields: list[str]



    threshold_warnings: list[dict]











class VersionComparisonTemplateListResponse(BaseModel):



    """List of comparison templates."""



    templates: list[VersionComparisonTemplate]



    total: int











# In-memory storage for comparison templates



_version_comparison_templates: dict[str, VersionComparisonTemplate] = {}











def _generate_template_id() -> str:



    """Generate a unique template ID."""



    import time



    return f"tmpl_{int(time.time() * 1000)}"











def _now_iso() -> str:



    """Get current ISO timestamp."""



    return datetime.now().isoformat()











def _apply_field_comparison(field_config: ComparisonTemplateField, value_a: any, value_b: any) -> dict:



    """Apply field-level comparison."""



    field_path = field_config.field_path



    comp_type = field_config.comparison_type







    if comp_type == "ignored":



        return {



            "field_path": field_path,



            "status": "ignored",



            "score": 0,



        }







    # Convert to strings for comparison



    str_a = str(value_a) if value_a is not None else ""



    str_b = str(value_b) if value_b is not None else ""







    # Check ignore patterns



    for pattern in field_config.ignore_patterns:



        if pattern in str_a or pattern in str_b:



            return {



                "field_path": field_path,



                "status": "ignored",



                "score": 0,



            }







    if comp_type == "exact":



        match = (str_a == str_b)



        score = 100.0 if match else 0.0



    elif comp_type == "numeric":



        try:



            num_a = float(str_a) if str_a else 0



            num_b = float(str_b) if str_b else 0



            if num_a == 0 and num_b == 0:



                score = 100.0



            else:



                max_val = max(abs(num_a), abs(num_b))



                if max_val > 0:



                    score = (1 - abs(num_a - num_b) / max_val) * 100



                else:



                    score = 100.0



        except:



            score = 100.0 if str_a == str_b else 0.0



    elif comp_type == "percentage":



        try:



            pct_a = float(str_a.replace("%", "")) if str_a else 0



            pct_b = float(str_b.replace("%", "")) if str_b else 0



            if pct_a == 0 and pct_b == 0:



                score = 100.0



            else:



                max_val = max(abs(pct_a), abs(pct_b))



                if max_val > 0:



                    score = (1 - abs(pct_a - pct_b) / max_val) * 100



                else:



                    score = 100.0



        except:



            score = 100.0 if str_a == str_b else 0.0



    elif comp_type == "fuzzy":



        # Simple fuzzy matching - check substring



        match = (str_a in str_b) or (str_b in str_a)



        score = 100.0 if match else 50.0



    else:



        score = 100.0 if str_a == str_b else 0.0







    return {



        "field_path": field_path,



        "display_name": field_config.display_name,



        "value_a": value_a,



        "value_b": value_b,



        "status": "matching" if score >= 100 else "different" if score > 0 else "mismatch",



        "score": score,



        "comparison_type": comp_type,



    }











@router.post("/versions/comparison/templates", response_model=VersionComparisonTemplate)



async def create_comparison_template(req: VersionComparisonTemplateCreateRequest) -> VersionComparisonTemplate:



    """Create a new version comparison template."""



    template_id = _generate_template_id()



    now = _now_iso()







    template = VersionComparisonTemplate(



        template_id=template_id,



        name=req.name,



        description=req.description,



        fields=req.fields,



        thresholds=req.thresholds,



        ignore_field_patterns=req.ignore_field_patterns,



        include_relations=req.include_relations,



        include_metadata=req.include_metadata,



        include_tags=req.include_tags,



        created_at=now,



        updated_at=now,



        enabled=True,



    )







    _version_comparison_templates[template_id] = template



    return template











