class AuditActionType(str, Enum):



    """Types of audit actions."""



    VERSION_CREATE = "version_create"



    VERSION_UPDATE = "version_update"



    VERSION_DELETE = "version_delete"



    VERSION_ROLLBACK = "version_rollback"



    VERSION_RESTORE = "version_restore"



    VERSION_EXPORT = "version_export"



    VERSION_IMPORT = "version_import"



    VERSION_TAG = "version_tag"



    VERSION_COMPARE = "version_compare"



    VERSION_MERGE = "version_merge"



    BRANCH_CREATE = "branch_create"



    BRANCH_DELETE = "branch_delete"



    SNAPSHOT_CREATE = "snapshot_create"



    SNAPSHOT_RESTORE = "snapshot_restore"



    TEMPLATE_APPLY = "template_apply"



    CONFIG_CHANGE = "config_change"











class AuditSeverity(str, Enum):



    """Audit severity levels."""



    INFO = "info"



    WARNING = "warning"



    ERROR = "error"



    CRITICAL = "critical"











class AuditEntry(BaseModel):



    """A single audit log entry."""



    entry_id: str = Field(description="Unique audit entry ID")



    timestamp: str = Field(description="ISO timestamp of the action")



    action: AuditActionType = Field(description="Type of action performed")



    severity: AuditSeverity = Field(default=AuditSeverity.INFO, description="Severity level")



    user_id: Optional[str] = Field(default=None, description="User who performed the action")



    entity_type: str = Field(description="Type of entity affected (e.g., 'version', 'branch')")



    entity_id: str = Field(description="ID of the entity affected")



    version_id: Optional[str] = Field(default=None, description="Version ID if applicable")



    branch_name: Optional[str] = Field(default=None, description="Branch name if applicable")



    description: str = Field(description="Human-readable description of the action")



    details: Dict[str, Any] = Field(default_factory=dict, description="Additional action details")



    ip_address: Optional[str] = Field(default=None, description="IP address of the request")



    user_agent: Optional[str] = Field(default=None, description="User agent string")



    duration_ms: Optional[int] = Field(default=None, description="Action duration in milliseconds")



    status: str = Field(default="success", description="Action status (success/error)")



    error_message: Optional[str] = Field(default=None, description="Error message if failed")











class AuditEntryCreateRequest(BaseModel):



    """Request to create an audit entry."""



    action: AuditActionType



    severity: AuditSeverity = AuditSeverity.INFO



    user_id: Optional[str] = None



    entity_type: str



    entity_id: str



    version_id: Optional[str] = None



    branch_name: Optional[str] = None



    description: str



    details: Dict[str, Any] = Field(default_factory=dict)



    ip_address: Optional[str] = None



    user_agent: Optional[str] = None



    duration_ms: Optional[int] = None



    status: str = "success"



    error_message: Optional[str] = None











class AuditEntryResponse(BaseModel):



    """Response for a single audit entry."""



    entry: AuditEntry











class AuditEntryListResponse(BaseModel):



    """List of audit entries."""



    entries: list[AuditEntry]



    total: int



    page: int



    page_size: int











class AuditSummary(BaseModel):



    """Summary statistics for audit logs."""



    total_entries: int



    entries_by_action: Dict[str, int]



    entries_by_severity: Dict[str, int]



    entries_by_entity_type: Dict[str, int]



    entries_by_status: Dict[str, int]



