@router.get("/versions/audit/summary", response_model=AuditSummary)



async def get_audit_summary() -> AuditSummary:



    """Get summary statistics for audit logs."""



    entries = list(_audit_entries.values())







    if not entries:



        return AuditSummary(



            total_entries=0,



            entries_by_action={},



            entries_by_severity={},



            entries_by_entity_type={},



            entries_by_status={},



            recent_actions=[],



            error_rate=0.0,



        )







    # Calculate statistics



    entries_by_action: Dict[str, int] = {}



    entries_by_severity: Dict[str, int] = {}



    entries_by_entity_type: Dict[str, int] = {}



    entries_by_status: Dict[str, int] = {}



    error_count = 0







    for entry in entries:



        # By action



        action_key = entry.action.value



        entries_by_action[action_key] = entries_by_action.get(action_key, 0) + 1







        # By severity



        severity_key = entry.severity.value



        entries_by_severity[severity_key] = entries_by_severity.get(severity_key, 0) + 1







        # By entity type



        entries_by_entity_type[entry.entity_type] = entries_by_entity_type.get(entry.entity_type, 0) + 1







        # By status



        entries_by_status[entry.status] = entries_by_status.get(entry.status, 0) + 1







        if entry.status == "error":



            error_count += 1







    # Recent actions (last 10)



    recent = sorted(entries, key=lambda x: x.timestamp, reverse=True)[:10]



    recent_actions = [



        {



            "entry_id": e.entry_id,



            "timestamp": e.timestamp,



            "action": e.action.value,



            "entity_type": e.entity_type,



            "entity_id": e.entity_id,



            "status": e.status,



        }



        for e in recent



    ]







    # Error rate



    error_rate = error_count / len(entries) if entries else 0.0







    return AuditSummary(



        total_entries=len(entries),



        entries_by_action=entries_by_action,



        entries_by_severity=entries_by_severity,



        entries_by_entity_type=entries_by_entity_type,



        entries_by_status=entries_by_status,



        recent_actions=recent_actions,



        error_rate=round(error_rate * 100, 2),



    )











@router.delete("/versions/audit/{entry_id}", response_model=dict)



async def delete_audit_entry(entry_id: str) -> dict:



    """Delete a specific audit entry."""



    if entry_id not in _audit_entries:



        raise HTTPException(status_code=404, detail="Audit entry not found")



    del _audit_entries[entry_id]



    return {"message": "Audit entry deleted", "entry_id": entry_id}











@router.delete("/versions/audit", response_model=dict)



async def clear_audit_logs(start_date: Optional[str] = None, end_date: Optional[str] = None) -> dict:



    """Clear audit logs, optionally within a date range."""



    global _audit_entries







    if not start_date and not end_date:



        # Clear all



        count = len(_audit_entries)



        _audit_entries = {}



        return {"message": f"Cleared {count} audit entries", "cleared": count}







    # Clear within date range



    to_delete = []



    for entry_id, entry in _audit_entries.items():



        if start_date and entry.timestamp < start_date:



            to_delete.append(entry_id)



        elif end_date and entry.timestamp > end_date:



            to_delete.append(entry_id)







    for entry_id in to_delete:



        del _audit_entries[entry_id]







    return {"message": f"Cleared {len(to_delete)} audit entries", "cleared": len(to_delete)}











