class VersionDiffVisualRequest(BaseModel):



    """Request for version diff visualization."""



    version_a: str = Field(description="First version to compare")



    version_b: str = Field(description="Second version to compare")



    view_mode: str = Field(default="unified", description="View mode: unified, side-by-side, inline")



    context_lines: int = Field(default=3, ge=0, le=10, description="Context lines around changes")



    ignore_whitespace: bool = Field(default=False, description="Ignore whitespace in diff")











class DiffLine(BaseModel):



    """Single line in a diff."""



    line_number_a: int | None = None



    line_number_b: int | None = None



    content: str



    change_type: str  # "add", "remove", "context"











class DiffHunk(BaseModel):



    """A hunk (section) in a diff."""



    old_start: int



    old_count: int



    new_start: int



    new_count: int



    lines: list[DiffLine]











class DiffFile(BaseModel):



    """Diff for a single file/entity."""



    entity_id: str



    hunks: list[DiffHunk]



    additions: int



    deletions: int



    unchanged: int











class VersionDiffVisualStats(BaseModel):



    """Statistics for version diff."""



    total_additions: int



    total_deletions: int



    total_unchanged: int



    files_changed: int



    change_percentage: float



    added_entities: list[str]



    removed_entities: list[str]



    modified_entities: list[str]











class VersionDiffVisualResponse(BaseModel):



    """Response for version diff visualization."""



    version_a: str



    version_b: str



    view_mode: str



    files: list[DiffFile]



    stats: VersionDiffVisualStats



    raw_unified_diff: str



    raw_side_by_side: str











class VersionDiffExportRequest(BaseModel):



    """Request to export version diff."""



    version_a: str



    version_b: str



    format: str = Field(default="json", description="Export format: json, html, markdown, text")











class VersionDiffExportResponse(BaseModel):



    """Response for exported diff."""



    exported_diff: str



    format: str



    filename: str











# Helper functions for diff visualization



def _compute_visual_diff(data_a: dict, data_b: dict, context_lines: int = 3, ignore_whitespace: bool = False) -> tuple[list[DiffHunk], dict]:



    """Compute visual diff between two data dictionaries."""



    hunks = []



    stats = {"additions": 0, "deletions": 0, "unchanged": 0, "added": [], "removed": [], "modified": []}







    # Get all keys from both data



    keys_a = set(data_a.keys())



    keys_b = set(data_b.keys())







    # Find added, removed, and common keys



    added_keys = keys_b - keys_a



    removed_keys = keys_a - keys_b



    common_keys = keys_a & keys_b







    stats["additions"] = len(added_keys)



    stats["deletions"] = len(removed_keys)







    # Build added entities list



    for key in added_keys:



        stats["added"].append(key)







    # Build removed entities list



    for key in removed_keys:



        stats["removed"].append(key)







    # Process modified keys



    modified_keys = []



    for key in common_keys:



        val_a = str(data_a.get(key, ""))



        val_b = str(data_b.get(key, ""))







        if ignore_whitespace:



            val_a = val_a.strip()



            val_b = val_b.strip()







        if val_a != val_b:



            modified_keys.append(key)



            stats["modified"].append(key)







    # Build hunks for modified keys



    if modified_keys:



        lines = []



        old_line_num = 1



        new_line_num = 1







        # Add context before



        for i in range(min(context_lines, len(modified_keys))):



            key = modified_keys[i]



            lines.append(DiffLine(



                line_number_a=old_line_num,



                line_number_b=new_line_num,



                content=f"{key}: {data_a.get(key, '')}",



                change_type="context"



            ))



            old_line_num += 1



            new_line_num += 1



            stats["unchanged"] += 1







        # Add changed lines



        for key in modified_keys:



            old_val = data_a.get(key, "")



            new_val = data_b.get(key, "")







            lines.append(DiffLine(



                line_number_a=old_line_num,



                line_number_b=None,



                content=f"- {key}: {old_val}",



                change_type="remove"



            ))



            old_line_num += 1



            stats["deletions"] += 1







            lines.append(DiffLine(



                line_number_a=None,



                line_number_b=new_line_num,



                content=f"+ {key}: {new_val}",



                change_type="add"



            ))



            new_line_num += 1



            stats["additions"] += 1







        # Add context after



        remaining = modified_keys[context_lines:] if context_lines < len(modified_keys) else []



        for i in range(min(context_lines, len(remaining))):



            key = remaining[i]



            lines.append(DiffLine(



                line_number_a=old_line_num,



                line_number_b=new_line_num,



                content=f" {key}: {data_a.get(key, '')}",



                change_type="context"



            ))



            old_line_num += 1



            new_line_num += 1



            stats["unchanged"] += 1







        if lines:



            hunks.append(DiffHunk(



                old_start=1,



                old_count=old_line_num - 1,



                new_start=1,



                new_count=new_line_num - 1,



                lines=lines



            ))







    return hunks, stats











def _generate_unified_diff(version_a: str, version_b: str, diff_files: list[DiffFile]) -> str:



    """Generate unified diff format string."""



    lines = []



    lines.append(f"--- {version_a}")



    lines.append(f"+++ {version_b}")







    for diff_file in diff_files:



        lines.append(f"@@ @@ {diff_file.entity_id}")



        for hunk in diff_file.hunks:



            for line in hunk.lines:



                prefix = "+" if line.change_type == "add" else "-" if line.change_type == "remove" else " "



                content = line.content



                lines.append(f"{prefix} {content}")







    return "\n".join(lines)











def _generate_side_by_side(version_a: str, version_b: str, diff_files: list[DiffFile]) -> str:



    """Generate side-by-side diff format string."""



    lines = []



    header = f"{version_a:<20} | {version_b}"



    lines.append(header)



    lines.append("=" * 60)







    for diff_file in diff_files:



        lines.append(f"[{diff_file.entity_id}]")



        for hunk in diff_file.hunks:



            for line in hunk.lines:



                old_val = line.content if line.change_type == "remove" else ""



                new_val = line.content if line.change_type == "add" else line.content if line.change_type == "context" else ""



                prefix = "(-) " if line.change_type == "remove" else "(+) " if line.change_type == "add" else "    "



                lines.append(f"{prefix}{old_val:<30} | {new_val}")







    return "\n".join(lines)











def _generate_html_diff(version_a: str, version_b: str, diff_files: list[DiffFile], stats: VersionDiffVisualStats) -> str:



    """Generate HTML diff representation."""



    html = []



    html.append(f"""<!DOCTYPE html>



<html>



<head>



    <title>Version Diff: {version_a} vs {version_b}</title>



    <style>



        body {{ font-family: monospace; margin: 20px; }}



        .diff-container {{ border: 1px solid #ccc; }}



        .diff-header {{ background: #f0f0f0; padding: 10px; font-weight: bold; }}



        .diff-stats {{ padding: 10px; background: #f9f9f9; }}



        .add {{ background: #e6ffed; color: #22863a; }}



        .remove {{ background: #ffeef0; color: #cb2431; }}



        .context {{ background: #fff; }}



        .line {{ padding: 2px 5px; white-space: pre; }}



        table {{ border-collapse: collapse; width: 100%; }}



        td {{ border: 1px solid #ddd; padding: 2px; }}



    </style>



</head>



<body>



    <h2>Version Diff: {version_a} → {version_b}</h2>



    <div class="diff-stats">



        <strong>Statistics:</strong><br>



        Files changed: {stats.files_changed}<br>



        Additions: +{stats.total_additions}<br>



        Deletions: -{stats.total_deletions}<br>



        Unchanged: {stats.total_unchanged}<br>



        Change: {stats.change_percentage:.1f}%



    </div>



    <div class="diff-container">""")







    for diff_file in diff_files:



        html.append(f"<h3>{diff_file.entity_id}</h3>")



        html.append("<table>")



        for hunk in diff_file.hunks:



            for line in hunk.lines:



                css_class = line.change_type



                content = line.content.replace("<", "&lt;").replace(">", "&gt;")



                html.append(f'<tr><td class="{css_class} line">{content}</td></tr>')



        html.append("</table>")







    html.append("</div></body></html>")



    return "\n".join(html)











def _generate_markdown_diff(version_a: str, version_b: str, diff_files: list[DiffFile], stats: VersionDiffVisualStats) -> str:



    """Generate Markdown diff representation."""



    md = []



    md.append(f"# Version Diff: {version_a} → {version_b}")



    md.append("")



    md.append("## Statistics")



    md.append("")



    md.append(f"- **Files changed**: {stats.files_changed}")



    md.append(f"- **Additions**: +{stats.total_additions}")



    md.append(f"- **Deletions**: -{stats.total_deletions}")



    md.append(f"- **Unchanged**: {stats.total_unchanged}")



    md.append(f"- **Change**: {stats.change_percentage:.1f}%")



    md.append("")



    md.append("## Diff Details")



    md.append("")







    for diff_file in diff_files:



        md.append(f"### {diff_file.entity_id}")



        md.append("")



        for hunk in diff_file.hunks:



            for line in hunk.lines:



                prefix = "+" if line.change_type == "add" else "-" if line.change_type == "remove" else " "



                md.append(f"{prefix} {line.content}")



        md.append("")







    return "\n".join(md)











# API Endpoints for Version Diff Visualization



@router.post("/versions/diff/visual", response_model=VersionDiffVisualResponse)



async def get_version_diff_visual(req: VersionDiffVisualRequest) -> VersionDiffVisualResponse:



    """Get visual diff between two versions with multiple view modes.







    Provides unified, side-by-side, and inline diff views with statistics.



    """



    # Try both version storage systems



    v1_data = None



    v2_data = None



    entity_id = None







    # Check _versions first



    if req.version_a in _versions:



        v1_data = _versions[req.version_a]



    elif req.version_a in [v.get("version") for versions in _entity_versions.values() for v in versions]:



        for eid, vers in _entity_versions.items():



            for v in vers:



                if v.get("version") == req.version_a:



                    v1_data = v



                    entity_id = eid



                    break







    if req.version_b in _versions:



        v2_data = _versions[req.version_b]



    elif req.version_b in [v.get("version") for versions in _entity_versions.values() for v in versions]:



        for eid, vers in _entity_versions.items():



            for v in vers:



                if v.get("version") == req.version_b:



                    v2_data = v



                    break







    # If still not found, create mock data from version IDs



    if not v1_data:



        v1_data = {"entities": {}, "version": req.version_a, "created_at": datetime.now(timezone.utc).isoformat()}



    if not v2_data:



        v2_data = {"entities": {}, "version": req.version_b, "created_at": datetime.now(timezone.utc).isoformat()}







    data_a = v1_data.get("entities", {})



    data_b = v2_data.get("entities", {})







    # Also check properties if entities are empty



    if not data_a:



        data_a = {k: v for k, v in v1_data.items() if k not in ("version", "created_at", "timestamp")}



    if not data_b:



        data_b = {k: v for k, v in v2_data.items() if k not in ("version", "created_at", "timestamp")}







    # Compute visual diff



    hunks, computed_stats = _compute_visual_diff(data_a, data_b, req.context_lines, req.ignore_whitespace)







    diff_file = DiffFile(



        entity_id=entity_id or "root",



        hunks=hunks,



        additions=computed_stats["additions"],



        deletions=computed_stats["deletions"],



        unchanged=computed_stats["unchanged"]



    )







    # Calculate stats



    total_changes = computed_stats["additions"] + computed_stats["deletions"]



    total_keys = len(data_a) + len(data_b)



    change_percentage = (total_changes / max(total_keys, 1)) * 100







    stats = VersionDiffVisualStats(



        total_additions=computed_stats["additions"],



        total_deletions=computed_stats["deletions"],



        total_unchanged=computed_stats["unchanged"],



        files_changed=len(hunks),



        change_percentage=round(change_percentage, 2),



        added_entities=computed_stats["added"],



        removed_entities=computed_stats["removed"],



        modified_entities=computed_stats["modified"]



    )







    diff_files = [diff_file]







    return VersionDiffVisualResponse(



        version_a=req.version_a,



        version_b=req.version_b,



        view_mode=req.view_mode,



        files=diff_files,



        stats=stats,



        raw_unified_diff=_generate_unified_diff(req.version_a, req.version_b, diff_files),



        raw_side_by_side=_generate_side_by_side(req.version_a, req.version_b, diff_files)



    )











@router.post("/versions/diff/export", response_model=VersionDiffExportResponse)



async def export_version_diff(req: VersionDiffExportRequest) -> VersionDiffExportResponse:



    """Export version diff in specified format.







    Supports: json, html, markdown, text formats.



    """



    # Get version data



    v1_data = _versions.get(req.version_a)



    v2_data = _versions.get(req.version_b)







    if not v1_data:



        v1_data = {"entities": {}, "version": req.version_a, "created_at": datetime.now(timezone.utc).isoformat()}



    if not v2_data:



        v2_data = {"entities": {}, "version": req.version_b, "created_at": datetime.now(timezone.utc).isoformat()}







    data_a = v1_data.get("entities", {})



    data_b = v2_data.get("entities", {})







    # Compute diff



    hunks, computed_stats = _compute_visual_diff(data_a, data_b)







    diff_file = DiffFile(



        entity_id="root",



        hunks=hunks,



        additions=computed_stats["additions"],



        deletions=computed_stats["deletions"],



        unchanged=computed_stats["unchanged"]



    )







    diff_files = [diff_file]







    total_changes = computed_stats["additions"] + computed_stats["deletions"]



    total_keys = len(data_a) + len(data_b)



    change_percentage = (total_changes / max(total_keys, 1)) * 100







    stats = VersionDiffVisualStats(



        total_additions=computed_stats["additions"],



        total_deletions=computed_stats["deletions"],



        total_unchanged=computed_stats["unchanged"],



        files_changed=len(hunks),



        change_percentage=round(change_percentage, 2),



        added_entities=computed_stats["added"],



        removed_entities=computed_stats["removed"],



        modified_entities=computed_stats["modified"]



    )







    # Generate export based on format



    exported = ""



    filename = f"diff_{req.version_a}_{req.version_b}"







    if req.format == "json":



        exported = VersionDiffVisualResponse(



            version_a=req.version_a,



            version_b=req.version_b,



            view_mode="unified",



            files=diff_files,



            stats=stats,



            raw_unified_diff=_generate_unified_diff(req.version_a, req.version_b, diff_files),



            raw_side_by_side=_generate_side_by_side(req.version_a, req.version_b, diff_files)



        ).model_dump_json(indent=2)



        filename += ".json"







    elif req.format == "html":



        exported = _generate_html_diff(req.version_a, req.version_b, diff_files, stats)



        filename += ".html"







    elif req.format == "markdown":



        exported = _generate_markdown_diff(req.version_a, req.version_b, diff_files, stats)



        filename += ".md"







    elif req.format == "text":



        exported = _generate_unified_diff(req.version_a, req.version_b, diff_files)



        filename += ".txt"







    else:



        exported = VersionDiffVisualResponse(



            version_a=req.version_a,



            version_b=req.version_b,



            view_mode="unified",



            files=diff_files,



            stats=stats,



            raw_unified_diff=_generate_unified_diff(req.version_a, req.version_b, diff_files),



            raw_side_by_side=_generate_side_by_side(req.version_a, req.version_b, diff_files)



        ).model_dump_json(indent=2)



        filename += ".json"







    return VersionDiffExportResponse(



        exported_diff=exported,



        format=req.format,



        filename=filename



    )











@router.get("/versions/diff/stats", response_model=dict)



async def get_version_diff_stats(



    version_a: str = Query(..., description="First version"),



    version_b: str = Query(..., description="Second version"),



) -> dict:



    """Get diff statistics between two versions without full diff content."""



    # Get version data



    v1_data = _versions.get(version_a)



    v2_data = _versions.get(version_b)







    if not v1_data:



        v1_data = {"entities": {}}



    if not v2_data:



        v2_data = {"entities": {}}







    data_a = v1_data.get("entities", {})



    data_b = v2_data.get("entities", {})







    keys_a = set(data_a.keys())



    keys_b = set(data_b.keys())







    added = list(keys_b - keys_a)



    removed = list(keys_a - keys_b)



    common = keys_a & keys_b







    modified = []



    for key in common:



        if str(data_a.get(key, "")) != str(data_b.get(key, "")):



            modified.append(key)







    unchanged = len(common) - len(modified)



    total_changes = len(added) + len(removed) + len(modified)



    total = len(keys_a | keys_b)







    return {



        "version_a": version_a,



        "version_b": version_b,



        "stats": {



            "files_changed": len(added) + len(removed) + len(modified),



            "additions": len(added),



            "deletions": len(removed),



            "modifications": len(modified),



            "unchanged": unchanged,



            "total_changes": total_changes,



            "change_percentage": round((total_changes / max(total, 1)) * 100, 2)



        },



        "added_entities": added[:20],  # Limit to 20



        "removed_entities": removed[:20],



        "modified_entities": modified[:20]



    }











@router.post("/versions/diff/batch", response_model=dict)



async def batch_compare_versions(



    version_ids: list[str] = Body(..., description="List of version IDs to compare"),



    base_version: str = Query(..., description="Base version to compare against"),



) -> dict:



    """Compare multiple versions against a base version."""



    comparisons = []







    for version_id in version_ids:



        if version_id == base_version:



            continue







        v_base = _versions.get(base_version)



        v_compare = _versions.get(version_id)







        if not v_compare:



            continue







        if not v_base:



            v_base = {"entities": {}}







        data_base = v_base.get("entities", {})



        data_compare = v_compare.get("entities", {})







        keys_base = set(data_base.keys())



        keys_compare = set(data_compare.keys())







        added = len(keys_compare - keys_base)



        removed = len(keys_base - keys_compare)



        common = keys_base & keys_compare



        modified = sum(1 for k in common if str(data_base.get(k, "")) != str(data_compare.get(k, "")))







        comparisons.append({



            "version": version_id,



            "additions": added,



            "deletions": removed,



            "modifications": modified,



            "total_changes": added + removed + modified,



            "similarity": round(len(common) / max(len(keys_base | keys_compare), 1) * 100, 2)



        })







    comparisons.sort(key=lambda x: x["total_changes"], reverse=True)







    return {



        "base_version": base_version,



        "total_compared": len(comparisons),



        "comparisons": comparisons



    }











# =============================================================================



# Version Relation Heatmap (v1.32.0)



# =============================================================================







class VersionHeatmapRequest(BaseModel):



    """Request model for version heatmap generation."""



    version_ids: list[str] = Field(default=[], description="Specific versions to include (empty = all)")



    metric: str = Field(default="entity_overlap", description="Metric: entity_overlap, similarity, temporal")



    min_similarity: float = Field(default=0.0, description="Minimum similarity threshold (0.0-1.0)")



    include_clusters: bool = Field(default=True, description="Include version clustering")



    max_clusters: int = Field(default=5, description="Maximum number of clusters")











class VersionHeatmapCell(BaseModel):



    """Single cell in the heatmap matrix."""



    version_a: str



    version_b: str



    score: float



    label: str











class VersionCluster(BaseModel):



    """Cluster of related versions."""



    cluster_id: int



    versions: list[str]



    avg_similarity: float



    centroid_version: str











class VersionHeatmapResponse(BaseModel):



    """Response for version heatmap."""



    metric: str



    versions: list[str]



    matrix: list[VersionHeatmapCell]



    clusters: list[VersionCluster]



    min_score: float



    max_score: float



    avg_score: float



    total_pairs: int











class VersionRelationsRequest(BaseModel):



    """Request model for version relations analysis."""



    version_id: str = Field(description="Version to analyze relations for")



    max_relations: int = Field(default=10, description="Maximum number of related versions")











class VersionRelationEntry(BaseModel):



    """Single relation entry."""



    version_id: str



    score: float



    relation_type: str



    shared_entities: list[str]











class VersionRelationsResponse(BaseModel):



    """Response for version relations."""



    version_id: str



    total_relations: int



    relations: list[VersionRelationEntry]











class VersionOverlapMatrixRequest(BaseModel):



    """Request model for entity overlap matrix."""



    entity_type: str = Field(default="all", description="Entity type: all, knowledge, skill, agent, workflow")



    version_ids: list[str] = Field(default=[], description="Versions to include (empty = all)")











class VersionOverlapCell(BaseModel):



    """Cell in overlap matrix."""



    version_a: str



    version_b: str



    shared_count: int



    total_a: int



    total_b: int



    overlap_ratio: float











class VersionOverlapMatrixResponse(BaseModel):



    """Response for entity overlap matrix."""



    entity_type: str



    versions: list[str]



    matrix: list[VersionOverlapCell]



    total_entities: dict[str, int]











# Helper functions for version relation heatmap



def _compute_entity_overlap(entities_a: set, entities_b: set) -> float:



    """Compute entity overlap ratio between two entity sets (Jaccard)."""



    if not entities_a and not entities_b:



        return 0.0



    intersection = len(entities_a & entities_b)



    union = len(entities_a | entities_b)



    return intersection / union if union > 0 else 0.0











def _compute_version_similarity(version_a: dict, version_b: dict) -> float:



    """Compute overall similarity score between two versions."""



    score = 0.0



    weights = {"knowledge": 0.4, "skills": 0.3, "agents": 0.2, "workflows": 0.1}







    for entity_type, weight in weights.items():



        entities_a = set(version_a.get(entity_type, {}).keys())



        entities_b = set(version_b.get(entity_type, {}).keys())



        overlap = _compute_entity_overlap(entities_a, entities_b)



        score += overlap * weight







    return score











def _extract_version_entities(version: dict) -> dict[str, set]:



    """Extract all entity sets from a version."""



    return {



        "knowledge": set(version.get("knowledge", {}).keys()),



        "skills": set(version.get("skills", {}).keys()),



        "agents": set(version.get("agents", {}).keys()),



        "workflows": set(version.get("workflows", {}).keys())



    }











def _compute_heatmap_matrix(



    versions: list[str],



    metric: str = "entity_overlap"



) -> list[VersionHeatmapCell]:



    """Compute heatmap matrix for version relationships."""



    matrix = []







    for i, ver_a in enumerate(versions):



        for j, ver_b in enumerate(versions):



            if i >= j:



                continue







            v_a = _versions.get(ver_a, {})



            v_b = _versions.get(ver_b, {})







            if metric == "entity_overlap":



                ents_a = _extract_version_entities(v_a)



                ents_b = _extract_version_entities(v_b)







                all_ents_a = set()



                all_ents_b = set()



                for ents in ents_a.values():



                    all_ents_a.update(ents)



                for ents in ents_b.values():



                    all_ents_b.update(ents)







                score = _compute_entity_overlap(all_ents_a, all_ents_b)







            elif metric == "similarity":



                score = _compute_version_similarity(v_a, v_b)







            elif metric == "temporal":



                ts_a = v_a.get("timestamp", 0)



                ts_b = v_b.get("timestamp", 0)



                time_diff = abs(ts_a - ts_b) / (24 * 3600) if ts_a and ts_b else 365



                score = max(0.0, 1.0 - (time_diff / 365))







            else:



                score = 0.0







            matrix.append(VersionHeatmapCell(



                version_a=ver_a,



                version_b=ver_b,



                score=round(score, 4),



                label=f"{score:.1%}"



            ))







    return matrix











def _cluster_versions(



    matrix: list[VersionHeatmapCell],



    versions: list[str],



    max_clusters: int = 5



) -> list[VersionCluster]:



    """Cluster versions based on similarity using greedy grouping."""



    if not matrix:



        return []







    scores = {}



    for cell in matrix:



        key = (cell.version_a, cell.version_b)



        scores[key] = cell.score



        scores[(cell.version_b, cell.version_a)] = cell.score







    clusters = []



    assigned = set()







    for cluster_id in range(max_clusters):



        if len(assigned) >= len(versions):



            break







        available = [v for v in versions if v not in assigned]



        if not available:



            break







        cluster_versions = [available[0]]



        assigned.add(available[0])







        for ver in available[1:]:



            if ver in assigned:



                continue







            avg_sim = 0.0



            count = 0



            for cv in cluster_versions:



                key = (cv, ver)



                if key in scores:



                    avg_sim += scores[key]



                    count += 1







            if count > 0 and avg_sim / count > 0.1:



                cluster_versions.append(ver)



                assigned.add(ver)







        if len(cluster_versions) > 1:



            sim_sum = 0.0



            sim_count = 0



            for i, v1 in enumerate(cluster_versions):



                for v2 in cluster_versions[i+1:]:



                    key = (v1, v2)



                    if key in scores:



                        sim_sum += scores[key]



                        sim_count += 1







            avg_sim = sim_sum / sim_count if sim_count > 0 else 0.0







            centroid = max(cluster_versions, key=lambda v: sum(scores.get((v, other), 0) for other in cluster_versions if other != v))







            clusters.append(VersionCluster(



                cluster_id=cluster_id,



                versions=cluster_versions,



                avg_similarity=round(avg_sim, 4),



                centroid_version=centroid



            ))







    return clusters











async def get_version_heatmap(req: VersionHeatmapRequest) -> VersionHeatmapResponse:



    """Generate version relation heatmap."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())







    if len(target_versions) < 2:



        raise HTTPException(status_code=400, detail="At least 2 versions required")







    matrix = _compute_heatmap_matrix(target_versions, req.metric)







    filtered_cells = [c for c in matrix if c.score >= req.min_similarity]







    clusters = []



    if req.include_clusters:



        clusters = _cluster_versions(filtered_cells, target_versions, req.max_clusters)







    scores = [c.score for c in filtered_cells]



    min_score = min(scores) if scores else 0.0



    max_score = max(scores) if scores else 0.0



    avg_score = sum(scores) / len(scores) if scores else 0.0







    return VersionHeatmapResponse(



        metric=req.metric,



        versions=target_versions,



        matrix=filtered_cells,



        clusters=clusters,



        min_score=round(min_score, 4),



        max_score=round(max_score, 4),



        avg_score=round(avg_score, 4),



        total_pairs=len(filtered_cells)



    )











async def get_version_relations(req: VersionRelationsRequest) -> VersionRelationsResponse:



    """Get relations for a specific version."""



    if req.version_id not in _versions:



        raise HTTPException(status_code=404, detail=f"Version {req.version_id} not found")







    source_version = _versions[req.version_id]



    relations = []







    for vid, ver in _versions.items():



        if vid == req.version_id:



            continue







        similarity = _compute_version_similarity(source_version, ver)



        source_ents = _extract_version_entities(source_version)



        target_ents = _extract_version_entities(ver)







        shared = {}



        for ent_type in source_ents:



            shared[ent_type] = list(source_ents[ent_type] & target_ents[ent_type])







        total_shared = sum(len(v) for v in shared.values())







        if total_shared > 0:



            relation_type = "high" if similarity > 0.5 else "medium" if similarity > 0.2 else "low"







            relations.append(VersionRelationEntry(



                version_id=vid,



                score=round(similarity, 4),



                relation_type=relation_type,



                shared_entities=[e for ents in shared.values() for e in ents]



            ))







    relations.sort(key=lambda r: r.score, reverse=True)



    limited_relations = relations[:req.max_relations]







    return VersionRelationsResponse(



        version_id=req.version_id,



        total_relations=len(relations),



        relations=limited_relations



    )











async def get_version_overlap_matrix(req: VersionOverlapMatrixRequest) -> VersionOverlapMatrixResponse:



    """Generate entity overlap matrix."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())







    if len(target_versions) < 2:



        raise HTTPException(status_code=400, detail="At least 2 versions required")







    entity_type = req.entity_type



    matrix = []



    total_entities = {}







    for ver_id in target_versions:



        ver = _versions.get(ver_id, {})



        if entity_type == "all":



            ents = _extract_version_entities(ver)



            total = sum(len(e) for e in ents.values())



        else:



            ents = ver.get(entity_type, {})



            total = len(ents)







        total_entities[ver_id] = total







    for i, ver_a in enumerate(target_versions):



        for j, ver_b in enumerate(target_versions):



            if i >= j:



                continue







            v_a = _versions.get(ver_a, {})



            v_b = _versions.get(ver_b, {})







            if entity_type == "all":



                ents_a = _extract_version_entities(v_a)



                ents_b = _extract_version_entities(v_b)







                all_ents_a = set()



                all_ents_b = set()



                for ents in ents_a.values():



                    all_ents_a.update(ents)



                for ents in ents_b.values():



                    all_ents_b.update(ents)







                shared = len(all_ents_a & all_ents_b)



                total_a = total_entities[ver_a]



                total_b = total_entities[ver_b]







            else:



                ents_a = set(v_a.get(entity_type, {}).keys())



                ents_b = set(v_b.get(entity_type, {}).keys())



                shared = len(ents_a & ents_b)



                total_a = len(ents_a)



                total_b = len(ents_b)







            overlap = shared / min(total_a, total_b) if min(total_a, total_b) > 0 else 0.0







            matrix.append(VersionOverlapCell(



                version_a=ver_a,



                version_b=ver_b,



                shared_count=shared,



                total_a=total_a,



                total_b=total_b,



                overlap_ratio=round(overlap, 4)



            ))







    return VersionOverlapMatrixResponse(



        entity_type=entity_type,



        versions=target_versions,



        matrix=matrix,



        total_entities=total_entities



    )











