class VersionTrendRequest(BaseModel):



    """Request model for version trend analysis."""



    entity_type: str = Field(default="all", description="Entity type: all, knowledge, skill, agent, workflow")



    version_ids: list[str] = Field(default=[], description="Versions to include (empty = all, sorted by time)")



    start_version: str = Field(default="", description="Start version (empty = earliest)")



    end_version: str = Field(default="", description="End version (empty = latest)")



    include_derivatives: bool = Field(default=True, description="Include derivative metrics")











class VersionTrendPoint(BaseModel):



    """Single point in trend data."""



    version_id: str



    timestamp: float



    entity_counts: dict[str, int]



    change_from_previous: dict[str, int]



    growth_rate: dict[str, float]











class VersionTrendResponse(BaseModel):



    """Response for version trend analysis."""



    entity_type: str



    trend_points: list[VersionTrendPoint]



    overall_growth: dict[str, float]



    total_changes: dict[str, int]



    avg_growth_rate: dict[str, float]



    version_count: int











class VersionGrowthRequest(BaseModel):



    """Request model for growth analysis."""



    entity_type: str = Field(default="all", description="Entity type to analyze")



    version_ids: list[str] = Field(default=[], description="Versions to compare")











class VersionGrowthEntry(BaseModel):



    """Single growth entry."""



    version_id: str



    total_entities: int



    new_entities: int



    removed_entities: int



    net_change: int



    growth_percentage: float











class VersionGrowthResponse(BaseModel):



    """Response for growth analysis."""



    entity_type: str



    entries: list[VersionGrowthEntry]



    total_new: int



    total_removed: int



    net_growth: int



    growth_trend: str  # growing, declining, stable











class VersionEvolutionRequest(BaseModel):



    """Request model for version evolution analysis."""



