# Helper functions for version trend analysis



def _compute_entity_counts(version: dict, entity_type: str) -> dict[str, int]:



    """Compute entity counts for a version."""



    if entity_type == "all":



        return {



            "knowledge": len(version.get("knowledge", {})),



            "skills": len(version.get("skills", {})),



            "agents": len(version.get("agents", {})),



            "workflows": len(version.get("workflows", {}))



        }



    else:



        return {entity_type: len(version.get(entity_type, {}))}











def _compute_change_from_previous(



    prev_counts: dict[str, int],



    current_counts: dict[str, int]



) -> dict[str, int]:



    """Compute change from previous version."""



    return {



        k: current_counts.get(k, 0) - prev_counts.get(k, 0)



        for k in set(list(prev_counts.keys()) + list(current_counts.keys()))



    }











def _compute_growth_rate(prev_count: int, current_count: int) -> float:



    """Compute percentage growth rate."""



    if prev_count == 0:



        return 100.0 if current_count > 0 else 0.0



    return ((current_count - prev_count) / prev_count) * 100











def _sort_versions_by_time(version_ids: list[str]) -> list[str]:



    """Sort versions by timestamp."""



    version_list = []



    for vid in version_ids:



        ver = _versions.get(vid)



        if ver:



            ts = ver.get("timestamp", 0)



            version_list.append((vid, ts))







    version_list.sort(key=lambda x: x[1])



    return [v[0] for v in version_list]











def _get_entity_set(version: dict, entity_type: str) -> set:



    """Get entity set for a version."""



    if entity_type == "all":



        entities = set()



        for key in ["knowledge", "skills", "agents", "workflows"]:



            entities.update(version.get(key, {}).keys())



        return entities



    else:



        return set(version.get(entity_type, {}).keys())











def _compute_trend_data(



    version_ids: list[str],



    entity_type: str,



    include_derivatives: bool = True



) -> tuple[list[VersionTrendPoint], dict]:



    """Compute trend data for versions."""



    sorted_versions = _sort_versions_by_time(version_ids)







    trend_points = []



    prev_counts = {}







    overall_growth = {}



    total_changes = {}



    growth_rates = []







    for vid in sorted_versions:



        ver = _versions.get(vid)



        if not ver:



            continue







        entity_counts = _compute_entity_counts(ver, entity_type)







        if include_derivatives and prev_counts:



            change_from_prev = _compute_change_from_previous(prev_counts, entity_counts)



            growth_rate = {



                k: _compute_growth_rate(prev_counts.get(k, 0), entity_counts.get(k, 0))



                for k in entity_counts



            }



        else:



            change_from_prev = {k: 0 for k in entity_counts}



            growth_rate = {k: 0.0 for k in entity_counts}







        timestamp = ver.get("timestamp", 0)







        trend_points.append(VersionTrendPoint(



            version_id=vid,



            timestamp=timestamp,



            entity_counts=entity_counts,



            change_from_previous=change_from_prev,



            growth_rate=growth_rate



        ))







        for k in entity_counts:



            if k not in overall_growth:



                overall_growth[k] = 0



                total_changes[k] = 0







            overall_growth[k] += change_from_prev.get(k, 0)



            total_changes[k] += abs(change_from_prev.get(k, 0))







        growth_rates.append(growth_rate)







        prev_counts = entity_counts







    avg_growth_rate = {}



    if growth_rates:



        all_keys = set()



        for gr in growth_rates:



            all_keys.update(gr.keys())







        for k in all_keys:



            values = [gr.get(k, 0) for gr in growth_rates]



            avg_growth_rate[k] = sum(values) / len(values) if values else 0.0







    return trend_points, {



        "overall_growth": overall_growth,



        "total_changes": total_changes,



        "avg_growth_rate": avg_growth_rate



    }











async def get_version_trend(req: VersionTrendRequest) -> VersionTrendResponse:



    """Get version trend analysis."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())







    if req.start_version:



        start_ts = _versions.get(req.start_version, {}).get("timestamp", 0)



        target_versions = [



            v for v in target_versions



            if _versions.get(v, {}).get("timestamp", 0) >= start_ts



        ]







    if req.end_version:



        end_ts = _versions.get(req.end_version, {}).get("timestamp", float("inf"))



        target_versions = [



            v for v in target_versions



            if _versions.get(v, {}).get("timestamp", 0) <= end_ts



        ]







    if len(target_versions) < 2:



        raise HTTPException(status_code=400, detail="At least 2 versions required for trend")







    trend_points, metrics = _compute_trend_data(



        target_versions,



        req.entity_type,



        req.include_derivatives



    )







    return VersionTrendResponse(



        entity_type=req.entity_type,



        trend_points=trend_points,



        overall_growth=metrics["overall_growth"],



        total_changes=metrics["total_changes"],



        avg_growth_rate=metrics["avg_growth_rate"],



        version_count=len(target_versions)



    )











async def get_version_growth(req: VersionGrowthRequest) -> VersionGrowthResponse:



    """Analyze version growth patterns."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())



    sorted_versions = _sort_versions_by_time(target_versions)







    entity_type = req.entity_type



    entries = []



    total_new = 0



    total_removed = 0







    prev_entities = set()







    for vid in sorted_versions:



        ver = _versions.get(vid)



        if not ver:



            continue







        current_entities = _get_entity_set(ver, entity_type)







        new_entities = len(current_entities - prev_entities)



        removed_entities = len(prev_entities - current_entities)



        net_change = new_entities - removed_entities



        total = len(current_entities)







        growth_pct = _compute_growth_rate(len(prev_entities), total)







        entries.append(VersionGrowthEntry(



            version_id=vid,



            total_entities=total,



            new_entities=new_entities,



            removed_entities=removed_entities,



            net_change=net_change,



            growth_percentage=round(growth_pct, 2)



        ))







        total_new += new_entities



        total_removed += removed_entities



        prev_entities = current_entities







    net_growth = total_new - total_removed







    if net_growth > 10:



        growth_trend = "growing"



    elif net_growth < -10:



        growth_trend = "declining"



    else:



        growth_trend = "stable"







    return VersionGrowthResponse(



        entity_type=entity_type,



        entries=entries,



        total_new=total_new,



        total_removed=total_removed,



        net_growth=net_growth,



        growth_trend=growth_trend



    )











async def get_version_evolution(req: VersionEvolutionRequest) -> VersionEvolutionResponse:



    """Analyze entity evolution across versions."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    sorted_versions = _sort_versions_by_time(list(_versions.keys()))







    entity_type = req.entity_type



    entity_to_versions = {}



    all_entities = set()







    for i, vid in enumerate(sorted_versions):



        ver = _versions.get(vid)



        if not ver:



            continue







        entities = _get_entity_set(ver, entity_type)







        if req.entity_ids:



            entities = entities & set(req.entity_ids)







        for entity in entities:



            if entity not in entity_to_versions:



                entity_to_versions[entity] = []



            entity_to_versions[entity].append(vid)







        all_entities.update(entities)







    entries = []



    status_counts = {"added": 0, "modified": 0, "stable": 0, "removed": 0}







    for entity in sorted(entity_to_versions.keys()):



        versions = entity_to_versions[entity]



        first_ver = versions[0]



        last_ver = versions[-1]







        if len(versions) == 1:



            if last_ver == sorted_versions[-1]:



                status = "stable"



                status_counts["stable"] += 1



            else:



                status = "added"



                status_counts["added"] += 1



        else:



            if last_ver != sorted_versions[-1]:



                status = "removed"



                status_counts["removed"] += 1



            elif len(versions) < len(sorted_versions):



                status = "modified"



                status_counts["modified"] += 1



            else:



                status = "stable"



                status_counts["stable"] += 1







        if not req.include_history:



            versions = [first_ver, last_ver] if first_ver != last_ver else [first_ver]







        entries.append(VersionEvolutionEntry(



            entity_id=entity,



            first_version=first_ver,



            last_version=last_ver,



            version_count=len(versions),



            versions=versions,



            status=status



        ))







    total_entities = len(entity_to_versions)







    avg_lifespan = 0.0



    if entries:



        lifespans = [e.version_count for e in entries]



        avg_lifespan = sum(lifespans) / len(lifespans)







    return VersionEvolutionResponse(



        entity_type=entity_type,



        entries=entries[:100],



        total_entities=total_entities,



        status_counts=status_counts,



        avg_lifespan=round(avg_lifespan, 2)



    )











def _export_trend_csv(trend_data: list[VersionTrendPoint]) -> str:



    """Export trend data as CSV."""



    lines = ["version_id,timestamp,knowledge,skills,agents,workflows"]







    for point in trend_data:



        counts = point.entity_counts



        lines.append(



            f"{point.version_id},{point.timestamp},"



            f"{counts.get('knowledge', 0)},{counts.get('skills', 0)},"



            f"{counts.get('agents', 0)},{counts.get('workflows', 0)}"



        )







    return "\n".join(lines)











def _export_trend_markdown(trend_data: list[VersionTrendPoint]) -> str:



    """Export trend data as Markdown table."""



    lines = [



        "# Version Trend Analysis",



        "",



        "| Version | Timestamp | Knowledge | Skills | Agents | Workflows |",



        "|---------|----------|-----------|--------|--------|-----------|"



    ]







    for point in trend_data:



        counts = point.entity_counts



        lines.append(



            f"| {point.version_id} | {point.timestamp} | "



            f"{counts.get('knowledge', 0)} | {counts.get('skills', 0)} | "



            f"{counts.get('agents', 0)} | {counts.get('workflows', 0)} |"



        )







    return "\n".join(lines)











async def export_version_trend(req: VersionTrendExportRequest) -> VersionTrendExportResponse:



    """Export version trend data."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())



    sorted_versions = _sort_versions_by_time(target_versions)







    trend_points, _ = _compute_trend_data(



        sorted_versions,



        req.entity_type,



        include_derivatives=False



    )







    format_type = req.format.lower()







    if format_type == "csv":



        exported = _export_trend_csv(trend_points)



    elif format_type == "markdown":



        exported = _export_trend_markdown(trend_points)



    else:



        exported_data = [



            {



                "version_id": p.version_id,



                "timestamp": p.timestamp,



                "entity_counts": p.entity_counts



            }



            for p in trend_points



        ]



        exported = json.dumps(exported_data, indent=2)







    filename = f"version_trend_{req.entity_type}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.{format_type}"







    return VersionTrendExportResponse(



        exported_data=exported,



        format=format_type,



        filename=filename



    )











