# Helper functions for version health scoring



def _compute_completeness(version: dict) -> float:



    """Compute completeness score (0-100)."""



    score = 0.0



    max_score = 100.0







    required_fields = ["knowledge", "skills", "agents", "workflows"]



    present_count = sum(1 for f in required_fields if version.get(f))







    score += (present_count / len(required_fields)) * 40







    entities = {



        "knowledge": version.get("knowledge", {}),



        "skills": version.get("skills", {}),



        "agents": version.get("agents", {}),



        "workflows": version.get("workflows", {})



    }







    for entity_type, entity_dict in entities.items():



        if entity_dict:



            count = len(entity_dict)



            score += min(count / 10, 15)







    return min(score, max_score)











def _compute_consistency(version: dict) -> float:



    """Compute consistency score (0-100)."""



    score = 50.0







    entities = {



        "knowledge": version.get("knowledge", {}),



        "skills": version.get("skills", {}),



        "agents": version.get("agents", {}),



        "workflows": version.get("workflows", {})



    }







    entity_counts = {k: len(v) for k, v in entities.items()}







    if len(set(entity_counts.values())) == 1:



        score = 100.0



    elif len(set(entity_counts.values())) == 2:



        score = 75.0



    else:



        counts = list(entity_counts.values())



        if counts:



            avg = sum(counts) / len(counts)



            variance = sum((c - avg) ** 2 for c in counts) / len(counts)



            std_dev = variance ** 0.5



            if avg > 0:



                cv = std_dev / avg



                score = max(0, 100 - (cv * 50))







    return score











def _compute_recency(version: dict) -> float:



    """Compute recency score based on timestamp (0-100)."""



    timestamp = version.get("timestamp", 0)







    if not timestamp:



        return 0.0







    current_time = datetime.now().timestamp()



    age_days = (current_time - timestamp) / (24 * 3600)







    if age_days <= 1:



        return 100.0



    elif age_days <= 7:



        return 90.0



    elif age_days <= 30:



        return 70.0



    elif age_days <= 90:



        return 50.0



    elif age_days <= 180:



        return 30.0



    else:



        return 10.0











def _compute_growth_score(version: dict, all_versions: dict) -> float:



    """Compute growth score based on entity count trends (0-100)."""



    if not all_versions:



        return 50.0







    version_list = sorted(all_versions.items(), key=lambda x: x[1].get("timestamp", 0))







    current_count = sum(len(v.get(k, {})) for k in ["knowledge", "skills", "agents", "workflows"] for v in [version])







    if len(version_list) < 2:



        return 50.0 if current_count > 0 else 0.0







    past_counts = []



    for vid, ver in version_list[:-1]:



        count = sum(len(ver.get(k, {})) for k in ["knowledge", "skills", "agents", "workflows"])



        past_counts.append(count)







    if past_counts:



        avg_past = sum(past_counts) / len(past_counts)



        if avg_past > 0:



            if current_count > avg_past:



                growth = ((current_count - avg_past) / avg_past) * 100



                return min(100, 50 + min(growth, 50))



            elif current_count < avg_past:



                decline = ((avg_past - current_count) / avg_past) * 100



                return max(0, 50 - min(decline, 50))



            else:



                return 50.0







    return 50.0











def _compute_stability(version: dict, all_versions: dict) -> float:



    """Compute stability score (0-100)."""



    if not all_versions:



        return 50.0







    version_list = sorted(all_versions.items(), key=lambda x: x[1].get("timestamp", 0))







    version_ids = [vid for vid, _ in version_list]



    current_idx = version_ids.index(version.get("id", "")) if version.get("id") in version_ids else -1







    if current_idx <= 0 or current_idx == -1:



        return 50.0







    prev_version = all_versions.get(version_ids[current_idx - 1], {})







    current_entities = set()



    prev_entities = set()







    for k in ["knowledge", "skills", "agents", "workflows"]:



        current_entities.update(version.get(k, {}).keys())



        prev_entities.update(prev_version.get(k, {}).keys())







    if not prev_entities:



        return 50.0







    stable_ratio = len(current_entities & prev_entities) / len(prev_entities)







    return stable_ratio * 100











def _compute_overall_health(



    version: dict,



    all_versions: dict,



    weights: dict[str, float]



) -> tuple[float, dict[str, float], list[str], list[str]]:



    """Compute overall health score."""



    if not weights:



        weights = {



            "completeness": 0.25,



            "consistency": 0.20,



            "recency": 0.20,



            "growth": 0.15,



            "stability": 0.20



        }







    completeness = _compute_completeness(version)



    consistency = _compute_consistency(version)



    recency = _compute_recency(version)



    growth = _compute_growth_score(version, all_versions)



    stability = _compute_stability(version, all_versions)







    metric_scores = {



        "completeness": completeness,



        "consistency": consistency,



        "recency": recency,



        "growth": growth,



        "stability": stability



    }







    overall = sum(metric_scores[k] * weights.get(k, 0) for k in metric_scores)







    issues = []



    recommendations = []







    if completeness < 50:



        issues.append("Low completeness score")



        recommendations.append("Add more entities to improve completeness")



    if consistency < 50:



        issues.append("Inconsistent entity distribution")



        recommendations.append("Balance entity counts across types")



    if recency < 50:



        issues.append("Version is outdated")



        recommendations.append("Update version with recent changes")



    if growth < 30:



        issues.append("Negative or no growth")



        recommendations.append("Focus on adding new entities")



    if stability < 50:



        issues.append("Low stability")



        recommendations.append("Maintain entities from previous version")







    return round(overall, 2), metric_scores, issues, recommendations











def _get_grade(score: float) -> str:



    """Get letter grade from score."""



    if score >= 90:



        return "A"



    elif score >= 80:



        return "B"



    elif score >= 70:



        return "C"



    elif score >= 60:



        return "D"



    else:



        return "F"











async def get_version_health(req: VersionHealthRequest) -> VersionHealthSummary:



    """Get health scores for versions."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    target_versions = req.version_ids if req.version_ids else list(_versions.keys())







    weights = req.weight_config if req.weight_config else {}







    versions = []



    all_scores = []



    issue_counts = {}



    highest_scored = ""



    lowest_scored = ""



    highest_score = 0



    lowest_score = 100







    for vid in target_versions:



        ver = _versions.get(vid)



        if not ver:



            continue







        overall, metric_scores, issues, recommendations = _compute_overall_health(ver, _versions, weights)







        grade = _get_grade(overall)







        filtered_metrics = metric_scores



        if req.include_metrics:



            filtered_metrics = {k: v for k, v in metric_scores.items() if k in req.include_metrics}







        versions.append(VersionHealthScore(



            version_id=vid,



            overall_score=overall,



            metric_scores=filtered_metrics,



            grade=grade,



            issues=issues,



            recommendations=recommendations



        ))







        all_scores.append(overall)







        for issue in issues:



            issue_counts[issue] = issue_counts.get(issue, 0) + 1







        if overall > highest_score:



            highest_score = overall



            highest_scored = vid







        if overall < lowest_score:



            lowest_score = overall



            lowest_scored = vid







    average_score = sum(all_scores) / len(all_scores) if all_scores else 0.0







    return VersionHealthSummary(



        total_versions=len(versions),



        average_score=round(average_score, 2),



        versions=versions,



        highest_scored=highest_scored,



        lowest_scored=lowest_scored,



        common_issues=issue_counts



    )











async def compare_version_health(req: VersionHealthCompareRequest) -> VersionHealthCompareResponse:



    """Compare health scores across versions."""



    if not _versions:



        raise HTTPException(status_code=404, detail="No versions found")







    metric = req.metric



    rankings = []



    scores = {}







    for vid in req.version_ids:



        ver = _versions.get(vid)



        if not ver:



            continue







        if metric == "overall":



            overall, _, _, _ = _compute_overall_health(ver, _versions, {})



            scores[vid] = overall



        else:



            if metric == "completeness":



                scores[vid] = _compute_completeness(ver)



            elif metric == "consistency":



                scores[vid] = _compute_consistency(ver)



            elif metric == "recency":



                scores[vid] = _compute_recency(ver)



            elif metric == "growth":



                scores[vid] = _compute_growth_score(ver, _versions)



            elif metric == "stability":



                scores[vid] = _compute_stability(ver, _versions)



            else:



                raise HTTPException(status_code=400, detail=f"Unknown metric: {metric}")







    sorted_versions = sorted(scores.items(), key=lambda x: x[1], reverse=True)







    for rank, (vid, score) in enumerate(sorted_versions, 1):



        rankings.append({



            "rank": rank,



            "version_id": vid,



            "score": round(score, 2)



        })







    best_version = sorted_versions[0][0] if sorted_versions else ""







    suggestions = []



    if rankings:



        top_score = rankings[0]["score"]



        bottom_score = rankings[-1]["score"]



        if top_score - bottom_score > 20:



            suggestions.append(f"Version {bottom_score} needs significant improvement")







    return VersionHealthCompareResponse(



        metric=metric,



        rankings=rankings,



        best_version=best_version,



        improvement_suggestions=suggestions



    )











async def get_health_stats() -> VersionHealthStatsResponse:



    """Get health statistics."""



    if not _versions:



        return VersionHealthStatsResponse(



            total_versions=0,



            average_score=0.0,



            score_distribution={"A": 0, "B": 0, "C": 0, "D": 0, "F": 0},



            metric_averages={}



        )







    all_scores = []



    grade_counts = {"A": 0, "B": 0, "C": 0, "D": 0, "F": 0}



    metric_totals = {"completeness": 0, "consistency": 0, "recency": 0, "growth": 0, "stability": 0}







    for vid, ver in _versions.items():



        overall, metrics, _, _ = _compute_overall_health(ver, _versions, {})



        all_scores.append(overall)







        grade = _get_grade(overall)



        grade_counts[grade] += 1







        for k, v in metrics.items():



            if k in metric_totals:



                metric_totals[k] += v







    total = len(_versions)



    avg_score = sum(all_scores) / total if total > 0 else 0.0







    metric_averages = {k: round(v / total, 2) for k, v in metric_totals.items()}







    return VersionHealthStatsResponse(



        total_versions=total,



        average_score=round(avg_score, 2),



        score_distribution=grade_counts,



        metric_averages=metric_averages



    )











