from typing import Any



from pydantic import BaseModel, Field



from datetime import datetime, timedelta



import hashlib



import json











class DiffPatternsResponse(BaseModel):



    """Response model for diff pattern analysis."""



    patterns: list[dict]



    summary: dict



    recommendations: list[str]











class DiffVelocityResponse(BaseModel):



    """Response model for change velocity analysis."""



    velocities: list[dict]



    average_velocity: float



    trend: str



    recommendations: list[str]











class DiffInsightsResponse(BaseModel):



    """Response model for AI-generated diff insights."""



    insights: list[dict]



    summary: str



    risk_level: str



    recommendations: list[str]











class DiffEvolutionResponse(BaseModel):



    """Response model for diff evolution over versions."""



    timeline: list[dict]



    patterns_detected: list[str]



    trend_direction: str



    forecast: list[dict]











class DiffPredictionRequest(BaseModel):



    """Request model for diff prediction."""



    base_version: str = Field(..., description="Base version ID")



    target_version: str | None = Field(None, description="Target version")



    simulation_mode: bool = Field(False, description="Enable simulation mode")











class DiffPredictionResponse(BaseModel):



    """Response model for diff prediction."""



    predicted_changes: dict



    confidence: float



    ai_insight: str



    risk_assessment: str



    validation: dict | None = None











async def analyze_diff_patterns(version_a: str, version_b: str) -> DiffPatternsResponse:



    """Analyze change patterns between two versions."""



    v1_data = _versions.get(version_a) or {"entities": {}}



    v2_data = _versions.get(version_b) or {"entities": {}}







    data_a = v1_data.get("entities", {})



    data_b = v2_data.get("entities", {})







    keys_a = set(data_a.keys())



    keys_b = set(data_b.keys())







    added = keys_b - keys_a



    removed = keys_a - keys_b



    common = keys_a & keys_b







    modified = []



    unchanged = []



    for k in common:



        if str(data_a.get(k, "")) != str(data_b.get(k, "")):



            modified.append(k)



        else:



            unchanged.append(k)







    total_entities = len(keys_b)



    add_ratio = len(added) / total_entities if total_entities > 0 else 0



    remove_ratio = len(removed) / total_entities if total_entities > 0 else 0



    modify_ratio = len(modified) / total_entities if total_entities > 0 else 0







    patterns = []



    if add_ratio > 0.3 and remove_ratio < 0.1:



        patterns.append({"type": "expansion", "score": round(add_ratio, 2), "description": "Bulk entity addition"})



    if remove_ratio > 0.3 and add_ratio < 0.1:



        patterns.append({"type": "pruning", "score": round(remove_ratio, 2), "description": "Bulk entity removal"})



    if modify_ratio > 0.5:



        patterns.append({"type": "heavy_modification", "score": round(modify_ratio, 2), "description": "Heavy modification"})



    if len(added) > 0 and len(removed) > 0 and abs(add_ratio - remove_ratio) < 0.1:



        patterns.append({"type": "replacement", "score": round(min(add_ratio, remove_ratio), 2), "description": "Entity replacement"})



    if add_ratio < 0.1 and remove_ratio < 0.1 and modify_ratio < 0.1:



        patterns.append({"type": "incremental", "score": round(1 - (add_ratio + remove_ratio + modify_ratio), 2), "description": "Minimal incremental change"})







    summary = {



        "added": len(added),



        "removed": len(removed),



        "modified": len(modified),



        "unchanged": len(unchanged),



        "primary_pattern": patterns[0]["type"] if patterns else "unknown"



    }







    recommendations = []



    if add_ratio > 0.3:



        recommendations.append("Consider reviewing new entities for quality and relevance")



    if remove_ratio > 0.3:



        recommendations.append("Review removed entities - ensure no critical data was lost")



    if modify_ratio > 0.5:



        recommendations.append("Track modification patterns - could indicate unstable data")







    return DiffPatternsResponse(



        patterns=patterns,



        summary=summary,



        recommendations=recommendations



    )











async def calculate_diff_velocity(versions: list[str]) -> DiffVelocityResponse:



    """Calculate change velocity across multiple versions."""



    velocities = []



    valid_versions = [v for v in versions if v in _versions]







    for i in range(len(valid_versions) - 1):



        v1 = valid_versions[i]



        v2 = valid_versions[i + 1]







        v1_data = _versions.get(v1) or {"entities": {}}



        v2_data = _versions.get(v2) or {"entities": {}}







        data_a = v1_data.get("entities", {})



        data_b = v2_data.get("entities", {})







        keys_a = set(data_a.keys())



        keys_b = set(data_b.keys())







        added = len(keys_b - keys_a)



        removed = len(keys_a - keys_b)



        total_changes = added + removed







        try:



            ts1 = v1_data.get("timestamp", datetime.now().isoformat())



            ts2 = v2_data.get("timestamp", datetime.now().isoformat())



            t1 = datetime.fromisoformat(ts1)



            t2 = datetime.fromisoformat(ts2)



            days_diff = max(1, abs((t2 - t1).days))



        except:



            days_diff = 1







        velocity = total_changes / days_diff if days_diff > 0 else 0







        velocities.append({



            "from_version": v1,



            "to_version": v2,



            "changes": total_changes,



            "days": days_diff,



            "velocity": round(velocity, 2)



        })







    avg_velocity = sum(v["velocity"] for v in velocities) / len(velocities) if velocities else 0







    if len(velocities) < 2:



        trend = "stable"



    else:



        first_half = sum(v["velocity"] for v in velocities[:len(velocities)//2]) / (len(velocities)//2 or 1)



        second_half = sum(v["velocity"] for v in velocities[len(velocities)//2:]) / (len(velocities) - len(velocities)//2 or 1)







        if second_half > first_half * 1.2:



            trend = "accelerating"



        elif second_half < first_half * 0.8:



            trend = "decelerating"



        else:



            trend = "stable"







    recommendations = []



    if trend == "accelerating":



        recommendations.append("Change velocity is increasing - monitor for potential instability")



    elif trend == "decelerating":



        recommendations.append("Change velocity is decreasing - system may be stabilizing")







    return DiffVelocityResponse(



        velocities=velocities,



        average_velocity=round(avg_velocity, 2),



        trend=trend,



        recommendations=recommendations



    )











async def generate_diff_insights(version_a: str, version_b: str) -> DiffInsightsResponse:



    """Generate AI-powered insights about version diff."""



    v1_data = _versions.get(version_a) or {"entities": {}}



    v2_data = _versions.get(version_b) or {"entities": {}}







    data_a = v1_data.get("entities", {})



    data_b = v2_data.get("entities", {})







    keys_a = set(data_a.keys())



    keys_b = set(data_b.keys())







    added = list(keys_b - keys_a)



    removed = list(keys_a - keys_b)



    common = keys_a & keys_b







    modified = []



    for k in common:



        if str(data_a.get(k, "")) != str(data_b.get(k, "")):



            modified.append(k)







    insights = []







    size_change = len(keys_b) - len(keys_a)



    if size_change > 10:



        insights.append({



            "type": "size",



            "title": "Significant Size Change",



            "description": f"Version grew by {size_change} entities",



            "severity": "medium"



        })



    elif size_change < -10:



        insights.append({



            "type": "size",



            "title": "Significant Size Reduction",



            "description": f"Version reduced by {abs(size_change)} entities",



            "severity": "medium"



        })







    if len(added) > len(keys_a) * 0.2:



        insights.append({



            "type": "addition",



            "title": "Bulk Entity Addition",



            "description": f"Added {len(added)} new entities",



            "severity": "low"



        })







    if len(removed) > len(keys_a) * 0.2:



        insights.append({



            "type": "removal",



            "title": "Bulk Entity Removal",



            "description": f"Removed {len(removed)} entities",



            "severity": "high"



        })







    if len(modified) > len(common) * 0.3:



        insights.append({



            "type": "modification",



            "title": "High Modification Rate",



            "description": f"Modified {len(modified)} entities",



            "severity": "medium"



        })







    empty_entities = sum(1 for v in data_b.values() if not v or str(v).strip() == "")



    if empty_entities > len(data_b) * 0.1:



        insights.append({



            "type": "quality",



            "title": "Potential Data Quality Issues",



            "description": f"{empty_entities} empty entities found",



            "severity": "high"



        })







    summary_parts = []



    if len(added) > len(removed):



        summary_parts.append(f"added {len(added)} new")



    if len(removed) > 0:



        summary_parts.append(f"removed {len(removed)}")



    if len(modified) > 0:



        summary_parts.append(f"modified {len(modified)}")







    summary = ", ".join(summary_parts) if summary_parts else "Minimal changes detected"







    risk_counts = {"high": 0, "medium": 0, "low": 0}



    for insight in insights:



        risk_counts[insight["severity"]] = risk_counts.get(insight["severity"], 0) + 1







    if risk_counts["high"] > 0:



        risk_level = "high"



    elif risk_counts["medium"] > 1:



        risk_level = "medium"



    else:



        risk_level = "low"







    recommendations = []



    if risk_level == "high":



        recommendations.append("Review high-severity insights before proceeding")



    if empty_entities > len(data_b) * 0.1:



        recommendations.append("Data quality improvements needed")







    return DiffInsightsResponse(



        insights=insights,



        summary=summary,



        risk_level=risk_level,



        recommendations=recommendations



    )











async def get_diff_evolution(versions: list[str]) -> DiffEvolutionResponse:



    """Get diff evolution over multiple versions."""



    timeline = []



    valid_versions = [v for v in versions if v in _versions]







    for i in range(len(valid_versions) - 1):



        v1 = valid_versions[i]



        v2 = valid_versions[i + 1]







        v1_data = _versions.get(v1) or {"entities": {}}



        v2_data = _versions.get(v2) or {"entities": {}}







        data_a = v1_data.get("entities", {})



        data_b = v2_data.get("entities", {})







        keys_a = set(data_a.keys())



        keys_b = set(data_b.keys())







        timeline.append({



            "from_version": v1,



            "to_version": v2,



            "added": len(keys_b - keys_a),



            "removed": len(keys_a - keys_b),



            "net_change": len(keys_b) - len(keys_a)



        })







    patterns = []



    if all(t["added"] > t["removed"] for t in timeline if t["added"] > 0 or t["removed"] > 0):



        patterns.append("consistent_growth")



    if all(t["removed"] > t["added"] for t in timeline if t["added"] > 0 or t["removed"] > 0):



        patterns.append("consistent_decline")







    if len(timeline) < 2:



        trend_direction = "stable"



    else:



        net_changes = [t["net_change"] for t in timeline]



        first_half = sum(net_changes[:len(net_changes)//2]) / (len(net_changes)//2 or 1)



        second_half = sum(net_changes[len(net_changes)//2:]) / (len(net_changes) - len(net_changes)//2 or 1)







        if second_half > first_half:



            trend_direction = "increasing"



        elif second_half < first_half:



            trend_direction = "decreasing"



        else:



            trend_direction = "stable"







    forecast = []



    if len(timeline) >= 2:



        avg_change = sum(t["net_change"] for t in timeline) / len(timeline)



        forecast = [



            {"predicted_change": round(avg_change * (i + 1), 0), "confidence": max(0.5, 1 - (i + 1) * 0.15)}



            for i in range(2)



        ]







    return DiffEvolutionResponse(



        timeline=timeline,



        patterns_detected=patterns,



        trend_direction=trend_direction,



        forecast=forecast



    )











async def predict_diff(req: DiffPredictionRequest) -> DiffPredictionResponse:



    """Predict changes using pattern analysis."""



    base_data = _versions.get(req.base_version) or {"entities": {}}



    data = base_data.get("entities", {})







    version_list = list(_versions.keys())



    if len(version_list) >= 2:



        v1 = version_list[-2]



        v2 = version_list[-1]







        v1_data = _versions.get(v1) or {"entities": {}}



        v2_data = _versions.get(v2) or {"entities": {}}







        data_a = v1_data.get("entities", {})



        data_b = v2_data.get("entities", {})







        keys_a = set(data_a.keys())



        keys_b = set(data_b.keys())







        added_recent = keys_b - keys_a



        removed_recent = keys_a - keys_b







        predicted_changes = {



            "predicted_additions": list(added_recent)[:5],



            "predicted_removals": list(removed_recent)[:5],



            "confidence": 0.7,



            "based_on_pattern": f"{v1} -> {v2}"



        }







        ai_insight = f"Based on recent pattern from {v1} to {v2}, expect similar changes"



        risk_assessment = "medium" if len(added_recent) > len(removed_recent) else "low"







        validation = None



        if req.target_version:



            target_data = _versions.get(req.target_version) or {"entities": {}}



            target_keys = set(target_data.get("entities", {}).keys())







            actual_added = target_keys - set(data.keys())



            actual_removed = set(data.keys()) - target_keys







            overlap_add = len(set(predicted_changes["predicted_additions"]) & actual_added)



            overlap_remove = len(set(predicted_changes["predicted_removals"]) & actual_removed)







            validation = {



                "actual_additions": len(actual_added),



                "actual_removals": len(actual_removed),



                "predicted_additions_correct": overlap_add,



                "predicted_removals_correct": overlap_remove



            }







        return DiffPredictionResponse(



            predicted_changes=predicted_changes,



            confidence=0.7,



            ai_insight=ai_insight,



            risk_assessment=risk_assessment,



            validation=validation



        )



    else:



        return DiffPredictionResponse(



            predicted_changes={"error": "Insufficient historical data"},



            confidence=0.0,



            ai_insight="Need at least 2 versions for prediction",



            risk_assessment="unknown",



            validation=None



        )











