# Version Statistics Summary



class VersionStatsSummary(BaseModel):



    """Summary statistics for all versions."""



    total_versions: int



    total_entities: int



    total_relations: int



    total_tags: int



    avg_entities_per_version: float



    avg_relations_per_version: float



    avg_tags_per_version: float



    most_active_version: str | None



    least_active_version: str | None



    versions_with_most_growth: str | None



    oldest_version: str | None



    newest_version: str | None



    timestamp: str











@router.get("/versions/analytics/summary", response_model=VersionStatsSummary)



async def get_version_stats_summary() -> VersionStatsSummary:



    """Get summary statistics across all versions."""



    global _versions







    if not _versions:



        return VersionStatsSummary(



            total_versions=0, total_entities=0, total_relations=0, total_tags=0,



            avg_entities_per_version=0.0, avg_relations_per_version=0.0, avg_tags_per_version=0.0,



            most_active_version=None, least_active_version=None, versions_with_most_growth=None,



            oldest_version=None, newest_version=None, timestamp=_now_iso()



        )







    entity_counts = []



    relation_counts = []



    tag_counts = []



    activity_scores = []







    for vid, v in _versions.items():



        entities = v.get("entities", [])



        relations = v.get("relations", [])



        tags = v.get("tags", [])



        activity = v.get("activity", {})







        entity_counts.append(len(entities))



        relation_counts.append(len(relations))



        tag_counts.append(len(tags))



        activity_scores.append(activity.get("edit_count", 0))







    total_entities = sum(entity_counts)



    total_relations = sum(relation_counts)



    total_tags = sum(tag_counts)



    total_versions = len(_versions)







    avg_entities = total_entities / total_versions if total_versions > 0 else 0



    avg_relations = total_relations / total_versions if total_versions > 0 else 0



    avg_tags = total_tags / total_versions if total_versions > 0 else 0







    # Find most/least active



    most_active_idx = activity_scores.index(max(activity_scores)) if activity_scores else 0



    least_active_idx = activity_scores.index(min(activity_scores)) if activity_scores else 0







    version_ids = list(_versions.keys())



    most_active = version_ids[most_active_idx] if version_ids else None



    least_active = version_ids[least_active_idx] if version_ids else None







    # Find versions with most growth (based on entity count growth)



    growth_rates = []



    sorted_versions = sorted(_versions.items(), key=lambda x: x[1].get("timestamp", ""))



    for i in range(1, len(sorted_versions)):



        prev_count = len(sorted_versions[i-1][1].get("entities", []))



        curr_count = len(sorted_versions[i][1].get("entities", []))



        growth = (curr_count - prev_count) / max(prev_count, 1) * 100 if prev_count > 0 else 0



        growth_rates.append((sorted_versions[i][0], growth))







    most_growth = max(growth_rates, key=lambda x: x[1])[0] if growth_rates else None







    # Timestamps for oldest/newest



    timestamps = [(vid, v.get("timestamp", "")) for vid, v in _versions.items()]



    timestamps.sort(key=lambda x: x[1])



    oldest = timestamps[0][0] if timestamps else None



    newest = timestamps[-1][0] if timestamps else None







    return VersionStatsSummary(



        total_versions=total_versions,



        total_entities=total_entities,



        total_relations=total_relations,



        total_tags=total_tags,



        avg_entities_per_version=round(avg_entities, 2),



        avg_relations_per_version=round(avg_relations, 2),



        avg_tags_per_version=round(avg_tags, 2),



        most_active_version=most_active,



        least_active_version=least_active,



        versions_with_most_growth=most_growth,



        oldest_version=oldest,



        newest_version=newest,



        timestamp=_now_iso()



    )











# Version Anomaly Detection



class VersionAnomaly(BaseModel):



    """Detected anomaly in a version."""



    version_id: str



    anomaly_type: str  # low_entities, high_relations, unusual_tags, activity_drop



    severity: str  # low, medium, high



    description: str



    expected_value: float



    actual_value: float



    deviation_percent: float











class VersionAnomalyResponse(BaseModel):



    """Response for anomaly detection."""



    anomalies: list[VersionAnomaly]



    total_checked: int



    anomaly_count: int



    severity_breakdown: dict[str, int]



    timestamp: str











@router.get("/versions/analytics/anomalies", response_model=VersionAnomalyResponse)



async def detect_version_anomalies(



    sensitivity: str = Query("medium", description="Detection sensitivity: low, medium, high"),



) -> VersionAnomalyResponse:



    """Detect anomalies in version data."""



    global _versions







    if not _versions:



        return VersionAnomalyResponse(



            anomalies=[], total_checked=0, anomaly_count=0,



            severity_breakdown={"low": 0, "medium": 0, "high": 0}, timestamp=_now_iso()



        )







    # Calculate baseline statistics



    entity_counts = [len(v.get("entities", [])) for v in _versions.values()]



    relation_counts = [len(v.get("relations", [])) for v in _versions.values()]



    tag_counts = [len(v.get("tags", [])) for v in _versions.values()]



    activity_scores = [v.get("activity", {}).get("edit_count", 0) for v in _versions.values()]







    # Set sensitivity thresholds



    sensitivity_multipliers = {"low": 3.0, "medium": 2.0, "high": 1.5}



    multiplier = sensitivity_multipliers.get(sensitivity, 2.0)







    mean_entities = statistics.mean(entity_counts) if entity_counts else 0



    std_entities = statistics.stdev(entity_counts) if len(entity_counts) > 1 else 0



    mean_relations = statistics.mean(relation_counts) if relation_counts else 0



    std_relations = statistics.stdev(relation_counts) if len(relation_counts) > 1 else 0



    mean_activity = statistics.mean(activity_scores) if activity_scores else 0







    anomalies = []



    severity_counts = {"low": 0, "medium": 0, "high": 0}







    for vid, v in _versions.items():



        entities = len(v.get("entities", []))



        relations = len(v.get("relations", []))



        tags = len(v.get("tags", []))



        activity = v.get("activity", {}).get("edit_count", 0)







        # Check for low entities



        if std_entities > 0 and entities < mean_entities - multiplier * std_entities:



            deviation = (mean_entities - entities) / std_entities



            severity = "high" if deviation > 2.5 else "medium" if deviation > 1.5 else "low"



            anomalies.append(VersionAnomaly(



                version_id=vid,



                anomaly_type="low_entities",



                severity=severity,



                description=f"Entity count {entities} is below expected {mean_entities:.0f}",



                expected_value=round(mean_entities, 2),



                actual_value=entities,



                deviation_percent=round((mean_entities - entities) / mean_entities * 100, 2) if mean_entities > 0 else 0



            ))



            severity_counts[severity] += 1







        # Check for high relations



        if std_relations > 0 and relations > mean_relations + multiplier * std_relations:



            deviation = (relations - mean_relations) / std_relations



            severity = "high" if deviation > 2.5 else "medium" if deviation > 1.5 else "low"



            anomalies.append(VersionAnomaly(



                version_id=vid,



                anomaly_type="high_relations",



                severity=severity,



                description=f"Relation count {relations} is above expected {mean_relations:.0f}",



                expected_value=round(mean_relations, 2),



                actual_value=relations,



                deviation_percent=round((relations - mean_relations) / mean_relations * 100, 2) if mean_relations > 0 else 0



            ))



            severity_counts[severity] += 1







        # Check for activity drop



        if mean_activity > 0 and activity < mean_activity - multiplier * (statistics.stdev(activity_scores) if len(activity_scores) > 1 else 0):



            deviation = (mean_activity - activity) / max(mean_activity, 1)



            severity = "high" if deviation > 0.75 else "medium" if deviation > 0.5 else "low"



            anomalies.append(VersionAnomaly(



                version_id=vid,



                anomaly_type="activity_drop",



                severity=severity,



                description=f"Activity {activity} is below expected {mean_activity:.0f}",



                expected_value=round(mean_activity, 2),



                actual_value=activity,



                deviation_percent=round(deviation * 100, 2)



            ))



            severity_counts[severity] += 1







    return VersionAnomalyResponse(



        anomalies=anomalies,



        total_checked=len(_versions),



        anomaly_count=len(anomalies),



        severity_breakdown=severity_counts,



        timestamp=_now_iso()



    )











# Version Correlation Analysis



class VersionCorrelationEntry(BaseModel):



    """Correlation between two version metrics."""



    metric_a: str



    metric_b: str



    correlation: float



    strength: str  # strong, moderate, weak, none











class VersionCorrelationResponse(BaseModel):



    """Response for correlation analysis."""



    correlations: list[VersionCorrelationEntry]



    version_id: str



    timestamp: str











@router.get("/versions/analytics/correlation/{version_id}", response_model=VersionCorrelationResponse)



async def analyze_version_correlation(



    version_id: str,



) -> VersionCorrelationResponse:



    """Analyze correlations between metrics in a version."""



    global _versions







    if version_id not in _versions:



        return VersionCorrelationResponse(



            correlations=[], version_id=version_id, timestamp=_now_iso()



        )







    v = _versions[version_id]



    entities = v.get("entities", [])



    relations = v.get("relations", [])



    tags = v.get("tags", [])







    # Calculate correlations



    entity_count = len(entities)



    relation_count = len(relations)



    tag_count = len(tags)







    correlations = []







    # Entity-Relation correlation (estimate based on ratio)



    if entity_count > 0:



        er_ratio = relation_count / entity_count



        if er_ratio > 2.0:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="relations",



                correlation=0.8,



                strength="strong"



            ))



        elif er_ratio > 1.0:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="relations",



                correlation=0.5,



                strength="moderate"



            ))



        else:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="relations",



                correlation=0.2,



                strength="weak"



            ))







    # Entity-Tag correlation



    if entity_count > 0:



        et_ratio = tag_count / entity_count



        if et_ratio > 0.5:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="tags",



                correlation=0.7,



                strength="strong"



            ))



        elif et_ratio > 0.2:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="tags",



                correlation=0.4,



                strength="moderate"



            ))



        else:



            correlations.append(VersionCorrelationEntry(



                metric_a="entities",



                metric_b="tags",



                correlation=0.1,



                strength="weak"



            ))







    # Relation-Tag correlation



    if relation_count > 0:



        rt_ratio = tag_count / relation_count



        if rt_ratio > 0.5:



            correlations.append(VersionCorrelationEntry(



                metric_a="relations",



                metric_b="tags",



                correlation=0.6,



                strength="moderate"



            ))



        else:



            correlations.append(VersionCorrelationEntry(



                metric_a="relations",



                metric_b="tags",



                correlation=0.2,



                strength="weak"



            ))







    return VersionCorrelationResponse(



        correlations=correlations,



        version_id=version_id,



        timestamp=_now_iso()



    )











