# Version Intelligence API Routes (v1.38.0)



# =============================================================================







import math



from datetime import datetime, timezone







# Version Quality Score



class VersionQualityScore(BaseModel):



    """Quality score for a version."""



    version_id: str



    overall_score: float  # 0-100



    grade: str  # A, B, C, D, F



    dimensions: dict[str, float]  # completeness, consistency, activity, connectivity



    strengths: list[str]



    weaknesses: list[str]



    recommendations: list[str]



    timestamp: str











class VersionQualityResponse(BaseModel):



    """Response for quality scores."""



    scores: list[VersionQualityScore]



    average_score: float



    timestamp: str











def _calculate_quality_score(version_id: str, version_data: dict) -> VersionQualityScore:



    """Calculate comprehensive quality score for a version."""



    entities = version_data.get("entities", [])



    relations = version_data.get("relations", [])



    tags = version_data.get("tags", [])



    activity = version_data.get("activity", {})







    entity_count = len(entities)



    relation_count = len(relations)



    tag_count = len(tags)



    edit_count = activity.get("edit_count", 0)







    # Dimension scores (0-100 each)



    # Completeness: entity count and tags



    completeness = min(100, (entity_count / 10 * 30) + (tag_count / 5 * 20))







    # Consistency: relation to entity ratio



    ratio = relation_count / max(entity_count, 1)



    consistency = min(100, ratio * 80) if ratio > 0 else 0







    # Activity: edit count



    activity_score = min(100, edit_count * 10)







    # Connectivity: relation density



    connectivity = min(100, relation_count / max(entity_count, 1) * 50 * 2)







    # Overall score (weighted average)



    overall = (completeness * 0.3 + consistency * 0.25 + activity_score * 0.2 + connectivity * 0.25)







    # Grade



    if overall >= 90:



        grade = "A"



    elif overall >= 75:



        grade = "B"



    elif overall >= 60:



        grade = "C"



    elif overall >= 40:



        grade = "D"



    else:



        grade = "F"







    # Strengths and weaknesses



    strengths = []



    weaknesses = []



    recommendations = []







    if completeness >= 60:



        strengths.append("Good entity completeness")



    else:



        weaknesses.append("Low entity count")



        recommendations.append("Add more entities to improve completeness")







    if consistency >= 50:



        strengths.append("Healthy entity-relation ratio")



    else:



        weaknesses.append("Low relation density")



        recommendations.append("Add relations between entities")







    if activity_score >= 30:



        strengths.append("Active version")



    else:



        weaknesses.append("Low activity")



        recommendations.append("Increase version activity")







    if connectivity >= 40:



        strengths.append("Good connectivity")



    else:



        weaknesses.append("Poor connectivity")



        recommendations.append("Increase relation density")







    return VersionQualityScore(



        version_id=version_id,



        overall_score=round(overall, 2),



        grade=grade,



        dimensions={



            "completeness": round(completeness, 2),



            "consistency": round(consistency, 2),



            "activity": round(activity_score, 2),



            "connectivity": round(connectivity, 2)



        },



        strengths=strengths,



        weaknesses=weaknesses,



        recommendations=recommendations,



        timestamp=_now_iso()



    )











@router.get("/versions/quality", response_model=VersionQualityResponse)



async def get_version_quality(



    version_ids: str = Query("", description="Comma-separated version IDs, empty for all"),



) -> VersionQualityResponse:



    """Get quality scores for versions."""



    global _versions







    if not _versions:



        return VersionQualityResponse(scores=[], average_score=0.0, timestamp=_now_iso())







    # Filter versions



    if version_ids:



        target_ids = [v.strip() for v in version_ids.split(",")]



        filtered = {k: v for k, v in _versions.items() if k in target_ids}



    else:



        filtered = _versions







    # Calculate scores



    scores = [_calculate_quality_score(vid, vdata) for vid, vdata in filtered.items()]







    # Sort by overall score



    scores.sort(key=lambda x: x.overall_score, reverse=True)







    # Average



    avg = sum(s.overall_score for s in scores) / len(scores) if scores else 0.0







    return VersionQualityResponse(



        scores=scores,



        average_score=round(avg, 2),



        timestamp=_now_iso()



    )











# Version Recommendation



class VersionRecommendation(BaseModel):



    """Recommended version."""



    version_id: str



    similarity: float  # 0-1



    recommendation_type: str  # similar_content, activity_based, growth_based



    reason: str











class VersionRecommendationResponse(BaseModel):



    """Response for recommendations."""



    source_version: str



    recommendations: list[VersionRecommendation]



    timestamp: str











@router.get("/versions/recommend/{version_id}", response_model=VersionRecommendationResponse)



async def get_version_recommendations(



    version_id: str,



    limit: int = Query(5, ge=1, le=20),



    recommendation_type: str = Query("all", description="similar, activity, growth"),



) -> VersionRecommendationResponse:



    """Get recommended related versions."""



    global _versions







    if version_id not in _versions:



        return VersionRecommendationResponse(



            source_version=version_id,



            recommendations=[],



            timestamp=_now_iso()



        )







    source = _versions[version_id]



    source_entities = set(e.get("id", "") for e in source.get("entities", []))



    source_relations = set(e.get("id", "") for e in source.get("relations", []))



    source_tags = set(e.get("id", "") for e in source.get("tags", []))



    source_activity = source.get("activity", {}).get("edit_count", 0)







    recommendations = []







    for vid, v in _versions.items():



        if vid == version_id:



            continue







        entities = set(e.get("id", "") for e in v.get("entities", []))



        relations = set(e.get("id", "") for e in v.get("relations", []))



        tags = set(e.get("id", "") for e in v.get("tags", []))



        activity = v.get("activity", {}).get("edit_count", 0)







        # Content similarity (Jaccard)



        all_a = source_entities | source_relations | source_tags



        all_b = entities | relations | tags



        intersection = len(all_a & all_b)



        union = len(all_a | all_b)



        similarity = intersection / union if union > 0 else 0.0







        # Activity similarity



        activity_diff = abs(source_activity - activity)



        activity_sim = max(0, 1 - activity_diff / 100)







        # Growth similarity (simplified)



        growth = len(entities) - len(source_entities)







        # Determine recommendation type



        rec_type = ""



        reason = ""







        if recommendation_type in ["all", "similar"] and similarity > 0.1:



            rec_type = "similar_content"



            reason = f"{intersection} common items, {round(similarity * 100, 1)}% similarity"



            recommendations.append(VersionRecommendation(



                version_id=vid,



                similarity=round(similarity, 3),



                recommendation_type=rec_type,



                reason=reason



            ))







        if recommendation_type in ["all", "activity"] and activity_sim > 0.3:



            rec_type = "activity_based"



            reason = f"Similar activity level (score: {round(activity_sim * 100, 1)}%)"



            recommendations.append(VersionRecommendation(



                version_id=vid,



                similarity=round(activity_sim, 3),



                recommendation_type=rec_type,



                reason=reason



            ))







    # Sort by similarity and limit



    if recommendation_type == "all":



        recommendations.sort(key=lambda x: x.similarity, reverse=True)



    else:



        recommendations = [r for r in recommendations if r.recommendation_type == recommendation_type]



        recommendations.sort(key=lambda x: x.similarity, reverse=True)







    return VersionRecommendationResponse(



        source_version=version_id,



        recommendations=recommendations[:limit],



        timestamp=_now_iso()



    )











