# Version Comparison Report



class VersionComparisonReportItem(BaseModel):



    """Comparison for a single version."""



    version_id: str



    metrics: dict[str, int]  # entities, relations, tags, activity



    score: float | None











class VersionComparisonReport(BaseModel):



    """Comparison report for multiple versions."""



    versions: list[VersionComparisonReportItem]



    comparison_type: str  # metrics, growth, quality



    summary: dict[str, str]



    insights: list[str]



    timestamp: str











@router.get("/versions/compare/report", response_model=VersionComparisonReport)



async def get_version_comparison_report(



    versions: str = Query(..., description="Comma-separated version IDs"),



    comparison_type: str = Query("metrics", description="metrics, growth, quality"),



) -> VersionComparisonReport:



    """Generate comparison report for versions."""



    global _versions







    version_ids = [v.strip() for v in versions.split(",")]



    version_ids = [v for v in version_ids if v in _versions]







    if not version_ids:



        return VersionComparisonReport(



            versions=[],



            comparison_type=comparison_type,



            summary={},



            insights=[],



            timestamp=_now_iso()



        )







    # Collect metrics



    report_items = []



    metrics_data = {}







    for vid in version_ids:



        v = _versions[vid]



        entities = v.get("entities", [])



        relations = v.get("relations", [])



        tags = v.get("tags", [])



        activity = v.get("activity", {}).get("edit_count", 0)







        metrics = {



            "entities": len(entities),



            "relations": len(relations),



            "tags": len(tags),



            "activity": activity



        }



        metrics_data[vid] = metrics







        # Calculate quality score if needed



        score = None



        if comparison_type == "quality":



            qs = _calculate_quality_score(vid, v)



            score = qs.overall_score







        report_items.append(VersionComparisonReportItem(



            version_id=vid,



            metrics=metrics,



            score=score



        ))







    # Generate summary



    summary = {}



    insights = []







    if comparison_type == "metrics":



        # Find max/min



        entity_counts = [(vid, m["entities"]) for vid, m in metrics_data.items()]



        max_entity = max(entity_counts, key=lambda x: x[1])



        min_entity = min(entity_counts, key=lambda x: x[1])



        summary["most_entities"] = f"{max_entity[0]} ({max_entity[1]})"



        summary["least_entities"] = f"{min_entity[0]} ({min_entity[1]})"



        insights.append(f"Entity count range: {min_entity[1]} to {max_entity[1]}")







    elif comparison_type == "growth":



        # Calculate growth



        sorted_v = sorted(version_ids, key=lambda x: _versions[x].get("timestamp", ""))



        growth_rates = []



        for i in range(1, len(sorted_v)):



            prev = len(_versions[sorted_v[i-1]].get("entities", []))



            curr = len(_versions[sorted_v[i]].get("entities", []))



            growth = ((curr - prev) / max(prev, 1)) * 100 if prev > 0 else 0



            growth_rates.append((sorted_v[i], round(growth, 1)))







        if growth_rates:



            max_growth = max(growth_rates, key=lambda x: x[1])



            summary["highest_growth"] = f"{max_growth[0]} (+{max_growth[1]}%)"



            insights.append(f"Highest growth: {max_growth[0]} at +{max_growth[1]}%")







    elif comparison_type == "quality" and any(item.score for item in report_items):



        scores = [(item.version_id, item.score) for item in report_items if item.score]



        if scores:



            max_score = max(scores, key=lambda x: x[1])



            min_score = min(scores, key=lambda x: x[1])



            summary["highest_quality"] = f"{max_score[0]} ({max_score[1]:.1f})"



            summary["lowest_quality"] = f"{min_score[0]} ({min_score[1]:.1f})"



            insights.append(f"Quality score range: {min_score[1]:.1f} to {max_score[1]:.1f}")







    return VersionComparisonReport(



        versions=report_items,



        comparison_type=comparison_type,



        summary=summary,



        insights=insights,



        timestamp=_now_iso()



    )











# Version Trend Prediction



class TrendPrediction(BaseModel):



    """Predicted trend for a metric."""



    metric: str



    current_value: float



    predicted_value: float



    trend: str  # increasing, decreasing, stable



    confidence: float











class VersionTrendPredictionResponse(BaseModel):



    """Response for trend predictions."""



    predictions: list[TrendPrediction]



    forecast_period: str  # 7d, 30d, 90d



    timestamp: str











@router.get("/versions/trend/prediction", response_model=VersionTrendPredictionResponse)



async def predict_version_trends(



    metric: str = Query("entities", description="Metric to predict: entities, relations, activity"),



    period: str = Query("30d", description="Forecast period: 7d, 30d, 90d"),



) -> VersionTrendPredictionResponse:



    """Predict future trends based on historical data."""



    global _versions







    if not _versions or len(_versions) < 3:



        return VersionTrendPredictionResponse(



            predictions=[],



            forecast_period=period,



            timestamp=_now_iso()



        )







    # Collect historical data



    sorted_versions = sorted(_versions.items(), key=lambda x: x[1].get("timestamp", ""))



    values = []







    for vid, v in sorted_versions:



        if metric == "entities":



            values.append(len(v.get("entities", [])))



        elif metric == "relations":



            values.append(len(v.get("relations", [])))



        elif metric == "tags":



            values.append(len(v.get("tags", [])))



        elif metric == "activity":



            values.append(v.get("activity", {}).get("edit_count", 0))



        else:



            values.append(0)







    if len(values) < 3:



        return VersionTrendPredictionResponse(



            predictions=[],



            forecast_period=period,



            timestamp=_now_iso()



        )







    # Simple linear regression



    n = len(values)



    x_mean = sum(range(n)) / n



    y_mean = sum(values) / n







    numerator = sum((i - x_mean) * (values[i] - y_mean) for i in range(n))



    denominator = sum((i - x_mean) ** 2 for i in range(n))







    if denominator == 0:



        slope = 0



    else:



        slope = numerator / denominator







    intercept = y_mean - slope * x_mean







    # Predict future



    periods = {"7d": 7, "30d": 30, "90d": 90}



    forecast_days = periods.get(period, 30)



    future_x = n + forecast_days / 30 * n  # Scale to historical length







    predicted_value = slope * future_x + intercept



    predicted_value = max(0, predicted_value)  # Can't be negative







    # Determine trend



    if slope > 0.5:



        trend = "increasing"



    elif slope < -0.5:



        trend = "decreasing"



    else:



        trend = "stable"







    # Confidence based on data fit



    y_pred = [slope * i + intercept for i in range(n)]



    ss_res = sum((values[i] - y_pred[i]) ** 2 for i in range(n))



    ss_tot = sum((values[i] - y_mean) ** 2 for i in range(n))



    r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0



    confidence = max(0, min(1, r_squared))







    prediction = TrendPrediction(



        metric=metric,



        current_value=round(y_mean, 2),



        predicted_value=round(predicted_value, 2),



        trend=trend,



        confidence=round(confidence, 2)



    )







    return VersionTrendPredictionResponse(



        predictions=[prediction],



        forecast_period=period,



        timestamp=_now_iso()



    )











