# Version Clustering



class VersionCluster(BaseModel):



    """Cluster of similar versions."""



    cluster_id: int



    versions: list[str]



    centroid: dict[str, float]  # Average metrics



    size: int











class VersionClusteringResponse(BaseModel):



    """Response for version clustering."""



    clusters: list[VersionCluster]



    total_clusters: int



    algorithm: str  # kmeans, hierarchical



    timestamp: str











def _calculate_version_vector(version_data: dict) -> list[float]:



    """Convert version to numerical vector for clustering."""



    entities = version_data.get("entities", [])



    relations = version_data.get("relations", [])



    tags = version_data.get("tags", [])



    activity = version_data.get("activity", {})







    # Normalized vector: [entity_count, relation_count, tag_count, activity_score]



    entity_norm = min(len(entities) / 100, 1.0)



    relation_norm = min(len(relations) / 100, 1.0)



    tag_norm = min(len(tags) / 50, 1.0)



    activity_norm = min(activity.get("edit_count", 0) / 50, 1.0)







    return [entity_norm, relation_norm, tag_norm, activity_norm]











def _kmeans_cluster(vectors: list[list[float]], k: int, max_iter: int = 20) -> list[list[int]]:



    """Simple k-means clustering."""



    n = len(vectors)



    if n < k:



        k = n



    if n == 0:



        return []







    # Initialize centroids (first k vectors)



    centroids = vectors[:k] if k > 0 else []



    assignments = [0] * n







    for _ in range(max_iter):



        # Assign to nearest centroid



        new_assignments = []



        for v in vectors:



            if not centroids:



                new_assignments.append(0)



                continue



            distances = [sum((v[i] - c[i]) ** 2 for i in range(len(v))) for c in centroids]



            new_assignments.append(distances.index(min(distances)))







        # Check convergence



        if new_assignments == assignments:



            break



        assignments = new_assignments







        # Update centroids



        for i in range(k):



            cluster_vectors = [vectors[j] for j in range(n) if assignments[j] == i]



            if cluster_vectors and vectors[0]:



                num_dims = len(vectors[0])



                new_centroid = []



                for dim in range(num_dims):



                    dim_values = [cv[dim] for cv in cluster_vectors if dim < len(cv)]



                    if dim_values:



                        new_centroid.append(sum(dim_values) / len(dim_values))



                    else:



                        new_centroid.append(0)



                centroids[i] = new_centroid







    return [[j for j in range(n) if assignments[j] == i] for i in range(k)]











@router.get("/versions/ml/clustering", response_model=VersionClusteringResponse)



async def get_version_clustering(



    k: int = Query(3, ge=2, le=10, description="Number of clusters"),



    algorithm: str = Query("kmeans", description="Clustering algorithm"),



) -> VersionClusteringResponse:



    """Cluster versions based on similarity."""



    global _versions







    if not _versions or len(_versions) < 2:



        return VersionClusteringResponse(



            clusters=[],



            total_clusters=0,



            algorithm=algorithm,



            timestamp=_now_iso()



        )







    # Build vectors



    version_vectors = {}



    for vid, v in _versions.items():



        version_vectors[vid] = _calculate_version_vector(v)







    ids = list(version_vectors.keys())



    vectors = [version_vectors[vid] for vid in ids]







    # Perform clustering



    cluster_indices = _kmeans_cluster(vectors, k)







    # Build response



    clusters = []



    for i, indices in enumerate(cluster_indices):



        if not indices:



            continue







        version_ids = [ids[idx] for idx in indices]







        # Calculate centroid



        centroid = {}



        if vectors and len(vectors[0]) >= 4:



            centroid = {



                "entities": sum(vectors[idx][0] for idx in indices) / len(indices),



                "relations": sum(vectors[idx][1] for idx in indices) / len(indices),



                "tags": sum(vectors[idx][2] for idx in indices) / len(indices),



                "activity": sum(vectors[idx][3] for idx in indices) / len(indices),



            }







        clusters.append(VersionCluster(



            cluster_id=i,



            versions=version_ids,



            centroid=centroid,



            size=len(version_ids)



        ))







    return VersionClusteringResponse(



        clusters=clusters,



        total_clusters=len(clusters),



        algorithm=algorithm,



        timestamp=_now_iso()



    )











# Version Forecasting (Advanced)



class VersionForecast(BaseModel):



    """Forecast for a version metric."""



    metric: str



    forecast: list[dict]  # [{period, value, lower, upper}]



    trend: str



    seasonality: str  # none, detected



    timestamp: str











@router.get("/versions/ml/forecast", response_model=VersionForecast)



async def get_version_forecast(



    metric: str = Query("entities", description="Metric to forecast"),



    periods: int = Query(5, ge=1, le=20, description="Number of periods"),



) -> VersionForecast:



    """Advanced forecasting with confidence intervals."""



    global _versions







    if not _versions or len(_versions) < 3:



        return VersionForecast(



            metric=metric,



            forecast=[],



            trend="unknown",



            seasonality="none",



            timestamp=_now_iso()



        )







    # Collect historical data



    sorted_versions = sorted(_versions.items(), key=lambda x: x[1].get("timestamp", ""))



    values = []







    for vid, v in sorted_versions:



        if metric == "entities":



            values.append(len(v.get("entities", [])))



        elif metric == "relations":



            values.append(len(v.get("relations", [])))



        elif metric == "tags":



            values.append(len(v.get("tags", [])))



        elif metric == "activity":



            values.append(v.get("activity", {}).get("edit_count", 0))



        else:



            values.append(0)







    if len(values) < 3:



        return VersionForecast(



            metric=metric,



            forecast=[],



            trend="unknown",



            seasonality="none",



            timestamp=_now_iso()



        )







    # Calculate trend



    n = len(values)



    x_mean = sum(range(n)) / n



    y_mean = sum(values) / n







    numerator = sum((i - x_mean) * (values[i] - y_mean) for i in range(n))



    denominator = sum((i - x_mean) ** 2 for i in range(n))



    slope = numerator / denominator if denominator != 0 else 0







    # Simple linear regression



    intercept = y_mean - slope * x_mean







    # Detect seasonality (simplified: check if values repeat pattern)



    seasonality = "none"



    if n >= 6:



        first_half = values[:n//2]



        second_half = values[n//2:]



        if abs(statistics.mean(first_half) - statistics.mean(second_half)) < statistics.stdev(values) * 0.3:



            seasonality = "stable"







    # Build forecast



    forecast = []



    for i in range(1, periods + 1):



        future_x = n + i



        predicted = slope * future_x + intercept



        predicted = max(0, predicted)







        # Confidence interval (widens with time)



        std_err = statistics.stdev(values) if len(values) > 1 else 0



        margin = std_err * (1 + i * 0.1)







        forecast.append({



            "period": f"+{i}",



            "value": round(predicted, 2),



            "lower": round(max(0, predicted - margin), 2),



            "upper": round(predicted + margin, 2),



        })







    # Determine trend



    if slope > 0.5:



        trend = "increasing"



    elif slope < -0.5:



        trend = "decreasing"



    else:



        trend = "stable"







    return VersionForecast(



        metric=metric,



        forecast=forecast,



        trend=trend,



        seasonality=seasonality,



        timestamp=_now_iso()



    )











# Anomaly Prediction



class AnomalyPrediction(BaseModel):



    """Predicted anomaly."""



    version_id: str



    anomaly_type: str



    probability: float  # 0-1



    severity: str



    expected_occurrence: str











class AnomalyPredictionResponse(BaseModel):



    """Response for anomaly predictions."""



    predictions: list[AnomalyPrediction]



    risk_score: float  # Overall risk 0-1



    recommendations: list[str]



    timestamp: str











@router.get("/versions/ml/anomaly-prediction", response_model=AnomalyPredictionResponse)



async def predict_anomalies() -> AnomalyPredictionResponse:



    """Predict future anomalies based on historical patterns."""



    global _versions







    if not _versions or len(_versions) < 3:



        return AnomalyPredictionResponse(



            predictions=[],



            risk_score=0.0,



            recommendations=[],



            timestamp=_now_iso()



        )







    # Collect historical data



    entity_counts = [len(v.get("entities", [])) for v in _versions.values()]



    relation_counts = [len(v.get("relations", [])) for v in _versions.values()]



    activity_scores = [v.get("activity", {}).get("edit_count", 0) for v in _versions.values()]







    # Calculate statistics



    mean_entities = statistics.mean(entity_counts)



    std_entities = statistics.stdev(entity_counts) if len(entity_counts) > 1 else 0



    mean_relations = statistics.mean(relation_counts)



    std_relations = statistics.stdev(relation_counts) if len(relation_counts) > 1 else 0



    mean_activity = statistics.mean(activity_scores)







    predictions = []



    recommendations = []







    # Check for potential anomalies



    most_recent = sorted(_versions.items(), key=lambda x: x[1].get("timestamp", ""), reverse=True)



    if most_recent:



        latest = most_recent[0][1]



        latest_entities = len(latest.get("entities", []))



        latest_relations = len(latest.get("relations", []))



        latest_activity = latest.get("activity", {}).get("edit_count", 0)







        # Entity drop prediction



        if std_entities > 0 and latest_entities < mean_entities - 1.5 * std_entities:



            prob = min(1.0, abs(latest_entities - mean_entities) / std_entities / 3)



            predictions.append(AnomalyPrediction(



                version_id=most_recent[0][0],



                anomaly_type="entity_drop",



                probability=round(prob, 2),



                severity="high" if prob > 0.7 else "medium" if prob > 0.4 else "low",



                expected_occurrence="next_version"



            ))



            recommendations.append("Monitor entity count in next version - risk of drop detected")







        # Relation anomaly prediction



        if latest_entities > 10 and latest_relations == 0:



            predictions.append(AnomalyPrediction(



                version_id=most_recent[0][0],



                anomaly_type="missing_relations",



                probability=0.8,



                severity="high",



                expected_occurrence="current"



            ))



            recommendations.append("Current version has entities but no relations - add connections")







        # Activity prediction



        if mean_activity > 0 and latest_activity < mean_activity * 0.3:



            prob = min(1.0, 1 - (latest_activity / mean_activity))



            predictions.append(AnomalyPrediction(



                version_id=most_recent[0][0],



                anomaly_type="low_activity",



                probability=round(prob, 2),



                severity="medium",



                expected_occurrence="next_version"



            ))



            recommendations.append("Low activity predicted for next version")







    # Calculate overall risk score



    if predictions:



        risk_score = max(p.probability for p in predictions)



    else:



        risk_score = 0.0







    # Generic recommendations if none specific



    if not recommendations:



        if mean_entities < 10:



            recommendations.append("Consider adding more entities to improve data richness")



        if mean_relations < mean_entities * 0.5:



            recommendations.append("Increase relation density for better connectivity")



        recommendations.append("Maintain consistent version updates for better prediction accuracy")







    return AnomalyPredictionResponse(



        predictions=predictions,



        risk_score=round(risk_score, 2),



        recommendations=recommendations,



        timestamp=_now_iso()



    )











# Version Similarity Graph



class VersionSimilarityEdge(BaseModel):



    """Edge in similarity graph."""



    version_a: str



    version_b: str



    similarity: float











class VersionSimilarityGraph(BaseModel):



    """Graph of version similarities."""



    nodes: list[str]



    edges: list[VersionSimilarityEdge]



    timestamp: str











@router.get("/versions/ml/similarity-graph", response_model=VersionSimilarityGraph)



async def get_similarity_graph(



    threshold: float = Query(0.1, ge=0, le=1, description="Minimum similarity threshold"),



) -> VersionSimilarityGraph:



    """Get version similarity network graph."""



    global _versions







    if not _versions:



        return VersionSimilarityGraph(



            nodes=[],



            edges=[],



            timestamp=_now_iso()



        )







    # Build vectors



    version_vectors = {}



    for vid, v in _versions.items():



        version_vectors[vid] = set()



        for e in v.get("entities", []):



            version_vectors[vid].add(e.get("id", ""))



        for r in v.get("relations", []):



            version_vectors[vid].add(r.get("id", ""))



        for t in v.get("tags", []):



            version_vectors[vid].add(t.get("id", ""))







    nodes = list(_versions.keys())



    edges = []







    # Calculate similarities



    for i, vid_a in enumerate(nodes):



        for vid_b in nodes[i+1:]:



            set_a = version_vectors.get(vid_a, set())



            set_b = version_vectors.get(vid_b, set())







            if not set_a or not set_b:



                continue







            intersection = len(set_a & set_b)



            union = len(set_a | set_b)



            similarity = intersection / union if union > 0 else 0.0







            if similarity >= threshold:



                edges.append(VersionSimilarityEdge(



                    version_a=vid_a,



                    version_b=vid_b,



                    similarity=round(similarity, 3)



                ))







    return VersionSimilarityGraph(



        nodes=nodes,



        edges=edges,



        timestamp=_now_iso()



    )











