class VersionVisualizationStream(BaseModel):



    """Stream of visualization data points."""



    points: list[VisualizationStreamPoint]



    total: int



    has_more: bool











@router.get("/versions/visualization/stream", response_model=VersionVisualizationStream)



async def get_visualization_stream(



    metric: str = Query("changes", description="Metric to stream: changes|quality|size|health"),



    limit: int = Query(50, ge=1, le=200, description="Maximum points to return"),



    offset: int = Query(0, ge=0, description="Offset for pagination"),



) -> VersionVisualizationStream:



    """Get real-time visualization stream data for version analytics."""



    global _versions







    if not _versions:



        return VersionVisualizationStream(



            points=[],



            total=0,



            has_more=False



        )







    points = []



    version_ids = sorted(_versions.keys(), reverse=True)







    for i, vid in enumerate(version_ids[offset:offset + limit]):



        v = _versions[vid]



        if metric == "changes":



            value = len(v.get("entities", [])) + len(v.get("relations", []))



        elif metric == "quality":



            value = v.get("quality_score", 0.0) or 75.0



        elif metric == "size":



            value = v.get("size_bytes", 0) / 1024 / 1024



        else:



            value = v.get("health_score", 0.0) or 80.0







        points.append(VisualizationStreamPoint(



            version_id=vid,



            timestamp=v.get("created_at", _now_iso()),



            metric=metric,



            value=value,



            category=v.get("status", "active")



        ))







    return VersionVisualizationStream(



        points=points,



        total=len(_versions),



        has_more=offset + limit < len(_versions)



    )











