class InteractiveTimeline(BaseModel):



    """Interactive timeline view."""



    markers: list[TimelineMarker]



    scale: str



    range_start: str



    range_end: str



    zoom_level: float











@router.get("/versions/visualization/timeline", response_model=InteractiveTimeline)



async def get_visualization_timeline(



    scale: str = Query("auto", description="Time scale: auto|day|week|month|year"),



    zoom: float = Query(1.0, ge=0.1, le=10.0, description="Zoom level"),



) -> InteractiveTimeline:



    """Get interactive timeline with version markers."""



    global _versions







    if not _versions:



        return InteractiveTimeline(



            markers=[],



            scale=scale,



            range_start=_now_iso(),



            range_end=_now_iso(),



            zoom_level=zoom



        )







    markers = []



    positions = sorted(_versions.items(), key=lambda x: x[1].get("created_at", ""), reverse=False)







    for i, (vid, v) in enumerate(positions):



        pos = i / max(len(positions) - 1, 1) if len(positions) > 1 else 0.5







        # Determine marker type based on version status



        status = v.get("status", "active")



        if status == "deprecated":



            marker_type = "deprecated"



        elif status == "archived":



            marker_type = "archived"



        else:



            marker_type = "active"







        markers.append(TimelineMarker(



            version_id=vid,



            position=pos,



            label=v.get("name", vid),



            type=marker_type,



            metadata={



                "entities": len(v.get("entities", [])),



                "quality": v.get("quality_score", 0.0) or 75.0,



                "health": v.get("health_score", 0.0) or 80.0



            }



        ))







    # Get date range



    dates = [v.get("created_at", "") for v in _versions.values() if v.get("created_at")]



    range_start = min(dates) if dates else _now_iso()



    range_end = max(dates) if dates else _now_iso()







    return InteractiveTimeline(



        markers=markers,



        scale=scale,



        range_start=range_start,



        range_end=range_end,



        zoom_level=zoom



    )











class ComparisonDimension(BaseModel):



    """Single dimension in dynamic comparison."""



    metric: str



    values: dict



    trend: str











class DynamicComparison(BaseModel):



    """Dynamic version comparison."""



    versions: list[str]



    dimensions: list[ComparisonDimension]



    similarity_scores: dict



    ranking: list[dict]











@router.get("/versions/visualization/comparison", response_model=DynamicComparison)



async def get_visualization_comparison(



    version_ids: str = Query("", description="Comma-separated version IDs (empty = all)"),



    dimensions: str = Query("changes,quality,health,size", description="Comma-separated dimensions"),



) -> DynamicComparison:



    """Get dynamic comparison across multiple versions."""



    global _versions







    if not _versions:



        return DynamicComparison(



            versions=[],



            dimensions=[],



            similarity_scores={},



            ranking=[]



        )







    # Select versions



    if version_ids:



        selected = [v.strip() for v in version_ids.split(",") if v.strip() in _versions]



    else:



        selected = list(_versions.keys())[:10]  # Limit to 10







    # Parse dimensions



    dim_list = [d.strip() for d in dimensions.split(",") if d.strip()]







    comparison_dims = []



    for dim in dim_list:



        values = {}



        for vid in selected:



            v = _versions[vid]



            if dim == "changes":



                values[vid] = len(v.get("entities", [])) + len(v.get("relations", []))



            elif dim == "quality":



                values[vid] = v.get("quality_score", 0.0) or 75.0



            elif dim == "health":



                values[vid] = v.get("health_score", 0.0) or 80.0



            elif dim == "size":



                values[vid] = v.get("size_bytes", 0) / 1024 / 1024



            else:



                values[vid] = 0







        # Determine trend



        sorted_v = sorted(values.items(), key=lambda x: x[1], reverse=True)



        if sorted_v[0][1] > sorted_v[-1][1]:



            trend = "increasing"



        elif sorted_v[0][1] < sorted_v[-1][1]:



            trend = "decreasing"



        else:



            trend = "stable"







        comparison_dims.append(ComparisonDimension(



            metric=dim,



            values=values,



            trend=trend



        ))







    # Calculate similarity scores (simple correlation)



    similarity_scores = {}



    for i, vid_a in enumerate(selected):



        for vid_b in selected[i+1:]:



            score = 0.0



            count = 0



            for dim in comparison_dims:



                if vid_a in dim.values and vid_b in dim.values:



                    diff = abs(dim.values[vid_a] - dim.values[vid_b])



                    score += 1 / (1 + diff)



                    count += 1



            similarity_scores[f"{vid_a}:{vid_b}"] = round(score / max(count, 1), 3)







    # Ranking based on combined score



    ranking = []



    for vid in selected:



        v = _versions[vid]



        score = (



            (v.get("quality_score", 0.0) or 75.0) * 0.4 +



            (v.get("health_score", 0.0) or 80.0) * 0.4 +



            min(len(v.get("entities", [])), 100) * 0.2



        )



        ranking.append({



            "version_id": vid,



            "score": round(score, 2),



            "rank": 0



        })







    ranking.sort(key=lambda x: x["score"], reverse=True)



    for i, r in enumerate(ranking):



        r["rank"] = i + 1







    return DynamicComparison(



        versions=selected,



        dimensions=comparison_dims,



        similarity_scores=similarity_scores,



        ranking=ranking



    )











