class SceneObject(BaseModel):



    """3D scene object."""



    id: str



    type: str



    position: dict



    rotation: dict



    scale: dict



    color: str



    metadata: dict











class CameraConfig(BaseModel):



    """3D camera configuration."""



    position: dict



    target: dict



    fov: float



    near: float



    far: float











class Scene3D(BaseModel):



    """3D visualization scene."""



    objects: list[SceneObject]



    camera: CameraConfig



    background: str



    lighting: dict



    timestamp: str











@router.get("/versions/visualization/3d", response_model=Scene3D)



async def get_visualization_3d(



    mode: str = Query("network", description="3D mode: network|timeline|scatter"),



    rotation: float = Query(0, ge=0, le=360, description="Auto-rotation angle"),



) -> Scene3D:



    """Get 3D visualization scene with version objects."""



    global _versions







    if not _versions:



        return Scene3D(



            objects=[],



            camera=CameraConfig(



                position={"x": 0, "y": 0, "z": 10},



                target={"x": 0, "y": 0, "z": 0},



                fov=60,



                near=0.1,



                far=1000



            ),



            background="#0a0a0a",



            lighting={"ambient": 0.5, "directional": 0.8},



            timestamp=_now_iso()



        )







    objects = []



    version_ids = sorted(_versions.keys(), reverse=False)



    version_count = len(version_ids)







    for i, vid in enumerate(version_ids):



        v = _versions[vid]



        entities = len(v.get("entities", []))



        quality = v.get("quality_score", 0.0) or 75.0



        health = v.get("health_score", 0.0) or 80.0



        status = v.get("status", "active")







        # Calculate position based on mode



        if mode == "network":



            angle = (i / max(version_count - 1, 1)) * 2 * 3.14159



            radius = 3 + entities * 0.1



            pos_x = radius * (1 if i % 2 == 0 else -1) * abs(1 - i / max(version_count, 1))



            pos_y = (i / max(version_count - 1, 1) - 0.5) * 6



            position = {"x": pos_x, "y": pos_y, "z": entities * 0.1}



        elif mode == "timeline":



            position = {"x": (i / max(version_count - 1, 1) - 0.5) * 10, "y": quality / 20 - 3, "z": health / 20 - 3}



        else:  # scatter



            position = {"x": entities - 5, "y": quality - 50, "z": health - 50}







        # Color based on status



        if status == "deprecated":



            color = "#ef4444"  # red



        elif status == "archived":



            color = "#eab308"  # yellow



        elif quality >= 90:



            color = "#22c55e"  # green



        elif quality >= 75:



            color = "#3b82f6"  # blue



        else:



            color = "#a855f7"  # purple







        # Scale based on entity count



        scale = {"x": 0.3 + entities * 0.02, "y": 0.3 + entities * 0.02, "z": 0.3 + entities * 0.02}







        objects.append(SceneObject(



            id=vid,



            type="box",



            position=position,



            rotation={"x": 0, "y": rotation, "z": 0},



            scale=scale,



            color=color,



            metadata={



                "version": vid,



                "entities": entities,



                "quality": quality,



                "health": health,



                "status": status



            }



        ))







    return Scene3D(



        objects=objects,



        camera=CameraConfig(



            position={"x": 0, "y": 0, "z": 15 if mode == "network" else 20},



            target={"x": 0, "y": 0, "z": 0},



            fov=60,



            near=0.1,



            far=1000



        ),



        background="#09090b",



        lighting={"ambient": 0.5, "directional": 0.8},



        timestamp=_now_iso()



    )











