# Scheduled Reports (v1.42)



# =============================================================================







class ReportSchedule(BaseModel):



    """Report schedule configuration."""



    schedule_id: str



    name: str



    report_type: str  # summary|detailed|对比|compliance



    frequency: str  # daily|weekly|monthly|quarterly



    recipients: list[str]



    format: str  # pdf|html|json



    filters: dict



    enabled: bool



    last_run: str | None



    next_run: str



    created_at: str











class CreateScheduleRequest(BaseModel):



    """Request to create report schedule."""



    name: str



    report_type: str



    frequency: str



    recipients: list[str]



    format: str



    filters: dict











class ReportRun(BaseModel):



    """Report generation run."""



    run_id: str



    schedule_id: str



    status: str  # pending|running|completed|failed



    started_at: str | None



    completed_at: str | None



    output_url: str | None



    error: str | None











# In-memory store for report schedules



_report_schedules: dict[str, dict] = {}



_report_runs: dict[str, dict] = {}











@router.post("/reports/schedule", response_model=ReportSchedule)



async def create_report_schedule(req: CreateScheduleRequest) -> ReportSchedule:



    """Create a scheduled report."""



    import uuid



    from datetime import datetime, timedelta







    schedule_id = f"report_{uuid.uuid4().hex[:8]}"







    # Calculate next run time based on frequency



    now = datetime.now()



    if req.frequency == "daily":



        next_run = now + timedelta(days=1)



    elif req.frequency == "weekly":



        next_run = now + timedelta(weeks=1)



    elif req.frequency == "monthly":



        next_run = now + timedelta(days=30)



    else:  # quarterly



        next_run = now + timedelta(days=90)







    schedule = ReportSchedule(



        schedule_id=schedule_id,



        name=req.name,



        report_type=req.report_type,



        frequency=req.frequency,



        recipients=req.recipients,



        format=req.format,



        filters=req.filters,



        enabled=True,



        last_run=None,



        next_run=next_run.isoformat(),



        created_at=_now_iso()



    )







    _report_schedules[schedule_id] = schedule.model_dump()



    return schedule











@router.get("/reports/schedule", response_model=list[ReportSchedule])



async def list_report_schedules() -> list[ReportSchedule]:



    """List all report schedules."""



    return [ReportSchedule(**s) for s in _report_schedules.values()]











@router.get("/reports/schedule/{schedule_id}", response_model=ReportSchedule)



async def get_report_schedule(schedule_id: str) -> ReportSchedule:



    """Get a specific report schedule."""



    if schedule_id not in _report_schedules:



        return ReportSchedule(



            schedule_id=schedule_id,



            name="Not Found",



            report_type="summary",



            frequency="daily",



            recipients=[],



            format="pdf",



            filters={},



            enabled=False,



            last_run=None,



            next_run=_now_iso(),



            created_at=_now_iso()



        )



    return ReportSchedule(**_report_schedules[schedule_id])











@router.post("/reports/schedule/{schedule_id}/run", response_model=ReportRun)



async def run_report_now(schedule_id: str) -> ReportRun:



    """Run a report schedule immediately."""



    import uuid







    if schedule_id not in _report_schedules:



        return ReportRun(



            run_id="",



            schedule_id=schedule_id,



            status="failed",



            started_at=None,



            completed_at=None,



            output_url=None,



            error="Schedule not found"



        )







    run_id = f"run_{uuid.uuid4().hex[:8]}"



    started_at = _now_iso()







    run = ReportRun(



        run_id=run_id,



        schedule_id=schedule_id,



        status="completed",  # Simulated - would actually generate report



        started_at=started_at,



        completed_at=_now_iso(),



        output_url=f"/api/reports/output/{run_id}",



        error=None



    )







    _report_runs[run_id] = run.model_dump()







    # Update last run time



    schedule = _report_schedules[schedule_id]



    schedule["last_run"] = started_at







    return run











@router.get("/reports/runs", response_model=list[ReportRun])



async def list_report_runs(



    schedule_id: str | None = None



) -> list[ReportRun]:



    """List report runs, optionally filtered by schedule."""



    runs = list(_report_runs.values())



    if schedule_id:



        runs = [r for r in runs if r["schedule_id"] == schedule_id]



    return [ReportRun(**r) for r in runs]











@router.delete("/reports/schedule/{schedule_id}")



async def delete_report_schedule(schedule_id: str) -> dict:



    """Delete a report schedule."""



    if schedule_id in _report_schedules:



        del _report_schedules[schedule_id]



        return {"status": "deleted", "schedule_id": schedule_id}



    return {"status": "not_found", "schedule_id": schedule_id}











@router.patch("/reports/schedule/{schedule_id}/toggle")



async def toggle_report_schedule(schedule_id: str) -> dict:



    """Enable or disable a report schedule."""



    if schedule_id in _report_schedules:



        schedule = _report_schedules[schedule_id]



        schedule["enabled"] = not schedule["enabled"]



        return {"status": "toggled", "enabled": schedule["enabled"]}



    return {"status": "not_found", "schedule_id": schedule_id}











