# Multi-user Permissions & RBAC (v1.43)



# =============================================================================







class User(BaseModel):



    """User definition."""



    user_id: str



    username: str



    email: str



    role: str  # admin|editor|viewer|custom



    permissions: list[str]



    api_keys: list[dict]



    created_at: str



    last_login: str | None



    status: str  # active|disabled











class CreateUserRequest(BaseModel):



    """Request to create a user."""



    username: str



    email: str



    role: str











class UpdateUserRequest(BaseModel):



    """Request to update a user."""



    role: str



    permissions: list[str]



    status: str











class ApiKeyRequest(BaseModel):



    """Request to create an API key."""



    name: str



    permissions: list[str]



    expires_in_days: int = 30











class Role(BaseModel):



    """Role definition."""



    role_id: str



    name: str



    description: str



    permissions: list[str]



    is_system: bool  # system roles cannot be deleted











class CreateRoleRequest(BaseModel):



    """Request to create a role."""



    name: str



    description: str



    permissions: list[str]











# In-memory stores



_users: dict[str, dict] = {}



_roles: dict[str, dict] = {}



_audit_logs: list[dict] = []







# Default system roles



_default_roles = {



    "admin": {



        "role_id": "admin",



        "name": "Administrator",



        "description": "Full system access",



        "permissions": ["*"],



        "is_system": True



    },



    "editor": {



        "role_id": "editor",



        "name": "Editor",



        "description": "Can edit and create",



        "permissions": ["create", "edit", "delete", "view"],



        "is_system": True



    },



    "viewer": {



        "role_id": "viewer",



        "name": "Viewer",



        "description": "View-only access",



        "permissions": ["view"],



        "is_system": True



    }



}







# Initialize default roles



for role_id, role_data in _default_roles.items():



    _roles[role_id] = role_data











def _log_audit(action: str, user_id: str, target: str, details: dict = None):



    """Log an audit event."""



    import uuid



    log_entry = {



        "log_id": f"log_{uuid.uuid4().hex[:8]}",



        "action": action,



        "user_id": user_id,



        "target": target,



        "details": details or {},



        "timestamp": _now_iso()



    }



    _audit_logs.append(log_entry)



    # Keep only last 1000 entries



    if len(_audit_logs) > 1000:



        _audit_logs.pop(0)











@router.post("/users", response_model=User)



async def create_user(req: CreateUserRequest, created_by: str = "system") -> User:



    """Create a new user."""



    import uuid







    user_id = f"user_{uuid.uuid4().hex[:8]}"







    # Get permissions from role



    role_data = _roles.get(req.role, _roles["viewer"])



    permissions = role_data.get("permissions", [])







    user = User(



        user_id=user_id,



        username=req.username,



        email=req.email,



        role=req.role,



        permissions=permissions,



        api_keys=[],



        created_at=_now_iso(),



        last_login=None,



        status="active"



    )







    _users[user_id] = user.model_dump()



    _log_audit("user.created", created_by, user_id, {"username": req.username, "role": req.role})



    return user











@router.get("/users", response_model=list[User])



async def list_users() -> list[User]:



    """List all users."""



    return [User(**u) for u in _users.values()]











@router.get("/users/{user_id}", response_model=User)



async def get_user(user_id: str) -> User:



    """Get a specific user."""



    if user_id not in _users:



        return User(



            user_id=user_id,



            username="Not Found",



            email="",



            role="viewer",



            permissions=[],



            api_keys=[],



            created_at=_now_iso(),



            last_login=None,



            status="disabled"



        )



    return User(**_users[user_id])











@router.patch("/users/{user_id}", response_model=User)



async def update_user(



    user_id: str,



    req: UpdateUserRequest,



    updated_by: str = "system"



) -> User:



    """Update a user."""



    if user_id in _users:



        user = _users[user_id]



        user["role"] = req.role



        user["permissions"] = req.permissions



        user["status"] = req.status







        _log_audit("user.updated", updated_by, user_id, {"role": req.role, "status": req.status})



        return User(**user)



    return User(



        user_id=user_id,



        username="Not Found",



        email="",



        role="viewer",



        permissions=[],



        api_keys=[],



        created_at=_now_iso(),



        last_login=None,



        status="disabled"



    )











@router.delete("/users/{user_id}")



async def delete_user(user_id: str, deleted_by: str = "system") -> dict:



    """Delete a user."""



    if user_id in _users:



        username = _users[user_id]["username"]



        del _users[user_id]



        _log_audit("user.deleted", deleted_by, user_id, {"username": username})



        return {"status": "deleted", "user_id": user_id}



    return {"status": "not_found", "user_id": user_id}











@router.post("/users/{user_id}/api-keys", response_model=dict)



async def create_api_key(



    user_id: str,



    req: ApiKeyRequest



) -> dict:



    """Create an API key for a user."""



    import uuid







    if user_id not in _users:



        return {"status": "not_found", "user_id": user_id}







    api_key = f"sk_{uuid.uuid4().hex[:16]}"



    api_key_id = f"key_{uuid.uuid4().hex[:8]}"







    key_entry = {



        "key_id": api_key_id,



        "name": req.name,



        "key": api_key,



        "permissions": req.permissions,



        "created_at": _now_iso(),



        "expires_in_days": req.expires_in_days



    }







    _users[user_id]["api_keys"].append(key_entry)



    _log_audit("api_key.created", user_id, api_key_id, {"name": req.name})







    return {



        "status": "created",



        "key_id": api_key_id,



        "api_key": api_key,  # Only returned once



        "name": req.name,



        "expires_in_days": req.expires_in_days



    }











@router.get("/users/{user_id}/api-keys", response_model=list[dict])



async def list_api_keys(user_id: str) -> list[dict]:



    """List API keys for a user (without the actual key values)."""



    if user_id not in _users:



        return []



    return [



        {



            "key_id": k["key_id"],



            "name": k["name"],



            "permissions": k["permissions"],



            "created_at": k["created_at"],



            "expires_in_days": k["expires_in_days"]



        }



        for k in _users[user_id]["api_keys"]



    ]











@router.delete("/users/{user_id}/api-keys/{key_id}")



async def delete_api_key(user_id: str, key_id: str) -> dict:



    """Delete an API key."""



    if user_id in _users:



        keys = _users[user_id]["api_keys"]



        _users[user_id]["api_keys"] = [k for k in keys if k["key_id"] != key_id]



        _log_audit("api_key.deleted", user_id, key_id)



        return {"status": "deleted", "key_id": key_id}



    return {"status": "not_found"}











@router.post("/users/{user_id}/login")



async def user_login(user_id: str) -> dict:



    """Record user login."""



    if user_id in _users:



        _users[user_id]["last_login"] = _now_iso()



        _log_audit("user.login", user_id, user_id)



        return {"status": "logged_in", "user_id": user_id}



    return {"status": "not_found"}











# Role management endpoints



@router.get("/roles", response_model=list[Role])



async def list_roles() -> list[Role]:



    """List all roles."""



    return [Role(**r) for r in _roles.values()]











@router.get("/roles/{role_id}", response_model=Role)



async def get_role(role_id: str) -> Role:



    """Get a specific role."""



    if role_id not in _roles:



        return Role(



            role_id=role_id,



            name="Not Found",



            description="",



            permissions=[],



            is_system=False



        )



    return Role(**_roles[role_id])











@router.post("/roles", response_model=Role)



async def create_role(req: CreateRoleRequest) -> Role:



    """Create a custom role."""



    import uuid







    role_id = f"role_{uuid.uuid4().hex[:8]}"







    role = Role(



        role_id=role_id,



        name=req.name,



        description=req.description,



        permissions=req.permissions,



        is_system=False



    )







    _roles[role_id] = role.model_dump()



    return role











@router.delete("/roles/{role_id}")



async def delete_role(role_id: str) -> dict:



    """Delete a custom role. Cannot delete system roles."""



    if role_id in _roles:



        role = _roles[role_id]



        if role.get("is_system"):



            return {"status": "cannot_delete_system_role", "role_id": role_id}



        del _roles[role_id]



        return {"status": "deleted", "role_id": role_id}



    return {"status": "not_found"}











