_audit_settings = {



    "retention_days": 90,



    "max_entries": 10000,



    "auto_archive": True



}











@router.post("/audit/logs/query", response_model=list[AuditLogEntry])



async def query_audit_logs(req: AuditLogQuery) -> list[AuditLogEntry]:



    """Query audit logs with filters."""



    results = _audit_logs







    if req.user_id:



        results = [l for l in results if l["user_id"] == req.user_id]



    if req.action:



        results = [l for l in results if l["action"] == req.action]



    if req.target:



        results = [l for l in results if req.target in l["target"]]







    # Apply date range



    if req.start_date:



        results = [l for l in results if l["timestamp"] >= req.start_date]



    if req.end_date:



        results = [l for l in results if l["timestamp"] <= req.end_date]







    # Limit results



    results = results[:req.limit]







    return [AuditLogEntry(**l) for l in results]











@router.get("/audit/logs/{log_id}", response_model=AuditLogEntry)



async def get_audit_log(log_id: str) -> AuditLogEntry:



    """Get a specific audit log entry."""



    for log in _audit_logs:



        if log["log_id"] == log_id:



            return AuditLogEntry(**log)



    return AuditLogEntry(



        log_id=log_id,



        action="",



        user_id="",



        target="",



        details={},



        timestamp=_now_iso()



    )











@router.get("/audit/stats", response_model=dict)



async def get_audit_stats() -> dict:



    """Get audit log statistics."""



    total = len(_audit_logs)







    # Count by action type



    action_counts = {}



    for log in _audit_logs:



        action = log["action"]



        action_counts[action] = action_counts.get(action, 0) + 1







    # Count by user



    user_counts = {}



    for log in _audit_logs:



        user = log["user_id"]



        user_counts[user] = user_counts.get(user, 0) + 1







    return {



        "total_entries": total,



        "by_action": action_counts,



        "by_user": user_counts,



        "retention_days": _audit_settings["retention_days"],



        "max_entries": _audit_settings["max_entries"]



    }











@router.post("/audit/export")



async def export_audit_logs(req: AuditExportRequest) -> dict:



    """Export audit logs in various formats."""



    results = _audit_logs







    # Apply filters



    if req.user_id:



        results = [l for l in results if l["user_id"] == req.user_id]



    if req.start_date:



        results = [l for l in results if l["timestamp"] >= req.start_date]



    if req.end_date:



        results = [l for l in results if l["timestamp"] <= req.end_date]







    if req.format == "csv":



        # Simple CSV format



        csv_lines = ["log_id,action,user_id,target,timestamp"]



        for log in results:



            csv_lines.append(f"{log['log_id']},{log['action']},{log['user_id']},{log['target']},{log['timestamp']}")



        return {



            "format": "csv",



            "data": "\n".join(csv_lines),



            "count": len(results)



        }



    elif req.format == "html":



        html = "<html><body><h1>Audit Logs</h1><table border='1'><tr><th>ID</th><th>Action</th><th>User</th><th>Target</th><th>Timestamp</th></tr>"



        for log in results:



            html += f"<tr><td>{log['log_id']}</td><td>{log['action']}</td><td>{log['user_id']}</td><td>{log['target']}</td><td>{log['timestamp']}</td></tr>"



        html += "</table></body></html>"



        return {



            "format": "html",



            "data": html,



            "count": len(results)



        }



    else:  # json



        return {



            "format": "json",



            "data": results,



            "count": len(results)



        }











@router.get("/audit/settings", response_model=AuditRetentionSettings)



async def get_audit_settings() -> AuditRetentionSettings:



    """Get audit retention settings."""



    return AuditRetentionSettings(**_audit_settings)











@router.post("/audit/settings")



async def update_audit_settings(req: AuditRetentionSettings) -> dict:



    """Update audit retention settings."""



    _audit_settings["retention_days"] = req.retention_days



    _audit_settings["max_entries"] = req.max_entries



    _audit_settings["auto_archive"] = req.auto_archive



    return {"status": "updated", "settings": _audit_settings}











@router.post("/audit/clear")



async def clear_audit_logs(before_date: str) -> dict:



    """Clear audit logs older than specified date."""



    global _audit_logs



    original_count = len(_audit_logs)



    _audit_logs = [l for l in _audit_logs if l["timestamp"] >= before_date]



    deleted = original_count - len(_audit_logs)



    return {"status": "cleared", "deleted_count": deleted, "remaining": len(_audit_logs)}











