@router.get("/analytics/metrics", response_model=list[AnalyticsMetric])



async def get_analytics_metrics(



    metric: str | None = None,



    limit: int = 10



) -> list[AnalyticsMetric]:



    """Get analytics metrics."""



    # Generate sample metrics



    import uuid







    metrics_list = [



        "total_entities", "total_relations", "avg_quality", "health_score",



        "active_users", "queries_today", "api_calls", "error_rate"



    ]







    results = []



    for m in (metrics_list if not metric else [metric]):



        value = float(hash(m) % 1000)



        results.append(AnalyticsMetric(



            metric_id=f"metric_{uuid.uuid4().hex[:8]}",



            value=value,



            label=m,



            change=float((hash(m) % 20) - 10),



            trend="up" if hash(m) % 2 == 0 else "down",



            timestamp=_now_iso()



        ))







    return results[:limit]











@router.post("/analytics/timeseries", response_model=list[TimeSeriesPoint])



async def get_time_series(req: AnalyticsQuery) -> list[TimeSeriesPoint]:



    """Get time series data for a metric."""



    # Generate sample time series



    import uuid



    from datetime import datetime, timedelta







    points = []



    granularity_map = {"hour": 1, "day": 24, "week": 168, "month": 720}



    hours = granularity_map.get(req.granularity, 24)







    for i in range(min(hours, 24)):



        timestamp = (datetime.now() - timedelta(hours=hours-i)).isoformat()



        value = float((hash(req.metric + str(i)) % 100))



        points.append(TimeSeriesPoint(



            timestamp=timestamp,



            value=value,



            label=req.metric



        ))







    return points











@router.get("/analytics/stats", response_model=dict)



async def get_analytics_stats() -> dict:



    """Get comprehensive analytics stats."""



    return {



        "dashboards": len(_analytics_dashboards),



        "metrics": 8,



        "cache_entries": sum(len(v) for v in _analytics_cache.values()),



        "timestamp": _now_iso()



    }











