# =============================================================================







class Notification(BaseModel):



    """Notification item."""



    notification_id: str



    type: str  # info|warning|error|success



    title: str



    message: str



    user_id: str



    read: bool



    priority: str  # low|medium|high



    action_url: str | None



    created_at: str











class NotificationPreferences(BaseModel):



    """Notification preferences."""



    user_id: str



    email_enabled: bool



    push_enabled: bool



    types: list[str]



    quiet_hours_start: str | None



    quiet_hours_end: str | None











class CreateNotificationRequest(BaseModel):



    """Request to create notification."""



    type: str



    title: str



    message: str



    user_id: str



    priority: str = "medium"



    action_url: str | None = None











# In-memory stores



_notifications: dict[str, list] = {}



_notification_preferences: dict[str, dict] = {}











@router.post("/notifications", response_model=Notification)



async def create_notification(req: CreateNotificationRequest) -> Notification:



    """Create a notification."""



    import uuid







    notification_id = f"notif_{uuid.uuid4().hex[:8]}"







    notification = Notification(



        notification_id=notification_id,



        type=req.type,



        title=req.title,



        message=req.message,



        user_id=req.user_id,



        read=False,



        priority=req.priority,



        action_url=req.action_url,



        created_at=_now_iso()



    )







    if req.user_id not in _notifications:



        _notifications[req.user_id] = []







    _notifications[req.user_id].append(notification.model_dump())



    return notification











@router.get("/notifications/{user_id}", response_model=list[Notification])



async def get_notifications(



    user_id: str,



    unread_only: bool = False



) -> list[Notification]:



    """Get notifications for a user."""



    user_notifs = _notifications.get(user_id, [])







    if unread_only:



        user_notifs = [n for n in user_notifs if not n.get("read", False)]







    return [Notification(**n) for n in user_notifs]











@router.post("/notifications/{notification_id}/read")



async def mark_notification_read(notification_id: str) -> dict:



    """Mark a notification as read."""



    for user_notifs in _notifications.values():



        for notif in user_notifs:



            if notif["notification_id"] == notification_id:



                notif["read"] = True



                return {"status": "marked_read"}







    return {"status": "not_found"}











@router.post("/notifications/{user_id}/read-all")



async def mark_all_read(user_id: str) -> dict:



    """Mark all notifications as read."""



    if user_id in _notifications:



        for notif in _notifications[user_id]:



            notif["read"] = True



        return {"status": "all_marked_read"}



    return {"status": "not_found"}











@router.delete("/notifications/{notification_id}")



async def delete_notification(notification_id: str) -> dict:



    """Delete a notification."""



    for user_notifs in _notifications.values():



        for i, notif in enumerate(user_notifs):



            if notif["notification_id"] == notification_id:



                user_notifs.pop(i)



                return {"status": "deleted"}







    return {"status": "not_found"}











@router.get("/notifications/{user_id}/count", response_model=dict)



async def get_notification_count(user_id: str) -> dict:



    """Get notification counts."""



    user_notifs = _notifications.get(user_id, [])



    total = len(user_notifs)



    unread = sum(1 for n in user_notifs if not n.get("read", False))







    return {



        "total": total,



        "unread": unread,



        "read": total - unread



    }











@router.post("/notifications/preferences", response_model=NotificationPreferences)



async def set_notification_preferences(req: NotificationPreferences) -> NotificationPreferences:



    """Set notification preferences."""



    _notification_preferences[req.user_id] = req.model_dump()



    return req











@router.get("/notifications/preferences/{user_id}", response_model=NotificationPreferences)



async def get_notification_preferences(user_id: str) -> NotificationPreferences:



    """Get notification preferences."""



    if user_id not in _notification_preferences:



        return NotificationPreferences(



            user_id=user_id,



            email_enabled=True,



            push_enabled=True,



            types=["info", "warning", "error", "success"],



            quiet_hours_start=None,



            quiet_hours_end=None



        )



    return NotificationPreferences(**_notification_preferences[user_id])











