async def create_workflow(req: CreateWorkflowRequest) -> Workflow:



    """Create a new workflow."""



    import uuid







    workflow_id = f"wf_{uuid.uuid4().hex[:8]}"







    workflow = Workflow(



        workflow_id=workflow_id,



        name=req.name,



        description=req.description,



        trigger=req.trigger,



        actions=req.actions,



        status="draft",



        run_count=0,



        last_run=None,



        created_at=_now_iso()



    )







    _workflows[workflow_id] = workflow.model_dump()



    return workflow











@router.get("/workflows", response_model=list[Workflow])



async def list_workflows() -> list[Workflow]:



    """List all workflows."""



    return [Workflow(**w) for w in _workflows.values()]











@router.get("/workflows/{workflow_id}", response_model=Workflow)



async def get_workflow(workflow_id: str) -> Workflow:



    """Get a specific workflow."""



    if workflow_id not in _workflows:



        return Workflow(



            workflow_id=workflow_id,



            name="Not Found",



            description="",



            trigger={},



            actions=[],



            status="draft",



            run_count=0,



            last_run=None,



            created_at=_now_iso()



        )



    return Workflow(**_workflows[workflow_id])











@router.post("/workflows/{workflow_id}/activate")



async def activate_workflow(workflow_id: str) -> dict:



    """Activate a workflow."""



    if workflow_id in _workflows:



        _workflows[workflow_id]["status"] = "active"



        _active_workflows[workflow_id] = True



        return {"status": "activated", "workflow_id": workflow_id}



    return {"status": "not_found"}











@router.post("/workflows/{workflow_id}/pause")



async def pause_workflow(workflow_id: str) -> dict:



    """Pause a workflow."""



    if workflow_id in _workflows:



        _workflows[workflow_id]["status"] = "paused"



        _active_workflows[workflow_id] = False



        return {"status": "paused", "workflow_id": workflow_id}



    return {"status": "not_found"}











@router.post("/workflows/{workflow_id}/run", response_model=WorkflowExecution)



async def run_workflow(workflow_id: str) -> WorkflowExecution:



    """Manually trigger a workflow."""



    import uuid







    if workflow_id not in _workflows:



        return WorkflowExecution(



            execution_id="",



            workflow_id=workflow_id,



            status="failed",



            trigger_event={},



            results=[],



            started_at=_now_iso(),



            completed_at=_now_iso()



        )







    execution_id = f"exec_{uuid.uuid4().hex[:8]}"



    workflow = _workflows[workflow_id]







    # Simulate execution



    execution = WorkflowExecution(



        execution_id=execution_id,



        workflow_id=workflow_id,



        status="completed",



        trigger_event={"manual": True},



        results=[{"action": a["name"], "status": "success"} for a in workflow.get("actions", [])],



        started_at=_now_iso(),



        completed_at=_now_iso()



    )







    _workflow_executions.append(execution.model_dump())



    workflow["run_count"] += 1



    workflow["last_run"] = _now_iso()







    return execution











@router.get("/workflows/{workflow_id}/executions", response_model=list[WorkflowExecution])



async def get_workflow_executions(workflow_id: str) -> list[WorkflowExecution]:



    """Get workflow execution history."""



    executions = [e for e in _workflow_executions if e["workflow_id"] == workflow_id]



    return [WorkflowExecution(**e) for e in executions]











@router.delete("/workflows/{workflow_id}")



async def delete_workflow(workflow_id: str) -> dict:



    """Delete a workflow."""



    if workflow_id in _workflows:



        del _workflows[workflow_id]



        if workflow_id in _active_workflows:



            del _active_workflows[workflow_id]



        return {"status": "deleted", "workflow_id": workflow_id}



    return {"status": "not_found"}











# =============================================================================



# API Rate Limiting (v1.45)



# =============================================================================







class RateLimitConfig(BaseModel):



    """Rate limit configuration."""



    endpoint: str



    requests_per_minute: int



    requests_per_hour: int



    burst_size: int



    enabled: bool











class RateLimitEntry(BaseModel):



    """Rate limit entry for tracking."""



    key: str  # user_id or API key



    endpoint: str



    minute_count: int



    hour_count: int



    minute_reset: str



    hour_reset: str











class RateLimitStats(BaseModel):



    """Rate limit statistics."""



    endpoint: str



    requests_current_minute: int



    requests_current_hour: int



    limit_minute: int



    limit_hour: int



    remaining_minute: int



    remaining_hour: int











# In-memory stores



_rate_limits: dict[str, dict] = {}



_rate_limit_configs: dict[str, dict] = {}



_request_counts: dict[str, list] = {}











# Default rate limits



_default_limits = {



    "default": {"requests_per_minute": 60, "requests_per_hour": 1000, "burst_size": 10},



    "/entities": {"requests_per_minute": 120, "requests_per_hour": 5000, "burst_size": 20},



    "/search": {"requests_per_minute": 30, "requests_per_hour": 500, "burst_size": 5},



}











@router.get("/rate-limits/config", response_model=list[RateLimitConfig])



async def get_rate_limit_configs() -> list[RateLimitConfig]:



    """Get rate limit configurations."""



    configs = []



    for endpoint, config in _default_limits.items():



        configs.append(RateLimitConfig(



            endpoint=endpoint,



            requests_per_minute=config["requests_per_minute"],



            requests_per_hour=config["requests_per_hour"],



            burst_size=config["burst_size"],



            enabled=True



        ))



    return configs











@router.post("/rate-limits/check")



async def check_rate_limit(



    key: str,



    endpoint: str



) -> dict:



    """Check if request is within rate limit."""



    from datetime import datetime, timedelta







    # Get limit config



    config = _default_limits.get("default")



    for ep in _default_limits:



        if endpoint.startswith(ep):



            config = _default_limits[ep]



            break







    now = datetime.now()



    minute_key = f"{key}:{endpoint}:minute"



    hour_key = f"{key}:{endpoint}:hour"







    # Initialize if not exists



    if minute_key not in _request_counts:



        _request_counts[minute_key] = [0, now.isoformat()]



    if hour_key not in _request_counts:



        _request_counts[hour_key] = [0, now.isoformat()]







    minute_count, minute_reset = _request_counts[minute_key]



    hour_count, hour_reset = _request_counts[hour_key]







    # Check reset



    if now.isoformat() > minute_reset:



        minute_count = 0



        _request_counts[minute_key] = [0, (now + timedelta(minutes=1)).isoformat()]



    if now.isoformat() > hour_reset:



        hour_count = 0



        _request_counts[hour_key] = [0, (now + timedelta(hours=1)).isoformat()]







    # Check limits



    can_proceed = minute_count < config["requests_per_minute"] and hour_count < config["requests_per_hour"]







    return {



        "allowed": can_proceed,



        "minute": {



            "current": minute_count,



            "limit": config["requests_per_minute"],



            "remaining": max(0, config["requests_per_minute"] - minute_count)



        },



        "hour": {



            "current": hour_count,



            "limit": config["requests_per_hour"],



            "remaining": max(0, config["requests_per_hour"] - hour_count)



        }



    }











@router.post("/rate-limits/record")



async def record_request(



    key: str,



    endpoint: str



) -> dict:



    """Record a request for rate limiting."""



    from datetime import datetime







    now = datetime.now()



    minute_key = f"{key}:{endpoint}:minute"



    hour_key = f"{key}:{endpoint}:hour"







    if minute_key not in _request_counts:



        _request_counts[minute_key] = [0, now.isoformat()]



    if hour_key not in _request_counts:



        _request_counts[hour_key] = [0, now.isoformat()]







    _request_counts[minute_key][0] += 1



    _request_counts[hour_key][0] += 1







    return {"status": "recorded"}











@router.get("/rate-limits/stats", response_model=list[RateLimitStats])



async def get_rate_limit_stats(key: str) -> list[RateLimitStats]:



    """Get rate limit statistics for a key."""



    stats = []



    for endpoint, config in _default_limits.items():



        minute_key = f"{key}:{endpoint}:minute"



        hour_key = f"{key}:{endpoint}:hour"







        minute_count = _request_counts.get(minute_key, [0, ""])[0]



        hour_count = _request_counts.get(hour_key, [0, ""])[0]







        stats.append(RateLimitStats(



            endpoint=endpoint,



            requests_current_minute=minute_count,



            requests_current_hour=hour_count,



            limit_minute=config["requests_per_minute"],



            limit_hour=config["requests_per_hour"],



            remaining_minute=max(0, config["requests_per_minute"] - minute_count),



            remaining_hour=max(0, config["requests_per_hour"] - hour_count)



        ))







    return stats











# =============================================================================



# Caching Layer (v1.45)



# =============================================================================







class CacheEntry(BaseModel):



    """Cache entry."""



    key: str



    value: dict



    expires_at: str | None



    hits: int



    created_at: str











class CacheStats(BaseModel):



    """Cache statistics."""



    total_entries: int



    total_hits: int



    total_misses: int



    hit_rate: float



    memory_size_bytes: int











class CacheConfig(BaseModel):



    """Cache configuration."""



    default_ttl_seconds: int



    max_entries: int



    eviction_policy: str  # lru|lfu|fifo



    enabled: bool











# In-memory cache



_cache: dict[str, dict] = {}



_cache_stats = {"hits": 0, "misses": 0}











@router.get("/cache/{key}", response_model=dict)



async def get_cache(key: str) -> dict:



    """Get a cached value."""



    if key in _cache:



        entry = _cache[key]



        entry["hits"] += 1



        _cache_stats["hits"] += 1



        return {"found": True, "value": entry["value"], "hits": entry["hits"]}



    _cache_stats["misses"] += 1



    return {"found": False}











@router.post("/cache/{key}")



async def set_cache(



    key: str,



    value: dict,



    ttl_seconds: int = 300



) -> dict:



    """Set a cache value."""



    from datetime import datetime, timedelta







    expires_at = None



    if ttl_seconds > 0:



        expires_at = (datetime.now() + timedelta(seconds=ttl_seconds)).isoformat()







    _cache[key] = {



        "key": key,



        "value": value,



        "expires_at": expires_at,



        "hits": 0,



        "created_at": _now_iso()



    }







    return {"status": "cached", "expires_at": expires_at}











@router.delete("/cache/{key}")



async def delete_cache(key: str) -> dict:



    """Delete a cache entry."""



    if key in _cache:



        del _cache[key]



        return {"status": "deleted"}



    return {"status": "not_found"}











@router.post("/cache/clear")



async def clear_cache() -> dict:



    """Clear all cache entries."""



    count = len(_cache)



    _cache.clear()



    _cache_stats = {"hits": 0, "misses": 0}



    return {"status": "cleared", "entries_deleted": count}











@router.get("/cache/stats", response_model=CacheStats)



async def get_cache_stats() -> CacheStats:



    """Get cache statistics."""



    total = len(_cache)



    hits = _cache_stats["hits"]



    misses = _cache_stats["misses"]



    total_requests = hits + misses



    hit_rate = hits / total_requests if total_requests > 0 else 0.0







    # Estimate memory size



    import sys



    memory_size = sys.getsizeof(str(_cache))







    return CacheStats(



        total_entries=total,



        total_hits=hits,



        total_misses=misses,



        hit_rate=hit_rate,



        memory_size_bytes=memory_size



    )











@router.get("/cache/config", response_model=CacheConfig)



async def get_cache_config() -> CacheConfig:



    """Get cache configuration."""



    return CacheConfig(



        default_ttl_seconds=300,



        max_entries=1000,



        eviction_policy="lru",



        enabled=True



    )











@router.post("/cache/config")



async def update_cache_config(req: CacheConfig) -> dict:



    """Update cache configuration."""



    # In production, this would update actual cache settings



    return {"status": "updated", "config": req.model_dump()}











