# Entity Versioning (v1.46)



# =============================================================================







class EntityVersion(BaseModel):



    """Version of an entity."""



    version_id: str



    entity_id: str



    version_number: int



    data: dict



    created_at: str



    created_by: str











class VersionDiff(BaseModel):



    """Difference between versions."""



    from_version: int



    to_version: int



    changes: list[dict]



    added: list[str]



    removed: list[str]



    modified: list[str]











class CreateVersionRequest(BaseModel):



    """Request to create a new version."""



    entity_id: str



    data: dict



    created_by: str











class VersionHistoryResponse(BaseModel):



    """Version history response."""



    entity_id: str



    versions: list[dict]



    total_versions: int











# In-memory version store



_entity_versions: dict[str, list] = {}











@router.post("/entities/{entity_id}/versions", response_model=EntityVersion)



async def create_entity_version(



    entity_id: str,



    req: CreateVersionRequest



) -> EntityVersion:



    """Create a new version of an entity."""



    import uuid







    version_id = f"v_{uuid.uuid4().hex[:8]}"







    if entity_id not in _entity_versions:



        _entity_versions[entity_id] = []







    version_number = len(_entity_versions[entity_id]) + 1







    version = EntityVersion(



        version_id=version_id,



        entity_id=entity_id,



        version_number=version_number,



        data=req.data,



        created_at=_now_iso(),



        created_by=req.created_by



    )







    _entity_versions[entity_id].append(version.model_dump())



    return version











@router.get("/entities/{entity_id}/versions", response_model=VersionHistoryResponse)



async def get_version_history(



    entity_id: str,



    limit: int = 10



) -> VersionHistoryResponse:



    """Get version history for an entity."""



    versions = _entity_versions.get(entity_id, [])[-limit:]



    return VersionHistoryResponse(



        entity_id=entity_id,



        versions=versions,



        total_versions=len(_entity_versions.get(entity_id, []))



    )











@router.get("/entities/{entity_id}/versions/{version_number}", response_model=EntityVersion)



async def get_entity_version(



    entity_id: str,



    version_number: int



) -> EntityVersion:



    """Get a specific version of an entity."""



    versions = _entity_versions.get(entity_id, [])



    for v in versions:



        if v["version_number"] == version_number:



            return EntityVersion(**v)







    return EntityVersion(



        version_id="",



        entity_id=entity_id,



        version_number=version_number,



        data={},



        created_at=_now_iso(),



        created_by=""



    )











@router.post("/entities/{entity_id}/versions/{version_number}/restore")



async def restore_version(



    entity_id: str,



    version_number: int



) -> dict:



    """Restore an entity to a specific version."""



    versions = _entity_versions.get(entity_id, [])



    for v in versions:



        if v["version_number"] == version_number:



            return {



                "status": "restored",



                "entity_id": entity_id,



                "version": version_number,



                "data": v["data"]



            }



    return {"status": "not_found"}











@router.post("/entities/{entity_id}/versions/diff", response_model=VersionDiff)



async def diff_versions(



    entity_id: str,



    from_version: int,



    to_version: int



) -> VersionDiff:



    """Get diff between two versions."""



    versions = _entity_versions.get(entity_id, [])







    from_data = {}



    to_data = {}







    for v in versions:



        if v["version_number"] == from_version:



            from_data = v["data"]



        if v["version_number"] == to_version:



            to_data = v["data"]







    # Calculate changes



    from_keys = set(from_data.keys())



    to_keys = set(to_data.keys())



    added = list(to_keys - from_keys)



    removed = list(from_keys - to_keys)



    modified = list(from_keys & to_keys)







    return VersionDiff(



        from_version=from_version,



        to_version=to_version,



        changes=[],



        added=added,



        removed=removed,



        modified=modified



    )











@router.get("/entities/{entity_id}/versions/stats", response_model=dict)



async def get_version_stats(entity_id: str) -> dict:



    """Get version statistics for an entity."""



    versions = _entity_versions.get(entity_id, [])



    return {



        "entity_id": entity_id,



        "total_versions": len(versions),



        "first_version": versions[0]["created_at"] if versions else None,



        "last_version": versions[-1]["created_at"] if versions else None,



        "versions_by_user": {}



    }











