class GraphExportRequest(BaseModel):



    """Request to export knowledge graph."""



    format: str  # json|xml|rdf|ttl|cypher|gml



    include_metadata: bool = True



    compression: bool = False



    encoding: str = "utf-8"











class GraphExportResponse(BaseModel):



    """Export response."""



    export_id: str



    format: str



    size_bytes: int



    download_url: str



    expires_at: str



    record_count: int











class ExportFormatMetadata(BaseModel):



    """Metadata about export format."""



    format: str



    mime_type: str



    file_extension: str



    supports_compression: bool



    schema_url: str | None











# In-memory exports



_exports: dict[str, dict] = {}











@router.post("/export/formats", response_model=list[ExportFormatMetadata])



async def list_export_formats() -> list[ExportFormatMetadata]:



    """List available export formats."""



    formats = [



        ExportFormatMetadata(



            format="json",



            mime_type="application/json",



            file_extension=".json",



            supports_compression=True,



            schema_url=None



        ),



        ExportFormatMetadata(



            format="xml",



            mime_type="application/xml",



            file_extension=".xml",



            supports_compression=True,



            schema_url=None



        ),



        ExportFormatMetadata(



            format="rdf",



            mime_type="application/rdf+xml",



            file_extension=".rdf",



            supports_compression=True,



            schema_url=None



        ),



        ExportFormatMetadata(



            format="ttl",



            mime_type="text/turtle",



            file_extension=".ttl",



            supports_compression=False,



            schema_url=None



        ),



        ExportFormatMetadata(



            format="cypher",



            mime_type="text/plain",



            file_extension=".cypher",



            supports_compression=False,



            schema_url=None



        ),



        ExportFormatMetadata(



            format="gml",



            mime_type="text/gml",



            file_extension=".gml",



            supports_compression=True,



            schema_url=None



        ),



    ]



    return formats











@router.post("/export/graph", response_model=GraphExportResponse)



async def export_graph(req: GraphExportRequest) -> GraphExportResponse:



    """Export knowledge graph in specified format."""



    import uuid



    import random







    export_id = f"export_{uuid.uuid4().hex[:8]}"



    record_count = random.randint(100, 1000)







    export = GraphExportResponse(



        export_id=export_id,



        format=req.format,



        size_bytes=record_count * 100,



        download_url=f"/api/kg/export/download/{export_id}",



        expires_at=_now_iso(),



        record_count=record_count



    )







    _exports[export_id] = export.model_dump()



    return export











@router.get("/export/graph/{export_id}", response_model=GraphExportResponse)



async def get_export(export_id: str) -> GraphExportResponse:



    """Get export status."""



    if export_id in _exports:



        return GraphExportResponse(**_exports[export_id])



    return GraphExportResponse(



        export_id=export_id,



        format="json",



        size_bytes=0,



        download_url="",



        expires_at="",



        record_count=0



    )











@router.get("/export/graph/{export_id}/download")



async def download_export(export_id: str) -> dict:



    """Download exported graph."""



    if export_id not in _exports:



        return {"error": "Export not found"}







    export = _exports[export_id]



    return {



        "format": export["format"],



        "data": f"Sample {export['format']} data content",



        "size_bytes": export["size_bytes"],



        "record_count": export["record_count"]



    }











@router.get("/export/history", response_model=list[dict])



async def get_export_history(limit: int = 10) -> list[dict]:



    """Get export history."""



    exports = list(_exports.values())[-limit:]



    return exports











