# Data Validation Rules (v1.47)



# =============================================================================







class ValidationRule(BaseModel):



    """Data validation rule."""



    rule_id: str



    name: str



    description: str



    field: str



    rule_type: str  # required|regex|type|range|custom



    config: dict



    enabled: bool



    severity: str  # error|warning|info











class ValidationResult(BaseModel):



    """Validation result."""



    valid: bool



    errors: list[dict]



    warnings: list[dict]



    validated_at: str











class ValidationStats(BaseModel):



    """Validation statistics."""



    total_rules: int



    enabled_rules: int



    last_validation: str | None



    pass_rate: float











# In-memory rules



_validation_rules: dict[str, dict] = {}











# Default rules



_default_rules = [



    {"rule_id": "rule_1", "name": "Entity ID Required", "description": "Entity ID must be present", "field": "entity_id", "rule_type": "required", "config": {}, "enabled": True, "severity": "error"},



    {"rule_id": "rule_2", "name": "Name Length", "description": "Name must be 1-200 chars", "field": "name", "rule_type": "range", "config": {"min": 1, "max": 200}, "enabled": True, "severity": "error"},



    {"rule_id": "rule_3", "name": "Email Format", "description": "Valid email format", "field": "email", "rule_type": "regex", "config": {"pattern": ".*@.*"}, "enabled": True, "severity": "warning"},



]







for r in _default_rules:



    _validation_rules[r["rule_id"]] = r











@router.get("/validation/rules", response_model=list[ValidationRule])



async def list_validation_rules() -> list[ValidationRule]:



    """List all validation rules."""



    return [ValidationRule(**r) for r in _validation_rules.values()]











@router.get("/validation/rules/{rule_id}", response_model=ValidationRule)



async def get_validation_rule(rule_id: str) -> ValidationRule:



    """Get a specific validation rule."""



    if rule_id in _validation_rules:



        return ValidationRule(**_validation_rules[rule_id])



    return ValidationRule(



        rule_id=rule_id,



        name="Not Found",



        description="",



        field="",



        rule_type="required",



        config={},



        enabled=False,



        severity="info"



    )











@router.post("/validation/rules", response_model=ValidationRule)



async def create_validation_rule(



    name: str,



    description: str,



    field: str,



    rule_type: str,



    config: dict = {},



    severity: str = "error"



) -> ValidationRule:



    """Create a validation rule."""



    import uuid



    rule_id = f"rule_{uuid.uuid4().hex[:8]}"







    rule = ValidationRule(



        rule_id=rule_id,



        name=name,



        description=description,



        field=field,



        rule_type=rule_type,



        config=config,



        enabled=True,



        severity=severity



    )







    _validation_rules[rule_id] = rule.model_dump()



    return rule











@router.post("/validation/rules/{rule_id}/toggle")



async def toggle_validation_rule(rule_id: str) -> dict:



    """Enable/disable a validation rule."""



    if rule_id in _validation_rules:



        rule = _validation_rules[rule_id]



        rule["enabled"] = not rule["enabled"]



        return {"status": "toggled", "enabled": rule["enabled"]}



    return {"status": "not_found"}











@router.delete("/validation/rules/{rule_id}")



async def delete_validation_rule(rule_id: str) -> dict:



    """Delete a validation rule."""



    if rule_id in _validation_rules:



        del _validation_rules[rule_id]



        return {"status": "deleted"}



    return {"status": "not_found"}











@router.post("/validation/validate", response_model=ValidationResult)



async def validate_data(data: dict) -> ValidationResult:



    """Validate data against all rules."""



    errors = []



    warnings = []







    for rule in _validation_rules.values():



        if not rule["enabled"]:



            continue







        field = rule["field"]



        value = data.get(field)







        if rule["rule_type"] == "required" and not value:



            errors.append({"field": field, "rule": rule["name"], "message": "Required field is missing"})







        elif rule["rule_type"] == "range":



            min_val = rule["config"].get("min", 0)



            max_val = rule["config"].get("max", float("inf"))



            if value and (len(str(value)) < min_val or len(str(value)) > max_val):



                errors.append({"field": field, "rule": rule["name"], "message": f"Length must be between {min_val} and {max_val}"})







    return ValidationResult(



        valid=len(errors) == 0,



        errors=errors,



        warnings=warnings,



        validated_at=_now_iso()



    )











@router.get("/validation/stats", response_model=ValidationStats)



async def get_validation_stats() -> ValidationStats:



    """Get validation statistics."""



    total = len(_validation_rules)



    enabled = sum(1 for r in _validation_rules.values() if r["enabled"])







    return ValidationStats(



        total_rules=total,



        enabled_rules=enabled,



        last_validation=_now_iso(),



        pass_rate=enabled / total if total > 0 else 0.0



    )











