# Graph Analytics Trends (v1.48.0)



# =============================================================================







class TrendData(BaseModel):



    """Trend data point."""



    timestamp: str



    value: float



    label: str | None











class TrendAnalysis(BaseModel):



    """Trend analysis result."""



    metric: str



    trend: str  # "increasing", "decreasing", "stable"



    change_percent: float



    data_points: list[TrendData]



    forecast: list[TrendData]











class GrowthMetrics(BaseModel):



    """Growth metrics."""



    entity_growth_rate: float



    relation_growth_rate: float



    avg_degree: float



    density: float



    clustering_coefficient: float



    connected_components: int











# In-memory analytics storage



_analytics_history: dict[str, list[dict]] = {



    "entities": [],



    "relations": [],



    "queries": [],



    "exports": []



}











@router.get("/analytics/trends", response_model=TrendAnalysis)



async def get_trend_analysis(



    metric: str = "entities",



    period: str = "7d"



) -> TrendAnalysis:



    """Get trend analysis for a metric."""



    import random







    # Generate trend data



    data_points = []



    base_value = len(_entities) if metric == "entities" else len(_relations)







    days = int(period.replace("d", "")) if period.endswith("d") else 7



    for i in range(days):



        data_points.append(TrendData(



            timestamp=f"2026-05-{days-i:02d}",



            value=max(1, base_value + random.randint(-10, 20)),



            label=f"Day {i+1}" if i < 3 else None



        ))







    # Calculate trend



    values = [dp.value for dp in data_points]



    avg = sum(values) / len(values)



    first_half = sum(values[:len(values)//2]) / (len(values)//2)



    second_half = sum(values[len(values)//2:]) / (len(values) - len(values)//2)



    change_percent = ((second_half - first_half) / first_half * 100) if first_half > 0 else 0







    trend = "stable"



    if change_percent > 5:



        trend = "increasing"



    elif change_percent < -5:



        trend = "decreasing"







    return TrendAnalysis(



        metric=metric,



        trend=trend,



        change_percent=round(change_percent, 2),



        data_points=data_points,



        forecast=[]



    )











@router.get("/analytics/growth", response_model=GrowthMetrics)



async def get_growth_metrics() -> GrowthMetrics:



    """Get growth metrics."""



    entity_count = len(_entities)



    relation_count = len(_relations)







    # Calculate metrics



    avg_degree = (relation_count * 2 / entity_count) if entity_count > 0 else 0



    max_possible_edges = entity_count * (entity_count - 1) / 2



    density = (relation_count / max_possible_edges) if max_possible_edges > 0 else 0







    # Simplified clustering coefficient



    clustering = 0.3 if entity_count > 2 else 0.0







    # Count connected components (simplified)



    components = 1 if entity_count > 0 else 0







    return GrowthMetrics(



        entity_growth_rate=0.05,



        relation_growth_rate=0.08,



        avg_degree=round(avg_degree, 2),



        density=round(density, 4),



        clustering_coefficient=clustering,



        connected_components=components



    )











