@router.post("/analytics/track")



async def track_analytics_event(event_type: str, data: dict = {}) -> dict:



    """Track an analytics event."""



    if event_type not in _analytics_history:



        _analytics_history[event_type] = []







    event = {



        "timestamp": _now_iso(),



        "data": data



    }



    _analytics_history[event_type].append(event)







    # Keep only last 100 events per type



    if len(_analytics_history[event_type]) > 100:



        _analytics_history[event_type] = _analytics_history[event_type][-100:]







    return {"status": "tracked", "type": event_type}











