@router.post("/insights/analyze")



async def analyze_graph_for_insights() -> dict:



    """Trigger AI analysis of the graph."""



    global _insights







    # Generate insights based on graph state



    _insights = []







    # High connectivity insight



    if _entities:



        max_connections = 0



        most_connected = None



        for eid, entity in _entities.items():



            connections = sum(1 for r in _relations.values()



                         if r.get("source_id") == eid or r.get("target_id") == eid)



            if connections > max_connections:



                max_connections = connections



                most_connected = entity.get("name", eid)







        if most_connected and max_connections > 5:



            _insights.append({



                "id": f"ins_{len(_insights)+1}",



                "type": "opportunity",



                "title": f"Hub Node: {most_connected}",



                "description": f"'{most_connected}' is a major hub with {max_connections} connections",



                "confidence": 0.9,



                "entities": [most_connected],



                "severity": "medium"



            })







    # Orphan detection



    connected_entities = set()



    for r in _relations.values():



        connected_entities.add(r.get("source_id"))



        connected_entities.add(r.get("target_id"))







    orphans = [eid for eid in _entities if eid not in connected_entities]



    if orphans:



        _insights.append({



            "id": f"ins_{len(_insights)+1}",



            "type": "risk",



            "title": "Orphan Entities",



            "description": f"Found {len(orphans)} entities without connections",



            "confidence": 0.95,



            "entities": orphans[:3],



            "severity": "high"



        })







    return {



        "status": "analyzed",



        "insights_count": len(_insights),



        "timestamp": _now_iso()



    }











