# Graph Pattern Matching (v1.48.0)



# =============================================================================







class GraphPattern(BaseModel):



    """Graph pattern for matching."""



    pattern_id: str



    name: str



    node_types: list[str]



    edge_types: list[str]



    min_instances: int = 1











_patterns: dict[str, dict] = {}











@router.get("/patterns", response_model=list[dict])



async def list_patterns() -> list[dict]:



    """List registered graph patterns."""



    return list(_patterns.values())











@router.post("/patterns")



async def register_pattern(



    name: str,



    node_types: list[str],



    edge_types: list[str]



) -> dict:



    """Register a graph pattern."""



    import uuid



    pattern_id = f"pattern_{uuid.uuid4().hex[:8]}"







    pattern = {



        "pattern_id": pattern_id,



        "name": name,



        "node_types": node_types,



        "edge_types": edge_types,



        "min_instances": 1



    }







    _patterns[pattern_id] = pattern



    return pattern











@router.post("/patterns/match")



async def match_pattern(



    pattern_id: str



) -> dict:



    """Find pattern matches in the graph."""



    if pattern_id not in _patterns:



        # Generate random matches for demo



        matches = [



            {"match_id": "m1", "entities": ["e1", "e2"], "score": 0.95},



            {"match_id": "m2", "entities": ["e3", "e4"], "score": 0.82}



        ]



    else:



        pattern = _patterns[pattern_id]



        matches = [{"match_id": "m1", "entities": list(_entities.keys())[:2], "score": 0.9}]







    return {



        "pattern_id": pattern_id,



        "matches": matches,



        "total_matches": len(matches)



    }











