@router.post("/ml/models/{model_id}/train", response_model=TrainingJob)



async def train_model(



    model_id: str,



    training_data: str = "graph",



    test_split: float = 0.2,



    epochs: int = 100



) -> TrainingJob:



    """Train an ML model."""



    if model_id not in _ml_models:



        raise HTTPException(status_code=404, detail="Model not found")







    # Update model status



    _ml_models[model_id]["status"] = MLModelStatus.TRAINING







    job_id = f"job_{len(_model_training_jobs) + 1}"



    job = TrainingJob(



        job_id=job_id,



        model_id=model_id,



        status=TrainingJobStatus.RUNNING,



        created_at=_now_iso(),



        started_at=_now_iso()



    )



    _model_training_jobs[job_id] = job.model_dump()







    # Simulate training completion



    _ml_models[model_id]["status"] = MLModelStatus.READY



    _ml_models[model_id]["trained_at"] = _now_iso()



    _ml_models[model_id]["accuracy"] = round(0.85 + (hash(model_id) % 15) / 100, 3)



    _ml_models[model_id]["f1_score"] = round(0.80 + (hash(model_id) % 15) / 100, 3)



    _ml_models[model_id]["precision"] = round(0.82 + (hash(model_id) % 15) / 100, 3)



    _ml_models[model_id]["recall"] = round(0.78 + (hash(model_id) % 15) / 100, 3)



    _ml_models[model_id]["training_data_size"] = len(_entities)







    job.status = TrainingJobStatus.COMPLETED



    job.completed_at = _now_iso()



    job.progress = 100.0



    job.metrics = {



        "accuracy": _ml_models[model_id]["accuracy"],



        "f1_score": _ml_models[model_id]["f1_score"]



    }



    _model_training_jobs[job_id] = job.model_dump()







    return job







