@router.post("/ml/models/{model_id}/predict", response_model=PredictionResult)



async def predict(



    model_id: str,



    request: PredictionRequest



) -> PredictionResult:



    """Make predictions using a trained model."""



    if model_id not in _ml_models:



        raise HTTPException(status_code=404, detail="Model not found")







    model = _ml_models[model_id]



    if model.get("status") != MLModelStatus.READY:



        raise HTTPException(status_code=400, detail="Model not ready for prediction")







    prediction_id = f"pred_{len(_model_predictions) + 1}"







    # Generate predictions based on model type



    results = []



    for entity_id in request.entity_ids:



        entity = _entities.get(entity_id, {})







        if model["model_type"] == MLModelType.LINK_PREDICTION:



            # Link prediction: predict potential connections



            target_entities = list(_entities.keys())[:5]



            for target in target_entities:



                if target != entity_id:



                    score = round(0.5 + (hash(entity_id + target) % 50) / 100, 3)



                    if request.return_probabilities:



                        results.append({



                            "source": entity_id,



                            "target": target,



                            "score": score,



                            "probability": score,



                            "label": "link" if score > 0.7 else "no_link"



                        })



                    else:



                        results.append({



                            "source": entity_id,



                            "target": target,



                            "score": score,



                            "label": "link" if score > 0.7 else "no_link"



                        })



        elif model["model_type"] == MLModelType.NODE_CLASSIFICATION:



            # Node classification



            classes = ["category_a", "category_b", "category_c"]



            class_idx = hash(entity_id) % len(classes)



            if request.return_probabilities:



                probs = [round(0.2 + (hash(entity_id + c) % 30) / 100, 3) for c in classes]



                # Normalize probabilities to sum to 1.0



                probs_sum = sum(probs)



                probs = [p / probs_sum for p in probs]



                probs[class_idx] = 1.0 - sum(probs[:class_idx]) - sum(probs[class_idx+1:])



                results.append({



                    "entity_id": entity_id,



                    "predicted_class": classes[class_idx],



                    "probabilities": dict(zip(classes, probs))



                })



            else:



                results.append({



                    "entity_id": entity_id,



                    "predicted_class": classes[class_idx]



                })



        elif model["model_type"] == MLModelType.ANOMALY_DETECTION:



            # Anomaly detection



            is_anomaly = (hash(entity_id) % 10) < 2



            results.append({



                "entity_id": entity_id,



                "is_anomaly": is_anomaly,



                "anomaly_score": round(0.1 + (hash(entity_id) % 40) / 100, 3),



                "details": "Unusual connection patterns detected" if is_anomaly else "Normal"



            })



        elif model["model_type"] == MLModelType.EMBEDDING:



            # Embedding generation



            embedding = [(hash(entity_id + str(i)) % 100) / 100 for i in range(128)]



            results.append({



                "entity_id": entity_id,



                "embedding": embedding[:model.get("training_data_size", 10)],



                "dimension": min(128, model.get("training_data_size", 10))



            })



        elif model["model_type"] == MLModelType.RECOMMENDATION:



            # Recommendation



            similar = [(hash(entity_id + str(i)) % 10) / 10 for i in range(5)]



            results.append({



                "entity_id": entity_id,



                "recommendations": [



                    {"entity_id": f"e{i}", "score": round(1.0 - s, 3)}



                    for i, s in enumerate(similar)



                ]



            })







    prediction = PredictionResult(



        prediction_id=prediction_id,



        model_id=model_id,



        results=results,



        timestamp=_now_iso()



    )



    _model_predictions[prediction_id] = prediction.model_dump()







    return prediction







