# Graph ML Algorithms APIs (v1.50.0)



# =============================================================================







# PageRank cache



_pagerank_scores: Dict[str, Dict[str, float]] = {}



_community_results: Dict[str, Dict] = {}



_centrality_cache: Dict[str, Dict] = {}











class AlgorithmType(str, Enum):



    """Graph algorithm types."""



    PAGERANK = "pagerank"



    COMMUNITY_DETECTION = "community_detection"



    CENTRALITY = "centrality"



    SHORTEST_PATH = "shortest_path"



    ALL_PATHS = "all_paths"



    CLUSTERING = "clustering"











class CentralityType(str, Enum):



    """Centrality types."""



    DEGREE = "degree"



    BETWEENNESS = "betweenness"



    CLOSENESS = "closeness"



    EIGENVECTOR = "eigenvector"











class CommunityAlgorithm(str, Enum):



    """Community detection algorithms."""



    LOUVAIN = "louvain"



    LABEL_PROPAGATION = "label_propagation"



    GREEDY_MODULARITY = "greedy_modularity"











class PageRankResult(BaseModel):



    """PageRank result schema."""



    entity_id: str



    score: float



    rank: int











class CommunityResult(BaseModel):



    """Community detection result schema."""



    community_id: str



    members: List[str]



    size: int



    density: float











class CentralityResult(BaseModel):



    """Centrality result schema."""



    entity_id: str



    centrality: float



    rank: int











class PathResult(BaseModel):



    """Path finding result schema."""



    path: List[str]



    length: int



    edges: List[Dict[str, str]]











@router.post("/ml/algorithms/pagerank", response_model=List[PageRankResult])



async def compute_pagerank(



    damping: float = 0.85,



    max_iterations: int = 100,



    tolerance: float = 1e-6



) -> List[PageRankResult]:



    """Compute PageRank scores for all entities."""



    # Build adjacency list from relations



    adjacency: Dict[str, List[str]] = {e["entity_id"]: [] for e in _entities}



    inlinks: Dict[str, List[str]] = {e["entity_id"]: [] for e in _entities}







    for rel in _relations:



        src, tgt = rel.get("source_entity_id"), rel.get("target_entity_id")



        if src and tgt:



            if src in adjacency:



                adjacency[src].append(tgt)



            if tgt in inlinks:



                inlinks[tgt].append(src)







    # Initialize PageRank



    n = len(_entities)



    ranks = {e["entity_id"]: 1.0 / n for e in _entities}







    # Power iteration



    for _iteration in range(max_iterations):



        new_ranks: Dict[str, float] = {}



        delta = 0.0







        for entity in _entities:



            entity_id = entity["entity_id"]



            in_links = inlinks.get(entity_id, [])







            # SumPageRank from in-links



            rank_sum = 0.0



            for source in in_links:



                out_links = adjacency.get(source, [])



                if out_links:



                    rank_sum += ranks.get(source, 0) / len(out_links)







            new_rank = (1 - damping) / n + damping * rank_sum



            new_ranks[entity_id] = new_rank



            delta += abs(new_rank - ranks.get(entity_id, 0))







        ranks = new_ranks



        if delta < tolerance:



            break







    # Sort and rank



    sorted_entities = sorted(ranks.items(), key=lambda x: x[1], reverse=True)



    results = []



    for rank, (entity_id, score) in enumerate(sorted_entities, 1):



        results.append(PageRankResult(entity_id=entity_id, score=round(score, 6), rank=rank))







    # Cache result



    _pagerank_scores["default"] = ranks



    return results











@router.get("/ml/algorithms/pagerank", response_model=List[PageRankResult])



async def get_pagerank_scores() -> List[PageRankResult]:



    """Get cached PageRank scores."""



    if not _pagerank_scores:



        raise HTTPException(status_code=404, detail="PageRank not computed yet")







    sorted_entities = sorted(



        _pagerank_scores.get("default", {}).items(),



        key=lambda x: x[1],



        reverse=True



    )



    results = []



    for rank, (entity_id, score) in enumerate(sorted_entities, 1):



        results.append(PageRankResult(entity_id=entity_id, score=round(score, 6), rank=rank))







    return results











@router.post("/ml/algorithms/community", response_model=List[CommunityResult])



async def detect_communities(



    algorithm: CommunityAlgorithm = CommunityAlgorithm.LOUVAIN,



    resolution: float = 1.0



) -> List[CommunityResult]:



    """Detect communities in the graph."""



    # Build adjacency for community detection



    adjacency: Dict[str, List[str]] = {e["entity_id"]: [] for e in _entities}



    for rel in _relations:



        src, tgt = rel.get("source_entity_id"), rel.get("target_entity_id")



        if src and tgt:



            adjacency[src].append(tgt)



            adjacency[tgt].append(src)







    # Simple label propagation algorithm



    labels = {e["entity_id"]: e["entity_id"] for e in _entities}



    entities_list = [e["entity_id"] for e in _entities]







    # Run label propagation



    for _iteration in range(50):



        changed = False



        import random



        random.shuffle(entities_list)







        for entity_id in entities_list:



            neighbors = adjacency.get(entity_id, [])



            if not neighbors:



                continue







            # Count label frequencies among neighbors



            label_counts: Dict[str, int] = {}



            for neighbor in neighbors:



                label = labels.get(neighbor)



                if label:



                    label_counts[label] = label_counts.get(label, 0) + 1







            if not label_counts:



                continue







            # Find max frequency label



            max_label = max(label_counts.items(), key=lambda x: x[1])[0]



            if labels.get(entity_id) != max_label:



                labels[entity_id] = max_label



                changed = True







        if not changed:



            break







    # Group by community



    communities: Dict[str, List[str]] = {}



    for entity_id, label in labels.items():



        if label not in communities:



            communities[label] = []



        communities[label].append(entity_id)







    # Calculate density for each community



    results = []



    for community_id, members in communities.items():



        edges = 0



        for member in members:



            edges += len([n for n in adjacency.get(member, []) if n in members])



        density = edges / max(1, len(members) * (len(members) - 1)) if len(members) > 1 else 0.0







        results.append(CommunityResult(



            community_id=community_id,



            members=members,



            size=len(members),



            density=round(density, 4)



        ))







    # Sort by size



    results.sort(key=lambda x: x.size, reverse=True)



    for i, r in enumerate(results, 1):



        r.community_id = f"community_{i}"







    _community_results["default"] = {r.community_id: r.model_dump() for r in results}



    return results











@router.get("/ml/algorithms/community", response_model=List[CommunityResult])



async def get_communities() -> List[CommunityResult]:



    """Get cached community results."""



    if not _community_results:



        raise HTTPException(status_code=404, detail="Community detection not run yet")







    results = []



    for community_id, data in _community_results.get("default", {}).items():



        results.append(CommunityResult(**data))







    return sorted(results, key=lambda x: x.size, reverse=True)











@router.post("/ml/algorithms/centrality", response_model=List[CentralityResult])



async def compute_centrality(



    centrality_type: CentralityType = CentralityType.DEGREE



) -> List[CentralityResult]:



    """Compute centrality metrics for entities."""



    # Build adjacency



    adjacency: Dict[str, List[str]] = {e["entity_id"]: [] for e in _entities}



    in_degree: Dict[str, int] = {e["entity_id"]: 0 for e in _entities}



    out_degree: Dict[str, int] = {e["entity_id"]: 0 for e in _entities}







    for rel in _relations:



        src, tgt = rel.get("source_entity_id"), rel.get("target_entity_id")



        if src and tgt:



            adjacency[src].append(tgt)



            out_degree[src] = out_degree.get(src, 0) + 1



            in_degree[tgt] = in_degree.get(tgt, 0) + 1







    # Compute centrality based on type



    centrality_scores: Dict[str, float] = {}







    if centrality_type == CentralityType.DEGREE:



        # Degree centrality = in-degree + out-degree



        for entity in _entities:



            entity_id = entity["entity_id"]



            centrality_scores[entity_id] = in_degree.get(entity_id, 0) + out_degree.get(entity_id, 0)







    elif centrality_type == CentralityType.BETWEENNESS:



        # Simplified betweenness: count how often node appears on shortest paths



        from collections import deque



        betweenness: Dict[str, float] = {e["entity_id"]: 0.0 for e in _entities}







        for source in adjacency:



            # BFS from source



            distances = {source: 0}



            parents: Dict[str, List[str]] = {source: []}







            queue = deque([source])



            while queue:



                current = queue.popleft()



                for neighbor in adjacency.get(current, []):



                    if neighbor not in distances:



                        distances[neighbor] = distances[current] + 1



                        parents[neighbor] = []



                        queue.append(neighbor)



                    if distances[neighbor] == distances[current] + 1:



                        parents[neighbor].append(current)







            # Count paths through each node (excluding source and target)



            for target, dist in distances.items():



                if target == source:



                    continue



                # Backtrack from target to source



                path_nodes = set()



                current = target



                stack = [target]



                while stack:



                    node = stack.pop()



                    if node != source and node != target:



                        path_nodes.add(node)



                    for parent in parents.get(node, []):



                        if distances.get(parent, 0) == distances[node] - 1:



                            stack.append(parent)







                for node in path_nodes:



                    betweenness[node] = betweenness.get(node, 0) + 1







        n = len(_entities)



        if n > 2:



            normalization = 2.0 / ((n - 1) * (n - 2))



        else:



            normalization = 1.0







        for entity_id, score in betweenness.items():



            centrality_scores[entity_id] = score * normalization







    elif centrality_type == CentralityType.CLOSENESS:



        # Closeness centrality: inverse of average shortest path



        from collections import deque



        closeness: Dict[str, float] = {e["entity_id"]: 0.0 for e in _entities}







        for source in adjacency:



            # BFS to find all distances



            distances = {source: 0}



            queue = deque([source])



            while queue:



                current = queue.popleft()



                for neighbor in adjacency.get(current, []):



                    if neighbor not in distances:



                        distances[neighbor] = distances[current] + 1



                        queue.append(neighbor)







            # Calculate closeness (excluding self)



            total_distance = sum(d for d in distances.values() if d > 0)



            reachable = len([d for d in distances.values() if d > 0])







            if reachable > 0 and total_distance > 0:



                closeness[source] = reachable / total_distance



            else:



                closeness[source] = 0.0







        centrality_scores = closeness







    else:



        # Default to degree centrality



        for entity in _entities:



            entity_id = entity["entity_id"]



            centrality_scores[entity_id] = in_degree.get(entity_id, 0) + out_degree.get(entity_id, 0)







    # Sort and rank



    sorted_entities = sorted(centrality_scores.items(), key=lambda x: x[1], reverse=True)



    results = []



    for rank, (entity_id, centrality) in enumerate(sorted_entities, 1):



        results.append(CentralityResult(



            entity_id=entity_id,



            centrality=round(centrality, 4),



            rank=rank



        ))







    _centrality_cache[centrality_type.value] = centrality_scores



    return results











@router.get("/ml/algorithms/centrality", response_model=List[CentralityResult])



async def get_centrality_scores(



    centrality_type: CentralityType = CentralityType.DEGREE



) -> List[CentralityResult]:



    """Get cached centrality scores."""



    if centrality_type.value not in _centrality_cache:



        raise HTTPException(status_code=404, detail="Centrality not computed yet")







    scores = _centrality_cache.get(centrality_type.value, {})



    sorted_entities = sorted(scores.items(), key=lambda x: x[1], reverse=True)







    results = []



    for rank, (entity_id, centrality) in enumerate(sorted_entities, 1):



        results.append(CentralityResult(



            entity_id=entity_id,



            centrality=round(centrality, 4),



            rank=rank



        ))







    return results











@router.post("/ml/algorithms/path", response_model=List[PathResult])



async def find_shortest_path(



    source_id: str,



    target_id: str,



    max_length: int = 10



) -> List[PathResult]:



    """Find shortest path between two entities."""



    from collections import deque







    # Build adjacency



    adjacency: Dict[str, List[str]] = {e["entity_id"]: [] for e in _entities}



    for rel in _relations:



        src, tgt = rel.get("source_entity_id"), rel.get("target_entity_id")



        if src and tgt:



            adjacency[src].append(tgt)







    # BFS for shortest path



    if source_id not in adjacency and source_id not in {e["entity_id"] for e in _entities}:



        raise HTTPException(status_code=404, detail="Source entity not found")



    if target_id not in adjacency and target_id not in {e["entity_id"] for e in _entities}:



        raise HTTPException(status_code=404, detail="Target entity not found")







    # BFS



    queue = deque([(source_id, [source_id])])



    visited = {source_id}



    paths: List[PathResult] = []







    while queue:



        current, path = queue.popleft()







        if len(path) > max_length:



            continue







        if current == target_id:



            # Build edge list



            edges = []



            for i in range(len(path) - 1):



                edges.append({



                    "source": path[i],



                    "target": path[i + 1],



                    "relation_type": "connected_to"



                })



            paths.append(PathResult(



                path=path,



                length=len(path) - 1,



                edges=edges



            ))



            continue







        for neighbor in adjacency.get(current, []):



            if neighbor not in visited:



                visited.add(neighbor)



                queue.append((neighbor, path + [neighbor]))







    if not paths:



        return []







    # Return shortest



    paths.sort(key=lambda x: x.length)



    return [paths[0]]











@router.post("/ml/algorithms/clustering", response_model=Dict)



async def compute_clustering_coefficient() -> Dict:



    """Compute clustering coefficient for the graph."""



    # Build undirected adjacency



    adjacency: Dict[str, Set[str]] = {e["entity_id"]: set() for e in _entities}



    for rel in _relations:



        src, tgt = rel.get("source_entity_id"), rel.get("target_entity_id")



        if src and tgt:



            adjacency[src].add(tgt)



            adjacency[tgt].add(src)







    # Calculate local clustering coefficient for each node



    local_coefficients: Dict[str, float] = {}



    total_coefficient = 0.0







    for entity_id, neighbors in adjacency.items():



        k = len(neighbors)



        if k < 2:



            local_coefficients[entity_id] = 0.0



            continue







        # Count edges between neighbors



        edges_between_neighbors = 0



        for neighbor1 in neighbors:



            for neighbor2 in neighbors:



                if neighbor1 != neighbor2 and neighbor2 in adjacency.get(neighbor1, set()):



                    edges_between_neighbors += 1







        # Each edge counted twice, so divide by 2



        edges_between_neighbors //= 2







        # Maximum possible edges



        max_edges = k * (k - 1) / 2







        coefficient = edges_between_neighbors / max_edges if max_edges > 0 else 0.0



        local_coefficients[entity_id] = round(coefficient, 4)



        total_coefficient += coefficient







    avg_clustering = total_coefficient / len(_entities) if _entities else 0.0







    return {



        "average_clustering_coefficient": round(avg_clustering, 4),



        "local_coefficients": local_coefficients,



        "entities": len(_entities)



    }











