# Iteration 151: Real-time Graph Streaming APIs



# =============================================================================







# Event storage for streaming



_graph_events: list[Dict] = []



_event_max_history = 1000







# Real-time notification subscribers



_notification_subscribers: Dict[str, list[WebSocket]] = {}







# Stream aggregation buffers



_stream_buffers: Dict[str, list[Dict]] = {}











class GraphEvent(BaseModel):



    """Graph event model."""



    event_id: str = Field(default_factory=lambda: str(uuid.uuid4()))



    event_type: str  # entity_added, entity_updated, entity_deleted, relation_added, relation_updated, relation_deleted



    entity_id: Optional[str] = None



    relation_id: Optional[str] = None



    data: Optional[Dict] = None



    timestamp: float = Field(default_factory=lambda: time.time())











class StreamFilter(BaseModel):



    """Stream filter model."""



    event_types: Optional[List[str]] = None



    entity_ids: Optional[List[str]] = None



    time_range: Optional[int] = 3600  # seconds











class NotificationMessage(BaseModel):



    """Notification message model."""



    notification_id: str = Field(default_factory=lambda: str(uuid.uuid4()))



    title: str



    message: str



    severity: str = "info"  # info, warning, error, success



    entity_id: Optional[str] = None



    timestamp: float = Field(default_factory=lambda: time.time())











@router.post("/stream/events", response_model=Dict)



async def create_graph_event(event: GraphEvent) -> Dict:



    """Create a graph event."""



    global _graph_events







    event_data = event.model_dump()



    _graph_events.append(event_data)







    # Trim history



    if len(_graph_events) > _event_max_history:



        _graph_events = _graph_events[-_event_max_history:]







    # Broadcast to WebSocket subscribers



    await _manager.broadcast(event_data, channel="all")







    return {"status": "created", "event_id": event.event_id}











@router.get("/stream/events", response_model=List[Dict])



async def get_graph_events(



    filter_params: Optional[StreamFilter] = None,



    limit: int = Query(default=100, le=500),



    offset: int = Query(default=0, ge=0)



) -> List[Dict]:



    """Get graph events with optional filtering."""



    events = _graph_events.copy()







    if filter_params:



        if filter_params.event_types:



            events = [e for e in events if e.get("event_type") in filter_params.event_types]



        if filter_params.entity_ids:



            events = [e for e in events if e.get("entity_id") in filter_params.entity_ids]



        if filter_params.time_range:



            cutoff = time.time() - filter_params.time_range



            events = [e for e in events if e.get("timestamp", 0) >= cutoff]







    # Apply pagination



    start = min(offset, len(events))



    end = min(start + limit, len(events))







    return events[start:end]











@router.get("/stream/events/count", response_model=Dict)



async def count_graph_events() -> Dict:



    """Count events by type."""



    counts: Dict[str, int] = {}



    for event in _graph_events:



        event_type = event.get("event_type", "unknown")



        counts[event_type] = counts.get(event_type, 0) + 1







    return {



        "total": len(_graph_events),



        "by_type": counts



    }











@router.post("/stream/aggregate", response_model=Dict)



async def aggregate_stream(



    window_seconds: int = Query(default=60),



    entity_ids: Optional[List[str]] = None



) -> Dict:



    """Aggregate events within a time window."""



    cutoff = time.time() - window_seconds



    relevant_events = [



        e for e in _graph_events



        if e.get("timestamp", 0) >= cutoff



    ]







    if entity_ids:



        relevant_events = [



            e for e in relevant_events



            if e.get("entity_id") in entity_ids



        ]







    # Aggregate by type



    aggregation: Dict[str, int] = {}



    for event in relevant_events:



        event_type = event.get("event_type", "unknown")



        aggregation[event_type] = aggregation.get(event_type, 0) + 1







    return {



        "window_seconds": window_seconds,



        "total_events": len(relevant_events),



        "by_type": aggregation,



        "entity_count": len(set(e.get("entity_id") for e in relevant_events if e.get("entity_id")))



    }











@router.websocket("/ws/stream")



async def websocket_stream(websocket: WebSocket):



    """WebSocket endpoint for real-time event streaming."""



    await websocket.accept()



    await _manager.connect(websocket, channel="all")







    try:



        while True:



            data = await websocket.receive_text()



            # Parse and handle incoming messages



            try:



                message = json.loads(data)



                if message.get("type") == "subscribe":



                    channel = message.get("channel", "all")



                    await _manager.connect(websocket, channel=channel)



                elif message.get("type") == "unsubscribe":



                    channel = message.get("channel", "all")



                    await _manager.disconnect(websocket, channel=channel)



            except json.JSONDecodeError:



                pass



    except WebSocketDisconnect:



        await _manager.disconnect(websocket, channel="all")











@router.get("/stream/sse")



async def stream_sse(request: Request):



    """Server-Sent Events stream for graph updates."""







    async def event_generator():



        last_event_id = 0







        while True:



            # Check if client disconnected



            if await request.is_disconnected():



                break







            # Get new events since lastEventId



            new_events = _graph_events[last_event_id:]







            for event in new_events:



                last_event_id += 1



                event_id = f"id: {last_event_id}\n"



                data = f"data: {json.dumps(event)}\n\n"



                yield event_id + data







            await asyncio.sleep(1)  # Check every second







    return StreamingResponse(



        event_generator(),



        media_type="text/event-stream",



        headers={



            "Cache-Control": "no-cache",



            "Connection": "keep-alive",



            "X-Accel-Buffering": "no"



        }



    )











# === Notification System ===







@router.post("/notifications/subscribe/{channel}", response_model=Dict)



async def subscribe_notifications(channel: str, websocket: WebSocket) -> Dict:



    """Subscribe to notifications on a channel."""



    await websocket.accept()







    if channel not in _notification_subscribers:



        _notification_subscribers[channel] = []







    _notification_subscribers[channel].append(websocket)







    return {"status": "subscribed", "channel": channel}











@router.post("/notifications/publish", response_model=Dict)



async def publish_notification(notification: NotificationMessage) -> Dict:



    """Publish a notification to a channel."""



    channel = notification.severity







    notification_data = notification.model_dump()







    # Send to subscribers



    if channel in _notification_subscribers:



        for websocket in _notification_subscribers[channel]:



            try:



                await websocket.send_json(notification_data)



            except Exception:



                pass







    # Also broadcast to "all" channel



    if "all" in _notification_subscribers:



        for websocket in _notification_subscribers["all"]:



            try:



                await websocket.send_json(notification_data)



            except Exception:



                pass







    return {



        "status": "published",



        "notification_id": notification.notification_id,



        "channel": channel



    }











@router.get("/notifications", response_model=List[Dict])



async def get_notifications(



    limit: int = Query(default=50, le=200),



    severity: Optional[str] = None



) -> List[Dict]:



    """Get recent notifications."""



    # Filter by severity if specified



    notifications = _graph_events  # Use events as notification history







    if severity:



        notifications = [



            n for n in notifications



            if n.get("severity") == severity



        ]







    return notifications[-limit:]











