@router.get("/stream/changes", response_model=Dict)



async def get_recent_changes(



    since: Optional[float] = Query(default=None),



    entity_id: Optional[str] = None



) -> Dict:



    """Get recent changes since timestamp."""



    if since is None:



        since = time.time() - 3600  # Default: last hour







    changes: List[Dict] = []







    for event in _graph_events:



        if event.get("timestamp", 0) >= since:



            if entity_id is None or event.get("entity_id") == entity_id:



                changes.append(event)







    return {



        "since": since,



        "changes": changes,



        "count": len(changes)



    }











@router.get("/stream/monitor/{entity_id}", response_model=Dict)



async def monitor_entity(entity_id: str) -> Dict:



    """Monitor a specific entity for changes."""



    entity_events = [



        e for e in _graph_events



        if e.get("entity_id") == entity_id



    ]







    # Get current state



    entity = _entities.get(entity_id, {})



    relations = [



        r for r in _relations.values()



        if r.get("source_id") == entity_id or r.get("target_id") == entity_id



    ]







    return {



        "entity_id": entity_id,



        "exists": entity_id in _entities,



        "event_count": len(entity_events),



        "relation_count": len(relations),



        "events": entity_events[-10:],  # Last 10 events



        "state": entity



    }











@router.post("/stream/export", response_model=Dict)



async def export_stream_events(



    format: str = Query(default="json", regex="^(json|csv|text)$"),



    start_time: Optional[float] = None,



    end_time: Optional[float] = None



) -> Dict:



    """Export stream events."""



    events = _graph_events.copy()







    if start_time:



        events = [e for e in events if e.get("timestamp", 0) >= start_time]



    if end_time:



        events = [e for e in events if e.get("timestamp", 0) <= end_time]







    if format == "csv":



        # Simple CSV format



        lines = ["event_id,event_type,entity_id,timestamp"]



        for e in events:



            lines.append(



                f"{e.get('event_id', '')},{e.get('event_type', '')},{e.get('entity_id', '')},{e.get('timestamp', '')}"



            )



        return {"format": "csv", "content": "\n".join(lines)}







    if format == "text":



        # Human-readable text



        lines = []



        for e in events:



            lines.append(



                f"[{e.get('timestamp', '')}] {e.get('event_type', '')}: {e.get('entity_id', '')}"



            )



        return {"format": "text", "content": "\n".join(lines)}







    return {"format": "json", "events": events}











