# Visualization cache



_visualization_cache: Dict[str, Dict] = {}



_cache_ttl = 300  # 5 minutes











class VisualizationRequest(BaseModel):



    """Visualization request model."""



    layout: str = "force"  # force, hierarchical, circular, grid



    include_relations: bool = True



    include_attributes: bool = True



    depth_limit: Optional[int] = None



    entity_ids: Optional[List[str]] = None











class LayoutConfig(BaseModel):



    """Layout configuration."""



    layout_type: str = "force"



    force_strength: float = 100



    force_distance: float = 100



    centering: bool = True



    iterations: int = 100











@router.post("/visualize/d3", response_model=Dict)



async def visualize_d3(request: VisualizationRequest) -> Dict:



    """Generate D3.js-compatible visualization data."""



    # Check cache



    cache_key = f"d3_{request.layout}_{request.depth_limit}"



    if cache_key in _visualization_cache:



        cached = _visualization_cache[cache_key]



        if time.time() - cached.get("_cached_at", 0) < _cache_ttl:



            return cached







    nodes = []



    links = []







    # Get entities to include



    entities_to_include = _entities



    if request.entity_ids:



        entities_to_include = {



            k: v for k, v in _entities.items()



            if k in request.entity_ids



        }







    # Depth filtering



    if request.depth_limit and request.depth_limit > 0:



        # BFS to find entities within depth



        visited = set()



        queue = [(eid, 0) for eid in request.entity_ids or list(_entities.keys())[:1]]



        while queue:



            eid, depth = queue.pop(0)



            if eid in visited or depth > request.depth_limit:



                continue



            visited.add(eid)



            if eid in _entities:



                # Add neighbors



                for rel in _relations.values():



                    if rel.get("source_id") == eid and depth + 1 <= request.depth_limit:



                        queue.append((rel.get("target_id"), depth + 1))



        entities_to_include = {k: v for k, v in _entities.items() if k in visited}



        if request.entity_ids:



            rels_to_include = {



                k: v for k, v in _relations.items()



                if v.get("source_id") in visited and v.get("target_id") in visited



            }



        else:



            rels_to_include = _relations



    else:



        rels_to_include = _relations







    # Build nodes



    for entity_id, entity in entities_to_include.items():



        node_data = {



            "id": entity_id,



            "label": entity.get("name", entity_id),



            "type": entity.get("type", "unknown"),



        }



        if request.include_attributes:



            node_data["data"] = entity



        nodes.append(node_data)







    # Build links



    if request.include_relations:



        for rel_id, rel in rels_to_include.items():



            link_data = {



                "id": rel_id,



                "source": rel.get("source_id"),



                "target": rel.get("target_id"),



                "type": rel.get("relation_type", "unknown"),



            }



            if request.include_attributes:



                link_data["data"] = rel



            links.append(link_data)







    result = {



        "nodes": nodes,



        "links": links,



        "metadata": {



            "node_count": len(nodes),



            "link_count": len(links),



            "layout": request.layout,



        }



    }







    # Cache result



    result["_cached_at"] = time.time()



    _visualization_cache[cache_key] = result







    return result











