class TimelineRequest(BaseModel):



    """Request for timeline analysis."""



    start_version: Optional[str] = None



    end_version: Optional[str] = None



    interval: str = "daily"  # daily, weekly, monthly



    metrics: List[str] = ["entities", "relations", "types"]











class EntityEvolutionRequest(BaseModel):



    """Request for entity evolution tracking."""



    entity_id: str



    include_versions: bool = True











@router.post("/timeseries/timeline", response_model=Dict)



async def get_timeline_analysis(request: TimelineRequest) -> Dict:



    """Get timeline analysis of graph changes."""



    if _versions is None or len(_versions) == 0:



        return {"error": "No version data available"}







    # Get version range



    version_list = list(_versions.keys())



    version_list.sort()







    if request.start_version:



        version_list = [v for v in version_list if v >= request.start_version]



    if request.end_version:



        version_list = [v for v in version_list if v <= request.end_version]







    timeline: List[Dict] = []







    for version in version_list:



        vdata = _versions.get(version, {})



        entities = vdata.get("entities", {})



        relations = vdata.get("relations", {})







        entry = {"version": version, "timestamp": vdata.get("timestamp", "")}







        if "entities" in request.metrics:



            entry["entity_count"] = len(entities)



        if "relations" in request.metrics:



            entry["relation_count"] = len(relations)



        if "types" in request.metrics:



            type_counts: Dict[str, int] = {}



            for e in entities.values():



                etype = e.get("type", "unknown")



                type_counts[etype] = type_counts.get(etype, 0) + 1



            entry["type_distribution"] = type_counts







        timeline.append(entry)







    # Calculate changes between versions



    changes: List[Dict] = []



    for i in range(1, len(timeline)):



        prev = timeline[i - 1]



        curr = timeline[i]







        change = {



            "version": curr["version"],



            "entity_delta": curr.get("entity_count", 0) - prev.get("entity_count", 0),



            "relation_delta": curr.get("relation_count", 0) - prev.get("relation_count", 0),



        }



        changes.append(change)







    return {



        "timeline": timeline,



        "changes": changes,



        "interval": request.interval,



    }











@router.post("/timeseries/evolution", response_model=Dict)



async def track_entity_evolution(request: EntityEvolutionRequest) -> Dict:



    """Track evolution of a specific entity."""



    entity_id = request.entity_id



    history: List[Dict] = []







    version_list = list(_versions.keys())



    version_list.sort()







    for version in version_list:



        vdata = _versions.get(version, {})



        entities = vdata.get("entities", {})







        if entity_id in entities:



            entity = entities[entity_id]



            entry = {



                "version": version,



                "timestamp": vdata.get("timestamp", ""),



                "exists": True,



                "name": entity.get("name"),



                "type": entity.get("type"),



                "properties": entity.get("properties", {}),



            }



            history.append(entry)







    if not history:



        return {"error": f"Entity {entity_id} not found in any version"}







    # Find changes



    changes: List[Dict] = []



    for i in range(1, len(history)):



        prev = history[i - 1]



        curr = history[i]







        change_fields = []



        if prev.get("name") != curr.get("name"):



            change_fields.append("name")



        if prev.get("type") != curr.get("type"):



            change_fields.append("type")







        # Check property changes



        prev_props = prev.get("properties", {})



        curr_props = curr.get("properties", {})



        for key in set(prev_props.keys()) | set(curr_props.keys()):



            if prev_props.get(key) != curr_props.get(key):



                change_fields.append(f"property:{key}")







        if change_fields:



            changes.append({



                "version": curr["version"],



                "changed_fields": change_fields,



            })







    return {



        "entity_id": entity_id,



        "versions_count": len(history),



        "first_seen": history[0]["version"] if history else None,



        "last_seen": history[-1]["version"] if history else None,



        "history": history if request.include_versions else None,



        "changes": changes,



    }











@router.post("/timeseries/growth", response_model=Dict)



async def get_growth_metrics() -> Dict:



    """Get growth metrics over time."""



    if _versions is None or len(_versions) == 0:



        return {"error": "No version data available"}







    version_list = list(_versions.keys())



    version_list.sort()







    if len(version_list) < 2:



        return {"error": "Need at least 2 versions for growth analysis"}







    first_v = _versions.get(version_list[0], {})



    last_v = _versions.get(version_list[-1], {})







    first_entities = len(first_v.get("entities", {}))



    last_entities = len(last_v.get("entities", {}))







    first_relations = len(first_v.get("relations", {}))



    last_relations = len(last_v.get("relations", {}))







    entity_growth = ((last_entities - first_entities) / max(1, first_entities)) * 100



    relation_growth = ((last_relations - first_relations) / max(1, first_relations)) * 100







    # Calculate average growth rate



    timeline_data = []



    for version in version_list:



        vdata = _versions.get(version, {})



        timeline_data.append({



            "version": version,



            "entities": len(vdata.get("entities", {})),



            "relations": len(vdata.get("relations", {})),



        })







    # Simple linear regression for growth rate



    n = len(timeline_data)



    if n > 1:



        x = list(range(n))



        y_entities = [d["entities"] for d in timeline_data]



        x.mean = sum(x) / n



        y_mean = sum(y_entities) / n







        numerator = sum((x[i] - x.mean) * (y_entities[i] - y_mean) for i in range(n))



        denominator = sum((x[i] - x.mean) ** 2 for i in range(n))







        entity_growth_rate = numerator / max(0.01, denominator)



    else:



        entity_growth_rate = 0







    return {



        "first_version": version_list[0],



        "last_version": version_list[-1],



        "first_version_entities": first_entities,



        "last_version_entities": last_entities,



        "entity_growth_percent": round(entity_growth, 2),



        "first_version_relations": first_relations,



        "last_version_relations": last_relations,



        "relation_growth_percent": round(relation_growth, 2),



        "avg_growth_rate": round(entity_growth_rate, 2),



    }











@router.post("/timeseries/emergence", response_model=Dict)



async def get_relation_emergence() -> Dict:



    """Track when relations emerged."""



    if _versions is None or len(_versions) == 0:



        return {"error": "No version data available"}







    version_list = list(_versions.keys())



    version_list.sort()







    # Track first appearance of each relation



    first_appearance: Dict[str, str] = {}







    for version in version_list:



        vdata = _versions.get(version, {})



        relations = vdata.get("relations", {})







        for rel_id, rel in relations.items():



            if rel_id not in first_appearance:



                first_appearance[rel_id] = version







    # Group by relation type



    by_type: Dict[str, List[str]] = {}



    for rel_id, version in first_appearance.items():



        rel = _versions.get(version, {}).get("relations", {}).get(rel_id, {})



        rtype = rel.get("relation_type", "unknown")







        if rtype not in by_type:



            by_type[rtype] = []



        by_type[rtype].append(rel_id)







    return {



        "total_new_relations": len(first_appearance),



        "by_type": {k: len(v) for k, v in by_type.items()},



        "timeline": first_appearance,



    }











