# =============================================================================



# Graph Sampling APIs (v1.53)



# =============================================================================







_sampling_cache: Dict[str, Dict] = {}











class SamplingRequest(BaseModel):



    """Request model for graph sampling."""



    sample_size: int = 100



    method: str = "random_nodes"  # random_nodes, random_edges, snowball, stratified



    seed: Optional[int] = None



    include_relations: bool = True











class EdgeSamplingRequest(BaseModel):



    """Request for edge sampling."""



    sample_size: int = 100



    strategy: str = "random"  # random, by_type, by_weight



    relation_types: Optional[List[str]] = None











def _sample_random_nodes(



    sample_size: int,



    include_relations: bool = True,



    seed: Optional[int] = None



) -> Dict:



    """Random node sampling."""



    if seed:



        random.seed(seed)







    entity_ids = list(_entities.keys())



    sample_size = min(sample_size, len(entity_ids))







    sampled_ids = random.sample(entity_ids, sample_size)



    sampled_entities = {eid: _entities[eid] for eid in sampled_ids}







    result = {



        "method": "random_nodes",



        "sample_size": sample_size,



        "entities": sampled_entities,



    }







    if include_relations:



        # Include relations between sampled nodes



        sampled_relations = {}



        for rel_id, rel in _relations.items():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent in sampled_ids and to_ent in sampled_ids:



                sampled_relations[rel_id] = rel







        result["relations"] = sampled_relations



        result["relation_count"] = len(sampled_relations)







    return result











def _sample_random_edges(



    sample_size: int,



    relation_types: Optional[List[str]] = None



) -> Dict:



    """Random edge sampling."""



    relation_ids = list(_relations.keys())







    if relation_types:



        filtered = [



            rid for rid in relation_ids



            if _relations[rid].get("relation_type") in relation_types



        ]



        relation_ids = filtered







    sample_size = min(sample_size, len(relation_ids))



    sampled_ids = random.sample(relation_ids, sample_size)







    sampled_relations = {rid: _relations[rid] for rid in sampled_ids}







    # Get all related entities



    entity_ids = set()



    for rel in sampled_relations.values():



        entity_ids.add(rel.get("from_entity"))



        entity_ids.add(rel.get("to_entity"))







    sampled_entities = {eid: _entities[eid] for eid in entity_ids if eid in _entities}







    return {



        "method": "random_edges",



        "sample_size": sample_size,



        "entities": sampled_entities,



        "relations": sampled_relations,



    }











def _sample_snowball(



    sample_size: int,



    seed_entity: Optional[str] = None



) -> Dict:



    """Snowball sampling starting from a seed entity."""



    if seed_entity is None:



        seed_entity = random.choice(list(_entities.keys()))







    visited = set()



    to_visit = [seed_entity]



    sampled_entities = {}



    sampled_relations = {}







    while to_visit and len(sampled_entities) < sample_size:



        current = to_visit.pop(0)







        if current in visited:



            continue



        visited.add(current)







        if current in _entities:



            sampled_entities[current] = _entities[current]







        # Find all neighbors



        for rel_id, rel in _relations.items():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent == current:



                neighbor = to_ent



            elif to_ent == current:



                neighbor = from_ent



            else:



                continue







            sampled_relations[rel_id] = rel







            if neighbor not in visited:



                to_visit.append(neighbor)







    return {



        "method": "snowball",



        "sample_size": len(sampled_entities),



        "seed_entity": seed_entity,



        "entities": sampled_entities,



        "relations": sampled_relations,



    }











def _sample_stratified(



    sample_size: int,



    include_relations: bool = True



) -> Dict:



    """Stratified sampling by entity type."""



    # Group entities by type



    by_type: Dict[str, List[str]] = {}



    for entity_id, entity in _entities.items():



        etype = entity.get("type", "unknown")



        if etype not in by_type:



            by_type[etype] = []



        by_type[etype].append(entity_id)







    # Sample proportionally from each type



    sampled_ids = []



    total_entities = len(_entities)







    for etype, entity_ids in by_type.items():



        proportion = len(entity_ids) / total_entities



        type_sample_size = max(1, int(sample_size * proportion))







        sample_size_actual = min(type_sample_size, len(entity_ids))



        sampled_ids.extend(random.sample(entity_ids, sample_size_actual))







    sampled_entities = {eid: _entities[eid] for eid in sampled_ids}







    result = {



        "method": "stratified",



        "sample_size": len(sampled_ids),



        "type_distribution": {etype: len(ids) for etype, ids in by_type.items()},



        "entities": sampled_entities,



    }







    if include_relations:



        sampled_relations = {}



        for rel_id, rel in _relations.items():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent in sampled_ids and to_ent in sampled_ids:



                sampled_relations[rel_id] = rel







        result["relations"] = sampled_relations







    return result











@router.post("/sample/nodes", response_model=Dict)



async def sample_nodes(request: SamplingRequest) -> Dict:



    """Sample nodes from the graph."""



    if request.method == "random_nodes":



        result = _sample_random_nodes(



            request.sample_size,



            request.include_relations,



            request.seed



        )



    elif request.method == "snowball":



        result = _sample_snowball(request.sample_size)



    elif request.method == "stratified":



        result = _sample_stratified(request.sample_size, request.include_relations)



    else:



        return {"error": f"Unknown method: {request.method}"}







    cache_key = f"nodes_{request.method}_{request.sample_size}"



    _sampling_cache[cache_key] = result







    return result











