@router.post("/sample/validate", response_model=Dict)



async def validate_sample(request: SamplingRequest) -> Dict:



    """Validate representativeness of a sample."""



    # Generate sample



    sample = _sample_random_nodes(request.sample_size, include_relations=False, seed=request.seed)







    # Compare type distribution



    original_distribution: Dict[str, int] = {}



    for entity in _entities.values():



        etype = entity.get("type", "unknown")



        original_distribution[etype] = original_distribution.get(etype, 0) + 1







    sample_distribution: Dict[str, int] = {}



    for entity in sample.get("entities", {}).values():



        etype = entity.get("type", "unknown")



        sample_distribution[etype] = sample_distribution.get(etype, 0) + 1







    # Calculate distribution similarity (simple)



    total_original = len(_entities)



    total_sample = len(sample.get("entities", {}))







    distribution_similarity = 0



    for etype in set(original_distribution.keys()) | set(sample_distribution.keys()):



        orig_pct = original_distribution.get(etype, 0) / max(1, total_original)



        sample_pct = sample_distribution.get(etype, 0) / max(1, total_sample)



        distribution_similarity += 1 - abs(orig_pct - sample_pct)







    return {



        "sample_size": request.sample_size,



        "original_distribution": original_distribution,



        "sample_distribution": sample_distribution,



        "distribution_similarity": round(distribution_similarity, 2),



    }











