@router.post("/export/graph", response_model=Dict)



async def export_graph(request: ExportRequest) -> Dict:



    """Export full graph."""



    entities = _entities if request.include_entities else {}



    relations = _relations if request.include_relations else {}







    if request.format == "json":



        data = {



            "entities": entities,



            "relations": relations,



            "metadata": {



                "entity_count": len(entities),



                "relation_count": len(relations),



                "exported_at": datetime.now().isoformat(),



            },



        }



    elif request.format == "csv":



        # Return CSV-like structure



        entity_rows = [[eid, e.get("name", ""), e.get("type", "")] for eid, e in entities.items()]



        relation_rows = [



            [rid, r.get("from_entity", ""), r.get("to_entity", ""), r.get("relation_type", "")]



            for rid, r in relations.items()



        ]



        data = {



            "entities": entity_rows,



            "relations": relation_rows,



        }



    elif request.format == "turtle":



        # Turtle RDF format (simplified)



        turtle = []



        for eid, e in entities.items():



            turtle.append(f":{eid} a :{e.get('type', 'Entity')} .")



        for rid, r in relations.items():



            turtle.append(f":{rid} :from :{r.get('from_entity')} ; :to :{r.get('to_entity')} .")



        data = {"turtle": "\n".join(turtle)}



    elif request.format == "jsonld":



        graph = {



            "@context": {"@vocab": "http://example.org/"},



            "@graph": [],



        }



        for eid, e in entities.items():



            graph["@graph"].append({"@id": eid, **e})



        for rid, r in relations.items():



            graph["@graph"].append({"@id": rid, **r})



        data = graph



    else:  # networkx-like



        data = {



            "nodes": list(entities.keys()),



            "edges": [



                [r.get("from_entity"), r.get("to_entity")]



                for r in relations.values()



            ],



        }







    cache_key = f"{request.format}_{len(entities)}_{len(relations)}"



    _export_cache[cache_key] = data







    return {



        "format": request.format,



        "entity_count": len(entities),



        "relation_count": len(relations),



    }











@router.post("/export/subgraph", response_model=Dict)



async def export_subgraph(request: PartialExportRequest) -> Dict:



    """Export subgraph."""



    entity_ids = set(request.entity_ids)







    # Filter entities



    entities = {eid: _entities[eid] for eid in entity_ids if eid in _entities}







    # Filter relations



    relations = {}



    for rid, rel in _relations.items():



        from_ent = rel.get("from_entity")



        to_ent = rel.get("to_entity")







        if from_ent in entity_ids or to_ent in entity_ids:



            relations[rid] = rel







    if request.format == "json":



        data = {"entities": entities, "relations": relations}



    else:



        data = {



            "nodes": list(entities.keys()),



            "edges": [[r.get("from_entity"), r.get("to_entity")] for r in relations.values()],



        }







    return {



        "format": request.format,



        "entity_count": len(entities),



        "relation_count": len(relations),



    }











