# =============================================================================



# Graph Attention Mechanisms (v1.58)



# =============================================================================







_attention_cache: Dict[str, Dict] = {}











class AttentionRequest(BaseModel):



    """Request for attention computation."""



    entity_id: Optional[str] = None



    heads: int = 4



    attention_type: str = "scaled_dot_product"  # scaled_dot_product, additive, multiplicative











class MultiHeadAttentionRequest(BaseModel):



    """Multi-head attention request."""



    source_entity: str



    target_entity: str



    heads: int = 4











def _compute_attention_weights(



    source_id: str,



    target_id: str,



    attention_type: str = "scaled_dot_product"



) -> Dict:



    """Compute attention weights between entities."""



    # Get neighbors of source



    source_neighbors: Dict[str, float] = {}







    for rel in _relations.values():



        from_ent = rel.get("from_entity")



        to_ent = rel.get("to_entity")







        if from_ent == source_id:



            source_neighbors[to_ent] = source_neighbors.get(to_ent, 0) + 1



        elif to_ent == source_id:



            source_neighbors[from_ent] = source_neighbors.get(from_ent, 0) + 1







    if not source_neighbors:



        return {"error": "No neighbors"}







    # Normalize



    total = sum(source_neighbors.values())



    weights = {k: v / max(1, total) for k, v in source_neighbors.items()}







    # Attention to target if exists



    attention = weights.get(target_id, 0)







    return {



        "source": source_id,



        "target": target_id,



        "attention_score": attention,



        "neighbors": weights,



    }











def _multi_head_attention(



    source_id: str,



    target_id: str,



    num_heads: int = 4



) -> Dict:



    """Compute multi-head attention."""



    # Multiple attention heads with different neighbor groups



    heads_scores: List[Dict] = []







    for head_idx in range(num_heads):



        # Different random attention patterns



        seed = head_idx * 1000 + hash(source_id) % 10000



        random.seed(seed)







        neighbor_weights: Dict[str, float] = {}







        for rel in _relations.values():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent == source_id:



                neighbor_weights[to_ent] = random.random()



            elif to_ent == source_id:



                neighbor_weights[from_ent] = random.random()







        # Normalize



        total = sum(neighbor_weights.values())



        if total > 0:



            neighbor_weights = {k: v / total for k, v in neighbor_weights.items()}







        attention = neighbor_weights.get(target_id, 0)







        heads_scores.append({



            "head": head_idx,



            "attention": attention,



        })







    # Average across heads



    avg_attention = sum(h["attention"] for h in heads_scores) / num_heads







    return {



        "source": source_id,



        "target": target_id,



        "num_heads": num_heads,



        "average_attention": avg_attention,



        "head_scores": heads_scores,



    }











@router.post("/attention/compute", response_model=Dict)



async def compute_attention(request: AttentionRequest) -> Dict:



    """Compute attention between entities."""



    if not request.entity_id:



        return {"error": "entity_id required"}







    # Get entity neighbors



    neighbors: Dict[str, float] = {}







    for rel in _relations.values():



        from_ent = rel.get("from_entity")



        to_ent = rel.get("to_entity")







        if from_ent == request.entity_id:



            neighbors[to_ent] = neighbors.get(to_ent, 0) + 1



        elif to_ent == request.entity_id:



            neighbors[from_ent] = neighbors.get(from_ent, 0) + 1







    total = sum(neighbors.values())



    normalized = {k: v / max(1, total) for k, v in neighbors.items()}







    sorted_neighbors = sorted(



        normalized.items(),



        key=lambda x: x[1],



        reverse=True



    )[:10]







    cache_key = f"{request.entity_id}_{request.attention_type}"



    _attention_cache[cache_key] = {"neighbors": normalized}







    return {



        "entity": request.entity_id,



        "attention_type": request.attention_type,



        "top_attended": sorted_neighbors,



    }











@router.post("/attention/multi-head", response_model=Dict)



async def compute_multi_head(request: MultiHeadAttentionRequest) -> Dict:



    """Compute multi-head attention."""



    result = _multi_head_attention(



        request.source_entity,



        request.target_entity,



        request.heads



    )







    cache_key = f"mh_{request.source_entity}_{request.target_entity}"



    _attention_cache[cache_key] = result







    return result











