async def get_attention_summary() -> Dict:



    """Get attention summary."""



    return {



        "cached_attentions": len(_attention_cache),



        "total_entities": len(_entities),



    }











# =============================================================================



# Multi-hop Reasoning APIs (v1.58)



# =============================================================================







_reasoning_cache: Dict[str, Dict] = {}











class ReasoningRequest(BaseModel):



    """Request for multi-hop reasoning."""



    start_entity: str



    hops: int = 2



    query_type: str = "find_path"  # find_path, count_reachable, find_common











class LogicalReasoningRequest(BaseModel):



    """Logical reasoning request."""



    entity_a: str



    entity_b: str



    relation_type: Optional[str] = None











def _multi_hop_reasoning(



    start_entity: str,



    hops: int = 2



) -> Dict:



    """Reason over multiple hops."""



    entity_ids = list(_entities.keys())



    current_level = {start_entity: 0}



    all_reachable: Dict[str, int] = {start_entity: 0}







    for hop in range(hops):



        next_level: Dict[str, int] = {}







        for entity_id, dist in current_level.items():



            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                if from_ent == entity_id:



                    next_ent = to_ent



                elif to_ent == entity_id:



                    next_ent = from_ent



                else:



                    continue







                if next_ent and next_ent not in all_reachable:



                    next_level[next_ent] = dist + 1



                    all_reachable[next_ent] = dist + 1







        current_level = next_level



        if not current_level:



            break







    # Group by hop



    by_hop: Dict[int, List[str]] = {}



    for entity_id, dist in all_reachable.items():



        if dist not in by_hop:



            by_hop[dist] = []



        by_hop[dist].append(entity_id)







    return {



        "start": start_entity,



        "hops": hops,



        "reachable_count": len(all_reachable),



        "by_hop": by_hop,



    }











def _find_common_reachers(entity_a: str, entity_b: str, hops: int = 2) -> List[Dict]:



    """Find entities that can reach both A and B."""



    # Get entities reachable from A



    reachable_a: Set[str] = {entity_a}



    current = {entity_a}







    for _ in range(hops):



        next_level: Set[str] = set()



        for entity_id in current:



            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                if from_ent == entity_id and to_ent:



                    next_level.add(to_ent)



                elif to_ent == entity_id and from_ent:



                    next_level.add(from_ent)







        reachable_a.update(next_level)



        current = next_level







    # Get entities reachable from B



    reachable_b: Set[str] = {entity_b}



    current = {entity_b}







    for _ in range(hops):



        next_level: Set[str] = set()



        for entity_id in current:



            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                if from_ent == entity_id and to_ent:



                    next_level.add(to_ent)



                elif to_ent == entity_id and from_ent:



                    next_level.add(from_ent)







        reachable_b.update(next_level)



        current = next_level







    # Common reachers



    common = reachable_a & reachable_b







    results = []



    for entity_id in common:



        if entity_id not in [entity_a, entity_b]:



            results.append({"entity": entity_id})







    return results











@router.post("/reasoning/multi-hop", response_model=Dict)



async def multi_hop_reasoning(request: ReasoningRequest) -> Dict:



    """Reason over multiple hops."""



    if request.start_entity not in _entities:



        return {"error": "Entity not found"}







    result = _multi_hop_reasoning(request.start_entity, request.hops)







    cache_key = f"reason_{request.start_entity}_{request.hops}"



    _reasoning_cache[cache_key] = result







    return result











@router.post("/reasoning/common", response_model=Dict)



async def find_common_reachers(request: LogicalReasoningRequest) -> Dict:



    """Find common reachers between entities."""



    if request.entity_a not in _entities or request.entity_b not in _entities:



        return {"error": "Entities not found"}







    common = _find_common_reachers(request.entity_a, request.entity_b, hops=2)







    return {



        "entity_a": request.entity_a,



        "entity_b": request.entity_b,



        "common_reachers": common,



        "count": len(common),



    }











@router.get("/reasoning/summary", response_model=Dict)



async def get_reasoning_summary() -> Dict:



    """Get reasoning summary."""



    return {



        "cached_queries": len(_reasoning_cache),



        "total_entities": len(_entities),



    }











# =============================================================================



# Graph Traversal Optimizations (v1.58)



# =============================================================================







_traversal_cache: Dict[str, Dict] = {}











class TraversalRequest(BaseModel):



    """Traversal request."""



    start_entity: str



    method: str = "bfs"  # bfs, dfs, bidirectional, weighted



    max_nodes: int = 100











class TraversalOptimizationRequest(BaseModel):



    """Traversal optimization request."""



    start_entity: str



    target_entity: str











def _bidirectional_traversal(



    start_id: str,



    target_id: str



) -> Dict:



    """Bidirectional BFS for faster path finding."""



    # Forward BFS from start



    forward: Dict[str, List[str]] = {start_id: [start_id]}



    forward_queue = deque([start_id])



    forward_visited = {start_id}







    # Backward BFS from target



    backward: Dict[str, List[str]] = {target_id: [target_id]}



    backward_queue = deque([target_id])



    backward_visited = {target_id}







    steps = 0



    max_steps = 50







    while forward_queue and backward_queue and steps < max_steps:



        steps += 1







        # Expand forward



        if forward_queue:



            current = forward_queue.popleft()



            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                next_ent = None



                if from_ent == current:



                    next_ent = to_ent



                elif to_ent == current:



                    next_ent = from_ent







                if next_ent and next_ent not in forward_visited:



                    forward_visited.add(next_ent)



                    forward[next_ent] = forward[current] + [next_ent]



                    forward_queue.append(next_ent)







                    if next_ent in backward_visited:



                        # Found path



                        full_path = forward[next_ent] + list(reversed(backward[next_ent]))[1:]



                        return {



                            "found": True,



                            "path": full_path,



                            "length": len(full_path),



                            "method": "bidirectional",



                        }







        # Expand backward



        if backward_queue:



            current = backward_queue.popleft()



            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                next_ent = None



                if from_ent == current:



                    next_ent = to_ent



                elif to_ent == current:



                    next_ent = from_ent







                if next_ent and next_ent not in backward_visited:



                    backward_visited.add(next_ent)



                    backward[next_ent] = backward[current] + [next_ent]



                    backward_queue.append(next_ent)







                    if next_ent in forward_visited:



                        full_path = forward[next_ent] + list(reversed(backward[next_ent]))[1:]



                        return {



                            "found": True,



                            "path": full_path,



                            "length": len(full_path),



                            "method": "bidirectional",



                        }







    return {"found": False, "method": "bidirectional"}











def _optimized_dfs(



    start_id: str,



    max_nodes: int = 100



) -> Dict:



    """Optimized DFS with depth limiting."""



    results: List[str] = []



    visited: Set[str] = set()







    stack = [start_id]







    while stack and len(results) < max_nodes:



        current = stack.pop()







        if current in visited:



            continue







        visited.add(current)



        results.append(current)







        # Get neighbors (shuffle for randomness)



        neighbors = []



        for rel in _relations.values():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent == current and to_ent not in visited:



                neighbors.append(to_ent)



            elif to_ent == current and from_ent not in visited:



                neighbors.append(from_ent)







        random.shuffle(neighbors)



        stack.extend(neighbors)







    return {



        "method": "dfs",



        "visited_count": len(results),



        "entities": results,



    }











@router.post("/traversal/optimize", response_model=Dict)



async def optimized_traversal(request: TraversalRequest) -> Dict:



    """Optimized graph traversal."""



    if request.start_entity not in _entities:



        return {"error": "Entity not found"}







    if request.method == "bidirectional":



        # Need target - use first entity as target



        target = list(_entities.keys())[0]



        if target != request.start_entity:



            return _bidirectional_traversal(request.start_entity, target)







    elif request.method == "dfs":



        return _optimized_dfs(request.start_entity, request.max_nodes)







    else:  # bfs



        queue = deque([request.start_entity])



        visited = {request.start_entity}



        results = []







        while queue and len(results) < request.max_nodes:



            current = queue.popleft()



            results.append(current)







            for rel in _relations.values():



                from_ent = rel.get("from_entity")



                to_ent = rel.get("to_entity")







                next_ent = None



                if from_ent == current:



                    next_ent = to_ent



                elif to_ent == current:



                    next_ent = from_ent







                if next_ent and next_ent not in visited:



                    visited.add(next_ent)



                    queue.append(next_ent)







        return {



            "method": "bfs",



            "visited_count": len(results),



            "entities": results,



        }











@router.post("/traversal/bidirectional", response_model=Dict)



async def bidirectional_search(request: TraversalOptimizationRequest) -> Dict:



    """Bidirectional search between entities."""



    if request.start_entity not in _entities or request.target_entity not in _entities:



        return {"error": "Entities not found"}







    result = _bidirectional_traversal(request.start_entity, request.target_entity)







    cache_key = f"bi_{request.start_entity}_{request.target_entity}"



    _traversal_cache[cache_key] = result







    return result











