# Graph Reinforcement Learning (v1.59)



# =============================================================================







_rl_cache: Dict[str, Dict] = {}











class RLEnvironmentRequest(BaseModel):



    """RL environment config."""



    state_entity: str



    actions: Optional[List[str]] = None



    gamma: float = 0.9











class RLTrainingRequest(BaseModel):



    """RL training request."""



    episodes: int = 100



    max_steps: int = 50



    epsilon: float = 0.1  # exploration rate











def _get_rl_actions(entity_id: str) -> List[str]:



    """Get available actions for entity."""



    neighbors = []







    for rel in _relations.values():



        from_ent = rel.get("from_entity")



        to_ent = rel.get("to_entity")







        if from_ent == entity_id:



            neighbors.append(to_ent)



        elif to_ent == entity_id:



            neighbors.append(from_ent)







    return neighbors[:10]  # Limit actions











def _rl_step_reward(entity_id: str, action: str) -> Tuple[float, str]:



    """Calculate reward for action."""



    # Check if action leads to goal



    for rel in _relations.values():



        from_ent = rel.get("from_entity")



        to_ent = rel.get("to_entity")







        if (from_ent == entity_id and to_ent == action) or (from_ent == action and to_ent == entity_id):



            # Found connection, positive reward



            return 1.0, to_ent







    return 0.0, action











@router.post("/rl/environment", response_model=Dict)



async def create_rl_environment(request: RLEnvironmentRequest) -> Dict:



    """Create RL environment."""



    actions = request.actions or _get_rl_actions(request.state_entity)







    env = {



        "state": request.state_entity,



        "actions": actions,



        "gamma": request.gamma,



    }







    cache_key = f"env_{request.state_entity}"



    _rl_cache[cache_key] = env







    return {



        "state": request.state_entity,



        "action_count": len(actions),



        "gamma": request.gamma,



    }











@router.post("/rl/train", response_model=Dict)



async def train_rl_agent(request: RLTrainingRequest) -> Dict:



    """Train RL agent using Q-learning (simplified)."""



    entity_ids = list(_entities.keys())[:20]







    # Simple Q-table



    Q: Dict[Tuple[str, str], float] = {}







    for episode in range(request.episodes):



        # Random start



        state = random.choice(entity_ids)







        for step in range(request.max_steps):



            # Epsilon-greedy exploration



            if random.random() < request.epsilon:



                action = random.choice(_get_rl_actions(state)) if _get_rl_actions(state) else None



            else:



                # Greedy



                best_action = None



                best_q = float("-inf")







                for a in _get_rl_actions(state):



                    q_val = Q.get((state, a), 0.0)



                    if q_val > best_q:



                        best_q = q_val



                        best_action = a







                action = best_action







            if not action:



                break







            # Take action



            reward, next_state = _rl_step_reward(state, action)







            # Q-update



            max_next_q = max(Q.get((next_state, a), 0.0) for a in _get_rl_actions(next_state))



            Q[(state, action)] = Q.get((state, action), 0.0) + 0.1 * (reward + 0.9 * max_next_q - Q.get((state, action), 0.0))







            state = next_state







    # Get best policy



    policy: Dict[str, str] = {}



    for eid in entity_ids:



        actions = _get_rl_actions(eid)



        if actions:



            best = max(actions, key=lambda a: Q.get((eid, a), 0.0))



            policy[eid] = best







    return {



        "episodes": request.episodes,



        "max_steps": request.max_steps,



        "policy_size": len(policy),



    }











@router.post("/rl/policy", response_model=Dict)



async def get_rl_policy(entity_id: str) -> Dict:



    """Get optimal policy for entity."""



    actions = _get_rl_actions(entity_id)







    # Simple greedy policy



    best_action = max(actions, key=lambda a: random.random()) if actions else None







    return {



        "entity": entity_id,



        "recommended_action": best_action,



        "available_actions": actions,



    }











