# Dynamic Graph Updates (v1.59)



# =============================================================================







_dynamic_cache: Dict[str, Dict] = {}











class DynamicUpdateRequest(BaseModel):



    """Dynamic graph update."""



    entity_id: str



    change_type: str  # add, update, delete



    properties: Optional[Dict] = None











class BatchUpdateRequest(BaseModel):



    """Batch dynamic updates."""



    updates: List[DynamicUpdateRequest]



    atomic: bool = True











@router.post("/dynamic/update", response_model=Dict)



async def dynamic_update(request: DynamicUpdateRequest) -> Dict:



    """Dynamically update graph."""



    entity_id = request.entity_id







    if request.change_type == "add":



        if entity_id in _entities:



            return {"status": "error", "message": "Entity exists"}







        _entities[entity_id] = request.properties or {"id": entity_id}



        return {"status": "added", "entity_id": entity_id}







    elif request.change_type == "update":



        if entity_id not in _entities:



            return {"status": "error", "message": "Entity not found"}







        _entities[entity_id].update(request.properties or {})



        return {"status": "updated", "entity_id": entity_id}







    elif request.change_type == "delete":



        if entity_id not in _entities:



            return {"status": "error", "message": "Entity not found"}







        del _entities[entity_id]



        return {"status": "deleted", "entity_id": entity_id}







    else:



        return {"status": "error", "message": "Unknown change_type"}











@router.post("/dynamic/batch", response_model=Dict)



async def batch_dynamic_update(request: BatchUpdateRequest) -> Dict:



    """Batch dynamic updates."""



    results = []







    for update in request.updates:



        result = await dynamic_update(update)



        results.append(result)







        if request.atomic and result.get("status") == "error":



            break







    return {



        "total": len(request.updates),



        "results": results,



    }











@router.post("/dynamic/undo", response_model=Dict)



async def undo_last_change() -> Dict:



    """Undo last change (simplified)."""



    # This would require storing history



    return {"status": "not_implemented", "message": "Would require history storage"}











@router.get("/dynamic/summary", response_model=Dict)



async def get_dynamic_summary() -> Dict:



    """Get dynamic update summary."""



    return {



        "dynamic_updates": len(_dynamic_cache),



        "total_entities": len(_entities),



    }











