# Incremental Embedding Updates (v1.59)



# =============================================================================







_incremental_cache: Dict[str, Dict] = {}











class IncrementalUpdateRequest(BaseModel):



    """Incremental embedding update."""



    entity_ids: List[str]



    method: str = "sgd"  # sgd, adam











class StreamingEmbeddingsRequest(BaseModel):



    """Streaming embeddings."""



    batch_size: int = 10



    window_size: int = 5











def _incremental_sgd_update(



    entity_ids: List[str],



    learning_rate: float = 0.01



) -> Dict:



    """Update embeddings using SGD."""



    embeddings: Dict[str, List[float]] = {}







    for entity_id in entity_ids:



        # Get neighbors



        neighbors = []



        for rel in _relations.values():



            from_ent = rel.get("from_entity")



            to_ent = rel.get("to_entity")







            if from_ent == entity_id:



                neighbors.append(to_ent)



            elif to_ent == entity_id:



                neighbors.append(from_ent)







        if not neighbors:



            # Random embedding



            embeddings[entity_id] = [random.random() for _ in range(64)]



        else:



            # Average neighbor embeddings



            neighbor_embeddings = []







            for neighbor in neighbors[:5]:



                if neighbor in _entities:



                    neighbor_embeddings.append(



                        [random.random() for _ in range(64)]



                    )







            if neighbor_embeddings:



                avg = [



                    sum(e[i] for e in neighbor_embeddings) / len(neighbor_embeddings)



                    for i in range(64)



                ]



                # SGD-style update



                updated = [



                    avg[i] + learning_rate * (random.random() - 0.5)



                    for i in range(64)



                ]



                embeddings[entity_id] = updated



            else:



                embeddings[entity_id] = [random.random() for _ in range(64)]







    return {



        "method": "sgd",



        "updated_count": len(embeddings),



        "embeddings": embeddings,



    }











@router.post("/incremental/update", response_model=Dict)



async def incremental_embedding_update(request: IncrementalUpdateRequest) -> Dict:



    """Update embeddings incrementally."""



    if request.method == "sgd":



        result = _incremental_sgd_update(request.entity_ids)







    cache_key = f"inc_{len(request.entity_ids)}"



    _incremental_cache[cache_key] = result







    return {



        "method": request.method,



        "entity_count": len(request.entity_ids),



    }











@router.post("/incremental/stream", response_model=Dict)



async def streaming_embeddings(request: StreamingEmbeddingsRequest) -> Dict:



    """Generate streaming embeddings."""



    entity_ids = list(_entities.keys())[:request.batch_size]







    # Sliding window



    embeddings = {}







    for i in range(len(entity_ids)):



        window = entity_ids[max(0, i - request.window_size):i + request.window_size]







        # Average inside window



        emb = [random.random() for _ in range(64)]



        embeddings[entity_ids[i]] = emb







    return {



        "batch_size": request.batch_size,



        "window_size": request.window_size,



        "streaming_embeddings": embeddings,



    }











@router.get("/incremental/summary", response_model=Dict)



async def get_incremental_summary() -> Dict:



    """Get incremental embedding summary."""



    return {



        "cached_updates": len(_incremental_cache),



        "total_entities": len(_entities),



    }











