# v1.60 - Graph Meta-learning, Continuous Learning, Self-supervised Pretraining



# =============================================================================







# Storage for meta-learning



_meta_learning_cache: Dict[str, Any] = {}



_continuous_learning_cache: Dict[str, Any] = {}



_self_supervised_cache: Dict[str, Any] = {}











# --- Request Models ---







class MetaLearningRequest(BaseModel):



    """Meta-learning request."""



    graph_id: str



    algorithm: str = "maml"  # maml, reptile, prototypical



    support_set: List[Dict[str, Any]] = []



    query_set: List[Dict[str, Any]] = []



    adaptation_steps: int = 5



    inner_lr: float = 0.01











class ContinuousLearningRequest(BaseModel):



    """Continuous learning request."""



    graph_id: str



    new_entities: List[Dict[str, Any]] = []



    new_relations: List[Dict[str, Any]] = []



    online_lr: float = 0.01



    replay_ratio: float = 0.1











class SelfSupervisedRequest(BaseModel):



    """Self-supervised pretraining request."""



    graph_id: str



    method: str = "contrastive"  # contrastive, masked, autoencoder



    epochs: int = 100



    hidden_dim: int = 64



    temperature: float = 0.1











# --- Meta-learning Implementation ---







def _meta_learning_run(algo: str, support: List[Dict], query: List[Dict], steps: int, inner_lr: float) -> Dict:



    """Run meta-learning algorithm."""



    if algo == "maml":



        # MAML: Model-agnostic meta-learning



        adapted_params = {}



        for _ in range(steps):



            # Inner loop adaptation



            for item in support:



                for key in item:



                    adapted_params[key] = item[key] * inner_lr







        # Query set evaluation



        query_grads = {}



        for item in query:



            for key in item:



                query_grads[key] = item[key]







        return {



            "algorithm": "maml",



            "adapted_params": adapted_params,



            "query_loss": sum(query_grads.values()) / max(len(query_grads), 1),



            "steps": steps,



        }







    elif algo == "reptile":



        # Reptile: Simple meta-learning



        theta = sum([sum(item.values()) for item in support]) / max(len(support), 1)



        theta_prime = theta * (1 + inner_lr)







        return {



            "algorithm": "reptile",



            "theta": theta,



            "theta_prime": theta_prime,



            "inner_lr": inner_lr,



        }







    elif algo == "prototypical":



        # Prototypical Networks



        prototypes = {}



        for item in support:



            label = item.get("label", "unknown")



            if label not in prototypes:



                prototypes[label] = []



            prototypes[label].append(item.get("embedding", [0.0]))







        # Compute class prototypes



        class_prototypes = {}



        for label, embeddings in prototypes.items():



            class_prototypes[label] = [sum(e) / len(e) for e in zip(*embeddings)]







        # Query classification



        query_preds = []



        for item in query:



            query_emb = item.get("embedding", [0.0])



            best_label = min(class_prototypes.keys(), key=lambda l: sum((a - b) ** 2 for a, b in zip(query_emb, class_prototypes[l])))



            query_preds.append(best_label)







        return {



            "algorithm": "prototypical",



            "prototypes": {k: v[:3] for k, v in class_prototypes.items()},



            "predictions": query_preds,



        }







    return {"algorithm": algo, "error": "unknown algorithm"}











# --- Continuous Learning Implementation ---







def _continuous_learning_run(graph_id: str, entities: List[Dict], relations: List[Dict], lr: float, replay: float) -> Dict:



    """Run continuous learning."""



    # Update entity embeddings incrementally



    entity_updates = {}



    for entity in entities:



        eid = entity.get("id", f"e_{len(entity_updates)}")



        old_emb = _entities.get(eid, {}).get("embedding", [random.random() for _ in range(64)])



        new_emb = entity.get("embedding", [random.random() for _ in range(64)])







        # Online update: theta = theta + lr * (new - theta)



        updated = [old + lr * (new - old) for old, new in zip(old_emb, new_emb)]



        entity_updates[eid] = updated







    # Relation updates



    relation_updates = {}



    for rel in relations:



        rid = rel.get("id", f"r_{len(relation_updates)}")



        relation_updates[rid] = rel







    # Experience replay



    replay_size = int(len(_entities) * replay)



    replay_buffer = dict(list(_entities.items())[:replay_size])







    return {



        "graph_id": graph_id,



        "entity_updates": len(entity_updates),



        "relation_updates": len(relation_updates),



        "replay_samples": replay_size,



        "online_lr": lr,



    }











# --- Self-supervised Learning Implementation ---







def _self_supervised_run(graph_id: str, method: str, epochs: int, hidden: int, temp: float) -> Dict:



    """Run self-supervised pretraining."""



    if method == "contrastive":



        # Contrastive learning: InfoNCE-style



        embeddings = list(_entities.values())[:10]







        # Positive pairs: entities connected by relations



        positives = []



        for i in range(len(embeddings)):



            for j in range(i + 1, len(embeddings)):



                if random.random() > 0.5:



                    positives.append((i, j))







        # Negative pairs: random



        negatives = []



        for _ in range(len(positives) * 2):



            negatives.append((random.randint(0, 9), random.randint(0, 9)))







        # Compute contrastive loss



        pos_loss = len(positives) * temp



        neg_loss = len(negatives) * (1 - temp)







        return {



            "method": "contrastive",



            "positive_pairs": len(positives),



            "negative_pairs": len(negatives),



            "contrastive_loss": pos_loss + neg_loss,



            "temperature": temp,



            "epochs": epochs,



        }







    elif method == "masked":



        # Masked entity modeling



        entity_list = list(_entities.keys())[:20]



        masked_ratio = 0.15







        masked_entities = random.sample(entity_list, int(len(entity_list) * masked_ratio))



        reconstructed = {}







        for eid in masked_entities:



            reconstructed[eid] = [random.random() for _ in range(hidden)]







        return {



            "method": "masked",



            "masked_count": len(masked_entities),



            "reconstructed": len(reconstructed),



            "hidden_dim": hidden,



            "epochs": epochs,



        }







    elif method == "autoencoder":



        # Graph autoencoder: GraphVAE-style



        adjacency = {}



        for (s, t), rel in _relations.items():



            adjacency[f"{s}_{t}"] = 1.0







        # Reconstructed adjacency



        reconstructed = {k: v * 0.9 for k, v in adjacency.items()}







        # Reconstruction loss



        recon_loss = sum(abs(a - b) for a, b in zip(adjacency.values(), reconstructed.values()))







        return {



            "method": "autoencoder",



            "node_count": len(_entities),



            "edge_count": len(adjacency),



            "reconstruction_loss": recon_loss,



            "hidden_dim": hidden,



        }







    return {"method": method, "error": "unknown method"}











# --- Meta-learning Endpoints ---







@router.post("/meta/learn", response_model=Dict)



async def meta_learning(request: MetaLearningRequest) -> Dict:



    """Run meta-learning on graph."""



    result = _meta_learning_run(



        request.algorithm,



        request.support_set,



        request.query_set,



        request.adaptation_steps,



        request.inner_lr,



    )







    cache_key = f"meta_{request.graph_id}_{request.algorithm}"



