# v1.61 - Temporal Reasoning, Causality Inference, Multi-hop Reasoning



# =============================================================================







# Storage for temporal/causal/multi-hop



_temporal_cache: Dict[str, Any] = {}



_causal_cache: Dict[str, Any] = {}



_multihop_cache: Dict[str, Any] = {}











# --- Request Models ---







class TemporalReasoningRequest(BaseModel):



    """Temporal reasoning request."""



    graph_id: str



    method: str = "temporal_order"  # temporal_order, time_series, sequence



    entities: List[str] = []



    window: int = 10











