# --- Graph Pooling Implementation







_pooling_cache: Dict[str, Dict] = {}











def _pooling_run(pType: str, ratio: float, num_layers: int, hidden_dim: int) -> Dict:



    """Run graph pooling."""



    if pType == "diffpool":



        # DiffPool - Differentiable Pooling



        return {



            "type": "diffpool",



            "ratio": ratio,



            "num_layers": num_layers,



            "hidden_dim": hidden_dim,



            "assignment_dim": int(hidden_dim * ratio),



            "level": num_layers,



            "aggregator": "mean",



        }







    elif pType == "topk":



        # TopK Pooling



        return {



            "type": "topk",



            "ratio": ratio,



            "num_layers": num_layers,



            "hidden_dim": hidden_dim,



            "score_func": "sigmoid",



            "sampling": "degree",



        }







    else:  # sag - Self-Attention Graph Pooling



        return {



            "type": "sag",



            "ratio": ratio,



            "num_layers": num_layers,



            "hidden_dim": hidden_dim,



            "attention": {



                "heads": 8,



                "dropout": ratio * 0.5,



            },



            "score_func": "scaled_dot",



        }











