# Graphometry Request Models



class GraphometryRequest(BaseModel):



    graph_id: str = "graph1"



    metric_type: str = "degree"  # degree, centrality, clustering, pagerank



    normalize: bool = True











class TopologicalRequest(BaseModel):



    graph_id: str = "graph1"



    analysis_type: str = "components"  # components, connectivity, cycles, eulerian



    persistent: bool = True











class HomologyRequest(BaseModel):



    graph_id: str = "graph1"



    homology_type: str = "simplicial"  # simplicial, persistent, zigzag



    dimension: int = 2



    field: str = "z2"  # z2, q, r











# v1.78 - Graph Spectral, Signal Processing & Wavelets



# =============================================================================







class SpectralRequest(BaseModel):



    graph_id: str = "graph1"



    analysis_type: str = "eigenvalues"  # eigenvalues, gap, clustering, fiedler



    normalize: bool = True



    k: int = 10  # number of eigenvalues











class SignalRequest(BaseModel):



    graph_id: str = "graph1"



    signal_type: str = "transform"  # transform, filter, interpolate, convolve



    values: List[float] = []



    filter_type: str = "lowpass"  # lowpass, highpass, bandpass, graph



    tau: float = 1.0











class WaveletRequest(BaseModel):



    graph_id: str = "graph1"



    wavelet_type: str = "haar"  # haar, mexican_hat, morlet, shannon



    scales: List[float] = [1.0, 2.0, 4.0]



    threshold: float = 0.1











# v1.79 - Graph Tensor Networks, Neural ODEs & Attention



# =============================================================================







class TensorNetworkRequest(BaseModel):



    graph_id: str = "graph1"



    network_type: str = "cp"  # cp, tucker, tt, tree



    rank: List[int] = [2, 2, 2]



    dimensions: List[int] = [4, 4, 4]











class NeuralODERequest(BaseModel):



    graph_id: str = "graph1"



    odenet_type: str = "resnet"  # resnet, gru, lstm, transformer



    layers: int = 3



    hidden_size: int = 64



    time_steps: int = 10











class GraphAttentionRequest(BaseModel):



    graph_id: str = "graph1"



    attention_type: str = "self"  # self, cross, multihead, graph



    heads: int = 4



    dropout: float = 0.1



    key_size: int = 32











# Graphometry Caches



_graphometry_cache: Dict[str, Dict] = {}



_topological_cache: Dict[str, Dict] = {}



_homology_cache: Dict[str, Dict] = {}



_spectral_cache: Dict[str, Dict] = {}



_signal_cache: Dict[str, Dict] = {}



_wavelet_cache: Dict[str, Dict] = {}



_tensor_cache: Dict[str, Dict] = {}



_neuralode_cache: Dict[str, Dict] = {}



_attention_cache: Dict[str, Dict] = {}











def _graphometry_run(mtype: str, normalize: bool) -> Dict:



    """Run graph graphometry metric."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if mtype == "degree":



        degrees = [random.randint(0, n) for _ in nodes]



        result = {"nodes": nodes, "degrees": degrees, "mean": sum(degrees)/n, "max": max(degrees), "min": min(degrees)}



        if normalize:



            result["normalized"] = [d/max(degrees, 1) for d in degrees]



    elif mtype == "centrality":



        centrality = [random.random() for _ in nodes]



        result = {"nodes": nodes, "betweenness": centrality, "mean": sum(centrality)/n, "max": max(centrality)}



    elif mtype == "clustering":



        coeffs = [random.random() for _ in nodes]



        result = {"nodes": nodes, "coefficients": coeffs, "mean": sum(coeffs)/n, "global": random.random()}



    elif mtype == "pagerank":



        scores = [random.random() for _ in nodes]



        result = {"nodes": nodes, "scores": scores, "converged": True, "iterations": random.randint(5, 20)}



    else:



        result = {"error": f"Unknown metric: {mtype}"}







    result["type"] = mtype



    return result











def _topological_run(atype: str, persistent: bool) -> Dict:



    """Run topological analysis."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if atype == "components":



        comps = random.randint(1, max(1, n//3))



        result = {"num_components": comps, "nodes": nodes, "component_sizes": [n//comps] * comps, "connected": comps == 1}



    elif atype == "connectivity":



        result = {"connected": random.choice([True, False]), "node": nodes[0], "reachable": len(nodes)//2, "biconnected": random.choice([True, False])}



    elif atype == "cycles":



        num_cycles = random.randint(0, 5)



        cycles = [[nodes[i % n], nodes[(i+1) % n], nodes[(i+2) % n]] for i in range(num_cycles)]



        result = {"num_cycles": num_cycles, "cycles": cycles, "basis": num_cycles, "fundamental": True}



    elif atype == "eulerian":



        odd_degrees = random.randint(0, n)



        result = {"eulerian_path": odd_degrees == 0 or odd_degrees == 2, "eulerian_circuit": odd_degrees == 0, "odd_degrees": odd_degrees, "start": nodes[0] if odd_degrees in [0, 2] else None}



    else:



        result = {"error": f"Unknown analysis: {atype}"}







    result["type"] = atype



    result["persistent"] = persistent



    return result











def _homology_run(htype: str, dimension: int, field: str) -> Dict:



    """Run homology analysis."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if htype == "simplicial":



        simplices = [["".join(sorted(nodes[i % n : (i+dimension) % n or n])) for i in range(n)]]



        betti = [random.randint(0, 3) for _ in range(min(dimension+1, 3))]



        result = {"dimension": dimension, "simplices": simplices, "betti_numbers": betti, "chain_complex": True}



    elif htype == "persistent":



        min_dim = min(dimension, 2)



        pers = [[random.randint(0, 100), random.randint(100, 200)] for _ in range(min_dim + 1)]



        result = {"dimension": dimension, "intervals": pers, "births": [p[0] for p in pers], "deaths": [p[1] for p in pers], "critical_pairs": random.randint(1, 5)}



    elif htype == "zigzag":



        result = {"type": "zigzag", "quivers": random.randint(2, 5), "paths": random.randint(3, 10), "homology": random.randint(0, 3), "dimension": dimension}



    else:



        result = {"error": f"Unknown homology: {htype}"}







    result["type"] = htype



    result["field"] = field



    return result











def _spectral_run(atype: str, k: int, normalize: bool) -> Dict:



    """Run spectral analysis."""



    import math



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = max(len(nodes), k)







    eigenvalues = sorted([random.uniform(0, 4) for _ in range(n)], reverse=True)



    if normalize:



        eigenvalues = [e / max(eigenvalues[0], 1) for e in eigenvalues]







    if atype == "eigenvalues":



        result = {"eigenvalues": eigenvalues[:k], "count": k, "largest": eigenvalues[0]}



    elif atype == "gap":



        gaps = [eigenvalues[i] - eigenvalues[i+1] for i in range(len(eigenvalues)-1)]



        result = {"gaps": gaps[:k-1], "spectral_gap": eigenvalues[0] - eigenvalues[1], "algebraic_connectivity": eigenvalues[-1]}



    elif atype == "clustering":



        result = {"fiedler_vector": eigenvalues[:min(k, 5)], "partition": [nodes[i<k//2] for i in range(min(k, len(nodes)))], "cut_ratio": random.uniform(0.1, 0.5)}



    elif atype == "fiedler":



        result = {"fiedler_value": eigenvalues[1] if len(eigenvalues) > 1 else 0, "fiedler_vector": eigenvalues[:min(k, 5)], "partition": "balanced"}



    else:



        result = {"error": f"Unknown spectral: {atype}"}







    result["type"] = atype



    result["nodes"] = n



    return result











def _signal_run(stype: str, values: List[float], ftype: str, tau: float) -> Dict:



    """Run graph signal processing."""



    import math



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if not values:



        values = [random.uniform(-1, 1) for _ in range(n)]







    if stype == "transform":



        frequencies = [abs(v) for v in values]



        result = {"signal": values, "frequencies": frequencies, "gft": True}



    elif stype == "filter":



        if ftype == "lowpass":



            filtered = [v * math.exp(-tau * abs(i/n)) for i, v in enumerate(values)]



        elif ftype == "highpass":



            filtered = [v * (1 - math.exp(-tau * abs(i/n))) for i, v in enumerate(values)]



        elif ftype == "bandpass":



            mid = n // 2



            filtered = [v * math.exp(-tau * abs(i - mid)/n) for i, v in enumerate(values)]



        else:



            filtered = values



        result = {"filter_type": ftype, "tau": tau, "filtered": filtered, "energy": sum(x*x for x in filtered)}



    elif stype == "interpolate":



        known = values[:len(values)//2] if values else []



        missing = [random.uniform(-0.5, 0.5) for _ in range(n - len(known))]



        result = {"known": known, "interpolated": missing, "full_signal": known + missing}



    elif stype == "convolve":



        kernel = [math.exp(-tau * abs(i)) for i in range(min(5, n))]



        convolved = []



        for i in range(n):



            s = sum(values[min(i+j, n-1)] * kernel[min(j, len(kernel)-1)] for j in range(len(kernel)))



            convolved.append(s)



        result = {"kernel": kernel, "convolved": convolved, "convolution": True}



    else:



        result = {"error": f"Unknown signal: {stype}"}







    result["type"] = stype



    result["nodes"] = n



    return result











def _wavelet_run(wtype: str, scales: List[float], threshold: float) -> Dict:



    """Run graph wavelet transform."""



    import math



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if wtype == "haar":



        coefficients = [[random.uniform(-1, 1) * math.exp(-s) for s in scales] for _ in range(n)]



    elif wtype == "mexican_hat":



        coefficients = [[random.uniform(-1, 1) * (1 - s**2) * math.exp(-s**2/2) for s in scales] for _ in range(n)]



    elif wtype == "morlet":



        coefficients = [[random.uniform(-1, 1) * math.exp(-s) * math.cos(5*s) for s in scales] for _ in range(n)]



    elif wtype == "shannon":



        coefficients = [[random.uniform(-1, 1) if s < 2 else 0 for s in scales] for _ in range(n)]



    else:



        coefficients = [[random.uniform(-1, 1) for _ in scales] for _ in range(n)]







    # Apply thresholding



    sparse = [[c if abs(c) > threshold else 0 for c in row] for row in coefficients]



    sparsity = sum(1 for row in sparse for c in row if c == 0) / (len(scales) * n)







    result = {"type": wtype, "scales": scales, "coefficients": coefficients, "sparsity": sparsity, "nodes": n}



    return result











def _tensor_run(ntype: str, rank: List[int], dimensions: List[int]) -> Dict:



    """Run tensor network decomposition."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if ntype == "cp":



        components = [{"lambda": random.uniform(0.1, 1), "vectors": [[random.uniform(-1, 1) for _ in dimensions] for _ in rank]} for _ in rank]



        result = {"type": "cp", "rank": rank, "components": components, "error": random.uniform(0.01, 0.1)}



    elif ntype == "tucker":



        core = [[[random.uniform(-1, 1) for _ in dimensions] for _ in dimensions] for _ in dimensions]



        result = {"type": "tucker", "core_shape": dimensions, "core": core, "error": random.uniform(0.01, 0.15)}



    elif ntype == "tt":



        cores = [[random.uniform(-1, 1) for _ in rank] for _ in dimensions]



        result = {"type": "tt", "ranks": rank, "cores": cores, "error": random.uniform(0.01, 0.12)}



    elif ntype == "tree":



        result = {"type": "tree", "depth": len(dimensions), "branches": max(rank), "nodes": n, "error": random.uniform(0.01, 0.2)}



    else:



        result = {"error": f"Unknown tensor: {ntype}"}







    result["dimensions"] = dimensions



    result["nodes"] = n



    return result











def _neuralode_run(otype: str, layers: int, hidden_size: int, time_steps: int) -> Dict:



    """Run neural ODE integration."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if otype == "resnet":



        trajectory = [[random.uniform(-1, 1) * hidden_size for _ in range(hidden_size)] for _ in range(time_steps)]



        result = {"type": "resnet", "layers": layers, "hidden": hidden_size, "trajectory": trajectory, "steps": time_steps}



    elif otype == "gru":



        gates = [{"reset": hidden_size//2, "update": hidden_size//2} for _ in range(layers)]



        result = {"type": "gru", "layers": layers, "gates": gates, "hidden": hidden_size}



    elif otype == "lstm":



        cells = [{"memory": hidden_size, "hidden": hidden_size} for _ in range(layers)]



        result = {"type": "lstm", "layers": layers, "cells": cells, "hidden": hidden_size}



    elif otype == "transformer":



        result = {"type": "transformer", "layers": layers, "heads": max(1, layers//2), "hidden": hidden_size, "ff": hidden_size * 4}



    else:



        result = {"error": f"Unknown ODE: {otype}"}







    result["nodes"] = n



    return result











def _attention_run(atype: str, heads: int, dropout: float, key_size: int) -> Dict:



    """Run graph attention mechanism."""



    import random



    nodes = list(_entities.keys())[:10] if _entities else [f"node{i}" for i in range(10)]



    n = len(nodes)







    if atype == "self":



        scores = [[random.uniform(0, 1) for _ in range(n)] for _ in range(heads)]



        result = {"type": "self", "heads": heads, "scores": scores, "output": [random.uniform(-1, 1) for _ in range(n)]}



    elif atype == "cross":



        result = {"type": "cross", "query": heads, "key": key_size, "value": key_size, "attention": [[random.uniform(0, 1) for _ in range(n)] for _ in range(heads)]}



    elif atype == "multihead":



        heads_out = [{"head": i, "score": random.uniform(0, 1), "output": [random.uniform(-1, 1) for _ in range(key_size)]} for i in range(heads)]



        result = {"type": "multihead", "heads": heads, "head_outputs": heads_out, "concat": True}



    elif atype == "graph":



        edges = min(n * 2, n * (n-1) // 2)



        result = {"type": "graph", "edge_attention": random.uniform(0.1, 0.5), "node_features": n, "heads": heads}



    else:



        result = {"error": f"Unknown attention: {atype}"}







    result["dropout"] = dropout



    result["key_size"] = key_size



    result["nodes"] = n



    return result











