@router.post("/alignment", response_model=Dict)



async def graph_alignment(



    graph_id: str,



    target_graph_id: str,



    alignment_type: AlignmentType = AlignmentType.NODE,



) -> Dict:



    """Align two graphs."""



    entity = get_or_create_entity(graph_id)



    target = get_or_create_entity(target_graph_id)







    adj1 = entity.get("adj", [[0]])



    adj2 = target.get("adj", [[0]])







    nodes1, nodes2 = len(adj1), len(adj2)



    min_nodes = min(nodes1, nodes2)







    node_mapping = {i: i % min_nodes for i in range(nodes1)}







    _align_cache[f"{graph_id}_{target_graph_id}_{alignment_type.value}"] = {



        "graph_id": graph_id,



        "target_id": target_graph_id,



        "alignment_type": alignment_type.value,



        "node_mapping": node_mapping,



    }







    return {



        "graph_id": graph_id,



        "target_graph_id": target_graph_id,



        "alignment_type": alignment_type.value,



        "node_mapping": node_mapping,



    }











