@router.post("/alignment/edge", response_model=Dict)



async def edge_alignment(



    graph_id: str,



    target_graph_id: str,



) -> Dict:



    """Align edges between graphs."""



    entity = get_or_create_entity(graph_id)



    target = get_or_create_entity(target_graph_id)







    adj1 = entity.get("adj", [[0]])



    adj2 = target.get("adj", [[0]])







    edges1 = sum(len([a for a in adj if a]) for adj in [adj1])



    edges2 = sum(len([a for a in adj if a]) for adj in [adj2])







    aligned = min(edges1, edges2)







    return {



        "graph_id": graph_id,



        "target_graph_id": target_graph_id,



        "aligned_edges": aligned,



    }











@router.post("/alignment/spectral", response_model=Dict)



async def spectral_alignment(



    graph_id: str,



    target_graph_id: str,



    k: int = 5,



) -> Dict:



    """Spectral graph alignment."""



    entity = get_or_create_entity(graph_id)



    target = get_or_create_entity(target_graph_id)







    adj1 = entity.get("adj", [[0]])



    adj2 = target.get("adj", [[0]])







    eigenvals1 = [hash(f"{graph_id}_{i}") % 100 / 100 for i in range(k)]



    eigenvals2 = [hash(f"{target_graph_id}_{i}") % 100 / 100 for i in range(k)]







    alignment_score = sum(e1 * e2 for e1, e2 in zip(eigenvals1, eigenvals2)) / k







    return {



        "graph_id": graph_id,



        "target_graph_id": target_graph_id,



        "k": k,



        "eigenvals1": eigenvals1,



        "eigenvals2": eigenvals2,



        "alignment_score": alignment_score,



    }











