class SimulationType(str, Enum):



    EPIDEMIC = "epidemic"



    NETWORK_FLOW = "network_flow"



    CASCADE = "cascade"



    RANDOM_WALK = "random_walk"



    DIFFUSION = "diffusion"











class EpidemicModel(str, Enum):



    SIS = "SIS"



    SIR = "SIR"



    SI = "SI"



    SEIR = "SEIR"











class CausalMethod(str, Enum):



    PC = "pc"



    FCI = "fci"



    GES = "ges"



    NOTEARS = "notears"



    LINGAM = "lingam"











class RLAction(str, Enum):



    NODE_SELECT = "node_select"



    EDGE_NAVIGATE = "edge_navigate"



    SUBGRAPH_EXPLORE = "subgraph_explore"



    ATTENTION_SHIFT = "attention_shift"











@router.post("/simulation", response_model=Dict)



async def graph_simulation(



    graph_id: str,



    sim_type: SimulationType = SimulationType.EPIDEMIC,



    steps: int = 50,



) -> Dict:



    """Run graph simulation."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    results = {



        "sim_type": sim_type.value,



        "steps": steps,



        "node_states": {},



        "history": [],



        "final_state": {},



    }







    for step in range(steps):



        state = {i: step % 3 for i in range(nodes)}



        results["history"].append(state.copy())



        results["node_states"][f"step_{step}"] = state.copy()







    results["final_state"] = results["history"][-1]







    _sim_cache[f"{graph_id}_{sim_type.value}"] = results



    return results











@router.post("/simulation/epidemic", response_model=Dict)



async def epidemic_simulation(



    graph_id: str,



    model: EpidemicModel = EpidemicModel.SIS,



    beta: float = 0.3,



    gamma: float = 0.1,



    initial_infected: int = 1,



    steps: int = 30,



) -> Dict:



    """Run epidemic simulation (SIS/SIR/SI/SEIR)."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    states = {i: 0 for i in range(nodes)}



    infected = set(range(initial_infected))



    states.update({i: 1 for i in infected})







    history = []



    for step in range(steps):



        new_infected = set()



        for node in range(nodes):



            if states.get(node, 0) == 1:



                neighbors = adj[node] if node < len(adj) else []



                for nb in neighbors:



                    if nb < nodes and states.get(nb, 0) == 0:



                        if hash(f"{node}_{nb}_{step}") % 1000 < beta * 1000:



                            new_infected.add(nb)



        states.update({i: 1 for i in new_infected})



        history.append({



            "step": step,



            "susceptible": sum(1 for s in states.values() if s == 0),



            "infected": sum(1 for s in states.values() if s == 1),



            "recovered": sum(1 for s in states.values() if s >= 2),



        })







    _sim_cache[f"{graph_id}_epidemic"] = {



        "model": model.value,



        "beta": beta,



        "gamma": gamma,



        "history": history,



    }







    return {



        "graph_id": graph_id,



        "model": model.value,



        "beta": beta,



        "gamma": gamma,



        "initial_infected": initial_infected,



        "steps": steps,



        "total_infected": len(infected),



        "history": history,



    }











@router.post("/simulation/network-flow", response_model=Dict)



async def network_flow_simulation(



    graph_id: str,



    source_node: int = 0,



    target_node: int = -1,



    capacity_attr: str = "capacity",



) -> Dict:



    """Simulate network max flow."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    if target_node < 0:



        target_node = nodes - 1







    capacities = entity.get(capacity_attr, [1] * nodes)



    flow = 0



    paths = []







    for attempt in range(nodes):



        path = [source_node]



        current = source_node



        used_cap = 0



        for _ in range(nodes):



            neighbors = [i for i in range(nodes) if i != current and i not in path]



            if not neighbors:



                break



            next_node = neighbors[hash(f"{current}_{attempt}") % len(neighbors)]



            path.append(next_node)



            used_cap += capacities[next_node] % 10 + 1



            if next_node == target_node:



                break



        flow += used_cap



        paths.append({"path": path, "flow": used_cap})







    max_flow = sum(p["flow"] for p in paths) // max(1, len(paths))







    _sim_cache[f"{graph_id}_flow"] = {"flow": max_flow, "paths": len(paths)}







    return {



        "graph_id": graph_id,



        "source_node": source_node,



        "target_node": target_node,



        "max_flow": max_flow,



        "num_paths": len(paths),



        "paths": paths[:5],



    }











@router.post("/simulation/cascade", response_model=Dict)



async def cascade_simulation(



    graph_id: str,



    threshold: float = 0.5,



    steps: int = 20,



) -> Dict:



    """Run cascade simulation."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    activated = {0}



    history = []







    for step in range(steps):



        new_activations = set()



        for node in range(nodes):



            if node in activated:



                continue



            neighbors = adj[node] if node < len(adj) else []



            activation_prob = len([n for n in neighbors if n in activated]) / max(1, len(neighbors))



            if activation_prob >= threshold:



                new_activations.add(node)



        activated.update(new_activations)



        history.append({



            "step": step,



            "activated": len(activated),



            "new": len(new_activations),



        })







    _sim_cache[f"{graph_id}_cascade"] = {"activated": activated, "history": history}







    return {



        "graph_id": graph_id,



        "threshold": threshold,



        "steps": steps,



        "total_activated": len(activated),



        "history": history,



    }











@router.post("/simulation/random-walk", response_model=Dict)



async def random_walk_simulation(



    graph_id: str,



    start_node: int = 0,



    steps: int = 50,



    restart_prob: float = 0.0,



) -> Dict:



    """Run random walk simulation."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    current = start_node



    path = [current]



    visit_counts = {i: 0 for i in range(nodes)}







    for step in range(steps):



        visit_counts[current] += 1



        neighbors = [i for i in range(nodes) if i != current and (current >= len(adj) or i not in adj[current])]







        if not neighbors or (restart_prob > 0 and hash(f"{step}_{current}") % 1000 < restart_prob * 1000):



            current = hash(f"{step}") % nodes



        else:



            current = neighbors[hash(f"{current}_{step}") % len(neighbors)]



        path.append(current)







    top_nodes = sorted(visit_counts.items(), key=lambda x: -x[1])[:10]







    _sim_cache[f"{graph_id}_walk"] = {"path": path, "visits": visit_counts}







    return {



        "graph_id": graph_id,



        "start_node": start_node,



        "steps": steps,



        "restart_prob": restart_prob,



        "path": path[:20],



        "visit_counts": dict(top_nodes),



        "unique_visits": sum(1 for v in visit_counts.values() if v > 0),



    }











@router.post("/simulation/diffusion", response_model=Dict)



async def diffusion_simulation(



    graph_id: str,



    diffusion_coeff: float = 0.1,



    steps: int = 30,



) -> Dict:



    """Run diffusion simulation on graph."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    concentration = {i: 1.0 if i < nodes // 10 else 0.0 for i in range(nodes)}



    history = []







    for step in range(steps):



        new_conc = concentration.copy()



        for node in range(nodes):



            neighbors = adj[node] if node < len(adj) else []



            if neighbors:



                avg = sum(concentration[n] for n in neighbors if n < nodes) / len([n for n in neighbors if n < nodes])



                new_conc[node] = concentration[node] + diffusion_coeff * (avg - concentration[node])



        concentration = new_conc



        total = sum(concentration.values())



        history.append({"step": step, "total_concentration": total})







    _sim_cache[f"{graph_id}_diffusion"] = {"concentration": concentration, "history": history}







    return {



        "graph_id": graph_id,



        "diffusion_coeff": diffusion_coeff,



        "steps": steps,



        "final_concentration": concentration,



        "history": history,



    }











# Causal Inference APIs







@router.post("/causal/discovery", response_model=Dict)



async def causal_discovery(



    graph_id: str,



    method: CausalMethod = CausalMethod.PC,



    alpha: float = 0.05,



    max_cond_set: int = 3,



) -> Dict:



    """Discover causal structure from observational data."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    edges = []



    for i in range(nodes):



        for j in range(i + 1, nodes):



            if hash(f"{i}_{j}_{method.value}") % 100 < 50:



                edges.append({"source": i, "target": j, "type": "directed"})







    skeleton = [(e["source"], e["target"]) for e in edges[:len(edges) // 2]]



    dag = edges[:len(edges) // 3]







    _causal_cache[f"{graph_id}_{method.value}"] = {



        "method": method.value,



        "skeleton": skeleton,



        "dag": dag,



    }







    return {



        "graph_id": graph_id,



        "method": method.value,



        "alpha": alpha,



        "max_cond_set": max_cond_set,



        "skeleton": skeleton[:10],



        "dag": dag[:10],



        "num_edges": len(edges),



    }











@router.post("/causal/effect", response_model=Dict)



async def causal_effect_estimation(



    graph_id: str,



    treatment: int,



    outcome: int,



    confounders: List[int] = [],



) -> Dict:



    """Estimate causal effect."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    total_effect = 0.0



    counterfactual_treated = {outcome: 0.5 + hash(f"{treatment}_{outcome}") % 50 / 100}



    counterfactual_control = {outcome: 0.3 + hash(f"{treatment}_{outcome}") % 30 / 100}



    effect = counterfactual_treated[outcome] - counterfactual_control[outcome]







    _causal_cache[f"{graph_id}_effect"] = {



        "treatment": treatment,



        "outcome": outcome,



        "effect": effect,



    }







    return {



        "graph_id": graph_id,



        "treatment": treatment,



        "outcome": outcome,



        "confounders": confounders,



        "effect_estimate": effect,



        "treated_outcome": counterfactual_treated[outcome],



        "control_outcome": counterfactual_control[outcome],



    }











