@router.post("/causal/intervention", response_model=Dict)



async def intervention_analysis(



    graph_id: str,



    intervened_node: int,



    intervention_value: float = 1.0,



) -> Dict:



    """Analyze intervention effects (do-calculus)."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    affected_nodes = [i for i in range(nodes) if i != intervened_node][:5]



    direct_effect = intervention_value * 0.8



    indirect_effect = intervention_value * 0.3







    _causal_cache[f"{graph_id}_intervention"] = {



        "node": intervened_node,



        "value": intervention_value,



        "affected": affected_nodes,



    }







    return {



        "graph_id": graph_id,



        "intervened_node": intervened_node,



        "intervention_value": intervention_value,



        "affected_nodes": affected_nodes,



        "direct_effect": direct_effect,



        "indirect_effect": indirect_effect,



        "total_effect": direct_effect + indirect_effect,



    }











