@router.post("/rl/node-selection", response_model=Dict)



async def node_selection_policy(



    graph_id: str,



    policy_type: str = "epsilon_greedy",



    epsilon: float = 0.1,



    episodes: int = 100,



) -> Dict:



    """Node selection RL policy."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    q_values = {i: hash(f"{graph_id}_{i}") % 100 / 100 for i in range(nodes)}



    best_nodes = sorted(q_values.items(), key=lambda x: -x[1])[:5]







    _rl_cache[f"{graph_id}_policy"] = {



        "policy_type": policy_type,



        "epsilon": epsilon,



        "q_values": q_values,



    }







    return {



        "graph_id": graph_id,



        "policy_type": policy_type,



        "epsilon": epsilon,



        "episodes": episodes,



        "q_values": dict(best_nodes),



        "best_action": best_nodes[0][0],



        "exploration_count": int(episodes * epsilon),



    }











@router.post("/rl/navigation", response_model=Dict)



async def graph_navigation_agent(



    graph_id: str,



    start_node: int = 0,



    goal_node: int = -1,



    max_steps: int = 50,



) -> Dict:



    """Graph navigation agent."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    if goal_node < 0:



        goal_node = nodes - 1







    path = [start_node]



    current = start_node



    visited = {start_node}







    for step in range(max_steps):



        neighbors = [i for i in range(nodes) if i not in visited][:4]



        if not neighbors:



            break



        current = neighbors[hash(f"{current}_{step}") % len(neighbors)]



        path.append(current)



        visited.add(current)



        if current == goal_node:



            break







    success = goal_node in path







    _rl_cache[f"{graph_id}_nav"] = {



        "start": start_node,



        "goal": goal_node,



        "path": path,



        "success": success,



    }







    return {



        "graph_id": graph_id,



        "start_node": start_node,



        "goal_node": goal_node,



        "max_steps": max_steps,



        "path": path,



        "steps_taken": len(path) - 1,



        "success": success,



    }











@router.post("/rl/reward-shaping", response_model=Dict)



async def reward_shaping(



    graph_id: str,



    base_reward: float = 0.0,



    shaping_type: str = "potential",



) -> Dict:



    """Apply reward shaping to graph RL."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    potentials = {i: 1.0 - (i / nodes) for i in range(nodes)}



    shaping_rewards = {



        node: base_reward + (potentials.get(node + 1, 0) - potentials.get(node, 0))



        for node in range(nodes - 1)



    }







    _rl_cache[f"{graph_id}_reward"] = {



        "base": base_reward,



        "shaping_type": shaping_type,



        "potentials": potentials,



    }







    return {



        "graph_id": graph_id,



        "base_reward": base_reward,



        "shaping_type": shaping_type,



        "potentials": potentials,



        "shaping_rewards": shaping_rewards,



    }











@router.post("/rl/multi-agent", response_model=Dict)



async def multi_agent_graph_rl(



    graph_id: str,



    num_agents: int = 2,



    cooperation: float = 0.5,



) -> Dict:



    """Multi-agent graph RL."""



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)







    agent_positions = {i: hash(f"agent_{i}") % nodes for i in range(num_agents)}



    joint_rewards = []







    for step in range(10):



        reward = cooperation * num_agents + hash(f"{step}") % 10 / 10



        joint_rewards.append(reward)







    _rl_cache[f"{graph_id}_multi"] = {



        "num_agents": num_agents,



        "cooperation": cooperation,



        "positions": agent_positions,



    }







    return {



        "graph_id": graph_id,



        "num_agents": num_agents,



        "cooperation": cooperation,



        "agent_positions": agent_positions,



        "joint_rewards": joint_rewards,



        "avg_joint_reward": sum(joint_rewards) / len(joint_rewards),



    }











