    num_perturbed = max(1, int(nodes * perturb_ratio))



    perturbed_nodes = list(range(num_perturbed))



    perturbation_deltas = {



        str(i): round(perturb_magnitude * (hash(f"feat_{i}") % 100 / 100 - 0.5) * 2, 4)



        for i in perturbed_nodes



    }







    result = {



        "graph_id": graph_id,



        "perturb_ratio": perturb_ratio,



        "perturb_magnitude": perturb_magnitude,



        "num_perturbed_nodes": num_perturbed,



        "perturbed_nodes": perturbed_nodes[:15],



        "perturbation_deltas": perturbation_deltas,



    }







    _attack_cache[f"{graph_id}_feat"] = result



