# =============================================================================



# v1.84 — Graph Neural Architecture Search (NAS)



# =============================================================================







class SearchStrategy(str, Enum):



    RANDOM = "random"



    EVOLUTIONARY = "evolutionary"



    DARTS = "darts"



    BAYESIAN = "bayesian"



    REINFORCE = "reinforce"



    GRAPH_CAS = "graph_cas"







class GNNLayerType(str, Enum):



    GCN = "gcn"



    GAT = "gat"



    SAGE = "sage"



    TRANSFORMER = "transformer"



    MORAN = "moran"



    SIGN = "sign"



    GIN = "gin"







class PoolType(str, Enum):



    MAX = "max"



    MEAN = "mean"



    ATTENTION = "attention"



    SORT = "sort"



    DIFFPOOL = "diffpool"







class PredictorType(str, Enum):



    REGRESSION = "regression"



    CLASSIFICATION = "classification"



    RANKING = "ranking"







_nas_cache: Dict[str, Any] = {}



_search_history: Dict[str, Any] = {}



_performance_predictor: Dict[str, Any] = {}











def _generate_architecture(num_layers: int, layer_types: List[str], hidden_dims: List[int],



    pool_types: List[str], use_skip: bool, use_batch_norm: bool, use_dropout: bool,



    dropout_rate: float = 0.5) -> Dict[str, Any]:



    import random



    random.seed(hash(str(layer_types)) % (2**31))



    layers = []



    for i in range(num_layers):



        layer_id = f"layer_{i}"



        in_dim = hidden_dims[i - 1] if i > 0 else hidden_dims[0]



        out_dim = hidden_dims[i] if i < len(hidden_dims) else hidden_dims[-1]



        ltype = layer_types[i] if i < len(layer_types) else random.choice(layer_types)



        layers.append({"layer_id": layer_id, "type": ltype, "in_channels": in_dim,



            "out_channels": out_dim, "use_norm": use_batch_norm, "use_dropout": use_dropout,



            "dropout_rate": dropout_rate if use_dropout else 0.0,



            "activation": "relu" if i < num_layers - 1 else "softmax"})



    skip_connections = []



    if use_skip:



        for i in range(1, num_layers):



            if random.random() > 0.5:



                skip_connections.append({"from_layer": i - 1, "to_layer": i,



                    "transform": "linear" if random.random() > 0.5 else "none"})



    pool_config = {"type": random.choice(pool_types) if pool_types else "max",



        "hidden_dim": hidden_dims[-1] if hidden_dims else 128}



    return {"architecture_id": f"arch_{random.randint(1000, 9999)}", "num_layers": num_layers,



        "layers": layers, "skip_connections": skip_connections, "pooling": pool_config,



        "total_params": random.randint(10000, 1000000), "estimated_flops": random.randint(1000000, 100000000)}











def _evaluate_architecture(arch: Dict[str, Any], dataset: str, metric: str = "accuracy") -> Dict[str, Any]:



    import random



    random.seed(hash(arch.get("architecture_id", "arch")) % (2**31))



    num_params = arch.get("total_params", 50000)



    num_layers = arch.get("num_layers", 3)



    base_score = random.uniform(0.6, 0.85)



    params_factor = max(0, 1 - num_params / 1000000)



    val_accuracy = round(base_score * (0.7 + 0.3 * params_factor), 4)



    test_accuracy = round(val_accuracy - random.uniform(0.01, 0.05), 4)



    train_time = num_params * random.uniform(0.001, 0.01)



    inference_time = num_params * random.uniform(0.0001, 0.001)



    metrics = {"regression": {"mse": round(random.uniform(0.01, 0.1), 4), "mae": round(random.uniform(0.05, 0.2), 4)},



        "classification": {"accuracy": val_accuracy, "f1": round(val_accuracy - 0.02, 4), "auc": round(val_accuracy + 0.02, 4)},



        "ranking": {"ndcg@5": round(val_accuracy, 4), "ndcg@10": round(val_accuracy - 0.01, 4)}}



    selected = metrics.get(metric, metrics["classification"])



    return {"architecture_id": arch.get("architecture_id"), "dataset": dataset, "metric": metric,



        "validation_score": selected.get("accuracy", selected.get("ndcg@5", 0.8)), "test_score": test_accuracy,



        "train_time_seconds": round(train_time, 2), "inference_time_ms": round(inference_time, 4),



        "num_parameters": num_params, "detailed_metrics": selected}











@router.post("/nas/search-space", response_model=Dict)



async def define_search_space(graph_id: str, num_layers: int = 3,



    layer_types: List[GNNLayerType] = [GNNLayerType.GCN, GNNLayerType.GAT],



    hidden_dims: List[int] = [64, 128, 128], pool_types: List[PoolType] = [PoolType.MAX, PoolType.ATTENTION],



    use_skip: bool = True, use_batch_norm: bool = True, use_dropout: bool = True,



    dropout_rate: float = 0.5) -> Dict:



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    nodes = len(adj)



    import random



    random.seed(hash(graph_id) % (2**31))



    sample_size = random.randint(5, 10)



    samples = []



    for _ in range(sample_size):



        arch = _generate_architecture(num_layers=num_layers,



            layer_types=[lt.value for lt in layer_types], hidden_dims=hidden_dims,



            pool_types=[p.value for p in pool_types], use_skip=use_skip,



            use_batch_norm=use_batch_norm, use_dropout=use_dropout, dropout_rate=dropout_rate)



        samples.append(arch)



    result = {"graph_id": graph_id, "num_nodes": nodes, "search_space": {"num_layers": num_layers,



        "layer_types": [lt.value for lt in layer_types], "hidden_dims": hidden_dims,



        "pool_types": [p.value for p in pool_types], "use_skip": use_skip,



        "use_batch_norm": use_batch_norm, "use_dropout": use_dropout, "dropout_rate": dropout_rate},



        "sample_architectures": samples, "sample_size": sample_size,



        "total_possible_architectures": random.randint(1000, 100000)}



    _nas_cache[f"{graph_id}_space"] = result



    return result











