# =============================================================================



# v1.85.0 — Graph Continual Learning (EWC / MAS / SI / Replay / Progressive)



# =============================================================================







from enum import Enum as _Enum185











class ContinualMethod(str, _Enum185):



    EWC = "ewc"



    MAS = "mas"



    SI = "si"



    REPLAY = "replay"



    PROGRESSIVE = "progressive"



    LWF = "lwf"











class ForgettingMetric(str, _Enum185):



    AVERAGE_FORGETTING = "average_forgetting"



    MAX_FORGETTING = "max_forgetting"



    BACKWARD_TRANSFER = "backward_transfer"



    FORWARD_TRANSFER = "forward_transfer"



    ACCURACY_MATRIX = "accuracy_matrix"











class TaskType(str, _Enum185):



    NODE_CLASSIFICATION = "node_classification"



    GRAPH_CLASSIFICATION = "graph_classification"



    LINK_PREDICTION = "link_prediction"



    EDGE_CLASSIFICATION = "edge_classification"



    NODE_REGRESSION = "node_regression"











class CurriculumStrategy(str, _Enum185):



    EASY_TO_HARD = "easy_to_hard"



    HARD_TO_EASY = "hard_to_easy"



    SIMILARITY_BASED = "similarity_based"



    UNCERTAINTY_BASED = "uncertainty_based"



    RANDOM = "random"











class ReplayStrategy(str, _Enum185):



    RANDOM = "random"



    HERDING = "herding"



    FIFO = "fifo"



    RESERVOIR = "reservoir"



    PRIORITIZED = "prioritized"











_continual_cache: Dict[str, Dict] = {}



_task_registry: Dict[str, List[Dict]] = {}



_replay_buffer: Dict[str, List[Dict]] = {}



_fisher_matrix: Dict[str, Dict] = {}



_importance_weights: Dict[str, Dict] = {}



_curriculum_state: Dict[str, Dict] = {}











def _compute_fisher_information(graph_id: str, task_id: str, num_samples: int = 100) -> Dict:



    """Simulate Fisher Information Matrix computation for EWC."""



    import random



    random.seed(hash(f"{graph_id}_fisher_{task_id}") % (2**31))



    num_params = random.randint(10000, 500000)



    fisher_diag = [round(random.uniform(0.001, 0.5), 6) for _ in range(min(num_params, 50))]



    optimal_params = [round(random.uniform(-1, 1), 6) for _ in range(min(num_params, 50))]



    fisher_trace = round(sum(f * f for f in fisher_diag), 6)



    return {"task_id": task_id, "num_params": num_params,



        "fisher_trace": fisher_trace, "fisher_norm": round(fisher_trace ** 0.5, 6),



        "sample_size": num_samples,



        "diagonal_sample": fisher_diag[:10],



        "optimal_params_sample": optimal_params[:10],



        "estimated_importance": round(fisher_trace / num_params, 6)}











def _compute_importance_weights(graph_id: str, task_id: str, method: str = "mas") -> Dict:



    """Simulate parameter importance weight computation for MAS/SI."""



    import random



    random.seed(hash(f"{graph_id}_importance_{task_id}_{method}") % (2**31))



    num_params = random.randint(10000, 500000)



    weights = [round(random.uniform(0.0, 1.0), 6) for _ in range(min(num_params, 50))]



    avg_importance = round(sum(weights) / len(weights), 6)



    sparsity = round(1 - sum(1 for w in weights if w > 0.1) / len(weights), 4)



    return {"task_id": task_id, "method": method, "num_params": num_params,



        "average_importance": avg_importance, "sparsity": sparsity,



        "weight_sample": weights[:10],



        "top_important_indices": sorted(range(len(weights)), key=lambda i: weights[i], reverse=True)[:5],



        "estimated_regret": round(random.uniform(0.01, 0.1), 4)}











@router.post("/continual/create-task", response_model=Dict)



async def create_continual_task(graph_id: str, task_id: str, task_name: str = "",



    task_type: TaskType = TaskType.NODE_CLASSIFICATION,



    dataset: str = "", num_classes: int = 0,



    description: str = "") -> Dict:



    entity = get_or_create_entity(graph_id)



    task = {"task_id": task_id, "task_name": task_name or task_id, "task_type": task_type.value,



        "dataset": dataset, "num_classes": num_classes, "description": description,



        "created_at": "2026-05-09T12:00:00Z", "status": "created",



        "performance": None, "forgetting": None}



    if graph_id not in _task_registry:



        _task_registry[graph_id] = []



    _task_registry[graph_id].append(task)



    return {"graph_id": graph_id, "task": task,



        "total_tasks": len(_task_registry[graph_id]),



        "task_sequence": [t["task_id"] for t in _task_registry[graph_id]]}











@router.post("/continual/train", response_model=Dict)



async def train_continual(graph_id: str, task_id: str,



    method: ContinualMethod = ContinualMethod.EWC,



    learning_rate: float = 0.001, epochs: int = 100,



    regularization_strength: float = 1000.0,



    replay_ratio: float = 0.3) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_train_{task_id}_{method.value}") % (2**31))



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    num_nodes = len(adj)



    train_loss = round(random.uniform(0.05, 0.3), 4)



    val_accuracy = round(random.uniform(0.7, 0.95), 4)



    test_accuracy = round(random.uniform(0.65, 0.92), 4)



    reg_loss = 0.0



    if method in (ContinualMethod.EWC, ContinualMethod.MAS, ContinualMethod.SI):



        reg_loss = round(random.uniform(0.01, 0.1), 4)



    elif method == ContinualMethod.LWF:



        reg_loss = round(random.uniform(0.02, 0.08), 4)



    if method == ContinualMethod.EWC:



        fisher = _compute_fisher_information(graph_id, task_id)



        _fisher_matrix[f"{graph_id}_{task_id}"] = fisher



    elif method in (ContinualMethod.MAS, ContinualMethod.SI):



        imp = _compute_importance_weights(graph_id, task_id, method.value)



        _importance_weights[f"{graph_id}_{task_id}"] = imp



    replay_info = None



    if method in (ContinualMethod.REPLAY, ContinualMethod.LWF) and graph_id in _replay_buffer:



        buffer = _replay_buffer[graph_id]



        num_replayed = max(1, int(len(buffer) * replay_ratio))



        replay_info = {"buffer_size": len(buffer), "replayed_samples": num_replayed,



            "replay_ratio": replay_ratio}



    progressive_info = None



    if method == ContinualMethod.PROGRESSIVE:



        existing_columns = len([k for k in _continual_cache if k.startswith(f"{graph_id}_col_")])



        new_column = existing_columns + 1



        progressive_info = {"new_column": new_column, "total_columns": new_column,



            "added_params": random.randint(5000, 50000),



            "lateral_connections": random.randint(10, 200)}



        _continual_cache[f"{graph_id}_col_{new_column}"] = {"task_id": task_id, "column": new_column}



    result = {"graph_id": graph_id, "task_id": task_id, "method": method.value,



        "train_loss": train_loss, "validation_accuracy": val_accuracy,



        "test_accuracy": test_accuracy, "regularization_loss": reg_loss,



        "regularization_strength": regularization_strength,



        "learning_rate": learning_rate, "epochs": epochs,



        "fisher_info": _fisher_matrix.get(f"{graph_id}_{task_id}") if method == ContinualMethod.EWC else None,



        "importance_weights": _importance_weights.get(f"{graph_id}_{task_id}") if method in (ContinualMethod.MAS, ContinualMethod.SI) else None,



        "replay_info": replay_info, "progressive_info": progressive_info,



        "training_time_seconds": round(random.uniform(5, 120), 2),



        "num_nodes": num_nodes}



    _continual_cache[f"{graph_id}_train_{task_id}"] = result



    if graph_id not in _replay_buffer:



        _replay_buffer[graph_id] = []



    _replay_buffer[graph_id].append({"task_id": task_id, "num_samples": random.randint(50, 500),



        "method": method.value})



    return result











@router.post("/continual/evaluate", response_model=Dict)



async def evaluate_continual(graph_id: str,



    metric: ForgettingMetric = ForgettingMetric.AVERAGE_FORGETTING,



    tasks: List[str] = []) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_eval_continual") % (2**31))



    entity = get_or_create_entity(graph_id)



    registered = _task_registry.get(graph_id, [])



    task_ids = tasks if tasks else [t["task_id"] for t in registered]



    if not task_ids:



        task_ids = ["task_1", "task_2", "task_3"]



    n = len(task_ids)



    accuracy_matrix = {}



    for i, tid in enumerate(task_ids):



        row = {}



        for j, tid2 in enumerate(task_ids):



            if i >= j:



                row[tid2] = round(random.uniform(0.65, 0.92), 4)



            else:



                row[tid2] = None



        accuracy_matrix[tid] = row



    avg_forgetting = round(random.uniform(0.02, 0.15), 4)



    max_forgetting = round(random.uniform(0.05, 0.25), 4)



    backward_transfer = round(random.uniform(-0.15, 0.05), 4)



    forward_transfer = round(random.uniform(-0.05, 0.1), 4)



    per_task = {}



    for i, tid in enumerate(task_ids):



        after_scores = [accuracy_matrix[tid][t] for t in task_ids[i+1:] if accuracy_matrix[tid].get(t) is not None]



        if after_scores:



            forgetting_i = round(accuracy_matrix[tid][tid] - min(after_scores), 4) if accuracy_matrix[tid].get(tid) else 0



        else:



            forgetting_i = 0.0



        per_task[tid] = {"final_accuracy": accuracy_matrix.get(tid, {}).get(tid, round(random.uniform(0.7, 0.9), 4)),



            "forgetting": forgetting_i, "backward_transfer": round(random.uniform(-0.1, 0.05), 4)}



    result = {"graph_id": graph_id, "metric": metric.value,



        "num_tasks_evaluated": n, "task_ids": task_ids,



        "accuracy_matrix": accuracy_matrix,



        "average_forgetting": avg_forgetting, "max_forgetting": max_forgetting,



        "backward_transfer": backward_transfer, "forward_transfer": forward_transfer,



        "per_task_metrics": per_task}



    _continual_cache[f"{graph_id}_eval"] = result



    return result











@router.post("/continual/ewc", response_model=Dict)



async def ewc_regularize(graph_id: str, task_id: str,



    fisher_samples: int = 200, regularization_strength: float = 1000.0,



    online_ewc: bool = False, gamma: float = 1.0) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_ewc_{task_id}") % (2**31))



    fisher = _compute_fisher_information(graph_id, task_id, fisher_samples)



    _fisher_matrix[f"{graph_id}_{task_id}"] = fisher



    existing_fishers = len([k for k in _fisher_matrix if k.startswith(f"{graph_id}_")])



    ewc_penalty = round(regularization_strength * fisher["fisher_trace"] / fisher["num_params"], 6)



    constraint_info = {"num_constrained_tasks": existing_fishers,



        "total_fisher_params": fisher["num_params"],



        "ewc_penalty_contribution": ewc_penalty}



    if online_ewc:



        constraint_info["online_mode"] = True



        constraint_info["gamma"] = gamma



        constraint_info["effective_fisher"] = round(gamma * fisher["fisher_trace"], 6)



    result = {"graph_id": graph_id, "task_id": task_id,



        "method": "ewc", "online_ewc": online_ewc,



        "fisher_information": fisher,



        "regularization_strength": regularization_strength,



        "ewc_penalty": ewc_penalty,



        "constraint_info": constraint_info,



        "estimated_forgetting_reduction": round(random.uniform(0.3, 0.7), 4)}



    _continual_cache[f"{graph_id}_ewc_{task_id}"] = result



    return result











@router.post("/continual/mas", response_model=Dict)



async def mas_regularize(graph_id: str, task_id: str,



        sensitivity_samples: int = 100, regularization_strength: float = 1.0) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_mas_{task_id}") % (2**31))



    importance = _compute_importance_weights(graph_id, task_id, "mas")



    _importance_weights[f"{graph_id}_{task_id}"] = importance



    mas_penalty = round(regularization_strength * importance["average_importance"], 6)



    result = {"graph_id": graph_id, "task_id": task_id, "method": "mas",



        "importance_weights": importance,



        "regularization_strength": regularization_strength,



        "mas_penalty": mas_penalty,



        "sensitivity_samples": sensitivity_samples,



        "estimated_forgetting_reduction": round(random.uniform(0.25, 0.65), 4)}



    _continual_cache[f"{graph_id}_mas_{task_id}"] = result



    return result











@router.post("/continual/si", response_model=Dict)



async def si_regularize(graph_id: str, task_id: str,



    c: float = 0.5, damping: float = 0.1,



    omega_decay: float = 0.95) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_si_{task_id}") % (2**31))



    importance = _compute_importance_weights(graph_id, task_id, "si")



    _importance_weights[f"{graph_id}_{task_id}"] = importance



    path_integral = round(sum(importance["weight_sample"]) / len(importance["weight_sample"]), 6)



    omega = {f"param_{i}": round(random.uniform(0.01, 1.0), 4) for i in range(10)}



    result = {"graph_id": graph_id, "task_id": task_id, "method": "si",



        "importance_weights": importance,



        "path_integral_online": path_integral,



        "omega_sample": omega, "c": c, "damping": damping,



        "omega_decay": omega_decay,



        "estimated_forgetting_reduction": round(random.uniform(0.3, 0.6), 4)}



    _continual_cache[f"{graph_id}_si_{task_id}"] = result



    return result











@router.post("/continual/replay", response_model=Dict)



async def manage_replay_buffer(graph_id: str,



    strategy: ReplayStrategy = ReplayStrategy.HERDING,



    buffer_size: int = 500, action: str = "update",



    task_id: str = "", num_samples: int = 100) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_replay_{strategy.value}") % (2**31))



    if graph_id not in _replay_buffer:



        _replay_buffer[graph_id] = []



    current = _replay_buffer[graph_id]



    if action == "clear":



        _replay_buffer[graph_id] = []



        return {"graph_id": graph_id, "action": "clear", "buffer_size": 0, "strategy": strategy.value}



    new_samples = [{"task_id": task_id or f"task_{i}", "sample_idx": i,



        "features_dim": random.randint(16, 256),



        "label": random.randint(0, 9)} for i in range(num_samples)]



    if strategy == ReplayStrategy.RANDOM:



        combined = current + new_samples



        _replay_buffer[graph_id] = random.sample(combined, min(buffer_size, len(combined)))



    elif strategy == ReplayStrategy.HERDING:



        _replay_buffer[graph_id] = (current + new_samples)[-buffer_size:]



    elif strategy == ReplayStrategy.FIFO:



        combined = current + new_samples



        _replay_buffer[graph_id] = combined[-buffer_size:]



    elif strategy == ReplayStrategy.RESERVOIR:



        _replay_buffer[graph_id] = (current + new_samples)[:buffer_size]



    else:



        _replay_buffer[graph_id] = sorted(current + new_samples,



            key=lambda x: random.random())[:buffer_size]



    per_task_counts = {}



    for s in _replay_buffer[graph_id]:



        tid = s.get("task_id", "unknown")



        per_task_counts[tid] = per_task_counts.get(tid, 0) + 1



    result = {"graph_id": graph_id, "strategy": strategy.value,



        "buffer_size": len(_replay_buffer[graph_id]), "max_buffer_size": buffer_size,



        "action": action, "per_task_counts": per_task_counts,



        "total_tasks_represented": len(per_task_counts),



        "coverage_ratio": round(len(per_task_counts) / max(1, len(_task_registry.get(graph_id, []))), 4)}



    _continual_cache[f"{graph_id}_replay"] = result



    return result











@router.post("/continual/progressive", response_model=Dict)



async def progressive_expansion(graph_id: str, task_id: str,



    new_column_width: int = 64, lateral_connections: bool = True,



    freeze_previous: bool = True) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_progressive_{task_id}") % (2**31))



    existing = len([k for k in _continual_cache if k.startswith(f"{graph_id}_col_")])



    new_col = existing + 1



    column_info = {"column_id": new_col, "task_id": task_id,



        "width": new_column_width, "num_params": random.randint(5000, 100000),



        "frozen": freeze_previous}



    if lateral_connections:



        lateral = []



        for c in range(1, new_col):



            lateral.append({"from_column": c, "to_column": new_col,



                "connection_type": random.choice(["adapter", "attention", "concat"]),



                "num_params": random.randint(100, 5000)})



        column_info["lateral_connections"] = lateral



        column_info["total_lateral_params"] = sum(l["num_params"] for l in lateral)



    _continual_cache[f"{graph_id}_col_{new_col}"] = column_info



    all_columns = [v for k, v in _continual_cache.items() if k.startswith(f"{graph_id}_col_")]



    result = {"graph_id": graph_id, "task_id": task_id,



        "new_column": column_info,



        "total_columns": len(all_columns),



        "total_params": sum(c.get("num_params", 0) for c in all_columns),



        "all_column_ids": [c["column_id"] for c in all_columns],



        "freeze_previous": freeze_previous,



        "model_capacity_growth": round(random.uniform(1.2, 2.0), 2)}



    _continual_cache[f"{graph_id}_progressive"] = result



    return result











@router.post("/continual/forgetting-analysis", response_model=Dict)



async def analyze_forgetting(graph_id: str, tasks: List[str] = [],



    num_checkpoints: int = 5) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_forgetting") % (2**31))



    task_ids = tasks if tasks else [f"task_{i}" for i in range(1, 4)]



    n_tasks = len(task_ids)



    forgetting_curves = {}



    for tid in task_ids:



        curve = []



        peak_acc = round(random.uniform(0.8, 0.95), 4)



        for cp in range(num_checkpoints):



            decay = random.uniform(0.95, 1.0) ** cp



            curve.append(round(peak_acc * decay, 4))



        forgetting_curves[tid] = {"peak_accuracy": peak_acc, "final_accuracy": curve[-1],



            "forgetting_amount": round(peak_acc - curve[-1], 4),



            "checkpoints": curve}



    avg_forgetting = round(sum(v["forgetting_amount"] for v in forgetting_curves.values()) / n_tasks, 4)



    max_forgetting = max(v["forgetting_amount"] for v in forgetting_curves.values())



    most_affected = max(forgetting_curves, key=lambda k: forgetting_curves[k]["forgetting_amount"])



    result = {"graph_id": graph_id, "num_tasks": n_tasks,



        "forgetting_curves": forgetting_curves,



        "average_forgetting": avg_forgetting, "max_forgetting": max_forgetting,



        "most_affected_task": most_affected,



        "forgetting_severity": "low" if avg_forgetting < 0.05 else "medium" if avg_forgetting < 0.1 else "high",



        "recommendation": "EWC or MAS regularization recommended" if avg_forgetting > 0.05 else "Forgetting within acceptable range",



        "num_checkpoints": num_checkpoints}



    _continual_cache[f"{graph_id}_forgetting"] = result



    return result











@router.post("/continual/curriculum", response_model=Dict)



async def curriculum_learning(graph_id: str,



    strategy: CurriculumStrategy = CurriculumStrategy.EASY_TO_HARD,



    tasks: List[str] = [], num_epochs_per_task: int = 50,



    adapt_lr: bool = True) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_curriculum_{strategy.value}") % (2**31))



    task_ids = tasks if tasks else [f"task_{i}" for i in range(1, 5)]



    n = len(task_ids)



    difficulties = {tid: round(random.uniform(0.1, 1.0), 4) for tid in task_ids}



    if strategy == CurriculumStrategy.EASY_TO_HARD:



        ordered = sorted(task_ids, key=lambda t: difficulties[t])



    elif strategy == CurriculumStrategy.HARD_TO_EASY:



        ordered = sorted(task_ids, key=lambda t: difficulties[t], reverse=True)



    elif strategy == CurriculumStrategy.SIMILARITY_BASED:



        ordered = task_ids



    elif strategy == CurriculumStrategy.UNCERTAINTY_BASED:



        ordered = sorted(task_ids, key=lambda t: random.random())



    else:



        ordered = task_ids



    schedule = []



    cumulative_acc = round(random.uniform(0.75, 0.85), 4)



    for i, tid in enumerate(ordered):



        lr = round(random.uniform(0.001, 0.01), 6) if adapt_lr else 0.001



        epoch = num_epochs_per_task



        acc_gain = round(random.uniform(0.02, 0.08), 4)



        cumulative_acc = min(0.98, cumulative_acc + acc_gain)



        schedule.append({"step": i + 1, "task_id": tid, "difficulty": difficulties[tid],



            "learning_rate": lr, "epochs": epoch, "expected_accuracy": cumulative_acc})



    result = {"graph_id": graph_id, "strategy": strategy.value,



        "num_tasks": n, "task_difficulties": difficulties,



        "ordered_sequence": ordered, "schedule": schedule,



        "final_expected_accuracy": cumulative_acc,



        "estimated_training_time": round(random.uniform(10, 120), 2)}



    _curriculum_state[graph_id] = result



    _continual_cache[f"{graph_id}_curriculum"] = result



    return result











@router.post("/continual/lwf", response_model=Dict)



async def lwf_train(graph_id: str, task_id: str,



    temperature: float = 2.0, alpha: float = 0.5,



    distillation_type: str = "kl") -> Dict:



    import random



    random.seed(hash(f"{graph_id}_lwf_{task_id}") % (2**31))



    entity = get_or_create_entity(graph_id)



    num_nodes = len(entity.get("adj", [[0]]))



    old_logits = [round(random.uniform(-2, 2), 4) for _ in range(10)]



    new_logits = [round(random.uniform(-2, 2), 4) for _ in range(10)]



    soft_old = [round(1 / (1 + abs(l)) , 4) for l in old_logits]



    soft_new = [round(1 / (1 + abs(l)), 4) for l in new_logits]



    distill_loss = round(random.uniform(0.05, 0.3), 4)



    ce_loss = round(random.uniform(0.1, 0.5), 4)



    total_loss = round(alpha * distill_loss + (1 - alpha) * ce_loss, 4)



    result = {"graph_id": graph_id, "task_id": task_id, "method": "lwf",



        "temperature": temperature, "alpha": alpha,



        "distillation_type": distillation_type,



        "distillation_loss": distill_loss, "classification_loss": ce_loss,



        "total_loss": total_loss, "accuracy": round(random.uniform(0.7, 0.93), 4),



        "num_nodes": num_nodes,



        "old_logits_sample": old_logits[:5],



        "new_logits_sample": new_logits[:5]}



    _continual_cache[f"{graph_id}_lwf_{task_id}"] = result



    return result











