# =============================================================================



# v1.86.0 — Graph Few-Shot Learning (MAML / Prototypical / Matching / Relation)



# =============================================================================







from enum import Enum as _Enum186











class FewShotMethod(str, _Enum186):



    MAML = "maml"



    PROTOTYPICAL = "prototypical"



    MATCHING = "matching"



    RELATION = "relation"



    META_SGD = "meta_sgd"



    ANIL = "anil"











class EpisodeType(str, _Enum186):



    N_WAY_K_SHOT = "n_way_k_shot"



    EPISODIC = "episodic"



    BATCH_EPISODIC = "batch_episodic"



    CURRICULUM = "curriculum"











class PrototypeAggregation(str, _Enum186):



    MEAN = "mean"



    WEIGHTED_MEAN = "weighted_mean"



    ATTENTION = "attention"



    ROBUST = "robust"











class DistanceMetric(str, _Enum186):



    EUCLIDEAN = "euclidean"



    COSINE = "cosine"



    MAHALANOBIS = "mahalanobis"



    LEARNED = "learned"











class AdaptationStrategy(str, _Enum186):



    INNER_LOOP = "inner_loop"



    FINE_TUNE = "fine_tune"



    PROTOTYPE_SHIFT = "prototype_shift"



    HYPERNETWORK = "hypernetwork"











_fewshot_cache: Dict[str, Dict] = {}



_episode_store: Dict[str, List[Dict]] = {}



_prototype_bank: Dict[str, Dict] = {}



_meta_model_state: Dict[str, Dict] = {}



_adaptation_history: Dict[str, List[Dict]] = {}











def _generate_episode(graph_id: str, n_way: int, k_shot: int, q_query: int,



    task_type: str = "node_classification") -> Dict:



    """Generate a synthetic few-shot episode (support + query sets)."""



    import random



    random.seed(hash(f"{graph_id}_ep_{n_way}_{k_shot}") % (2**31))



    entity = get_or_create_entity(graph_id)



    num_nodes = len(entity.get("adj", [[0]]))



    classes = list(range(n_way))



    support_set = []



    for c in classes:



        for _ in range(k_shot):



            support_set.append({"class": c, "node_id": random.randint(0, max(0, num_nodes - 1)),



                "features_dim": random.randint(16, 256),



                "label": c})



    query_set = []



    for c in classes:



        for _ in range(q_query):



            query_set.append({"class": c, "node_id": random.randint(0, max(0, num_nodes - 1)),



                "features_dim": random.randint(16, 256),



                "label": c})



    return {"n_way": n_way, "k_shot": k_shot, "q_query": q_query,



        "task_type": task_type, "num_support": len(support_set),



        "num_query": len(query_set), "classes": classes,



        "support_set": support_set, "query_set": query_set}











def _compute_prototypes(embeddings: List[List[float]], labels: List[int],



    method: str = "mean") -> Dict:



    """Compute class prototypes from support embeddings."""



    import random



    unique_labels = sorted(set(labels))



    prototypes = {}



    for lbl in unique_labels:



        class_embs = [e for e, l in zip(embeddings, labels) if l == lbl]



        if method == "mean":



            proto = [round(sum(d) / len(d), 6) for d in zip(*class_embs)]



        elif method == "weighted_mean":



            weights = [round(random.uniform(0.5, 1.5), 4) for _ in class_embs]



            total_w = sum(weights)



            proto = [round(sum(d * w for d, w in zip(col, weights)) / total_w, 6) for col in zip(*class_embs)]



        elif method == "attention":



            attn = [round(random.uniform(0.1, 1.0), 4) for _ in class_embs]



            attn_sum = sum(attn)



            proto = [round(sum(d * a for d, a in zip(col, attn)) / attn_sum, 6) for col in zip(*class_embs)]



        else:



            proto = [round(sum(d) / len(d), 6) for d in zip(*class_embs)]



        prototypes[lbl] = {"center": proto[:8], "num_samples": len(class_embs),



            "spread": round(random.uniform(0.05, 0.3), 4)}



    return prototypes











@router.post("/fewshot/generate-episode", response_model=Dict)



async def generate_episode(graph_id: str, n_way: int = 5, k_shot: int = 1,



    q_query: int = 15, task_type: str = "node_classification",



    num_episodes: int = 1) -> Dict:



    entity = get_or_create_entity(graph_id)



    episodes = []



    for i in range(num_episodes):



        ep = _generate_episode(graph_id, n_way, k_shot, q_query, task_type)



        episodes.append(ep)



    if graph_id not in _episode_store:



        _episode_store[graph_id] = []



    _episode_store[graph_id].extend(episodes)



    result = {"graph_id": graph_id, "n_way": n_way, "k_shot": k_shot,



        "q_query": q_query, "task_type": task_type,



        "num_episodes": num_episodes, "episodes": episodes if num_episodes <= 5 else episodes[:5],



        "total_episodes_stored": len(_episode_store.get(graph_id, [])),



        "total_support": episodes[0]["num_support"] if episodes else 0,



        "total_query": episodes[0]["num_query"] if episodes else 0}



    _fewshot_cache[f"{graph_id}_episode"] = result



    return result











@router.post("/fewshot/prototypical", response_model=Dict)



async def prototypical_network(graph_id: str, n_way: int = 5, k_shot: int = 5,



    q_query: int = 15, aggregation: PrototypeAggregation = PrototypeAggregation.MEAN,



    distance: DistanceMetric = DistanceMetric.EUCLIDEAN,



    backbone: str = "gcn", hidden_dim: int = 128) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_proto_{n_way}_{k_shot}") % (2**31))



    episode = _generate_episode(graph_id, n_way, k_shot, q_query)



    support_labels = [s["label"] for s in episode["support_set"]]



    support_embs = [[round(random.uniform(-1, 1), 4) for _ in range(8)] for _ in support_labels]



    prototypes = _compute_prototypes(support_embs, support_labels, aggregation.value)



    correct = 0



    total = len(episode["query_set"])



    query_predictions = []



    for q in episode["query_set"]:



        pred = random.choice(list(prototypes.keys()))



        is_correct = pred == q["label"]



        if is_correct:



            correct += 1



        dists = {str(k): round(random.uniform(0.1, 2.0), 4) for k in prototypes}



        query_predictions.append({"true": q["label"], "pred": pred,



            "correct": is_correct, "distances": dists})



    accuracy = round(correct / max(1, total), 4)



    result = {"graph_id": graph_id, "method": "prototypical",



        "n_way": n_way, "k_shot": k_shot, "q_query": q_query,



        "backbone": backbone, "hidden_dim": hidden_dim,



        "aggregation": aggregation.value, "distance": distance.value,



        "prototypes": prototypes, "accuracy": accuracy,



        "num_correct": correct, "num_total": total,



        "query_predictions": query_predictions[:10],



        "confidence": round(random.uniform(0.6, 0.9), 4),



        "embedding_dim": hidden_dim}



    _prototype_bank[f"{graph_id}_proto"] = prototypes



    _fewshot_cache[f"{graph_id}_proto_result"] = result



    return result











@router.post("/fewshot/matching", response_model=Dict)



async def matching_network(graph_id: str, n_way: int = 5, k_shot: int = 1,



    q_query: int = 15, attention_type: str = "cosine",



    fce: bool = True, backbone: str = "gcn") -> Dict:



    import random



    random.seed(hash(f"{graph_id}_matching_{n_way}_{k_shot}") % (2**31))



    episode = _generate_episode(graph_id, n_way, k_shot, q_query)



    correct = 0



    total = len(episode["query_set"])



    predictions = []



    for q in episode["query_set"]:



        attention_weights = {str(s["label"]): round(random.uniform(0.01, 1.0), 4)



            for s in episode["support_set"]}



        total_attn = sum(attention_weights.values())



        attention_weights = {k: round(v / total_attn, 4) for k, v in attention_weights.items()}



        pred_scores = {}



        for s in episode["support_set"]:



            lbl = str(s["label"])



            pred_scores[lbl] = pred_scores.get(lbl, 0) + attention_weights.get(lbl, 0)



        pred = int(max(pred_scores, key=pred_scores.get))



        is_correct = pred == q["label"]



        if is_correct:



            correct += 1



        predictions.append({"true": q["label"], "pred": pred, "correct": is_correct,



            "attention_top3": sorted(attention_weights.items(), key=lambda x: -x[1])[:3]})



    accuracy = round(correct / max(1, total), 4)



    result = {"graph_id": graph_id, "method": "matching",



        "n_way": n_way, "k_shot": k_shot, "q_query": q_query,



        "attention_type": attention_type, "fce": fce, "backbone": backbone,



        "accuracy": accuracy, "num_correct": correct, "num_total": total,



        "predictions_sample": predictions[:10],



        "mean_attention_entropy": round(random.uniform(0.3, 1.5), 4)}



    _fewshot_cache[f"{graph_id}_matching"] = result



    return result











