# =============================================================================



# v1.87.0 — Graph Self-Supervised Contrastive Learning



#            (SimCLR-Gr / MoCo-Gr / BYOL-Gr / Barlow Twins-Gr / VICReg / SwAV)



# =============================================================================







from enum import Enum as _Enum187











class SSLMethod(str, _Enum187):



    SIMCLR = "simclr"



    MOCO = "moco"



    BYOL = "byol"



    BARLOW_TWINS = "barlow_twins"



    VICREG = "vicreg"



    SWAV = "swav"











class GraphAugmentation(str, _Enum187):



    NODE_DROPPING = "node_dropping"



    EDGE_DROPPING = "edge_dropping"



    SUBGRAPH = "subgraph"



    FEATURE_MASKING = "feature_masking"



    ATTRIBUTION = "attribution"



    IDENTITY = "identity"











class ProjectionHead(str, _Enum187):



    LINEAR = "linear"



    MLP = "mlp"



    GNN = "gnn"



    BILINEAR = "bilinear"











class NegativeStrategy(str, _Enum187):



    ALL = "all"



    HARD = "hard"



    BATCH = "batch"



    MIXED = "mixed"











class SSLObjective(str, _Enum187):



    NT_XENT = "nt_xent"



    INFONCE = "infoNCE"



    TRIPLET = "triplet"



    MARGIN = "margin"











_ssl_cache: Dict[str, Dict] = {}



_augmentation_state: Dict[str, Dict] = {}



_encoder_state: Dict[str, Dict] = {}



_projection_state: Dict[str, Dict] = {}



_ssl_training_log: Dict[str, List[Dict]] = {}











def _apply_augmentation(graph_id: str, aug_type: str, aug_ratio: float = 0.2) -> Dict:



    """Simulate graph data augmentation."""



    import random



    random.seed(hash(f"{graph_id}_aug_{aug_type}_{aug_ratio}") % (2**31))



    entity = get_or_create_entity(graph_id)



    adj = entity.get("adj", [[0]])



    num_nodes = len(adj)



    num_edges = sum(len(row) for row in adj) // 2



    if aug_type == "node_dropping":



        dropped = max(1, int(num_nodes * aug_ratio))



        kept = num_nodes - dropped



        return {"augmentation": aug_type, "ratio": aug_ratio,



            "nodes_dropped": dropped, "nodes_kept": kept,



            "edge_retention": round(1 - aug_ratio * 1.5, 4)}



    elif aug_type == "edge_dropping":



        dropped_edges = max(1, int(num_edges * aug_ratio))



        return {"augmentation": aug_type, "ratio": aug_ratio,



            "edges_dropped": dropped_edges, "edges_kept": num_edges - dropped_edges,



            "connectivity_preserved": round(random.uniform(0.7, 0.95), 4)}



    elif aug_type == "subgraph":



        sample_size = max(2, int(num_nodes * (1 - aug_ratio)))



        return {"augmentation": aug_type, "ratio": aug_ratio,



            "subgraph_nodes": sample_size, "subgraph_edges": max(1, int(sample_size * 1.5)),



            "coverage": round(sample_size / num_nodes, 4)}



    elif aug_type == "feature_masking":



        mask_dim = max(1, int(64 * aug_ratio))



        return {"augmentation": aug_type, "ratio": aug_ratio,



            "masked_features": mask_dim, "total_features": 64,



            "mask_ratio": aug_ratio}



    elif aug_type == "attribution":



        return {"augmentation": aug_type, "ratio": aug_ratio,



            "perturbed_nodes": max(1, int(num_nodes * aug_ratio)),



            "perturbation_scale": round(aug_ratio * 0.5, 4)}



    else:



        return {"augmentation": "identity", "ratio": 0.0,



            "nodes": num_nodes, "edges": num_edges}











def _compute_embeddings(graph_id: str, num_nodes: int, dim: int, method: str = "gcn") -> List[List[float]]:



    """Simulate GNN encoder output embeddings."""



    import random



    random.seed(hash(f"{graph_id}_emb_{method}_{dim}") % (2**31))



    return [[round(random.uniform(-1, 1), 4) for _ in range(dim)] for _ in range(min(num_nodes, 20))]











@router.post("/ssl/augment", response_model=Dict)



async def augment_graph(graph_id: str,



    augmentation: GraphAugmentation = GraphAugmentation.NODE_DROPPING,



    aug_ratio: float = 0.2, num_augmentations: int = 2) -> Dict:



    entity = get_or_create_entity(graph_id)



    results = []



    for i in range(num_augmentations):



        aug_result = _apply_augmentation(graph_id, augmentation.value, aug_ratio)



        results.append(aug_result)



    if graph_id not in _augmentation_state:



        _augmentation_state[graph_id] = {}



    _augmentation_state[graph_id][augmentation.value] = results



    result = {"graph_id": graph_id, "augmentation": augmentation.value,



        "aug_ratio": aug_ratio, "num_views": num_augmentations,



        "augmentations": results}



    _ssl_cache[f"{graph_id}_aug_{augmentation.value}"] = result



    return result











@router.post("/ssl/simclr", response_model=Dict)



async def train_simclr(graph_id: str, temperature: float = 0.5,



    projection_dim: int = 128, hidden_dim: int = 256,



    backbone: str = "gcn", num_layers: int = 2,



    batch_size: int = 512, epochs: int = 200,



    aug1: GraphAugmentation = GraphAugmentation.NODE_DROPPING,



    aug2: GraphAugmentation = GraphAugmentation.EDGE_DROPPING,



    aug_ratio: float = 0.2) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_simclr_{temperature}") % (2**31))



    entity = get_or_create_entity(graph_id)



    num_nodes = len(entity.get("adj", [[0]]))



    aug_v1 = _apply_augmentation(graph_id, aug1.value, aug_ratio)



    aug_v2 = _apply_augmentation(graph_id, aug2.value, aug_ratio)



    loss_trajectory = [round(4.0 * (0.97 ** i) + random.uniform(-0.1, 0.1), 4) for i in range(min(epochs, 20))]



    final_loss = loss_trajectory[-1]



    alignment = round(random.uniform(0.85, 0.98), 4)



    uniformity = round(random.uniform(0.05, 0.2), 4)



    result = {"graph_id": graph_id, "method": "simclr",



        "temperature": temperature, "projection_dim": projection_dim,



        "hidden_dim": hidden_dim, "backbone": backbone, "num_layers": num_layers,



        "batch_size": batch_size, "epochs": epochs,



        "augmentation_1": aug_v1, "augmentation_2": aug_v2,



        "final_loss": final_loss, "alignment": alignment, "uniformity": uniformity,



        "loss_trajectory": loss_trajectory,



        "num_nodes": num_nodes,



        "downstream_linear_acc": round(random.uniform(0.7, 0.88), 4),



        "downstream_finetune_acc": round(random.uniform(0.78, 0.93), 4),



        "encoder_params": random.randint(100000, 1000000)}



    _encoder_state[f"{graph_id}_simclr"] = {"alignment": alignment, "uniformity": uniformity, "final_loss": final_loss}



    _ssl_cache[f"{graph_id}_simclr"] = result



    return result











@router.post("/ssl/moco", response_model=Dict)



async def train_moco(graph_id: str, queue_size: int = 65536,



    momentum: float = 0.999, temperature: float = 0.07,



    projection_dim: int = 128, backbone: str = "gcn",



    epochs: int = 200,



    aug1: GraphAugmentation = GraphAugmentation.SUBGRAPH,



    aug2: GraphAugmentation = GraphAugmentation.FEATURE_MASKING) -> Dict:



    import random



    random.seed(hash(f"{graph_id}_moco_{momentum}") % (2**31))



    entity = get_or_create_entity(graph_id)



    num_nodes = len(entity.get("adj", [[0]]))



    loss_trajectory = [round(6.0 * (0.96 ** i) + random.uniform(-0.1, 0.1), 4) for i in range(min(epochs, 20))]



    queue_utilization = round(random.uniform(0.85, 0.99), 4)



    key_encoder_consistency = round(random.uniform(0.92, 0.99), 4)



    result = {"graph_id": graph_id, "method": "moco",



        "queue_size": queue_size, "momentum": momentum,



        "temperature": temperature, "projection_dim": projection_dim,



        "backbone": backbone, "epochs": epochs,



        "augmentation_1": _apply_augmentation(graph_id, aug1.value, 0.2),



        "augmentation_2": _apply_augmentation(graph_id, aug2.value, 0.2),



        "final_loss": loss_trajectory[-1],



        "loss_trajectory": loss_trajectory,



        "queue_utilization": queue_utilization,



        "key_encoder_consistency": key_encoder_consistency,



        "num_nodes": num_nodes,



        "downstream_linear_acc": round(random.uniform(0.72, 0.9), 4),



        "downstream_finetune_acc": round(random.uniform(0.8, 0.94), 4),



        "encoder_params": random.randint(100000, 800000),



        "queue_params": random.randint(50000, 500000)}



    _ssl_cache[f"{graph_id}_moco"] = result



    return result











