@router.post("/ood/ensemble", response_model=Dict)



async def ensemble_ood_detection(graph_id: str,



        num_models: int = 5,



        diversity_metric: str = "entropy",



        use_mcdropout: bool = False) -> Dict:



    """Deep ensemble OOD detection"""



    import random



    random.seed(hash(f"{graph_id}_ensemble") % (2**31))



    # Generate ensemble models



    models = []



    for i in range(num_models):



        models.append({



            "model_id": f"model_{i}",



            "architecture": random.choice(["gcn", "gat", "sage", "gin", "gatv2"]),



            "hidden_dim": random.randint(64, 256),



            "accuracy": round(random.uniform(0.72, 0.92), 4)



        })



    _ensemble_models[graph_id] = models



    model = {



        "graph_id": graph_id,



        "method": "ensemble",



        "num_models": num_models,



        "diversity_metric": diversity_metric,



        "use_mcdropout": use_mcdropout,



        "models": models,



        "trained": True



    }



    _ood_model_state[f"{graph_id}_ensemble"] = model



    # Simulate disagreement scores



    id_agreement = random.uniform(0.75, 0.95)



    ood_agreement = random.uniform(0.35, 0.60)



    result = {



        "graph_id": graph_id,



        "method": "ensemble",



        "num_models": num_models,



        "diversity_metric": diversity_metric,



        "use_mcdropout": use_mcdropout,



        "ensemble_accuracy": round(sum(m["accuracy"] for m in models) / len(models), 4),



        "id_disagreement": round(1.0 - id_agreement, 4),



        "ood_disagreement": round(1.0 - ood_agreement, 4),



        "prediction_agreement": {



            "id": round(id_agreement, 4),



            "ood": round(ood_agreement, 4)



        },



        "diversity_scores": {



            "id": round(random.uniform(0.1, 0.3), 4),



            "ood": round(random.uniform(0.5, 0.8), 4)



        },



        "auroc": round(random.uniform(0.82, 0.97), 4),



        "fpr95": round(random.uniform(0.02, 0.12), 4),



        "ensemble_diversity": round(random.uniform(0.15, 0.45), 4)}



    _ood_cache[f"{graph_id}_ensemble"] = result



    return result











