# ── 7. Unified OOD Scoring ────────────────────────────────────────







@router.post("/ood/score", response_model=Dict)



async def compute_ood_scores(graph_id: str,



        score_types: List[str] = ["energy_score", "msp", "entropy"],



        num_samples: int = 10,



        use_ensemble: bool = False) -> Dict:



    """Compute OOD scores for a graph using multiple methods"""



    import random



    import math



    random.seed(hash(f"{graph_id}_score") % (2**31))



    num_classes = random.randint(3, 8)



    # Generate sample logits



    samples_scores = {}



    for i in range(num_samples):



        logits = [random.uniform(-2, 2) for _ in range(num_classes)]



        sample_scores = {}



        # Energy score



        if "energy_score" in score_types:



            sample_scores["energy_score"] = _compute_energy_score(logits, temperature=1.0)



        # MSP



        if "msp" in score_types:



            sample_scores["msp"] = _compute_msp(logits)



        # Entropy



        if "entropy" in score_types:



            sample_scores["entropy"] = _compute_entropy(logits)



        # ODIN (perturbation-based)



        if "odin" in score_types:



            sample_scores["odin"] = _compute_energy_score(



                [l + random.uniform(-0.1, 0.1) for l in logits], temperature=0.5)



        # Likelihood (simplified)



        if "likelihood" in score_types:



            sample_scores["likelihood"] = round(random.uniform(-5.0, -0.5), 4)



        sample_key = f"sample_{i}"



        samples_scores[sample_key] = sample_scores



    # Aggregate statistics



    agg_scores = {}



    for st in score_types:



        vals = [s.get(st, 0.0) for s in samples_scores.values()]



        agg_scores[st] = {



            "mean": round(sum(vals) / len(vals), 4),



            "std": round((sum((x - sum(vals)/len(vals))**2 for x in vals) / len(vals))**0.5, 4),



            "min": round(min(vals), 4),



            "max": round(max(vals), 4)



        }



    result = {



        "graph_id": graph_id,



        "score_types": score_types,



        "num_samples": num_samples,



        "use_ensemble": use_ensemble,



        "samples": samples_scores,



        "aggregate_scores": agg_scores,



        "ood_indicators": {



            "energy_score": random.choice([True, False]),



            "msp": random.choice([True, False]),



            "entropy": random.choice([True, False])



        },



        "recommendation": random.choice(["in_distribution", "out_of_distribution", "uncertain"])}



    _ood_scores_cache[graph_id] = result



    return result











