from enum import Enum as _Enum190







class UncertaintyMethod(str, _Enum190):



    mc_dropout = "mc_dropout"



    deep_ensemble = "deep_ensemble"



    bayesian_gnn = "bayesian_gnn"



    evidential = "evidential"



    mc_gnn = "mc_gnn"



    dropout_bnn = "dropout_bnn"







class UncertaintyType(str, _Enum190):



    aleatoric = "aleatoric"



    epistemic = "epistemic"



    total = "total"



    predictive = "predictive"







class CalibrationMethod(str, _Enum190):



    temperature_scaling = "temperature_scaling"



    platt_scaling = "platt_scaling"



    isotonic_regression = "isotonic_regression"



    beta_calibration = "beta_calibration"



    histogram_binning = "histogram_binning"







class UncertaintyMetric(str, _Enum190):



    nll = "nll"



    brier_score = "brier_score"



    ece = "ece"



    mce = "mce"



    sharpness = "sharpness"



    calibration_error = "calibration_error"







_uncertainty_cache: Dict[str, Dict] = {}



_uncertainty_model_cache: Dict[str, Dict] = {}



_calibration_state: Dict[str, Dict] = {}



_uncertainty_benchmark: Dict[str, Dict] = {}











def _simulate_entropy(probs: list, base: float = 2.0) -> float:



    """Compute predictive entropy from probability distribution."""



    import math



    entropy = 0.0



    for p in probs:



        if p > 0:



            entropy -= p * math.log(p, base)



    return round(entropy, 6)











def _simulate_mutual_information(mean_probs: list, per_model_probs: list) -> float:



    """Compute mutual information (epistemic uncertainty proxy)."""



    import math



    total_entropy = _simulate_entropy(mean_probs)



    avg_entropy = 0.0



    for model_probs in per_model_probs:



        avg_entropy += _simulate_entropy(model_probs)



    avg_entropy /= max(len(per_model_probs), 1)



    return round(total_entropy - avg_entropy, 6)











def _simulate_nll(probs: list, labels: list) -> float:



    """Compute negative log-likelihood."""



    import math



    nll = 0.0



    for p, l in zip(probs, labels):



        nll -= math.log(max(p, 1e-10)) if l == 1 else 0



        if l == 1:



            nll -= math.log(max(p, 1e-10))



    return round(nll / max(len(labels), 1), 6)











def _compute_ece(probs: list, confidences: list, n_bins: int = 15) -> float:



    """Expected Calibration Error."""



    bin_size = 1.0 / n_bins



    ece = 0.0



    n = len(confidences)



    for i in range(n_bins):



        lower = i * bin_size



        upper = (i + 1) * bin_size



        mask = [j for j in range(n) if lower <= confidences[j] < upper]



        if mask:



            avg_conf = sum(confidences[j] for j in mask) / len(mask)



            avg_acc = sum(probs[j] for j in mask) / len(mask)



            ece += len(mask) / n * abs(avg_acc - avg_conf)



    return round(ece, 6)











def _generate_dirichlet_samples(alpha: list, n_samples: int = 100) -> list:



    """Generate Dirichlet samples for evidential uncertainty."""



    import random, math



    samples = []



    for _ in range(n_samples):



        gammas = [random.gammavariate(a, 1.0) for a in alpha]



        total = sum(gammas)



        samples.append([g / total for g in gammas] if total > 0 else [1.0 / len(alpha)] * len(alpha))



    return samples











@router.post("/uncertainty/mc-dropout", response_model=Dict)



async def uncertainty_mc_dropout(request: Request) -> Dict:



    """Monte Carlo Dropout uncertainty estimation for GNNs."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_forward_passes = body.get("num_forward_passes", 20)



    dropout_rate = body.get("dropout_rate", 0.5)



    num_classes = body.get("num_classes", 5)



    use_mc_batchnorm = body.get("use_mc_batchnorm", True)







    import random, time



    t0 = time.time()







    per_pass_predictions = []



    for _ in range(num_forward_passes):



        probs = [random.random() for _ in range(num_classes)]



        total = sum(probs)



        probs = [p / total for p in probs]



        per_pass_predictions.append(probs)







    mean_probs = [sum(p[c] for p in per_pass_predictions) / num_forward_passes for c in range(num_classes)]







    predictive_entropy = _simulate_entropy(mean_probs)



    avg_entropy = sum(_simulate_entropy(p) for p in per_pass_predictions) / num_forward_passes



    mutual_info = predictive_entropy - avg_entropy







    aleatoric_unc = avg_entropy



    epistemic_unc = mutual_info



    total_unc = predictive_entropy







    confidence = max(mean_probs)







    result = {



        "graph_id": graph_id,



        "method": "mc_dropout",



        "config": {



            "num_forward_passes": num_forward_passes,



            "dropout_rate": dropout_rate,



            "num_classes": num_classes,



            "use_mc_batchnorm": use_mc_batchnorm,



        },



        "mean_prediction": [round(p, 4) for p in mean_probs],



        "predicted_class": mean_probs.index(max(mean_probs)),



        "confidence": round(confidence, 4),



        "uncertainties": {



            "aleatoric": round(aleatoric_unc, 4),



            "epistemic": round(epistemic_unc, 4),



            "total": round(total_unc, 4),



            "predictive_entropy": round(predictive_entropy, 4),



            "mutual_information": round(mutual_info, 4),



        },



        "variance_per_class": [round(sum((p[c] - mean_probs[c])**2 for p in per_pass_predictions) / num_forward_passes, 6) for c in range(num_classes)],



        "per_pass_predictions": [[round(v, 4) for v in p] for p in per_pass_predictions[:5]],



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _uncertainty_cache[f"{graph_id}_mc_dropout"] = result



    return result











@router.post("/uncertainty/deep-ensemble", response_model=Dict)



async def uncertainty_deep_ensemble(request: Request) -> Dict:



    """Deep Ensemble uncertainty estimation with multiple independently trained GNNs."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_models = body.get("num_models", 5)



    num_classes = body.get("num_classes", 5)



    diversity_metric = body.get("diversity_metric", "entropy")



    use_weight_averaging = body.get("use_weight_averaging", True)







    import random, time, math



    t0 = time.time()







    model_predictions = []



    for _ in range(num_models):



        probs = [random.random() for _ in range(num_classes)]



        total = sum(probs)



        model_predictions.append([p / total for p in probs])







    mean_probs = [sum(m[c] for m in model_predictions) / num_models for c in range(num_classes)]







    predictive_entropy = _simulate_entropy(mean_probs)



    avg_entropy = sum(_simulate_entropy(m) for m in model_predictions) / num_models



    mutual_info = predictive_entropy - avg_entropy







    pairwise_diversity = []



    for i in range(num_models):



        for j in range(i + 1, num_models):



            kl = sum(model_predictions[i][c] * math.log(max(model_predictions[i][c], 1e-10) / max(model_predictions[j][c], 1e-10)) for c in range(num_classes) if model_predictions[j][c] > 0)



            pairwise_diversity.append(round(kl, 6))







    agreement = sum(1 for m in model_predictions if m.index(max(m)) == mean_probs.index(max(mean_probs))) / num_models







    confidence = max(mean_probs)







    result = {



        "graph_id": graph_id,



        "method": "deep_ensemble",



        "config": {"num_models": num_models, "num_classes": num_classes, "diversity_metric": diversity_metric, "use_weight_averaging": use_weight_averaging},



        "mean_prediction": [round(p, 4) for p in mean_probs],



        "predicted_class": mean_probs.index(max(mean_probs)),



        "confidence": round(confidence, 4),



        "uncertainties": {



            "aleatoric": round(avg_entropy, 4),



            "epistemic": round(mutual_info, 4),



            "total": round(predictive_entropy, 4),



            "predictive_entropy": round(predictive_entropy, 4),



            "mutual_information": round(mutual_info, 4),



        },



        "model_agreement": round(agreement, 4),



        "pairwise_kl_divergence": pairwise_diversity[:10],



        "avg_diversity": round(sum(pairwise_diversity) / max(len(pairwise_diversity), 1), 6),



        "per_model_predictions": [[round(v, 4) for v in m] for m in model_predictions],



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _uncertainty_cache[f"{graph_id}_ensemble"] = result



    _uncertainty_model_cache[graph_id] = {"num_models": num_models, "predictions": model_predictions}



    return result











@router.post("/uncertainty/bayesian-gnn", response_model=Dict)



async def uncertainty_bayesian_gnn(request: Request) -> Dict:



    """Bayesian Graph Neural Network uncertainty via variational inference."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_samples = body.get("num_samples", 50)



    prior_type = body.get("prior_type", "gaussian")



    num_classes = body.get("num_classes", 5)



    kl_weight = body.get("kl_weight", 0.1)



    posterior_type = body.get("posterior_type", "mean_field")







    import random, time, math



    t0 = time.time()







    weight_samples = []



    for _ in range(num_samples):



        w = [random.gauss(0, 1) for _ in range(num_classes)]



        weight_samples.append(w)







    predictions = []



    for w in weight_samples:



        exp_w = [math.exp(min(wn, 10)) for wn in w]



        total = sum(exp_w)



        predictions.append([e / total for e in exp_w])







    mean_probs = [sum(p[c] for p in predictions) / num_samples for c in range(num_classes)]







    predictive_entropy = _simulate_entropy(mean_probs)



    avg_entropy = sum(_simulate_entropy(p) for p in predictions) / num_samples



    mutual_info = predictive_entropy - avg_entropy







    kl_divergence = sum(random.uniform(0.5, 2.0) for _ in range(10)) / 10



    elbo = -predictive_entropy - kl_weight * kl_divergence







    confidence = max(mean_probs)







    result = {



        "graph_id": graph_id,



        "method": "bayesian_gnn",



        "config": {"num_samples": num_samples, "prior_type": prior_type, "num_classes": num_classes, "kl_weight": kl_weight, "posterior_type": posterior_type},



        "mean_prediction": [round(p, 4) for p in mean_probs],



        "predicted_class": mean_probs.index(max(mean_probs)),



        "confidence": round(confidence, 4),



        "uncertainties": {



            "aleatoric": round(avg_entropy, 4),



            "epistemic": round(mutual_info, 4),



            "total": round(predictive_entropy, 4),



            "predictive_entropy": round(predictive_entropy, 4),



            "mutual_information": round(mutual_info, 4),



        },



        "variational_inference": {



            "kl_divergence": round(kl_divergence, 4),



            "elbo": round(elbo, 4),



            "posterior_type": posterior_type,



            "prior_type": prior_type,



        },



        "weight_statistics": {



            "mean_per_class": [round(sum(ws[c] for ws in weight_samples) / num_samples, 4) for c in range(num_classes)],



            "std_per_class": [round((sum((ws[c] - sum(wss[c] for wss in weight_samples) / num_samples)**2 for ws in weight_samples) / num_samples)**0.5, 4) for c in range(num_classes)],



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _uncertainty_cache[f"{graph_id}_bayesian"] = result



    return result











@router.post("/uncertainty/evidential", response_model=Dict)



async def uncertainty_evidential(request: Request) -> Dict:



    """Evidential Deep Learning uncertainty — Dirichlet prior with type-specific uncertainties."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_classes = body.get("num_classes", 5)



    evidence_type = body.get("evidence_type", "dense")



    regularization = body.get("regularization", 0.1)



    num_samples = body.get("num_samples", 100)







    import random, time, math



    t0 = time.time()







    evidence = [random.uniform(0.5, 3.0) for _ in range(num_classes)]



    alpha = [e + 1.0 for e in evidence]



    S = sum(alpha)







    dirichlet_mean = [a / S for a in alpha]



    belief = [e / S for e in evidence]



    uncertainty_total = num_classes / S







    aleatoric_unc = sum((a * (S - a)) / (S * S * (S + 1)) for a in alpha)



    epistemic_unc = uncertainty_total - aleatoric_unc







    predictive_entropy = _simulate_entropy(dirichlet_mean)







    dir_samples = _generate_dirichlet_samples(alpha, num_samples)



    sample_entropy = [_simulate_entropy(s) for s in dir_samples]



    avg_sample_entropy = sum(sample_entropy) / num_samples







    max_evidence = max(evidence)



    total_evidence = sum(evidence)







    confidence = max(dirichlet_mean)







    result = {



        "graph_id": graph_id,



        "method": "evidential",



        "config": {"num_classes": num_classes, "evidence_type": evidence_type, "regularization": regularization, "num_samples": num_samples},



        "evidence": [round(e, 4) for e in evidence],



        "alpha": [round(a, 4) for a in alpha],



        "dirichlet_mean": [round(m, 4) for m in dirichlet_mean],



        "belief": [round(b, 4) for b in belief],



        "predicted_class": dirichlet_mean.index(max(dirichlet_mean)),



        "confidence": round(confidence, 4),



        "uncertainties": {



            "aleatoric": round(aleatoric_unc, 6),



            "epistemic": round(epistemic_unc, 6),



            "total": round(uncertainty_total, 6),



            "predictive_entropy": round(predictive_entropy, 4),



        },



        "strength": S,



        "max_evidence": round(max_evidence, 4),



        "total_evidence": round(total_evidence, 4),



        "evidence_concentration": round(max_evidence / max(total_evidence, 1e-10), 4),



        "sample_statistics": {



            "avg_entropy": round(avg_sample_entropy, 4),



            "entropy_std": round((sum((e - avg_sample_entropy)**2 for e in sample_entropy) / num_samples)**0.5, 4),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _uncertainty_cache[f"{graph_id}_evidential"] = result



    return result











@router.post("/uncertainty/mc-gnn", response_model=Dict)



async def uncertainty_mc_gnn(request: Request) -> Dict:



    """MC-GNN: Monte Carlo Graph Neural Network — node-level dropout + edge dropout."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_forward_passes = body.get("num_forward_passes", 20)



    node_dropout = body.get("node_dropout", 0.3)



    edge_dropout = body.get("edge_dropout", 0.2)



    num_classes = body.get("num_classes", 5)



    message_passing_steps = body.get("message_passing_steps", 3)







    import random, time



    t0 = time.time()







    per_pass = []



    nodes_active = []



    edges_active = []



    for _ in range(num_forward_passes):



        n_active = max(1, int(10 * (1 - node_dropout)))



        e_active = max(1, int(20 * (1 - edge_dropout)))



        nodes_active.append(n_active)



        edges_active.append(e_active)



        probs = [random.random() for _ in range(num_classes)]



        total = sum(probs)



        per_pass.append([p / total for p in probs])







    mean_probs = [sum(p[c] for p in per_pass) / num_forward_passes for c in range(num_classes)]



    predictive_entropy = _simulate_entropy(mean_probs)



    avg_entropy = sum(_simulate_entropy(p) for p in per_pass) / num_forward_passes







    result = {



        "graph_id": graph_id,



        "method": "mc_gnn",



        "config": {"num_forward_passes": num_forward_passes, "node_dropout": node_dropout, "edge_dropout": edge_dropout, "num_classes": num_classes, "message_passing_steps": message_passing_steps},



        "mean_prediction": [round(p, 4) for p in mean_probs],



        "predicted_class": mean_probs.index(max(mean_probs)),



        "confidence": round(max(mean_probs), 4),



        "uncertainties": {



            "aleatoric": round(avg_entropy, 4),



            "epistemic": round(predictive_entropy - avg_entropy, 4),



            "total": round(predictive_entropy, 4),



        },



        "graph_dropout_stats": {



            "avg_active_nodes": round(sum(nodes_active) / num_forward_passes, 1),



            "avg_active_edges": round(sum(edges_active) / num_forward_passes, 1),



            "node_retention_rate": round(1 - node_dropout, 4),



            "edge_retention_rate": round(1 - edge_dropout, 4),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _uncertainty_cache[f"{graph_id}_mc_gnn"] = result



    return result











