@router.post("/uncertainty/calibrate", response_model=Dict)



async def uncertainty_calibrate(request: Request) -> Dict:



    """Calibrate uncertainty estimates using temperature scaling or other methods."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    calibration_method = body.get("calibration_method", "temperature_scaling")



    num_bins = body.get("num_bins", 15)



    temperature = body.get("temperature", 1.0)



    num_samples = body.get("num_samples", 100)







    import random, time, math



    t0 = time.time()







    raw_probs = []



    labels = []



    for _ in range(num_samples):



        p = random.uniform(0.3, 0.99)



        raw_probs.append(p)



        labels.append(1 if p > 0.5 + random.uniform(-0.3, 0.3) else 0)







    if calibration_method == "temperature_scaling":



        opt_temp = round(0.8 + random.uniform(-0.3, 0.5), 4)



        calibrated_probs = [1 / (1 + math.exp(-math.log(p / (1 - p + 1e-10) + 1e-10) / opt_temp)) for p in raw_probs]



    elif calibration_method == "platt_scaling":



        a, b = round(1.0 + random.uniform(-0.2, 0.2), 4), round(random.uniform(-0.1, 0.1), 4)



        calibrated_probs = [1 / (1 + math.exp(-(a * math.log(p / (1 - p + 1e-10) + 1e-10) + b))) for p in raw_probs]



    else:



        calibrated_probs = raw_probs.copy()







    ece_before = _compute_ece([1 if p > 0.5 else 0 for p in raw_probs], raw_probs, num_bins)



    ece_after = _compute_ece([1 if p > 0.5 else 0 for p in calibrated_probs], calibrated_probs, num_bins)







    confidences = calibrated_probs



    reliability_diagram = []



    bin_size = 1.0 / num_bins



    for i in range(num_bins):



        lower = i * bin_size



        upper = (i + 1) * bin_size



        mask = [j for j in range(len(confidences)) if lower <= confidences[j] < upper]



        if mask:



            avg_conf = sum(confidences[j] for j in mask) / len(mask)



            avg_acc = sum(1 for j in mask if (calibrated_probs[j] > 0.5) == (labels[j] == 1)) / len(mask)



            reliability_diagram.append({"bin_lower": round(lower, 3), "bin_upper": round(upper, 3), "avg_confidence": round(avg_conf, 4), "avg_accuracy": round(avg_acc, 4), "count": len(mask)})







    nll_before = sum(-math.log(max(p if l == 1 else 1 - p, 1e-10)) for p, l in zip(raw_probs, labels)) / num_samples



    nll_after = sum(-math.log(max(p if l == 1 else 1 - p, 1e-10)) for p, l in zip(calibrated_probs, labels)) / num_samples







    result = {



        "graph_id": graph_id,



        "method": calibration_method,



        "config": {"calibration_method": calibration_method, "num_bins": num_bins, "temperature": temperature, "num_samples": num_samples},



        "calibration_result": {



            "optimal_temperature": opt_temp if calibration_method == "temperature_scaling" else None,



            "ece_before": round(ece_before, 4),



            "ece_after": round(ece_after, 4),



            "ece_improvement": round(ece_before - ece_after, 4),



            "nll_before": round(nll_before, 4),



            "nll_after": round(nll_after, 4),



        },



        "reliability_diagram": reliability_diagram,



        "sample_comparison": {



            "before_top5": [round(p, 4) for p in raw_probs[:5]],



            "after_top5": [round(p, 4) for p in calibrated_probs[:5]],



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _calibration_state[graph_id] = result



    return result











