from enum import Enum as _Enum192







class PrivacyMechanism(str, _Enum192):



    edge_dp = "edge_dp"



    node_dp = "node_dp"



    ldp = "ldp"



    gap = "gap"



    dp_sgd = "dp_sgd"



    federated = "federated"







class PrivacyBudgetType(str, _Enum192):



    epsilon = "epsilon"



    epsilon_delta = "epsilon_delta"



    renyi_dp = "renyi_dp"



    concentrated_dp = "concentrated_dp"



    gaussian_dp = "gaussian_dp"







class AttackType(str, _Enum192):



    membership_inference = "membership_inference"



    attribute_inference = "attribute_inference"



    link_prediction = "link_prediction"



    model_inversion = "model_inversion"



    property_inference = "property_inference"







class NoiseMechanism(str, _Enum192):



    laplace = "laplace"



    gaussian = "gaussian"



    analytic_gaussian = "analytic_gaussian"



    staircase = "staircase"







_privacy_cache: Dict[str, Dict] = {}



_budget_cache: Dict[str, Dict] = {}



_attack_cache: Dict[str, Dict] = {}



_privacy_benchmark_cache: Dict[str, Dict] = {}











def _laplace_mechanism(value: float, sensitivity: float, epsilon: float) -> float:



    """Apply Laplace noise for epsilon-DP."""



    import random, math



    scale = sensitivity / max(epsilon, 1e-10)



    noise = random.gauss(0, scale / (2**0.5)) - random.gauss(0, scale / (2**0.5))



    return round(value + noise, 6)











def _gaussian_mechanism(value: float, sensitivity: float, epsilon: float, delta: float = 1e-5) -> float:



    """Apply Gaussian noise for (epsilon, delta)-DP."""



    import random, math



    sigma = sensitivity * (2 * math.log(1.25 / max(delta, 1e-10)))**0.5 / max(epsilon, 1e-10)



    noise = random.gauss(0, sigma)



    return round(value + noise, 6)











def _compute_privacy_loss(num_steps: int, epsilon_per_step: float, delta: float = 1e-5) -> Dict:



    """Compute cumulative privacy loss via advanced composition."""



    import math



    total_epsilon = epsilon_per_step * (2 * num_steps * math.log(1 / max(delta, 1e-10)))**0.5 + epsilon_per_step * num_steps * (math.exp(epsilon_per_step) - 1)



    return {"total_epsilon": round(total_epsilon, 4), "num_steps": num_steps, "delta": delta,



            "epsilon_per_step": epsilon_per_step}











def _simulate_membership_attack(model_confidence: list, is_member: list) -> Dict:



    """Simulate membership inference attack and compute metrics."""



    if len(model_confidence) != len(is_member):



        return {"error": "mismatched lengths"}







    threshold = 0.5



    tp = sum(1 for c, m in zip(model_confidence, is_member) if c > threshold and m)



    fp = sum(1 for c, m in zip(model_confidence, is_member) if c > threshold and not m)



    tn = sum(1 for c, m in zip(model_confidence, is_member) if c <= threshold and not m)



    fn = sum(1 for c, m in zip(model_confidence, is_member) if c <= threshold and m)







    precision = tp / max(tp + fp, 1)



    recall = tp / max(tp + fn, 1)



    accuracy = (tp + tn) / max(tp + fp + tn + fn, 1)



    f1 = 2 * precision * recall / max(precision + recall, 1e-10)







    return {"attack_accuracy": round(accuracy, 4), "attack_precision": round(precision, 4),



            "attack_recall": round(recall, 4), "attack_f1": round(f1, 4),



            "tp": tp, "fp": fp, "tn": tn, "fn": fn}











@router.post("/privacy/edge-dp", response_model=Dict)



async def privacy_edge_dp(request: Request) -> Dict:



    """Edge-level Differential Privacy — perturb adjacency matrix with noise."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon = body.get("epsilon", 1.0)



    num_nodes = body.get("num_nodes", 100)



    mechanism = body.get("mechanism", "laplace")



    num_edges = body.get("num_edges", 500)







    import random, time



    t0 = time.time()







    # Original adjacency weights



    original_weights = [round(random.uniform(0, 1), 4) for _ in range(num_edges)]







    # Apply noise to each edge



    if mechanism == "laplace":



        noisy_weights = [_laplace_mechanism(w, 1.0, epsilon) for w in original_weights]



    else:



        noisy_weights = [_gaussian_mechanism(w, 1.0, epsilon) for w in original_weights]







    # Clip to [0, 1]



    noisy_weights = [round(max(0, min(1, w)), 4) for w in noisy_weights]







    # Compute utility loss



    edge_diffs = [abs(o - n) for o, n in zip(original_weights, noisy_weights)]



    avg_diff = round(sum(edge_diffs) / max(len(edge_diffs), 1), 6)



    max_diff = round(max(edge_diffs), 6)







    # Edge flipping probability for randomized response



    flip_prob = 1 / (1 + epsilon) if epsilon > 0 else 0.5



    flipped_count = sum(1 for _ in range(num_edges) if random.random() < flip_prob)







    # Estimate privacy guarantee



    import math



    sensitivity = 1.0



    privacy_guarantee = {



        "epsilon": epsilon,



        "mechanism": mechanism,



        "sensitivity": sensitivity,



        "noise_scale": round(sensitivity / max(epsilon, 1e-10), 4),



        "edge_flipping_probability": round(flip_prob, 4),



    }







    # Graph statistics comparison



    orig_density = round(sum(1 for w in original_weights if w > 0.5) / num_edges, 4)



    noisy_density = round(sum(1 for w in noisy_weights if w > 0.5) / num_edges, 4)







    result = {



        "graph_id": graph_id,



        "method": "edge_dp",



        "config": {"epsilon": epsilon, "num_nodes": num_nodes, "mechanism": mechanism, "num_edges": num_edges},



        "privacy_guarantee": privacy_guarantee,



        "utility_analysis": {



            "avg_edge_weight_change": avg_diff,



            "max_edge_weight_change": max_diff,



            "density_before": orig_density,



            "density_after": noisy_density,



            "density_preservation": round(1 - abs(orig_density - noisy_density), 4),



            "edges_flipped_estimate": flipped_count,



        },



        "sample_edges": {



            "original_top5": original_weights[:5],



            "noisy_top5": noisy_weights[:5],



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_edge_dp"] = result



    return result











@router.post("/privacy/node-dp", response_model=Dict)



async def privacy_node_dp(request: Request) -> Dict:



    """Node-level Differential Privacy — protect presence/absence of entire nodes."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon = body.get("epsilon", 1.0)



    num_nodes = body.get("num_nodes", 100)



    mechanism = body.get("mechanism", "gaussian")



    delta = body.get("delta", 1e-5)



    max_degree = body.get("max_degree", 20)







    import random, time, math



    t0 = time.time()







    # Node degrees (sensitive info)



    original_degrees = [random.randint(1, max_degree) for _ in range(num_nodes)]







    # Apply noise to degree sequence



    if mechanism == "laplace":



        noisy_degrees = [_laplace_mechanism(d, max_degree, epsilon) for d in original_degrees]



    else:



        noisy_degrees = [_gaussian_mechanism(d, max_degree, epsilon, delta) for d in original_degrees]







    noisy_degrees = [max(0, round(d)) for d in noisy_degrees]







    # Compute node-level utility metrics



    degree_diffs = [abs(o - n) for o, n in zip(original_degrees, noisy_degrees)]



    avg_degree_diff = round(sum(degree_diffs) / num_nodes, 4)



    max_degree_diff = max(degree_diffs)







    # Graph statistics comparison



    orig_avg_degree = round(sum(original_degrees) / num_nodes, 4)



    noisy_avg_degree = round(sum(noisy_degrees) / num_nodes, 4)







    # Clustering coefficient impact



    orig_clustering = round(random.uniform(0.2, 0.6), 4)



    noisy_clustering = round(orig_clustering + random.uniform(-0.05 * epsilon, 0.05 * epsilon), 4)







    # Sensitivity for node DP is higher (max degree)



    sigma = max_degree * (2 * math.log(1.25 / max(delta, 1e-10)))**0.5 / max(epsilon, 1e-10)







    result = {



        "graph_id": graph_id,



        "method": "node_dp",



        "config": {"epsilon": epsilon, "num_nodes": num_nodes, "mechanism": mechanism, "delta": delta, "max_degree": max_degree},



        "privacy_guarantee": {



            "epsilon": epsilon, "delta": delta,



            "mechanism": mechanism,



            "sensitivity": max_degree,



            "sigma": round(sigma, 4),



            "privacy_level": "strong" if epsilon < 1 else ("moderate" if epsilon < 5 else "weak"),



        },



        "utility_analysis": {



            "avg_degree_change": avg_degree_diff,



            "max_degree_change": max_degree_diff,



            "avg_degree_before": orig_avg_degree,



            "avg_degree_after": noisy_avg_degree,



            "clustering_before": orig_clustering,



            "clustering_after": noisy_clustering,



        },



        "degree_comparison": {



            "original_top10": original_degrees[:10],



            "noisy_top10": noisy_degrees[:10],



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_node_dp"] = result



    return result











@router.post("/privacy/ldp", response_model=Dict)



async def privacy_ldp(request: Request) -> Dict:



    """Local Differential Privacy — each user perturbs their own data before sharing."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon = body.get("epsilon", 2.0)



    num_users = body.get("num_users", 100)



    num_features = body.get("num_features", 10)



    mechanism = body.get("mechanism", "laplace")







    import random, time



    t0 = time.time()







    # Each user has feature vector



    user_features = []



    noisy_features = []



    for _ in range(num_users):



        original = [round(random.uniform(0, 1), 4) for _ in range(num_features)]



        user_features.append(original)







        if mechanism == "laplace":



            noisy = [_laplace_mechanism(f, 1.0, epsilon) for f in original]



        else:



            noisy = [_gaussian_mechanism(f, 1.0, epsilon, 1e-5) for f in original]



        noisy_features.append([round(max(0, min(1, n)), 4) for n in noisy])







    # Aggregate statistics comparison



    orig_means = [round(sum(u[i] for u in user_features) / num_users, 4) for i in range(num_features)]



    noisy_means = [round(sum(u[i] for u in noisy_features) / num_users, 4) for i in range(num_features)]







    mean_diffs = [abs(o - n) for o, n in zip(orig_means, noisy_means)]



    avg_mean_diff = round(sum(mean_diffs) / num_features, 6)







    # Randomized response for binary attributes



    rr_prob = math.exp(epsilon) / (1 + math.exp(epsilon)) if epsilon > 0 else 0.5







    import math



    result = {



        "graph_id": graph_id,



        "method": "ldp",



        "config": {"epsilon": epsilon, "num_users": num_users, "num_features": num_features, "mechanism": mechanism},



        "privacy_guarantee": {



            "epsilon": epsilon,



            "mechanism": mechanism,



            "randomized_response_accuracy": round(rr_prob, 4),



            "noise_per_user": round(1.0 / max(epsilon, 1e-10), 4),



        },



        "utility_analysis": {



            "avg_feature_mean_change": avg_mean_diff,



            "max_feature_mean_change": round(max(mean_diffs), 6),



            "aggregation_quality": round(1 - avg_mean_diff, 4),



        },



        "feature_means": {



            "original": orig_means[:5],



            "noisy": noisy_means[:5],



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_ldp"] = result



    return result











@router.post("/privacy/gap", response_model=Dict)



async def privacy_gap(request: Request) -> Dict:



    """GAP: Graph-Aware Privacy — topology-aware noise injection for graph ML."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon = body.get("epsilon", 1.0)



    num_nodes = body.get("num_nodes", 100)



    hidden_dim = body.get("hidden_dim", 64)



    num_layers = body.get("num_layers", 2)



    noise_multiplier = body.get("noise_multiplier", 1.1)







    import random, time, math



    t0 = time.time()







    # Simulate GNN layer outputs with privacy noise



    layer_results = []



    cumulative_epsilon = 0.0







    for layer in range(num_layers):



        # Per-layer noise allocation



        layer_epsilon = epsilon / num_layers



        cumulative_epsilon += layer_epsilon







        # Simulate output embeddings



        embeddings = [round(random.uniform(-1, 1), 4) for _ in range(hidden_dim)]



        noisy_embeddings = [_gaussian_mechanism(e, 1.0, layer_epsilon, 1e-5) for e in embeddings]







        embedding_diff = round(sum(abs(e - n) for e, n in zip(embeddings, noisy_embeddings)) / hidden_dim, 4)



        layer_results.append({



            "layer": layer,



            "layer_epsilon": round(layer_epsilon, 4),



            "cumulative_epsilon": round(cumulative_epsilon, 4),



            "avg_embedding_change": embedding_diff,



        })







    # Graph-aware: sensitivity depends on graph structure



    graph_sensitivity = round(1.0 + random.uniform(0, 0.5), 4)



    sigma = graph_sensitivity * noise_multiplier * (2 * math.log(1.25 / 1e-5))**0.5 / max(epsilon, 1e-10)







    # Task utility: classification accuracy



    base_accuracy = round(random.uniform(0.85, 0.95), 4)



    utility_loss = round(random.uniform(0.01, 0.05) * (1 / max(epsilon, 0.1)), 4)



    private_accuracy = round(base_accuracy - utility_loss, 4)







    result = {



        "graph_id": graph_id,



        "method": "gap",



        "config": {"epsilon": epsilon, "num_nodes": num_nodes, "hidden_dim": hidden_dim,



                   "num_layers": num_layers, "noise_multiplier": noise_multiplier},



        "privacy_guarantee": {



            "total_epsilon": epsilon,



            "per_layer_epsilon": round(epsilon / num_layers, 4),



            "graph_sensitivity": graph_sensitivity,



            "sigma": round(sigma, 4),



            "noise_multiplier": noise_multiplier,



        },



        "layer_analysis": layer_results,



        "utility_analysis": {



            "base_accuracy": base_accuracy,



            "private_accuracy": private_accuracy,



            "accuracy_drop": round(base_accuracy - private_accuracy, 4),



            "relative_utility": round(private_accuracy / base_accuracy, 4),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_gap"] = result



    return result











@router.post("/privacy/dp-sgd", response_model=Dict)



async def privacy_dp_sgd(request: Request) -> Dict:



    """Differentially Private SGD — gradient perturbation for private GNN training."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon = body.get("epsilon", 3.0)



    delta = body.get("delta", 1e-5)



    num_epochs = body.get("num_epochs", 50)



    batch_size = body.get("batch_size", 32)



    num_nodes = body.get("num_nodes", 1000)



    learning_rate = body.get("learning_rate", 0.01)



    max_grad_norm = body.get("max_grad_norm", 1.0)



    noise_multiplier = body.get("noise_multiplier", 1.1)







    import random, time, math



    t0 = time.time()







    # Simulate training epochs



    epochs_data = []



    running_epsilon = 0.0







    for epoch in range(0, num_epochs, 5):



        # Per-step privacy cost (simplified moments accountant)



        step_epsilon = epsilon / max(num_epochs, 1)



        running_epsilon = step_epsilon * (2 * (epoch + 1) * math.log(1 / max(delta, 1e-10)))**0.5







        # Accuracy improves over time, lower with more noise



        base_acc = round(0.5 + 0.4 * (epoch / num_epochs), 4)



        noise_penalty = round(noise_multiplier * 0.02, 4)



        private_acc = round(min(base_acc - noise_penalty, 0.95), 4)







        # Gradient norm before/after clipping



        avg_grad_norm = round(random.uniform(0.5, 3.0), 4)



        clipped_norm = min(avg_grad_norm, max_grad_norm)







        epochs_data.append({



            "epoch": epoch + 1,



            "cumulative_epsilon": round(running_epsilon, 4),



            "train_accuracy": private_acc,



            "avg_grad_norm": avg_grad_norm,



            "clipped_grad_norm": round(clipped_norm, 4),



        })







    # Final privacy budget



    final_epsilon = round(min(running_epsilon, epsilon), 4)







    # Utility comparison



    non_private_accuracy = round(random.uniform(0.90, 0.96), 4)



    private_accuracy = epochs_data[-1]["train_accuracy"] if epochs_data else 0.0







    result = {



        "graph_id": graph_id,



        "method": "dp_sgd",



        "config": {"epsilon": epsilon, "delta": delta, "num_epochs": num_epochs,



                   "batch_size": batch_size, "num_nodes": num_nodes,



                   "learning_rate": learning_rate, "max_grad_norm": max_grad_norm,



                   "noise_multiplier": noise_multiplier},



        "privacy_accounting": {



            "target_epsilon": epsilon,



            "achieved_epsilon": final_epsilon,



            "delta": delta,



            "noise_multiplier": noise_multiplier,



            "max_grad_norm": max_grad_norm,



            "sampling_ratio": round(batch_size / max(num_nodes, 1), 4),



        },



        "training_progress": epochs_data,



        "utility_comparison": {



            "non_private_accuracy": non_private_accuracy,



            "private_accuracy": private_accuracy,



            "accuracy_gap": round(non_private_accuracy - private_accuracy, 4),



            "relative_utility": round(private_accuracy / max(non_private_accuracy, 1e-10), 4),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_dp_sgd"] = result



    return result











@router.post("/privacy/federated", response_model=Dict)



async def privacy_federated(request: Request) -> Dict:



    """Federated Graph Learning — distributed training with privacy guarantees."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    num_clients = body.get("num_clients", 10)



    num_rounds = body.get("num_rounds", 20)



    local_epsilon = body.get("local_epsilon", 2.0)



    local_epochs = body.get("local_epochs", 3)



    aggregation = body.get("aggregation", "fedavg")







    import random, time, math



    t0 = time.time()







    # Simulate federated rounds



    rounds_data = []



    for rnd in range(1, num_rounds + 1, max(num_rounds // 5, 1)):



        # Client participation



        participating = random.randint(max(1, num_clients // 2), num_clients)







        # Local training accuracy



        local_accs = [round(random.uniform(0.6, 0.9), 4) for _ in range(participating)]



        avg_local_acc = round(sum(local_accs) / participating, 4)







        # Global model accuracy improves



        global_acc = round(0.5 + 0.4 * (rnd / num_rounds), 4)







        # Privacy cost per round



        round_epsilon = local_epsilon * local_epochs



        total_epsilon = round(round_epsilon * rnd, 4)







        rounds_data.append({



            "round": rnd,



            "participating_clients": participating,



            "avg_local_accuracy": avg_local_acc,



            "global_accuracy": global_acc,



            "cumulative_epsilon": total_epsilon,



        })







    # Communication cost



    model_params = random.randint(10000, 100000)



    total_comm = model_params * num_rounds * num_clients







    # Secure aggregation status



    sec_agg_status = {



        "enabled": True,



        "threshold": max(1, num_clients // 2),



        "dropped_clients_per_round": random.randint(0, 2),



    }







    result = {



        "graph_id": graph_id,



        "method": "federated",



        "config": {"num_clients": num_clients, "num_rounds": num_rounds,



                   "local_epsilon": local_epsilon, "local_epochs": local_epochs,



                   "aggregation": aggregation},



        "privacy_guarantee": {



            "local_epsilon": local_epsilon,



            "total_epsilon_budget": round(local_epsilon * local_epochs * num_rounds, 4),



            "aggregation": aggregation,



            "secure_aggregation": True,



        },



        "training_progress": rounds_data,



        "communication": {



            "model_parameters": model_params,



            "total_communication_cost": f"{total_comm / 1e6:.2f}M params",



            "rounds": num_rounds,



        },



        "secure_aggregation": sec_agg_status,



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_cache[f"{graph_id}_federated"] = result



    return result











@router.post("/privacy/budget", response_model=Dict)



async def privacy_budget(request: Request) -> Dict:



    """Privacy budget management — track and allocate privacy budget across operations."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    total_budget = body.get("total_budget", 10.0)



    operations = body.get("operations", [



        {"name": "query_degree", "epsilon": 0.5},



        {"name": "query_subgraph", "epsilon": 1.0},



        {"name": "train_model", "epsilon": 3.0},



    ])







    import time



    t0 = time.time()







    allocated = 0.0



    ops_status = []



    for op in operations:



        op_eps = op.get("epsilon", 0.5)



        remaining = total_budget - allocated



        feasible = op_eps <= remaining



        if feasible:



            allocated += op_eps







        ops_status.append({



            "operation": op.get("name", "unknown"),



            "requested_epsilon": op_eps,



            "feasible": feasible,



            "allocated": feasible,



            "remaining_after": round(max(total_budget - allocated, 0), 4),



        })







    result = {



        "graph_id": graph_id,



        "total_budget": total_budget,



        "allocated_budget": round(allocated, 4),



        "remaining_budget": round(max(total_budget - allocated, 0), 4),



        "utilization": round(allocated / max(total_budget, 1e-10), 4),



        "operations": ops_status,



        "budget_exhausted": allocated >= total_budget,



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _budget_cache[graph_id] = result



    return result











@router.post("/privacy/attack", response_model=Dict)



async def privacy_attack(request: Request) -> Dict:



    """Simulate privacy attacks and evaluate defense effectiveness."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    attack_type = body.get("attack_type", "membership_inference")



    num_samples = body.get("num_samples", 200)



    defense_epsilon = body.get("defense_epsilon", 1.0)







    import random, time



    t0 = time.time()







    # Generate member/non-member samples



    is_member = [i < num_samples // 2 for i in range(num_samples)]



    random.shuffle(is_member)







    # Simulate model confidence (members tend to have higher confidence)



    model_confidence = []



    for m in is_member:



        if m:



            conf = random.uniform(0.55, 0.95)



        else:



            conf = random.uniform(0.1, 0.55)



        model_confidence.append(round(conf, 4))







    # No defense attack



    no_defense_result = _simulate_membership_attack(model_confidence, is_member)







    # With DP defense — reduce confidence gap



    defended_confidence = []



    for c, m in zip(model_confidence, is_member):



        noise = random.uniform(-0.15 * defense_epsilon, 0.15 * defense_epsilon)



        defended_confidence.append(round(max(0, min(1, c + noise)), 4))







    defense_result = _simulate_membership_attack(defended_confidence, is_member)







    attack_descriptions = {



        "membership_inference": "Determine if a node was in the training set",



        "attribute_inference": "Infer sensitive node attributes",



        "link_prediction": "Predict existence of edges",



        "model_inversion": "Reconstruct graph structure from model",



        "property_inference": "Infer global graph properties",



    }







    result = {



        "graph_id": graph_id,



        "attack_type": attack_type,



        "attack_description": attack_descriptions.get(attack_type, ""),



        "config": {"num_samples": num_samples, "defense_epsilon": defense_epsilon},



        "no_defense": no_defense_result,



        "with_dp_defense": defense_result,



        "defense_effectiveness": {



            "accuracy_reduction": round(no_defense_result["attack_accuracy"] - defense_result["attack_accuracy"], 4),



            "advantage_reduction": round(



                (no_defense_result["attack_accuracy"] - 0.5) - (defense_result["attack_accuracy"] - 0.5), 4



            ),



            "epsilon_used": defense_epsilon,



        },



        "random_baseline": 0.5,



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _attack_cache[f"{graph_id}_{attack_type}"] = result



    return result











@router.post("/privacy/utility-tradeoff", response_model=Dict)



async def privacy_utility_tradeoff(request: Request) -> Dict:



    """Analyze privacy-utility tradeoff across different epsilon values."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    epsilon_range = body.get("epsilon_range", [0.1, 0.5, 1.0, 2.0, 5.0, 10.0])



    mechanism = body.get("mechanism", "gaussian")







    import random, time, math



    t0 = time.time()







    tradeoff_data = []



    base_accuracy = round(random.uniform(0.88, 0.95), 4)







    for eps in epsilon_range:



        # Utility decreases as epsilon decreases (more privacy)



        noise_factor = 1 / max(eps, 0.01)



        accuracy = round(max(0.5, base_accuracy - 0.02 * noise_factor - random.uniform(0, 0.02)), 4)



        utility = round(accuracy / base_accuracy, 4)







        # Attack success decreases with more privacy



        attack_acc = round(min(0.99, 0.5 + 0.3 / max(eps, 0.1) + random.uniform(-0.02, 0.02)), 4)







        # Noise level



        sigma = round((2 * math.log(1.25 / 1e-5))**0.5 / max(eps, 1e-10), 4)







        tradeoff_data.append({



            "epsilon": eps,



            "model_accuracy": accuracy,



            "relative_utility": utility,



            "attack_accuracy": attack_acc,



            "noise_sigma": sigma,



            "privacy_level": "very_strong" if eps < 0.5 else ("strong" if eps < 1 else ("moderate" if eps < 5 else "weak")),



        })







    # Find optimal epsilon (best utility-privacy balance)



    optimal = max(tradeoff_data, key=lambda x: x["relative_utility"] * (1 - x["attack_accuracy"] + 0.5))







    result = {



        "graph_id": graph_id,



        "mechanism": mechanism,



        "base_accuracy": base_accuracy,



        "tradeoff_analysis": tradeoff_data,



        "optimal_epsilon": {"epsilon": optimal["epsilon"], "accuracy": optimal["model_accuracy"],



                           "privacy_level": optimal["privacy_level"]},



        "recommendations": {



            "high_privacy": {"epsilon": 0.5, "expected_utility_loss": "5-10%"},



            "balanced": {"epsilon": 2.0, "expected_utility_loss": "1-3%"},



            "high_utility": {"epsilon": 8.0, "expected_utility_loss": "<1%"},



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _privacy_benchmark_cache[graph_id] = result



    return result











