from enum import Enum as _Enum193







class SearchStrategy(str, _Enum193):



    random_search = "random_search"



    grid_search = "grid_search"



    bayesian = "bayesian"



    evolutionary = "evolutionary"



    hyperband = "hyperband"



    bohb = "bohb"







class ObjectiveMetric(str, _Enum193):



    accuracy = "accuracy"



    f1_score = "f1_score"



    auroc = "auroc"



    privacy_utility = "privacy_utility"



    uncertainty_quality = "uncertainty_quality"



    robustness = "robustness"



    composite = "composite"







class PipelineStage(str, _Enum193):



    preprocessing = "preprocessing"



    feature_engineering = "feature_engineering"



    architecture_search = "architecture_search"



    training = "training"



    evaluation = "evaluation"



    deployment = "deployment"







class EarlyStopStrategy(str, _Enum193):



    patience = "patience"



    decay = "decay"



    curve_fit = "curve_fit"



    median_stop = "median_stop"







_automl_cache: Dict[str, Dict] = {}



_automl_trials: Dict[str, list] = {}



_automl_pipeline: Dict[str, Dict] = {}



_automl_benchmark: Dict[str, Dict] = {}











def _evaluate_config(config: Dict, graph_id: str) -> Dict:



    """Evaluate a configuration and return multi-objective metrics."""



    import random, math







    # Architecture quality



    num_layers = config.get("num_layers", 2)



    hidden_dim = config.get("hidden_dim", 64)



    layer_type = config.get("layer_type", "gcn")







    # Base performance depends on architecture choices



    arch_bonus = {"gcn": 0, "gat": 0.02, "sage": 0.015, "gin": 0.01, "transformer": 0.025}



    base_acc = 0.82 + (hidden_dim / 512) * 0.05 + arch_bonus.get(layer_type, 0)



    accuracy = round(min(0.98, base_acc + random.uniform(-0.03, 0.03)), 4)







    # Privacy cost



    epsilon = config.get("epsilon", float("inf"))



    if epsilon < 1:



        privacy_score = round(0.95 + random.uniform(-0.02, 0.02), 4)



        acc_penalty = round(random.uniform(0.03, 0.08), 4)



    elif epsilon < 5:



        privacy_score = round(0.7 + random.uniform(-0.05, 0.05), 4)



        acc_penalty = round(random.uniform(0.01, 0.03), 4)



    else:



        privacy_score = round(0.3 + random.uniform(-0.05, 0.05), 4)



        acc_penalty = round(random.uniform(0, 0.01), 4)







    private_accuracy = round(max(0.5, accuracy - acc_penalty), 4)







    # Uncertainty quality



    unc_method = config.get("uncertainty_method", "mc_dropout")



    unc_bonus = {"mc_dropout": 0, "deep_ensemble": 0.05, "bayesian_gnn": 0.03, "evidential": 0.04}



    uncertainty_ece = round(max(0.01, 0.08 - unc_bonus.get(unc_method, 0) + random.uniform(-0.02, 0.02)), 4)







    # Training time estimate



    base_time = num_layers * 10 + hidden_dim * 0.1



    if epsilon < float("inf"):



        base_time *= 1.5



    if unc_method == "deep_ensemble":



        base_time *= 3



    training_time = round(base_time + random.uniform(-5, 5), 2)







    # Robustness



    robustness_score = round(min(0.95, accuracy * 0.9 + random.uniform(-0.05, 0.05)), 4)







    # Composite score



    composite = round(



        0.4 * private_accuracy +



        0.2 * privacy_score +



        0.2 * (1 - uncertainty_ece) +



        0.2 * robustness_score, 4)







    return {



        "accuracy": accuracy,



        "private_accuracy": private_accuracy,



        "privacy_score": privacy_score,



        "uncertainty_ece": uncertainty_ece,



        "robustness_score": robustness_score,



        "training_time_s": training_time,



        "composite_score": composite,



        "epsilon_used": epsilon,



    }











