@router.post("/automl/search", response_model=Dict)



async def automl_search(request: Request) -> Dict:



    """Run AutoML search with specified strategy."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    strategy = body.get("strategy", "bayesian")



    num_trials = body.get("num_trials", 20)



    objective = body.get("objective", "composite")







    import random, time



    t0 = time.time()







    layer_types = ["gcn", "gat", "sage", "gin", "transformer"]



    hidden_dims = [32, 64, 128, 256]



    epsilons = [0.5, 1.0, 2.0, 5.0, 10.0, 999]



    unc_methods = ["mc_dropout", "deep_ensemble", "bayesian_gnn", "evidential"]



    activations = ["relu", "elu", "gelu"]







    trials = []



    best_score = -1



    best_config = None







    for trial_idx in range(num_trials):



        # Strategy influences sampling



        if strategy == "random_search":



            config = {



                "layer_type": random.choice(layer_types),



                "num_layers": random.randint(1, 5),



                "hidden_dim": random.choice(hidden_dims),



                "dropout": round(random.uniform(0, 0.5), 2),



                "activation": random.choice(activations),



                "epsilon": random.choice(epsilons),



                "uncertainty_method": random.choice(unc_methods),



                "learning_rate": round(10 ** random.uniform(-4, -1), 6),



            }



        elif strategy == "bayesian":



            # Simulated Bayesian: exploit near previous best



            if best_config and random.random() < 0.7:



                config = dict(best_config)



                config["hidden_dim"] = random.choice(hidden_dims)



                config["dropout"] = round(max(0, min(0.8, config.get("dropout", 0.3) + random.uniform(-0.1, 0.1))), 2)



            else:



                config = {



                    "layer_type": random.choice(layer_types),



                    "num_layers": random.randint(1, 5),



                    "hidden_dim": random.choice(hidden_dims),



                    "dropout": round(random.uniform(0, 0.5), 2),



                    "activation": random.choice(activations),



                    "epsilon": random.choice(epsilons),



                    "uncertainty_method": random.choice(unc_methods),



                    "learning_rate": round(10 ** random.uniform(-4, -1), 6),



                }



        elif strategy == "evolutionary":



            # Simulated evolutionary: mutate best config



            if best_config and trial_idx > 2:



                config = dict(best_config)



                if random.random() < 0.3:



                    config["layer_type"] = random.choice(layer_types)



                if random.random() < 0.3:



                    config["hidden_dim"] = random.choice(hidden_dims)



                if random.random() < 0.2:



                    config["epsilon"] = random.choice(epsilons)



                if random.random() < 0.2:



                    config["uncertainty_method"] = random.choice(unc_methods)



            else:



                config = {



                    "layer_type": random.choice(layer_types),



                    "num_layers": random.randint(1, 5),



                    "hidden_dim": random.choice(hidden_dims),



                    "dropout": round(random.uniform(0, 0.5), 2),



                    "activation": random.choice(activations),



                    "epsilon": random.choice(epsilons),



                    "uncertainty_method": random.choice(unc_methods),



                    "learning_rate": round(10 ** random.uniform(-4, -1), 6),



                }



        else:



            config = {



                "layer_type": random.choice(layer_types),



                "num_layers": random.randint(1, 5),



                "hidden_dim": random.choice(hidden_dims),



                "dropout": round(random.uniform(0, 0.5), 2),



                "activation": random.choice(activations),



                "epsilon": random.choice(epsilons),



                "uncertainty_method": random.choice(unc_methods),



                "learning_rate": round(10 ** random.uniform(-4, -1), 6),



            }







        metrics = _evaluate_config(config, graph_id)



        score = metrics.get(objective, metrics["composite_score"])







        trial = {



            "trial_id": trial_idx,



            "config": config,



            "metrics": metrics,



            "score": score,



        }



        trials.append(trial)







        if score > best_score:



            best_score = score



            best_config = config







    ranked = sorted(trials, key=lambda t: t["score"], reverse=True)







    result = {



        "graph_id": graph_id,



        "strategy": strategy,



        "objective": objective,



        "num_trials": num_trials,



        "best_config": best_config,



        "best_metrics": ranked[0]["metrics"] if ranked else None,



        "top_5_trials": [



            {"trial_id": t["trial_id"], "config": t["config"], "score": t["score"],



             "accuracy": t["metrics"]["private_accuracy"], "composite": t["metrics"]["composite_score"]}



            for t in ranked[:5]



        ],



        "search_efficiency": {



            "best_found_at_trial": next((i for i, t in enumerate(ranked) if t["trial_id"] == ranked[0]["trial_id"]), 0),



            "improvement_over_random": round(best_score - sum(t["score"] for t in trials) / num_trials, 4),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _automl_cache[f"{graph_id}_{strategy}"] = result



    _automl_trials[graph_id] = trials



    return result











@router.post("/automl/multi-objective", response_model=Dict)



async def automl_multi_objective(request: Request) -> Dict:



    """Multi-objective optimization — find Pareto front across accuracy, privacy, uncertainty."""



    body = await request.json()



    graph_id = body.get("graph_id", "graph1")



    objectives = body.get("objectives", ["private_accuracy", "privacy_score", "uncertainty_ece"])



    num_trials = body.get("num_trials", 30)







    import random, time



    t0 = time.time()







    layer_types = ["gcn", "gat", "sage", "gin", "transformer"]



    hidden_dims = [64, 128, 256]



    epsilons = [0.5, 1.0, 2.0, 5.0, 10.0, 999]



    unc_methods = ["mc_dropout", "deep_ensemble", "bayesian_gnn", "evidential"]







    trials = []



    for _ in range(num_trials):



        config = {



            "layer_type": random.choice(layer_types),



            "num_layers": random.randint(1, 5),



            "hidden_dim": random.choice(hidden_dims),



            "dropout": round(random.uniform(0.1, 0.5), 2),



            "epsilon": random.choice(epsilons),



            "uncertainty_method": random.choice(unc_methods),



            "learning_rate": round(10 ** random.uniform(-3, -1), 6),



        }



        metrics = _evaluate_config(config, graph_id)



        trials.append({"config": config, "metrics": metrics})







    # Find Pareto front



    pareto_front = []



    for i, t1 in enumerate(trials):



        dominated = False



        for j, t2 in enumerate(trials):



            if i == j:



                continue



            # Check if t2 dominates t1



            all_better = True



            for obj in objectives:



                v1 = t1["metrics"].get(obj, 0)



                v2 = t2["metrics"].get(obj, 0)



                if obj == "uncertainty_ece":  # Lower is better



                    if v2 >= v1:



                        all_better = False



                else:  # Higher is better



                    if v2 <= v1:



                        all_better = False



            if all_better:



                dominated = True



                break



        if not dominated:



            pareto_front.append(t1)







    # Sort Pareto front by first objective



    pareto_front.sort(key=lambda t: t["metrics"].get(objectives[0], 0), reverse=True)







    result = {



        "graph_id": graph_id,



        "objectives": objectives,



        "num_trials": num_trials,



        "pareto_front_size": len(pareto_front),



        "pareto_front": [



            {"config": t["config"],



             "metrics": {obj: t["metrics"].get(obj, 0) for obj in objectives},



             "composite": t["metrics"]["composite_score"]}



            for t in pareto_front[:10]



        ],



        "knee_point": pareto_front[0] if pareto_front else None,



        "extremes": {



            "best_accuracy": max(trials, key=lambda t: t["metrics"]["private_accuracy"]),



            "best_privacy": max(trials, key=lambda t: t["metrics"]["privacy_score"]),



            "best_uncertainty": min(trials, key=lambda t: t["metrics"]["uncertainty_ece"]),



        },



        "inference_time_ms": round((time.time() - t0) * 1000, 2),



    }



    _automl_cache[f"{graph_id}_multi_obj"] = result



    return result











