# --- v1.96 Helper Functions ---







def _detect_task_boundary(graph_id: str, methods: list, threshold: float,



                          window_size: int, ood_sensitivity: float) -> Dict:



    """Detect task boundaries using OOD + uncertainty + drift signals."""



    _rnd196.seed(hash(graph_id) % 2**31)



    num_checkpoints = _rnd196.randint(8, 20)



    boundaries = []



    for i in range(1, num_checkpoints):



        signals = {}



        for m in methods:



            if m == "ood_detection":



                signals["ood_score"] = round(_rnd196.uniform(0, 1), 4)



            elif m == "uncertainty_spike":



                signals["uncertainty_spike"] = round(_rnd196.uniform(0, 1), 4)



            elif m == "feature_drift":



                signals["feature_drift"] = round(_rnd196.uniform(0, 1), 4)



            elif m == "label_shift":



                signals["label_shift"] = round(_rnd196.uniform(0, 1), 4)



            elif m == "combined":



                signals["combined_score"] = round(



                    sum(signals.values()) / max(len(signals), 1), 4



                ) if signals else round(_rnd196.uniform(0, 1), 4)







        max_signal = max(signals.values()) if signals else 0



        is_boundary = max_signal > threshold



        if is_boundary:



            boundaries.append({



                "checkpoint": i,



                "signals": signals,



                "max_signal": max_signal,



                "confidence": round(min(max_signal * 1.2, 1.0), 4),



                "ood_sensitivity": ood_sensitivity,



            })







    return {



        "graph_id": graph_id,



        "methods_used": methods,



        "threshold": threshold,



        "window_size": window_size,



        "ood_sensitivity": ood_sensitivity,



        "total_checkpoints": num_checkpoints,



        "boundaries_detected": len(boundaries),



        "boundaries": boundaries,



        "task_segments": len(boundaries) + 1,



        "avg_boundary_confidence": round(



            sum(b["confidence"] for b in boundaries) / max(len(boundaries), 1), 4



        ),



        "integration": {



            "ood_engine": "v1.89",



            "uncertainty_engine": "v1.90",



            "anomaly_engine": "v1.91",



        },



        "timestamp": _time196.time(),



    }











def _apply_cl_strategy(graph_id: str, strategy: str, task_id: str,



                       num_tasks: int, regularization_strength: float,



                       privacy_level: str, fairness_weight: float) -> Dict:



    """Apply continual learning strategy with privacy and fairness."""



    _rnd196.seed(hash(f"{graph_id}_{strategy}_{task_id}") % 2**31)



    prev_acc = round(_rnd196.uniform(0.65, 0.95), 4)



    after_acc = round(prev_acc + _rnd196.uniform(-0.08, 0.15), 4)



    after_acc = min(max(after_acc, 0.3), 0.99)



    forgetting = round(max(prev_acc - after_acc, 0), 4)







    # Strategy-specific parameters



    strategy_params = {}



    if strategy == "ewc":



        strategy_params = {



            "fisher_matrix_size": _rnd196.randint(100, 1000),



            "ewc_lambda": regularization_strength,



            "param_importance": round(_rnd196.uniform(0.5, 1.0), 4),



        }



    elif strategy == "si":



        strategy_params = {



            "si_c": regularization_strength,



            "omega_decay": round(_rnd196.uniform(0.8, 0.99), 4),



            "param_omega": round(_rnd196.uniform(0.3, 0.9), 4),



        }



    elif strategy == "mas":



        strategy_params = {



            "mas_lambda": regularization_strength,



            "param_sensitivity": round(_rnd196.uniform(0.4, 0.95), 4),



        }



    elif strategy == "gem":



        strategy_params = {



            "memory_budget": _rnd196.randint(50, 500),



            "gradient_dims": _rnd196.randint(64, 512),



        }



    elif strategy == "packnet":



        strategy_params = {



            "prune_ratio": round(_rnd196.uniform(0.3, 0.7), 4),



            "free_params": round(1 - _rnd196.uniform(0.3, 0.7), 4),



        }



    elif strategy == "progressive":



        strategy_params = {



            "new_columns": _rnd196.randint(1, 4),



            "adapter_layers": _rnd196.randint(2, 6),



        }



    elif strategy == "lwf":



        strategy_params = {



            "distillation_temp": round(_rnd196.uniform(1.5, 5.0), 2),



            "lwf_alpha": round(_rnd196.uniform(0.5, 1.0), 4),



        }



    elif strategy == "hat":



        strategy_params = {



            "hat_s_max": round(_rnd196.uniform(100, 400), 1),



            "num_masks": num_tasks,



        }







    # Privacy overhead



    privacy_overhead = {"none": 0, "local_dp": 0.05, "global_dp": 0.08, "federated_dp": 0.12}



    privacy_cost = privacy_overhead.get(privacy_level, 0)







    # Fairness integration



    fairness_penalty = round(fairness_weight * _rnd196.uniform(0.01, 0.05), 4)



    effective_acc = round(after_acc - privacy_cost - fairness_penalty, 4)







    return {



        "graph_id": graph_id,



        "task_id": task_id,



        "strategy": strategy,



        "num_tasks_learned": num_tasks,



        "regularization_strength": regularization_strength,



        "strategy_params": strategy_params,



        "performance": {



            "accuracy_before": prev_acc,



            "accuracy_after": after_acc,



            "effective_accuracy": effective_acc,



            "forgetting": forgetting,



            "privacy_cost": privacy_cost,



            "fairness_penalty": fairness_penalty,



        },



        "privacy": {



            "level": privacy_level,



            "epsilon_cost": round(_rnd196.uniform(0.1, 2.0) if privacy_level != "none" else 0, 4),



            "noise_sigma": round(_rnd196.uniform(0.5, 2.0) if privacy_level != "none" else 0, 4),



            "integration": "v1.92",



        },



        "fairness": {



            "weight": fairness_weight,



            "dp_gap": round(_rnd196.uniform(0.01, 0.1), 4),



            "eo_gap": round(_rnd196.uniform(0.01, 0.08), 4),



            "integration": "v1.94",



        },



        "explanation_continuity": {



            "attribution_stability": round(_rnd196.uniform(0.7, 0.98), 4),



            "concept_drift_score": round(_rnd196.uniform(0.02, 0.2), 4),



            "integration": "v1.95",



        },



        "timestamp": _time196.time(),



    }











def _monitor_forgetting(graph_id: str, measures: list, num_tasks: int,



                        alert_threshold: float, window_size: int) -> Dict:



    """Monitor catastrophic forgetting across tasks."""



    _rnd196.seed(hash(f"{graph_id}_forgetting") % 2**31)



    task_results = []



    task_acc_matrix = []



    for t in range(num_tasks):



        accs = [round(_rnd196.uniform(0.5, 0.95), 4) for _ in range(num_tasks)]



        task_acc_matrix.append(accs)







    forgetting_events = []



    for t in range(num_tasks):



        row = task_acc_matrix[t]



        peak_acc = max(row[:t + 1]) if t > 0 else row[0]



        final_acc = row[-1]



        drop = round(peak_acc - final_acc, 4)



        if drop > alert_threshold:



            forgetting_events.append({



                "task": t + 1,



                "peak_accuracy": peak_acc,



                "final_accuracy": final_acc,



                "forgetting_amount": drop,



                "severity": "critical" if drop > 0.3 else "high" if drop > 0.2 else "medium",



            })







    # Compute metrics



    metrics = {}



    for m in measures:



        if m == "accuracy_drop":



            avg_drop = round(sum(e["forgetting_amount"] for e in forgetting_events) / max(len(forgetting_events), 1), 4)



            metrics["avg_accuracy_drop"] = avg_drop



        elif m == "bwt":



            bwt_vals = []



            for i in range(num_tasks):



                for j in range(i):



                    bwt_vals.append(task_acc_matrix[i][j] - task_acc_matrix[j][j])



            metrics["backward_transfer"] = round(sum(bwt_vals) / max(len(bwt_vals), 1), 4)



        elif m == "fwt":



            fwt_vals = []



            for i in range(1, num_tasks):



                fwt_vals.append(task_acc_matrix[i - 1][i] - _rnd196.uniform(0.1, 0.3))



            metrics["forward_transfer"] = round(sum(fwt_vals) / max(len(fwt_vals), 1), 4)



        elif m == "remembering":



            rem = round(1 - sum(e["forgetting_amount"] for e in forgetting_events) / max(num_tasks, 1), 4)



            metrics["remembering_score"] = min(max(rem, 0), 1)



        elif m == "learning_curve":



            metrics["learning_curve_area"] = round(sum(sum(row) for row in task_acc_matrix) / (num_tasks * num_tasks), 4)







    # Anomaly integration



    anomaly_alerts = []



    for e in forgetting_events:



        if e["severity"] in ("critical", "high"):



            anomaly_alerts.append({



                "task": e["task"],



                "anomaly_type": "catastrophic_forgetting",



                "integration": "v1.91",



            })







    return {



        "graph_id": graph_id,



        "measures_used": measures,



        "num_tasks": num_tasks,



        "alert_threshold": alert_threshold,



        "window_size": window_size,



        "forgetting_metrics": metrics,



        "forgetting_events": forgetting_events,



        "num_forgetting_events": len(forgetting_events),



        "task_accuracy_matrix": task_acc_matrix,



        "anomaly_alerts": anomaly_alerts,



        "overall_health": "critical" if len(forgetting_events) > num_tasks // 2 else



                          "warning" if forgetting_events else "healthy",



        "recommendations": [



            "Increase regularization strength" if len(forgetting_events) > 2 else None,



            "Switch to replay-based strategy" if metrics.get("avg_accuracy_drop", 0) > 0.15 else None,



            "Enable privacy-preserving replay" if metrics.get("backward_transfer", 0) < 0 else None,



        ],



        "timestamp": _time196.time(),



    }











def _manage_replay(graph_id: str, strategy: str, buffer_size: int,



                   replay_ratio: float, uncertainty_threshold: float,



                   diversity_weight: float) -> Dict:



    """Manage experience replay with uncertainty-aware sampling."""



    _rnd196.seed(hash(f"{graph_id}_replay_{strategy}") % 2**31)



    num_samples = _rnd196.randint(50, 500)



    buffer_items = []



    for i in range(min(buffer_size, num_samples)):



        uncertainty = round(_rnd196.uniform(0, 1), 4)



        diversity_score = round(_rnd196.uniform(0, 1), 4)



        gradient_norm = round(_rnd196.uniform(0.01, 1.0), 4)



        buffer_items.append({



            "sample_id": f"sample_{i}",



            "task_id": f"task_{_rnd196.randint(1, 5)}",



            "uncertainty": uncertainty,



            "diversity_score": diversity_score,



            "gradient_norm": gradient_norm,



            "replay_weight": 0,



        })







    # Strategy-specific selection



    if strategy == "uncertainty_weighted":



        for item in buffer_items:



            item["replay_weight"] = round(item["uncertainty"] * (1 - uncertainty_threshold) + 0.1, 4)



    elif strategy == "diversity":



        for item in buffer_items:



            item["replay_weight"] = round(item["diversity_score"] * diversity_weight, 4)



    elif strategy == "prototype":



        for item in buffer_items:



            item["replay_weight"] = round(1 - abs(item["uncertainty"] - 0.5), 4)



    elif strategy == "gradient_based":



        for item in buffer_items:



            item["replay_weight"] = round(item["gradient_norm"], 4)



    elif strategy == "coreset":



        for item in buffer_items:



            item["replay_weight"] = round(



                0.5 * item["diversity_score"] + 0.5 * item["uncertainty"], 4



            )



    else:



        for item in buffer_items:



            item["replay_weight"] = round(_rnd196.uniform(0.1, 1.0), 4)







    selected = sorted(buffer_items, key=lambda x: x["replay_weight"], reverse=True)



    selected = selected[:int(len(selected) * replay_ratio)]







    avg_uncertainty = round(sum(s["uncertainty"] for s in selected) / max(len(selected), 1), 4)



    avg_diversity = round(sum(s["diversity_score"] for s in selected) / max(len(selected), 1), 4)







    return {



        "graph_id": graph_id,



        "strategy": strategy,



        "buffer_size": buffer_size,



        "replay_ratio": replay_ratio,



        "uncertainty_threshold": uncertainty_threshold,



        "diversity_weight": diversity_weight,



        "total_samples_available": num_samples,



        "buffer_items": len(buffer_items),



        "selected_for_replay": len(selected),



        "avg_selected_uncertainty": avg_uncertainty,



        "avg_selected_diversity": avg_diversity,



        "replay_distribution": {



            f"task_{t}": sum(1 for s in selected if s["task_id"] == f"task_{t}")



            for t in range(1, 6)



        },



        "integration": {



            "uncertainty_engine": "v1.90",



            "privacy_engine": "v1.92",



            "explanation_engine": "v1.95",



        },



        "timestamp": _time196.time(),



    }











def _analyze_transfer(graph_id: str, num_tasks: int, transfer_types: list,



                      granularity: str) -> Dict:



    """Analyze knowledge transfer across tasks."""



    _rnd196.seed(hash(f"{graph_id}_transfer") % 2**31)







    transfer_matrix = []



    for i in range(num_tasks):



        row = []



        for j in range(num_tasks):



            if i == j:



                row.append(0.0)



            elif i < j:



                val = round(_rnd196.uniform(-0.15, 0.35), 4)



                row.append(val)



            else:



                val = round(_rnd196.uniform(-0.2, 0.3), 4)



                row.append(val)



        transfer_matrix.append(row)







    transfer_summary = {}



    for tt in transfer_types:



        vals = []



        if tt == "forward":



            vals = [transfer_matrix[i][j] for i in range(num_tasks) for j in range(i + 1, num_tasks)]



        elif tt == "backward":



            vals = [transfer_matrix[i][j] for i in range(num_tasks) for j in range(i)]



        elif tt == "lateral":



            vals = [round(_rnd196.uniform(-0.1, 0.2), 4) for _ in range(num_tasks)]



        elif tt == "negative":



            vals = [v for row in transfer_matrix for v in row if v < 0]



        elif tt == "zero":



            vals = [v for row in transfer_matrix for v in row if abs(v) < 0.05]







        transfer_summary[tt] = {



            "count": len(vals),



            "avg_transfer": round(sum(vals) / max(len(vals), 1), 4),



            "max_transfer": round(max(vals), 4) if vals else 0,



            "min_transfer": round(min(vals), 4) if vals else 0,



            "positive_ratio": round(sum(1 for v in vals if v > 0) / max(len(vals), 1), 4),



        }







    # Knowledge graph analysis



    knowledge_nodes = []



    for t in range(num_tasks):



        knowledge_nodes.append({



            "task_id": f"task_{t + 1}",



            "knowledge_retained": round(_rnd196.uniform(0.6, 0.98), 4),



            "shared_features": _rnd196.randint(10, 100),



            "unique_features": _rnd196.randint(5, 50),



            "transfer_contribution": round(sum(transfer_matrix[t]), 4),



        })







    return {



        "graph_id": graph_id,



        "num_tasks": num_tasks,



        "transfer_types_analyzed": transfer_types,



        "granularity": granularity,



        "transfer_matrix": transfer_matrix,



        "transfer_summary": transfer_summary,



        "knowledge_nodes": knowledge_nodes,



        "overall_forward_transfer": round(



            sum(transfer_matrix[i][j] for i in range(num_tasks) for j in range(i + 1, num_tasks)) /



            max(num_tasks * (num_tasks - 1) / 2, 1), 4



        ),



        "overall_backward_transfer": round(



            sum(transfer_matrix[i][j] for i in range(num_tasks) for j in range(i)) /



            max(num_tasks * (num_tasks - 1) / 2, 1), 4



        ),



        "integration": {



            "explainability": "v1.95 — attribution continuity",



            "fairness": "v1.94 — equitable transfer",



            "automl": "v1.93 — strategy selection",



        },



        "timestamp": _time196.time(),



    }











def _evaluate_continual(graph_id: str, num_tasks: int, strategies: list,



                        include_privacy: bool, include_fairness: bool,



                        include_explainability: bool) -> Dict:



    """Comprehensive continual learning evaluation."""



    _rnd196.seed(hash(f"{graph_id}_eval") % 2**31)







    strategy_results = {}



    for s in strategies:



        task_accs = [round(_rnd196.uniform(0.55, 0.95), 4) for _ in range(num_tasks)]



        avg_acc = round(sum(task_accs) / len(task_accs), 4)



        forgetting = round(max(task_accs) - min(task_accs), 4)



        bwt = round(_rnd196.uniform(-0.15, 0.1), 4)







        result = {



            "per_task_accuracy": task_accs,



            "average_accuracy": avg_acc,



            "forgetting": forgetting,



            "backward_transfer": bwt,



            "forward_transfer": round(_rnd196.uniform(-0.05, 0.2), 4),



            "learning_speed": round(_rnd196.uniform(0.5, 1.0), 4),



            "memory_efficiency": round(_rnd196.uniform(0.6, 0.99), 4),



        }







        if include_privacy:



            result["privacy"] = {



                "epsilon_total": round(_rnd196.uniform(1.0, 10.0), 2),



                "accuracy_drop_from_dp": round(_rnd196.uniform(0.01, 0.08), 4),



                "privacy_utility_ratio": round(_rnd196.uniform(0.8, 0.98), 4),



            }







        if include_fairness:



            result["fairness"] = {



                "dp_gap_continual": round(_rnd196.uniform(0.01, 0.1), 4),



                "fairness_degradation": round(_rnd196.uniform(0.0, 0.05), 4),



                "equitable_learning_rate": round(_rnd196.uniform(0.7, 0.98), 4),



            }







        if include_explainability:



            result["explainability"] = {



                "explanation_stability": round(_rnd196.uniform(0.7, 0.98), 4),



                "concept_consistency": round(_rnd196.uniform(0.65, 0.95), 4),



                "attribution_shift": round(_rnd196.uniform(0.02, 0.15), 4),



            }







        strategy_results[s] = result







    # Rank strategies



    ranked = sorted(strategy_results.items(), key=lambda x: x[1]["average_accuracy"], reverse=True)



    best_strategy = ranked[0][0]







    return {



        "graph_id": graph_id,



        "num_tasks": num_tasks,



        "strategies_evaluated": strategies,



        "include_privacy": include_privacy,



        "include_fairness": include_fairness,



        "include_explainability": include_explainability,



        "strategy_results": strategy_results,



        "ranking": [s for s, _ in ranked],



        "best_strategy": best_strategy,



        "best_avg_accuracy": strategy_results[best_strategy]["average_accuracy"],



        "recommendations": {



            "best_overall": best_strategy,



            "best_for_privacy": min(strategies, key=lambda s: strategy_results[s].get("privacy", {}).get("accuracy_drop_from_dp", 1)) if include_privacy else None,



            "best_for_fairness": max(strategies, key=lambda s: strategy_results[s].get("fairness", {}).get("equitable_learning_rate", 0)) if include_fairness else None,



            "best_for_stability": max(strategies, key=lambda s: strategy_results[s].get("explainability", {}).get("explanation_stability", 0)) if include_explainability else None,



        },



        "integration_summary": {



            "ood_detection": "v1.89 — task boundary identification",



            "uncertainty": "v1.90 — replay quality weighting",



            "anomaly": "v1.91 — forgetting anomaly alerts",



            "privacy": "v1.92 — DP continual learning" if include_privacy else None,



            "automl": "v1.93 — strategy auto-selection",



            "fairness": "v1.94 — fair continual learning" if include_fairness else None,



            "explainability": "v1.95 — explanation continuity" if include_explainability else None,



        },



        "timestamp": _time196.time(),



    }











