# --- v1.97 Enums ---







class CertificationType(str, Enum):



    DETERMINISTIC = "deterministic"



    RANDOMIZED_SMOOTHING = "randomized_smoothing"



    INTERVAL_BOUND = "interval_bound"



    LINEAR_PROGRAMMING = "linear_programming"



    CONVEX_RELAXATION = "convex_relaxation"











class PerturbationNorm(str, Enum):



    L0 = "l0"



    L1 = "l1"



    L2 = "l2"



    LINF = "linf"



    SPECTRAL = "spectral"











class RobustnessLevel(str, Enum):



    CERTIFIED = "certified"



    PROBABLY_ROBUST = "probably_robust"



    UNKNOWN = "unknown"



    VULNERABLE = "vulnerable"



    CRITICALLY_VULNERABLE = "critically_vulnerable"











class DistributionShift(str, Enum):



    COVARIATE_SHIFT = "covariate_shift"



    CONCEPT_SHIFT = "concept_shift"



    STRUCTURAL_SHIFT = "structural_shift"



    LABEL_SHIFT = "label_shift"



    ADVERSARIAL_SHIFT = "adversarial_shift"











class HardeningMethod(str, Enum):



    ADVERSARIAL_TRAINING = "adversarial_training"



    CERTIFIABLE_TRAINING = "certifiable_training"



    ROBUST_AGGREGATION = "robust_aggregation"



    GRAPH_PURIFICATION = "graph_purification"



    STRUCTURAL_REGULARIZATION = "structural_regularization"



    ENSEMBLE_HARDENING = "ensemble_hardening"











class CascadeType(str, Enum):



    NODE_FAILURE = "node_failure"



    EDGE_FAILURE = "edge_failure"



