class DistillV2NASRequest(BaseModel):



    graph_id: str = Field(default="default-graph")



    search_space: str = Field(default="cell_based")



    objective: str = Field(default="composite")



    compression_ratio: float = Field(default=0.5, ge=0.1, le=0.9)



    temperature: float = Field(default=3.0, ge=0.5, le=20.0)



    alpha: float = Field(default=0.7, ge=0.0, le=1.0)



    nas_integration: bool = Field(default=True)



    seed: int = Field(default=42)











class DistillV2PrivacyRequest(BaseModel):



    graph_id: str = Field(default="default-graph")



    privacy_level: str = Field(default="local_dp")



    epsilon: float = Field(default=3.0, ge=0.1, le=100.0)



    delta: float = Field(default=1e-5, ge=1e-10, le=1e-1)



    compression_ratio: float = Field(default=0.5, ge=0.1, le=0.9)



