    """Execute meta-learning training with specified strategy."""



    result = _meta_training(



        req.graph_id, req.strategy, req.num_tasks,



        req.meta_lr, req.inner_lr, req.num_inner_steps,



        req.num_meta_steps, req.init_method, req.seed,



    )



    _meta_v2_train_cache[result["task_id"]] = result



    return result











