class SSLPretextType(str, Enum):



    contrastive = "contrastive"



    generative = "generative"



    predictive = "predictive"



    reasoning_guided = "reasoning_guided"



    causal_structure = "causal_structure"



    multi_view = "multi_view"







class SSLEncoderType(str, Enum):



    gcn = "gcn"



    gat = "gat"



    gin = "gin"



    sage = "sage"



    gine = "gine"



    pna = "pna"







class SSLScale(str, Enum):



    node = "node"



    edge = "edge"



    subgraph = "subgraph"



    graph = "graph"



    path = "path"



    motif = "motif"







class SSLCLMode(str, Enum):



    ewc = "ewc"



    si = "si"



    mas = "mas"



    progressive = "progressive"



    packnet = "packnet"



    reasoning_aware = "reasoning_aware"







class SSLQualityMetric(str, Enum):



    transferability = "transferability"



    discriminability = "discriminability"



    robustness = "robustness"



    fairness = "fairness"



    calibration = "calibration"



    completeness = "completeness"







class SSLPipelineStrategy(str, Enum):



    curriculum = "curriculum"



    self_paced = "self_paced"



    transfer_guided = "transfer_guided"



    difficulty_aware = "difficulty_aware"



    budget_aware = "budget_aware"



    adaptive = "adaptive"







class SSLLossType(str, Enum):



    info_nce = "info_nce"



    triplet = "triplet"



    jensen_shannon = "jensen_shannon"



    barlow_twins = "barlow_twins"



    vicreg = "vicreg"



    byol = "byol"







