# --- Computation Functions ---











def _fed_reason_partition(



    graph_id: str, partition_method: str, num_clients: int,



    overlap_ratio: float, boundary_strategy: str, topology_config: dict,



) -> dict:



    """Federated graph partitioning with boundary management."""



    import random as _rng



    _rng.seed(hash(graph_id) % (2**31))



    clients = []



    for i in range(num_clients):



        n_nodes = _rng.randint(80, 500)



        n_edges = int(n_nodes * _rng.uniform(2.0, 6.0))



        boundary_nodes = int(n_nodes * overlap_ratio)



        internal_edges = n_edges - int(boundary_nodes * _rng.uniform(1.5, 3.0))



        cross_edges = n_edges - internal_edges



        clients.append({



            "client_id": f"client_{i}",



            "client_type": list(FedClientType.__members__.values())[i % 6].value,



            "num_nodes": n_nodes,



            "num_edges": n_edges,



            "boundary_nodes": boundary_nodes,



            "internal_edges": internal_edges,



            "cross_edges": cross_edges,



            "partition_quality": round(_rng.uniform(0.75, 0.98), 4),



            "edge_cut_ratio": round(cross_edges / max(n_edges, 1), 4),



            "balance_score": round(1.0 - abs(n_nodes - 300) / 500, 4),



            "modularity": round(_rng.uniform(0.4, 0.9), 4),



            "conductance": round(_rng.uniform(0.05, 0.35), 4),



        })



    total_boundary = sum(c["boundary_nodes"] for c in clients)



    total_cross = sum(c["cross_edges"] for c in clients)



    avg_quality = round(sum(c["partition_quality"] for c in clients) / len(clients), 4)



    avg_balance = round(sum(c["balance_score"] for c in clients) / len(clients), 4)



    return {



        "graph_id": graph_id,



        "partition_method": partition_method,



        "num_clients": num_clients,



        "overlap_ratio": overlap_ratio,



        "boundary_strategy": boundary_strategy,



        "topology_config": topology_config,



        "clients": clients,



        "partition_stats": {



            "total_boundary_nodes": total_boundary,



            "total_cross_edges": total_cross,



            "avg_partition_quality": avg_quality,



            "avg_balance_score": avg_balance,



            "global_modularity": round(_rng.uniform(0.45, 0.85), 4),



            "communication_cost_estimate": round(total_cross * 0.001, 4),



        },



        "comparison": {



            m: {"quality": round(_rng.uniform(0.6, 0.98), 4), "balance": round(_rng.uniform(0.5, 0.99), 4)}



            for m in [e.value for e in FedGraphPartition]



        },



    }











def _fed_reason_privacy(



    graph_id: str, privacy_level: str, epsilon: float, delta: float,



    reasoning_type: str, num_rounds: int, sensitivity: float,



) -> dict:



    """Privacy-preserving distributed reasoning with DP guarantees."""



    import random as _rng



    _rng.seed(hash(graph_id + privacy_level) % (2**31))



    rounds = []



    cumulative_privacy_cost = 0.0



    for r in range(num_rounds):



        noise_scale = sensitivity / max(epsilon, 0.01)



        privacy_cost_this_round = epsilon / num_rounds



        cumulative_privacy_cost += privacy_cost_this_round



        reasoning_acc = max(0.3, 1.0 - noise_scale * _rng.uniform(0.1, 0.5) - cumulative_privacy_cost * 0.01)



        rounds.append({



            "round": r + 1,



            "privacy_cost": round(privacy_cost_this_round, 6),



            "cumulative_epsilon": round(cumulative_privacy_cost, 6),



            "noise_scale": round(noise_scale, 6),



            "reasoning_accuracy": round(reasoning_acc, 4),



            "signal_to_noise_ratio": round(_rng.uniform(2.0, 20.0), 4),



            "gradient_clip_norm": round(sensitivity * 1.5, 4),



            "perturbation_l2": round(noise_scale * _rng.uniform(0.5, 1.5), 6),



            "utility_preservation": round(max(0.4, 1.0 - noise_scale * 0.3), 4),



        })



    avg_acc = round(sum(r["reasoning_accuracy"] for r in rounds) / len(rounds), 4)



    avg_utility = round(sum(r["utility_preservation"] for r in rounds) / len(rounds), 4)



    privacy_levels = {



        lvl: {



            "epsilon": round(_rng.uniform(0.1, 10.0), 2),



            "utility": round(_rng.uniform(0.4, 0.99), 4),



            "reasoning_degradation": round(_rng.uniform(0.0, 0.3), 4),



            "recommendation": "optimal" if _rng.random() > 0.5 else "cautious",



        }



        for lvl in [e.value for e in FedPrivacyLevel]



    }



    return {



        "graph_id": graph_id,



        "privacy_level": privacy_level,



        "epsilon": epsilon,



        "delta": delta,



        "reasoning_type": reasoning_type,



        "num_rounds": num_rounds,



        "sensitivity": sensitivity,



        "rounds": rounds,



        "privacy_summary": {



            "total_epsilon_cost": round(cumulative_privacy_cost, 6),



            "avg_reasoning_accuracy": avg_acc,



            "avg_utility_preservation": avg_utility,



            "privacy_utility_tradeoff": round(avg_utility / max(cumulative_privacy_cost, 0.001), 4),



            "formal_guarantee": f"({epsilon},{delta})-differential privacy",



            "composition_method": "advanced_composition",



        },



        "reasoning_types_comparison": {



            rt: {"accuracy": round(_rng.uniform(0.5, 0.98), 4), "privacy_cost": round(_rng.uniform(0.1, 5.0), 4)}



            for rt in [e.value for e in FedReasoningType]



        },



        "privacy_level_comparison": privacy_levels,



    }











def _fed_reason_aggregate(



    graph_id: str, aggregation_method: str, num_clients: int,



    num_rounds: int, participation_rate: float,



) -> dict:



    """Cross-client knowledge aggregation with secure multi-party protocols."""



    import random as _rng



    _rng.seed(hash(graph_id + aggregation_method) % (2**31))



    participating = max(2, int(num_clients * participation_rate))



    clients_info = []



    for i in range(participating):



        clients_info.append({



            "client_id": f"client_{i}",



            "model_version": f"v_r{num_rounds}",



            "local_accuracy": round(_rng.uniform(0.6, 0.95), 4),



            "local_loss": round(_rng.uniform(0.05, 0.5), 4),



            "num_samples": _rng.randint(100, 5000),



            "contribution_weight": round(_rng.uniform(0.05, 0.3), 4),



            "gradient_norm": round(_rng.uniform(0.01, 2.0), 4),



            " staleness": _rng.randint(0, 3),



        })



    agg_rounds = []



    for r in range(min(num_rounds, 10)):



        global_acc = min(0.98, 0.5 + r * 0.04 + _rng.uniform(-0.02, 0.02))



        global_loss = max(0.01, 0.5 - r * 0.04 + _rng.uniform(-0.02, 0.02))



        agg_rounds.append({



            "round": r + 1,



            "participating_clients": participating,



            "global_accuracy": round(global_acc, 4),



            "global_loss": round(global_loss, 4),



            "aggregation_variance": round(_rng.uniform(0.001, 0.05), 6),



            "consensus_score": round(min(1.0, 0.6 + r * 0.03), 4),



            "divergence_metric": round(_rng.uniform(0.01, 0.2), 4),



            "communication_bytes": _rng.randint(100000, 5000000),



            "aggregation_time_ms": _rng.randint(50, 2000),



        })



    best_round = max(agg_rounds, key=lambda x: x["global_accuracy"])



    return {



        "graph_id": graph_id,



        "aggregation_method": aggregation_method,



        "num_clients": num_clients,



        "participation_rate": participation_rate,



        "actual_participants": participating,



        "clients": clients_info,



        "rounds": agg_rounds,



        "aggregation_summary": {



            "best_round": best_round["round"],



            "best_accuracy": best_round["global_accuracy"],



            "convergence_round": min(r["round"] for r in agg_rounds if r["global_accuracy"] > 0.85) if any(r["global_accuracy"] > 0.85 for r in agg_rounds) else num_rounds,



            "total_communication_mb": round(sum(r["communication_bytes"] for r in agg_rounds) / 1e6, 2),



            "avg_consensus": round(sum(r["consensus_score"] for r in agg_rounds) / len(agg_rounds), 4),



        },



        "method_comparison": {



            m: {"final_accuracy": round(_rng.uniform(0.6, 0.98), 4), "convergence_speed": round(_rng.uniform(0.3, 1.0), 4)}



            for m in [e.value for e in FedAggregation]



        },



    }











def _fed_reason_communicate(



    graph_id: str, compress_method: str, bandwidth_limit_mbps: float,



    num_rounds: int, message_size_mb: float, latency_ms: float,



) -> dict:



    """Communication-efficient training with gradient compression."""



    import random as _rng



    _rng.seed(hash(graph_id + compress_method) % (2**31))



    if compress_method == "none":



        compression_ratio = 1.0



    elif compress_method == "topk":



        compression_ratio = _rng.uniform(0.01, 0.1)



    elif compress_method == "randomk":



        compression_ratio = _rng.uniform(0.05, 0.2)



    elif compress_method == "quantization":



        compression_ratio = _rng.uniform(0.1, 0.33)



    elif compress_method == "sparsification":



        compression_ratio = _rng.uniform(0.02, 0.15)



    else:



        compression_ratio = _rng.uniform(0.1, 0.5)



    rounds_data = []



    for r in range(min(num_rounds, 10)):



        original_size = message_size_mb



        compressed_size = round(original_size * compression_ratio, 4)



        transfer_time = round(compressed_size / max(bandwidth_limit_mbps, 0.1) * 1000 + latency_ms, 2)



        rounds_data.append({



            "round": r + 1,



            "original_size_mb": original_size,



            "compressed_size_mb": compressed_size,



            "compression_ratio": round(compression_ratio, 4),



            "transfer_time_ms": transfer_time,



            "bandwidth_used_mbps": round(compressed_size / max(transfer_time / 1000, 0.001), 2),



            "info_loss": round(_rng.uniform(0.001, 0.05) * compression_ratio, 6),



            "reconstruction_error": round(_rng.uniform(0.001, 0.02), 6),



            "gradient_fidelity": round(1.0 - _rng.uniform(0.001, 0.05) * compression_ratio, 4),



        })



    total_original = sum(r["original_size_mb"] for r in rounds_data)



    total_compressed = sum(r["compressed_size_mb"] for r in rounds_data)



    avg_fidelity = round(sum(r["gradient_fidelity"] for r in rounds_data) / len(rounds_data), 4)



    return {



        "graph_id": graph_id,



        "compress_method": compress_method,



        "bandwidth_limit_mbps": bandwidth_limit_mbps,



        "num_rounds": num_rounds,



        "message_size_mb": message_size_mb,



        "latency_ms": latency_ms,



        "rounds": rounds_data,



        "communication_summary": {



            "total_original_mb": round(total_original, 2),



            "total_compressed_mb": round(total_compressed, 2),



            "total_savings_pct": round((1 - total_compressed / max(total_original, 0.001)) * 100, 2),



            "avg_transfer_time_ms": round(sum(r["transfer_time_ms"] for r in rounds_data) / len(rounds_data), 2),



            "avg_gradient_fidelity": avg_fidelity,



            "bandwidth_efficiency": round(min(1.0, bandwidth_limit_mbps / 100), 4),



        },



        "method_comparison": {



            m: {



                "ratio": round(_rng.uniform(0.01, 1.0), 4),



                "fidelity": round(_rng.uniform(0.7, 0.999), 4),



                "speed": round(_rng.uniform(0.3, 1.0), 4),



            }



            for m in [e.value for e in FedCompressMethod]



        },



    }











def _fed_reason_heterogeneous(



    graph_id: str, num_clients: int, client_distribution: str,



    data_heterogeneity: float, resource_variance: float,



) -> dict:



    """Heterogeneous client adaptation handling different capabilities."""



    import random as _rng



    _rng.seed(hash(graph_id + client_distribution) % (2**31))



    client_types = [e.value for e in FedClientType]



    clients = []



    for i in range(num_clients):



        c_type = client_types[i % len(client_types)]



        if c_type == "high_resource":



            compute_power = _rng.uniform(0.8, 1.0)



            memory_gb = _rng.uniform(16, 64)



            bandwidth = _rng.uniform(50, 1000)



        elif c_type == "medium_resource":



            compute_power = _rng.uniform(0.5, 0.8)



            memory_gb = _rng.uniform(8, 16)



            bandwidth = _rng.uniform(10, 50)



        elif c_type == "low_resource":



            compute_power = _rng.uniform(0.2, 0.5)



            memory_gb = _rng.uniform(2, 8)



            bandwidth = _rng.uniform(1, 10)



        elif c_type == "edge":



            compute_power = _rng.uniform(0.1, 0.3)



            memory_gb = _rng.uniform(1, 4)



            bandwidth = _rng.uniform(0.5, 5)



        elif c_type == "mobile":



            compute_power = _rng.uniform(0.05, 0.2)



            memory_gb = _rng.uniform(0.5, 2)



            bandwidth = _rng.uniform(0.1, 2)



        else:



            compute_power = _rng.uniform(0.01, 0.1)



            memory_gb = _rng.uniform(0.1, 0.5)



            bandwidth = _rng.uniform(0.01, 0.5)



        data_skew = round(data_heterogeneity * _rng.uniform(0.5, 1.5), 4)



        clients.append({



            "client_id": f"client_{i}",



            "client_type": c_type,



            "compute_power": round(compute_power, 4),



            "memory_gb": round(memory_gb, 2),



            "bandwidth_mbps": round(bandwidth, 2),



            "data_skew": data_skew,



            "local_epochs": max(1, int(compute_power * 10)),



            "batch_size": max(8, int(memory_gb * 4)),



            "model_capacity": round(compute_power * _rng.uniform(0.5, 1.0), 4),



            "training_time_s": round(_rng.uniform(1, 300) / max(compute_power, 0.01), 2),



            " staleness_tolerance": _rng.randint(0, 5),



            "adaptation_strategy": "full" if compute_power > 0.6 else ("partial" if compute_power > 0.3 else "minimal"),



        })



    avg_compute = round(sum(c["compute_power"] for c in clients) / len(clients), 4)



    max_staleness = max(c["staleness_tolerance"] for c in clients)



    return {



        "graph_id": graph_id,



        "num_clients": num_clients,



        "client_distribution": client_distribution,



        "data_heterogeneity": data_heterogeneity,



        "resource_variance": resource_variance,



        "clients": clients,



        "adaptation_summary": {



            "type_distribution": {t: sum(1 for c in clients if c["client_type"] == t) for t in client_types},



            "avg_compute_power": avg_compute,



            "max_compute_gap": round(max(c["compute_power"] for c in clients) - min(c["compute_power"] for c in clients), 4),



            "avg_data_skew": round(sum(c["data_skew"] for c in clients) / len(clients), 4),



            "stragglers_count": sum(1 for c in clients if c["compute_power"] < 0.3),



            "synchronization_strategy": "async" if max_staleness > 2 else "sync",



            "recommended_aggregation": "fednova" if resource_variance > 0.5 else ("fedprox" if data_heterogeneity > 0.5 else "fedavg"),



        },



        "distribution_comparison": {



            dist: {"heterogeneity_score": round(_rng.uniform(0.1, 1.0), 4), "convergence_rounds": _rng.randint(10, 100)}



            for dist in ["iid", "non_iid_label", "non_iid_quantity", "non_iid_feature", "realistic"]



        },



    }











def _fed_reason_pipeline(



    graph_id: str, total_rounds: int, privacy_budget: float,



    num_clients: int, target_accuracy: float,



) -> dict:



    """Autonomous federated reasoning pipeline with end-to-end orchestration."""



    import random as _rng



    _rng.seed(hash(graph_id) % (2**31))



    stages = [



        {"name": "graph_partitioning", "status": "completed"},



        {"name": "client_initialization", "status": "completed"},



        {"name": "privacy_budget_allocation", "status": "completed"},



        {"name": "federated_training", "status": "completed"},



        {"name": "global_aggregation", "status": "completed"},



        {"name": "reasoning_validation", "status": "completed"},



        {"name": "deployment", "status": "completed"},



    ]



    for s in stages:



        s["quality"] = round(_rng.uniform(0.7, 0.99), 4)



        s["privacy_cost"] = round(_rng.uniform(0.01, privacy_budget / 7), 6)



        s["duration_s"] = round(_rng.uniform(5, 300), 2)



    total_privacy = round(sum(s["privacy_cost"] for s in stages), 6)



    remaining_budget = round(privacy_budget - total_privacy, 6)



    final_acc = min(0.99, target_accuracy + _rng.uniform(-0.05, 0.05))



    resource_usage = {



        "total_gpu_hours": round(_rng.uniform(1, 50), 2),



        "peak_memory_gb": round(_rng.uniform(2, 32), 2),



        "total_data_gb": round(_rng.uniform(0.1, 100), 2),



        "total_communication_gb": round(_rng.uniform(0.01, 10), 2),



        "total_wall_time_hours": round(_rng.uniform(0.5, 24), 2),



    }



    return {



        "graph_id": graph_id,



        "total_rounds": total_rounds,



        "privacy_budget": privacy_budget,



        "num_clients": num_clients,



        "target_accuracy": target_accuracy,



        "stages": stages,



        "pipeline_summary": {



            "final_accuracy": round(final_acc, 4),



            "target_met": final_acc >= target_accuracy,



            "privacy_remaining": remaining_budget,



            "privacy_budget_utilization": round(total_privacy / max(privacy_budget, 0.001) * 100, 2),



            "total_duration_s": round(sum(s["duration_s"] for s in stages), 2),



            "best_aggregation_method": _rng.choice([e.value for e in FedAggregation]),



            "best_partition_method": _rng.choice([e.value for e in FedGraphPartition]),



            "best_privacy_level": _rng.choice([e.value for e in FedPrivacyLevel]),



            "within_budget": remaining_budget >= 0,



        },



        "resource_usage": resource_usage,



        "distillation_v3_integration": {



            "teacher_distillation": "enabled",



            "student_compression_ratio": round(_rng.uniform(0.1, 0.5), 4),



            "reasoning_preservation": round(_rng.uniform(0.8, 0.99), 4),



        },



        "ssl_v3_integration": {



            "pretrained_encoders": "enabled",



            "representation_quality": round(_rng.uniform(0.75, 0.98), 4),



            "label_efficiency": round(_rng.uniform(0.5, 0.95), 4),



        },



    }











