# --- Computation Functions ---











def _auto_learn_curiosity(



    graph_id: str, curiosity_type: str, exploration_budget: int,



    num_frontier_nodes: int, novelty_decay: float,



) -> dict:



    """Curiosity-driven exploration with intrinsic motivation."""



    import random as _rng



    _rng.seed(hash(graph_id) % (2**31))



    frontier_nodes = []



    for i in range(num_frontier_nodes):



        prediction_error = round(_rng.uniform(0.1, 0.9), 4)



        information_gain = round(_rng.uniform(0.05, 0.8), 4)



        novelty_score = round(_rng.uniform(0.2, 1.0) * (1.0 - novelty_decay * (i / max(num_frontier_nodes, 1))), 4)



        competence_progress = round(_rng.uniform(0.05, 0.6), 4)



        semantic_gap = round(_rng.uniform(0.1, 0.7), 4)



        diversity_score = round(_rng.uniform(0.3, 1.0), 4)



        curiosity_scores = {



            "prediction_error": prediction_error,



            "information_gain": information_gain,



            "novelty_seeking": novelty_score,



            "competence_progress": competence_progress,



            "semantic_gap": semantic_gap,



            "diversity_driven": diversity_score,



        }



        frontier_nodes.append({



            "node_id": f"node_{i}",



            "node_type": _rng.choice(["entity", "relation", "attribute", "event", "concept", "pattern"]),



            "curiosity_scores": curiosity_scores,



            "primary_motivation": max(curiosity_scores, key=curiosity_scores.get),



            "exploration_priority": round(sum(curiosity_scores.values()) / 6.0, 4),



            "visited": False,



            "visit_count": 0,



            "last_visit_step": None,



            "knowledge_gap_estimate": round(_rng.uniform(0.3, 0.95), 4),



            "neighbors_unexplored": _rng.randint(2, 25),



            "embedding_distance_to_known": round(_rng.uniform(0.1, 0.8), 4),



        })



    frontier_nodes.sort(key=lambda n: n["exploration_priority"], reverse=True)



    total_budget_used = 0



    exploration_path = []



    for node in frontier_nodes:



        if total_budget_used >= exploration_budget:



            break



        cost = _rng.randint(1, 5)



        total_budget_used += cost



        node["visited"] = True



        node["visit_count"] = 1



        node["last_visit_step"] = len(exploration_path)



        exploration_path.append({



            "step": len(exploration_path) + 1,



            "node_id": node["node_id"],



            "curiosity_type": curiosity_type,



            "intrinsic_reward": round(node["exploration_priority"] * _rng.uniform(0.8, 1.2), 4),



            "knowledge_gained": round(_rng.uniform(0.05, 0.3), 4),



            "surprise_factor": round(_rng.uniform(0.0, 0.5), 4),



            "cost": cost,



        })



    avg_priority = round(sum(n["exploration_priority"] for n in frontier_nodes) / max(len(frontier_nodes), 1), 4)



    novelty_methods = ["prediction_error", "information_gain", "novelty_seeking", "competence_progress", "semantic_gap", "diversity_driven"]



    method_comparison = []



    for method in novelty_methods:



        scores = [n["curiosity_scores"][method] for n in frontier_nodes]



        avg_score = round(sum(scores) / max(len(scores), 1), 4)



        coverage = round(_rng.uniform(0.5, 0.95), 4)



        discovery_rate = round(_rng.uniform(0.3, 0.9), 4)



        method_comparison.append({



            "method": method,



            "avg_score": avg_score,



            "coverage_ratio": coverage,



            "discovery_rate": discovery_rate,



            "efficiency": round(avg_score * coverage, 4),



            "recommended_for": _rng.choice(["sparse_graphs", "dense_graphs", "heterogeneous", "dynamic", "large_scale", "any"]),



        })



    return {



        "graph_id": graph_id,



        "curiosity_type": curiosity_type,



        "exploration_budget": exploration_budget,



        "budget_used": total_budget_used,



        "budget_efficiency": round(total_budget_used / max(exploration_budget, 1), 4),



        "num_frontier_nodes": num_frontier_nodes,



        "nodes_explored": len(exploration_path),



        "frontier_nodes": frontier_nodes[:20],



        "exploration_path": exploration_path[:15],



        "average_priority": avg_priority,



        "novelty_decay": novelty_decay,



        "total_knowledge_gained": round(sum(s["knowledge_gained"] for s in exploration_path), 4),



        "total_surprise": round(sum(s["surprise_factor"] for s in exploration_path), 4),



        "method_comparison": method_comparison,



        "curiosity_distribution": {



            "high_curiosity": sum(1 for n in frontier_nodes if n["exploration_priority"] > 0.7),



            "medium_curiosity": sum(1 for n in frontier_nodes if 0.4 <= n["exploration_priority"] <= 0.7),



            "low_curiosity": sum(1 for n in frontier_nodes if n["exploration_priority"] < 0.4),



        },



        "recommendations": [



            "Focus exploration on high-prediction-error frontier nodes",



            "Use information_gain method for sparse graph regions",



            "Apply novelty decay to avoid redundant exploration",



            "Combine competence_progress with semantic_gap for balanced learning",



        ],



    }











def _auto_learn_intrinsic_reward(



    graph_id: str, reward_type: str, num_steps: int,



    exploration_rate: float, skill_level: float,



) -> dict:



    """Intrinsic reward shaping for self-motivated learning."""



    import random as _rng



    _rng.seed(hash(f"{graph_id}_{reward_type}") % (2**31))



    reward_types = ["exploration_bonus", "learning_progress", "empowerment", "state_novelty", "skill_mastery", "knowledge_density"]



    steps_data = []



    cumulative_reward = 0.0



    for step in range(num_steps):



        progress = step / max(num_steps, 1)



        exploration_factor = exploration_rate * (1.0 - progress * 0.5)



        exploitation_factor = 1.0 - exploration_factor



        base_reward = _rng.uniform(0.1, 1.0)



        intrinsic_r = base_reward * (exploration_factor + skill_level * exploitation_factor)



        extrinsic_r = base_reward * exploitation_factor * skill_level



        cumulative_reward += intrinsic_r



        steps_data.append({



            "step": step + 1,



            "phase": "exploration" if exploration_factor > 0.5 else ("balanced" if exploration_factor > 0.25 else "exploitation"),



            "intrinsic_reward": round(intrinsic_r, 4),



            "extrinsic_reward": round(extrinsic_r, 4),



            "total_reward": round(intrinsic_r + extrinsic_r, 4),



            "cumulative_reward": round(cumulative_reward, 4),



            "exploration_weight": round(exploration_factor, 4),



            "exploitation_weight": round(exploitation_factor, 4),



            "skill_level": round(min(1.0, skill_level + progress * 0.3), 4),



            "knowledge_coverage": round(min(1.0, progress * _rng.uniform(0.6, 1.0)), 4),



            "surprise_index": round(_rng.uniform(0.0, 0.5) * (1 - progress), 4),



        })



    reward_comparison = []



    for rt in reward_types:



        avg_intrinsic = round(_rng.uniform(0.2, 0.9), 4)



        consistency = round(_rng.uniform(0.5, 0.98), 4)



        sample_efficiency = round(_rng.uniform(0.4, 0.95), 4)



        reward_comparison.append({



            "reward_type": rt,



            "avg_intrinsic_reward": avg_intrinsic,



            "consistency": consistency,



            "sample_efficiency": sample_efficiency,



            "convergence_speed": round(_rng.uniform(0.3, 0.9), 4),



            "skill_acceleration": round(avg_intrinsic * consistency, 4),



            "best_for": _rng.choice(["early_exploration", "mid_learning", "late_refinement", "transfer", "robustness", "any_phase"]),



        })



    return {



        "graph_id": graph_id,



        "reward_type": reward_type,



        "num_steps": num_steps,



        "exploration_rate": exploration_rate,



        "initial_skill_level": skill_level,



        "final_skill_level": steps_data[-1]["skill_level"] if steps_data else skill_level,



        "skill_improvement": round((steps_data[-1]["skill_level"] if steps_data else skill_level) - skill_level, 4),



        "total_cumulative_reward": round(cumulative_reward, 4),



        "average_reward_per_step": round(cumulative_reward / max(num_steps, 1), 4),



        "steps": steps_data[:30],



        "reward_comparison": reward_comparison,



        "learning_efficiency": {



            "early_phase_avg": round(sum(s["total_reward"] for s in steps_data[:num_steps // 3]) / max(num_steps // 3, 1), 4) if num_steps > 2 else 0,



            "mid_phase_avg": round(sum(s["total_reward"] for s in steps_data[num_steps // 3:2 * num_steps // 3]) / max(num_steps // 3, 1), 4) if num_steps > 2 else 0,



            "late_phase_avg": round(sum(s["total_reward"] for s in steps_data[2 * num_steps // 3:]) / max(num_steps // 3, 1), 4) if num_steps > 2 else 0,



        },



        "knowledge_coverage_final": steps_data[-1]["knowledge_coverage"] if steps_data else 0,



        "recommendations": [



            "Use exploration_bonus for initial graph discovery phase",



            "Switch to learning_progress during skill acquisition",



            "Apply knowledge_density for fine-grained representation learning",



        ],



    }











def _auto_learn_curriculum(



    graph_id: str, strategy: str, num_tasks: int,



    initial_difficulty: float, mastery_threshold: float,



) -> dict:



    """Self-paced curriculum with autonomous task sequencing."""



    import random as _rng



    _rng.seed(hash(f"{graph_id}_{strategy}") % (2**31))



    tasks = []



    task_types = ["node_classification", "edge_prediction", "subgraph_matching", "path_reasoning", "pattern_recognition", "graph_generation"]



    difficulty_levels = ["trivial", "easy", "moderate", "challenging", "hard", "expert"]



    for i in range(num_tasks):



        difficulty = min(1.0, initial_difficulty + (i / max(num_tasks, 1)) * (1.0 - initial_difficulty))



        diff_idx = min(int(difficulty * 5), 5)



        prerequisite_count = min(i, _rng.randint(1, 3))



        tasks.append({



            "task_id": f"task_{i}",



            "task_type": _rng.choice(task_types),



            "difficulty": round(difficulty, 4),



            "difficulty_level": difficulty_levels[diff_idx],



            "prerequisites": [f"task_{j}" for j in range(max(0, i - prerequisite_count), i)],



            "readiness_score": round(max(0, min(1, difficulty * _rng.uniform(0.8, 1.2))), 4),



            "mastery_achieved": difficulty < mastery_threshold or _rng.random() > 0.3,



            "mastery_level": round(min(1.0, mastery_threshold + _rng.uniform(-0.1, 0.3)), 4) if difficulty < mastery_threshold else round(_rng.uniform(0.3, mastery_threshold), 4),



            "attempts": _rng.randint(1, 5),



            "learning_gain": round(_rng.uniform(0.05, 0.4), 4),



            "time_spent_ratio": round(_rng.uniform(0.5, 1.5), 4),



            "zone_of_proximal": abs(difficulty - (initial_difficulty + 0.3)) < 0.15,



            "skills_required": _rng.sample(["embedding", "aggregation", "attention", "pooling", "readout", "reasoning"], _rng.randint(2, 4)),



            "skills_acquired": _rng.sample(["embedding", "aggregation", "attention", "pooling", "readout", "reasoning"], _rng.randint(1, 3)),



            "cognitive_load": round(_rng.uniform(0.2, 0.9), 4),



        })



    strategies = ["difficulty_ascending", "competence_based", "readiness_scored", "zone_of_proximal", "spiral_curriculum", "adaptive_pacing"]



    strategy_comparison = []



    for s in strategies:



        avg_mastery = round(_rng.uniform(0.6, 0.95), 4)



        completion_rate = round(_rng.uniform(0.7, 1.0), 4)



        avg_time = round(_rng.uniform(0.6, 1.0), 4)



        strategy_comparison.append({



            "strategy": s,



            "avg_mastery": avg_mastery,



            "completion_rate": completion_rate,



            "efficiency": round(avg_mastery * completion_rate, 4),



            "avg_time_ratio": avg_time,



            "zone_utilization": round(_rng.uniform(0.5, 0.95), 4),



            "transfer_quality": round(_rng.uniform(0.4, 0.9), 4),



            "recommended_for": _rng.choice(["beginners", "intermediate", "advanced", "mixed_level", "self_paced", "guided"]),



        })



    mastered = sum(1 for t in tasks if t["mastery_achieved"])



    avg_mastery_level = round(sum(t["mastery_level"] for t in tasks) / max(len(tasks), 1), 4)



    avg_readiness = round(sum(t["readiness_score"] for t in tasks) / max(len(tasks), 1), 4)



    return {



        "graph_id": graph_id,



        "strategy": strategy,



        "num_tasks": num_tasks,



        "initial_difficulty": initial_difficulty,



        "mastery_threshold": mastery_threshold,



        "tasks": tasks[:25],



        "tasks_mastered": mastered,



        "mastery_rate": round(mastered / max(num_tasks, 1), 4),



        "average_mastery_level": avg_mastery_level,



        "average_readiness": avg_readiness,



        "curriculum_complete": mastered >= num_tasks * 0.8,



        "strategy_comparison": strategy_comparison,



        "learning_curve": {



            "tasks_attempted": num_tasks,



            "avg_attempts_to_master": round(sum(t["attempts"] for t in tasks if t["mastery_achieved"]) / max(mastered, 1), 2),



            "total_learning_gain": round(sum(t["learning_gain"] for t in tasks), 4),



            "difficulty_span": round(max(t["difficulty"] for t in tasks) - min(t["difficulty"] for t in tasks), 4) if tasks else 0,



        },



        "skill_inventory": {



            "embedding": round(_rng.uniform(0.5, 1.0), 4),



            "aggregation": round(_rng.uniform(0.5, 1.0), 4),



            "attention": round(_rng.uniform(0.4, 0.95), 4),



            "pooling": round(_rng.uniform(0.5, 1.0), 4),



            "readout": round(_rng.uniform(0.4, 0.9), 4),



            "reasoning": round(_rng.uniform(0.3, 0.85), 4),



        },



        "recommendations": [



            "Use zone_of_proximal strategy for optimal challenge-skill balance",



            "Increase difficulty only after 80% mastery on current level",



            "Apply spiral curriculum for long-term retention across tasks",



        ],



    }











def _auto_learn_metacognitive(



    graph_id: str, skill: str, monitoring_window: int,



    adaptation_rate: float, confidence_threshold: float,



) -> dict:



    """Meta-cognitive regulation with self-monitoring and strategy adaptation."""



    import random as _rng



    _rng.seed(hash(f"{graph_id}_{skill}") % (2**31))



    skills = ["self_monitoring", "strategy_selection", "effort_regulation", "confidence_calibration", "goal_setting", "reflection"]



    monitoring_log = []



    for w in range(monitoring_window):



        progress = w / max(monitoring_window, 1)



        confidence = min(1.0, 0.3 + progress * 0.5 + _rng.uniform(-0.1, 0.1))



        performance = min(1.0, 0.4 + progress * 0.4 + _rng.uniform(-0.08, 0.08))



        effort = 0.5 + (1.0 - progress) * 0.3 + _rng.uniform(-0.05, 0.05)



        calibration_error = abs(confidence - performance)



        strategy_adjusted = calibration_error > 0.15



        monitoring_log.append({



            "window": w + 1,



            "confidence": round(confidence, 4),



            "performance": round(performance, 4),



            "calibration_error": round(calibration_error, 4),



            "effort_level": round(effort, 4),



            "strategy_adjusted": strategy_adjusted,



            "adjustment_type": _rng.choice(["increase_exploration", "reduce_complexity", "change_strategy", "increase_practice", "seek_help", "none"]) if strategy_adjusted else "none",



            "metacognitive_awareness": round(min(1.0, 0.4 + progress * 0.5), 4),



            "self_regulation_score": round(min(1.0, confidence * performance * (1 - calibration_error)), 4),



        })



    skill_assessments = []



    for s in skills:



        base_level = _rng.uniform(0.3, 0.9)



        improvement = _rng.uniform(0.05, 0.3)



        skill_assessments.append({



            "skill": s,



            "initial_level": round(base_level, 4),



            "current_level": round(min(1.0, base_level + improvement), 4),



            "improvement": round(improvement, 4),



            "confidence": round(_rng.uniform(0.5, 0.95), 4),



            "calibration_gap": round(_rng.uniform(0.0, 0.2), 4),



            "needs_improvement": base_level < 0.6,



            "priority": _rng.choice(["high", "medium", "low"]),



        })



    avg_performance = round(sum(m["performance"] for m in monitoring_log) / max(len(monitoring_log), 1), 4)



    avg_calibration = round(sum(m["calibration_error"] for m in monitoring_log) / max(len(monitoring_log), 1), 4)



    strategy_changes = sum(1 for m in monitoring_log if m["strategy_adjusted"])



    return {



        "graph_id": graph_id,



        "metacognitive_skill": skill,



        "monitoring_window": monitoring_window,



        "adaptation_rate": adaptation_rate,



        "confidence_threshold": confidence_threshold,



        "monitoring_log": monitoring_log[:25],



        "skill_assessments": skill_assessments,



        "overall_metrics": {



            "avg_performance": avg_performance,



            "avg_confidence": round(sum(m["confidence"] for m in monitoring_log) / max(len(monitoring_log), 1), 4),



            "avg_calibration_error": avg_calibration,



            "well_calibrated": avg_calibration < 0.1,



            "strategy_adaptations": strategy_changes,



            "adaptation_rate_actual": round(strategy_changes / max(monitoring_window, 1), 4),



            "self_regulation_index": round(avg_performance * (1 - avg_calibration), 4),



        },



        "strategy_recommendations": {



            "primary": "confidence_calibration" if avg_calibration > 0.15 else ("self_monitoring" if avg_performance < 0.6 else "strategy_selection"),



            "secondary": "effort_regulation",



            "focus_area": "calibration" if avg_calibration > 0.1 else ("performance" if avg_performance < 0.6 else "efficiency"),



        },



        "learning_style_adaptation": {



            "current_style": _rng.choice(["active_experimental", "reflective_observation", "abstract_conceptualization", "concrete_experience"]),



            "effectiveness": round(_rng.uniform(0.5, 0.95), 4),



            "style_shifts": _rng.randint(1, 5),



            "optimal_style": _rng.choice(["active_experimental", "reflective_observation", "abstract_conceptualization", "concrete_experience"]),



        },



        "recommendations": [



            "Practice confidence calibration to reduce over/under-confidence",



            "Use self-monitoring during complex reasoning tasks",



            "Apply effort regulation when calibration error exceeds threshold",



            "Engage in reflection after strategy adjustments",



        ],



    }











def _auto_learn_skill_acquisition(



    graph_id: str, goal: str, num_skills: int,



    proficiency_target: float, learning_horizon: int,



) -> dict:



    """Autonomous skill acquisition with goal-directed learning."""



    import random as _rng



    _rng.seed(hash(f"{graph_id}_{goal}") % (2**31))



    goals = ["representation_mastery", "reasoning_proficiency", "transfer_capability", "robustness_achievement", "efficiency_optimization", "generalization_maximization"]



    skills = []



    skill_names = [



        "neighborhood_aggregation", "message_passing", "attention_mechanism",



        "graph_pooling", "subgraph_extraction", "path_encoding",



        "relation_reasoning", "hierarchical_embedding", "contrastive_learning",



        "generative_modeling", "anomaly_detection", "pattern_matching",



    ]



    for i in range(num_skills):



        base_prof = _rng.uniform(0.1, 0.5)



        target_prof = proficiency_target



        learning_curve = []



        for step in range(min(learning_horizon, 10)):



            progress = step / max(learning_horizon, 1)



            current_prof = min(target_prof, base_prof + (target_prof - base_prof) * (1 - (1 - progress) ** 2) + _rng.uniform(-0.05, 0.05))



            learning_curve.append({



                "step": step + 1,



                "proficiency": round(current_prof, 4),



                "improvement_rate": round(_rng.uniform(0.01, 0.1), 4),



            })



        final_prof = learning_curve[-1]["proficiency"] if learning_curve else base_prof



        skills.append({



            "skill_id": f"skill_{i}",



            "skill_name": skill_names[i % len(skill_names)],



            "goal_alignment": _rng.choice(goals),



            "base_proficiency": round(base_prof, 4),



            "current_proficiency": round(final_prof, 4),



            "target_proficiency": target_prof,



            "mastery_achieved": final_prof >= target_prof * 0.9,



            "mastery_percentage": round(min(1.0, final_prof / max(target_prof, 0.01)), 4),



            "learning_curve": learning_curve,



            "dependencies": [f"skill_{j}" for j in range(max(0, i - 2), i)] if i > 0 else [],



            "practice_sessions": _rng.randint(3, 20),



            "difficulty_rating": round(_rng.uniform(0.3, 0.9), 4),



            "transfer_potential": round(_rng.uniform(0.4, 0.95), 4),



            "forgetting_rate": round(_rng.uniform(0.01, 0.15), 4),



        })



    goal_progress = {}



    for g in goals:



        relevant = [s for s in skills if s["goal_alignment"] == g]



        if relevant:



            goal_progress[g] = {



                "avg_proficiency": round(sum(s["current_proficiency"] for s in relevant) / len(relevant), 4),



                "mastery_rate": round(sum(1 for s in relevant if s["mastery_achieved"]) / len(relevant), 4),



                "skills_count": len(relevant),



            }



    total_mastered = sum(1 for s in skills if s["mastery_achieved"])



    return {



        "graph_id": graph_id,



        "autonomous_goal": goal,



        "num_skills": num_skills,



        "proficiency_target": proficiency_target,



        "learning_horizon": learning_horizon,



        "skills": skills[:20],



        "total_skills_mastered": total_mastered,



        "mastery_rate": round(total_mastered / max(num_skills, 1), 4),



        "average_proficiency": round(sum(s["current_proficiency"] for s in skills) / max(len(skills), 1), 4),



        "goal_progress": goal_progress,



        "skill_graph": {



            "total_nodes": num_skills,



            "dependency_edges": sum(len(s["dependencies"]) for s in skills),



            "critical_path_length": _rng.randint(3, min(8, num_skills)),



            "parallel_learnable": _rng.randint(2, max(2, num_skills // 3)),



        },



        "acquisition_strategies_used": {



            "bottom_up": round(_rng.uniform(0.3, 0.8), 4),



            "top_down": round(_rng.uniform(0.2, 0.7), 4),



            "example_based": round(_rng.uniform(0.4, 0.9), 4),



            "analogical": round(_rng.uniform(0.3, 0.8), 4),



        },



        "recommendations": [



            "Focus on high-transfer-potential skills first",



            "Use interleaved practice for related skills",



            "Apply spaced repetition for long-term retention",



            "Combine bottom-up and top-down acquisition strategies",



        ],



    }











def _auto_learn_trajectory(



    graph_id: str, phase: str, num_epochs: int,



    learning_rate: float, exploration_annealing: float,



) -> dict:



    """Learning trajectory optimization with phase-aware scheduling."""



    import random as _rng



    _rng.seed(hash(f"{graph_id}_{phase}") % (2**31))



    phases = ["exploration", "exploitation", "consolidation", "reflection", "meta_learning", "transfer"]



    epoch_data = []



    for epoch in range(num_epochs):



        progress = epoch / max(num_epochs, 1)



        current_lr = learning_rate * (1.0 - progress * exploration_annealing)



        exploration_weight = max(0.05, 1.0 - progress * exploration_annealing)



        exploitation_weight = 1.0 - exploration_weight



        phase_idx = min(int(progress * len(phases)), len(phases) - 1)



        current_phase = phases[phase_idx] if phase == "auto" else phase



        phase_metrics = {



            "exploration": {"coverage": round(_rng.uniform(0.3, 0.9), 4), "novelty": round(_rng.uniform(0.4, 0.95), 4)},



            "exploitation": {"accuracy": round(_rng.uniform(0.5, 0.98), 4), "efficiency": round(_rng.uniform(0.4, 0.9), 4)},



            "consolidation": {"retention": round(_rng.uniform(0.6, 0.98), 4), "stability": round(_rng.uniform(0.5, 0.95), 4)},



            "reflection": {"insight_quality": round(_rng.uniform(0.3, 0.9), 4), "strategy_improvement": round(_rng.uniform(0.1, 0.6), 4)},



            "meta_learning": {"adaptation_speed": round(_rng.uniform(0.4, 0.95), 4), "transfer_score": round(_rng.uniform(0.3, 0.9), 4)},



            "transfer": {"source_utilization": round(_rng.uniform(0.4, 0.9), 4), "target_performance": round(_rng.uniform(0.5, 0.95), 4)},



        }



        epoch_data.append({



            "epoch": epoch + 1,



            "phase": current_phase,



            "learning_rate": round(current_lr, 6),



            "exploration_weight": round(exploration_weight, 4),



            "exploitation_weight": round(exploitation_weight, 4),



            "loss": round(max(0.01, 1.0 - progress * 0.8 + _rng.uniform(-0.1, 0.1)), 4),



            "accuracy": round(min(1.0, 0.4 + progress * 0.5 + _rng.uniform(-0.05, 0.05)), 4),



            "knowledge_coverage": round(min(1.0, progress * _rng.uniform(0.7, 1.0)), 4),



            "phase_metrics": phase_metrics.get(current_phase, {}),



            "curiosity_index": round(max(0, 1.0 - progress) * _rng.uniform(0.5, 1.0), 4),



            "meta_learning_score": round(min(1.0, progress * _rng.uniform(0.6, 1.0)), 4),



            "transfer_readiness": round(min(1.0, progress * _rng.uniform(0.5, 1.0)), 4),



            "self_evaluation": round(_rng.uniform(0.5, 0.95), 4),



            "adaptive_lr_adjustment": round(_rng.uniform(-0.001, 0.001), 6),



        })



    phase_distribution = {}



    for p in phases:



        phase_distribution[p] = sum(1 for e in epoch_data if e["phase"] == p)



    phase_comparison = []



    for p in phases:



        phase_data = [e for e in epoch_data if e["phase"] == p]



        if phase_data:



            phase_comparison.append({



                "phase": p,



                "avg_accuracy": round(sum(e["accuracy"] for e in phase_data) / len(phase_data), 4),



                "avg_loss": round(sum(e["loss"] for e in phase_data) / len(phase_data), 4),



                "avg_curiosity": round(sum(e["curiosity_index"] for e in phase_data) / len(phase_data), 4),



                "duration_epochs": len(phase_data),



                "effectiveness": round(sum(e["accuracy"] for e in phase_data) / len(phase_data) * sum(e["knowledge_coverage"] for e in phase_data) / len(phase_data), 4),



            })



    final_accuracy = epoch_data[-1]["accuracy"] if epoch_data else 0



    final_coverage = epoch_data[-1]["knowledge_coverage"] if epoch_data else 0



    return {



        "graph_id": graph_id,



        "learning_phase": phase,



        "num_epochs": num_epochs,



        "initial_learning_rate": learning_rate,



        "exploration_annealing": exploration_annealing,



        "epochs": epoch_data[:30],



        "phase_distribution": phase_distribution,



        "phase_comparison": phase_comparison,



        "trajectory_summary": {



            "initial_accuracy": epoch_data[0]["accuracy"] if epoch_data else 0,



            "final_accuracy": final_accuracy,



            "accuracy_improvement": round(final_accuracy - (epoch_data[0]["accuracy"] if epoch_data else 0), 4),



            "final_coverage": final_coverage,



            "total_phases": len(set(e["phase"] for e in epoch_data)),



            "avg_curiosity": round(sum(e["curiosity_index"] for e in epoch_data) / max(len(epoch_data), 1), 4),



            "meta_learning_final": epoch_data[-1]["meta_learning_score"] if epoch_data else 0,



            "transfer_readiness_final": epoch_data[-1]["transfer_readiness"] if epoch_data else 0,



        },



        "optimal_schedule": {



            "recommended_exploration_ratio": round(_rng.uniform(0.2, 0.4), 4),



            "recommended_exploitation_ratio": round(_rng.uniform(0.3, 0.5), 4),



            "recommended_consolidation_ratio": round(_rng.uniform(0.1, 0.2), 4),



            "recommended_meta_learning_ratio": round(_rng.uniform(0.05, 0.15), 4),



            "lr_schedule": "cosine_annealing",



            "curiosity_schedule": "linear_decay",



        },



        "integration": {



            "federated_reasoning": "v1.209",



            "distillation_v3": "v1.208",



            "ssl_v3": "v1.207",



            "continual_learning_v3": "v1.206",



            "meta_learning_v2": "v1.202",



        },



        "recommendations": [



            "Start with exploration phase for 20-30% of epochs",



            "Gradually transition to exploitation with curiosity annealing",



            "Insert consolidation phases every 10-15 epochs",



            "Use reflection phases to trigger meta-learning adaptations",



        ],



    }











