_adv_v3_tradeoff_cache: dict = {}



_adv_v3_testing_cache: dict = {}











def _adv_v3_train(



    graph_id: str,



    strategy: str,



    num_epochs: int,



    attack_strength: float,



    defense_budget: float,



) -> dict:



    """Advanced adversarial training with 6 strategies."""



    strategies = [s.value for s in AdversarialTrainStrategy]



    strategy = strategy if strategy in strategies else strategies[0]







    epochs_data = []



    for ep in range(num_epochs):



        progress = (ep + 1) / num_epochs



        noise_factor = attack_strength * (1 - 0.3 * progress)



        clean_acc = round(0.85 + 0.1 * progress + _rng.uniform(-0.02, 0.02), 4)



        robust_acc = round(0.65 + 0.2 * progress + _rng.uniform(-0.03, 0.02), 4)







        if strategy == "trades":



            tradeoff_lambda = round(1 + 5 * (1 - progress), 2)



            perturb_loss = round(noise_factor * (1 - progress) * _rng.uniform(0.3, 0.8), 4)



            train_loss = round((1 - clean_acc) + tradeoff_lambda * perturb_loss, 4)



            metric = {"tradeoff_lambda": tradeoff_lambda, "perturbation_loss": perturb_loss, "kl_divergence": round(_rng.uniform(0.1, 0.5), 4)}



        elif strategy == "mart":



            misclassification_weight = round(1 + 3 * (1 - progress), 2)



            adv_cond_prob = round(robust_acc * _rng.uniform(0.7, 0.95), 4)



            train_loss = round((1 - clean_acc) + misclassification_weight * (1 - adv_cond_prob), 4)



            metric = {"misclassification_weight": misclassification_weight, "adv_cond_prob": adv_cond_prob, "bdd_loss": round(_rng.uniform(0.1, 0.4), 4)}



        elif strategy == "virtual_adversarial":



            vat_epsilon = round(noise_factor * 2, 4)



            local_smoothness = round(0.5 + 0.4 * progress, 4)



            train_loss = round((1 - clean_acc) + vat_epsilon * (1 - local_smoothness), 4)



            metric = {"vat_epsilon": vat_epsilon, "local_smoothness": local_smoothness, "perturb_directions": _rng.randint(3, 10)}



        elif strategy == "graph_at":



            graph_reg = round(noise_factor * _rng.uniform(0.2, 0.6), 4)



            message_perturb = round(1 - 0.5 * progress, 4)



            train_loss = round((1 - clean_acc) + graph_reg * message_perturb, 4)



            metric = {"graph_regularization": graph_reg, "message_perturbation": message_perturb, "neighbor_influence": round(_rng.uniform(0.3, 0.8), 4)}



        elif strategy == "grand":



            drop_ratio = round(min(0.5, noise_factor * 0.8), 4)



            consistency_loss = round((1 - progress) * _rng.uniform(0.2, 0.6), 4)



            train_loss = round((1 - clean_acc) + drop_ratio * consistency_loss, 4)



            metric = {"drop_ratio": drop_ratio, "consistency_loss": consistency_loss, "augmented_views": _rng.randint(2, 6)}



        else:  # robust_gnn



            spectral_norm = round(noise_factor * _rng.uniform(0.5, 1.0), 4)



            certify_radius = round(0.3 + 0.4 * progress, 4)



            train_loss = round((1 - clean_acc) + spectral_norm * (1 - certify_radius), 4)



            metric = {"spectral_norm": spectral_norm, "certified_radius": certify_radius, "robustness_margin": round(certify_radius * 0.8, 4)}







        epochs_data.append({



            "epoch": ep + 1,



            "clean_accuracy": clean_acc,



            "robust_accuracy": robust_acc,



            "robustness_gap": round(clean_acc - robust_acc, 4),



            "train_loss": train_loss,



            "defense_budget_used": round(defense_budget * progress, 2),



            "strategy_metrics": metric,



        })







    strategy_comparison = []



    for s in strategies:



        final_clean = round(0.88 + _rng.uniform(-0.05, 0.05), 4)



        final_robust = round(0.72 + _rng.uniform(-0.05, 0.05), 4)



        strategy_comparison.append({



            "strategy": s,



            "final_clean_accuracy": final_clean,



            "final_robust_accuracy": final_robust,



            "robustness_gap": round(final_clean - final_robust, 4),



            "training_efficiency": round(_rng.uniform(0.6, 0.95), 4),



            "budget_efficiency": round(_rng.uniform(0.5, 0.9), 4),



            "convergence_epoch": _rng.randint(num_epochs // 3, num_epochs),



        })







    return {



        "graph_id": graph_id,



        "strategy": strategy,



        "num_epochs": num_epochs,



        "attack_strength": attack_strength,



        "defense_budget": defense_budget,



        "epochs": epochs_data[:50],



        "final_metrics": {



            "clean_accuracy": epochs_data[-1]["clean_accuracy"],



            "robust_accuracy": epochs_data[-1]["robust_accuracy"],



            "robustness_gap": epochs_data[-1]["robustness_gap"],



            "budget_utilization": round(defense_budget * 0.85, 2),



        },



        "strategy_comparison": strategy_comparison,



    }











def _adv_v3_distill(



    graph_id: str,



    method: str,



    teacher_robustness: float,



    student_capacity: float,



    num_rounds: int,



) -> dict:



    """Distillation-hardened defense with 6 distillation methods."""



    methods = [m.value for m in DistillHardenMethod]



    method = method if method in methods else methods[0]







    rounds_data = []



    for r in range(num_rounds):



        progress = (r + 1) / num_rounds



        teacher_acc = round(teacher_robustness * (0.95 + 0.05 * progress), 4)



        student_acc = round(student_capacity * (0.7 + 0.25 * progress), 4)



        transfer_eff = round(0.5 + 0.4 * progress + _rng.uniform(-0.05, 0.05), 4)



        hardened_acc = round(min(student_acc + transfer_eff * (teacher_acc - student_acc) * 0.8, teacher_acc), 4)







        if method == "robust_teacher":



            knowledge_transferred = round(transfer_eff * teacher_robustness * 0.9, 4)



            robustness_gain = round(hardened_acc - student_acc, 4)



            detail = {"teacher_robustness_level": round(teacher_robustness, 2), "knowledge_transferred": knowledge_transferred, "robustness_inheritance_ratio": round(knowledge_transferred / max(teacher_robustness, 0.01), 4)}



        elif method == "feature_distill":



            feature_alignment = round(0.6 + 0.3 * progress, 4)



            robustness_gain = round(feature_alignment * (teacher_acc - student_acc) * 0.7, 4)



            detail = {"feature_alignment_score": feature_alignment, "intermediate_layers_matched": _rng.randint(2, 6), "robustness_gain": robustness_gain}



        elif method == "response_distill":



            response_fidelity = round(0.7 + 0.2 * progress, 4)



            robustness_gain = round(response_fidelity * (teacher_acc - student_acc) * 0.6, 4)



            detail = {"response_fidelity": response_fidelity, "logit_matching_score": round(_rng.uniform(0.6, 0.95), 4), "temperature": round(2 + 3 * (1 - progress), 2)}



        elif method == "relation_distill":



            relation_preserved = round(0.5 + 0.4 * progress, 4)



            robustness_gain = round(relation_preserved * (teacher_acc - student_acc) * 0.65, 4)



            detail = {"relation_preservation": relation_preserved, "graph_structural_fidelity": round(_rng.uniform(0.6, 0.9), 4), "pairwise_similarity_transfer": round(_rng.uniform(0.5, 0.85), 4)}



        elif method == "contrastive_distill":



            contrastive_score = round(0.6 + 0.35 * progress, 4)



            robustness_gain = round(contrastive_score * (teacher_acc - student_acc) * 0.75, 4)



            detail = {"contrastive_score": contrastive_score, "negative_samples_per_anchor": _rng.randint(3, 8), "feature_invariance": round(_rng.uniform(0.5, 0.85), 4)}



        else:  # ensemble_distill



            num_teachers = _rng.randint(3, 7)



            diversity_bonus = round(_rng.uniform(0.02, 0.08), 4)



            robustness_gain = round((teacher_acc - student_acc) * 0.7 + diversity_bonus, 4)



            detail = {"num_teachers": num_teachers, "teacher_diversity": round(_rng.uniform(0.5, 0.9), 4), "voting_consensus": round(_rng.uniform(0.7, 0.95), 4), "diversity_bonus": diversity_bonus}







        rounds_data.append({



            "round": r + 1,



            "teacher_accuracy": teacher_acc,



            "student_accuracy": student_acc,



            "hardened_accuracy": hardened_acc,



            "transfer_efficiency": transfer_eff,



            "robustness_gain": robustness_gain,



            "method_detail": detail,



        })







    method_comparison = []



    for m in methods:



        final_hardened = round(0.75 + _rng.uniform(-0.05, 0.1), 4)



        base_student = round(student_capacity * 0.85, 4)



        method_comparison.append({



            "method": m,



            "final_hardened_accuracy": final_hardened,



            "robustness_gain": round(final_hardened - base_student, 4),



            "transfer_efficiency": round(_rng.uniform(0.5, 0.9), 4),



            "computational_cost": round(_rng.uniform(0.3, 0.8), 4),



            "fidelity_score": round(_rng.uniform(0.6, 0.95), 4),



        })







    return {



        "graph_id": graph_id,



        "method": method,



        "teacher_robustness": teacher_robustness,



        "student_capacity": student_capacity,



        "num_rounds": num_rounds,



        "rounds": rounds_data[:50],



        "final_result": {



            "hardened_accuracy": rounds_data[-1]["hardened_accuracy"],



            "total_robustness_gain": round(rounds_data[-1]["hardened_accuracy"] - rounds_data[0]["student_accuracy"], 4),



            "teacher_student_gap_closed": round((rounds_data[-1]["hardened_accuracy"] - rounds_data[0]["student_accuracy"]) / max(rounds_data[0]["teacher_accuracy"] - rounds_data[0]["student_accuracy"], 0.01), 4),



        },



        "method_comparison": method_comparison,



    }











def _adv_v3_temporal(



    graph_id: str,



    attack_type: str,



    num_snapshots: int,



    defense_strategy: str,



    attack_intensity: float,



) -> dict:



    """Temporal attack defense against time-evolving adversarial threats."""



    attacks = [a.value for a in TemporalAttackType]



    attack_type = attack_type if attack_type in attacks else attacks[0]







    snapshots_data = []



    for s in range(num_snapshots):



        progress = (s + 1) / num_snapshots



        attack_success_rate = round(attack_intensity * (1 - 0.6 * progress) * _rng.uniform(0.7, 1.0), 4)



        defense_effectiveness = round(min(0.95, 0.4 + 0.5 * progress + _rng.uniform(-0.05, 0.05)), 4)



        temporal_damage = round(attack_success_rate * (1 - defense_effectiveness), 4)







        if attack_type == "temporal_perturbation":



            detail = {"perturbation_persistence": round(_rng.uniform(0.3, 0.8), 4), "temporal_correlation": round(_rng.uniform(0.4, 0.9), 4), "snapshot_sensitivity": round(_rng.uniform(0.2, 0.7), 4)}



        elif attack_type == "snapshot_injection":



            detail = {"injected_snapshots": _rng.randint(1, 5), "detection_rate": round(_rng.uniform(0.6, 0.95), 4), "injection_quality": round(_rng.uniform(0.3, 0.8), 4)}



        elif attack_type == "drift_attack":



            detail = {"drift_magnitude": round(attack_intensity * _rng.uniform(0.2, 0.6), 4), "drift_direction": _rng.choice(["gradual", "sudden", "oscillating"]), "drift_detection_delay": round(_rng.uniform(0.5, 3.0), 2)}



        elif attack_type == "causality_attack":



            detail = {"causal_links_targeted": _rng.randint(2, 10), "causal_distortion": round(_rng.uniform(0.2, 0.7), 4), "temporal_granger_score": round(_rng.uniform(0.1, 0.6), 4)}



        elif attack_type == "evolution_manipulation":



            detail = {"evolution_hijacked": _rng.randint(1, 4), "structural_divergence": round(_rng.uniform(0.3, 0.8), 4), "recovery_steps_needed": _rng.randint(3, 15)}



        else:  # retrospective_attack



            detail = {"history_modified_steps": _rng.randint(1, 8), "audit_trail_integrity": round(_rng.uniform(0.5, 0.95), 4), "forensic_recoverability": round(_rng.uniform(0.4, 0.9), 4)}







        snapshots_data.append({



            "snapshot": s + 1,



            "attack_success_rate": attack_success_rate,



            "defense_effectiveness": defense_effectiveness,



            "temporal_damage": temporal_damage,



            "damage_accumulated": round(sum(sd.get("temporal_damage", 0) for sd in snapshots_data) + temporal_damage, 4),



            "defense_adaptation": round(defense_effectiveness * progress, 4),



            "detail": detail,



        })







    attack_comparison = []



    for at in attacks:



        attack_comparison.append({



            "attack_type": at,



            "avg_success_rate": round(_rng.uniform(0.15, 0.55), 4),



            "max_damage": round(_rng.uniform(0.1, 0.4), 4),



            "defense_evasion_rate": round(_rng.uniform(0.1, 0.5), 4),



            "temporal_persistence": round(_rng.uniform(0.2, 0.7), 4),



            "detection_difficulty": round(_rng.uniform(0.3, 0.8), 4),



        })







    return {



        "graph_id": graph_id,



        "attack_type": attack_type,



        "num_snapshots": num_snapshots,



        "defense_strategy": defense_strategy,



        "attack_intensity": attack_intensity,



        "snapshots": snapshots_data[:50],



        "defense_summary": {



            "overall_defense_rate": round(sum(s["defense_effectiveness"] for s in snapshots_data) / max(len(snapshots_data), 1), 4),



            "total_damage_accumulated": snapshots_data[-1]["damage_accumulated"] if snapshots_data else 0,



            "adaptation_speed": round(1 / max(num_snapshots * 0.1, 0.1), 4),



            "best_defense_snapshot": max(snapshots_data, key=lambda x: x["defense_effectiveness"])["snapshot"] if snapshots_data else 0,



        },



        "attack_comparison": attack_comparison,



    }











def _adv_v3_transfer(



    graph_id: str,



    scenario: str,



    num_attacks: int,



    source_model: str,



    target_model: str,



) -> dict:



    """Adversarial transferability analysis across 6 scenarios."""



    scenarios = [s.value for s in TransferScenario]



    scenario = scenario if scenario in scenarios else scenarios[0]







    attacks_data = []



    for a in range(num_attacks):



        attack_strength = round(_rng.uniform(0.1, 0.9), 4)



        source_success = round(attack_strength * _rng.uniform(0.6, 1.0), 4)







        if scenario == "same_architecture":



            transfer_rate = round(source_success * _rng.uniform(0.7, 0.95), 4)



        elif scenario == "cross_architecture":



            transfer_rate = round(source_success * _rng.uniform(0.3, 0.7), 4)



        elif scenario == "cross_task":



            transfer_rate = round(source_success * _rng.uniform(0.2, 0.6), 4)



        elif scenario == "cross_domain":



            transfer_rate = round(source_success * _rng.uniform(0.1, 0.5), 4)



        elif scenario == "black_box":



            transfer_rate = round(source_success * _rng.uniform(0.15, 0.55), 4)



        else:  # query_limited



            transfer_rate = round(source_success * _rng.uniform(0.2, 0.65), 4)







        attacks_data.append({



            "attack_id": a + 1,



            "attack_strength": attack_strength,



            "source_success_rate": source_success,



            "transfer_rate": transfer_rate,



            "transfer_efficiency": round(transfer_rate / max(source_success, 0.01), 4),



            "perturbation_type": _rng.choice(["feature", "edge", "node", "structure", "combined"]),



            "perturbation_budget": round(_rng.uniform(0.05, 0.3), 4),



            "query_count": _rng.randint(10, 500) if scenario == "query_limited" else _rng.randint(1, 50),



        })







    scenario_comparison = []



    for sc in scenarios:



        avg_transfer = round(_rng.uniform(0.15, 0.7), 4)



        scenario_comparison.append({



            "scenario": sc,



            "avg_transfer_rate": avg_transfer,



            "max_transfer_rate": round(avg_transfer + _rng.uniform(0.05, 0.2), 4),



            "attack_variety_effectiveness": round(_rng.uniform(0.3, 0.8), 4),



            "defense_awareness_score": round(1 - avg_transfer, 4),



            "recommended_defense": _rng.choice(["input_transformation", "model_ensemble", "randomized_smoothing", "adversarial_detection", "feature_squeezing"]),



        })







    return {



        "graph_id": graph_id,



        "scenario": scenario,



        "num_attacks": num_attacks,



        "source_model": source_model,



        "target_model": target_model,



        "attacks": attacks_data[:50],



        "transfer_summary": {



            "avg_transfer_rate": round(sum(a["transfer_rate"] for a in attacks_data) / max(len(attacks_data), 1), 4),



            "max_transfer_rate": max((a["transfer_rate"] for a in attacks_data), default=0),



            "high_transfer_attacks": sum(1 for a in attacks_data if a["transfer_rate"] > 0.5),



            "low_transfer_attacks": sum(1 for a in attacks_data if a["transfer_rate"] < 0.2),



        },



        "scenario_comparison": scenario_comparison,



    }











def _adv_v3_tradeoff(



    graph_id: str,



    tradeoff_mode: str,



    num_points: int,



    accuracy_weight: float,



    robustness_weight: float,



) -> dict:



    """Robustness-utility tradeoff optimization with Pareto analysis."""



    modes = [m.value for m in RobustnessTradeoff]



    tradeoff_mode = tradeoff_mode if tradeoff_mode in modes else modes[2]







    pareto_points = []



    for p in range(num_points):



        alpha = p / max(num_points - 1, 1)



        accuracy = round(0.7 + 0.25 * alpha + _rng.uniform(-0.02, 0.02), 4)



        robustness = round(0.9 - 0.35 * alpha + _rng.uniform(-0.02, 0.02), 4)



        certified_score = round(robustness * _rng.uniform(0.7, 0.95), 4)



        composite_score = round(accuracy_weight * accuracy + robustness_weight * robustness, 4)







        pareto_points.append({



            "point_id": p + 1,



            "robustness_weight": round(alpha, 4),



            "accuracy": accuracy,



            "robustness_score": robustness,



            "certified_robustness": certified_score,



            "composite_score": composite_score,



            "tradeoff_ratio": round(robustness / max(accuracy, 0.01), 4),



            "utility_preserved": round(accuracy / max(0.95, 0.01), 4),



        })







    # Find Pareto front



    pareto_front = sorted(pareto_points, key=lambda x: x["composite_score"], reverse=True)[:max(num_points // 3, 3)]







    knee_point = min(pareto_points, key=lambda x: abs(x["robustness_score"] - x["accuracy"]))







    mode_comparison = []



    for m in modes:



        mode_comparison.append({



            "mode": m,



            "optimal_accuracy": round(0.8 + _rng.uniform(-0.05, 0.1), 4),



            "optimal_robustness": round(0.7 + _rng.uniform(-0.05, 0.1), 4),



            "composite_score": round(_rng.uniform(0.7, 0.9), 4),



            "accuracy_sacrifice": round(_rng.uniform(0.02, 0.15), 4),



            "robustness_gain": round(_rng.uniform(0.1, 0.3), 4),



            "efficiency_ratio": round(_rng.uniform(0.5, 0.9), 4),



        })







    return {



        "graph_id": graph_id,



        "tradeoff_mode": tradeoff_mode,



        "num_points": num_points,



        "accuracy_weight": accuracy_weight,



        "robustness_weight": robustness_weight,



        "pareto_points": pareto_points[:50],



        "pareto_front": pareto_front,



        "knee_point": knee_point,



        "extreme_points": {



            "best_accuracy": max(pareto_points, key=lambda x: x["accuracy"]),



            "best_robustness": max(pareto_points, key=lambda x: x["robustness_score"]),



            "best_composite": max(pareto_points, key=lambda x: x["composite_score"]),



        },



        "mode_comparison": mode_comparison,



    }











def _adv_v3_testing(



    graph_id: str,



    num_attacks: int,



    num_defenses: int,



    test_budget: float,



    threat_level: str,



) -> dict:



    """Automated adversarial testing pipeline with attack-defense matrix."""



    phases = [p.value for p in AdversarialTestPhase]



    threat_levels = ["low", "medium", "high", "critical"]



    threat_level = threat_level if threat_level in threat_levels else "high"







    # Phase 1: Threat modeling



    threat_model = {



        "threat_level": threat_level,



        "attack_surfaces": ["node_features", "edge_structure", "graph_topology", "message_passing", "aggregation"],



        "attacker_capabilities": {



            "knowledge": _rng.choice(["white_box", "gray_box", "black_box"]),



            "perturbation_budget": round(_rng.uniform(0.05, 0.3), 4),



            "query_limit": _rng.randint(50, 1000),



            "computation_budget": round(test_budget * 0.3, 2),



        },



        "target_assets": ["node_classification", "link_prediction", "graph_classification"],



        "risk_assessment": {k: round(_rng.uniform(0.3, 0.9), 4) for k in ["confidentiality", "integrity", "availability"]},



    }







    # Phase 2: Attack generation



    attack_types = ["fgsm", "pgd", "deepfool", "netattack", "random_edge", "feature_perturbation"]



    attacks = []



    for i in range(num_attacks):



        atype = attack_types[i % len(attack_types)]



        attacks.append({



            "attack_id": i + 1,



            "attack_type": atype,



            "success_rate": round(_rng.uniform(0.1, 0.8), 4),



            "perturbation_magnitude": round(_rng.uniform(0.01, 0.2), 4),



            "detection_difficulty": round(_rng.uniform(0.3, 0.9), 4),



            "execution_time_ms": round(_rng.uniform(10, 500), 1),



        })







    # Phase 3: Defense evaluation



    defense_types = ["adversarial_training", "graph_purification", "robust_aggregation", "randomized_smoothing", "certified_defense", "ensemble_defense"]



    defenses = []



    for i in range(num_defenses):



        dtype = defense_types[i % len(defense_types)]



        defense_success = round(_rng.uniform(0.5, 0.95), 4)



        defenses.append({



            "defense_id": i + 1,



            "defense_type": dtype,



            "effectiveness": defense_success,



            "overhead_ms": round(_rng.uniform(5, 200), 1),



            "accuracy_impact": round(_rng.uniform(-0.05, 0.02), 4),



            "robustness_improvement": round(_rng.uniform(0.1, 0.4), 4),



        })







    # Phase 4: Attack-defense matrix



    matrix = []



    for atk in attacks:



        row = {"attack_type": atk["attack_type"], "base_success_rate": atk["success_rate"]}



        for dfn in defenses:



            reduction = round(_rng.uniform(0.3, 0.8), 4)



            row[f"defense_{dfn['defense_type']}"] = round(max(0, atk["success_rate"] * (1 - reduction)), 4)



        matrix.append(row)







    # Phase 5: Robustness scoring



    robustness_score = {



        "overall_robustness": round(_rng.uniform(0.6, 0.85), 4),



        "certified_robustness": round(_rng.uniform(0.4, 0.7), 4),



        "empirical_robustness": round(_rng.uniform(0.65, 0.9), 4),



        "worst_case_robustness": round(_rng.uniform(0.35, 0.6), 4),



        "average_case_robustness": round(_rng.uniform(0.6, 0.85), 4),



        "robustness_grade": _rng.choice(["A", "B+", "B", "C+"]),



    }







    # Phase 6: Vulnerability mapping



    vulnerability_map = {



        "high_risk_components": [{"component": c, "risk_score": round(_rng.uniform(0.6, 0.9), 4), "vulnerability_type": _rng.choice(["evasion", "poisoning", "backdoor"])} for c in ["feature_layer", "aggregation_layer", "readout_layer", "embedding_layer"][:_rng.randint(2, 4)]],



        "attack_paths": [{"path_id": i + 1, "entry_point": _rng.choice(["input_features", "graph_structure"]), "target": _rng.choice(["prediction", "embedding", "gradient"]), "difficulty": round(_rng.uniform(0.3, 0.8), 4)} for i in range(_rng.randint(2, 5))],



    }







    # Phase 7: Hardening recommendations



    recommendations = [



        {"priority": "high", "action": "Deploy adversarial training with TRADES strategy", "expected_improvement": round(_rng.uniform(0.1, 0.25), 4), "cost": "moderate"},



        {"priority": "high", "action": "Enable graph purification preprocessing", "expected_improvement": round(_rng.uniform(0.08, 0.2), 4), "cost": "low"},



        {"priority": "medium", "action": "Implement randomized smoothing for certified robustness", "expected_improvement": round(_rng.uniform(0.05, 0.15), 4), "cost": "moderate"},



        {"priority": "medium", "action": "Deploy distillation-hardened student models", "expected_improvement": round(_rng.uniform(0.1, 0.2), 4), "cost": "high"},



        {"priority": "low", "action": "Add temporal consistency monitoring", "expected_improvement": round(_rng.uniform(0.05, 0.12), 4), "cost": "low"},



    ]







    return {



        "graph_id": graph_id,



        "num_attacks": num_attacks,



        "num_defenses": num_defenses,



        "test_budget": test_budget,



        "threat_level": threat_level,



        "phases_completed": 6,



        "threat_model": threat_model,



        "attacks": attacks,



        "defenses": defenses,



        "attack_defense_matrix": matrix,



        "robustness_score": robustness_score,



        "vulnerability_map": vulnerability_map,



        "recommendations": recommendations,



        "test_summary": {



            "total_attack_success_rate": round(sum(a["success_rate"] for a in attacks) / max(len(attacks), 1), 4),



            "total_defense_effectiveness": round(sum(d["effectiveness"] for d in defenses) / max(len(defenses), 1), 4),



            "overall_security_level": _rng.choice(["strong", "adequate", "needs_improvement"]),



            "budget_utilized": round(test_budget * _rng.uniform(0.7, 0.95), 2),



        },



    }











