async def adversarial_v3_testing(request: Request):



    """Automated adversarial testing pipeline with attack-defense matrix."""



    body = await request.json()



    result = _adv_v3_testing(



        graph_id=body.get("graph_id", "graph_001"),



        num_attacks=body.get("num_attacks", 6),



        num_defenses=body.get("num_defenses", 6),



        test_budget=body.get("test_budget", 1000.0),



        threat_level=body.get("threat_level", "high"),



    )



    key = f"{result['graph_id']}_{result['num_attacks']}_{result['threat_level']}"



    _adv_v3_testing_cache[key] = result



    return result











