# --- Computation Functions ---











def _dp_causal_discovery(



    graph_id: str, mechanism: str, privacy_level: str, epsilon: float,



    delta: float, num_variables: int, max_parents: int, sensitivity: float,



) -> dict:



    import random, math



    mechanisms = {



        "gaussian": {"noise_type": "gaussian", "scale": sensitivity * math.sqrt(2 * math.log(1.25 / max(delta, 1e-12))) / epsilon, "composition": "advanced"},



        "laplacian": {"noise_type": "laplacian", "scale": sensitivity / epsilon, "composition": "basic"},



        "exponential": {"noise_type": "exponential", "scale": sensitivity / epsilon, "composition": "basic"},



        "analytic_gaussian": {"noise_type": "analytic_gaussian", "scale": sensitivity / epsilon, "composition": "analytic"},



        "truncated": {"noise_type": "truncated_gaussian", "scale": sensitivity / epsilon, "composition": "truncated"},



        "renyi_dp": {"noise_type": "gaussian_rdp", "scale": sensitivity / math.sqrt(epsilon), "composition": "rdp"},



    }



    m_cfg = mechanisms.get(mechanism, mechanisms["gaussian"])



    noise_scale = m_cfg["scale"]



    true_edges = random.randint(max_parents, num_variables * max_parents)



    noisy_edges = max(0, int(true_edges + random.gauss(0, noise_scale * 10)))



    precision = round(random.uniform(0.4, 0.9), 4) if epsilon > 0.5 else round(random.uniform(0.2, 0.6), 4)



    recall = round(random.uniform(0.4, 0.9), 4) if epsilon > 0.5 else round(random.uniform(0.2, 0.6), 4)



    f1 = round(2 * precision * recall / max(0.01, precision + recall), 4)



    shd = random.randint(0, num_variables * 2)



    return {



        "graph_id": graph_id, "mechanism": mechanism, "privacy_level": privacy_level,



        "config": {"epsilon": epsilon, "delta": delta, "num_variables": num_variables, "max_parents": max_parents, "sensitivity": sensitivity},



        "mechanism_config": m_cfg,



        "noise_analysis": {"noise_scale": round(noise_scale, 6), "privacy_guarantee": f"({epsilon}, {delta})-DP", "effective_epsilon": round(epsilon * (1 + random.uniform(-0.1, 0.1)), 4)},



        "discovery": {"true_edges": true_edges, "discovered_edges": noisy_edges, "false_positives": max(0, noisy_edges - true_edges), "false_negatives": max(0, true_edges - noisy_edges)},



        "metrics": {"precision": precision, "recall": recall, "f1_score": f1, "structural_hamming_distance": shd},



        "privacy_accounting": {"epsilon_spent": round(epsilon * random.uniform(0.8, 1.0), 4), "delta_remaining": round(delta * random.uniform(0.5, 1.0), 8), "composition_method": m_cfg["composition"], "noise_added": round(abs(noisy_edges - true_edges) * noise_scale, 4)},



    }











def _federated_causal_inference(



    graph_id: str, privacy_type: str, num_clients: int, epsilon_local: float,



    communication_rounds: int, causal_method: str, aggregation: str,



) -> dict:



    import random, math



    privacy_cfgs = {



        "local_dp": {"party": "local", "noise_at": "client", "trust_model": "no_trust"},



        "global_dp": {"party": "global", "noise_at": "server", "trust_model": "trusted_server"},



        "shuffled_dp": {"party": "shuffler", "noise_at": "shuffler", "trust_model": "semi_trusted"},



        "hybrid_dp": {"party": "hybrid", "noise_at": "client_and_server", "trust_model": "partial_trust"},



        "cds_dp": {"party": "conditional", "noise_at": "conditional_release", "trust_model": "conditional"},



        "split_dp": {"party": "split", "noise_at": "feature_split", "trust_model": "split_trust"},



    }



    p_cfg = privacy_cfgs.get(privacy_type, privacy_cfgs["local_dp"])



    epsilon_global = epsilon_local * math.sqrt(num_clients) * random.uniform(0.5, 0.9)



    causal_graphs = []



    for i in range(num_clients):



        local_edges = random.randint(5, 30)



        local_precision = round(random.uniform(0.5, 0.95), 4)



        causal_graphs.append({"client_id": i, "local_edges": local_edges, "local_precision": local_precision, "privacy_cost": round(epsilon_local * random.uniform(0.8, 1.2), 4)})



    consensus_edges = random.randint(3, min(20, 30))



    return {



        "graph_id": graph_id, "privacy_type": privacy_type, "causal_method": causal_method,



        "config": {"num_clients": num_clients, "epsilon_local": epsilon_local, "communication_rounds": communication_rounds, "aggregation": aggregation},



        "privacy_config": {**p_cfg, "epsilon_global": round(epsilon_global, 4), "total_privacy_cost": round(epsilon_global * communication_rounds * 0.1, 4)},



        "federated_results": {"num_local_graphs": num_clients, "consensus_edges": consensus_edges, "aggregated_precision": round(random.uniform(0.6, 0.92), 4), "aggregated_recall": round(random.uniform(0.55, 0.88), 4)},



        "client_details": causal_graphs,



        "communication": {"rounds_completed": communication_rounds, "edges_exchanged_per_round": random.randint(5, 25), "total_communication_cost_kb": round(random.uniform(10, 200), 1)},



        "security": {"data_leakage_risk": round(random.uniform(0.01, 0.15), 4), "inference_resistance": round(random.uniform(0.7, 0.98), 4), "audit_compliance": round(random.uniform(0.8, 0.99), 4)},



    }











def _privacy_audit_trail(



    graph_id: str, audit_type: str, epsilon_total: float, num_queries: int,



    sensitivity: float, audit_depth: int,



) -> dict:



    import random



    audit_checks = {



        "epsilon_audit": {"focus": "budget_consumption", "severity_threshold": 0.8},



        "composition_audit": {"focus": "sequential_composition", "severity_threshold": 0.7},



        "leakage_audit": {"focus": "information_leakage", "severity_threshold": 0.6},



        "membership_inference": {"focus": "membership_attack_resistance", "severity_threshold": 0.75},



        "attribute_inference": {"focus": "attribute_attack_resistance", "severity_threshold": 0.7},



        "model_inversion": {"focus": "reconstruction_attack_resistance", "severity_threshold": 0.65},



    }



    a_cfg = audit_checks.get(audit_type, audit_checks["epsilon_audit"])



    events = []



    for i in range(min(num_queries, 10)):



        sev = round(random.uniform(0.1, 1.0), 4)



        events.append({"event_id": i, "query_type": random.choice(["causal_edge", "intervention", "counterfactual"]), "epsilon_used": round(epsilon_total / num_queries * random.uniform(0.8, 1.2), 4), "severity": sev, "passed": sev < a_cfg["severity_threshold"], "timestamp": f"2026-05-10T{8 + i:02d}:{random.randint(10,59):02d}:00Z"})



    pass_rate = sum(1 for e in events if e["passed"]) / max(1, len(events))



    return {



        "graph_id": graph_id, "audit_type": audit_type,



        "config": {"epsilon_total": epsilon_total, "num_queries": num_queries, "sensitivity": sensitivity, "audit_depth": audit_depth},



        "audit_config": a_cfg,



        "results": {"total_events": len(events), "passed": sum(1 for e in events if e["passed"]), "failed": sum(1 for e in events if not e["passed"]), "pass_rate": round(pass_rate, 4)},



        "events": events,



        "recommendations": [



            {"priority": "high", "action": "Reduce per-query epsilon allocation", "impact": round(random.uniform(0.05, 0.2), 4)} if pass_rate < 0.8 else {"priority": "low", "action": "Continue monitoring", "impact": round(random.uniform(0.01, 0.05), 4)},



            {"priority": "medium", "action": "Implement adaptive composition", "impact": round(random.uniform(0.03, 0.15), 4)},



            {"priority": "medium", "action": "Enable noise calibration", "impact": round(random.uniform(0.02, 0.1), 4)},



        ],



        "overall_risk": round(1 - pass_rate, 4),



    }











def _manage_privacy_budget(



    graph_id: str, total_epsilon: float, total_delta: float, num_operations: int,



    allocation_strategy: str, renewal_policy: str,



) -> dict:



    import random, math



    strategies = {



        "uniform": {"per_op": total_epsilon / max(1, num_operations), "waste": round(random.uniform(0.05, 0.15), 4)},



        "adaptive": {"per_op": total_epsilon * random.uniform(0.6, 0.9) / max(1, num_operations), "waste": round(random.uniform(0.02, 0.08), 4)},



        "prioritized": {"per_op": total_epsilon * random.uniform(0.3, 0.7) / max(1, num_operations), "waste": round(random.uniform(0.03, 0.1), 4)},



        "exponential_decay": {"per_op": total_epsilon / max(1, num_operations) * 2, "waste": round(random.uniform(0.01, 0.05), 4)},



        "round_robin": {"per_op": total_epsilon / max(1, num_operations), "waste": round(random.uniform(0.08, 0.2), 4)},



        "reserved": {"per_op": total_epsilon * 0.7 / max(1, num_operations), "waste": round(random.uniform(0.01, 0.06), 4)},



    }



    s_cfg = strategies.get(allocation_strategy, strategies["uniform"])



    allocations = []



    remaining = total_epsilon



    for i in range(min(num_operations, 8)):



        alloc = round(s_cfg["per_op"] * random.uniform(0.8, 1.2), 4)



        alloc = min(alloc, remaining)



        remaining = max(0, remaining - alloc)



        allocations.append({"operation_id": i, "allocated_epsilon": alloc, "consumed_epsilon": round(alloc * random.uniform(0.7, 1.0), 4), "remaining_budget": round(remaining, 4), "status": "consumed" if remaining > 0 else "exhausted"})



    utilization = round((total_epsilon - remaining) / total_epsilon, 4) if total_epsilon > 0 else 0



    return {



        "graph_id": graph_id,



        "config": {"total_epsilon": total_epsilon, "total_delta": total_delta, "num_operations": num_operations, "allocation_strategy": allocation_strategy, "renewal_policy": renewal_policy},



        "strategy_config": s_cfg,



        "allocations": allocations,



        "summary": {"total_budget": total_epsilon, "consumed": round(total_epsilon - remaining, 4), "remaining": round(remaining, 4), "utilization_rate": utilization, "waste_rate": s_cfg["waste"]},



        "renewal": {"policy": renewal_policy, "next_renewal": "2026-05-11T00:00:00Z", "renewal_amount": round(total_epsilon * 0.5, 4) if renewal_policy != "none" else 0},



    }











def _secure_causal_aggregation(



    graph_id: str, method: str, num_parties: int, threshold: int,



    causal_graph_size: int, security_param: int,



) -> dict:



    import random, math



    methods = {



        "secret_sharing": {"overhead_factor": 2.5, "communication_rounds": 3, "security_level": "information_theoretic"},



        "homomorphic": {"overhead_factor": 5.0, "communication_rounds": 2, "security_level": "computational"},



        "tee_based": {"overhead_factor": 1.2, "communication_rounds": 1, "security_level": "hardware_trusted"},



        "secure_mpc": {"overhead_factor": 3.0, "communication_rounds": 4, "security_level": "information_theoretic"},



        "functional_enc": {"overhead_factor": 4.5, "communication_rounds": 2, "security_level": "computational"},



        "trusted_aggregator": {"overhead_factor": 1.0, "communication_rounds": 1, "security_level": "trusted_third_party"},



    }



    m_cfg = methods.get(method, methods["secret_sharing"])



    local_edges = []



    for i in range(num_parties):



        local_edges.append({"party_id": i, "edges_contributed": random.randint(3, causal_graph_size), "noise_added": round(random.uniform(0.01, 0.1), 4), "share_sent": True})



    total_aggregated = random.randint(causal_graph_size // 2, causal_graph_size * 2)



    return {



        "graph_id": graph_id, "method": method,



        "config": {"num_parties": num_parties, "threshold": threshold, "causal_graph_size": causal_graph_size, "security_param": security_param},



        "method_config": m_cfg,



        "aggregation": {"total_edges_aggregated": total_aggregated, "consensus_edges": random.randint(3, min(15, total_aggregated)), "aggregation_accuracy": round(random.uniform(0.7, 0.95), 4), "false_positive_rate": round(random.uniform(0.01, 0.15), 4)},



        "party_details": local_edges,



        "performance": {"communication_rounds": m_cfg["communication_rounds"], "total_data_sent_kb": round(random.uniform(5, 100) * m_cfg["overhead_factor"], 1), "computation_time_ms": round(random.uniform(50, 500) * m_cfg["overhead_factor"], 1), "overhead_factor": m_cfg["overhead_factor"]},



        "security_analysis": {"collusion_resistance": f"t < {threshold}/{num_parties}", "privacy_amplification": round(math.sqrt(num_parties) * random.uniform(0.5, 1.0), 4), "cheating_detection_rate": round(random.uniform(0.85, 0.99), 4)},



    }











def _privacy_utility_tradeoff(



    graph_id: str, metric: str, epsilon_range: list, causal_model_size: int,



    noise_multiplier: float, evaluation_rounds: int,



) -> dict:



    import random, math



    metrics_info = {



        "causal_f1": {"higher_better": True, "baseline_range": (0.7, 0.95), "privacy_impact": "moderate"},



        "structural_hamming": {"higher_better": False, "baseline_range": (2, 15), "privacy_impact": "high"},



        "intervention_accuracy": {"higher_better": True, "baseline_range": (0.65, 0.9), "privacy_impact": "moderate"},



        "ate_error": {"higher_better": False, "baseline_range": (0.05, 0.3), "privacy_impact": "low"},



        "privacy_overhead": {"higher_better": False, "baseline_range": (0.1, 0.5), "privacy_impact": "direct"},



        "information_gain": {"higher_better": True, "baseline_range": (0.5, 0.85), "privacy_impact": "moderate"},



    }



    m_cfg = metrics_info.get(metric, metrics_info["causal_f1"])



    tradeoff_curve = []



    baseline = round(random.uniform(*m_cfg["baseline_range"]), 4)



    for eps in epsilon_range:



        noise_effect = max(0, 1 - eps * noise_multiplier * random.uniform(0.5, 1.5))



        if m_cfg["higher_better"]:



            utility = round(baseline * noise_effect * random.uniform(0.85, 1.0), 4)



        else:



            utility = round(baseline * (2 - noise_effect) * random.uniform(0.9, 1.1), 4)



        tradeoff_curve.append({"epsilon": eps, "utility": utility, "privacy_loss": round(eps, 4), "noise_scale": round(noise_multiplier / max(0.01, eps), 4)})



    optimal_point = max(tradeoff_curve, key=lambda x: x["utility"]) if m_cfg["higher_better"] else min(tradeoff_curve, key=lambda x: x["utility"])



    return {



        "graph_id": graph_id, "metric": metric,



        "config": {"epsilon_range": epsilon_range, "causal_model_size": causal_model_size, "noise_multiplier": noise_multiplier, "evaluation_rounds": evaluation_rounds},



        "metric_config": m_cfg,



        "tradeoff_curve": tradeoff_curve,



        "analysis": {"baseline_performance": baseline, "optimal_epsilon": optimal_point["epsilon"], "optimal_utility": optimal_point["utility"], "pareto_efficient_points": random.randint(2, min(5, len(epsilon_range)))},



        "recommendations": {"suggested_epsilon": round(random.uniform(0.5, 3.0), 2), "expected_utility_drop": round(random.uniform(0.02, 0.15), 4), "confidence_interval": [round(optimal_point["utility"] - 0.05, 4), round(optimal_point["utility"] + 0.05, 4)]},



        "evaluations": evaluation_rounds,



    }











