# --- Computation Functions ---











def _temporal_causal_discover(



    graph_id: str, model: str, num_time_steps: int, num_variables: int,



    max_lag: int, significance: float, window_size: int,



) -> dict:



    import random, math



    models = {



        "var_causal": {"lag_order": max_lag, "stationarity": "required", "causality_test": "granger"},



        "granger": {"lag_order": max_lag, "stationarity": "required", "causality_test": "f_test"},



        "dti": {"lag_order": max_lag, "stationarity": "not_required", "causality_test": "transfer_entropy"},



        "svcm": {"lag_order": max_lag, "stationarity": "not_required", "causality_test": "structural"},



        "time_varying_dag": {"lag_order": max_lag, "stationarity": "not_required", "causality_test": "score_based"},



        "rnn_causal": {"lag_order": max_lag, "stationarity": "not_required", "causality_test": "neural"},



    }



    m_cfg = models.get(model, models["var_causal"])



    time_windows = []



    for w in range(max(1, num_time_steps // window_size)):



        edges = random.randint(2, num_variables * max_lag)



        density = round(edges / max(1, num_variables * (num_variables - 1)), 4)



        time_windows.append({



            "window_id": w, "start_step": w * window_size, "end_step": min((w + 1) * window_size, num_time_steps),



            "causal_edges": edges, "density": density,



            "stability": round(random.uniform(0.6, 0.99), 4),



            "dominant_direction": random.choice(["X→Y", "Y→X", "X↔Y", "X⟂Y"]),



        })



    total_edges = sum(tw["causal_edges"] for tw in time_windows)



    stable_edges = int(total_edges * random.uniform(0.4, 0.8))



    return {



        "graph_id": graph_id, "model": model,



        "config": {"num_time_steps": num_time_steps, "num_variables": num_variables, "max_lag": max_lag, "significance": significance, "window_size": window_size},



        "model_config": m_cfg,



        "discovery": {



            "total_causal_edges": total_edges, "stable_edges": stable_edges, "transient_edges": total_edges - stable_edges,



            "avg_density": round(sum(tw["density"] for tw in time_windows) / max(1, len(time_windows)), 4),



            "temporal_consistency": round(random.uniform(0.5, 0.9), 4),



            "discovery_method": m_cfg["causality_test"],



        },



        "time_windows": time_windows,



        "lag_analysis": {"optimal_lag": random.randint(1, max_lag), "lag_significance": [round(random.uniform(0.01, significance), 4) for _ in range(max_lag)], "decay_pattern": "exponential"},



        "stationarity": {"is_stationary": random.random() > 0.3, "adf_statistic": round(random.uniform(-5, 1), 4), "kpss_statistic": round(random.uniform(0.01, 0.5), 4)},



    }











def _causal_forecast(



    graph_id: str, method: str, horizon: int, confidence: float,



    num_variables: int, history_length: int,



) -> dict:



    import random, math



    methods = {



        "arima_causal": {"type": "statistical", "handles_nonlinear": False, "causal_aware": True},



        "var_forecast": {"type": "multivariate", "handles_nonlinear": False, "causal_aware": True},



        "lstm_causal": {"type": "neural", "handles_nonlinear": True, "causal_aware": True},



        "transformer_causal": {"type": "attention", "handles_nonlinear": True, "causal_aware": True},



        "gnn_temporal": {"type": "graph_neural", "handles_nonlinear": True, "causal_aware": True},



        "ensemble_causal": {"type": "ensemble", "handles_nonlinear": True, "causal_aware": True},



    }



    m_cfg = methods.get(method, methods["arima_causal"])



    forecasts = []



    for h in range(horizon):



        base = random.uniform(-2, 2)



        unc = base * (1 + h * 0.05)



        forecasts.append({



            "step": h + 1, "point_forecast": round(base, 4),



            "lower_bound": round(base - unc * 0.5, 4), "upper_bound": round(base + unc * 0.5, 4),



            "causal_contribution": round(random.uniform(0.1, 0.6), 4),



        })



    return {



        "graph_id": graph_id, "method": method,



        "config": {"horizon": horizon, "confidence": confidence, "num_variables": num_variables, "history_length": history_length},



        "method_config": m_cfg,



        "forecasts": forecasts,



        "accuracy": {



            "mae": round(random.uniform(0.05, 0.5), 4), "rmse": round(random.uniform(0.1, 0.8), 4),



            "mape": round(random.uniform(1, 15), 1), "causal_explanation_ratio": round(random.uniform(0.4, 0.85), 4),



        },



        "causal_decomposition": [{"variable": f"X_{i}", "contribution_pct": round(random.uniform(5, 30), 1), "lag_effect": random.randint(0, 3)} for i in range(min(num_variables, 6))],



        "uncertainty": {"aleatoric": round(random.uniform(0.05, 0.2), 4), "epistemic": round(random.uniform(0.02, 0.15), 4), "total": round(random.uniform(0.08, 0.3), 4)},



    }











def _changepoint_detect(



    graph_id: str, method: str, num_time_steps: int, sensitivity: float,



    min_segment_length: int, num_variables: int,



) -> dict:



    import random, math



    methods = {



        "cusum": {"type": "parametric", "online": False, "computational_cost": "low"},



        "bayesian_online": {"type": "bayesian", "online": True, "computational_cost": "medium"},



        "kernel_cp": {"type": "nonparametric", "online": False, "computational_cost": "medium"},



        "energy_distance": {"type": "nonparametric", "online": False, "computational_cost": "low"},



        "graph_cp": {"type": "graph_based", "online": False, "computational_cost": "high"},



        "causal_cp": {"type": "causal_aware", "online": True, "computational_cost": "high"},



    }



    m_cfg = methods.get(method, methods["cusum"])



    num_cps = random.randint(1, max(1, num_time_steps // min_segment_length // 2))



    changepoints = []



    for i in range(num_cps):



        cp_step = random.randint(min_segment_length, num_time_steps - min_segment_length)



        changepoints.append({



            "cp_id": i, "step": cp_step,



            "confidence": round(random.uniform(0.6, 0.99), 4),



            "magnitude": round(random.uniform(0.1, 1.0), 4),



            "affected_variables": random.sample([f"X_{j}" for j in range(num_variables)], min(num_variables, random.randint(1, 4))),



            "type": random.choice(["mean_shift", "variance_change", "structural_break", "causal_rewiring"]),



        })



    changepoints.sort(key=lambda x: x["step"])



    segments = []



    prev = 0



    for cp in changepoints:



        segments.append({"start": prev, "end": cp["step"], "length": cp["step"] - prev, "regime": f"regime_{len(segments)}"})



        prev = cp["step"]



    segments.append({"start": prev, "end": num_time_steps, "length": num_time_steps - prev, "regime": f"regime_{len(segments)}"})



    return {



        "graph_id": graph_id, "method": method,



        "config": {"num_time_steps": num_time_steps, "sensitivity": sensitivity, "min_segment_length": min_segment_length, "num_variables": num_variables},



        "method_config": m_cfg,



        "changepoints": changepoints,



        "segments": segments,



        "summary": {"num_changepoints": len(changepoints), "avg_segment_length": round(sum(s["length"] for s in segments) / max(1, len(segments)), 1), "detection_sensitivity": sensitivity, "false_positive_rate": round(random.uniform(0.01, 0.1), 4)},



    }











def _temporal_intervention_sim(



    graph_id: str, intervention_type: str, num_steps: int, intervention_step: int,



    target_variable: str, effect_magnitude: float, propagation_depth: int,



) -> dict:



    import random, math



    int_types = {



        "instantaneous": {"duration": 1, "spread": "immediate", "reversibility": "automatic"},



        "delayed": {"duration": 1, "spread": "delayed", "reversibility": "automatic"},



        "sustained": {"duration": "ongoing", "spread": "gradual", "reversibility": "manual"},



        "periodic": {"duration": "repeating", "spread": "oscillating", "reversibility": "periodic"},



        "adaptive": {"duration": "dynamic", "spread": "adaptive", "reversibility": "conditional"},



        "rolling": {"duration": "rolling_window", "spread": "smoothed", "reversibility": "gradual"},



    }



    i_cfg = int_types.get(intervention_type, int_types["instantaneous"])



    timeline = []



    for t in range(min(num_steps, 20)):



        pre_effect = round(random.gauss(0, 0.5), 4) if t < intervention_step else None



        if t >= intervention_step:



            delay = t - intervention_step



            decay = math.exp(-0.1 * delay) if intervention_type != "sustained" else 1.0



            post_effect = round(effect_magnitude * decay * random.uniform(0.8, 1.2), 4)



            propagated = round(post_effect * random.uniform(0.3, 0.8), 4) if delay <= propagation_depth else 0



            timeline.append({"step": t, "phase": "post", "direct_effect": post_effect, "propagated_effect": propagated, "total_effect": round(post_effect + propagated, 4)})



        else:



            timeline.append({"step": t, "phase": "pre", "baseline": pre_effect, "direct_effect": 0, "propagated_effect": 0, "total_effect": pre_effect})



    total_impact = sum(abs(t.get("total_effect", 0)) for t in timeline if t["phase"] == "post")



    return {



        "graph_id": graph_id, "intervention_type": intervention_type,



        "config": {"num_steps": num_steps, "intervention_step": intervention_step, "target_variable": target_variable, "effect_magnitude": effect_magnitude, "propagation_depth": propagation_depth},



        "intervention_config": i_cfg,



        "timeline": timeline,



        "impact_summary": {



            "total_impact": round(total_impact, 4), "peak_effect": round(effect_magnitude * random.uniform(1.0, 1.5), 4),



            "time_to_peak": random.randint(0, propagation_depth + 2),



            "recovery_step": random.randint(intervention_step + propagation_depth, num_steps) if intervention_type != "sustained" else None,



            "spillover_ratio": round(random.uniform(0.1, 0.5), 4),



        },



        "affected_paths": [{"from": target_variable, "to": f"X_{random.randint(0, 5)}", "delay": random.randint(0, 3), "strength": round(random.uniform(0.2, 0.8), 4)} for _ in range(min(3, propagation_depth))],



    }











def _time_varying_effect_estimate(



    graph_id: str, effect_type: str, num_time_points: int, treatment: str,



    outcome: str, confounders: list,



) -> dict:



    import random, math



    effect_types = {



        "constant": {"pattern": "flat", "variation": 0, "interpretability": "high"},



        "linear_trend": {"pattern": "increasing/decreasing", "variation": "low", "interpretability": "high"},



        "piecewise": {"pattern": "segmented", "variation": "medium", "interpretability": "medium"},



        "cyclic": {"pattern": "periodic", "variation": "medium", "interpretability": "medium"},



        "decaying": {"pattern": "exponential_decay", "variation": "low", "interpretability": "high"},



        "regime_switching": {"pattern": "switching", "variation": "high", "interpretability": "low"},



    }



    e_cfg = effect_types.get(effect_type, effect_types["constant"])



    effect_curve = []



    base_ate = round(random.uniform(0.1, 1.0), 4)



    for t in range(min(num_time_points, 12)):



        if effect_type == "constant":



            ate = base_ate



        elif effect_type == "linear_trend":



            ate = base_ate * (1 + t * 0.05)



        elif effect_type == "piecewise":



            ate = base_ate if t < num_time_points // 2 else base_ate * 1.5



        elif effect_type == "cyclic":



            ate = base_ate * (1 + 0.3 * math.sin(t * math.pi / 4))



        elif effect_type == "decaying":



            ate = base_ate * math.exp(-0.15 * t)



        else:



            ate = base_ate * random.choice([0.8, 1.2, 1.0])



        ate = round(ate, 4)



        effect_curve.append({"time": t, "ate": ate, "ci_lower": round(ate - random.uniform(0.05, 0.2), 4), "ci_upper": round(ate + random.uniform(0.05, 0.2), 4)})



    return {



        "graph_id": graph_id, "effect_type": effect_type, "treatment": treatment, "outcome": outcome,



        "config": {"num_time_points": num_time_points, "confounders": confounders},



        "effect_config": e_cfg,



        "effect_curve": effect_curve,



        "summary": {



            "mean_ate": round(sum(e["ate"] for e in effect_curve) / len(effect_curve), 4),



            "max_ate": max(e["ate"] for e in effect_curve),



            "min_ate": min(e["ate"] for e in effect_curve),



            "variance": round(random.uniform(0.001, 0.05), 6),



            "trend_direction": "increasing" if effect_curve[-1]["ate"] > effect_curve[0]["ate"] else "decreasing" if effect_curve[-1]["ate"] < effect_curve[0]["ate"] else "stable",



        },



        "confounder_adjustment": [{"variable": c, "time_varying": random.random() > 0.5, "adjustment_quality": round(random.uniform(0.6, 0.95), 4)} for c in confounders[:6]],



        "robustness": {"sensitivity_score": round(random.uniform(0.7, 0.95), 4), "e_value": round(random.uniform(1.5, 3.0), 2)},



    }











def _causal_cycle_detect(



    graph_id: str, cycle_type: str, num_nodes: int, num_edges: int,



    max_cycle_length: int, damping: float,



) -> dict:



    import random, math



    cycle_types = {



        "positive_feedback": {"stability": "unstable", "growth": "exponential", "control_difficulty": "high"},



        "negative_feedback": {"stability": "stable", "growth": "damped", "control_difficulty": "low"},



        "oscillating": {"stability": "marginal", "growth": "bounded", "control_difficulty": "medium"},



        "damped": {"stability": "stable", "growth": "decaying", "control_difficulty": "low"},



        "chaotic": {"stability": "unstable", "growth": "sensitive", "control_difficulty": "very_high"},



        "resonant": {"stability": "marginal", "growth": "amplifying", "control_difficulty": "high"},



    }



    c_cfg = cycle_types.get(cycle_type, cycle_types["positive_feedback"])



    cycles = []



    for i in range(random.randint(1, min(5, num_edges // 2))):



        length = random.randint(2, max_cycle_length)



        nodes = random.sample([f"N_{j}" for j in range(num_nodes)], length)



        cycles.append({



            "cycle_id": i, "length": length, "nodes": nodes,



            "strength": round(random.uniform(0.3, 0.95), 4),



            "period": random.randint(2, 20) if cycle_type in ("oscillating", "resonant") else None,



            "gain": round(random.uniform(0.5, 2.0), 4),



            "damping_ratio": round(damping * random.uniform(0.5, 1.5), 4),



        })



    simulation = []



    val = 1.0



    for t in range(20):



        if cycle_type == "positive_feedback":



            val *= 1.05



        elif cycle_type == "negative_feedback":



            val *= 0.95



        elif cycle_type == "oscillating":



            val = math.sin(t * 0.5) * damping



        elif cycle_type == "damped":



            val *= math.exp(-0.1) * math.cos(t * 0.5)



        elif cycle_type == "chaotic":



            val = val * 3.9 * (1 - val)



        else:



            val = val * (1 + 0.1 * math.sin(t * 0.3))



        simulation.append({"step": t, "amplitude": round(val, 4)})



    return {



        "graph_id": graph_id, "cycle_type": cycle_type,



        "config": {"num_nodes": num_nodes, "num_edges": num_edges, "max_cycle_length": max_cycle_length, "damping": damping},



        "cycle_config": c_cfg,



        "detected_cycles": cycles,



        "simulation": simulation,



        "analysis": {



            "total_cycles": len(cycles), "avg_cycle_strength": round(sum(c["strength"] for c in cycles) / max(1, len(cycles)), 4),



            "dominant_cycle": max(cycles, key=lambda x: x["strength"])["cycle_id"] if cycles else None,



            "stability_assessment": c_cfg["stability"], "control_recommendation": random.choice(["break_cycle", "add_damping", "monitor", "redesign"]),



        },



        "intervention_points": [{"node": f"N_{random.randint(0, num_nodes-1)}", "intervention": random.choice(["reduce_gain", "add_delay", "clamp_value"]), "expected_impact": round(random.uniform(0.1, 0.5), 4)} for _ in range(min(3, len(cycles)))],



    }











