# --- Caches ---







_cf_generate_cache: Dict[str, dict] = {}



_cf_evaluate_cache: Dict[str, dict] = {}



_cf_whatif_cache: Dict[str, dict] = {}



_cf_explain_cache: Dict[str, dict] = {}



_cf_sensitivity_cache: Dict[str, dict] = {}



_cf_fairness_cache: Dict[str, dict] = {}











# --- Computation Functions ---











def _generate_counterfactual(



    graph_id: str, method: str, factual_outcome: float, target_outcome: float,



    num_variables: int, intervention_vars: list, max_iterations: int,



) -> dict:



    import random, math



    methods = {



        "twin_network": {"approach": "parallel_worlds", "complexity": "medium", "guarantees": "structural"},



        "structural": {"approach": "structural_equations", "complexity": "high", "guarantees": "exact"},



        "abduction": {"approach": "abduction_action_prediction", "complexity": "medium", "guarantees": "consistent"},



        "interventionist": {"approach": "do_operator", "complexity": "low", "guarantees": "interventional"},



        "gnn_counterfactual": {"approach": "graph_neural", "complexity": "high", "guarantees": "approximate"},



        "variational_cf": {"approach": "variational_inference", "complexity": "high", "guarantees": "probabilistic"},



    }



    m_cfg = methods.get(method, methods["twin_network"])



    cf_facts = []



    for v in range(min(num_variables, 8)):



        factual_val = round(random.uniform(-2, 2), 4)



        cf_val = round(factual_val + random.uniform(-1, 1) * abs(target_outcome - factual_outcome) * 0.3, 4)



        cf_facts.append({"variable": f"X_{v}", "factual_value": factual_val, "counterfactual_value": cf_val, "change": round(cf_val - factual_val, 4), "intervened": f"X_{v}" in intervention_vars})



    gap = abs(target_outcome - factual_outcome)



    achieved = round(target_outcome + random.uniform(-gap * 0.1, gap * 0.1), 4)



    return {



        "graph_id": graph_id, "method": method,



        "config": {"factual_outcome": factual_outcome, "target_outcome": target_outcome, "num_variables": num_variables, "intervention_vars": intervention_vars, "max_iterations": max_iterations},



        "method_config": m_cfg,



        "counterfactual": {"achieved_outcome": achieved, "target_outcome": target_outcome, "outcome_gap": round(abs(achieved - target_outcome), 4), "iterations_used": random.randint(1, max_iterations)},



        "factual_world": [{"variable": cf["variable"], "value": cf["factual_value"]} for cf in cf_facts],



        "counterfactual_world": [{"variable": cf["variable"], "value": cf["counterfactual_value"], "changed": cf["change"] != 0} for cf in cf_facts],



        "changes": [cf for cf in cf_facts if cf["change"] != 0],



        "causal_path": {"from_vars": intervention_vars[:3], "through_vars": [f"X_{random.randint(0, num_variables - 1)}" for _ in range(2)], "to_outcome": "Y", "path_strength": round(random.uniform(0.5, 0.95), 4)},



    }











def _evaluate_counterfactual(



    graph_id: str, metric: str, num_samples: int, threshold: float,



    factual_distribution: list, cf_distribution: list,



) -> dict:



    import random, math



    metrics_info = {



        "validity": {"description": "CF achieves target", "higher_better": True, "range": (0, 1)},



        "proximity": {"description": "Minimal change from factual", "higher_better": True, "range": (0, 1)},



        "sparsity": {"description": "Few features changed", "higher_better": True, "range": (0, 1)},



        "plausibility": {"description": "CF is realistic", "higher_better": True, "range": (0, 1)},



        "causally_consistent": {"description": "Respects causal structure", "higher_better": True, "range": (0, 1)},



        "diversity": {"description": "Multiple diverse CFs", "higher_better": True, "range": (0, 1)},



    }



    m_cfg = metrics_info.get(metric, metrics_info["validity"])



    score = round(random.uniform(0.5, 0.98), 4) if random.random() > 0.2 else round(random.uniform(0.3, 0.6), 4)



    samples = []



    for i in range(min(num_samples, 8)):



        s = round(random.uniform(0.4, 0.99), 4)



        passed = s >= threshold



        samples.append({"sample_id": i, "score": s, "passed": passed})



    pass_rate = sum(1 for s in samples if s["passed"]) / max(1, len(samples))



    return {



        "graph_id": graph_id, "metric": metric,



        "config": {"num_samples": num_samples, "threshold": threshold},



        "metric_config": m_cfg,



        "overall_score": score,



        "samples": samples,



        "summary": {"total": len(samples), "passed": sum(1 for s in samples if s["passed"]), "pass_rate": round(pass_rate, 4), "mean_score": round(sum(s["score"] for s in samples) / max(1, len(samples)), 4)},



        "distribution_analysis": {"factual_mean": round(random.uniform(-1, 1), 4), "cf_mean": round(random.uniform(-1, 1), 4), "wasserstein_distance": round(random.uniform(0.01, 0.5), 4), "kl_divergence": round(random.uniform(0.01, 0.3), 4)},



    }











def _whatif_scenario(



    graph_id: str, scenario: str, num_nodes: int, num_edges: int,



    target_node: str, perturbation_strength: float,



) -> dict:



    import random, math



    scenarios = {



        "node_removal": {"impact_type": "structural", "reversibility": "reversible", "scope": "local_to_global"},



        "edge_removal": {"impact_type": "connectivity", "reversibility": "reversible", "scope": "local"},



        "edge_addition": {"impact_type": "connectivity", "reversibility": "reversible", "scope": "local"},



        "weight_change": {"impact_type": "strength", "reversibility": "reversible", "scope": "local"},



        "subgraph_replace": {"impact_type": "structural", "reversibility": "reversible", "scope": "global"},



        "cascade_interrupt": {"impact_type": "dynamics", "reversibility": "irreversible", "scope": "global"},



    }



    s_cfg = scenarios.get(scenario, scenarios["node_removal"])



    affected_nodes = random.sample([f"N_{i}" for i in range(num_nodes)], min(num_nodes, random.randint(2, 8)))



    before_metrics = {"centrality": round(random.uniform(0.1, 0.9), 4), "clustering": round(random.uniform(0.2, 0.8), 4), "path_length": round(random.uniform(1, 5), 4), "density": round(num_edges / max(1, num_nodes * (num_nodes - 1)), 4)}



    impact = perturbation_strength * random.uniform(0.5, 1.5)



    after_metrics = {k: round(max(0, v * (1 - impact * random.uniform(0.2, 0.8))), 4) for k, v in before_metrics.items()}



    cascading_effects = []



    for n in affected_nodes[:5]:



        cascading_effects.append({"node": n, "before": round(random.uniform(0, 1), 4), "after": round(random.uniform(0, 1), 4), "delta": round(random.uniform(-0.5, 0.3), 4), "propagation_depth": random.randint(0, 3)})



    return {



        "graph_id": graph_id, "scenario": scenario,



        "config": {"num_nodes": num_nodes, "num_edges": num_edges, "target_node": target_node, "perturbation_strength": perturbation_strength},



        "scenario_config": s_cfg,



        "graph_metrics": {"before": before_metrics, "after": after_metrics, "delta": {k: round(after_metrics[k] - before_metrics[k], 4) for k in before_metrics}},



        "affected_nodes": affected_nodes,



        "cascading_effects": cascading_effects,



        "robustness": {"graph_resilience": round(random.uniform(0.4, 0.95), 4), "critical_nodes": random.randint(1, 3), "recovery_probability": round(random.uniform(0.6, 0.99), 4)},



        "recommendation": {"action": random.choice(["monitor", "reinforce", "restructure", "accept"]), "confidence": round(random.uniform(0.7, 0.95), 4)},



    }











def _counterfactual_explain(



    graph_id: str, explanation_type: str, outcome: str, outcome_value: float,



    num_candidate_causes: int, explanation_depth: int,



) -> dict:



    import random



    explanations = {



        "necessary_cause": {"logic": "X is necessary for Y", "negation": "not X → not Y"},



        "sufficient_cause": {"logic": "X is sufficient for Y", "negation": "X → Y always"},



        "contributory_cause": {"logic": "X contributes to Y", "negation": "X increases P(Y)"},



        "counter_necessary": {"logic": "without X, not Y", "negation": "CF: not X → not Y"},



        "counter_sufficient": {"logic": "X alone can cause Y", "negation": "CF: X → Y in minimal context"},



        "actual_cause": {"logic": "X actually caused Y", "negation": "but-for test: without X, Y?"},



    }



    e_cfg = explanations.get(explanation_type, explanations["necessary_cause"])



    causes = []



    for i in range(num_candidate_causes):



        causes.append({



            "cause_variable": f"X_{i}", "causal_strength": round(random.uniform(0.1, 0.9), 4),



            "is_explanation": i == 0,



            "counterfactual_dependence": round(random.uniform(0.3, 0.95), 4),



            "normality": round(random.uniform(0.4, 0.95), 4),



            "specificity": round(random.uniform(0.3, 0.9), 4),



        })



    causes.sort(key=lambda x: x["causal_strength"], reverse=True)



    return {



        "graph_id": graph_id, "explanation_type": explanation_type,



        "config": {"outcome": outcome, "outcome_value": outcome_value, "num_candidate_causes": num_candidate_causes, "explanation_depth": explanation_depth},



        "explanation_config": e_cfg,



        "primary_explanation": {"cause": causes[0]["cause_variable"], "strength": causes[0]["causal_strength"], "reasoning": f"Based on {explanation_type} analysis", "counterfactual": f"If {causes[0]['cause_variable']} had been different, {outcome} would likely change"},



        "causal_candidates": causes,



        "explanation_chain": [{"step": i, "variable": causes[i]["cause_variable"], "mechanism": random.choice(["direct_effect", "mediated", "moderated", "suppressed"]), "confidence": round(random.uniform(0.6, 0.95), 4)} for i in range(min(explanation_depth, len(causes)))],



        "but_for_test": {"passed": random.random() > 0.3, "original_outcome": outcome_value, "counterfactual_outcome": round(outcome_value * random.uniform(-0.5, 0.8), 4), "difference": round(random.uniform(0.1, 0.9), 4)},



    }











def _sensitivity_analysis(



    graph_id: str, method: str, treatment: str, outcome: str,



    confounders: list, num_simulations: int,



) -> dict:



    import random, math



    methods = {



        "einstein": {"type": "formal", "output": "e_value", "interpretation": "minimum strength of confounder"},



        "rosenbaum": {"type": "bounds", "output": "gamma", "interpretation": "odds of differential treatment"},



        "cornfield": {"type": "inequality", "output": "risk_ratio_bound", "interpretation": "minimum confounder-outcome association"},



        "dagitty": {"type": "graph_based", "output": "adjustment_set", "interpretation": "minimal sufficient adjustment set"},



        "causal_forest": {"type": "machine_learning", "output": "heterogeneous_effects", "interpretation": "treatment effect variation"},



        "partial_r2": {"type": "variance_based", "output": "r2_partial", "interpretation": "proportion of variance from confounding"},



    }



    m_cfg = methods.get(method, methods["einstein"])



    simulations = []



    for i in range(min(num_simulations, 8)):



        bias = round(random.uniform(0, 1), 4)



        sims = {"sim_id": i, "confounding_strength": round(random.uniform(0, 0.5), 4), "estimated_effect": round(random.uniform(0.1, 1.0) - bias * 0.3, 4), "bias": bias, "robust": bias < 0.3}



        simulations.append(sims)



    robust_count = sum(1 for s in simulations if s["robust"])



    return {



        "graph_id": graph_id, "method": method, "treatment": treatment, "outcome": outcome,



        "config": {"confounders": confounders, "num_simulations": num_simulations},



        "method_config": m_cfg,



        "main_result": {"point_estimate": round(random.uniform(0.2, 0.8), 4), "robustness_value": round(random.uniform(0.3, 0.95), 4), "e_value": round(random.uniform(1.5, 5.0), 2), "partial_r2": round(random.uniform(0.01, 0.3), 4)},



        "simulations": simulations,



        "confounder_analysis": [{"confounder": c, "potential_bias": round(random.uniform(0.01, 0.2), 4), "r2_with_treatment": round(random.uniform(0.01, 0.15), 4), "r2_with_outcome": round(random.uniform(0.01, 0.2), 4)} for c in confounders[:6]],



        "summary": {"robustness_rate": round(robust_count / max(1, len(simulations)), 4), "max_bias": round(max(s["bias"] for s in simulations), 4), "conclusion": "robust" if robust_count / max(1, len(simulations)) > 0.7 else "sensitive"},



    }











def _counterfactual_fairness(



    graph_id: str, fairness_metric: str, sensitive_attribute: str,



    outcome: str, num_individuals: int, threshold: float,



) -> dict:



    import random, math



    metrics_info = {



        "demographic_parity": {"compares": "P(Y|A=a) vs P(Y|A≠a)", "type": "group", "range": (0, 1)},



        "equalized_odds": {"compares": "P(Y|Y_true,A=a) vs P(Y|Y_true,A≠a)", "type": "group", "range": (0, 1)},



        "counterfactual_parity": {"compares": "P(Y_A=a vs Y_A≠a)", "type": "individual", "range": (0, 1)},



        "individual_fairness": {"compares": "similar individuals → similar outcomes", "type": "individual", "range": (0, 1)},



        "path_specific": {"compares": "effect through specific causal paths", "type": "path", "range": (0, 1)},



        "interventional_fair": {"compares": "P(Y|do(A=a)) vs P(Y|do(A≠a))", "type": "interventional", "range": (0, 1)},



    }



    m_cfg = metrics_info.get(fairness_metric, metrics_info["demographic_parity"])



    individuals = []



    for i in range(min(num_individuals, 8)):



        factual = round(random.uniform(0, 1), 4)



        cf = round(random.uniform(0, 1), 4)



        individuals.append({



            "individual_id": i, "factual_outcome": factual, "counterfactual_outcome": cf,



            "difference": round(cf - factual, 4), "fair": abs(cf - factual) < threshold,



        })



    fair_count = sum(1 for ind in individuals if ind["fair"])



    disparity = round(abs(random.uniform(-0.3, 0.3)), 4)



    return {



        "graph_id": graph_id, "fairness_metric": fairness_metric, "sensitive_attribute": sensitive_attribute, "outcome": outcome,



        "config": {"num_individuals": num_individuals, "threshold": threshold},



        "metric_config": m_cfg,



        "fairness_score": round(1 - disparity, 4),



        "individual_analysis": individuals,



        "group_analysis": {



            "group_a_mean": round(random.uniform(0.3, 0.7), 4), "group_b_mean": round(random.uniform(0.3, 0.7), 4),



            "disparity": disparity, "statistical_parity": round(1 - disparity, 4),



        },



        "paths": {



            "direct_effect": round(random.uniform(0.01, 0.15), 4),



            "indirect_effect": round(random.uniform(0.02, 0.2), 4),



            "spurious_effect": round(random.uniform(0, 0.1), 4),



            "total_effect": round(random.uniform(0.05, 0.3), 4),



        },



        "summary": {"fairness_rate": round(fair_count / max(1, len(individuals)), 4), "is_fair": disparity < threshold, "recommendation": random.choice(["no_action", "adjust_threshold", "add_constraint", "retrain"])},



    }











