    body = await request.json()



    result = _counterfactual_fairness(graph_id=body.get("graph_id", "graph_001"), fairness_metric=body.get("fairness_metric", "counterfactual_parity"), sensitive_attribute=body.get("sensitive_attribute", "A"), outcome=body.get("outcome", "Y"), num_individuals=body.get("num_individuals", 50), threshold=body.get("threshold", 0.1))



    _cf_fairness_cache[f"{result['graph_id']}_{result['fairness_metric']}_{result['sensitive_attribute']}"] = result



    return result











