# --- Caches ---







_compress_prune_cache: Dict[str, dict] = {}



_compress_quant_cache: Dict[str, dict] = {}



_compress_distill_cache: Dict[str, dict] = {}



_compress_structure_cache: Dict[str, dict] = {}



_compress_hardware_cache: Dict[str, dict] = {}



_compress_quality_cache: Dict[str, dict] = {}











# --- Computation Functions ---











def _model_pruning(



    graph_id: str, strategy: str, num_layers: int, hidden_dim: int,



    sparsity: float, importance_metric: str,



) -> dict:



    import random, math



    strategies = {



        "magnitude": {"criterion": "weight_magnitude", "granularity": "element", "retraining": True},



        "gradient": {"criterion": "gradient_magnitude", "granularity": "element", "retraining": True},



        "attention": {"criterion": "attention_score", "granularity": "head", "retraining": False},



        "structural": {"criterion": "graph_structure", "granularity": "layer", "retraining": True},



        "lottery_ticket": {"criterion": "iterative_magnitude", "granularity": "element", "retraining": True},



        "movement": {"criterion": "weight_movement", "granularity": "element", "retraining": True},



    }



    s_cfg = strategies.get(strategy, strategies["magnitude"])



    original_params = num_layers * hidden_dim * hidden_dim



    pruned_params = int(original_params * (1 - sparsity))



    layers = []



    for l in range(num_layers):



        kept = round(1 - sparsity * random.uniform(0.7, 1.3), 4)



        layers.append({"layer": l, "original_dim": hidden_dim, "kept_ratio": kept, "pruned_dim": max(1, int(hidden_dim * kept))})



    return {



        "graph_id": graph_id, "strategy": strategy,



        "config": {"num_layers": num_layers, "hidden_dim": hidden_dim, "sparsity": sparsity, "importance_metric": importance_metric},



        "strategy_config": s_cfg,



        "compression": {"original_params": original_params, "pruned_params": pruned_params, "compression_ratio": round(1 - pruned_params / max(1, original_params), 4), "flops_reduction": round(sparsity * random.uniform(0.8, 1.0), 4)},



        "layer_details": layers,



        "quality": {"accuracy_retention": round(random.uniform(0.92, 0.99), 4), "perplexity_increase": round(random.uniform(0, 0.05), 4), "embedding_shift": round(random.uniform(0.01, 0.08), 4)},



        "recovery": {"retraining_epochs": random.randint(5, 50), "recovery_rate": round(random.uniform(0.85, 0.98), 4), "lottery_ticket_found": random.random() > 0.5},



    }











def _model_quantization(



    graph_id: str, quant_type: str, model_size_mb: float, num_parameters: int,



    calibration_samples: int, sensitivity_layers: list,



) -> dict:



    import random, math



    quant_cfgs = {



        "int8": {"bits": 8, "memory_reduction": 0.75, "speedup": 2.0, "accuracy_cost": "low"},



        "int4": {"bits": 4, "memory_reduction": 0.875, "speedup": 3.0, "accuracy_cost": "medium"},



        "fp16": {"bits": 16, "memory_reduction": 0.5, "speedup": 1.5, "accuracy_cost": "negligible"},



        "bf16": {"bits": 16, "memory_reduction": 0.5, "speedup": 1.5, "accuracy_cost": "negligible"},



        "mixed_precision": {"bits": "variable", "memory_reduction": 0.6, "speedup": 1.8, "accuracy_cost": "low"},



        "adaptive": {"bits": "adaptive", "memory_reduction": 0.7, "speedup": 2.2, "accuracy_cost": "low"},



    }



    q_cfg = quant_cfgs.get(quant_type, quant_cfgs["int8"])



    compressed_size = round(model_size_mb * (1 - q_cfg["memory_reduction"]), 2)



    layer_analysis = []



    for sl in sensitivity_layers[:6]:



        layer_analysis.append({"layer": sl, "sensitivity": round(random.uniform(0.01, 0.2), 4), "recommended_bits": random.choice([4, 8, 16]), "error_contribution": round(random.uniform(0.01, 0.1), 4)})



    return {



        "graph_id": graph_id, "quant_type": quant_type,



        "config": {"model_size_mb": model_size_mb, "num_parameters": num_parameters, "calibration_samples": calibration_samples, "sensitivity_layers": sensitivity_layers},



        "quant_config": q_cfg,



        "compression": {"original_size_mb": model_size_mb, "compressed_size_mb": compressed_size, "compression_ratio": round(1 - compressed_size / max(0.01, model_size_mb), 4), "speedup_factor": q_cfg["speedup"]},



        "calibration": {"samples_used": calibration_samples, " kl_divergence": round(random.uniform(0.001, 0.05), 4), "mse": round(random.uniform(0.0001, 0.01), 4)},



        "layer_analysis": layer_analysis,



        "quality": {"accuracy_retention": round(random.uniform(0.95, 0.999), 4), "snr_db": round(random.uniform(30, 60), 1), "cosine_similarity": round(random.uniform(0.98, 0.9999), 4)},



    }











def _distillation_compression(



    graph_id: str, distill_type: str, teacher_params: int, student_params: int,



    temperature: float, num_epochs: int, alpha: float,



) -> dict:



    import random, math



    distill_cfgs = {



        "task_distill": {"loss": "task_kl", "transfer": "logit_matching", "complexity": "low"},



        "feature_distill": {"loss": "feature_mse", "transfer": "intermediate_matching", "complexity": "medium"},



        "response_distill": {"loss": "response_kl", "transfer": "output_matching", "complexity": "low"},



        "relational_distill": {"loss": "relational", "transfer": "relation_matching", "complexity": "high"},



        "progressive_distill": {"loss": "progressive", "transfer": "stage_wise", "complexity": "high"},



        "self_distill": {"loss": "self_kl", "transfer": "internal_matching", "complexity": "medium"},



    }



    d_cfg = distill_cfgs.get(distill_type, distill_cfgs["task_distill"])



    compression_ratio = round(1 - student_params / max(1, teacher_params), 4)



    teacher_acc = round(random.uniform(0.85, 0.96), 4)



    student_acc = round(teacher_acc * random.uniform(0.95, 1.0), 4)



    return {



        "graph_id": graph_id, "distill_type": distill_type,



        "config": {"teacher_params": teacher_params, "student_params": student_params, "temperature": temperature, "num_epochs": num_epochs, "alpha": alpha},



        "distill_config": d_cfg,



        "compression": {"teacher_params": teacher_params, "student_params": student_params, "compression_ratio": compression_ratio, "speedup": round(teacher_params / max(1, student_params), 1)},



        "teacher_student": {"teacher_accuracy": teacher_acc, "student_accuracy": student_acc, "fidelity": round(student_acc / max(0.01, teacher_acc), 4), "knowledge_retention": round(random.uniform(0.9, 0.98), 4)},



        "training": {"epochs": num_epochs, "final_loss": round(random.uniform(0.01, 0.2), 4), "convergence": random.randint(3, num_epochs), "temperature": temperature},



    }











def _structural_compression(



    graph_id: str, method: str, num_nodes: int, num_edges: int,



    target_ratio: float, preserve_property: str,



) -> dict:



    import random, math



    methods = {



        "pooling": {"type": "node_reduction", "overhead": "low", "invertible": False},



        "coarsening": {"type": "graph_reduction", "overhead": "medium", "invertible": False},



        "partition": {"type": "graph_splitting", "overhead": "medium", "invertible": True},



        "skeleton": {"type": "backbone_extraction", "overhead": "low", "invertible": False},



        "core_extraction": {"type": "k_core", "overhead": "low", "invertible": False},



        "spectral_compress": {"type": "eigenvalue_based", "overhead": "high", "invertible": True},



    }



    m_cfg = methods.get(method, methods["pooling"])



    compressed_nodes = max(2, int(num_nodes * target_ratio))



    compressed_edges = max(1, int(num_edges * target_ratio * random.uniform(0.8, 1.2)))



    return {



        "graph_id": graph_id, "method": method,



        "config": {"num_nodes": num_nodes, "num_edges": num_edges, "target_ratio": target_ratio, "preserve_property": preserve_property},



        "method_config": m_cfg,



        "compression": {"original_nodes": num_nodes, "compressed_nodes": compressed_nodes, "original_edges": num_edges, "compressed_edges": compressed_edges, "node_reduction": round(1 - compressed_nodes / max(1, num_nodes), 4), "edge_reduction": round(1 - compressed_edges / max(1, num_edges), 4)},



        "properties": {"degree_preservation": round(random.uniform(0.8, 0.98), 4), "centrality_preservation": round(random.uniform(0.75, 0.96), 4), "clustering_preservation": round(random.uniform(0.7, 0.95), 4), "spectral_similarity": round(random.uniform(0.85, 0.98), 4)},



        "mapping": {"node_mapping_size": min(num_nodes, compressed_nodes * 2), "edge_mapping_size": min(num_edges, compressed_edges * 2), "reconstruction_error": round(random.uniform(0.01, 0.1), 4)},



    }











def _hardware_aware_optimize(



    graph_id: str, target: str, model_size_mb: float, latency_ms: float,



    memory_mb: float, accuracy: float, constraints: dict,



) -> dict:



    import random, math



    targets = {



        "cpu_server": {"compute_tflops": 2, "memory_gb": 128, "bandwidth": "high", "power": "medium"},



        "gpu_consumer": {"compute_tflops": 30, "memory_gb": 12, "bandwidth": "high", "power": "high"},



        "gpu_datacenter": {"compute_tflops": 300, "memory_gb": 80, "bandwidth": "very_high", "power": "very_high"},



        "edge_mobile": {"compute_tflops": 1, "memory_gb": 4, "bandwidth": "medium", "power": "low"},



        "iot_device": {"compute_tflops": 0.1, "memory_gb": 0.5, "bandwidth": "low", "power": "very_low"},



        "fpga": {"compute_tflops": 10, "memory_gb": 8, "bandwidth": "high", "power": "low"},



    }



    t_cfg = targets.get(target, targets["cpu_server"])



    optimizations = []



    if model_size_mb > t_cfg["memory_gb"] * 500:



        optimizations.append({"technique": "quantization", "reduction": "4x", "accuracy_impact": round(random.uniform(0.005, 0.02), 4)})



    if latency_ms > 100:



        optimizations.append({"technique": "pruning", "reduction": "2x", "accuracy_impact": round(random.uniform(0.01, 0.03), 4)})



    if target in ("edge_mobile", "iot_device"):



        optimizations.append({"technique": "knowledge_distillation", "reduction": "10x", "accuracy_impact": round(random.uniform(0.02, 0.05), 4)})



    optimized_size = round(model_size_mb / random.uniform(2, 8), 2)



    optimized_latency = round(latency_ms / random.uniform(1.5, 4), 2)



    optimized_accuracy = round(accuracy * random.uniform(0.96, 0.995), 4)



    return {



        "graph_id": graph_id, "target": target,



        "config": {"model_size_mb": model_size_mb, "latency_ms": latency_ms, "memory_mb": memory_mb, "accuracy": accuracy, "constraints": constraints},



        "target_profile": t_cfg,



        "applied_optimizations": optimizations,



        "results": {"original_size_mb": model_size_mb, "optimized_size_mb": optimized_size, "original_latency_ms": latency_ms, "optimized_latency_ms": optimized_latency, "original_accuracy": accuracy, "optimized_accuracy": optimized_accuracy},



        "improvements": {"size_reduction": round(1 - optimized_size / max(0.01, model_size_mb), 4), "latency_reduction": round(1 - optimized_latency / max(0.01, latency_ms), 4), "accuracy_retention": round(optimized_accuracy / max(0.01, accuracy), 4)},



        "feasibility": {"fits_memory": optimized_size < t_cfg["memory_gb"] * 1000, "fits_latency": optimized_latency < 100, "meets_accuracy": optimized_accuracy > 0.9, "overall": "feasible" if optimized_size < t_cfg["memory_gb"] * 1000 and optimized_accuracy > 0.9 else "needs_adjustment"},



    }











def _quality_assured_compress(



    graph_id: str, guarantee: str, original_accuracy: float, model_params: int,



    max_quality_loss: float, compression_target: float,



) -> dict:



    import random, math



    guarantees = {



        "bounded_error": {"metric": "max_error", "threshold": max_quality_loss, "method": "error_bounded_pruning"},



        "relative_accuracy": {"metric": "accuracy_ratio", "threshold": 1 - max_quality_loss, "method": "accuracy_aware_quantization"},



        "rank_preservation": {"metric": "rank_correlation", "threshold": 0.95, "method": "rank_preserved_distillation"},



        "spectral_similarity": {"metric": "spectral_gap", "threshold": 0.9, "method": "spectral_aware_compression"},



        "structural_fidelity": {"metric": "graph_edit_distance", "threshold": 0.1, "method": "structure_preserving_reduction"},



        "downstream_preserved": {"metric": "downstream_task_accuracy", "threshold": 0.95, "method": "task_aware_compression"},



    }



    g_cfg = guarantees.get(guarantee, guarantees["bounded_error"])



    steps = []



    remaining_quality = original_accuracy



    remaining_params = model_params



    for s in range(5):



        quality_cost = round(random.uniform(0.002, max_quality_loss / 5), 4)



        param_reduction = round(random.uniform(0.1, 0.3), 4)



        remaining_quality -= quality_cost



        remaining_params = int(remaining_params * (1 - param_reduction))



        steps.append({"step": s, "technique": random.choice(["pruning", "quantization", "distillation"]), "quality_after": round(remaining_quality, 4), "params_after": remaining_params, "quality_cost": quality_cost})



        if remaining_quality < original_accuracy * (1 - max_quality_loss):



            break



    final_accuracy = round(remaining_quality, 4)



    final_params = remaining_params



    return {



        "graph_id": graph_id, "guarantee": guarantee,



        "config": {"original_accuracy": original_accuracy, "model_params": model_params, "max_quality_loss": max_quality_loss, "compression_target": compression_target},



        "guarantee_config": g_cfg,



        "compression_steps": steps,



        "result": {"final_accuracy": final_accuracy, "accuracy_preserved": round(final_accuracy / max(0.01, original_accuracy), 4), "final_params": final_params, "compression_achieved": round(1 - final_params / max(1, model_params), 4), "guarantee_met": final_accuracy >= original_accuracy * (1 - max_quality_loss)},



        "quality_metrics": {"max_degradation": round(original_accuracy - final_accuracy, 4), "quality_efficiency": round((1 - final_params / max(1, model_params)) / max(0.001, original_accuracy - final_accuracy), 2), "pareto_optimal": random.random() > 0.3},



    }











