from enum import Enum as _Enum224











class CrossModalCausalMethod(str, _Enum224):



    """Methods for detecting causal relationships across modalities."""



    canonical_correlation = "canonical_correlation"



    mutual_information = "mutual_information"



    kernel_independence = "kernel_independence"



    neural_causal = "neural_causal"



    granger_cross = "granger_cross"



    attention_causal = "attention_causal"











class ModalityAlignmentMode(str, _Enum224):



    """Modes for causal-aware multimodal alignment."""



    contrastive = "contrastive"



    generative = "generative"



    hybrid = "hybrid"



    optimal_transport = "optimal_transport"



    graph_match = "graph_match"



    adversarial = "adversarial"











class CausalGraphType(str, _Enum224):



    """Types of causal graphs spanning modalities."""



    homogeneous = "homogeneous"



    heterogeneous = "heterogeneous"



    multiplex = "multiplex"



    dynamic = "dynamic"



    attributed = "attributed"



    hierarchical = "hierarchical"











class CausalGroundingMethod(str, _Enum224):



    """Methods for grounding causal claims in multimodal evidence."""



    visual_grounding = "visual_grounding"



    textual_grounding = "textual_grounding"



    temporal_grounding = "temporal_grounding"



    structural_grounding = "structural_grounding"



    statistical_grounding = "statistical_grounding"



    joint_grounding = "joint_grounding"











class CrossModalIntervention(str, _Enum224):



    """Types of cross-modal causal interventions."""



    do_calculus = "do_calculus"



