import enum as _enum225











class SymbolicExtractionMethod(str, _enum225.Enum):



    rule_mining = "rule_mining"



    decision_tree = "decision_tree"



    attention_mapping = "attention_mapping"



    gradient_analysis = "gradient_analysis"



    concept_activation = "concept_activation"



    prototype_decomposition = "prototype_decomposition"











class LogicalInferenceMode(str, _enum225.Enum):



    deduction = "deduction"



    abduction = "abduction"



    induction = "induction"



    analogical = "analogical"



    defeasible = "defeasible"



    probabilistic = "probabilistic"











class NeuroSymbolicBridge(str, _enum225.Enum):



    continuous_discrete = "continuous_discrete"



    embedding_symbol = "embedding_symbol"



    attention_rule = "attention_rule"



    gradient_logic = "gradient_logic"



    message_passing = "message_passing"



    differentiable_prolog = "differentiable_prolog"











class ProofStrategy(str, _enum225.Enum):



    natural_deduction = "natural_deduction"



    resolution = "resolution"



    tableau = "tableau"



    sequent_calculus = "sequent_calculus"



    model_checking = "model_checking"



    automated_theorem = "automated_theorem"











class ConsistencyCheck(str, _enum225.Enum):



    semantic = "semantic"



    syntactic = "syntactic"



    empirical = "empirical"



    structural = "structural"



    temporal = "temporal"



    cross_domain = "cross_domain"











class KnowledgeCompletion(str, _enum225.Enum):



    rule_extension = "rule_extension"



