# In-memory caches for v1.226



_cf_detect_cache: dict = {}



_cf_counterfactual_cache: dict = {}



_cf_decompose_cache: dict = {}



_cf_intervene_cache: dict = {}



_cf_propagate_cache: dict = {}



_cf_certify_cache: dict = {}







_PROTECTED_ATTRS_226 = ["gender", "race", "age_group", "disability", "religion", "socioeconomic"]



_FAIRNESS_METRICS_226 = ["demographic_parity", "equal_opportunity", "predictive_equality", "calibration", "individual_consistency", "intersectional_score"]



_INTERVENTION_STATUS_226 = ["applied", "pending", "failed", "partial", "rolled_back", "optimized"]











def _compute_fairness_detection(



    graph_id: str, method: str, num_attributes: int, sensitivity: float, num_layers: int



) -> dict:



    """Detect fairness violations in causal graph structures."""



    random.seed(hash(graph_id) + hash(method) + hash("cf_detect"))



    method_metrics = {



        "statistical_parity": {"demographic_parity_diff": round(random.uniform(0.0, 0.4), 4), "disparate_impact_ratio": round(random.uniform(0.5, 1.2), 4), "group_balance": round(random.uniform(0.6, 1.0), 4)},



        "equalized_odds": {"tpr_difference": round(random.uniform(0.0, 0.3), 4), "fpr_difference": round(random.uniform(0.0, 0.25), 4), "equal_opportunity_gap": round(random.uniform(0.0, 0.35), 4)},



        "calibration_check": {"calibration_error": round(random.uniform(0.0, 0.2), 4), "reliability_score": round(random.uniform(0.7, 0.99), 4), "brier_score": round(random.uniform(0.05, 0.3), 4)},



        "individual_fairness": {"lipschitz_constant": round(random.uniform(0.8, 2.5), 4), "consistency_score": round(random.uniform(0.7, 0.98), 4), "neighborhood_agreement": round(random.uniform(0.6, 0.95), 4)},



        "counterfactual_detection": {"counterfactual_gap": round(random.uniform(0.0, 0.3), 4), "treatment_effect_disparity": round(random.uniform(0.0, 0.25), 4), "causal_bias_score": round(random.uniform(0.0, 0.4), 4)},



        "intersectional_analysis": {"intersectional_disparity": round(random.uniform(0.0, 0.35), 4), "multiplicative_bias": round(random.uniform(0.0, 0.3), 4), "subgroup_coverage": round(random.uniform(0.6, 1.0), 4)},



    }



    detections = []



    for i in range(num_attributes):



        attr = random.choice(_PROTECTED_ATTRS_226)



        severity = random.choice(["low", "medium", "high", "critical"])



        severity_score = {"low": round(random.uniform(0.0, 0.25), 4), "medium": round(random.uniform(0.25, 0.5), 4), "high": round(random.uniform(0.5, 0.75), 4), "critical": round(random.uniform(0.75, 1.0), 4)}[severity]



        affected_paths = []



        for _ in range(random.randint(1, 4)):



            affected_paths.append({



                "source": f"node_{random.randint(1, 20)}",



                "target": f"node_{random.randint(1, 20)}",



                "edge_type": random.choice(["direct_causal", "indirect_causal", "spurious", "mediated", "confounded", "backdoor"]),



                "bias_contribution": round(random.uniform(0.01, severity_score), 4),



            })



        detections.append({



            "detection_id": f"detect_{i+1}",



            "protected_attribute": attr,



            "severity": severity,



            "severity_score": severity_score,



            "fairness_metric": random.choice(_FAIRNESS_METRICS_226),



            "violation_score": round(random.uniform(0.0 if severity == "low" else 0.3, 1.0 if severity == "critical" else 0.7), 4),



            "affected_paths": affected_paths,



            "affected_layers": random.randint(1, num_layers),



            "remediation_priority": round(random.uniform(0.3, 1.0), 4),



            "evidence_nodes": [f"node_{random.randint(1, 30)}" for _ in range(random.randint(2, 8))],



        })



    severity_dist = {s: sum(1 for d in detections if d["severity"] == s) for s in ["low", "medium", "high", "critical"]}



    avg_violation = round(sum(d["violation_score"] for d in detections) / max(len(detections), 1), 4)



    return {



        "graph_id": graph_id,



        "method": method,



        "num_detections": len(detections),



        "sensitivity": sensitivity,



        "num_layers_analyzed": num_layers,



        "detections": detections,



        "method_metrics": method_metrics.get(method, {}),



        "severity_distribution": severity_dist,



        "average_violation_score": avg_violation,



        "fairness_overview": {



            "total_violations": len(detections),



            "critical_count": severity_dist.get("critical", 0),



            "high_count": severity_dist.get("high", 0),



            "protected_attributes_flagged": len(set(d["protected_attribute"] for d in detections)),



            "overall_fairness_score": round(1.0 - avg_violation, 4),



        },



        "analysis_coverage": round(random.uniform(0.7, 0.98), 4),



    }











def _compute_counterfactual_fairness(



    graph_id: str, fairness_type: str, num_individuals: int, num_interventions: int, depth: int



) -> dict:



    """Analyze counterfactual fairness across protected attribute interventions."""



    random.seed(hash(graph_id) + hash(fairness_type) + hash("cf_counterfactual"))



    type_metrics = {



        "individual": {"consistency_rate": round(random.uniform(0.7, 0.98), 4), "max_individual_disparity": round(random.uniform(0.0, 0.2), 4), "violation_count": random.randint(0, num_individuals // 3)},



        "group": {"group_disparity": round(random.uniform(0.0, 0.3), 4), "between_group_variance": round(random.uniform(0.01, 0.15), 4), "advantage_ratio": round(random.uniform(0.8, 1.2), 4)},



        "path_specific": {"path_effect_ratio": round(random.uniform(0.7, 1.0), 4), "discriminatory_path_strength": round(random.uniform(0.0, 0.3), 4), "mediated_fairness": round(random.uniform(0.6, 0.95), 4)},



        "mediation_fair": {"mediation_bias": round(random.uniform(0.0, 0.25), 4), "fair_mediator_ratio": round(random.uniform(0.7, 0.98), 4), "unfair_mediator_count": random.randint(0, 4)},



        "total_effect": {"total_effect_fairness": round(random.uniform(0.6, 0.95), 4), "ate_disparity": round(random.uniform(0.0, 0.2), 4), "effect_homogeneity": round(random.uniform(0.7, 0.98), 4)},



        "direct_indirect": {"direct_effect_balance": round(random.uniform(0.6, 0.95), 4), "indirect_effect_ratio": round(random.uniform(0.1, 0.5), 4), "decomposition_clarity": round(random.uniform(0.7, 0.98), 4)},



    }



    analyses = []



    for i in range(num_individuals):



        protected_val = random.choice(["A", "B", "C"])



        counterfactual_val = random.choice([v for v in ["A", "B", "C"] if v != protected_val])



        original_outcome = round(random.uniform(0.1, 0.9), 4)



        counterfactual_outcome = round(random.uniform(max(0.05, original_outcome - 0.2), min(0.95, original_outcome + 0.2)), 4)



        outcome_shift = round(abs(counterfactual_outcome - original_outcome), 4)



        intervention_paths = []



        for j in range(num_interventions):



            intervention_paths.append({



                "intervention_id": f"intv_{i+1}_{j+1}",



                "attribute_changed": random.choice(_PROTECTED_ATTRS_226),



                "original_value": protected_val,



                "counterfactual_value": counterfactual_val,



                "path_length": random.randint(1, depth),



                "effect_magnitude": round(random.uniform(0.0, outcome_shift), 4),



                "path_nodes": [f"node_{random.randint(1, 25)}" for _ in range(random.randint(2, depth + 1))],



                "is_discriminatory": outcome_shift > 0.1,



            })



        analyses.append({



            "analysis_id": f"cf_analysis_{i+1}",



            "individual_id": f"ind_{i+1}",



            "protected_attribute": random.choice(_PROTECTED_ATTRS_226),



            "original_value": protected_val,



            "counterfactual_value": counterfactual_val,



            "original_outcome": original_outcome,



            "counterfactual_outcome": counterfactual_outcome,



            "outcome_shift": outcome_shift,



            "fairness_score": round(1.0 - min(outcome_shift * 2, 1.0), 4),



            "is_fair": outcome_shift < sensitivity * 0.3,



            "intervention_paths": intervention_paths,



            "depth_analyzed": depth,



            "confidence": round(random.uniform(0.7, 0.98), 4),



        })



    avg_fairness = round(sum(a["fairness_score"] for a in analyses) / max(len(analyses), 1), 4)



    unfair_count = sum(1 for a in analyses if not a["is_fair"])



    return {



        "graph_id": graph_id,



        "fairness_type": fairness_type,



        "num_analyses": len(analyses),



        "num_interventions": num_interventions,



        "depth": depth,



        "analyses": analyses,



        "type_metrics": type_metrics.get(fairness_type, {}),



        "aggregate_fairness": {



            "average_fairness_score": avg_fairness,



            "unfair_individuals": unfair_count,



            "fairness_rate": round(1.0 - unfair_count / max(len(analyses), 1), 4),



            "max_disparity": round(max((a["outcome_shift"] for a in analyses), default=0.0), 4),



            "avg_outcome_shift": round(sum(a["outcome_shift"] for a in analyses) / max(len(analyses), 1), 4),



        },



        "protected_attributes_analyzed": len(set(a["protected_attribute"] for a in analyses)),



    }











def _compute_causal_decomposition(



    graph_id: str, mode: str, num_paths: int, granularity: float, num_protected: int



) -> dict:



    """Decompose causal effects through protected attribute pathways."""



    random.seed(hash(graph_id) + hash(mode) + hash("cf_decompose"))



    mode_metrics = {



        "direct_effect": {"direct_coefficient": round(random.uniform(-0.2, 0.2), 4), "direct_significance": round(random.uniform(0.01, 0.1), 4), "direct_proportion": round(random.uniform(0.2, 0.6), 4)},



        "indirect_effect": {"indirect_coefficient": round(random.uniform(-0.15, 0.15), 4), "mediator_count": random.randint(1, 5), "indirect_proportion": round(random.uniform(0.15, 0.5), 4)},



        "spurious_path": {"spurious_ratio": round(random.uniform(0.0, 0.3), 4), "confounding_strength": round(random.uniform(0.1, 0.6), 4), "non_causal_correlation": round(random.uniform(0.0, 0.25), 4)},



        "mediator_analysis": {"mediation_proportion": round(random.uniform(0.2, 0.7), 4), "significant_mediators": random.randint(1, 4), "partial_mediation_rate": round(random.uniform(0.3, 0.8), 4)},



        "confounding_path": {"confounding_bias": round(random.uniform(0.0, 0.3), 4), "unmeasured_confounding": round(random.uniform(0.0, 0.2), 4), "sensitivity_parameter": round(random.uniform(0.5, 2.0), 4)},



        "backdoor_adjustment": {"adjustment_quality": round(random.uniform(0.7, 0.98), 4), "backdoor_criterion_met": random.choice([True, True, False]), "adjustment_set_size": random.randint(2, 8)},



    }



    paths = []



    for i in range(num_paths):



        protected_attr = random.choice(_PROTECTED_ATTRS_226[:num_protected])



        path_type = random.choice(["direct", "indirect", "spurious", "mediated", "confounded", "backdoor"])



        effect_magnitude = round(random.uniform(0.01, 0.4), 4)



        nodes_in_path = [f"node_{random.randint(1, 25)}" for _ in range(random.randint(2, 6))]



        fair_contribution = round(random.uniform(0.0, effect_magnitude), 4)



        unfair_contribution = round(effect_magnitude - fair_contribution, 4)



        paths.append({



            "path_id": f"path_{i+1}",



            "protected_attribute": protected_attr,



            "path_type": path_type,



            "source_node": nodes_in_path[0],



            "target_node": nodes_in_path[-1],



            "intermediate_nodes": nodes_in_path[1:-1],



            "total_effect": effect_magnitude,



            "fair_contribution": fair_contribution,



            "unfair_contribution": unfair_contribution,



            "fairness_ratio": round(fair_contribution / max(effect_magnitude, 0.001), 4),



            "granularity": granularity,



            "confidence": round(random.uniform(0.6, 0.98), 4),



            "is_adjustable": random.choice([True, True, False]),



            "adjustment_method": random.choice(["reweighting", "blocking", "stratification", "matching", "regression", "ipw"]),



        })



    total_unfair = sum(p["unfair_contribution"] for p in paths)



    total_effect = sum(p["total_effect"] for p in paths)



    return {



        "graph_id": graph_id,



        "mode": mode,



        "num_paths": len(paths),



        "granularity": granularity,



        "num_protected_attributes": num_protected,



        "paths": paths,



        "mode_metrics": mode_metrics.get(mode, {}),



        "decomposition_summary": {



            "total_effect": round(total_effect, 4),



            "total_fair_contribution": round(total_effect - total_unfair, 4),



            "total_unfair_contribution": round(total_unfair, 4),



            "fairness_ratio": round(1.0 - total_unfair / max(total_effect, 0.001), 4),



            "adjustable_paths": sum(1 for p in paths if p["is_adjustable"]),



            "path_type_distribution": {pt: sum(1 for p in paths if p["path_type"] == pt) for pt in ["direct", "indirect", "spurious", "mediated", "confounded", "backdoor"]},



        },



    }











def _compute_fairness_intervention(



    graph_id: str, intervention_type: str, num_interventions: int, target_fairness: float, budget: float



) -> dict:



    """Design fairness interventions for causal graph correction."""



    random.seed(hash(graph_id) + hash(intervention_type) + hash("cf_intervene"))



    type_metrics = {



        "preprocessing": {"reweighing_ratio": round(random.uniform(0.8, 1.2), 4), "data_balance_score": round(random.uniform(0.7, 0.98), 4), "distribution_shift": round(random.uniform(0.0, 0.15), 4)},



        "inprocessing": {"constraint_satisfaction": round(random.uniform(0.8, 0.99), 4), "accuracy_fairness_tradeoff": round(random.uniform(0.6, 0.95), 4), "convergence_rate": round(random.uniform(0.7, 0.98), 4)},



        "postprocessing": {"threshold_balance": round(random.uniform(0.7, 0.98), 4), "calibration_improvement": round(random.uniform(0.1, 0.4), 4), "reject_option_quality": round(random.uniform(0.6, 0.95), 4)},



        "causal_repair": {"repair_fidelity": round(random.uniform(0.7, 0.98), 4), "structural_preservation": round(random.uniform(0.8, 0.99), 4), "causal_validity": round(random.uniform(0.75, 0.98), 4)},



        "path_blocking": {"blocking_effectiveness": round(random.uniform(0.6, 0.95), 4), "collateral_impact": round(random.uniform(0.0, 0.2), 4), "path_coverage": round(random.uniform(0.7, 0.98), 4)},



        "counterfactual_augmentation": {"augmentation_quality": round(random.uniform(0.7, 0.98), 4), "distributional_fidelity": round(random.uniform(0.75, 0.98), 4), "sample_efficiency": round(random.uniform(0.6, 0.95), 4)},



    }



    interventions = []



    for i in range(num_interventions):



        protected_attr = random.choice(_PROTECTED_ATTRS_226)



        current_fairness = round(random.uniform(0.4, target_fairness - 0.05), 4)



        projected_fairness = round(min(current_fairness + random.uniform(0.05, 0.3), 1.0), 4)



        improvement = round(projected_fairness - current_fairness, 4)



        cost = round(random.uniform(0.01, budget / max(num_interventions, 1)), 4)



        affected_components = []



        for _ in range(random.randint(1, 5)):



            affected_components.append({



                "component_type": random.choice(["node", "edge", "path", "subgraph", "layer", "attribute"]),



                "component_id": f"comp_{random.randint(1, 20)}",



                "change_magnitude": round(random.uniform(0.01, improvement), 4),



                "reversibility": random.choice(["full", "partial", "irreversible"]),



            })



        interventions.append({



            "intervention_id": f"fair_intv_{i+1}",



            "intervention_type": intervention_type,



            "protected_attribute": protected_attr,



            "target_metric": random.choice(_FAIRNESS_METRICS_226),



            "current_fairness": current_fairness,



            "projected_fairness": projected_fairness,



            "improvement": improvement,



            "cost": cost,



            "priority": round(random.uniform(0.3, 1.0), 4),



            "status": random.choice(_INTERVENTION_STATUS_226),



            "affected_components": affected_components,



            "risk_level": random.choice(["low", "medium", "high"]),



            "utility_preservation": round(random.uniform(0.7, 0.98), 4),



            "side_effects": [random.choice(["accuracy_drop", "coverage_change", "distribution_shift", "new_bias_risk", "calibration_change"]) for _ in range(random.randint(0, 2))],



        })



    total_improvement = sum(iv["improvement"] for iv in interventions)



    total_cost = sum(iv["cost"] for iv in interventions)



    return {



        "graph_id": graph_id,



        "intervention_type": intervention_type,



        "num_interventions": len(interventions),



        "target_fairness": target_fairness,



        "budget": budget,



        "interventions": interventions,



        "type_metrics": type_metrics.get(intervention_type, {}),



        "intervention_summary": {



            "total_improvement": round(total_improvement, 4),



            "total_cost": round(total_cost, 4),



            "cost_effectiveness": round(total_improvement / max(total_cost, 0.001), 4),



            "applied_count": sum(1 for iv in interventions if iv["status"] == "applied"),



            "pending_count": sum(1 for iv in interventions if iv["status"] == "pending"),



            "avg_utility_preservation": round(sum(iv["utility_preservation"] for iv in interventions) / max(len(interventions), 1), 4),



        },



    }











def _compute_bias_propagation(



    graph_id: str, method: str, num_hops: int, sensitivity_threshold: float, num_sources: int



) -> dict:



    """Track bias propagation through causal graph structures."""



    random.seed(hash(graph_id) + hash(method) + hash("cf_propagate"))



    method_metrics = {



        "forward_pass": {"bias_accumulation": round(random.uniform(0.1, 0.5), 4), "amplification_factor": round(random.uniform(1.0, 2.5), 4), "attenuation_rate": round(random.uniform(0.1, 0.5), 4)},



        "backward_trace": {"attribution_accuracy": round(random.uniform(0.7, 0.98), 4), "trace_depth_reached": random.randint(2, num_hops), "source_coverage": round(random.uniform(0.6, 0.95), 4)},



        "path_analysis": {"path_strength": round(random.uniform(0.3, 0.9), 4), "critical_path_count": random.randint(1, 5), "bottleneck_nodes": random.randint(1, 4)},



        "node_influence": {"influence_score": round(random.uniform(0.2, 0.8), 4), "sensitive_node_count": random.randint(2, 8), "influence_entropy": round(random.uniform(0.5, 2.0), 4)},



        "gradient_flow": {"gradient_magnitude": round(random.uniform(0.01, 0.5), 4), "vanishing_ratio": round(random.uniform(0.0, 0.3), 4), "exploding_ratio": round(random.uniform(0.0, 0.2), 4)},



        "message_distortion": {"distortion_rate": round(random.uniform(0.0, 0.3), 4), "fidelity_score": round(random.uniform(0.6, 0.98), 4), "distortion_accumulation": round(random.uniform(0.0, 0.25), 4)},



    }



    sources = []



    for i in range(num_sources):



        attr = random.choice(_PROTECTED_ATTRS_226)



        initial_bias = round(random.uniform(0.1, 0.6), 4)



        propagation_trace = []



        accumulated_bias = initial_bias



        for hop in range(num_hops):



            delta = round(random.uniform(-0.05, 0.15), 4)



            accumulated_bias = round(min(max(accumulated_bias + delta, 0.0), 1.0), 4)



            propagation_trace.append({



                "hop": hop + 1,



                "node_id": f"node_{random.randint(1, 30)}",



                "bias_level": accumulated_bias,



                "bias_delta": delta,



                "contribution_sources": [f"node_{random.randint(1, 30)}" for _ in range(random.randint(1, 3))],



                "activation_threshold": round(random.uniform(0.2, 0.8), 4),



                "exceeds_threshold": accumulated_bias > sensitivity_threshold,



            })



        sources.append({



            "source_id": f"bias_src_{i+1}",



            "protected_attribute": attr,



            "source_node": f"node_{random.randint(1, 20)}",



            "initial_bias": initial_bias,



            "final_bias": accumulated_bias,



            "bias_amplification": round(accumulated_bias / max(initial_bias, 0.001), 4),



            "propagation_trace": propagation_trace,



            "num_hops": num_hops,



            "critical_nodes": [t["node_id"] for t in propagation_trace if t["exceeds_threshold"]],



            "max_bias_reached": round(max(t["bias_level"] for t in propagation_trace), 4),



        })



    overall_bias = round(sum(s["final_bias"] for s in sources) / max(len(sources), 1), 4)



    return {



        "graph_id": graph_id,



        "method": method,



        "num_hops": num_hops,



        "sensitivity_threshold": sensitivity_threshold,



        "num_sources": len(sources),



        "sources": sources,



        "method_metrics": method_metrics.get(method, {}),



        "propagation_summary": {



            "overall_bias_level": overall_bias,



            "max_amplification": round(max(s["bias_amplification"] for s in sources), 4) if sources else 0.0,



            "critical_nodes_total": sum(len(s["critical_nodes"]) for s in sources),



            "sources_above_threshold": sum(1 for s in sources if s["final_bias"] > sensitivity_threshold),



            "avg_propagation_distance": round(sum(s["num_hops"] for s in sources) / max(len(sources), 1), 2),



        },



    }











def _compute_fairness_certification(



    graph_id: str, certification_type: str, num_claims: int, confidence_level: float, rigor: float



) -> dict:



    """Provide formal fairness certifications with mathematical guarantees."""



    random.seed(hash(graph_id) + hash(certification_type) + hash("cf_certify"))



    type_metrics = {



        "statistical_guarantee": {"confidence_interval": round(confidence_level, 4), "sample_size_required": random.randint(500, 10000), "power_analysis": round(random.uniform(0.7, 0.99), 4)},



        "individual_bound": {"individual_guarantee_bound": round(random.uniform(0.01, 0.1), 4), "worst_case_disparity": round(random.uniform(0.0, 0.15), 4), "coverage_probability": round(random.uniform(0.9, 0.99), 4)},



        "group_margin": {"group_margin_bound": round(random.uniform(0.0, 0.1), 4), "protected_group_count": random.randint(2, 6), "worst_group_gap": round(random.uniform(0.0, 0.12), 4)},



        "causal_certificate": {"causal_guarantee_strength": round(random.uniform(0.7, 0.98), 4), "identifiability_condition": random.choice(["backdoor", "frontdoor", "instrumental", "marginal", "conditional", "none"]), "sensitivity_robustness": round(random.uniform(0.6, 0.95), 4)},



        "intersectional_cover": {"intersectional_coverage": round(random.uniform(0.7, 0.98), 4), "subgroup_certified": random.randint(3, 12), "worst_intersectional_gap": round(random.uniform(0.0, 0.15), 4)},



        "robustness_cert": {"robustness_radius": round(random.uniform(0.05, 0.3), 4), "adversarial_fairness": round(random.uniform(0.7, 0.98), 4), "perturbation_stability": round(random.uniform(0.8, 0.99), 4)},



    }



    claims = []



    for i in range(num_claims):



        claim_type = random.choice(["parity", "equal_opportunity", "calibration", "counterfactual", "individual", "intersectional"])



        is_certified = random.random() < rigor



        claim_rigor = round(random.uniform(0.5, rigor), 4)



        guarantee_strength = round(random.uniform(0.6, 0.99), 4) if is_certified else round(random.uniform(0.2, 0.6), 4)



        evidence_chain = []



        for j in range(random.randint(2, 5)):



            evidence_chain.append({



                "evidence_id": f"evidence_{i+1}_{j+1}",



                "evidence_type": random.choice(["statistical_test", "causal_bound", "empirical_measurement", "formal_proof", "simulation", "counterfactual_analysis"]),



                "supports_claim": random.choice([True, True, True, False]),



                "strength": round(random.uniform(0.5, 0.99), 4),



                "source": random.choice(["v1.225_proof", "v1.224_multimodal", "v1.222_contrastive", "v1.220_counterfactual", "v1.219_temporal", "empirical_data"]),



            })



        claims.append({



            "claim_id": f"claim_{i+1}",



            "claim_type": claim_type,



            "protected_attribute": random.choice(_PROTECTED_ATTRS_226),



            "assertion": f"Fairness guarantee for {claim_type} across protected groups",



            "is_certified": is_certified,



            "guarantee_strength": guarantee_strength,



            "rigor_level": claim_rigor,



            "confidence_level": confidence_level,



            "evidence_chain": evidence_chain,



            "evidence_support_ratio": round(sum(1 for e in evidence_chain if e["supports_claim"]) / max(len(evidence_chain), 1), 4),



            "certification_status": "certified" if is_certified else "conditional" if guarantee_strength > 0.5 else "denied",



            "validity_period": random.choice(["ephemeral", "session", "persistent", "versioned", "permanent", "conditional"]),



            "assumptions": [f"assumption_{random.randint(1, 10)}" for _ in range(random.randint(1, 4))],



        })



    certified_count = sum(1 for c in claims if c["is_certified"])



    return {



        "graph_id": graph_id,



        "certification_type": certification_type,



        "num_claims": len(claims),



        "confidence_level": confidence_level,



        "rigor": rigor,



        "claims": claims,



        "type_metrics": type_metrics.get(certification_type, {}),



        "certification_summary": {



            "total_claims": len(claims),



            "certified_claims": certified_count,



            "conditional_claims": sum(1 for c in claims if c["certification_status"] == "conditional"),



            "denied_claims": sum(1 for c in claims if c["certification_status"] == "denied"),



            "certification_rate": round(certified_count / max(len(claims), 1), 4),



            "avg_guarantee_strength": round(sum(c["guarantee_strength"] for c in claims) / max(len(claims), 1), 4),



            "strongest_guarantee": round(max(c["guarantee_strength"] for c in claims), 4) if claims else 0.0,



        },



        "overall_fairness_grade": random.choice(["A", "A-", "B+", "B", "B-", "C+"]),



    }











