# In-memory caches for v1.227



_ar_attack_cache: dict = {}



_ar_defense_cache: dict = {}



_ar_robustness_cache: dict = {}



_ar_detection_cache: dict = {}



_ar_certification_cache: dict = {}



_ar_summary_cache: dict = {}







_ATTACK_TYPES_227 = ["node_injection", "edge_perturbation", "feature_poisoning", "causal_masking", "gradient_leakage", "structure_corruption"]



_DEFENSE_STRATEGIES_227 = ["adversarial_training", "causal_certification", "robust_aggregation", "structure_purification", "gradient_clipping", "causal_invariant"]



_THREAT_LEVELS_227 = ["benign", "low", "medium", "high", "critical", "catastrophic"]











def _compute_adversarial_attack(



    graph_id: str, attack_type: str, num_attacks: int, attack_strength: float, num_layers: int



) -> dict:



    """Simulate adversarial attacks on causal graph models."""



    random.seed(hash(graph_id) + hash(attack_type) + hash("ar_attack"))



    type_metrics = {



        "node_injection": {"injection_success_rate": round(random.uniform(0.3, 0.8), 4), "causal_disruption_score": round(random.uniform(0.2, 0.7), 4), "detection_evasion": round(random.uniform(0.4, 0.9), 4)},



        "edge_perturbation": {"perturbation_impact": round(random.uniform(0.15, 0.6), 4), "causal_flow_disruption": round(random.uniform(0.2, 0.65), 4), "recovery_difficulty": round(random.uniform(0.3, 0.85), 4)},



        "feature_poisoning": {"poisoning_effectiveness": round(random.uniform(0.25, 0.75), 4), "feature_contamination_rate": round(random.uniform(0.1, 0.5), 4), "causal_bias_amplification": round(random.uniform(0.15, 0.6), 4)},



        "causal_masking": {"masking_success_rate": round(random.uniform(0.3, 0.85), 4), "hidden_causal_paths": random.randint(2, 12), "detection_difficulty": round(random.uniform(0.5, 0.95), 4)},



        "gradient_leakage": {"information_leaked": round(random.uniform(0.1, 0.6), 4), "causal_structure_exposure": round(random.uniform(0.2, 0.7), 4), "privacy_violation_score": round(random.uniform(0.3, 0.8), 4)},



        "structure_corruption": {"structure_damage_score": round(random.uniform(0.3, 0.85), 4), "causal_integrity_loss": round(random.uniform(0.25, 0.75), 4), "reconstruction_impossibility": round(random.uniform(0.2, 0.7), 4)},



    }



    attacks = []



    for i in range(num_attacks):



        threat_level = random.choice(_THREAT_LEVELS_227)



        severity_map = {"benign": 0.05, "low": 0.2, "medium": 0.45, "high": 0.7, "critical": 0.85, "catastrophic": 0.95}



        severity_score = round(random.uniform(severity_map[threat_level] - 0.1, severity_map[threat_level] + 0.05), 4)



        severity_score = max(0.0, min(1.0, severity_score))



        target_nodes = [f"node_{random.randint(1, 30)}" for _ in range(random.randint(1, 6))]



        attack_vectors = []



        for _ in range(random.randint(1, 4)):



            attack_vectors.append({



                "vector_type": random.choice(["add_edge", "remove_edge", "modify_feature", "inject_node", "flip_label", "mask_path"]),



                "target_component": random.choice(["node", "edge", "feature", "causal_path", "intervention", "counterfactual"]),



                "perturbation_magnitude": round(random.uniform(0.01, attack_strength), 4),



                "causal_impact": round(random.uniform(0.05, severity_score), 4),



            })



        attacks.append({



            "attack_id": f"atk_{i+1}",



            "attack_type": attack_type,



            "threat_level": threat_level,



            "severity_score": severity_score,



            "attack_strength": round(attack_strength * random.uniform(0.5, 1.5), 4),



            "target_nodes": target_nodes,



            "affected_layers": random.randint(1, num_layers),



            "attack_vectors": attack_vectors,



            "causal_disruption": round(random.uniform(0.1, severity_score * 0.9), 4),



            "stealth_score": round(random.uniform(0.3, 0.95), 4),



            "detection_difficulty": round(random.uniform(0.2, 0.9), 4),



        })



    threat_dist = {t: sum(1 for a in attacks if a["threat_level"] == t) for t in _THREAT_LEVELS_227}



    avg_severity = round(sum(a["severity_score"] for a in attacks) / max(len(attacks), 1), 4)



    return {



        "graph_id": graph_id,



        "attack_type": attack_type,



        "num_attacks": len(attacks),



        "attack_strength": attack_strength,



        "num_layers_targeted": num_layers,



        "attacks": attacks,



        "type_metrics": type_metrics.get(attack_type, {}),



        "threat_distribution": threat_dist,



        "average_severity": avg_severity,



        "attack_overview": {



            "total_attacks": len(attacks),



            "critical_count": threat_dist.get("critical", 0) + threat_dist.get("catastrophic", 0),



            "high_count": threat_dist.get("high", 0),



            "most_targeted_nodes": list(set(n for a in attacks for n in a["target_nodes"]))[:5],



            "overall_vulnerability_score": round(avg_severity * attack_strength, 4),



        },



        "causal_impact_summary": {



            "avg_causal_disruption": round(sum(a["causal_disruption"] for a in attacks) / max(len(attacks), 1), 4),



            "max_causal_disruption": round(max(a["causal_disruption"] for a in attacks), 4) if attacks else 0.0,



            "causal_paths_affected": random.randint(3, 20),



        },



    }











def _compute_causal_defense(



    graph_id: str, defense_strategy: str, num_defenses: int, protection_level: float, robustness_target: float



) -> dict:



    """Design and evaluate defense strategies for causal graph models."""



    random.seed(hash(graph_id) + hash(defense_strategy) + hash("ar_defense"))



    strategy_metrics = {



        "adversarial_training": {"robustness_gain": round(random.uniform(0.15, 0.45), 4), "clean_accuracy_retention": round(random.uniform(0.85, 0.98), 4), "training_overhead": round(random.uniform(1.5, 4.0), 2)},



        "causal_certification": {"certification_rate": round(random.uniform(0.7, 0.95), 4), "certificate Tightness": round(random.uniform(0.6, 0.9), 4), "false_positive_rate": round(random.uniform(0.02, 0.15), 4)},



        "robust_aggregation": {"aggregation_robustness": round(random.uniform(0.75, 0.95), 4), "noise_resilience": round(random.uniform(0.7, 0.92), 4), "performance_overhead": round(random.uniform(1.1, 1.8), 2)},



        "structure_purification": {"purification_accuracy": round(random.uniform(0.8, 0.97), 4), "false_edge_removal": round(random.uniform(0.02, 0.12), 4), "causal_preservation": round(random.uniform(0.85, 0.98), 4)},



        "gradient_clipping": {"leakage_reduction": round(random.uniform(0.6, 0.92), 4), "gradient_norm_control": round(random.uniform(0.3, 0.7), 4), "convergence_impact": round(random.uniform(0.95, 1.05), 4)},



        "causal_invariant": {"invariance_achieved": round(random.uniform(0.7, 0.95), 4), "distribution_shift_resistance": round(random.uniform(0.65, 0.9), 4), "generalization_gap": round(random.uniform(0.02, 0.1), 4)},



    }



    defenses = []



    for i in range(num_defenses):



        protected_components = random.sample(["nodes", "edges", "features", "causal_paths", "interventions", "counterfactuals"], k=random.randint(2, 5))



        attack_resistance = {}



        for at in _ATTACK_TYPES_227:



            attack_resistance[at] = round(random.uniform(protection_level * 0.6, protection_level * 1.1), 4)



        defenses.append({



            "defense_id": f"def_{i+1}",



            "defense_strategy": defense_strategy,



            "protection_level": round(protection_level * random.uniform(0.8, 1.2), 4),



            "protected_components": protected_components,



            "robustness_improvement": round(random.uniform(0.1, 0.4), 4),



            "attack_resistance_profile": attack_resistance,



            "computational_cost": round(random.uniform(0.05, 0.3), 4),



            "latency_overhead_ms": round(random.uniform(5, 50), 1),



            "effectiveness_score": round(random.uniform(protection_level * 0.7, min(1.0, protection_level * 1.15)), 4),



            "coverage_score": round(random.uniform(0.6, 0.95), 4),



        })



    avg_effectiveness = round(sum(d["effectiveness_score"] for d in defenses) / max(len(defenses), 1), 4)



    return {



        "graph_id": graph_id,



        "defense_strategy": defense_strategy,



        "num_defenses": len(defenses),



        "protection_level": protection_level,



        "robustness_target": robustness_target,



        "defenses": defenses,



        "strategy_metrics": strategy_metrics.get(defense_strategy, {}),



        "defense_overview": {



            "total_defenses": len(defenses),



            "avg_effectiveness": avg_effectiveness,



            "best_defense_id": max(defenses, key=lambda d: d["effectiveness_score"])["defense_id"] if defenses else None,



            "target_met": avg_effectiveness >= robustness_target,



            "overall_protection_score": round(avg_effectiveness * protection_level, 4),



        },



        "robustness_profile": {



            "weakest_attack_vector": min(attack_resistance, key=attack_resistance.get) if defenses else None,



            "strongest_attack_vector": max(attack_resistance, key=attack_resistance.get) if defenses else None,



            "avg_attack_resistance": round(sum(v for r in [d["attack_resistance_profile"] for d in defenses] for v in r.values()) / max(sum(len(r) for r in [d["attack_resistance_profile"] for d in defenses]), 1), 4),



        },



    }











def _compute_robustness_evaluation(



    graph_id: str, metric_type: str, num_evaluations: int, perturbation_budget: float, num_layers: int



) -> dict:



    """Evaluate adversarial robustness of causal graph models."""



    random.seed(hash(graph_id) + hash(metric_type) + hash("ar_robustness"))



    metric_results = {



        "certified_radius": {"avg_radius": round(random.uniform(0.1, 0.6), 4), "min_radius": round(random.uniform(0.02, 0.2), 4), "max_radius": round(random.uniform(0.5, 0.95), 4)},



        "perturbation_stability": {"stability_index": round(random.uniform(0.6, 0.95), 4), "perturbation_sensitivity": round(random.uniform(0.05, 0.35), 4), "output_variance": round(random.uniform(0.01, 0.15), 4)},



        "causal_consistency": {"consistency_rate": round(random.uniform(0.7, 0.98), 4), "causal_preservation": round(random.uniform(0.75, 0.97), 4), "structure_stability": round(random.uniform(0.65, 0.95), 4)},



        "attack_success_rate": {"asr": round(random.uniform(0.05, 0.4), 4), "targeted_asr": round(random.uniform(0.1, 0.5), 4), "untargeted_asr": round(random.uniform(0.03, 0.3), 4)},



        "robustness_accuracy": {"clean_accuracy": round(random.uniform(0.85, 0.99), 4), "robust_accuracy": round(random.uniform(0.7, 0.95), 4), "accuracy_gap": round(random.uniform(0.05, 0.2), 4)},



        "invariance_score": {"avg_invariance": round(random.uniform(0.7, 0.96), 4), "worst_case_invariance": round(random.uniform(0.5, 0.85), 4), "distribution_stability": round(random.uniform(0.65, 0.93), 4)},



    }



    evaluations = []



    for i in range(num_evaluations):



        perturbation_types = random.sample(["node_feature", "edge_weight", "graph_structure", "label_noise", "attribute_mask", "path_disruption"], k=random.randint(2, 5))



        evaluations.append({



            "evaluation_id": f"eval_{i+1}",



            "metric_type": metric_type,



            "perturbation_budget": round(perturbation_budget * random.uniform(0.5, 1.5), 4),



            "perturbation_types": perturbation_types,



            "robustness_score": round(random.uniform(0.5, 0.98), 4),



            "layers_evaluated": random.randint(1, num_layers),



            "causal_stability": round(random.uniform(0.6, 0.97), 4),



            "output_deviation": round(random.uniform(0.01, 0.25), 4),



            "recovery_rate": round(random.uniform(0.7, 0.99), 4),



            "vulnerable_paths": random.randint(0, 8),



            "defense_effectiveness": round(random.uniform(0.6, 0.95), 4),



        })



    avg_robustness = round(sum(e["robustness_score"] for e in evaluations) / max(len(evaluations), 1), 4)



    return {



        "graph_id": graph_id,



        "metric_type": metric_type,



        "num_evaluations": len(evaluations),



        "perturbation_budget": perturbation_budget,



        "evaluations": evaluations,



        "metric_results": metric_results.get(metric_type, {}),



        "robustness_overview": {



            "avg_robustness_score": avg_robustness,



            "min_robustness_score": round(min(e["robustness_score"] for e in evaluations), 4) if evaluations else 0.0,



            "max_robustness_score": round(max(e["robustness_score"] for e in evaluations), 4) if evaluations else 0.0,



            "avg_causal_stability": round(sum(e["causal_stability"] for e in evaluations) / max(len(evaluations), 1), 4),



            "total_vulnerable_paths": sum(e["vulnerable_paths"] for e in evaluations),



        },



        "robustness_grade": "A" if avg_robustness >= 0.9 else "B" if avg_robustness >= 0.8 else "C" if avg_robustness >= 0.7 else "D" if avg_robustness >= 0.6 else "F",



    }











def _compute_adversarial_detection(



    graph_id: str, detection_method: str, num_candidates: int, sensitivity: float, num_layers: int



) -> dict:



    """Detect adversarial attacks on causal graph models."""



    random.seed(hash(graph_id) + hash(detection_method) + hash("ar_detection"))



    method_metrics = {



        "anomaly_detection": {"detection_rate": round(random.uniform(0.7, 0.95), 4), "false_positive_rate": round(random.uniform(0.02, 0.15), 4), "anomaly_score_distribution": {"low": random.randint(5, 20), "medium": random.randint(3, 10), "high": random.randint(1, 5)}},



        "causal_consistency_check": {"consistency_violation_rate": round(random.uniform(0.05, 0.3), 4), "causal_anomaly_score": round(random.uniform(0.1, 0.5), 4), "recovery_confidence": round(random.uniform(0.7, 0.95), 4)},



        "distribution_shift": {"shift_magnitude": round(random.uniform(0.05, 0.4), 4), "kl_divergence": round(random.uniform(0.01, 0.25), 4), "ks_test_statistic": round(random.uniform(0.05, 0.35), 4)},



        "structural_analysis": {"structural_anomaly_rate": round(random.uniform(0.03, 0.2), 4), "graph_edit_distance": round(random.uniform(1, 15), 0), "topology_preservation": round(random.uniform(0.8, 0.98), 4)},



        "gradient_monitoring": {"gradient_anomaly_score": round(random.uniform(0.1, 0.45), 4), "norm_deviation": round(random.uniform(0.05, 0.3), 4), "direction_instability": round(random.uniform(0.05, 0.25), 4)},



        "adversarial_probing": {"probe_success_rate": round(random.uniform(0.6, 0.9), 4), "adversarial_confidence": round(random.uniform(0.7, 0.95), 4), "vulnerability_coverage": round(random.uniform(0.6, 0.92), 4)},



    }



    detections = []



    for i in range(num_candidates):



        is_adversarial = random.random() < sensitivity



        threat_type = random.choice(_ATTACK_TYPES_227) if is_adversarial else "none"



        detections.append({



            "detection_id": f"det_{i+1}",



            "is_adversarial": is_adversarial,



            "confidence": round(random.uniform(0.6, 0.99) if is_adversarial else random.uniform(0.1, 0.5), 4),



            "threat_type": threat_type,



            "affected_nodes": [f"node_{random.randint(1, 30)}" for _ in range(random.randint(1, 5))] if is_adversarial else [],



            "affected_layers": random.randint(1, num_layers) if is_adversarial else 0,



            "anomaly_score": round(random.uniform(0.5, 1.0) if is_adversarial else random.uniform(0.0, 0.3), 4),



            "causal_impact": round(random.uniform(0.2, 0.8) if is_adversarial else 0.0, 4),



            "recommended_action": random.choice(["block", "quarantine", "investigate", "monitor", "ignore"]) if is_adversarial else "none",



        })



    adversarial_count = sum(1 for d in detections if d["is_adversarial"])



    return {



        "graph_id": graph_id,



        "detection_method": detection_method,



        "num_candidates": num_candidates,



        "sensitivity": sensitivity,



        "detections": detections,



        "method_metrics": method_metrics.get(detection_method, {}),



        "detection_overview": {



            "total_scanned": len(detections),



            "adversarial_detected": adversarial_count,



            "detection_rate": round(adversarial_count / max(len(detections), 1), 4),



            "avg_confidence": round(sum(d["confidence"] for d in detections if d["is_adversarial"]) / max(adversarial_count, 1), 4),



            "threat_types_found": list(set(d["threat_type"] for d in detections if d["is_adversarial"])),



            "most_common_action": max(set(d["recommended_action"] for d in detections if d["is_adversarial"]), key=lambda a: sum(1 for d in detections if d["recommended_action"] == a)) if adversarial_count > 0 else "none",



        },



        "security_assessment": {



            "risk_level": "critical" if adversarial_count > num_candidates * 0.5 else "high" if adversarial_count > num_candidates * 0.3 else "medium" if adversarial_count > num_candidates * 0.1 else "low",



            "immediate_action_required": adversarial_count > num_candidates * 0.3,



            "recommended_sensitivity": round(min(1.0, sensitivity + 0.1), 2),



        },



    }











def _compute_robustness_certification(



    graph_id: str, certification_type: str, num_certificates: int, confidence_level: float, rigor: float



) -> dict:



    """Generate robustness certificates for causal graph models."""



    random.seed(hash(graph_id) + hash(certification_type) + hash("ar_cert"))



    cert_metrics = {



        "lipschitz_certificate": {"lipschitz_bound": round(random.uniform(0.5, 3.0), 4), "certificate_tightness": round(random.uniform(0.6, 0.95), 4), "bound_gap": round(random.uniform(0.05, 0.3), 4)},



        "randomized_smoothing": {"smoothing_sigma": round(random.uniform(0.1, 0.5), 4), "certified_accuracy": round(random.uniform(0.7, 0.93), 4), "radius_certificate": round(random.uniform(0.15, 0.6), 4)},



        "interval_bound": {"bound_width": round(random.uniform(0.05, 0.3), 4), "propagation_stability": round(random.uniform(0.75, 0.97), 4), "interval_accuracy": round(random.uniform(0.8, 0.96), 4)},



        "causal_shield": {"shield_coverage": round(random.uniform(0.7, 0.95), 4), "causal_protection_rate": round(random.uniform(0.75, 0.97), 4), "attack_mitigation": round(random.uniform(0.6, 0.92), 4)},



        "provable_defense": {"provability_score": round(random.uniform(0.8, 0.99), 4), "defense_guarantee": round(random.uniform(0.7, 0.95), 4), "assumption_validity": round(random.uniform(0.85, 0.99), 4)},



        "ensemble_certificate": {"ensemble_agreement": round(random.uniform(0.75, 0.95), 4), "diversity_score": round(random.uniform(0.6, 0.9), 4), "collective_certified_rate": round(random.uniform(0.7, 0.93), 4)},



    }



    certificates = []



    for i in range(num_certificates):



        status = random.choices(["certified", "conditional", "pending", "expired"], weights=[0.5, 0.25, 0.15, 0.1])[0]



        protected_causal_paths = [f"path_{random.randint(1, 15)}" for _ in range(random.randint(1, 6))]



        certificates.append({



            "certificate_id": f"cert_{i+1}",



            "certification_type": certification_type,



            "status": status,



            "confidence_level": round(confidence_level * random.uniform(0.9, 1.0), 4),



            "certified_radius": round(random.uniform(0.1, 0.8), 4),



            "protected_causal_paths": protected_causal_paths,



            "robustness_guarantee": round(random.uniform(0.7, 0.98), 4),



            "assumption_set": random.sample(["smoothness", "bounded_gradient", "causal_markov", "faithfulness", "sufficient_data", "no_hidden_confounder"], k=random.randint(2, 4)),



            "validity_period_hours": random.choice([1, 6, 12, 24, 72, 168]),



            "rigor_level": round(rigor * random.uniform(0.85, 1.0), 4),



            "attack_coverage": round(random.uniform(0.6, 0.95), 4),



        })



    certified_count = sum(1 for c in certificates if c["status"] == "certified")



    return {



        "graph_id": graph_id,



        "certification_type": certification_type,



        "num_certificates": len(certificates),



        "confidence_level": confidence_level,



        "rigor": rigor,



        "certificates": certificates,



        "cert_metrics": cert_metrics.get(certification_type, {}),



        "certification_overview": {



            "total_certificates": len(certificates),



            "certified_count": certified_count,



            "conditional_count": sum(1 for c in certificates if c["status"] == "conditional"),



            "certification_rate": round(certified_count / max(len(certificates), 1), 4),



            "avg_certified_radius": round(sum(c["certified_radius"] for c in certificates if c["status"] == "certified") / max(certified_count, 1), 4),



            "avg_robustness_guarantee": round(sum(c["robustness_guarantee"] for c in certificates) / max(len(certificates), 1), 4),



        },



        "security_posture": {



            "overall_certification_strength": "strong" if certified_count > num_certificates * 0.6 else "moderate" if certified_count > num_certificates * 0.3 else "weak",



            "weakest_assumption": random.choice(["smoothness", "bounded_gradient", "causal_markov", "faithfulness", "sufficient_data"]),



            "recommended_renewal": "immediate" if certified_count < num_certificates * 0.3 else "scheduled",



        },



    }











def _compute_adversarial_summary(



    graph_id: str, analysis_depth: int, coverage: float



) -> dict:



    """Generate comprehensive adversarial robustness summary for causal models."""



    random.seed(hash(graph_id) + hash("ar_summary"))



    attack_sim = _compute_adversarial_attack(graph_id, "edge_perturbation", 4, 0.5, analysis_depth)



    defense_sim = _compute_causal_defense(graph_id, "adversarial_training", 3, 0.8, 0.9)



    robustness_sim = _compute_robustness_evaluation(graph_id, "robustness_accuracy", 4, 0.3, analysis_depth)



    detection_sim = _compute_adversarial_detection(graph_id, "anomaly_detection", 6, 0.6, analysis_depth)



    cert_sim = _compute_robustness_certification(graph_id, "causal_shield", 4, 0.95, 0.8)



    return {



        "graph_id": graph_id,



        "analysis_depth": analysis_depth,



        "coverage": coverage,



        "attack_assessment": {



            "vulnerability_score": round(random.uniform(0.2, 0.6), 4),



            "critical_attack_vectors": random.sample(_ATTACK_TYPES_227, k=3),



            "most_damaging_attack": random.choice(_ATTACK_TYPES_227),



            "attack_surface_size": round(random.uniform(0.3, 0.7), 4),



        },



        "defense_assessment": {



            "defense_posture": random.choice(["strong", "moderate", "needs_improvement"]),



            "best_defense_strategy": random.choice(_DEFENSE_STRATEGIES_227),



            "coverage_gaps": random.sample(_ATTACK_TYPES_227, k=2),



            "defense_efficiency": round(random.uniform(0.6, 0.9), 4),



        },



        "robustness_summary": {



            "overall_robustness": round(random.uniform(0.6, 0.9), 4),



            "robustness_grade": random.choice(["A", "B", "B+", "C+"]),



            "weakest_metric": random.choice(["certified_radius", "perturbation_stability", "causal_consistency"]),



            "strongest_metric": random.choice(["robustness_accuracy", "invariance_score", "attack_success_rate"]),



        },



        "certification_status": {



            "certified_percentage": round(random.uniform(0.5, 0.9), 4),



            "pending_renewal": random.randint(1, 5),



            "strongest_certificate_type": random.choice(["lipschitz_certificate", "causal_shield", "provable_defense"]),



        },



        "recommendations": [



            {"priority": "high", "action": f"Strengthen defense against {random.choice(_ATTACK_TYPES_227)}", "effort": "medium"},



            {"priority": "medium", "action": f"Improve {random.choice(['certified_radius', 'perturbation_stability'])} metric", "effort": "high"},



            {"priority": "low", "action": "Schedule robustness recertification", "effort": "low"},



        ],



        "simulated_results": {



            "attack": attack_sim["attack_overview"],



            "defense": defense_sim["defense_overview"],



            "robustness": robustness_sim["robustness_overview"],



            "detection": detection_sim["detection_overview"],



            "certification": cert_sim["certification_overview"],



        },



    }











