"""



Graph Causal Uncertainty Quantification Engine — Uncertainty-aware causal reasoning.







Provides comprehensive uncertainty quantification for causal inference on graphs,



including quantification methods, uncertainty propagation, calibration assessment,



uncertainty decomposition, sensitivity auditing, and uncertainty reduction strategies.







Endpoints:



  POST /causal-uncertainty/uncertainty    — Causal uncertainty quantification



  POST /causal-uncertainty/propagation    — Uncertainty propagation analysis



  POST /causal-uncertainty/calibration    — Calibration assessment



  POST /causal-uncertainty/decomposition  — Uncertainty decomposition analysis



  POST /causal-uncertainty/sensitivity    — Sensitivity auditing



  POST /causal-uncertainty/reduction      — Uncertainty reduction strategy



  GET  /causal-uncertainty/overview       — Engine overview and integration status



"""











class UncertaintyQuantificationMethod(str, Enum):



    """Methods for causal uncertainty quantification."""



    BOOTSTRAP = "bootstrap"



    BAYESIAN_INFERENCE = "bayesian_inference"



    MONTE_CARLO_DROPOUT = "monte_carlo_dropout"



    ENSEMBLE_VARIANCE = "ensemble_variance"



    CONFORMAL_PREDICTION = "conformal_prediction"



    DEUP = "deup"











class UncertaintyPropagationMode(str, Enum):



    """Modes for uncertainty propagation through causal graph."""



    LINEAR_PROPAGATION = "linear_propagation"



    NONLINEAR_PROPAGATION = "nonlinear_propagation"



    BAYESIAN_NETWORK = "bayesian_network"



    MONTE_CARLO_SIMULATION = "monte_carlo_simulation"



    SENSITIVITY_BASED = "sensitivity_based"



    INTERVAL_ARITHMETIC = "interval_arithmetic"











class CalibrationMethod(str, Enum):



    """Methods for uncertainty calibration assessment."""



    PLATT_SCALING = "platt_scaling"



    ISOTONIC_REGRESSION = "isotonic_regression"



    BETA_CALIBRATION = "beta_calibration"



    TEMPERATURE_SCALING = "temperature_scaling"



    HISTOGRAM_BINNING = "histogram_binning"



    NATIVE_CALIBRATION = "native_calibration"











class UncertaintyDecompositionMethod(str, Enum):



    """Methods for uncertainty decomposition."""



    ALEATORIC_EPISTEMIC = "aleatoric_epistemic"



    TOTAL_UNCERTAINTY = "total_uncertainty"



    VARIANCE_DECOMPOSITION = "variance_decomposition"



    INFORMATION_THEORETIC = "information_theoretic"



    SPECTRAL_DECOMPOSITION = "spectral_decomposition"



    DEEP_ENSEMBLE_DECOMP = "deep_ensemble_decomp"











class SensitivityAuditDimension(str, Enum):



    """Dimensions for causal sensitivity auditing."""



    PARAMETER_SENSITIVITY = "parameter_sensitivity"



    STRUCTURE_SENSITIVITY = "structure_sensitivity"



    DATA_SENSITIVITY = "data_sensitivity"



    MODEL_SENSITIVITY = "model_sensitivity"



    TEMPORAL_SENSITIVITY = "temporal_sensitivity"



    CONTEXT_SENSITIVITY = "context_sensitivity"











class UncertaintyReductionStrategy(str, Enum):



    """Strategies for reducing causal uncertainty."""



    ACTIVE_LEARNING = "active_learning"



    DATA_AUGMENTATION = "data_augmentation"



    ENSEMBLE_EXPANSION = "ensemble_expansion"



    BAYESIAN_OPTIMIZATION = "bayesian_optimization"



    TRANSFER_LEARNING = "transfer_learning"



    META_LEARNING = "meta_learning"











