# ── v1.230 Compute Functions ────────────────────────────────────────







def _compute_causal_uncertainty(



    graph_id: str,



    method: UncertaintyQuantificationMethod,



    num_causal_effects: int,



    confidence_level: float,



) -> Dict[str, Any]:



    """Compute causal uncertainty quantification using specified method."""



    random.seed(hash(graph_id + method.value) % (2**31))



    method_cfg = _QUANTIFICATION_METHODS_230[method]



    effects = []



    for i in range(num_causal_effects):



        point_estimate = round(random.uniform(-2.0, 2.0), 4)



        std_error = round(random.uniform(0.05, 0.8), 4)



        margin = round(std_error * 1.96 * random.uniform(0.8, 1.2), 4)



        effects.append({



            "effect_id": f"causal_effect_{i + 1}",



            "point_estimate": point_estimate,



            "standard_error": std_error,



            "confidence_interval": {



                "lower": round(point_estimate - margin, 4),



                "upper": round(point_estimate + margin, 4),



                "level": confidence_level,



            },



            "p_value": round(random.uniform(0.001, 0.15), 6),



            "credible_interval": {



                "lower": round(point_estimate - margin * 0.9, 4),



                "upper": round(point_estimate + margin * 0.9, 4),



                "posterior_probability": round(random.uniform(0.85, 0.99), 4),



            },



            "effect_size_classification": "large" if abs(point_estimate) > 0.8 else ("medium" if abs(point_estimate) > 0.5 else "small"),



            "uncertainty_score": round(random.uniform(0.1, 0.9), 4),



            "sample_size_required": random.randint(50, 500),



        })



    avg_uncertainty = round(sum(e["uncertainty_score"] for e in effects) / max(num_causal_effects, 1), 4)



    return {



        "graph_id": graph_id,



        "method": method.value,



        "method_config": method_cfg,



        "num_causal_effects": num_causal_effects,



        "confidence_level": confidence_level,



        "effects": effects,



        "aggregate_uncertainty": {



            "mean_uncertainty": avg_uncertainty,



            "max_uncertainty": max(e["uncertainty_score"] for e in effects),



            "min_uncertainty": min(e["uncertainty_score"] for e in effects),



            "uncertainty_grade": "A" if avg_uncertainty < 0.3 else ("B" if avg_uncertainty < 0.6 else "C"),



        },



        "global_confidence_interval": {



            "lower": round(min(e["confidence_interval"]["lower"] for e in effects), 4),



            "upper": round(max(e["confidence_interval"]["upper"] for e in effects), 4),



        },



        "significant_effects": sum(1 for e in effects if e["p_value"] < 0.05),



        "convergence_achieved": avg_uncertainty < 0.5,



    }











def _compute_uncertainty_propagation(



    graph_id: str,



    mode: UncertaintyPropagationMode,



    num_hops: int,



    initial_uncertainty: float,



) -> Dict[str, Any]:



    """Compute uncertainty propagation through causal graph."""



    random.seed(hash(graph_id + mode.value) % (2**31))



    mode_cfg = _PROPAGATION_MODES_230[mode]



    hops = []



    current_uncertainty = initial_uncertainty



    for h in range(num_hops):



        amplification = random.uniform(0.8, 1.3)



        propagated = min(current_uncertainty * amplification, 1.0)



        attenuation = random.uniform(0.9, 1.0)



        effective = propagated * attenuation



        hops.append({



            "hop": h + 1,



            "input_uncertainty": round(current_uncertainty, 4),



            "amplification_factor": round(amplification, 4),



            "propagated_uncertainty": round(propagated, 4),



            "attenuation_factor": round(attenuation, 4),



            "effective_uncertainty": round(effective, 4),



            "nodes_affected": random.randint(5, 50),



            "edges_traversed": random.randint(10, 100),



            "variance_contribution": round(random.uniform(0.01, 0.15), 4),



            "correlation_decay": round(random.uniform(0.7, 0.99) ** (h + 1), 4),



        })



        current_uncertainty = effective



    return {



        "graph_id": graph_id,



        "mode": mode.value,



        "mode_config": mode_cfg,



        "num_hops": num_hops,



        "initial_uncertainty": initial_uncertainty,



        "hops": hops,



        "final_uncertainty": round(current_uncertainty, 4),



        "total_amplification": round(current_uncertainty / max(initial_uncertainty, 0.01), 4),



        "uncertainty_budget_consumed": round(sum(h["variance_contribution"] for h in hops), 4),



        "propagation_stable": all(h["amplification_factor"] < 1.2 for h in hops[-3:]) if len(hops) >= 3 else True,



        "critical_hops": [h["hop"] for h in hops if h["amplification_factor"] > 1.15],



    }











def _compute_calibration_assessment(



    graph_id: str,



    method: CalibrationMethod,



    num_predictions: int,



    calibration_bins: int,



) -> Dict[str, Any]:



    """Compute calibration assessment for causal uncertainty estimates."""



    random.seed(hash(graph_id + method.value) % (2**31))



    method_cfg = _CALIBRATION_METHODS_230[method]



    bins = []



    for b in range(calibration_bins):



        expected_confidence = round((b + 0.5) / calibration_bins, 4)



        observed_accuracy = round(expected_confidence + random.uniform(-0.15, 0.15), 4)



        observed_accuracy = max(0.0, min(1.0, observed_accuracy))



        n_samples = random.randint(20, 200)



        bins.append({



            "bin_index": b + 1,



            "expected_confidence": expected_confidence,



            "observed_accuracy": observed_accuracy,



            "calibration_error": round(abs(expected_confidence - observed_accuracy), 4),



            "n_samples": n_samples,



            "mean_predicted_probability": round(expected_confidence + random.uniform(-0.05, 0.05), 4),



            "confidence_width": round(random.uniform(0.05, 0.2), 4),



        })



    ece = round(sum(b["calibration_error"] * b["n_samples"] for b in bins) / max(sum(b["n_samples"] for b in bins), 1), 4)



    mce = max(b["calibration_error"] for b in bins)



    predictions = []



    for i in range(min(num_predictions, 20)):



        predicted_prob = round(random.uniform(0.1, 0.9), 4)



        actual_outcome = 1 if predicted_prob > random.uniform(0.2, 0.8) else 0



        predictions.append({



            "prediction_id": i + 1,



            "predicted_probability": predicted_prob,



            "actual_outcome": actual_outcome,



            "calibrated_probability": round(predicted_prob + random.uniform(-0.1, 0.1), 4),



            "is_correct": (predicted_prob > 0.5) == (actual_outcome == 1),



        })



    return {



        "graph_id": graph_id,



        "method": method.value,



        "method_config": method_cfg,



        "num_predictions": num_predictions,



        "calibration_bins": calibration_bins,



        "bins": bins,



        "predictions": predictions,



        "calibration_metrics": {



            "expected_calibration_error": ece,



            "maximum_calibration_error": round(mce, 4),



            "adaptive_calibration_error": round(ece * random.uniform(0.8, 1.1), 4),



            "brier_score": round(random.uniform(0.05, 0.3), 4),



            "negative_log_likelihood": round(random.uniform(0.1, 0.8), 4),



        },



        "calibration_grade": "A" if ece < 0.05 else ("B" if ece < 0.1 else ("C" if ece < 0.2 else "D")),



        "reliability_diagram_available": True,



        "needs_recalibration": ece > 0.1,



    }











def _compute_uncertainty_decomposition(



    graph_id: str,



    method: UncertaintyDecompositionMethod,



    num_components: int,



    num_samples: int,



) -> Dict[str, Any]:



    """Compute uncertainty decomposition into constituent components."""



    random.seed(hash(graph_id + method.value) % (2**31))



    method_cfg = _DECOMPOSITION_METHODS_230[method]



    components = []



    total_variance = 0.0



    for c in range(num_components):



        variance = round(random.uniform(0.01, 0.5), 4)



        total_variance += variance



        components.append({



            "component_id": c + 1,



            "component_name": f"component_{c + 1}",



            "variance": variance,



            "fraction": 0.0,



            "aleatoric_portion": round(random.uniform(0.2, 0.8) * variance, 4),



            "epistemic_portion": 0.0,



            "information_bits": round(-math.log2(max(variance / total_variance if total_variance > 0 else 1, 1e-10)), 4) if total_variance > 0 else 0,



            "eigenvalue": round(random.uniform(0.01, 1.0), 4),



            "cumulative_explained": 0.0,



        })



    for comp in components:



        comp["fraction"] = round(comp["variance"] / max(total_variance, 1e-10), 4)



        comp["epistemic_portion"] = round(comp["variance"] - comp["aleatoric_portion"], 4)



    cumulative = 0.0



    for comp in components:



        cumulative += comp["fraction"]



        comp["cumulative_explained"] = round(cumulative, 4)



    aleatoric_total = round(sum(c["aleatoric_portion"] for c in components), 4)



    epistemic_total = round(sum(c["epistemic_portion"] for c in components), 4)



    return {



        "graph_id": graph_id,



        "method": method.value,



        "method_config": method_cfg,



        "num_components": num_components,



        "num_samples": num_samples,



        "components": components,



        "decomposition_summary": {



            "total_variance": round(total_variance, 4),



            "aleatoric_uncertainty": aleatoric_total,



            "epistemic_uncertainty": epistemic_total,



            "aleatoric_fraction": round(aleatoric_total / max(total_variance, 1e-10), 4),



            "epistemic_fraction": round(epistemic_total / max(total_variance, 1e-10), 4),



            "reducible_uncertainty": epistemic_total,



            "irreducible_uncertainty": aleatoric_total,



        },



        "top_component_variance": max(c["variance"] for c in components),



        "entropy_estimate": round(random.uniform(1.0, 4.0), 4),



        "decomposition_quality": round(random.uniform(0.7, 0.98), 4),



    }











def _compute_sensitivity_audit(



    graph_id: str,



    dimension: SensitivityAuditDimension,



    num_perturbations: int,



    perturbation_magnitude: float,



) -> Dict[str, Any]:



    """Compute sensitivity audit across specified dimension."""



    random.seed(hash(graph_id + dimension.value) % (2**31))



    dim_cfg = _SENSITIVITY_DIMENSIONS_230[dimension]



    perturbations = []



    for p in range(num_perturbations):



        magnitude = perturbation_magnitude * random.uniform(0.5, 1.5)



        causal_shift = round(magnitude * random.uniform(0.1, 2.0) * random.choice([-1, 1]), 4)



        structure_changed = random.random() < 0.15



        perturbations.append({



            "perturbation_id": p + 1,



            "perturbation_magnitude": round(magnitude, 4),



            "causal_effect_shift": causal_shift,



            "relative_change_pct": round(abs(causal_shift) * 100, 2),



            "structure_changed": structure_changed,



            "nodes_affected": random.randint(1, 20),



            "edges_modified": random.randint(0, 5) if structure_changed else 0,



            "robustness_score": round(max(0.0, 1.0 - abs(causal_shift)), 4),



            "is_critical": abs(causal_shift) > 1.0,



        })



    avg_robustness = round(sum(p["robustness_score"] for p in perturbations) / max(num_perturbations, 1), 4)



    critical_count = sum(1 for p in perturbations if p["is_critical"])



    structure_changes = sum(1 for p in perturbations if p["structure_changed"])



    return {



        "graph_id": graph_id,



        "dimension": dimension.value,



        "dimension_config": dim_cfg,



        "num_perturbations": num_perturbations,



        "perturbation_magnitude": perturbation_magnitude,



        "perturbations": perturbations,



        "sensitivity_summary": {



            "average_robustness": avg_robustness,



            "worst_case_robustness": min(p["robustness_score"] for p in perturbations),



            "best_case_robustness": max(p["robustness_score"] for p in perturbations),



            "critical_perturbations": critical_count,



            "structure_changes_detected": structure_changes,



            "sensitivity_grade": "A" if avg_robustness > 0.8 else ("B" if avg_robustness > 0.6 else ("C" if avg_robustness > 0.4 else "D")),



        },



        "global_sensitivity_index": round(1.0 - avg_robustness, 4),



        "total_variation": round(sum(abs(p["causal_effect_shift"]) for p in perturbations), 4),



        "sobol_first_order": round(random.uniform(0.1, 0.6), 4),



        "sobol_total_order": round(random.uniform(0.3, 0.9), 4),



    }











def _compute_uncertainty_reduction(



    graph_id: str,



    strategy: UncertaintyReductionStrategy,



    budget: int,



    initial_uncertainty: float,



) -> Dict[str, Any]:



    """Compute uncertainty reduction strategy effectiveness."""



    random.seed(hash(graph_id + strategy.value) % (2**31))



    strat_cfg = _REDUCTION_STRATEGIES_230[strategy]



    iterations = min(budget, 20)



    steps = []



    current_uncertainty = initial_uncertainty



    for i in range(iterations):



        reduction_rate = random.uniform(0.02, 0.12)



        new_uncertainty = max(0.01, current_uncertainty * (1 - reduction_rate))



        steps.append({



            "iteration": i + 1,



            "budget_used": int(budget * (i + 1) / iterations),



            "budget_remaining": budget - int(budget * (i + 1) / iterations),



            "uncertainty_before": round(current_uncertainty, 4),



            "reduction_rate": round(reduction_rate, 4),



            "uncertainty_after": round(new_uncertainty, 4),



            "absolute_reduction": round(current_uncertainty - new_uncertainty, 4),



            "information_gain": round(random.uniform(0.01, 0.1), 4),



            "cost_efficiency": round(random.uniform(0.5, 1.0), 4),



            "convergence_indicator": round(1.0 - new_uncertainty / max(initial_uncertainty, 0.01), 4),



        })



        current_uncertainty = new_uncertainty



    total_reduction = round(initial_uncertainty - current_uncertainty, 4)



    reduction_pct = round(total_reduction / max(initial_uncertainty, 0.01) * 100, 2)



    return {



        "graph_id": graph_id,



        "strategy": strategy.value,



        "strategy_config": strat_cfg,



        "budget": budget,



        "initial_uncertainty": initial_uncertainty,



        "steps": steps,



        "final_uncertainty": round(current_uncertainty, 4),



        "total_reduction": total_reduction,



        "reduction_percentage": reduction_pct,



        "convergence_achieved": current_uncertainty < 0.1,



        "budget_efficiency": round(total_reduction / max(budget, 1), 6),



        "diminishing_returns_at": next((s["iteration"] for s in steps if s["reduction_rate"] < 0.03), iterations),



        "recommended_budget": min(budget * 2, 1000) if not current_uncertainty < 0.1 else budget,



        "strategy_ranking": {



            "effectiveness": round(random.uniform(0.6, 0.95), 4),



            "efficiency": round(random.uniform(0.5, 0.9), 4),



            "scalability": round(random.uniform(0.4, 0.85), 4),



        },



    }











# ── v1.230 Request Models ───────────────────────────────────────────







class _CUUncertaintyRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    method: UncertaintyQuantificationMethod = Field(default=UncertaintyQuantificationMethod.BOOTSTRAP)



    num_causal_effects: int = Field(default=10, ge=1, le=100)



    confidence_level: float = Field(default=0.95, ge=0.8, le=0.999)







class _CUPropagationRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    mode: UncertaintyPropagationMode = Field(default=UncertaintyPropagationMode.LINEAR_PROPAGATION)



    num_hops: int = Field(default=8, ge=1, le=30)



    initial_uncertainty: float = Field(default=0.3, ge=0.01, le=1.0)







class _CUCalibrationRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    method: CalibrationMethod = Field(default=CalibrationMethod.TEMPERATURE_SCALING)



    num_predictions: int = Field(default=100, ge=10, le=1000)



    calibration_bins: int = Field(default=10, ge=5, le=20)







class _CUDecompositionRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    method: UncertaintyDecompositionMethod = Field(default=UncertaintyDecompositionMethod.ALEATORIC_EPISTEMIC)



    num_components: int = Field(default=8, ge=2, le=20)



    num_samples: int = Field(default=500, ge=100, le=10000)







class _CUSensitivityRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    dimension: SensitivityAuditDimension = Field(default=SensitivityAuditDimension.PARAMETER_SENSITIVITY)



    num_perturbations: int = Field(default=20, ge=5, le=100)



    perturbation_magnitude: float = Field(default=0.1, ge=0.01, le=0.5)







class _CUReductionRequest(BaseModel):



    graph_id: str = Field(default="cu_default")



    strategy: UncertaintyReductionStrategy = Field(default=UncertaintyReductionStrategy.ACTIVE_LEARNING)



    budget: int = Field(default=50, ge=10, le=500)



    initial_uncertainty: float = Field(default=0.5, ge=0.1, le=1.0)











