    result = _compute_causal_uncertainty(



        req.graph_id, req.method, req.num_causal_effects, req.confidence_level,



    )



    _cu_uncertainty_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.230", "data": result})











