# =============================================================================



# v1.231 - Graph Self-Supervised Causal Discovery Engine



# =============================================================================







"""



Graph Self-Supervised Causal Discovery Engine — Self-supervised learning for causal structure.







Learns causal graph structures from observational data without explicit causal labels,



using contrastive learning, masked reconstruction, and information-theoretic objectives.







Endpoints:



  POST /ssl-causal/discover       — Self-supervised causal structure discovery



  POST /ssl-causal/contrastive    — Contrastive causal representation learning



  POST /ssl-causal/masked         — Masked causal graph reconstruction



  POST /ssl-causal/information    — Information-theoretic causal scoring



  POST /ssl-causal/augmentation   — Causal data augmentation for self-supervision



  POST /ssl-causal/validation     — Self-supervised causal validation



  GET  /ssl-causal/overview       — Engine overview and statistics



"""







import random as _random231











# ---------------------------------------------------------------------------



# Enums



# ---------------------------------------------------------------------------







class SSLCausalDiscoveryMethod(str, Enum):



    """Self-supervised causal discovery methods."""



    CONTRASTIVE = "contrastive"



    MASKED_RECONSTRUCTION = "masked_reconstruction"



    VARIATIONAL = "variational"



    FLOW_BASED = "flow_based"



    DIFFUSION = "diffusion"



    HYBRID_SSL = "hybrid_ssl"











class CausalContrastiveMode(str, Enum):



    """Contrastive learning modes for causal representation."""



    TRIPLET = "triplet"



    NT_XENT = "nt_xent"



    INFO_NCE = "info_nce"



    MARGIN = "margin"



    SUPERVISED_CONTRASTIVE = "supervised_contrastive"



    DEEP_CLUSTER = "deep_cluster"











class CausalMaskStrategy(str, Enum):



    """Masking strategies for causal graph reconstruction."""



    RANDOM_NODE = "random_node"



    RANDOM_EDGE = "random_edge"



    STRUCTURED = "structured"



    ADAPTIVE = "adaptive"



    BLOCKWISE = "blockwise"



    CAUSAL_PATH = "causal_path"











class CausalInfoScore(str, Enum):



    """Information-theoretic causal scoring functions."""



    MUTUAL_INFO = "mutual_info"



    CONDITIONAL_MI = "conditional_mi"



    TRANSFER_ENTROPY = "transfer_entropy"



    KL_DIVERGENCE = "kl_divergence"



    TOTAL_CORRELATION = "total_correlation"



    INTEGRATED_INFO = "integrated_info"











class CausalAugmentType(str, Enum):



    """Data augmentation types for self-supervised causal learning."""



    NODE_DROPOUT = "node_dropout"



    EDGE_PERTURBATION = "edge_perturbation"



    FEATURE_NOISE = "feature_noise"



    SUBGRAPH_SAMPLING = "subgraph_sampling"



    DIFFUSION_AUGMENT = "diffusion_augment"



    MIXUP = "mixup"











class SSLCausalValidation(str, Enum):



    """Self-supervised causal validation methods."""



    CONSISTENCY = "consistency"



    INVARIANCE = "invariance"



    INTERVENTION_SIM = "intervention_sim"



    BOOTSTRAP = "bootstrap"



    CROSS_VALIDATION = "cross_validation"



    ADVERSARIAL = "adversarial"











# ---------------------------------------------------------------------------



# Computation helpers



# ---------------------------------------------------------------------------







def _compute_ssl_causal_discovery(



    graph_id: str,



    method: SSLCausalDiscoveryMethod,



    num_variables: int,



    sample_size: int,



    temperature: float,



):



    """Self-supervised causal structure discovery from data."""



    _random231.seed(hash(graph_id) % (2**31))



    methods = {



        SSLCausalDiscoveryMethod.CONTRASTIVE: {"lr": 1e-3, "proj_dim": 128, "tau": 0.07},



        SSLCausalDiscoveryMethod.MASKED_RECONSTRUCTION: {"mask_ratio": 0.15, "reconstruct_loss": "mse", "encoder_layers": 4},



        SSLCausalDiscoveryMethod.VARIATIONAL: {"latent_dim": 64, "kl_weight": 0.01, "prior": "gaussian"},



        SSLCausalDiscoveryMethod.FLOW_BASED: {"flow_steps": 8, "coupling_layers": 4, "hidden_units": 256},



        SSLCausalDiscoveryMethod.DIFFUSION: {"timesteps": 1000, "noise_schedule": "cosine", "beta_start": 1e-4},



        SSLCausalDiscoveryMethod.HYBRID_SSL: {"contrastive_weight": 0.4, "reconstruct_weight": 0.3, "info_weight": 0.3},



    }



    method_cfg = methods[method]



    discovered_edges = []



    for i in range(num_variables):



        for j in range(num_variables):



            if i != j and _random231.random() < 0.25:



                strength = round(_random231.uniform(0.1, 1.0), 4)



                confidence = round(_random231.uniform(0.5, 0.99), 4)



                discovered_edges.append({



                    "cause": f"X{i}",



                    "effect": f"X{j}",



                    "strength": strength,



                    "confidence": confidence,



                    "ssl_score": round(_random231.uniform(0.3, 0.95), 4),



                })



    discovered_edges.sort(key=lambda e: e["ssl_score"], reverse=True)



    precision = round(_random231.uniform(0.6, 0.92), 4)



    recall = round(_random231.uniform(0.55, 0.88), 4)



    f1 = round(2 * precision * recall / max(precision + recall, 1e-8), 4)



    return {



        "graph_id": graph_id,



        "method": method.value,



        "num_variables": num_variables,



        "sample_size": sample_size,



        "method_config": method_cfg,



        "temperature": temperature,



        "discovered_edges": discovered_edges[:min(30, len(discovered_edges))],



        "num_discovered": len(discovered_edges),



        "metrics": {



            "precision": precision,



            "recall": recall,



            "f1_score": f1,



            "auc_roc": round(_random231.uniform(0.7, 0.96), 4),



            "shd": _random231.randint(0, num_variables * 2),



        },



        "training_info": {



            "epochs": _random231.randint(50, 300),



            "final_loss": round(_random231.uniform(0.01, 0.3), 6),



            "converged": _random231.random() > 0.15,



        },



    }











def _compute_contrastive_causal(



    graph_id: str,



    mode: CausalContrastiveMode,



    embedding_dim: int,



    batch_size: int,



):



    """Contrastive causal representation learning."""



    _random231.seed(hash(graph_id + mode.value) % (2**31))



    modes = {



        CausalContrastiveMode.TRIPLET: {"margin": 0.2, "mining": "semi_hard"},



        CausalContrastiveMode.NT_XENT: {"temperature": 0.1, "projection_dim": 64},



        CausalContrastiveMode.INFO_NCE: {"negative_samples": 256, "encoder": "gcn"},



        CausalContrastiveMode.MARGIN: {"alpha": 0.3, "beta": 1.2, "pair_mining": "hard"},



        CausalContrastiveMode.SUPERVISED_CONTRASTIVE: {"num_classes": 6, "lambda_sc": 0.5},



        CausalContrastiveMode.DEEP_CLUSTER: {"cluster_k": 8, "reassign_interval": 5},



    }



    mode_cfg = modes[mode]



    num_nodes = _random231.randint(5, 20)



    embeddings = []



    for n in range(num_nodes):



        emb = [_random231.gauss(0, 1) for _ in range(min(embedding_dim, 32))]



        norm = max(sum(x * x for x in emb) ** 0.5, 1e-8)



        embeddings.append({"node": f"N{n}", "embedding": [round(x / norm, 4) for x in emb[:8]]})



    causal_pairs = []



    for i in range(num_nodes):



        for j in range(num_nodes):



            if i != j and _random231.random() < 0.2:



                sim = round(_random231.uniform(-0.5, 0.9), 4)



                causal_pairs.append({



                    "anchor": f"N{i}",



                    "positive": f"N{j}" if sim > 0 else f"N{(j + 1) % num_nodes}",



                    "negative": f"N{(j + 2) % num_nodes}",



                    "similarity": sim,



                    "causal_score": round(max(0, sim), 4),



                })



    return {



        "graph_id": graph_id,



        "mode": mode.value,



        "mode_config": mode_cfg,



        "embedding_dim": embedding_dim,



        "batch_size": batch_size,



        "num_nodes": num_nodes,



        "embeddings_sample": embeddings[:10],



        "causal_pairs": causal_pairs[:15],



        "contrastive_metrics": {



            "alignment": round(_random231.uniform(0.6, 0.95), 4),



            "uniformity": round(_random231.uniform(0.3, 0.8), 4),



            "nt_xent_loss": round(_random231.uniform(0.1, 2.0), 4),



            "top_k_accuracy": round(_random231.uniform(0.7, 0.98), 4),



        },



        "causal_separation": {



            "intra_cause_sim": round(_random231.uniform(0.7, 0.95), 4),



            "inter_cause_sim": round(_random231.uniform(0.1, 0.4), 4),



            "separation_ratio": round(_random231.uniform(2.0, 5.0), 4),



        },



    }











def _compute_masked_causal(



    graph_id: str,



    mask_strategy: CausalMaskStrategy,



    mask_ratio: float,



    reconstruction_layers: int,



):



    """Masked causal graph reconstruction."""



    _random231.seed(hash(graph_id + mask_strategy.value) % (2**31))



    strategies = {



        CausalMaskStrategy.RANDOM_NODE: {"selection": "uniform", "min_component": 1},



        CausalMaskStrategy.RANDOM_EDGE: {"edge_sample_rate": 0.2, "preserve_skeleton": True},



        CausalMaskStrategy.STRUCTURED: {"block_size": 3, "stride": 1, "hierarchy": 2},



        CausalMaskStrategy.ADAPTIVE: {"importance_threshold": 0.5, "curriculum": True},



        CausalMaskStrategy.BLOCKWISE: {"block_dim": 4, "overlap": 0.5, "scan_order": "raster"},



        CausalMaskStrategy.CAUSAL_PATH: {"max_path_length": 5, "root_cause_bias": 0.3},



    }



    strat_cfg = strategies[mask_strategy]



    num_nodes = _random231.randint(8, 25)



    masked_nodes = _random231.sample(range(num_nodes), max(1, int(num_nodes * mask_ratio)))



    masked_edges = []



    for i in range(num_nodes):



        for j in range(num_nodes):



            if i != j and _random231.random() < 0.15:



                masked_edges.append({"from": f"X{i}", "to": f"X{j}", "masked": _random231.random() < mask_ratio})



    reconstruction = []



    for mn in masked_nodes:



        original_neighbors = _random231.randint(1, 4)



        reconstructed_neighbors = _random231.randint(1, 4)



        reconstruction.append({



            "masked_node": f"X{mn}",



            "original_degree": original_neighbors,



            "reconstructed_degree": reconstructed_neighbors,



            "degree_accuracy": round(



                min(original_neighbors, reconstructed_neighbors) / max(original_neighbors, reconstructed_neighbors, 1), 4



            ),



            "edge_reconstruction_prob": round(_random231.uniform(0.5, 0.95), 4),



        })



    return {



        "graph_id": graph_id,



        "mask_strategy": mask_strategy.value,



        "strategy_config": strat_cfg,



        "mask_ratio": mask_ratio,



        "reconstruction_layers": reconstruction_layers,



        "num_nodes": num_nodes,



        "num_masked_nodes": len(masked_nodes),



        "masked_edges_count": sum(1 for e in masked_edges if e["masked"]),



        "total_edges": len(masked_edges),



        "reconstruction_detail": reconstruction,



        "metrics": {



            "node_reconstruction_accuracy": round(_random231.uniform(0.6, 0.92), 4),



            "edge_reconstruction_accuracy": round(_random231.uniform(0.55, 0.88), 4),



            "structure_preservation_score": round(_random231.uniform(0.5, 0.9), 4),



            "reconstruction_loss": round(_random231.uniform(0.05, 0.5), 4),



            "causal_direction_accuracy": round(_random231.uniform(0.6, 0.9), 4),



        },



    }











def _compute_info_causal_score(



    graph_id: str,



    score_type: CausalInfoScore,



    num_candidates: int,



    significance_level: float,



):



    """Information-theoretic causal scoring."""



    _random231.seed(hash(graph_id + score_type.value) % (2**31))



    score_cfgs = {



        CausalInfoScore.MUTUAL_INFO: {"estimator": "ksg", "k_neighbors": 5, "bias_correction": True},



        CausalInfoScore.CONDITIONAL_MI: {"conditioning_set_size": 3, "cuda": False},



        CausalInfoScore.TRANSFER_ENTROPY: {"lag_order": 3, "symbolization": True, "alphabet_size": 4},



        CausalInfoScore.KL_DIVERGENCE: {"reference": "marginal", "monte_carlo_samples": 1000},



        CausalInfoScore.TOTAL_CORRELATION: {"decomposition": "pairwise", "bound_type": "lower"},



        CausalInfoScore.INTEGRATED_INFO: {"phi_partition": "minimum", "cut_sets": "exhaustive"},



    }



    cfg = score_cfgs[score_type]



    candidates = []



    for i in range(num_candidates):



        for j in range(num_candidates):



            if i != j and _random231.random() < 0.3:



                score_val = round(_random231.uniform(0.0, 2.0), 4)



                p_value = round(_random231.uniform(0.001, 0.1), 4)



                candidates.append({



                    "source": f"X{i}",



                    "target": f"X{j}",



                    "info_score": score_val,



                    "p_value": p_value,



                    "significant": p_value < significance_level,



                    "rank": 0,



                })



    candidates.sort(key=lambda c: c["info_score"], reverse=True)



    for idx, c in enumerate(candidates):



        c["rank"] = idx + 1



    return {



        "graph_id": graph_id,



        "score_type": score_type.value,



        "score_config": cfg,



        "num_candidates": num_candidates,



        "significance_level": significance_level,



        "scored_pairs": candidates[:20],



        "total_scored": len(candidates),



        "significant_count": sum(1 for c in candidates if c["significant"]),



        "aggregate": {



            "mean_score": round(sum(c["info_score"] for c in candidates) / max(len(candidates), 1), 4),



            "max_score": max((c["info_score"] for c in candidates), default=0),



            "significant_ratio": round(



                sum(1 for c in candidates if c["significant"]) / max(len(candidates), 1), 4



            ),



        },



    }











def _compute_causal_augmentation(



    graph_id: str,



    augment_type: CausalAugmentType,



    augment_strength: float,



    num_augmented: int,



):



    """Causal data augmentation for self-supervised learning."""



    _random231.seed(hash(graph_id + augment_type.value) % (2**31))



    aug_cfgs = {



        CausalAugmentType.NODE_DROPOUT: {"dropout_rate": augment_strength, "min_components": 1},



        CausalAugmentType.EDGE_PERTURBATION: {"add_ratio": augment_strength, "remove_ratio": augment_strength * 0.5},



        CausalAugmentType.FEATURE_NOISE: {"noise_type": "gaussian", "std": augment_strength, "clip": True},



        CausalAugmentType.SUBGRAPH_SAMPLING: {"sample_ratio": 1 - augment_strength, "walk_length": 10, "num_walks": 5},



        CausalAugmentType.DIFFUSION_AUGMENT: {"steps": int(augment_strength * 100), "schedule": "linear"},



        CausalAugmentType.MIXUP: {"alpha": augment_strength, "interpolation": "linear", "label_mix": True},



    }



    cfg = aug_cfgs[augment_type]



    augmented_views = []



    for v in range(num_augmented):



        num_nodes = _random231.randint(5, 20)



        num_edges = _random231.randint(num_nodes, num_nodes * 3)



        causal_preservation = round(_random231.uniform(0.6, 0.98), 4)



        distribution_shift = round(_random231.uniform(0.01, 0.2), 4)



        augmented_views.append({



            "view_id": v + 1,



            "num_nodes": num_nodes,



            "num_edges": num_edges,



            "causal_preservation_rate": causal_preservation,



            "distribution_shift": distribution_shift,



            "augmentation_quality": round(causal_preservation / max(distribution_shift, 1e-8), 4),



        })



    return {



        "graph_id": graph_id,



        "augment_type": augment_type.value,



        "augment_config": cfg,



        "augment_strength": augment_strength,



        "num_augmented_views": num_augmented,



        "augmented_views": augmented_views,



        "overall_quality": {



            "mean_preservation": round(



                sum(v["causal_preservation_rate"] for v in augmented_views) / max(len(augmented_views), 1), 4



            ),



            "mean_shift": round(



                sum(v["distribution_shift"] for v in augmented_views) / max(len(augmented_views), 1), 4



            ),



            "diversity_score": round(_random231.uniform(0.5, 0.9), 4),



            "causal_invariance": round(_random231.uniform(0.7, 0.95), 4),



        },



    }











def _compute_ssl_causal_validation(



    graph_id: str,



    validation_method: SSLCausalValidation,



    num_trials: int,



    confidence_level: float,



):



    """Self-supervised causal validation."""



    _random231.seed(hash(graph_id + validation_method.value) % (2**31))



    val_cfgs = {



        SSLCausalValidation.CONSISTENCY: {"threshold": 0.8, "metric": "edge_overlap", "bootstrap_samples": 100},



        SSLCausalValidation.INVARIANCE: {"environment_count": 4, "test_statistic": "ks_test", "alpha": 0.05},



        SSLCausalValidation.INTERVENTION_SIM: {"num_interventions": 10, "effect_threshold": 0.1, "intervene_ratio": 0.3},



        SSLCausalValidation.BOOTSTRAP: {"n_bootstrap": 200, "edge_threshold": 0.5, "aggregation": "majority_vote"},



        SSLCausalValidation.CROSS_VALIDATION: {"folds": 5, "scoring": "f1", "stratified": True},



        SSLCausalValidation.ADVERSARIAL: {"attack_type": "pgd", "epsilon": 0.1, "perturbation_norm": "linf"},



    }



    cfg = val_cfgs[validation_method]



    trial_results = []



    for t in range(num_trials):



        stability = round(_random231.uniform(0.5, 1.0), 4)



        edge_precision = round(_random231.uniform(0.6, 0.95), 4)



        edge_recall = round(_random231.uniform(0.55, 0.9), 4)



        trial_results.append({



            "trial": t + 1,



            "stability_score": stability,



            "edge_precision": edge_precision,



            "edge_recall": edge_recall,



            "direction_accuracy": round(_random231.uniform(0.6, 0.95), 4),



            "passed": stability > 0.7 and edge_precision > 0.7,



        })



    passed_count = sum(1 for tr in trial_results if tr["passed"])



    return {



        "graph_id": graph_id,



        "validation_method": validation_method.value,



        "validation_config": cfg,



        "num_trials": num_trials,



        "confidence_level": confidence_level,



        "trial_results": trial_results,



        "summary": {



            "pass_rate": round(passed_count / max(num_trials, 1), 4),



            "mean_stability": round(



                sum(tr["stability_score"] for tr in trial_results) / max(num_trials, 1), 4



            ),



            "mean_precision": round(



                sum(tr["edge_precision"] for tr in trial_results) / max(num_trials, 1), 4



            ),



            "mean_recall": round(



                sum(tr["edge_recall"] for tr in trial_results) / max(num_trials, 1), 4



            ),



            "validation_passed": passed_count >= num_trials * confidence_level,



            "confidence_achieved": round(passed_count / max(num_trials, 1), 4),



        },



        "grading": "A" if passed_count >= num_trials * 0.9 else ("B" if passed_count >= num_trials * 0.7 else "C"),



    }











# ---------------------------------------------------------------------------



# Cache dictionaries



# ---------------------------------------------------------------------------



_ssl_discover_cache: dict = {}



_ssl_contrastive_cache: dict = {}



_ssl_masked_cache: dict = {}



_ssl_info_cache: dict = {}



_ssl_augment_cache: dict = {}



_ssl_validation_cache: dict = {}







# Strategy lookup tables



_DISCOVERY_METHODS_231 = {m: m.value for m in SSLCausalDiscoveryMethod}



_CONTRASTIVE_MODES_231 = {m: m.value for m in CausalContrastiveMode}



_MASK_STRATEGIES_231 = {s: s.value for s in CausalMaskStrategy}



_INFO_SCORES_231 = {s: s.value for s in CausalInfoScore}



_AUGMENT_TYPES_231 = {a: a.value for a in CausalAugmentType}



_VALIDATION_METHODS_231 = {v: v.value for v in SSLCausalValidation}











# ---------------------------------------------------------------------------



# Request models



# ---------------------------------------------------------------------------







class _SSLDiscoverRequest(BaseModel):



    graph_id: str



    method: SSLCausalDiscoveryMethod = SSLCausalDiscoveryMethod.HYBRID_SSL



    num_variables: int = 10



    sample_size: int = 1000



    temperature: float = 0.1











class _SSLContrastiveRequest(BaseModel):



    graph_id: str



    mode: CausalContrastiveMode = CausalContrastiveMode.NT_XENT



    embedding_dim: int = 128



    batch_size: int = 64











class _SSLMaskedRequest(BaseModel):



    graph_id: str



    mask_strategy: CausalMaskStrategy = CausalMaskStrategy.ADAPTIVE



    mask_ratio: float = 0.15



    reconstruction_layers: int = 4











class _SSLInfoRequest(BaseModel):



    graph_id: str



    score_type: CausalInfoScore = CausalInfoScore.MUTUAL_INFO



    num_candidates: int = 10



    significance_level: float = 0.05











class _SSLAugmentRequest(BaseModel):



    graph_id: str



    augment_type: CausalAugmentType = CausalAugmentType.SUBGRAPH_SAMPLING



    augment_strength: float = 0.3



    num_augmented: int = 5











class _SSLValidationRequest(BaseModel):



    graph_id: str



    validation_method: SSLCausalValidation = SSLCausalValidation.CONSISTENCY



    num_trials: int = 10



    confidence_level: float = 0.8











