# Endpoints



# ---------------------------------------------------------------------------







@router.post("/ssl-causal/discover")



async def ssl_causal_discover(req: _SSLDiscoverRequest):



    """Self-supervised causal structure discovery from data."""



    result = _compute_ssl_causal_discovery(



        req.graph_id, req.method, req.num_variables, req.sample_size, req.temperature,



    )



    _ssl_discover_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.post("/ssl-causal/contrastive")



async def ssl_causal_contrastive(req: _SSLContrastiveRequest):



    """Contrastive causal representation learning."""



    result = _compute_contrastive_causal(



        req.graph_id, req.mode, req.embedding_dim, req.batch_size,



    )



    _ssl_contrastive_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.post("/ssl-causal/masked")



async def ssl_causal_masked(req: _SSLMaskedRequest):



    """Masked causal graph reconstruction."""



    result = _compute_masked_causal(



        req.graph_id, req.mask_strategy, req.mask_ratio, req.reconstruction_layers,



    )



    _ssl_masked_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.post("/ssl-causal/information")



async def ssl_causal_information(req: _SSLInfoRequest):



    """Information-theoretic causal scoring."""



    result = _compute_info_causal_score(



        req.graph_id, req.score_type, req.num_candidates, req.significance_level,



    )



    _ssl_info_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.post("/ssl-causal/augmentation")



async def ssl_causal_augmentation(req: _SSLAugmentRequest):



    """Causal data augmentation for self-supervised learning."""



    result = _compute_causal_augmentation(



        req.graph_id, req.augment_type, req.augment_strength, req.num_augmented,



    )



    _ssl_augment_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.post("/ssl-causal/validation")



async def ssl_causal_validation(req: _SSLValidationRequest):



    """Self-supervised causal validation."""



    result = _compute_ssl_causal_validation(



        req.graph_id, req.validation_method, req.num_trials, req.confidence_level,



    )



    _ssl_validation_cache[req.graph_id] = result



    return JSONResponse({"status": "success", "version": "v1.231", "data": result})











@router.get("/ssl-causal/overview")



async def ssl_causal_overview():



    """Overview of the Self-Supervised Causal Discovery Engine."""



    return {



        "engine": "Graph Self-Supervised Causal Discovery",



        "version": "v1.231",



        "description": "Self-supervised learning for causal structure discovery from observational data",



        "enums": {



            "SSLCausalDiscoveryMethod": [m.value for m in SSLCausalDiscoveryMethod],



            "CausalContrastiveMode": [m.value for m in CausalContrastiveMode],



            "CausalMaskStrategy": [s.value for s in CausalMaskStrategy],



            "CausalInfoScore": [s.value for s in CausalInfoScore],



            "CausalAugmentType": [a.value for a in CausalAugmentType],



            "SSLCausalValidation": [v.value for v in SSLCausalValidation],



        },



        "caches": {



            "discover": len(_ssl_discover_cache),



            "contrastive": len(_ssl_contrastive_cache),



            "masked": len(_ssl_masked_cache),



            "information": len(_ssl_info_cache),



            "augmentation": len(_ssl_augment_cache),



            "validation": len(_ssl_validation_cache),



        },



        "discovery_methods": {k.value: v for k, v in _DISCOVERY_METHODS_231.items()},



        "integration": {



            "causal_uncertainty": "v1.230",



            "dynamic_topology": "v1.229",



            "federated_causal": "v1.228",



            "causal_discovery": "v1.214",



            "self_supervised_learning": "v1.207",



            "multimodal_ssl": "v1.215",



        },



    }











