# =============================================================================



# v1.233 - Graph Topology-Aware Causal Intervention Engine



# =============================================================================







"""



Graph Topology-Aware Causal Intervention Engine — Topology-guided causal intervention design and execution.







Integrates graph topology analysis with Pearl's do-calculus to design, execute, propagate,



optimize, validate, and reason counterfactually about causal interventions on graph structures.







Endpoints:



  POST /topo-intervention/design        — Design topology-aware causal intervention plan



  POST /topo-intervention/execute       — Execute causal intervention on graph topology



  POST /topo-intervention/propagate     — Propagate intervention effects through topology



  POST /topo-intervention/optimize      — Optimize intervention placement via topology analysis



  POST /topo-intervention/validate      — Validate intervention with topology-constrained analysis



  POST /topo-intervention/counterfactual — Counterfactual reasoning under topology constraints



  GET  /topo-intervention/overview      — Engine overview and statistics



"""







import random as _random233











# ---------------------------------------------------------------------------



# Enums



# ---------------------------------------------------------------------------







class InterventionStrategy(str, Enum):



    """Causal intervention strategies guided by topology analysis."""



    DO_OPERATOR = "do_operator"



    BACKDOOR_ADJUST = "backdoor_adjust"



    FRONTDOOR_ADJUST = "frontdoor_adjust"



    INSTRUMENTAL = "instrumental"



    MEDIATOR_BLOCK = "mediator_block"



    TOPOLOGY_GUIDED = "topology_guided"











class TopologyFeature(str, Enum):



    """Graph topology features used to guide intervention design."""



    BETWEENNESS = "betweenness"



    CLOSENESS = "closeness"



    EIGENVECTOR = "eigenvector"



    PAGERANK = "pagerank"



    CLUSTERING = "clustering"



    BRIDGE_SCORE = "bridge_score"











class EffectEstimator(str, Enum):



    """Causal effect estimation methods for intervention outcomes."""



    ATE = "ate"



    ITE = "ite"



    CATE = "cate"



    QTE = "qte"



    DET = "det"



    DISTRIBUTIONAL = "distributional"











class InterventionScope(str, Enum):



    """Scope of causal intervention on graph structures."""



    NODE_LEVEL = "node_level"



    EDGE_LEVEL = "edge_level"



    SUBGRAPH_LEVEL = "subgraph_level"



    PATH_LEVEL = "path_level"



    COMMUNITY_LEVEL = "community_level"



    GLOBAL_LEVEL = "global_level"











class CausalPathway(str, Enum):



    """Types of causal pathways analyzed during intervention."""



    DIRECT = "direct"



    INDIRECT = "indirect"



    SPURIOUS = "spurious"



    MEDIATED = "mediated"



    MODERATED = "moderated"



    FEEDBACK = "feedback"











class OutcomeMetric(str, Enum):



    """Metrics for evaluating intervention outcomes."""



    INTERVENTION_EFFECT = "intervention_effect"



    TOPOLOGY_PRESERVATION = "topology_preservation"



    CAUSAL_CONSISTENCY = "causal_consistency"



    INTERVENTION_ROBUSTNESS = "intervention_robustness"



    COMPLIANCE_SCORE = "compliance_score"



    INFORMATION_GAIN = "information_gain"











# ---------------------------------------------------------------------------



# Computation helpers



# ---------------------------------------------------------------------------







def _compute_topo_intervention_design(



    graph_id: str,



    strategy: InterventionStrategy,



    topology_feature: TopologyFeature,



    scope: InterventionScope,



    num_targets: int,



):



    """Design a topology-aware causal intervention plan."""



    _random233.seed(hash(graph_id) % (2**31))



    strategies = {



        InterventionStrategy.DO_OPERATOR: {"requires_observational": True, "graphoid_axioms": 4, "identifiability": "full"},



        InterventionStrategy.BACKDOOR_ADJUST: {"min_adjustment_set": 2, "confounder_bound": 0.95, "stability": "high"},



        InterventionStrategy.FRONTDOOR_ADJUST: {"mediator_required": True, "chain_length": 2, "identifiability": "partial"},



        InterventionStrategy.INSTRUMENTAL: {"relevance_threshold": 0.3, "exclusion_test": True, "strength": "moderate"},



        InterventionStrategy.MEDIATOR_BLOCK: {"block_mediators": 3, "path_decomposition": True, "deconfound": True},



        InterventionStrategy.TOPOLOGY_GUIDED: {"topology_weight": 0.7, "adaptive_adjustment": True, "fallback_strategy": "backdoor"},



    }



    strat_cfg = strategies[strategy]



    topo_features = {



        TopologyFeature.BETWEENNESS: {"sensitivity": 0.85, "coverage": "high", "computational_cost": "moderate"},



        TopologyFeature.CLOSENESS: {"sensitivity": 0.72, "coverage": "medium", "computational_cost": "low"},



        TopologyFeature.EIGENVECTOR: {"sensitivity": 0.90, "coverage": "high", "computational_cost": "high"},



        TopologyFeature.PAGERANK: {"sensitivity": 0.88, "coverage": "high", "computational_cost": "moderate"},



        TopologyFeature.CLUSTERING: {"sensitivity": 0.65, "coverage": "local", "computational_cost": "low"},



        TopologyFeature.BRIDGE_SCORE: {"sensitivity": 0.78, "coverage": "structural", "computational_cost": "moderate"},



    }



    feat_cfg = topo_features[topology_feature]



    targets = []



    for i in range(num_targets):



        targets.append({



            "target_id": f"target_{i+1}",



            "topology_score": round(_random233.uniform(0.3, 1.0), 4),



            "confounders_detected": _random233.randint(1, 6),



            "adjustment_set_size": _random233.randint(2, 8),



            "identifiability_score": round(_random233.uniform(0.6, 1.0), 4),



            "intervention_feasibility": round(_random233.uniform(0.5, 1.0), 4),



        })



    plan = {



        "graph_id": graph_id,



        "strategy": strategy.value,



        "strategy_config": strat_cfg,



        "topology_feature": topology_feature.value,



        "topology_config": feat_cfg,



        "scope": scope.value,



        "num_targets": num_targets,



        "targets": targets,



        "design_quality": round(_random233.uniform(0.7, 0.98), 4),



        "topology_utilization": round(_random233.uniform(0.6, 0.95), 4),



        "estimated_causal_power": round(_random233.uniform(0.5, 0.95), 4),



    }



    return plan











def _compute_topo_intervention_execute(



    graph_id: str,



    strategy: InterventionStrategy,



    scope: InterventionScope,



    intervention_strength: float,



    num_steps: int,



):



    """Execute causal intervention on graph topology."""



    _random233.seed(hash(graph_id) % (2**31))



    steps = []



    for s in range(num_steps):



        pre_state = {



            "active_nodes": _random233.randint(50, 200),



            "active_edges": _random233.randint(100, 500),



            "causal_density": round(_random233.uniform(0.1, 0.5), 4),



            "confounding_paths": _random233.randint(5, 30),



        }



        do_application = {



            "variables_intervened": _random233.randint(1, 8),



            "conditional_set_size": _random233.randint(0, 5),



            "distribution_shift": round(_random233.uniform(0.01, 0.3), 4),



        }



        post_state = {



            "active_nodes": _random233.randint(50, 200),



            "active_edges": _random233.randint(80, 450),



            "causal_density": round(_random233.uniform(0.05, 0.4), 4),



            "confounding_paths": _random233.randint(0, 15),



        }



        steps.append({



            "step": s + 1,



            "intervention_strength": round(intervention_strength * (1 - 0.1 * s / max(num_steps, 1)), 4),



            "pre_intervention_state": pre_state,



            "do_application": do_application,



            "post_intervention_state": post_state,



            "effect_magnitude": round(_random233.uniform(0.1, 0.8), 4),



            "residual_confounding": round(_random233.uniform(0.0, 0.15), 4),



        })



    execution = {



        "graph_id": graph_id,



        "strategy": strategy.value,



        "scope": scope.value,



        "intervention_strength": intervention_strength,



        "total_steps": num_steps,



        "steps": steps,



        "total_effect": round(_random233.uniform(0.3, 0.9), 4),



        "confounding_reduction": round(_random233.uniform(0.5, 0.95), 4),



        "topology_impact": round(_random233.uniform(0.2, 0.7), 4),



    }



    return execution











def _compute_topo_intervention_propagate(



    graph_id: str,



    pathway_type: CausalPathway,



    effect_estimator: EffectEstimator,



    propagation_depth: int,



):



    """Propagate intervention effects through graph topology."""



    _random233.seed(hash(graph_id) % (2**31))



    estimators = {



        EffectEstimator.ATE: {"bias_correction": True, "variance_reduction": "ipw", "robustness": "high"},



        EffectEstimator.ITE: {"personalization": True, "heterogeneity": "captured", "robustness": "medium"},



        EffectEstimator.CATE: {"conditioning_vars": 3, "subgroup_analysis": True, "robustness": "high"},



        EffectEstimator.QTE: {"quantile_levels": [0.25, 0.5, 0.75], "distribution_free": True, "robustness": "medium"},



        EffectEstimator.DET: {"distribution_sensitive": True, "wasserstein_metric": True, "robustness": "low"},



        EffectEstimator.DISTRIBUTIONAL: {"full_distribution": True, "ks_test": True, "robustness": "high"},



    }



    est_cfg = estimators[effect_estimator]



    layers = []



    for d in range(propagation_depth):



        affected_nodes = _random233.randint(5, 30) * (d + 1)



        affected_edges = _random233.randint(10, 60) * (d + 1)



        effect_at_layer = round(max(0.01, _random233.uniform(0.2, 0.8) * (0.85 ** d)), 4)



        pathway_edges = []



        for e in range(_random233.randint(2, 8)):



            pathway_edges.append({



                "source": f"node_{_random233.randint(1, 50)}",



                "target": f"node_{_random233.randint(1, 50)}",



                "pathway_type": pathway_type.value,



                "flow_magnitude": round(_random233.uniform(0.1, 1.0), 4),



            })



        layers.append({



            "depth": d + 1,



            "affected_nodes": affected_nodes,



            "affected_edges": affected_edges,



            "effect_magnitude": effect_at_layer,



            "decay_factor": round(0.85 ** d, 4),



            "pathway_edges": pathway_edges,



            "spillover_effect": round(_random233.uniform(0.01, 0.1), 4),



            "attenuation_ratio": round(1.0 / (1 + d * 0.3), 4),



        })



    propagation = {



        "graph_id": graph_id,



        "pathway_type": pathway_type.value,



        "effect_estimator": effect_estimator.value,



        "estimator_config": est_cfg,



        "propagation_depth": propagation_depth,



        "layers": layers,



        "total_reach": sum(l["affected_nodes"] for l in layers),



        "cumulative_effect": round(sum(l["effect_magnitude"] for l in layers) / len(layers), 4),



        "propagation_efficiency": round(_random233.uniform(0.5, 0.9), 4),



    }



    return propagation











def _compute_topo_intervention_optimize(



    graph_id: str,



    topology_feature: TopologyFeature,



    outcome_metric: OutcomeMetric,



    budget: int,



):



    """Optimize intervention placement via topology analysis."""



    _random233.seed(hash(graph_id) % (2**31))



    metrics = {



        OutcomeMetric.INTERVENTION_EFFECT: {"weight": 0.35, "direction": "maximize"},



        OutcomeMetric.TOPOLOGY_PRESERVATION: {"weight": 0.20, "direction": "maximize"},



        OutcomeMetric.CAUSAL_CONSISTENCY: {"weight": 0.25, "direction": "maximize"},



        OutcomeMetric.INTERVENTION_ROBUSTNESS: {"weight": 0.10, "direction": "maximize"},



        OutcomeMetric.COMPLIANCE_SCORE: {"weight": 0.05, "direction": "maximize"},



        OutcomeMetric.INFORMATION_GAIN: {"weight": 0.05, "direction": "maximize"},



    }



    met_cfg = metrics[outcome_metric]



    candidates = []



    for c in range(_random233.randint(8, 20)):



        topo_score = round(_random233.uniform(0.2, 1.0), 4)



        causal_impact = round(_random233.uniform(0.1, 0.9), 4)



        cost = _random233.randint(1, budget)



        candidates.append({



            "candidate_id": f"cand_{c+1}",



            "topology_score": topo_score,



            "causal_impact": causal_impact,



            "intervention_cost": cost,



            "expected_effect": round(topo_score * causal_impact, 4),



            "roi": round(topo_score * causal_impact / max(cost, 1), 4),



        })



    candidates.sort(key=lambda x: x["expected_effect"], reverse=True)



    selected = candidates[:min(len(candidates), budget)]



    pareto_frontier = []



    for c in candidates:



        dominated = False



        for other in candidates:



            if (other["expected_effect"] >= c["expected_effect"]



                    and other["intervention_cost"] <= c["intervention_cost"]



                    and (other["expected_effect"] > c["expected_effect"]



                         or other["intervention_cost"] < c["intervention_cost"])):



                dominated = True



                break



        if not dominated:



            pareto_frontier.append(c)



    optimization = {



        "graph_id": graph_id,



        "topology_feature": topology_feature.value,



        "outcome_metric": outcome_metric.value,



        "metric_config": met_cfg,



        "budget": budget,



        "total_candidates": len(candidates),



        "selected_interventions": selected,



        "pareto_frontier_size": len(pareto_frontier),



        "pareto_frontier": pareto_frontier[:10],



        "total_expected_effect": round(sum(s["expected_effect"] for s in selected), 4),



        "total_cost": sum(s["intervention_cost"] for s in selected),



        "optimization_efficiency": round(sum(s["expected_effect"] for s in selected) / max(sum(s["intervention_cost"] for s in selected), 1), 4),



    }



    return optimization











def _compute_topo_intervention_validate(



    graph_id: str,



    strategy: InterventionStrategy,



    effect_estimator: EffectEstimator,



    num_bootstrap: int,



):



    """Validate intervention with topology-constrained analysis."""



    _random233.seed(hash(graph_id) % (2**31))



    bootstrap_results = []



    for b in range(num_bootstrap):



        sample_effect = round(_random233.uniform(0.1, 0.9), 4)



        sample_se = round(_random233.uniform(0.01, 0.1), 4)



        ci_lower = round(max(0, sample_effect - 1.96 * sample_se), 4)



        ci_upper = round(min(1, sample_effect + 1.96 * sample_se), 4)



        bootstrap_results.append({



            "bootstrap_id": b + 1,



            "estimated_effect": sample_effect,



            "standard_error": sample_se,



            "ci_95": [ci_lower, ci_upper],



            "p_value": round(_random233.uniform(0.001, 0.1), 4),



        })



    effects = [b["estimated_effect"] for b in bootstrap_results]



    mean_effect = round(sum(effects) / len(effects), 4)



    variance = round(sum((e - mean_effect) ** 2 for e in effects) / len(effects), 6)



    std_effect = round(variance ** 0.5, 4)



    validation = {



        "graph_id": graph_id,



        "strategy": strategy.value,



        "effect_estimator": effect_estimator.value,



        "num_bootstrap": num_bootstrap,



        "bootstrap_results": bootstrap_results,



        "mean_effect": mean_effect,



        "standard_deviation": std_effect,



        "ci_95_aggregate": [round(max(0, mean_effect - 1.96 * std_effect), 4), round(min(1, mean_effect + 1.96 * std_effect), 4)],



        "p_value_aggregate": round(_random233.uniform(0.001, 0.05), 4),



        "topology_constraint_satisfied": _random233.choice([True, True, True, False]),



        "identifiability_verified": _random233.choice([True, True, False]),



        "validation_grade": "A" if mean_effect > 0.7 else "B" if mean_effect > 0.4 else "C",



    }



    return validation











def _compute_topo_intervention_counterfactual(



    graph_id: str,



    pathway_type: CausalPathway,



    scope: InterventionScope,



    num_worlds: int,



):



    """Counterfactual reasoning under topology constraints."""



    _random233.seed(hash(graph_id) % (2**31))



    pathways_cfg = {



        CausalPathway.DIRECT: {"hops": 1, "mediation": False, "confounding_risk": "low"},



        CausalPathway.INDIRECT: {"hops": 3, "mediation": True, "confounding_risk": "medium"},



        CausalPathway.SPURIOUS: {"hops": 2, "mediation": False, "confounding_risk": "high"},



        CausalPathway.MEDIATED: {"hops": 2, "mediation": True, "confounding_risk": "medium"},



        CausalPathway.MODERATED: {"hops": 2, "mediation": False, "confounding_risk": "medium"},



        CausalPathway.FEEDBACK: {"hops": 4, "mediation": True, "confounding_risk": "high"},



    }



    pw_cfg = pathways_cfg[pathway_type]



    worlds = []



    for w in range(num_worlds):



        factual_value = round(_random233.uniform(0.3, 0.9), 4)



        counterfactual_value = round(_random233.uniform(0.1, 0.7), 4)



        ate = round(factual_value - counterfactual_value, 4)



        worlds.append({



            "world_id": w + 1,



            "factual_outcome": factual_value,



            "counterfactual_outcome": counterfactual_value,



            "individual_treatment_effect": ate,



            "necessity_score": round(_random233.uniform(0.5, 1.0), 4),



            "sufficiency_score": round(_random233.uniform(0.4, 0.95), 4),



            "topology_constraint_violated": _random233.choice([False, False, False, True]),



            "pathway_integrity": round(_random233.uniform(0.6, 1.0), 4),



        })



    counterfactual = {



        "graph_id": graph_id,



        "pathway_type": pathway_type.value,



        "pathway_config": pw_cfg,



        "scope": scope.value,



        "num_counterfactual_worlds": num_worlds,



        "worlds": worlds,



        "average_treatment_effect": round(sum(w["individual_treatment_effect"] for w in worlds) / len(worlds), 4),



        "necessity_probability": round(sum(w["necessity_score"] for w in worlds) / len(worlds), 4),



        "sufficiency_probability": round(sum(w["sufficiency_score"] for w in worlds) / len(worlds), 4),



        "counterfactual_consistency": round(_random233.uniform(0.6, 0.95), 4),



    }



    return counterfactual











