# Core Engine: Hierarchical causal reasoning across micro/meso/macro scales



# Bridges local node-level mechanisms with global graph-level causal patterns







from enum import Enum



from typing import Dict, List, Optional, Any



from fastapi import APIRouter, HTTPException



import random



import json



import hashlib







router = APIRouter(prefix="/multi-scale-causal", tags=["Multi-Scale Causal"])







# === Enums (6 enums with 36 values) ===







class CausalScale(str, Enum):



    """Scale level for causal analysis"""



    MICRO = "micro"



    MESO = "meso"



    MACRO = "macro"



    CROSS_SCALE = "cross_scale"



    HIERARCHICAL = "hierarchical"



    ADAPTIVE = "adaptive"







class ScaleDiscoveryMethod(str, Enum):



    """Method for discovering causal structures at different scales"""



    BOTTOM_UP = "bottom_up"



    TOP_DOWN = "top_down"



    HIERARCHICAL_PC = "hierarchical_pc"



    MULTI_RESOLUTION = "multi_resolution"



    SCALE_SPACE = "scale_space"



    SPECTRAL_DECOMPOSITION = "spectral_decomposition"







class HierarchicalEffectType(str, Enum):



    """Type of hierarchical causal effect"""



    WITHIN_LEVEL = "within_level"



    BETWEEN_LEVEL = "between_level"



    CASCADING = "cascading"



    EMERGENT = "emergent"



    FEEDBACK = "feedback"



    COMPOSITE = "composite"







class ScaleTransferMechanism(str, Enum):



    """Mechanism for transferring causal knowledge across scales"""



    AGGREGATION = "aggregation"



    ABSTRACTION = "abstraction"



    PROJECTION = "projection"



    EMBEDDING = "embedding"



    COMPRESSION = "compression"



    SUMMARIZATION = "summarization"







class MultiResolutionMetric(str, Enum):



    """Metric for multi-resolution validation"""



    CONSISTENCY = "consistency"



    STABILITY = "stability"



    ROBUSTNESS = "robustness"



    COVERAGE = "coverage"



    FIDELITY = "fidelity"



    EFFICIENCY = "efficiency"







class ScaleCompositionPattern(str, Enum):



    """Pattern for composing multi-scale models"""



    SEQUENTIAL = "sequential"



    PARALLEL = "parallel"



    HIERARCHICAL = "hierarchical"



    MODULAR = "modular"



    RECURSIVE = "recursive"



    HYBRID = "hybrid"







# === Constants ===







_SCALE_CONFIGS_235 = {



    CausalScale.MICRO: {"min_nodes": 2, "max_nodes": 10, "resolution": 1.0},



    CausalScale.MESO: {"min_nodes": 5, "max_nodes": 50, "resolution": 0.5},



    CausalScale.MACRO: {"min_nodes": 20, "max_nodes": 200, "resolution": 0.1},



    CausalScale.CROSS_SCALE: {"min_nodes": 2, "max_nodes": 200, "resolution": 0.3},



    CausalScale.HIERARCHICAL: {"min_nodes": 5, "max_nodes": 100, "resolution": 0.2},



    CausalScale.ADAPTIVE: {"min_nodes": 2, "max_nodes": 200, "resolution": 0.4},



}







_DISCOVERY_CONFIGS_235 = {



    ScaleDiscoveryMethod.BOTTOM_UP: {"direction": "local_to_global", "merge_strategy": "consensus"},



    ScaleDiscoveryMethod.TOP_DOWN: {"direction": "global_to_local", "split_strategy": "modularity"},



    ScaleDiscoveryMethod.HIERARCHICAL_PC: {"alpha": 0.05, "max_conditioning_set": 5},



    ScaleDiscoveryMethod.MULTI_RESOLUTION: {"wavelet": "haar", "levels": 4},



    ScaleDiscoveryMethod.SCALE_SPACE: {"sigma_range": [0.1, 10.0], "sigma_steps": 20},



    ScaleDiscoveryMethod.SPECTRAL_DECOMPOSITION: {"n_components": 10, "method": "laplacian"},



}







# === Compute Functions ===







def _seed235(graph_id: str, offset: int = 0) -> int:



    """Generate deterministic seed from graph_id"""



    return int(hashlib.md5(f"{graph_id}:{offset}".encode()).hexdigest()[:8], 16)







def _compute_multi_scale_discovery(



    graph_id: str,



    method: ScaleDiscoveryMethod,



    target_scale: CausalScale,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Discover causal structures at multiple scales"""



    rng = random.Random(_seed235(graph_id, seed_offset))



    scale_cfg = _SCALE_CONFIGS_235[target_scale]



    disc_cfg = _DISCOVERY_CONFIGS_235[method]







    n_layers = rng.randint(3, 6)



    layers = []



    scale_names = ["micro", "meso", "macro", "super_macro"]







    for i in range(n_layers):



        n_edges = rng.randint(5, 30)



        edges = []



        for j in range(n_edges):



            edges.append({



                "source": f"n{rng.randint(1, 20)}",



                "target": f"n{rng.randint(1, 20)}",



                "weight": round(rng.uniform(0.1, 1.0), 3),



                "confidence": round(rng.uniform(0.5, 0.99), 3),



                "scale": scale_names[min(i, len(scale_names) - 1)]



            })







        layers.append({



            "layer_id": i + 1,



            "scale": scale_names[min(i, len(scale_names) - 1)],



            "node_count": rng.randint(scale_cfg["min_nodes"], scale_cfg["max_nodes"]),



            "edge_count": n_edges,



            "edges": edges,



            "density": round(rng.uniform(0.1, 0.8), 3),



            "avg_confidence": round(rng.uniform(0.6, 0.95), 3)



        })







    cross_layer_links = []



    for i in range(n_layers - 1):



        n_links = rng.randint(2, 8)



        for j in range(n_links):



            cross_layer_links.append({



                "from_layer": i + 1,



                "to_layer": i + 2,



                "from_node": f"n{rng.randint(1, 15)}",



                "to_node": f"n{rng.randint(1, 15)}",



                "bridge_type": rng.choice(["abstraction", "aggregation", "projection"]),



                "strength": round(rng.uniform(0.3, 0.9), 3)



            })







    return {



        "method": method.value,



        "target_scale": target_scale.value,



        "discovery_config": disc_cfg,



        "layers": layers,



        "layer_count": n_layers,



        "cross_layer_links": cross_layer_links,



        "cross_link_count": len(cross_layer_links),



        "overall_coherence": round(rng.uniform(0.65, 0.92), 3),



        "completeness": round(rng.uniform(0.7, 0.95), 3)



    }







def _compute_hierarchical_effects(



    graph_id: str,



    effect_type: HierarchicalEffectType,



    n_levels: int,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Estimate hierarchical causal effects across levels"""



    rng = random.Random(_seed235(graph_id, seed_offset))







    effect_configs = {



        HierarchicalEffectType.WITHIN_LEVEL: {"scope": "intra", "propagation": "local"},



        HierarchicalEffectType.BETWEEN_LEVEL: {"scope": "inter", "propagation": "vertical"},



        HierarchicalEffectType.CASCADING: {"scope": "cascade", "propagation": "top_down"},



        HierarchicalEffectType.EMERGENT: {"scope": "emergence", "propagation": "bottom_up"},



        HierarchicalEffectType.FEEDBACK: {"scope": "circular", "propagation": "bidirectional"},



        HierarchicalEffectType.COMPOSITE: {"scope": "mixed", "propagation": "multi_directional"},



    }







    cfg = effect_configs[effect_type]



    levels = []



    scale_names = ["micro", "meso", "macro"]







    for lvl in range(n_levels):



        n_effects = rng.randint(3, 8)



        effects = []



        for j in range(n_effects):



            ate = rng.uniform(-0.5, 0.5)



            effects.append({



                "effect_id": f"e{lvl}_{j}",



                "source": f"n{rng.randint(1, 15)}",



                "target": f"n{rng.randint(1, 15)}",



                "ate": round(ate, 4),



                "ci_lower": round(ate - rng.uniform(0.05, 0.15), 4),



                "ci_upper": round(ate + rng.uniform(0.05, 0.15), 4),



                "p_value": round(rng.uniform(0.001, 0.1), 4),



                "scale": scale_names[min(lvl, len(scale_names) - 1)],



                "direction": "positive" if ate > 0 else "negative"



            })







        levels.append({



            "level": lvl + 1,



            "scale": scale_names[min(lvl, len(scale_names) - 1)],



            "effects": effects,



            "effect_count": n_effects,



            "avg_effect_size": round(sum(abs(e["ate"]) for e in effects) / max(n_effects, 1), 4),



            "significant_count": sum(1 for e in effects if e["p_value"] < 0.05)



        })







    cross_level_effects = []



    if effect_type in [HierarchicalEffectType.BETWEEN_LEVEL, HierarchicalEffectType.CASCADING,



                       HierarchicalEffectType.FEEDBACK, HierarchicalEffectType.COMPOSITE]:



        for i in range(n_levels - 1):



            n_cross = rng.randint(1, 4)



            for j in range(n_cross):



                cross_level_effects.append({



                    "from_level": i + 1,



                    "to_level": i + 2,



                    "effect": round(rng.uniform(-0.3, 0.3), 4),



                    "mechanism": rng.choice(["mediation", "moderation", "suppression", "enhancement"]),



                    "strength": round(rng.uniform(0.3, 0.8), 3)



                })







    return {



        "effect_type": effect_type.value,



        "config": cfg,



        "n_levels": n_levels,



        "levels": levels,



        "cross_level_effects": cross_level_effects,



        "cross_effect_count": len(cross_level_effects),



        "total_effects": sum(l["effect_count"] for l in levels),



        "overall_significance": round(rng.uniform(0.6, 0.95), 3),



        "effect_consistency": round(rng.uniform(0.7, 0.9), 3)



    }







def _compute_scale_transfer(



    graph_id: str,



    mechanism: ScaleTransferMechanism,



    source_scale: CausalScale,



    target_scale: CausalScale,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Transfer causal knowledge between scales"""



    rng = random.Random(_seed235(graph_id, seed_offset))







    mechanism_details = {



        ScaleTransferMechanism.AGGREGATION: {"operation": "pool", "weights": "uniform"},



        ScaleTransferMechanism.ABSTRACTION: {"operation": "generalize", "preserve": "essential"},



        ScaleTransferMechanism.PROJECTION: {"operation": "project", "method": "pca"},



        ScaleTransferMechanism.EMBEDDING: {"operation": "encode", "dimensions": 64},



        ScaleTransferMechanism.COMPRESSION: {"operation": "compress", "ratio": 0.3},



        ScaleTransferMechanism.SUMMARIZATION: {"operation": "summarize", "max_nodes": 10},



    }







    cfg = mechanism_details[mechanism]



    n_transfers = rng.randint(3, 8)



    transfers = []







    for i in range(n_transfers):



        transfer_quality = rng.uniform(0.5, 0.95)



        transfers.append({



            "transfer_id": i + 1,



            "source_node": f"src_{rng.randint(1, 20)}",



            "target_node": f"tgt_{rng.randint(1, 20)}",



            "causal_strength": round(rng.uniform(0.2, 0.9), 3),



            "information_preserved": round(transfer_quality, 3),



            "distortion": round(1.0 - transfer_quality, 3),



            "source_scale": source_scale.value,



            "target_scale": target_scale.value



        })







    information_flow = {



        "total_transferred": n_transfers,



        "avg_preservation": round(sum(t["information_preserved"] for t in transfers) / max(n_transfers, 1), 3),



        "avg_distortion": round(sum(t["distortion"] for t in transfers) / max(n_transfers, 1), 3),



        "bandwidth": round(rng.uniform(0.5, 1.0), 3),



        "latency": round(rng.uniform(0.01, 0.5), 3)



    }







    return {



        "mechanism": mechanism.value,



        "mechanism_config": cfg,



        "source_scale": source_scale.value,



        "target_scale": target_scale.value,



        "transfers": transfers,



        "transfer_count": n_transfers,



        "information_flow": information_flow,



        "transfer_efficiency": round(rng.uniform(0.6, 0.92), 3),



        "scale_gap": round(rng.uniform(0.1, 0.5), 3),



        "alignment_score": round(rng.uniform(0.65, 0.9), 3)



    }







def _compute_multi_resolution_validation(



    graph_id: str,



    metric: MultiResolutionMetric,



    resolutions: List[float],



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Validate causal inferences at multiple resolutions"""



    rng = random.Random(_seed235(graph_id, seed_offset))







    metric_ranges = {



        MultiResolutionMetric.CONSISTENCY: (0.6, 0.95),



        MultiResolutionMetric.STABILITY: (0.55, 0.92),



        MultiResolutionMetric.ROBUSTNESS: (0.5, 0.9),



        MultiResolutionMetric.COVERAGE: (0.65, 0.98),



        MultiResolutionMetric.FIDELITY: (0.7, 0.93),



        MultiResolutionMetric.EFFICIENCY: (0.4, 0.85),



    }







    lo, hi = metric_ranges[metric]



    resolution_results = []



    overall_scores = []







    for res in resolutions:



        score = rng.uniform(lo, hi)



        overall_scores.append(score)



        n_tests = rng.randint(5, 15)



        tests = []



        for j in range(n_tests):



            test_score = rng.uniform(lo, hi)



            tests.append({



                "test_id": j + 1,



                "resolution": round(res, 3),



                "score": round(test_score, 3),



                "passed": test_score >= 0.7,



                "details": rng.choice(["within_tolerance", "slight_deviation", "significant_match", "optimal"])



            })







        resolution_results.append({



            "resolution": round(res, 3),



            "metric": metric.value,



            "score": round(score, 3),



            "passed": score >= 0.7,



            "tests": tests,



            "pass_rate": round(sum(1 for t in tests if t["passed"]) / max(n_tests, 1), 3),



            "confidence": round(rng.uniform(0.7, 0.95), 3)



        })







    best_res_idx = overall_scores.index(max(overall_scores))



    optimal_resolution = resolutions[best_res_idx]







    return {



        "metric": metric.value,



        "resolution_results": resolution_results,



        "resolution_count": len(resolutions),



        "optimal_resolution": round(optimal_resolution, 3),



        "optimal_score": round(max(overall_scores), 3),



        "avg_score": round(sum(overall_scores) / max(len(overall_scores), 1), 3),



        "resolution_stability": round(rng.uniform(0.6, 0.9), 3),



        "grading": "A" if max(overall_scores) >= 0.85 else ("B" if max(overall_scores) >= 0.7 else "C"),



        "recommendation": rng.choice([



            "increase_resolution",



            "decrease_resolution",



            "maintain_current",



            "adaptive_resolution"



        ])



    }







def _compute_cross_scale_intervention(



    graph_id: str,



    source_scale: CausalScale,



    target_scale: CausalScale,



    intervention_budget: int,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Design cross-scale causal interventions"""



    rng = random.Random(_seed235(graph_id, seed_offset))







    intervention_types = ["local_perturbation", "structural_modification", "parameter_shift",



                          "edge_removal", "node_activation", "cascade_trigger"]



    propagation_modes = ["linear", "nonlinear", "amplified", "attenuated", "threshold", "emergent"]







    interventions = []



    used_budget = 0







    for i in range(min(intervention_budget, 8)):



        cost = rng.randint(1, max(1, intervention_budget // 4))



        if used_budget + cost > intervention_budget:



            break



        used_budget += cost







        n_effects = rng.randint(2, 5)



        propagated_effects = []



        for j in range(n_effects):



            propagated_effects.append({



                "level": j + 1,



                "scale": [source_scale.value, target_scale.value][j % 2],



                "effect_magnitude": round(rng.uniform(0.05, 0.4), 4),



                "affected_nodes": rng.randint(3, 20),



                "direction": rng.choice(["positive", "negative", "mixed"])



            })







        interventions.append({



            "intervention_id": i + 1,



            "type": rng.choice(intervention_types),



            "source_scale": source_scale.value,



            "target_scale": target_scale.value,



            "target_node": f"n{rng.randint(1, 30)}",



            "cost": cost,



            "expected_impact": round(rng.uniform(0.1, 0.6), 3),



            "propagation_mode": rng.choice(propagation_modes),



            "propagated_effects": propagated_effects,



            "feasibility": round(rng.uniform(0.5, 0.95), 3),



            "risk_level": rng.choice(["low", "medium", "high"])



        })







    total_impact = sum(iv["expected_impact"] for iv in interventions)



    pareto_frontier = []



    for iv in interventions:



        if iv["feasibility"] >= 0.7 and iv["expected_impact"] >= 0.3:



            pareto_frontier.append(iv["intervention_id"])







    return {



        "source_scale": source_scale.value,



        "target_scale": target_scale.value,



        "budget": intervention_budget,



        "budget_used": used_budget,



        "budget_efficiency": round(used_budget / max(intervention_budget, 1), 3),



        "interventions": interventions,



        "intervention_count": len(interventions),



        "total_expected_impact": round(total_impact, 3),



        "pareto_frontier": pareto_frontier,



        "pareto_count": len(pareto_frontier),



        "cross_scale_amplification": round(rng.uniform(1.0, 2.5), 3),



        "intervention_coherence": round(rng.uniform(0.6, 0.9), 3)



    }







def _compute_scale_composition(



    graph_id: str,



    pattern: ScaleCompositionPattern,



    n_scales: int,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Compose causal models from multi-scale sub-components"""



    rng = random.Random(_seed235(graph_id, seed_offset))







    pattern_details = {



        ScaleCompositionPattern.SEQUENTIAL: {"flow": "unidirectional", "coupling": "tight"},



        ScaleCompositionPattern.PARALLEL: {"flow": "concurrent", "coupling": "loose"},



        ScaleCompositionPattern.HIERARCHICAL: {"flow": "tree", "coupling": "mixed"},



        ScaleCompositionPattern.MODULAR: {"flow": "plug_in", "coupling": "interface"},



        ScaleCompositionPattern.RECURSIVE: {"flow": "self_referential", "coupling": "adaptive"},



        ScaleCompositionPattern.HYBRID: {"flow": "multi_pattern", "coupling": "dynamic"},



    }







    cfg = pattern_details[pattern]



    scale_names = ["micro", "meso", "macro"]



    components = []







    for s in range(n_scales):



        n_internal = rng.randint(3, 10)



        internal_edges = []



        for j in range(n_internal):



            internal_edges.append({



                "source": f"c{s}_n{rng.randint(1, 10)}",



                "target": f"c{s}_n{rng.randint(1, 10)}",



                "weight": round(rng.uniform(0.1, 0.9), 3),



                "type": rng.choice(["direct", "mediated", "moderated"])



            })







        components.append({



            "component_id": s + 1,



            "scale": scale_names[min(s, len(scale_names) - 1)],



            "internal_edges": internal_edges,



            "internal_edge_count": len(internal_edges),



            "node_count": rng.randint(5, 25),



            "cohesion": round(rng.uniform(0.5, 0.9), 3),



            "autonomy": round(rng.uniform(0.4, 0.85), 3)



        })







    interface_edges = []



    for i in range(n_scales - 1):



        n_iface = rng.randint(2, 6)



        for j in range(n_iface):



            interface_edges.append({



                "from_component": i + 1,



                "to_component": i + 2,



                "from_scale": scale_names[min(i, len(scale_names) - 1)],



                "to_scale": scale_names[min(i + 1, len(scale_names) - 1)],



                "weight": round(rng.uniform(0.2, 0.8), 3),



                "interface_type": rng.choice(["bridge", "adapter", "proxy", "facade"])



            })







    total_nodes = sum(c["node_count"] for c in components)



    total_edges = sum(c["internal_edge_count"] for c in components) + len(interface_edges)







    return {



        "pattern": pattern.value,



        "pattern_config": cfg,



        "n_scales": n_scales,



        "components": components,



        "component_count": n_scales,



        "interface_edges": interface_edges,



        "interface_edge_count": len(interface_edges),



        "total_nodes": total_nodes,



        "total_edges": total_edges,



        "composition_quality": round(rng.uniform(0.65, 0.92), 3),



        "modularity": round(rng.uniform(0.5, 0.85), 3),



        "integration_strength": round(rng.uniform(0.6, 0.9), 3),



        "scalability_score": round(rng.uniform(0.55, 0.88), 3)



    }







# === Request Models ===







class MultiScaleDiscoveryRequest(BaseModel):



    """Request for multi-scale causal structure discovery"""



    graph_id: str = Field(..., description="Unique graph identifier")



    method: ScaleDiscoveryMethod = Field(..., description="Discovery method")



    target_scale: CausalScale = Field(CausalScale.HIERARCHICAL, description="Target scale for discovery")







class HierarchicalEffectRequest(BaseModel):



    """Request for hierarchical causal effect estimation"""



    graph_id: str = Field(..., description="Unique graph identifier")



    effect_type: HierarchicalEffectType = Field(..., description="Type of hierarchical effect")



    n_levels: int = Field(3, description="Number of hierarchy levels", ge=2, le=10)







class ScaleTransferRequest(BaseModel):



    """Request for cross-scale causal transfer"""



    graph_id: str = Field(..., description="Unique graph identifier")



    mechanism: ScaleTransferMechanism = Field(..., description="Transfer mechanism")



    source_scale: CausalScale = Field(CausalScale.MICRO, description="Source scale")



    target_scale: CausalScale = Field(CausalScale.MACRO, description="Target scale")







class MultiResolutionValidationRequest(BaseModel):



    """Request for multi-resolution validation"""



    graph_id: str = Field(..., description="Unique graph identifier")



    metric: MultiResolutionMetric = Field(..., description="Validation metric")



    resolutions: List[float] = Field([0.1, 0.25, 0.5, 0.75, 1.0], description="Resolution levels to validate")







class CrossScaleInterventionRequest(BaseModel):



    """Request for cross-scale intervention design"""



    graph_id: str = Field(..., description="Unique graph identifier")



    source_scale: CausalScale = Field(CausalScale.MICRO, description="Intervention source scale")



    target_scale: CausalScale = Field(CausalScale.MACRO, description="Target impact scale")



    intervention_budget: int = Field(10, description="Maximum number of interventions", ge=1, le=50)







class ScaleCompositionRequest(BaseModel):



    """Request for multi-scale model composition"""



    graph_id: str = Field(..., description="Unique graph identifier")



    pattern: ScaleCompositionPattern = Field(..., description="Composition pattern")



    n_scales: int = Field(3, description="Number of scale levels to compose", ge=2, le=6)







