_discovery_cache: Dict[str, Dict[str, Any]] = {}



_hierarchical_cache: Dict[str, Dict[str, Any]] = {}



_transfer_cache: Dict[str, Dict[str, Any]] = {}



_validation_cache: Dict[str, Dict[str, Any]] = {}



_intervention_cache: Dict[str, Dict[str, Any]] = {}



_composition_cache: Dict[str, Dict[str, Any]] = {}







