@router.post("/discovery")



async def discover_multi_scale(request: MultiScaleDiscoveryRequest):



    """Discover causal structures at multiple scales"""



    cache_key = f"{request.graph_id}:{request.method.value}:{request.target_scale.value}"







    if cache_key not in _discovery_cache:



        result = _compute_multi_scale_discovery(



            request.graph_id,



            request.method,



            request.target_scale



        )







        _discovery_cache[cache_key] = {



            "graph_id": request.graph_id,



            "method": request.method.value,



            "target_scale": request.target_scale.value,



            "discovery": result,



            "timestamp": random.randint(1700000000, 1800000000)



        }







    return _discovery_cache[cache_key]







@router.post("/hierarchical-effects")



async def estimate_hierarchical_effects(request: HierarchicalEffectRequest):



    """Estimate hierarchical causal effects across levels"""



    cache_key = f"{request.graph_id}:{request.effect_type.value}:{request.n_levels}"







    if cache_key not in _hierarchical_cache:



        result = _compute_hierarchical_effects(



            request.graph_id,



            request.effect_type,



            request.n_levels,



            seed_offset=100



        )







        _hierarchical_cache[cache_key] = {



            "graph_id": request.graph_id,



            "effect_type": request.effect_type.value,



            "n_levels": request.n_levels,



            "effects": result,



            "timestamp": random.randint(1700000000, 1800000000)



        }







    return _hierarchical_cache[cache_key]







