class SynthesisStrategy(str, Enum):



    """Strategy for synthesizing causal analysis programs"""



    TEMPLATE_BASED = "template_based"



    CONSTRAINT_DRIVEN = "constraint_driven"



    EXAMPLE_GUIDED = "example_guided"



    NEURO_SYMBOLIC = "neuro_symbolic"



    LLM_ASSISTED = "llm_assisted"



    EVOLUTIONARY = "evolutionary"







class ProgramLanguage(str, Enum):



    """Target programming language for synthesized programs"""



    PYTHON = "python"



    R = "r"



    JULIA = "julia"



    MATLAB = "matlab"



    SQL = "sql"



    DSL = "dsl"







class VerificationMethod(str, Enum):



    """Method for verifying synthesized programs"""



    TYPE_CHECK = "type_check"



    RUNTIME_TEST = "runtime_test"



    FORMAL_PROOF = "formal_proof"



    COUNTEREXAMPLE = "counterexample"



    PROPERTY_CHECK = "property_check"



    EQUIVALENCE = "equivalence"







class OptimizationTarget(str, Enum):



    """Optimization target for program refinement"""



    CORRECTNESS = "correctness"



    EFFICIENCY = "efficiency"



    READABILITY = "readability"



    COMPOSABILITY = "composability"



    ROBUSTNESS = "robustness"



    INTERPRETABILITY = "interpretability"







class CompositionMode(str, Enum):



    """Mode for composing program components"""



    SEQUENTIAL = "sequential"



    PARALLEL = "parallel"



    CONDITIONAL = "conditional"



    ITERATIVE = "iterative"



    RECURSIVE = "recursive"



    MODULAR = "modular"







class ExecutionEnvironment(str, Enum):



    """Execution environment for synthesized programs"""



    LOCAL = "local"



    SANDBOX = "sandbox"



    DISTRIBUTED = "distributed"



    GPU_ENABLED = "gpu_enabled"



    STREAMING = "streaming"



    INTERACTIVE = "interactive"







