class TemporalGranularity(str, Enum):



    """Time granularity for temporal causal analysis"""



    TICK = "tick"                     # Discrete time steps



    SECOND = "second"                 # Second-level resolution



    MINUTE = "minute"                 # Minute-level resolution



    HOUR = "hour"                     # Hour-level resolution



    DAY = "day"                       # Day-level resolution



    ADAPTIVE = "adaptive"             # Auto-determined granularity











class CausalTransition(str, Enum):



    """Types of causal structure transitions"""



    EDGE_APPEARANCE = "edge_appearance"       # New causal edge forms



    EDGE_DISAPPEARANCE = "edge_disappearance" # Causal edge vanishes



    STRENGTH_CHANGE = "strength_change"       # Causal effect magnitude shifts



    DIRECTION_REVERSAL = "direction_reversal" # Cause-effect direction flips



    FEEDBACK_LOOP = "feedback_loop"           # Cyclic causal feedback emerges



    LATENT_ACTIVATION = "latent_activation"   # Hidden cause becomes active











class TemporalPattern(str, Enum):



    """Temporal patterns in causal dynamics"""



    PERIODIC = "periodic"                     # Recurring causal oscillation



    TREND = "trend"                           # Monotonic causal drift



    REGIME_SHIFT = "regime_shift"             # Abrupt structural change



    SEASONAL = "seasonal"                     # Seasonal causal variation



    INTERMITTENT = "intermittent"             # On-off causal activation



    CUMULATIVE = "cumulative"                 # Accumulating causal effect











class InterventionTiming(str, Enum):



    """Timing strategies for temporal interventions"""



    IMMEDIATE = "immediate"                   # Apply at current time step



    DELAYED = "delayed"                       # Apply after specified lag



    SCHEDULED = "scheduled"                   # Apply at specific future time



    CONDITIONAL = "conditional"               # Apply when condition met



    RECURRING = "recurring"                   # Repeated periodic application



    OPTIMAL = "optimal"                       # Computed optimal timing











class DriftDetector(str, Enum):



    """Methods for detecting causal drift"""



    PAGE_HINKLEY = "page_hinkley"             # Page-Hinkley test



    CUSUM = "cusum"                           # Cumulative sum control chart



    ADWIN = "adwin"                           # Adaptive windowing



    KULLBACK_LEIBLER = "kl_divergence"        # KL divergence monitoring



    MANN_WHITNEY = "mann_whitney"             # Mann-Whitney U test



    KERNEL_MMD = "kernel_mmd"                 # Kernel maximum mean discrepancy











class ForecastHorizon(str, Enum):



    """Forecast horizons for causal prediction"""



    SHORT_TERM = "short_term"                 # 1-5 steps ahead



    MEDIUM_TERM = "medium_term"               # 6-20 steps ahead



    LONG_TERM = "long_term"                   # 21-100 steps ahead



    EXTENDED = "extended"                     # 100+ steps ahead



    MULTI_SCALE = "multi_scale"               # Combined multi-horizon



    EVENT_DRIVEN = "event_driven"             # Until next regime shift











