def _seed238(graph_id: str, offset: int = 0) -> int:



    return abs(hash(f"temporal_causal_{graph_id}_{offset}")) % (2**31)











# Request models



class TemporalEvolutionRequest(BaseModel):



    graph_id: str



    granularity: TemporalGranularity = TemporalGranularity.TICK



    n_steps: int = 50



    transition_types: List[CausalTransition] = [CausalTransition.STRENGTH_CHANGE]







class DriftDetectionRequest(BaseModel):



    graph_id: str



    detector: DriftDetector



    window_size: int = 20



    sensitivity: float = 0.05



    edges: List[str] = []







class TemporalForecastRequest(BaseModel):



    graph_id: str



    horizon: ForecastHorizon = ForecastHorizon.SHORT_TERM



    n_steps_ahead: int = 10



    confidence_level: float = 0.95







class TimedInterventionRequest(BaseModel):



    graph_id: str



    timing: InterventionTiming = InterventionTiming.IMMEDIATE



    target_node: str = ""



    delay_steps: int = 0



    n_interventions: int = 3







class TemporalPatternRequest(BaseModel):



    graph_id: str



    pattern: TemporalPattern = TemporalPattern.PERIODIC



    analysis_window: int = 100



    min_occurrences: int = 3







class CausalLifecycleRequest(BaseModel):



    graph_id: str



    edge_id: str = ""



    granularity: TemporalGranularity = TemporalGranularity.TICK











# Caches



_evolution_cache: Dict[str, Any] = {}



_drift_cache: Dict[str, Any] = {}



_forecast_cache: Dict[str, Any] = {}



_intervention_cache: Dict[str, Any] = {}



_pattern_cache: Dict[str, Any] = {}



_lifecycle_cache: Dict[str, Any] = {}











# Compute functions



def _compute_temporal_evolution(



    graph_id: str,



    granularity: TemporalGranularity,



    n_steps: int,



    transition_types: List[CausalTransition],



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Simulate temporal evolution of causal graph structure"""



    rng = random.Random(_seed238(graph_id, seed_offset))



    gran_cfg = _TEMPORAL_CONFIGS_238[granularity]







    transitions = []



    for i in range(rng.randint(3, min(n_steps // 5, 20))):



        t_type = rng.choice(transition_types)



        t_cfg = _TRANSITION_CONFIGS_238[t_type]



        step = rng.randint(1, n_steps)







        source = f"var_{rng.randint(1, 12)}"



        target = f"var_{rng.randint(1, 12)}"



        while target == source:



            target = f"var_{rng.randint(1, 12)}"







        old_strength = round(rng.uniform(0.1, 0.95), 3)



        new_strength = round(max(0.01, old_strength + rng.uniform(-0.4, 0.4)), 3)







        transitions.append({



            "step": step,



            "type": t_type.value,



            "description": t_cfg["description"],



            "source": source,



            "target": target,



            "old_strength": old_strength,



            "new_strength": new_strength,



            "confidence": round(rng.uniform(0.6, 0.99), 3),



            "reversibility": t_cfg["reversibility"],



            "duration_estimate": rng.randint(1, max(2, n_steps // 10)),



        })







    transitions.sort(key=lambda x: x["step"])







    # Snapshot analysis at key time points



    n_snapshots = min(6, max(3, n_steps // 20))



    snapshot_interval = max(1, n_steps // n_snapshots)



    snapshots = []



    for s_idx in range(n_snapshots):



        t = (s_idx + 1) * snapshot_interval



        n_edges = rng.randint(8, 25)



        n_active = rng.randint(5, n_edges)



        n_emerging = rng.randint(0, 4)



        n_vanishing = rng.randint(0, 3)







        snapshots.append({



            "time_step": t,



            "total_edges": n_edges,



            "active_edges": n_active,



            "emerging_edges": n_emerging,



            "vanishing_edges": n_vanishing,



            "avg_strength": round(rng.uniform(0.3, 0.8), 3),



            "graph_density": round(rng.uniform(0.1, 0.5), 3),



            "connectivity": round(rng.uniform(0.5, 1.0), 3),



            "feedback_loops": rng.randint(0, 3),



            "d_separation_changes": rng.randint(0, 5),



        })







    # Stability metrics over time



    stability_profile = {



        "structural_stability": round(rng.uniform(0.4, 0.95), 3),



        "effect_consistency": round(rng.uniform(0.5, 0.9), 3),



        "intervention_durability": round(rng.uniform(0.3, 0.85), 3),



        "prediction_reliability": round(rng.uniform(0.4, 0.9), 3),



        "adaptation_rate": round(rng.uniform(0.1, 0.7), 3),



    }







    return {



        "graph_id": graph_id,



        "granularity": granularity.value,



        "granularity_info": gran_cfg,



        "n_steps": n_steps,



        "n_transitions": len(transitions),



        "transitions": transitions,



        "snapshots": snapshots,



        "stability_profile": stability_profile,



        "temporal_complexity": round(rng.uniform(0.2, 0.9), 3),



        "evolution_regime": rng.choice(["stable", "slowly_changing", "rapidly_changing", "chaotic"]),



    }











def _compute_drift_detection(



    graph_id: str,



    detector: DriftDetector,



    window_size: int,



    sensitivity: float,



    edges: List[str],



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Detect causal drift in temporal graph data"""



    rng = random.Random(_seed238(graph_id, seed_offset))







    detector_methods = {



        DriftDetector.PAGE_HINKLEY: {"statistic": "cumulative_sum", "threshold_type": "adaptive"},



        DriftDetector.CUSUM: {"statistic": "sequential_ratio", "threshold_type": "fixed"},



        DriftDetector.ADWIN: {"statistic": "window_mean_diff", "threshold_type": "adaptive"},



        DriftDetector.KULLBACK_LEIBLER: {"statistic": "kl_divergence", "threshold_type": "percentile"},



        DriftDetector.MANN_WHITNEY: {"statistic": "u_statistic", "threshold_type": "p_value"},



        DriftDetector.KERNEL_MMD: {"statistic": "mmd_squared", "threshold_type": "bootstrap"},



    }







    det_cfg = detector_methods[detector]



    target_edges = edges if edges else [f"edge_{i}" for i in range(rng.randint(3, 8))]







    edge_drifts = []



    for edge in target_edges:



        n_windows = rng.randint(5, 15)



        drift_detected = rng.random() < 0.6







        windows = []



        for w in range(n_windows):



            windows.append({



                "window_start": w * window_size,



                "window_end": (w + 1) * window_size,



                "statistic_value": round(rng.uniform(-2, 5), 4),



                "threshold": round(rng.uniform(1.0, 3.0), 4),



                "p_value": round(rng.uniform(0.001, 0.15), 4),



                "drift_flag": rng.random() < 0.3,



            })







        if drift_detected:



            change_point = rng.randint(2, n_windows - 1)



            pre_drift_mean = round(rng.uniform(0.2, 0.6), 3)



            post_drift_mean = round(pre_drift_mean + rng.uniform(-0.3, 0.3), 3)



        else:



            change_point = None



            pre_drift_mean = round(rng.uniform(0.3, 0.7), 3)



            post_drift_mean = pre_drift_mean







        edge_drifts.append({



            "edge": edge,



            "drift_detected": drift_detected,



            "change_point": change_point,



            "pre_drift_mean": pre_drift_mean,



            "post_drift_mean": post_drift_mean,



            "magnitude": round(abs(post_drift_mean - pre_drift_mean), 3) if drift_detected else 0.0,



            "direction": "increase" if post_drift_mean > pre_drift_mean else "decrease" if drift_detected else "stable",



            "significance": round(rng.uniform(0.01, 0.05), 4) if drift_detected else None,



            "windows_analyzed": n_windows,



            "window_details": windows,



        })







    total_drifts = sum(1 for d in edge_drifts if d["drift_detected"])



    avg_magnitude = round(



        sum(d["magnitude"] for d in edge_drifts if d["drift_detected"]) / max(1, total_drifts), 3



    )







    return {



        "graph_id": graph_id,



        "detector": detector.value,



        "detector_config": det_cfg,



        "window_size": window_size,



        "sensitivity": sensitivity,



        "edges_monitored": len(target_edges),



        "edge_drifts": edge_drifts,



        "summary": {



            "total_edges": len(target_edges),



            "drifting_edges": total_drifts,



            "stable_edges": len(target_edges) - total_drifts,



            "drift_rate": round(total_drifts / len(target_edges), 3),



            "average_magnitude": avg_magnitude,



            "overall_status": "critical" if total_drifts > len(target_edges) * 0.5 else "warning" if total_drifts > 0 else "stable",



        }



    }











def _compute_temporal_forecast(



    graph_id: str,



    horizon: ForecastHorizon,



    n_steps_ahead: int,



    confidence_level: float,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Forecast future causal graph states"""



    rng = random.Random(_seed238(graph_id, seed_offset))







    horizon_cfgs = {



        ForecastHorizon.SHORT_TERM: {"steps": (1, 5), "confidence": "high", "methods": ["AR", "ETS"]},



        ForecastHorizon.MEDIUM_TERM: {"steps": (6, 20), "confidence": "medium", "methods": ["VAR", "ARIMA"]},



        ForecastHorizon.LONG_TERM: {"steps": (21, 100), "confidence": "low", "methods": ["LSTM", "Transformer"]},



        ForecastHorizon.EXTENDED: {"steps": (100, 500), "confidence": "very_low", "methods": ["Simulation", "Ensemble"]},



        ForecastHorizon.MULTI_SCALE: {"steps": (1, 100), "confidence": "variable", "methods": ["Multi-Resolution"]},



        ForecastHorizon.EVENT_DRIVEN: {"steps": "until_event", "confidence": "conditional", "methods": ["Survival", "Hazard"]},



    }



    h_cfg = horizon_cfgs[horizon]







    # Forecast edge trajectories



    n_forecast_edges = rng.randint(4, 10)



    edge_forecasts = []



    for i in range(n_forecast_edges):



        base_strength = round(rng.uniform(0.2, 0.8), 3)



        trend = rng.choice([-0.02, -0.01, 0, 0.01, 0.02])



        forecast_points = []



        for t in range(1, n_steps_ahead + 1):



            pred = max(0.01, min(1.0, base_strength + trend * t + rng.gauss(0, 0.02)))



            half_width = rng.uniform(0.05, 0.15) * (1 + t * 0.05)



            forecast_points.append({



                "step": t,



                "predicted_strength": round(pred, 3),



                "lower_bound": round(max(0.01, pred - half_width), 3),



                "upper_bound": round(min(1.0, pred + half_width), 3),



            })







        edge_forecasts.append({



            "edge": f"var_{rng.randint(1, 10)}→var_{rng.randint(1, 10)}",



            "current_strength": base_strength,



            "trend_direction": "increasing" if trend > 0 else "decreasing" if trend < 0 else "stable",



            "trend_magnitude": round(abs(trend), 4),



            "volatility": round(rng.uniform(0.01, 0.1), 3),



            "forecast_points": forecast_points,



            "terminal_strength": round(forecast_points[-1]["predicted_strength"], 3) if forecast_points else base_strength,



        })







    # Structural change predictions



    n_predicted_changes = rng.randint(1, 6)



    predicted_changes = []



    for i in range(n_predicted_changes):



        predicted_changes.append({



            "predicted_step": rng.randint(1, n_steps_ahead),



            "change_type": rng.choice([t.value for t in CausalTransition]),



            "affected_edge": f"var_{rng.randint(1, 10)}→var_{rng.randint(1, 10)}",



            "probability": round(rng.uniform(0.3, 0.95), 3),



            "estimated_impact": round(rng.uniform(0.1, 0.7), 3),



            "confidence": round(rng.uniform(0.4, 0.9), 3),



        })



    predicted_changes.sort(key=lambda x: x["predicted_step"])







    # Forecast quality metrics



    quality = {



        "mean_absolute_error_estimate": round(rng.uniform(0.01, 0.1), 3),



        "coverage_probability": round(rng.uniform(0.85, 0.99), 3),



        "sharpness": round(rng.uniform(0.03, 0.15), 3),



        "calibration_score": round(rng.uniform(0.7, 0.98), 3),



        "crps_estimate": round(rng.uniform(0.02, 0.12), 3),



    }







    return {



        "graph_id": graph_id,



        "horizon": horizon.value,



        "horizon_config": h_cfg,



        "n_steps_ahead": n_steps_ahead,



        "confidence_level": confidence_level,



        "n_edges_forecast": n_forecast_edges,



        "edge_forecasts": edge_forecasts,



        "predicted_structural_changes": predicted_changes,



        "n_predicted_changes": len(predicted_changes),



        "quality_metrics": quality,



        "model_type": rng.choice(["VAR", "ARIMA", "LSTM", "Transformer", "Ensemble"]),



        "forecast_stability": round(rng.uniform(0.5, 0.95), 3),



    }











def _compute_timed_intervention(



    graph_id: str,



    timing: InterventionTiming,



    target_node: str,



    delay_steps: int,



    n_interventions: int,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Plan and simulate temporally-aware interventions"""



    rng = random.Random(_seed238(graph_id, seed_offset))







    timing_cfgs = {



        InterventionTiming.IMMEDIATE: {"lag": 0, "description": "Apply at current time step"},



        InterventionTiming.DELAYED: {"lag": delay_steps, "description": f"Apply after {delay_steps}-step delay"},



        InterventionTiming.SCHEDULED: {"lag": "fixed", "description": "Apply at predetermined time"},



        InterventionTiming.CONDITIONAL: {"lag": "variable", "description": "Apply when trigger condition is met"},



        InterventionTiming.RECURRING: {"lag": "periodic", "description": "Repeated at regular intervals"},



        InterventionTiming.OPTIMAL: {"lag": "computed", "description": "Computed optimal intervention timing"},



    }



    t_cfg = timing_cfgs[timing]



    target = target_node or f"var_{rng.randint(1, 10)}"







    interventions = []



    for i in range(n_interventions):



        if timing == InterventionTiming.IMMEDIATE:



            apply_step = 0



        elif timing == InterventionTiming.DELAYED:



            apply_step = delay_steps



        elif timing == InterventionTiming.SCHEDULED:



            apply_step = rng.randint(5, 30)



        elif timing == InterventionTiming.CONDITIONAL:



            apply_step = rng.randint(3, 20)



        elif timing == InterventionTiming.RECURRING:



            apply_step = i * max(1, rng.randint(3, 10))



        else:



            apply_step = rng.randint(0, 20)







        effect_duration = rng.randint(5, 50)



        peak_effect = round(rng.uniform(0.3, 0.9), 3)



        decay_rate = round(rng.uniform(0.01, 0.1), 3)







        # Effect trajectory



        trajectory = []



        for t in range(effect_duration):



            if t < 3:



                effect = peak_effect * (t + 1) / 3



            else:



                effect = peak_effect * max(0, 1 - decay_rate * (t - 3))



            trajectory.append({



                "step": apply_step + t,



                "effect_magnitude": round(max(0, effect), 3),



                "propagation_depth": min(t, 5),



                "affected_nodes": rng.randint(1, 6),



            })







        interventions.append({



            "id": f"intervention_{i+1}",



            "target_node": target,



            "timing": timing.value,



            "apply_step": apply_step,



            "effect_duration": effect_duration,



            "peak_effect": peak_effect,



            "peak_step": apply_step + 3,



            "decay_rate": decay_rate,



            "trajectory": trajectory,



            "total_impact": round(sum(t["effect_magnitude"] for t in trajectory), 3),



            "side_effects": rng.randint(0, 3),



            "robustness_score": round(rng.uniform(0.5, 0.95), 3),



        })







    # Temporal interaction analysis



    interactions = []



    for i in range(len(interventions)):



        for j in range(i + 1, min(len(interventions), i + 3)):



            overlap = max(0, interventions[i]["apply_step"] + interventions[i]["effect_duration"] - interventions[j]["apply_step"])



            if overlap > 0:



                interactions.append({



                    "pair": f"{interventions[i]['id']}×{interventions[j]['id']}",



                    "temporal_overlap": overlap,



                    "interaction_type": rng.choice(["synergistic", "antagonistic", "neutral"]),



                    "combined_effect_modifier": round(rng.uniform(0.7, 1.4), 3),



                })







    # Optimal timing recommendation



    optimal_step = rng.randint(0, 20)



    best_intervention = max(interventions, key=lambda x: x["total_impact"])







    return {



        "graph_id": graph_id,



        "timing_strategy": timing.value,



        "timing_config": t_cfg,



        "target_node": target,



        "n_interventions": n_interventions,



        "interventions": interventions,



        "interactions": interactions,



        "optimal_timing": {



            "recommended_step": optimal_step,



            "best_intervention_id": best_intervention["id"],



            "expected_effect": best_intervention["total_impact"],



            "timing_rationale": "Maximizes cumulative effect with minimal interference",



        },



        "temporal_efficiency": round(rng.uniform(0.4, 0.9), 3),



    }











def _compute_temporal_pattern(



    graph_id: str,



    pattern: TemporalPattern,



    analysis_window: int,



    min_occurrences: int,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Detect and analyze temporal patterns in causal dynamics"""



    rng = random.Random(_seed238(graph_id, seed_offset))



    pat_cfg = _PATTERN_CONFIGS_238[pattern]







    n_instances = rng.randint(min_occurrences, min_occurrences + 5)



    instances = []



    for i in range(n_instances):



        start = rng.randint(0, analysis_window)



        duration = rng.randint(5, max(6, analysis_window // 5))







        instances.append({



            "instance_id": i + 1,



            "start_step": start,



            "end_step": start + duration,



            "duration": duration,



            "amplitude": round(rng.uniform(0.2, 0.9), 3),



            "phase_offset": round(rng.uniform(0, 2 * 3.14159), 3),



            "strength_correlation": round(rng.uniform(0.4, 0.95), 3),



            "affected_edges": [f"var_{rng.randint(1, 10)}→var_{rng.randint(1, 10)}" for _ in range(rng.randint(1, 4))],



        })







    # Pattern statistics



    if pattern == TemporalPattern.PERIODIC:



        period = rng.randint(5, 30)



        pattern_specific = {



            "estimated_period": period,



            "period_stability": round(rng.uniform(0.6, 0.98), 3),



            "frequency_hz": round(1.0 / period, 4),



            "harmonics": rng.randint(1, 4),



            "dominant_frequency_ratio": round(rng.uniform(0.7, 0.99), 3),



        }



    elif pattern == TemporalPattern.TREND:



        slope = round(rng.uniform(-0.05, 0.05), 4)



        pattern_specific = {



            "trend_slope": slope,



            "trend_direction": "increasing" if slope > 0 else "decreasing",



            "r_squared": round(rng.uniform(0.5, 0.95), 3),



            "detected_at_step": rng.randint(5, analysis_window // 2),



        }



    elif pattern == TemporalPattern.REGIME_SHIFT:



        pattern_specific = {



            "shift_count": rng.randint(1, 4),



            "shift_magnitudes": [round(rng.uniform(0.2, 0.8), 3) for _ in range(rng.randint(1, 4))],



            "inter_regime_stability": round(rng.uniform(0.6, 0.95), 3),



            "early_warning_signals": rng.randint(1, 3),



        }



    elif pattern == TemporalPattern.SEASONAL:



        pattern_specific = {



            "season_length": rng.randint(10, 50),



            "seasonal_strength": round(rng.uniform(0.5, 0.9), 3),



            "n_seasons_detected": rng.randint(2, 6),



            "trend_seasonal_ratio": round(rng.uniform(0.3, 2.0), 3),



        }



    elif pattern == TemporalPattern.INTERMITTENT:



        pattern_specific = {



            "activation_probability": round(rng.uniform(0.2, 0.6), 3),



            "avg_active_duration": rng.randint(3, 15),



            "avg_inactive_duration": rng.randint(5, 25),



            "hmm_states": rng.randint(2, 4),



        }



    else:



        pattern_specific = {



            "accumulation_rate": round(rng.uniform(0.01, 0.1), 4),



            "saturation_level": round(rng.uniform(0.6, 1.0), 3),



            "half_life": rng.randint(10, 100),



            "threshold_effects": rng.randint(1, 3),



        }







    return {



        "graph_id": graph_id,



        "pattern_type": pattern.value,



        "pattern_config": pat_cfg,



        "analysis_window": analysis_window,



        "n_instances": n_instances,



        "instances": instances,



        "pattern_specific": pattern_specific,



        "significance": round(rng.uniform(0.01, 0.05), 4),



        "effect_size": round(rng.uniform(0.3, 0.9), 3),



        "predictability_score": round(rng.uniform(0.4, 0.9), 3),



    }











def _compute_causal_lifecycle(



    graph_id: str,



    edge_id: str,



    granularity: TemporalGranularity,



    seed_offset: int = 0



) -> Dict[str, Any]:



    """Track the full lifecycle of causal edges from emergence to dissolution"""



    rng = random.Random(_seed238(graph_id, seed_offset))







    target_edge = edge_id or f"var_{rng.randint(1, 8)}→var_{rng.randint(1, 8)}"







    # Lifecycle phases



    phases = [



        {"phase": "dormant", "description": "Causal link not yet present", "typical_duration": "variable"},



        {"phase": "emerging", "description": "Causal link forming, weak effect", "typical_duration": "short"},



        {"phase": "strengthening", "description": "Causal effect growing in magnitude", "typical_duration": "medium"},



        {"phase": "stable", "description": "Causal link at equilibrium strength", "typical_duration": "long"},



        {"phase": "weakening", "description": "Causal effect diminishing", "typical_duration": "medium"},



        {"phase": "dissolving", "description": "Causal link disappearing", "typical_duration": "short"},



    ]







    lifecycle_phases = []



    total_duration = rng.randint(20, 200)



    phase_durations = []



    remaining = total_duration







    for i, phase in enumerate(phases):



        if i == len(phases) - 1:



            dur = remaining



        else:



            max_dur = remaining - (len(phases) - 1 - i)



            dur = rng.randint(1, max(2, max_dur))



        remaining -= dur



        if remaining < 0:



            remaining = 0



        phase_durations.append(dur)







    current_step = 0



    for i, phase in enumerate(phases):



        dur = phase_durations[i]



        strength_range = {



            "dormant": (0.0, 0.05),



            "emerging": (0.05, 0.25),



            "strengthening": (0.25, 0.6),



            "stable": (0.6, 0.9),



            "weakening": (0.3, 0.6),



            "dissolving": (0.0, 0.3),



        }



        lo, hi = strength_range[phase["phase"]]







        # Sample points within phase



        n_points = min(dur, 10)



        trajectory_points = []



        for p in range(n_points):



            frac = p / max(1, n_points - 1)



            strength = round(lo + (hi - lo) * (frac if i < 3 else 1 - frac), 3)



            trajectory_points.append({



                "relative_step": p,



                "strength": max(0.0, min(1.0, strength)),



                "stability": round(rng.uniform(0.5, 0.95), 3),



            })







        lifecycle_phases.append({



            "phase": phase["phase"],



            "description": phase["description"],



            "start_step": current_step,



            "end_step": current_step + dur,



            "duration": dur,



            "strength_range": [round(lo, 3), round(hi, 3)],



            "trajectory_points": trajectory_points,



            "transition_trigger": rng.choice([



                "data_distribution_change",



                "external_intervention",



                "feedback_loop_saturation",



                "confounder_shift",



                "natural_dynamics",



            ]),



        })



        current_step += dur







    # Key lifecycle metrics



    peak_strength = max(



        pt["strength"]



        for phase in lifecycle_phases



        for pt in phase["trajectory_points"]



    )



    peak_phase = max(lifecycle_phases, key=lambda p: p["trajectory_points"][-1]["strength"] if p["trajectory_points"] else 0)







    return {



        "graph_id": graph_id,



        "edge": target_edge,



        "granularity": granularity.value,



        "total_lifespan": total_duration,



        "lifecycle_phases": lifecycle_phases,



        "summary": {



            "peak_strength": round(peak_strength, 3),



            "peak_phase": peak_phase["phase"],



            "peak_step": peak_phase["start_step"] + peak_phase["duration"] // 2,



            "stable_duration": phase_durations[3],



            "transition_count": len(phases) - 1,



            "robustness_across_lifecycle": round(rng.uniform(0.5, 0.9), 3),



            "resilience_score": round(rng.uniform(0.4, 0.85), 3),



        },



        "lifecycle_class": rng.choice(["transient", "persistent", "episodic", "gradual_transition"]),



        "temporal_signature": {



            "rise_time": phase_durations[1] + phase_durations[2],



            "stable_time": phase_durations[3],



            "decay_time": phase_durations[4] + phase_durations[5],



            "asymmetry_ratio": round((phase_durations[1] + phase_durations[2]) / max(1, phase_durations[4] + phase_durations[5]), 3),



        }



    }











# Endpoints



@router.post("/temporal-causal/evolution")



async def simulate_temporal_evolution(request: TemporalEvolutionRequest):



    """Simulate temporal evolution of causal graph structure"""



    cache_key = f"{request.graph_id}:{request.granularity.value}:{request.n_steps}:{':'.join(sorted(t.value for t in request.transition_types))}"







    if cache_key not in _evolution_cache:



        result = _compute_temporal_evolution(



            request.graph_id,



            request.granularity,



            request.n_steps,



            request.transition_types



        )



        _evolution_cache[cache_key] = {



            "graph_id": request.graph_id,



            "result": result,



            "timestamp": random.randint(1700000000, 1800000000)



        }







    return _evolution_cache[cache_key]











