def _seed239(graph_id: str, offset: int = 0) -> int:



    return abs(hash(f"ontology_causal_{graph_id}_{offset}")) % (2**31)











# --- Request Models ---







class OntologyBuildRequest(BaseModel):



    graph_id: str



    method: OntologyConstruction = OntologyConstruction.HYBRID



    max_depth: int = 5



    min_concept_support: float = 0.1



    domain_hints: List[str] = []







class ConceptExtractRequest(BaseModel):



    graph_id: str



    extractor: ConceptExtraction = ConceptExtraction.EMBEDDING



    n_concepts: int = 20



    min_confidence: float = 0.5



    source_types: List[str] = ["entity", "relation", "attribute"]







class OntologyAlignRequest(BaseModel):



    graph_id: str



    strategy: OntologyAlignment = OntologyAlignment.SEMANTIC



    target_ontology_id: str = ""



    threshold: float = 0.7



    max_mappings: int = 100







class OntologyReasonRequest(BaseModel):



    graph_id: str



    reasoner: OntologyReasoning = OntologyReasoning.DEDUCTIVE



    query: str = ""



    max_inference_depth: int = 3



    confidence_threshold: float = 0.6







class OntologyEvolveRequest(BaseModel):



    graph_id: str



