# --- Compute Functions ---







def _compute_ontology_build(graph_id: str, method: OntologyConstruction, max_depth: int,



                            min_support: float, domain_hints: List[str]) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 1))



    cfg = ONTOLOGY_CONSTRUCTION_CONFIG[method]



    n_concepts = rng.randint(30, 120)



    n_relations = rng.randint(40, 200)



    n_levels = rng.randint(2, max_depth)



    concepts = []



    for i in range(n_concepts):



        concepts.append({



            "id": f"concept_{i}",



            "label": f"{method.value}_concept_{i}",



            "level": rng.randint(0, n_levels),



            "support": round(rng.uniform(min_support, 1.0), 4),



            "confidence": round(rng.uniform(0.5, 0.99), 4),



            "properties": rng.randint(1, 8),



            "instances": rng.randint(0, 500),



        })



    hierarchy = {



        "max_depth": n_levels,



        "avg_breadth": round(n_concepts / max(n_levels, 1), 2),



        "root_concepts": rng.randint(2, 8),



        "leaf_concepts": rng.randint(10, 50),



        "is_a_relations": rng.randint(n_concepts // 2, n_concepts),



        "part_of_relations": rng.randint(5, 30),



        "custom_relations": n_relations - rng.randint(n_concepts // 2, n_concepts) - 10,



    }



    return {



        "method": method.value,



        "method_info": cfg,



        "n_concepts": n_concepts,



        "n_relations": n_relations,



        "concepts_sample": concepts[:10],



        "hierarchy": hierarchy,



        "domain_hints_used": domain_hints[:3],



        "construction_quality": {



            "coherence": round(rng.uniform(0.7, 0.98), 4),



            "coverage": round(rng.uniform(0.6, 0.95), 4),



            "specificity": round(rng.uniform(0.5, 0.9), 4),



            "consistency": round(rng.uniform(0.75, 0.99), 4),



            "richness": round(rng.uniform(0.6, 0.92), 4),



        },



        "build_time_ms": rng.randint(50, 500),



    }











def _compute_concept_extract(graph_id: str, extractor: ConceptExtraction, n_concepts: int,



                             min_confidence: float, source_types: List[str]) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 2))



    cfg = CONCEPT_EXTRACTION_CONFIG[extractor]



    extracted = []



    for i in range(n_concepts):



        conf = round(rng.uniform(min_confidence, 0.99), 4)



        extracted.append({



            "concept_id": f"ext_concept_{i}",



            "label": f"extracted_{extractor.value}_{i}",



            "confidence": conf,



            "source_type": rng.choice(source_types),



            "frequency": rng.randint(1, 1000),



            "related_concepts": rng.randint(0, 15),



            "embedding_dim": rng.choice([64, 128, 256, 512]),



            "tfidf_score": round(rng.uniform(0.01, 5.0), 4),



        })



    return {



        "extractor": extractor.value,



        "extractor_info": cfg,



        "n_requested": n_concepts,



        "n_extracted": len(extracted),



        "concepts": extracted,



        "source_types_used": source_types,



        "extraction_stats": {



            "avg_confidence": round(sum(c["confidence"] for c in extracted) / max(len(extracted), 1), 4),



            "high_confidence_count": sum(1 for c in extracted if c["confidence"] >= 0.8),



            "unique_source_types": len(set(c["source_type"] for c in extracted)),



            "coverage_ratio": round(rng.uniform(0.5, 0.95), 4),



        },



        "extraction_time_ms": rng.randint(30, 300),



    }











def _compute_ontology_align(graph_id: str, strategy: OntologyAlignment,



                            target_ontology_id: str, threshold: float,



                            max_mappings: int) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 3))



    cfg = ONTOLOGY_ALIGNMENT_CONFIG[strategy]



    n_mappings = rng.randint(5, min(max_mappings, 100))



    mappings = []



    for i in range(n_mappings):



        sim = round(rng.uniform(threshold, 1.0), 4)



        mappings.append({



            "source_concept": f"src_concept_{i}",



            "target_concept": f"tgt_concept_{i}",



            "similarity": sim,



            "relation_type": rng.choice(["equivalent", "subsumes", "related", "overlaps"]),



            "confidence": round(sim * rng.uniform(0.8, 1.0), 4),



            "evidence": rng.choice(["label_match", "structure_match", "instance_overlap", "embedding_sim"]),



        })



    return {



        "strategy": strategy.value,



        "strategy_info": cfg,



        "target_ontology_id": target_ontology_id or "default_target",



        "threshold": threshold,



        "n_mappings": n_mappings,



        "mappings": mappings,



        "alignment_quality": {



            "precision": round(rng.uniform(0.7, 0.95), 4),



            "recall": round(rng.uniform(0.6, 0.9), 4),



            "f1_score": round(rng.uniform(0.65, 0.92), 4),



            "avg_similarity": round(sum(m["similarity"] for m in mappings) / max(n_mappings, 1), 4),



        },



        "alignment_time_ms": rng.randint(100, 1000),



    }











def _compute_ontology_reason(graph_id: str, reasoner: OntologyReasoning,



                             query: str, max_depth: int,



                             confidence_threshold: float) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 4))



    cfg = ONTOLOGY_REASONING_CONFIG[reasoner]



    n_inferences = rng.randint(5, 50)



    inferences = []



    for i in range(n_inferences):



        conf = round(rng.uniform(confidence_threshold, 0.99), 4)



        inferences.append({



            "inference_id": f"inf_{i}",



            "type": rng.choice(["subsumption", "equivalence", "disjointness", "instance_check", "realization"]),



            "premises": [f"axiom_{rng.randint(0, 20)}" for _ in range(rng.randint(1, 3))],



            "conclusion": f"derived_fact_{i}",



            "confidence": conf,



            "depth": rng.randint(1, max_depth),



            "rule_applied": rng.choice(["modus_ponens", "universal_instantiation", "existential_generalization", "resolution"]),



        })



    return {



        "reasoner": reasoner.value,



        "reasoner_info": cfg,



        "query": query or "classify_all",



        "max_inference_depth": max_depth,



        "confidence_threshold": confidence_threshold,



        "n_inferences": n_inferences,



        "inferences": inferences,



        "reasoning_stats": {



            "avg_confidence": round(sum(i["confidence"] for i in inferences) / max(n_inferences, 1), 4),



            "max_depth_used": max(i["depth"] for i in inferences) if inferences else 0,



            "rules_used": len(set(i["rule_applied"] for i in inferences)),



            "entailment_ratio": round(rng.uniform(0.3, 0.8), 4),



        },



        "reasoning_time_ms": rng.randint(20, 400),



    }











def _compute_ontology_evolve(graph_id: str, evolution_type: OntologyEvolution,



                             new_facts: List[str], max_changes: int) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 5))



    cfg = ONTOLOGY_EVOLUTION_CONFIG[evolution_type]



    n_changes = rng.randint(1, min(max_changes, 50))



    changes = []



    for i in range(n_changes):



        changes.append({



            "change_id": f"change_{i}",



            "type": rng.choice(["add_concept", "remove_concept", "add_relation", "modify_relation", "reclassify", "merge_concepts"]),



            "target": f"ontology_element_{rng.randint(0, 100)}",



            "description": f"{evolution_type.value}_change_{i}",



            "impact_score": round(rng.uniform(0.1, 1.0), 4),



            "reversible": rng.choice([True, False]),



            "validation_status": rng.choice(["pending", "validated", "rejected"]),



        })



    return {



        "evolution_type": evolution_type.value,



        "evolution_info": cfg,



        "n_new_facts": len(new_facts),



        "new_facts_processed": new_facts[:10],



        "n_changes": n_changes,



        "changes": changes,



        "evolution_metrics": {



            "concepts_added": sum(1 for c in changes if c["type"] == "add_concept"),



            "concepts_removed": sum(1 for c in changes if c["type"] == "remove_concept"),



            "relations_modified": sum(1 for c in changes if c["type"] in ["add_relation", "modify_relation"]),



            "avg_impact": round(sum(c["impact_score"] for c in changes) / max(n_changes, 1), 4),



            "validation_pass_rate": round(rng.uniform(0.7, 0.98), 4),



        },



        "evolution_time_ms": rng.randint(50, 600),



    }











def _compute_semantic_validate(graph_id: str, validator: SemanticValidation,



                               scope: str, severity_threshold: float,



                               auto_fix: bool) -> Dict[str, Any]:



    rng = Random(_seed239(graph_id, 6))



    cfg = SEMANTIC_VALIDATION_CONFIG[validator]



    n_issues = rng.randint(0, 30)



    issues = []



    for i in range(n_issues):



        sev = round(rng.uniform(severity_threshold, 1.0), 4)



        issues.append({



            "issue_id": f"issue_{i}",



            "type": rng.choice(["inconsistency", "incompleteness", "redundancy", "circular_dependency", "orphan_concept", "type_violation"]),



            "severity": sev,



            "location": f"concept_{rng.randint(0, 100)}",



            "description": f"{validator.value}_issue_{i}: detected quality problem",



            "suggestion": f"Consider {rng.choice(['merging', 'splitting', 'reclassifying', 'removing', 'adding'])} affected element",



            "auto_fixable": auto_fix and rng.choice([True, False]),



        })



    return {



        "validator": validator.value,



        "validator_info": cfg,



        "scope": scope,



        "severity_threshold": severity_threshold,



        "auto_fix_enabled": auto_fix,



        "n_issues_found": n_issues,



        "issues": issues,



        "validation_results": {



            "overall_score": round(rng.uniform(0.6, 0.98), 4),



            "consistency_score": round(rng.uniform(0.7, 0.99), 4),



            "completeness_score": round(rng.uniform(0.5, 0.95), 4),



            "coherence_score": round(rng.uniform(0.65, 0.97), 4),



            "critical_issues": sum(1 for i in issues if i["severity"] >= 0.8),



            "auto_fixed": sum(1 for i in issues if i.get("auto_fixable")) if auto_fix else 0,



        },



        "validation_time_ms": rng.randint(20, 300),



    }











