from enum import Enum



from typing import Dict, Any, List, Optional



from pydantic import BaseModel



import time











class NASSearchStrategy(str, Enum):



    """Neural Architecture Search strategies for graph neural networks."""



    EVOLUTIONARY = "evolutionary"



    REINFORCEMENT_LEARNING = "reinforcement_learning"



    DARTS = "darts"



    BAYESIAN = "bayesian"



    ONE_SHOT = "one_shot"



    PROXYLESS_NAS = "proxyless_nas"











class GraphSearchSpace(str, Enum):



    """Graph neural network search space definitions."""



    GCN_BASED = "gcn_based"



    GAT_BASED = "gat_based"



    GRAPHSAGE_BASED = "graphsage_based"



    TRANSFORMER_BASED = "transformer_based"



    HYBRID = "hybrid"



    CUSTOM = "custom"











class NASOptimizationObjective(str, Enum):



    """NAS optimization objectives."""



    ACCURACY = "accuracy"



    FLOPs = "flops"



    LATENCY = "latency"



    MEMORY = "memory"



    PARAMETER_COUNT = "parameter_count"



    MULTI_OBJECTIVE = "multi_objective"











class EvaluationStrategy(str, Enum):



    """Architecture evaluation strategies."""



    FULL_TRAINING = "full_training"



    WEIGHT_SHARING = "weight_sharing"



    SUPERNET = "supernet"



    PREDICTOR_BASED = "predictor_based"



    META_LEARNING = "meta_learning"



    TRANSFER_LEARNING = "transfer_learning"











class NetworkOperation(str, Enum):



    """Graph neural network operations."""



    GRAPH_CONVOLUTION = "graph_convolution"



    ATTENTION = "attention"



    POOLING = "pooling"



    MESSAGE_PASSING = "message_passing"



    SKIP_CONNECTION = "skip_connection"



    NORMALIZATION = "normalization"











class ArchitectureConstraint(str, Enum):



    """Architecture design constraints."""



    MAX_LAYERS = "max_layers"



    MAX_HIDDEN_DIMS = "max_hidden_dims"



    MAX_HEADS = "max_heads"



    RECURRENT = "recurrent"



    SPARSE = "sparse"



    QUANTIZED = "quantized"











