@_router247.post("/causal-world/build", tags=["v1.247"])



async def build_world_model(request: _WorldBuildRequest) -> _WorldModelResponse:



    """Build a causal world model from a graph's causal structure."""



    mid = f"wm-{_uuid247.uuid4().hex[:8]}"



    n_obs = request.num_state_variables



    n_lat = int(n_obs * 0.4) if request.include_latent else 0



    rng = _rng247.Random(hash(request.graph_id) % (2**31))







    variables: _List247[_StateVariable] = []



    for i in range(n_obs + n_lat):



        is_lat = i >= n_obs



        parents = []



        if i > 0:



            n_parents = min(i, rng.randint(0, min(4, i)))



            parents = [f"var_{j}" for j in sorted(rng.sample(range(i), n_parents))]



        vtype = rng.choice(["continuous", "discrete", "categorical", "binary"])



        domain_desc = (



            "(-inf, inf)" if vtype == "continuous"



            else f"{{0,...,{rng.randint(2,20)}}}" if vtype == "discrete"



            else f"{{cat_{k} for k in {rng.randint(2,8)}}}" if vtype == "categorical"



            else "{0,1}"



        )



        variables.append(_StateVariable(



            var_id=f"var_{i}",



            name=f"{'latent_' if is_lat else ''}var_{i}",



            var_type=vtype,



            domain=domain_desc,



            causal_parents=parents,



            is_latent=is_lat,



            current_value=round(rng.uniform(-1, 1), 4) if vtype == "continuous" else rng.randint(0, 5),



            possible_values=[round(rng.uniform(-2, 2), 2) for _ in range(4)] if vtype == "continuous" else list(range(rng.randint(2, 7))),



        ))







    mechanisms: _List247[_CausalMechanism] = []



    for v in variables:



        if not v.causal_parents:



            continue



        mechanisms.append(_CausalMechanism(



            mechanism_id=f"mech_{v.var_id}",



            output_var=v.var_id,



            input_vars=v.causal_parents,



            mechanism_type=rng.choice(["linear", "nonlinear_mlp", "neural_scm", "gp_mechanism", "structural_equation", "conditional_probability"]),



            is_noisy=rng.random() > 0.3,



            noise_distribution=rng.choice(["gaussian", "exponential", "uniform", "laplace", "student_t", "mixture_gaussian"]),



            deterministic_core=f"f_{v.var_id}({', '.join(v.causal_parents)})",



            r_squared=round(rng.uniform(0.6, 0.99), 4),



            intervention_robustness=round(rng.uniform(0.7, 0.98), 4),



        ))







    markov_blankets: _Dict247[str, _List247[str]] = {}



    for v in variables:



        parents = set(v.causal_parents)



        children = {u.var_id for u in variables if v.var_id in u.causal_parents}



        co_parents: set = set()



        for c in children:



            for u in variables:



                if u.var_id == c:



                    co_parents.update(u.causal_parents)



        co_parents.discard(v.var_id)



        markov_blankets[v.var_id] = sorted(parents | children | co_parents)







    structural_complexity = round(



        sum(len(m.input_vars) for m in mechanisms) / max(len(variables), 1), 2



    )







    resp = _WorldModelResponse(



        model_id=mid,



        graph_id=request.graph_id,



        model_type=request.model_type.value,



        state_repr=request.state_repr.value,



        state_variables=variables,



        causal_mechanisms=mechanisms,



        latent_variable_count=n_lat,



        observed_variable_count=n_obs,



        markov_blanket_summary=markov_blankets,



        structural_complexity=structural_complexity,



        timestamp=_time247.time(),



    )



    _wm_cache[mid] = resp



    return resp











@_router247.post("/causal-world/simulate", tags=["v1.247"])



async def simulate_intervention(request: _SimulateRequest) -> _SimulationResult:



    """Simulate an intervention in the causal world model."""



    sid = f"sim-{_uuid247.uuid4().hex[:8]}"



    rng = _rng247.Random(hash(request.model_id) % (2**31))



    model = _wm_cache.get(request.model_id)



    n_vars = len(model.state_variables) if model else 10



    var_names = [f"var_{i}" for i in range(n_vars)]







    intervention_info = {



        "variable": request.intervention_var,



        "type": request.intervention_type.value,



        "value": request.intervention_value if request.intervention_value is not None else round(rng.uniform(-2, 2), 3),



    }







    sample_traj: _List247[_TrajectoryStep] = []



    current_state: _Dict247[str, _Any247] = {v: round(rng.gauss(0, 1), 4) for v in var_names}



    for step in range(min(request.num_steps, 50)):



        intervened = [request.intervention_var] if step == 0 else []



        if request.intervention_var in current_state:



            current_state[request.intervention_var] = intervention_info["value"]



        current_state = {



            v: round(current_state[v] + rng.gauss(0, 0.1) + (0.05 if v != request.intervention_var else 0), 4)



            for v in var_names



        }



        divergence = round(sum(abs(current_state[v]) for v in var_names) / n_vars, 4)



        sample_traj.append(_TrajectoryStep(



            step=step,



            state=dict(current_state),



            observations={v: round(current_state[v] + rng.gauss(0, 0.05), 4) for v in var_names[:min(6, n_vars)]},



            intervened_vars=intervened,



            reward=round(-divergence + rng.gauss(0, 0.1), 4),



            divergence=divergence,



        ))







    agg_effects: _Dict247[str, _Dict247[str, float]] = {}



    for v in var_names[:min(10, n_vars)]:



        agg_effects[v] = {



            "mean_effect": round(rng.gauss(0, 0.5), 4),



            "std_effect": round(rng.uniform(0.01, 0.3), 4),



            "max_effect": round(rng.uniform(0.1, 1.5), 4),



            "effect_direction": rng.choice([-1, 1]),



        }







    causal_estimates = {v: round(rng.gauss(0, 0.3), 4) for v in var_names[:min(10, n_vars)]}



    expected_outcome = {v: round(rng.gauss(0, 0.4), 4) for v in var_names[:min(8, n_vars)]}



    outcome_var = {v: round(rng.uniform(0.01, 0.2), 4) for v in var_names[:min(8, n_vars)]}



    cis = {v: [round(expected_outcome[v] - 1.96 * outcome_var[v], 4),



               round(expected_outcome[v] + 1.96 * outcome_var[v], 4)]



           for v in expected_outcome}







    return _SimulationResult(



        sim_id=sid,



        model_id=request.model_id,



        intervention=intervention_info,



        mode=request.simulation_mode.value,



        horizon=request.temporal_horizon.value,



        num_steps=request.num_steps,



        num_trajectories=request.num_trajectories,



        sample_trajectory=sample_traj,



        aggregated_effects=agg_effects,



        causal_effect_estimates=causal_estimates,



        expected_outcome=expected_outcome,



        outcome_variance=outcome_var,



        confidence_intervals=cis,



        timestamp=_time247.time(),



    )











@_router247.post("/causal-world/rollout", tags=["v1.247"])



async def policy_rollout(request: _RolloutRequest) -> _RolloutResponse:



    """Execute multi-episode policy rollouts in the causal world model."""



    rid = f"ro-{_uuid247.uuid4().hex[:8]}"



    rng = _rng247.Random(hash(request.model_id) % (2**31))



    n_vars = 8



    var_names = [f"var_{i}" for i in range(n_vars)]







    episodes: _List247[_EpisodeSummary] = []



    for ep in range(min(request.num_episodes, 50)):



        steps = rng.randint(5, request.max_steps_per_episode)



        total_r = sum(rng.gauss(0, 1) * (request.discount_factor ** t) for t in range(steps))



        n_interventions = rng.randint(0, max(1, steps // 5))



        final_state = {v: round(rng.gauss(0, 1), 4) for v in var_names}



        episodes.append(_EpisodeSummary(



            episode_id=ep,



            total_reward=round(total_r, 4),



            steps=steps,



            final_state=final_state,



            interventions_applied=n_interventions,



            outcome_divergence=round(rng.uniform(0, 2), 4),



        ))







    rewards = [e.total_reward for e in episodes]



    mean_r = round(sum(rewards) / len(rewards), 4) if rewards else 0.0



    std_r = round((sum((r - mean_r) ** 2 for r in rewards) / len(rewards)) ** 0.5, 4) if len(rewards) > 1 else 0.0







    value_fn = {v: round(rng.gauss(0, 1), 4) for v in var_names}



    policy = {v: rng.choice(["increase", "decrease", "maintain", "intervene", "observe"]) for v in var_names}



    leverage = [f"var_{i}" for i in sorted(rng.sample(range(n_vars), min(3, n_vars)))]







    return _RolloutResponse(



        rollout_id=rid,



        model_id=request.model_id,



        num_episodes=request.num_episodes,



        episodes=episodes,



        mean_reward=mean_r,



        std_reward=std_r,



        value_function_estimate=value_fn,



        optimal_policy=policy,



        causal_leverage_points=leverage,



        timestamp=_time247.time(),



    )











@_router247.post("/causal-world/verify", tags=["v1.247"])



async def verify_consistency(request: _ConsistencyRequest) -> _ConsistencyResponse:



    """Verify consistency of the causal world model against formal criteria."""



    vid = f"vfy-{_uuid247.uuid4().hex[:8]}"



    rng = _rng247.Random(hash(request.model_id) % (2**31))







    results: _List247[_CheckResult] = []



    for chk in request.checks:



        passed = rng.random() > 0.25



        score = round(rng.uniform(0.7, 1.0) if passed else rng.uniform(0.1, 0.6), 4)



        violations = [] if passed else [f"Violation in {chk.value}: condition not met at node var_{rng.randint(0, 7)}"]



        counterexamples = []



        if request.generate_counterexamples and not passed:



            counterexamples = [



                {"state": {f"var_{j}": round(rng.gauss(0, 1), 3) for j in range(5)},



                 "expected": round(rng.uniform(0, 1), 3),



                 "actual": round(rng.uniform(0, 1), 3)}



                for _ in range(rng.randint(1, 3))



            ]



        recommendation = (



            "Model passes this check." if passed



            else f"Consider restructuring causal dependencies to satisfy {chk.value}."



        )



        results.append(_CheckResult(



            check_type=chk.value,



            passed=passed,



            score=score,



            violations=violations,



            counterexamples=counterexamples,



            recommendation=recommendation,



        ))







    overall = round(sum(r.score for r in results) / max(len(results), 1), 4)



    critical = [f"{r.check_type}: {v}" for r in results if not r.passed for v in r.violations]







    return _ConsistencyResponse(



        verification_id=vid,



        model_id=request.model_id,



        checks_performed=len(results),



        results=results,



        overall_consistency=overall,



        is_consistent=overall >= (1.0 - request.tolerance),



        critical_violations=critical,



        timestamp=_time247.time(),



    )











@_router247.post("/causal-world/compose", tags=["v1.247"])



async def compose_world_models(request: _ComposeRequest) -> _ComposedModelResponse:



    """Compose multiple sub-world models into a unified causal world model."""



    cid = f"comp-{_uuid247.uuid4().hex[:8]}"



    rng = _rng247.Random(hash(tuple(request.sub_model_ids)) % (2**31))



    n_shared = len(request.shared_variables) if request.shared_variables else rng.randint(1, 4)



    shared_vars = request.shared_variables or [f"shared_var_{i}" for i in range(n_shared)]







    n_bridged = rng.randint(2, min(8, len(request.sub_model_ids) * 2))



    bridged = [f"bridge_mech_{i}" for i in range(n_bridged)]







    conflicts = []



    if request.resolve_conflicts:



        for _ in range(rng.randint(0, 3)):



            conflicts.append({



                "variable": rng.choice(shared_vars),



                "conflict_type": rng.choice(["direction_mismatch", "strength_divergence", "latent_overlap"]),



                "resolution": rng.choice(["average", "vote", "causal_priority", "evidence_weighted"]),



            })







    total_vars = sum(rng.randint(5, 15) for _ in request.sub_model_ids)







    return _ComposedModelResponse(



        composed_id=cid,



        sub_models=request.sub_model_ids,



        composition_strategy=request.composition_strategy,



        shared_variables=shared_vars,



        bridged_mechanisms=bridged,



        conflict_resolutions=conflicts,



        total_state_variables=total_vars,



        composition_fidelity=round(rng.uniform(0.75, 0.98), 4),



        timestamp=_time247.time(),



    )











@_router247.post("/causal-world/predict", tags=["v1.247"])



async def predict_with_model(request: _PredictRequest) -> _PredictResponse:



    """Predict target variables using the causal world model with evidence."""



    pid = f"pred-{_uuid247.uuid4().hex[:8]}"



    rng = _rng247.Random(hash(request.model_id + str(request.target_variables)) % (2**31))







    predictions: _List247[_VariablePrediction] = []



    for tv in request.target_variables:



        pred_val = round(rng.gauss(0, 1), 4)



        conf = round(rng.uniform(0.6, 0.99), 4)



        half_w = 1.96 * (1 - conf) * abs(pred_val) + 0.1



        contributing = rng.sample(



            list(request.evidence.keys()) if request.evidence else [f"var_{i}" for i in range(5)],



            min(3, max(1, len(request.evidence) if request.evidence else 5)),



        )



        explanations = {



            "marginal": f"Marginal prediction based on prior distribution of {tv}",



            "conditional": f"Conditional on evidence: {', '.join(contributing)}",



            "interventional": f"Interventional prediction under do({tv}={pred_val})",



            "counterfactual": f"Counterfactual: what if {tv} were {pred_val}",



        }



        predictions.append(_VariablePrediction(



            variable=tv,



            predicted_value=pred_val,



            confidence=conf,



            interval=[round(pred_val - half_w, 4), round(pred_val + half_w, 4)],



            causal_explanation=explanations.get(request.prediction_type, explanations["marginal"]),



            contributing_evidence=contributing,



        ))







    ll = sum(rng.gauss(-1, 0.5) for _ in predictions)







    return _PredictResponse(



        prediction_id=pid,



        model_id=request.model_id,



        predictions=predictions,



        joint_log_likelihood=round(ll, 4),



        causal_graph_snapshot={"nodes": request.target_variables, "edges": len(request.target_variables) - 1},



        timestamp=_time247.time(),



    )











