# v1.248 — Graph Causal Program Verification Engine



# =============================================================================







"""



Graph Causal Program Verification — formally verify causal graph programs



using Hoare-style logic, model checking, type systems, and automated proof



synthesis.  Treats causal models as programs amenable to formal reasoning



about safety, liveness, intervention correctness, and counterfactual validity.



"""







import time as _time248



import random as _rng248



import uuid as _uuid248



from enum import Enum as _Enum248



from typing import Any as _Any248, Dict as _Dict248, List as _List248, Optional as _Opt248







from fastapi import APIRouter as _APIRouter248



from pydantic import BaseModel as _Base248, Field as _Field248







_router248 = APIRouter(prefix="/graph", tags=["v1.248"])











# ---------------------------------------------------------------------------



# Enums



# ---------------------------------------------------------------------------







class VerificationLogic(str, _Enum248):



    hoare_logic = "hoare_logic"



    separation_logic = "separation_logic"



    temporal_logic_ctl = "temporal_logic_ctl"



    temporal_logic_ltl = "temporal_logic_ltl"



    dependent_type = "dependent_type"



    effect_system = "effect_system"











class CausalProgramType(str, _Enum248):



    structural_equation = "structural_equation"



    do_calculus_program = "do_calculus_program"



    counterfactual_program = "counterfactual_program"



    intervention_policy = "intervention_policy"



    causal_dag_program = "causal_dag_program"



    ai_synthesized_causal = "ai_synthesized_causal"











class SafetyProperty(str, _Enum248):



    intervention_safety = "intervention_safety"



    counterfactual_consistency = "counterfactual_consistency"



    causal_monotonicity = "causal_monotonicity"



    no_backdoor_violation = "no_backdoor_violation"



    markov_locality = "markov_locality"



    faithfulness_preservation = "faithfulness_preservation"











class ProofStrategy(str, _Enum248):



    forward_proof = "forward_proof"



    backward_proof = "backward_proof"



    induction_on_graph = "induction_on_graph"



    contradiction = "contradiction"



    coinduction = "coinduction"



    smt_assisted = "smt_assisted"











class VerificationResult(str, _Enum248):



    verified = "verified"



    falsified = "falsified"



    unknown = "unknown"



    conditionally_verified = "conditionally_verified"



    timeout = "timeout"



    error = "error"











class TemporalProperty(str, _Enum248):



    always_safe = "always_safe"



    eventually_stable = "eventually_stable"



    never_violate = "never_violate"



    leads_to = "leads_to"



    until_property = "until_property"



    globally_monotone = "globally_monotone"











# ---------------------------------------------------------------------------



# Request / Response Models



# ---------------------------------------------------------------------------







class _VerifyProgramRequest(_Base248):



    program_id: str = _Field248(..., description="ID of the causal program to verify")



    program_type: CausalProgramType = _Field248(..., description="Type of causal program")



    verification_logic: VerificationLogic = _Field248(..., description="Verification logic framework")



    safety_properties: _List248[SafetyProperty] = _Field248(..., description="Safety properties to verify")



    proof_strategy: ProofStrategy = _Field248(default=ProofStrategy.forward_proof, description="Proof search strategy")



    max_proof_depth: int = _Field248(default=20, ge=1, le=200, description="Maximum proof search depth")



    assumptions: _Opt248[_List248[str]] = _Field248(default=None, description="Additional assumptions for the proof")











class _TypeCheckRequest(_Base248):



    program_id: str = _Field248(..., description="ID of the causal program")



    program_type: CausalProgramType = _Field248(..., description="Program type for type context")



    strict_mode: bool = _Field248(default=True, description="Enable strict type checking (no implicit coercions)")



    check_causal_types: bool = _Field248(default=True, description="Check causal-specific type rules")



    check_intervention_types: bool = _Field248(default=True, description="Type-check intervention expressions")











class _ModelCheckRequest(_Base248):



    program_id: str = _Field248(..., description="ID of the causal program")



    temporal_properties: _List248[TemporalProperty] = _Field248(..., description="Temporal properties to check")



    max_states: int = _Field248(default=10000, ge=100, le=1000000, description="Max state space exploration")



    search_strategy: str = _Field248(default="bfs", description="State space search strategy (bfs/dfs/symbolic)")











class _ProvePropertyRequest(_Base248):



    program_id: str = _Field248(..., description="ID of the causal program")



    property_type: SafetyProperty = _Field248(..., description="Property to prove")



    proof_strategy: ProofStrategy = _Field248(default=ProofStrategy.induction_on_graph)



    generate_witness: bool = _Field248(default=False, description="Generate witness for existential properties")



    lemma_depth: int = _Field248(default=5, ge=1, le=50, description="Max auxiliary lemma depth")











class _SynthesizeProofRequest(_Base248):



    program_id: str = _Field248(..., description="ID of the causal program")



    target_property: SafetyProperty = _Field248(..., description="Target property to synthesize proof for")



    max_proof_steps: int = _Field248(default=30, ge=1, le=200, description="Maximum number of proof steps")



    allowed_tactics: _Opt248[_List248[str]] = _Field248(default=None, description="Restrict proof tactics")











class _CompositionVerifyRequest(_Base248):



    program_ids: _List248[str] = _Field248(..., min_length=2, description="IDs of programs to verify composition")



    composition_type: str = _Field248(default="sequential", description="Composition type (sequential/parallel/conditional)")



    verify_compositional_safety: bool = _Field248(default=True, description="Verify safety is preserved under composition")



    verify_information_flow: bool = _Field248(default=True, description="Verify causal information flow constraints")











class _ProofStep(_Base248):



    step_number: int



    tactic: str



    goal: str



    result: str



    subgoals: _List248[str] = _Field248(default_factory=list)











class _TypeViolation(_Base248):



    location: str



    expected_type: str



    actual_type: str



    severity: str = "error"



    message: str











class _StateTransition(_Base248):



    from_state: str



    to_state: str



    condition: str



    satisfies_property: bool











class _Lemma(_Base248):



    name: str



    statement: str



    proof_sketch: str



    is_proven: bool











class _VerifyProgramResponse(_Base248):



    verification_id: str



    program_id: str



    result: VerificationResult



    properties_verified: _List248[str]



    properties_failed: _List248[str]



    proof_trace: _List248[_ProofStep]



    verification_time_ms: float



    confidence_score: float



