@_router248.post("/causal-verify/verify-program", tags=["v1.248"])



async def verify_program(request: _VerifyProgramRequest) -> _VerifyProgramResponse:



    """Formally verify a causal graph program against safety properties."""



    vid = f"vpf-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(request.program_id + request.verification_logic.value) % (2**31))



    start = _time248.time()







    props_verified: _List248[str] = []



    props_failed: _List248[str] = []



    proof_trace: _List248[_ProofStep] = []







    for prop in request.safety_properties:



        step_count = rng.randint(3, min(12, request.max_proof_depth))



        steps: _List248[_ProofStep] = []



        goal = f"verify({prop.value}) for program {request.program_id}"



        is_ok = rng.random() < 0.78







        for s in range(step_count):



            tactic = rng.choice([



                "apply_intervention_rule", "unfold_causal_mechanism",



                "split_on_variable", "induction_step", "strengthen_invariant",



                "apply_backdoor_criterion", "causal_substitution",



                "simplify_expression", "use_assumption",



            ])



            subgoals = []



            if s < step_count - 1:



                subgoals = [f"subgoal_{s}_{i}" for i in range(rng.randint(0, 2))]



            steps.append(_ProofStep(



                step_number=s + 1,



                tactic=tactic,



                goal=goal if s == 0 else f"subgoal_from_step_{s}",



                result="proceed" if s < step_count - 1 else ("QED" if is_ok else "STUCK"),



                subgoals=subgoals,



            ))







        proof_trace.extend(steps)



        if is_ok:



            props_verified.append(prop.value)



        else:



            props_failed.append(prop.value)







    assumptions_used = request.assumptions or [



        f"assumption_{i}" for i in range(rng.randint(1, 4))



    ]



    elapsed = (_time248.time() - start) * 1000







    overall = VerificationResult.verified if not props_failed else (



        VerificationResult.conditionally_verified if rng.random() < 0.5



        else VerificationResult.falsified



    )



    conf = round(rng.uniform(0.75, 0.99) if not props_failed else rng.uniform(0.3, 0.7), 4)







    return _VerifyProgramResponse(



        verification_id=vid,



        program_id=request.program_id,



        result=overall,



        properties_verified=props_verified,



        properties_failed=props_failed,



        proof_trace=proof_trace,



        verification_time_ms=round(elapsed, 2),



        confidence_score=conf,



        assumptions_used=assumptions_used,



        timestamp=_time248.time(),



    )











@_router248.post("/causal-verify/type-check", tags=["v1.248"])



async def type_check(request: _TypeCheckRequest) -> _TypeCheckResponse:



    """Type-check a causal program for well-formedness and type safety."""



    cid = f"tc-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(request.program_id) % (2**31))







    violations: _List248[_TypeViolation] = []



    n_vars = rng.randint(5, 20)



    type_env: _Dict248[str, str] = {}



    for i in range(n_vars):



        vtype = rng.choice(["CausalReal", "CausalInt", "CausalBool", "Intervention[T]", "Counterfactual[T]", "Latent[T]"])



        type_env[f"var_{i}"] = vtype







    is_well = rng.random() < 0.7



    if not is_well:



        n_violations = rng.randint(1, 4)



        for _ in range(n_violations):



            violations.append(_TypeViolation(



                location=f"line_{rng.randint(1, 30)}:col_{rng.randint(1, 15)}",



                expected_type=rng.choice(["CausalReal", "Intervention[T]", "Counterfactual[T]"]),



                actual_type=rng.choice(["UntreatedObs", "Confounded[T]", "RawObservation"]),



                severity=rng.choice(["error", "warning"]),



                message=rng.choice([



                    "Cannot apply do() to confounded variable without adjustment",



                    "Counterfactual type mismatch: factual and counterfactual branches diverge",



                    "Intervention type requires unconfounded context",



                    "Latent variable used as observed in structural equation",



                    "Implicit coercion from Observational to Interventional loses causal info",



                ]),



            ))







    constraints = [



        f"∀ x, y: CausalReal. x → y ⟹ type(x) ≤ type(y)",



        f"do(T) : Intervention[T] requires unconfounded(T)",



        f"CF(T, obs) : Counterfactual[T] requires factual(obs) : T",



    ]



    if request.check_causal_types:



        constraints.extend([



            f"backdoor_adjustment requires conditioning_set blocks all backdoor paths",



            f"frontdoor_criterion requires mediation through controlled mediator",



        ])







    return _TypeCheckResponse(



        check_id=cid,



        program_id=request.program_id,



        is_well_typed=is_well,



        violations=violations,



        type_environment=type_env,



        causal_type_constraints=constraints,



        inference_count=rng.randint(5, 30),



        timestamp=_time248.time(),



    )











@_router248.post("/causal-verify/model-check", tags=["v1.248"])



async def model_check(request: _ModelCheckRequest) -> _ModelCheckResponse:



    """Model-check a causal program for temporal properties over its state space."""



    mcid = f"mc-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(request.program_id + str(request.temporal_properties)) % (2**31))







    states_explored = rng.randint(min(100, request.max_states), min(request.max_states, 5000))



    n_transitions = rng.randint(10, min(100, states_explored))







    transitions: _List248[_StateTransition] = []



    for _ in range(n_transitions):



        transitions.append(_StateTransition(



            from_state=f"s_{rng.randint(0, states_explored)}",



            to_state=f"s_{rng.randint(0, states_explored)}",



            condition=rng.choice([



                "do(x=v)", "observe(x=v)", "intervene(x,v)", "no_op",



                "counterfactual_swap(x,y)", "backdoor_block(x,z)",



            ]),



            satisfies_property=rng.random() < 0.85,



        ))







    satisfied: _List248[str] = []



    violated: _List248[str] = []



    counterexample = None







    for prop in request.temporal_properties:



        if rng.random() < 0.8:



            satisfied.append(prop.value)



        else:



            violated.append(prop.value)







    if violated:



        counterexample = {



            "violating_property": violated[0],



            "path": [f"s_{rng.randint(0, states_explored)}" for _ in range(rng.randint(3, 8))],



            "final_state": {"variable": f"var_{rng.randint(0, 9)}", "value": round(rng.gauss(0, 1), 4)},



        }







    return _ModelCheckResponse(



        check_id=mcid,



        program_id=request.program_id,



        states_explored=states_explored,



        transitions=transitions[:50],



        satisfied_properties=satisfied,



        violated_properties=violated,



        counterexample=counterexample,



        state_space_size=states_explored,



        timestamp=_time248.time(),



    )











@_router248.post("/causal-verify/prove-property", tags=["v1.248"])



async def prove_property(request: _ProvePropertyRequest) -> _ProvePropertyResponse:



    """Prove a specific safety property of a causal program with proof construction."""



    pid = f"prf-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(request.program_id + request.property_type.value) % (2**31))







    is_proven = rng.random() < 0.75



    steps: _List248[_ProofStep] = []



    n_steps = rng.randint(4, min(request.lemma_depth * 4, 25))







    for s in range(n_steps):



        tactic = rng.choice([



            "causal_induction_base", "causal_induction_step",



            "apply_do_calculus_rule1", "apply_do_calculus_rule2", "apply_do_calculus_rule3",



            "backdoor_identification", "frontdoor_identification",



            "counterfactual_recursion", "structural_decomposition",



            "graph_moralization", "d_separation_invocation",



        ])



        steps.append(_ProofStep(



            step_number=s + 1,



            tactic=tactic,



            goal=f"prove_{request.property_type.value}_step_{s}",



            result="QED" if (s == n_steps - 1 and is_proven) else



                   ("STUCK" if (s == n_steps - 1 and not is_proven) else "proceed"),



            subgoals=[f"lemma_{s}_{j}" for j in range(rng.randint(0, 2))],



        ))







    lemmas: _List248[_Lemma] = []



    for i in range(rng.randint(1, 4)):



        lemmas.append(_Lemma(



            name=f"aux_lemma_{i}",



            statement=f"For all causal variables v in scope, {request.property_type.value} holds under do-intervention",



            proof_sketch=f"By induction on causal graph depth, applying {rng.choice(['backdoor', 'frontdoor', 'd-separation'])} criterion",



            is_proven=rng.random() < 0.9,



        ))







    witness = None



    if request.generate_witness and is_proven:



        witness = {



            "witness_variables": [f"var_{i}" for i in range(rng.randint(2, 5))],



            "witness_values": {f"var_{i}": round(rng.gauss(0, 1), 4) for i in range(rng.randint(2, 5))},



            "satisfying_assignment": True,



        }







    return _ProvePropertyResponse(



        proof_id=pid,



        program_id=request.program_id,



        property_type=request.property_type.value,



        is_proven=is_proven,



        proof_steps=steps,



        auxiliary_lemmas=lemmas,



        proof_size=len(steps) + sum(len(l.proof_sketch) for l in lemmas),



        witness=witness,



        timestamp=_time248.time(),



    )











@_router248.post("/causal-verify/synthesize-proof", tags=["v1.248"])



async def synthesize_proof(request: _SynthesizeProofRequest) -> _SynthesizeProofResponse:



    """Automatically synthesize a formal proof for a target property."""



    sid = f"syn-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(request.program_id + request.target_property.value) % (2**31))







    can_synthesize = rng.random() < 0.65



    n_steps = rng.randint(3, min(request.max_proof_steps, 20))







    steps: _List248[_ProofStep] = []



    tactics_used: _List248[str] = []







    if can_synthesize:



        for s in range(n_steps):



            tactic = rng.choice([



                "intro_hypothesis", "apply_causal_axiom",



                "destruct_intervention", "rewrite_structural_eq",



                "apply_backdoor_rule", "symmetry_lemma",



                "induction_on_depth", "auto_simplify",



            ])



            tactics_used.append(tactic)



            steps.append(_ProofStep(



                step_number=s + 1,



                tactic=tactic,



                goal=f"synthesize_goal_{s}" if s < n_steps - 1 else f"QED: {request.target_property.value}",



                result="proceed" if s < n_steps - 1 else "QED",



                subgoals=[],



            ))







    complexity = round(rng.uniform(1.0, 5.0), 2)







    return _SynthesizeProofResponse(



        synthesis_id=sid,



        program_id=request.program_id,



        target_property=request.target_property.value,



        proof_synthesized=can_synthesize,



        synthesized_proof=steps,



        tactics_used=list(set(tactics_used)),



        proof_length=len(steps),



        proof_complexity=complexity,



        timestamp=_time248.time(),



    )











@_router248.post("/causal-verify/composition", tags=["v1.248"])



async def verify_composition(request: _CompositionVerifyRequest) -> _CompositionVerifyResponse:



    """Verify that composing multiple causal programs preserves safety properties."""



    compid = f"comp-{_uuid248.uuid4().hex[:8]}"



    rng = _rng248.Random(hash(tuple(request.program_ids)) % (2**31))







    is_safe = rng.random() < 0.7



    safety_violations: _List248[str] = []



    if not is_safe:



        safety_violations = [



            rng.choice([



                "Composition breaks intervention isolation between sub-programs",



                "Shared variable causes causal cycle across program boundary",



                "Counterfactual consistency violated under sequential composition",



                "Backdoor path introduced by composition not present in sub-programs",



            ])



            for _ in range(rng.randint(1, 3))



        ]







    flow_valid = rng.random() < 0.8



    flow_violations: _List248[str] = []



    if not flow_valid:



        flow_violations = [



            rng.choice([



                "Information leaks from latent to observed across program interface",



                "Causal influence flows against declared direction between programs",



                "Unobservable variable in P1 influences observable in P2 without declaration",



            ])



            for _ in range(rng.randint(1, 2))



        ]







    guarantees: _List248[str] = []



    if is_safe:



        guarantees = [



            "Compositional safety: each sub-program safety preserved",



            "Interface contract: causal types compatible across boundary",



        ]



        if flow_valid:



            guarantees.append("Information flow: no undeclared causal influence across programs")



        if request.composition_type == "sequential":



            guarantees.append("Sequential composition: output types of P1 match input types of P2")



        elif request.composition_type == "parallel":



            guarantees.append("Parallel composition: no interference between concurrent programs")







    return _CompositionVerifyResponse(



        composition_id=compid,



        programs=request.program_ids,



        composition_type=request.composition_type,



        is_safe=is_safe,



        safety_violations=safety_violations,



        information_flow_valid=flow_valid,



        flow_violations=flow_violations,



        compositional_guarantees=guarantees,



        timestamp=_time248.time(),



    )











