@_router249.post("/auto-causal/discover", tags=["v1.249"])



async def autonomous_discover(request: _DiscoverRequest) -> _DiscoverResponse:



    """Autonomously discover causal graph structure from data."""



    disc_id = f"acd-{_uuid249.uuid4().hex[:12]}"



    n_vars = _rng249.randint(8, min(request.max_variables, 30))



    n_edges = _rng249.randint(n_vars, n_vars * 2)







    variables = [f"V{i}" for i in range(n_vars)]



    edges: _List249[_EdgeInfo] = []



    for _ in range(n_edges):



        s, t = _rng249.sample(variables, 2)



        conf = round(_rng249.uniform(0.4, 0.99), 4)



        etype = _rng249.choice(["directed", "directed", "directed", "undirected", "bidirected"])



        mechanism = _rng249.choice(["linear", "nonlinear", "linear_gaussian", "nonparametric", None])



        edges.append(_EdgeInfo(source=s, target=t, confidence=conf, edge_type=etype, mechanism=mechanism))







    score_val = round(_rng249.uniform(-2000, -100), 4)



    elapsed = round(_rng249.uniform(200, 5000), 2)



    conf_summary = {



        "mean_edge_confidence": round(_rng249.uniform(0.55, 0.92), 4),



        "high_confidence_ratio": round(_rng249.uniform(0.3, 0.8), 4),



        "orientation_certainty": round(_rng249.uniform(0.4, 0.9), 4),



        "skeleton_completeness": round(_rng249.uniform(0.6, 0.98), 4),



    }







    return _DiscoverResponse(



        discovery_id=disc_id,



        dataset_id=request.dataset_id,



        method=request.discovery_method,



        discovered_graph=edges,



        num_variables=n_vars,



        num_edges=len(edges),



        scoring_value=score_val,



        discovery_time_ms=elapsed,



        confidence_summary=conf_summary,



        equiv_class_size=_rng249.randint(1, 24),



    )











@_router249.post("/auto-causal/active-intervene", tags=["v1.249"])



async def active_intervene(request: _ActiveInterveneRequest) -> _ActiveInterveneResponse:



    """Select optimal interventions to actively refine the discovered causal graph."""



    iid = f"intv-{_uuid249.uuid4().hex[:12]}"



    n_interventions = min(request.budget, _rng249.randint(3, 12))



    variables = [f"V{i}" for i in range(_rng249.randint(5, 20))]







    recommended = []



    info_gains = []



    for i in range(n_interventions):



        target_var = _rng249.choice(variables)



        intervention_value = round(_rng249.uniform(-3, 3), 2)



        recommended.append({



            "variable": target_var,



            "intervention_type": _rng249.choice(["do", "soft", "hard", "conditional"]),



            "value": intervention_value,



            "priority": round(_rng249.uniform(0.1, 1.0), 3),



            "expected_edge_resolution": _rng249.randint(1, 5),



            "rationale": f"High uncertainty around {target_var}; intervention expected to resolve {_rng249.randint(1,4)} edge orientations",



        })



        info_gains.append(round(_rng249.uniform(0.01, 0.5), 4))







    n_edges = _rng249.randint(5, 25)



    updated_edges: _List249[_EdgeInfo] = []



    for _ in range(n_edges):



        s, t = _rng249.sample(variables, 2)



        updated_edges.append(_EdgeInfo(



            source=s, target=t,



            confidence=round(_rng249.uniform(0.5, 0.98), 4),



            edge_type=_rng249.choice(["directed", "directed", "undirected"]),



        ))







    return _ActiveInterveneResponse(



        intervention_id=iid,



        discovery_id=request.discovery_id,



        strategy=request.strategy,



        recommended_interventions=recommended,



        expected_information_gain=info_gains,



        graph_reduction_ratio=round(_rng249.uniform(0.1, 0.6), 4),



        budget_remaining=request.budget - n_interventions,



        updated_graph=updated_edges,



    )











@_router249.post("/auto-causal/stability", tags=["v1.249"])



async def evaluate_stability(request: _StabilityRequest) -> _StabilityResponse:



    """Evaluate stability of discovered causal structure using bootstrap and subsample analysis."""



    sid = f"stab-{_uuid249.uuid4().hex[:12]}"



    metrics: _Dict249[str, float] = {}



    for m in request.stability_metrics:



        metrics[m.value] = round(_rng249.uniform(0.5, 0.98), 4)







    variables = [f"V{i}" for i in range(_rng249.randint(5, 15))]



    edge_stability: _Dict249[str, float] = {}



    unstable: _List249[str] = []



    ci_map: _Dict249[str, _List249[float]] = {}







    for i in range(len(variables)):



        for j in range(i + 1, min(i + 3, len(variables))):



            ek = f"{variables[i]}→{variables[j]}"



            stab_val = round(_rng249.uniform(0.3, 0.99), 4)



            edge_stability[ek] = stab_val



            ci_map[ek] = [round(max(0, stab_val - 0.15), 4), round(min(1, stab_val + 0.15), 4)]



            if stab_val < 0.6:



                unstable.append(ek)







    overall = round(sum(metrics.values()) / max(len(metrics), 1), 4)







    return _StabilityResponse(



        stability_id=sid,



        discovery_id=request.discovery_id,



        metrics=metrics,



        edge_stability_map=edge_stability,



        overall_stability=overall,



        unstable_edges=unstable,



        confidence_intervals=ci_map,



    )











@_router249.post("/auto-causal/refine", tags=["v1.249"])



async def refine_graph(request: _RefineRequest) -> _RefineResponse:



    """Iteratively refine a discovered causal graph using the specified mode."""



    rid = f"ref-{_uuid249.uuid4().hex[:12]}"



    orig_edges = _rng249.randint(15, 50)



    refined_count = _rng249.randint(max(5, orig_edges - 10), orig_edges + 5)







    variables = [f"V{i}" for i in range(_rng249.randint(8, 20))]



    changes: _List249[_Dict249[str, _Any249]] = []



    for _ in range(_rng249.randint(2, 8)):



        ct = _rng249.choice(["edge_added", "edge_removed", "edge_reoriented", "confidence_updated", "latent_variable_added"])



        change: _Dict249[str, _Any249] = {



            "type": ct,



            "iteration": _rng249.randint(1, request.iterations),



            "confidence_delta": round(_rng249.uniform(-0.3, 0.4), 4),



        }



        if ct in ("edge_added", "edge_removed", "edge_reoriented"):



            s, t = _rng249.sample(variables, 2)



            change["edge"] = f"{s}→{t}"



        changes.append(change)







    refined_edges: _List249[_EdgeInfo] = []



    for _ in range(refined_count):



        s, t = _rng249.sample(variables, 2)



        refined_edges.append(_EdgeInfo(



            source=s, target=t,



            confidence=round(_rng249.uniform(0.6, 0.99), 4),



            edge_type=_rng249.choice(["directed", "directed", "directed", "undirected"]),



        ))







    return _RefineResponse(



        refinement_id=rid,



        discovery_id=request.discovery_id,



        graph_id=request.graph_id,



        mode=request.mode,



        original_edges=orig_edges,



        refined_edges=refined_count,



        changes=changes,



        improvement_score=round(_rng249.uniform(0.02, 0.35), 4),



        refined_graph=refined_edges,



        iterations_used=min(request.iterations, _rng249.randint(2, request.iterations)),



    )











@_router249.post("/auto-causal/ensemble", tags=["v1.249"])



async def ensemble_discovery(request: _EnsembleRequest) -> _EnsembleResponse:



    """Combine multiple discovery methods into an ensemble for robust causal graph learning."""



    eid = f"ens-{_uuid249.uuid4().hex[:12]}"



    variables = [f"V{i}" for i in range(_rng249.randint(8, 20))]







    individual: _Dict249[str, _List249[_EdgeInfo]] = {}



    for method in request.methods:



        n_e = _rng249.randint(5, len(variables) * 2)



        edges: _List249[_EdgeInfo] = []



        for _ in range(n_e):



            s, t = _rng249.sample(variables, 2)



            edges.append(_EdgeInfo(



                source=s, target=t,



                confidence=round(_rng249.uniform(0.4, 0.95), 4),



                edge_type=_rng249.choice(["directed", "undirected"]),



            ))



        individual[method.value] = edges







    # Build ensemble graph from consensus



    ensemble_edges: _List249[_EdgeInfo] = []



    for _ in range(_rng249.randint(5, len(variables) * 2)):



        s, t = _rng249.sample(variables, 2)



        ensemble_edges.append(_EdgeInfo(



            source=s, target=t,



            confidence=round(_rng249.uniform(0.6, 0.99), 4),



            edge_type="directed",



        ))







    n_consensus = _rng249.randint(3, len(ensemble_edges))



    n_disputed = max(0, len(ensemble_edges) - n_consensus)







    return _EnsembleResponse(



        ensemble_id=eid,



        discovery_id=request.discovery_id,



        individual_graphs=individual,



        ensemble_graph=ensemble_edges,



        method_agreement=round(_rng249.uniform(0.4, 0.85), 4),



        diversity_score=round(_rng249.uniform(0.2, 0.7), 4),



        consensus_edges=n_consensus,



        disputed_edges=n_disputed,



        final_scoring={



            "ensemble_bic": round(_rng249.uniform(-2000, -100), 4),



            "ensemble_aic": round(_rng249.uniform(-1800, -80), 4),



            "stability_index": round(_rng249.uniform(0.6, 0.95), 4),



            "causal_strength": round(_rng249.uniform(0.5, 0.9), 4),



        },



    )











@_router249.post("/auto-causal/validate", tags=["v1.249"])



async def validate_discovery(request: _ValidateDiscoveryRequest) -> _ValidateDiscoveryResponse:



    """Validate a discovered causal graph against criteria or ground truth."""



    vid = f"val-{_uuid249.uuid4().hex[:12]}"







    has_gt = request.ground_truth_id is not None



    precision = round(_rng249.uniform(0.6, 0.95), 4) if has_gt else None



    recall = round(_rng249.uniform(0.55, 0.92), 4) if has_gt else None



    f1 = round(2 * precision * recall / max(precision + recall, 0.01), 4) if has_gt else None



    shd = round(_rng249.uniform(2, 20), 1) if has_gt else None



    markov_eq = _rng249.choice([True, False]) if has_gt else None







    n_violations = _rng249.randint(0, 4)



    violations: _List249[str] = []



    violation_templates = [



        "Cyclic dependency detected in subgraph",



        "Faithfulness assumption violated: conditional independence implies zero effect",



        "Markov blanket inconsistency for variable V{}",



        "Latent confounder suspected between V{} and V{}",



        "Edge orientation conflict: V{}→V{} vs V{}→V{}",



    ]



    for _ in range(n_violations):



        tmpl = _rng249.choice(violation_templates)



        if "{}" in tmpl:



            tmpl = tmpl.format(*[_rng249.randint(0, 15) for _ in range(tmpl.count("{}"))])



        violations.append(tmpl)







    recommendations: _List249[str] = []



    if n_violations > 0:



        recommendations.append("Apply orientation refinement to resolve directional conflicts")



    if precision and precision < 0.8:



        recommendations.append("Increase confidence threshold or apply edge pruning")



    if recall and recall < 0.8:



        recommendations.append("Lower significance level alpha to detect weaker causal links")



    if not recommendations:



        recommendations.append("Discovered graph meets quality criteria — ready for downstream causal inference")







    is_valid = n_violations == 0 and (f1 is None or f1 >= 0.75)







    return _ValidateDiscoveryResponse(



        validation_id=vid,



        discovery_id=request.discovery_id,



        graph_id=request.graph_id,



        is_valid=is_valid,



        structural_hamming_distance=shd,



        precision=precision,



        recall=recall,



        f1_score=f1,



        markov_equivalence=markov_eq,



        violations=violations,



        recommendations=recommendations,



    )











