# v1.250 — Graph Causal Explanation Generation Engine



# =============================================================================



# Converts causal structures and verified causal programs into human-readable



# natural language explanations for causal reasoning interpretability.







# Version-specific type aliases for v1.250



from typing import Any as _Any250



from typing import Dict as _Dict250











class ExplanationStyle(str, Enum):



    """Style of causal explanation generation."""



    narrative = "narrative"



    technical = "technical"



    pedagogical = "pedagogical"



    comparative = "comparative"



    counterfactual = "counterfactual"



    interactive = "interactive"











class CausalDepth(str, Enum):



    """Depth of causal explanation."""



    surface = "surface"



    mechanism = "mechanism"



    pathway = "pathway"



    structural = "structural"



    interventional = "interventional"



    counterfactual = "counterfactual"











class AudienceLevel(str, Enum):



    """Target audience for explanations."""



    layperson = "layperson"



    student = "student"



    analyst = "analyst"



    researcher = "researcher"



    domain_expert = "domain_expert"



    policy_maker = "policy_maker"











class NarrativeMode(str, Enum):



    """Narrative mode for explanation."""



    chronological = "chronological"



    effect_tracing = "effect_tracing"



    pathway = "pathway"



    comparative = "comparative"



    scenario = "scenario"



    interactive = "interactive"











class EvidenceStrength(str, Enum):



    """Strength of evidence for explanation."""



    conclusive = "conclusive"



    strong = "strong"



    moderate = "moderate"



    weak = "weak"



    speculative = "speculative"



    contradictory = "contradictory"











class ExplanationFormat(str, Enum):



    """Output format for explanations."""



    natural_language = "natural_language"



    structured_report = "structured_report"



    visual_description = "visual_description"



    annotated_graph = "annotated_graph"



    interactive_doc = "interactive_doc"



    executive_summary = "executive_summary"











# Pydantic models for v1.250



class ExplanationGenerateRequest(BaseModel):



    """Request to generate causal explanation."""



    explanation_id: str = Field(..., description="Unique explanation identifier")



    causal_structure_id: str = Field(..., description="Input causal structure ID (from v1.249 or v1.248)")



    explanation_style: ExplanationStyle = Field(ExplanationStyle.narrative, description="Style of explanation")



    causal_depth: CausalDepth = Field(CausalDepth.mechanism, description="Depth of causal reasoning")



    audience_level: AudienceLevel = Field(AudienceLevel.analyst, description="Target audience")



    narrative_mode: NarrativeMode = Field(NarrativeMode.effect_tracing, description="Narrative structure")



    explanation_format: ExplanationFormat = Field(ExplanationFormat.natural_language, description="Output format")



    include_visualizations: bool = Field(True, description="Include visualization descriptions")



    include_counterfactuals: bool = Field(True, description="Generate counterfactual scenarios")



    language: str = Field("en", description="Output language (en, zh, es, fr)")











class ExplanationGenerateResponse(BaseModel):



    """Response from causal explanation generation."""



    explanation_id: str



    causal_structure_id: str



    style: str



    depth: str



    audience: str



    explanation_text: str



    explanation_metadata: _Dict250[str, _Any250]



    causality_summary: _Dict250[str, str]



    counterfactual_scenarios: list[_Dict250[str, str]]



    readability_score: float



    completeness_score: float



    generated_at: str











class ExplanationChainRequest(BaseModel):



    """Request to build explanation chain."""



    chain_id: str = Field(..., description="Chain identifier")



    base_explanation_id: str = Field(..., description="Base explanation ID")



    chain_direction: str = Field("forward", description="forward (deeper) or backward (simpler)")



    chain_depth: int = Field(3, ge=1, le=10, description="Number of explanation layers")



    audience_progression: list[AudienceLevel] = Field(default_factory=lambda: [AudienceLevel.layperson, AudienceLevel.analyst, AudienceLevel.researcher], description="Audience levels across chain")



    transition_style: str = Field("gradual", description="gradual or abrupt transitions")











class ExplanationChainResponse(BaseModel):



    """Response from explanation chain building."""



    chain_id: str



    base_explanation_id: str



    chain_layers: list[_Dict250[str, _Any250]]



    transition_analysis: _Dict250[str, str]



    complexity_gradient: list[float]



    coherence_score: float



    chain_metadata: _Dict250[str, _Any250]











class ExplanationContrastRequest(BaseModel):



    """Request for contrastive explanation."""



    contrast_id: str = Field(..., description="Contrast identifier")



    explanation_id_a: str = Field(..., description="First explanation ID")



    explanation_id_b: str = Field(..., description="Second explanation ID")



    contrast_dimensions: list[str] = Field(default_factory=list, description="Dimensions to contrast")



    highlight_differences: bool = Field(True, description="Highlight key differences")



    compare_confidence: bool = Field(True, description="Compare evidence confidence")



    suggest_synthesis: bool = Field(True, description="Suggest synthesis")











class ExplanationContrastResponse(BaseModel):



    """Response from contrastive explanation."""



    contrast_id: str



    explanation_a_summary: str



    explanation_b_summary: str



    differences: list[_Dict250[str, str]]



    similarities: list[str]



    confidence_comparison: _Dict250[str, float]



    synthesis_suggestion: str



