class ExplanationValidateResponse(BaseModel):



    """Response from explanation validation."""



    validation_id: str



    explanation_id: str



    is_valid: bool



    validation_summary: str



    accuracy_score: float



    clarity_score: float



    completeness_score: float



    domain_correctness: float



    audience_comprehension: float



    validation_details: _Dict250[str, _Any250]



