# =============================================================================



# v1.251 — Graph Causal Argumentation Engine



# =============================================================================



# Structured argumentation-based causal debate and reasoning engine.



# Bridges causal explanations (v1.250) with formal argumentation theory,



# enabling challenge, defense, and synthesis of causal claims.







# Version-specific type aliases for v1.251



from typing import Any as _Any251



from typing import Dict as _Dict251











class ArgumentType(str, Enum):



    """Type of argument component in causal argumentation."""



    premise = "premise"



    conclusion = "conclusion"



    rebuttal = "rebuttal"



    support = "support"



    attack = "attack"



    concession = "concession"











class ArgumentationFramework(str, Enum):



    """Argumentation framework for evaluating causal arguments."""



    abstract_argumentation = "abstract_argumentation"



    aspic_plus = "aspic_plus"



    structured_debate = "structured_debate"



    dialectical_analysis = "dialectical_analysis"



    bipartite_argumentation = "bipartite_argumentation"



    causal_focused = "causal_focused"











class ArgumentStrength(str, Enum):



    """Strength status of a causal argument."""



    refuted = "refuted"



    defeated = "defeated"



    acceptable = "acceptable"



    defended = "defended"



    preferred = "preferred"



    warranted = "warranted"











class DebateMode(str, Enum):



    """Mode of causal debate interaction."""



    adversarial = "adversarial"



    collaborative = "collaborative"



    constructive = "constructive"



    dialectical = "dialectical"



    synthesis_focused = "synthesis_focused"



    consensus_building = "consensus_building"











class EvaluationMethod(str, Enum):



    """Method for evaluating argument acceptability."""



    grounded_extension = "grounded_extension"



    preferred_extension = "preferred_extension"



    stable_extension = "stable_extension"



    semi_stable = "semi_stable"



    complete_extension = "complete_extension"



    ideal_extension = "ideal_extension"











class ArgumentRelation(str, Enum):



    """Relation type between two arguments."""



    attacks = "attacks"



    supports = "supports"



    defeats = "defeats"



    undermines = "undermines"



    rebuts = "rebuts"



    concedes = "concedes"











# Pydantic models for v1.251



class ArgumentConstructRequest(BaseModel):



    """Request to construct a causal argument."""



    argument_id: str = Field(..., description="Unique argument identifier")



    causal_claim: str = Field(..., description="The causal claim to argue about")



    argument_type: ArgumentType = Field(ArgumentType.conclusion, description="Type of argument component")



    framework: ArgumentationFramework = Field(ArgumentationFramework.structured_debate, description="Argumentation framework")



    premise_ids: list[str] = Field(default_factory=list, description="Supporting premise IDs")



    evidence_ids: list[str] = Field(default_factory=list, description="Evidence source IDs from v1.250")



    confidence: float = Field(0.8, ge=0, le=1, description="Initial confidence in claim")



    domain: str = Field("general", description="Knowledge domain")











class ArgumentConstructResponse(BaseModel):



    """Response from causal argument construction."""



    argument_id: str



    causal_claim: str



    argument_type: str



    framework: str



    premises: list[_Dict251[str, _Any251]]



    evidence_links: list[_Dict251[str, str]]



    initial_strength: ArgumentStrength



    attack_surface: list[str]



    defense_points: list[str]



    construction_metadata: _Dict251[str, _Any251]











class DebateSessionRequest(BaseModel):



    """Request to create a causal debate session."""



    session_id: str = Field(..., description="Debate session identifier")



    claim_ids: list[str] = Field(..., description="Causal claim IDs to debate")



    debate_mode: DebateMode = Field(DebateMode.dialectical, description="Debate interaction mode")



    participants: list[str] = Field(default_factory=lambda: ["proponent", "opponent", "judge"], description="Debate participant roles")



    max_rounds: int = Field(5, ge=1, le=20, description="Maximum debate rounds")



    evaluation_method: EvaluationMethod = Field(EvaluationMethod.grounded_extension, description="Acceptability evaluation method")



    focus_dimensions: list[str] = Field(default_factory=lambda: ["causal_mechanism", "evidence_strength", "confounders"], description="Dimensions to focus debate on")











class DebateSessionResponse(BaseModel):



    """Response from causal debate session."""



    session_id: str



    debate_rounds: list[_Dict251[str, _Any251]]



    argument_graph: _Dict251[str, _Any251]



    extension_analysis: _Dict251[str, _Any251]



    winner: str



    consensus_points: list[str]



    unresolved_points: list[str]



    debate_summary: str



    session_metadata: _Dict251[str, _Any251]











class RebuttalGenerateRequest(BaseModel):



    """Request to generate causal rebuttals."""



    rebuttal_id: str = Field(..., description="Rebuttal identifier")



    target_argument_id: str = Field(..., description="Argument to rebut")



    relation_type: ArgumentRelation = Field(ArgumentRelation.attacks, description="Relation to target")



    rebuttal_strategy: str = Field("evidence_based", description="counter_evidence, alternative_mechanism, confounder_highlight, scope_challenge, methodology_critique")



    strength_threshold: float = Field(0.5, ge=0, le=1, description="Minimum rebuttal strength")



    generate_counter_rebuttals: bool = Field(True, description="Generate responses to rebuttal")











class RebuttalGenerateResponse(BaseModel):



    """Response from rebuttal generation."""



    rebuttal_id: str



    target_argument_id: str



    relation_type: str



    rebuttal_claims: list[_Dict251[str, _Any251]]



    supporting_evidence: list[_Dict251[str, str]]



    counter_rebuttals: list[_Dict251[str, _Any251]]



    rebuttal_strength: float



    effectiveness_score: float



    vulnerability_points: list[str]



    rebuttal_metadata: _Dict251[str, _Any251]











class ArgumentEvaluateRequest(BaseModel):



    """Request to evaluate argument acceptability."""



    evaluation_id: str = Field(..., description="Evaluation identifier")



    argument_ids: list[str] = Field(..., description="Arguments to evaluate")



    evaluation_method: EvaluationMethod = Field(EvaluationMethod.preferred_extension, description="Evaluation method")



    include_attack_graph: bool = Field(True, description="Include attack relation graph")



    include_defense_graph: bool = Field(True, description="Include defense relation graph")



    strength_calibration: bool = Field(True, description="Calibrate strength scores")











class ArgumentEvaluateResponse(BaseModel):



    """Response from argument evaluation."""



    evaluation_id: str



    evaluated_arguments: list[_Dict251[str, _Any251]]



    extensions: list[list[str]]



    attack_graph: _Dict251[str, list[str]]



    defense_graph: _Dict251[str, list[str]]



    grounded: list[str]



    preferred: list[str]



    strength_calibration: _Dict251[str, float]



    ranking: list[_Dict251[str, _Any251]]



    evaluation_metadata: _Dict251[str, _Any251]











class ConsensusSynthesisRequest(BaseModel):



    """Request to synthesize consensus from arguments."""



    synthesis_id: str = Field(..., description="Synthesis identifier")



    argument_set_ids: list[str] = Field(..., description="Sets of arguments to synthesize")



    debate_session_id: str = Field("", description="Optional debate session for context")



    resolution_strategy: str = Field("weighted_merge", description="weighted_merge, majority_vote, strongest_argument, dialectical_synthesis")



    preserve_minority_views: bool = Field(True, description="Include minority viewpoints")



    generate_explanation: bool = Field(True, description="Generate explanation for consensus")











class ConsensusSynthesisResponse(BaseModel):



    """Response from consensus synthesis."""



    synthesis_id: str



    consensus_claims: list[_Dict251[str, _Any251]]



    dissenting_views: list[_Dict251[str, _Any251]]



    confidence_distribution: _Dict251[str, float]



    agreement_matrix: list[list[float]]



    synthesis_explanation: str



