class PlanResponse(BaseModel):



    plan_id: str



    causal_graph_id: str



    goal: str



    intervention_type: str



    planning_horizon: str



    intervention_steps: List[Dict[str, Any]]



    estimated_effects: Dict[str, Any]



    constraint_satisfaction: Dict[str, Any]



    risk_assessment: Dict[str, Any]



