    ASSOCIATIVE_RECALL = "associative_recall"



    TEMPORAL_SCAN = "temporal_scan"



    CAUSAL_TRACE = "causal_trace"



    PATTERN_COMPLETION = "pattern_completion"



    RECONSTRUCTIVE_RETRIEVAL = "reconstructive_retrieval"



