    NEUTRAL_DRIFT = "neutral"  # 中性漂移 - 随机无方向的变异
    DIRECTED_ADAPTATION = "directed"  # 定向适应 - 环境驱动的定向变化
    PUNCTUATED_EQUILIBRIUM = "punctuated"  # 间断平衡 - 突变与稳定交替
